#[derive(Debug, Clone)]
pub struct BuiltinExtensionError {
    pub loc: LocIdx,
    pub message: String,
    pub sub: Vec<BuiltinExtensionError>,
}

fn extension_eval_string(
    arena: &ParseArena,
    item: &crate::parser::ast::StructureItem,
) -> Option<String> {
    let crate::parser::ast::StructureItemDesc::Pstr_eval(eval) = &item.pstr_desc else {
        return None;
    };
    let expr = arena.get_expanded_expr(eval.0);
    let crate::parser::ast::ExpressionDesc::Pexp_constant(constant) = &expr.pexp_desc else {
        return None;
    };
    let ParsedConstant::String(message) = constant else {
        return None;
    };
    Some(message.semantic(arena).to_string())
}

fn builtin_extension_sub_errors(
    arena: &ParseArena,
    name: &str,
    loc: LocIdx,
    items: &[crate::parser::ast::StructureItem],
) -> Option<Vec<BuiltinExtensionError>> {
    let mut sub = Vec::new();
    for item in items {
        match &item.pstr_desc {
            crate::parser::ast::StructureItemDesc::Pstr_extension(extension) => {
                sub.push(extension_error(arena, &extension.0)?);
            }
            _ => sub.push(BuiltinExtensionError {
                loc,
                message: format!("Invalid syntax for sub-error of extension '{name}'."),
                sub: Vec::new(),
            }),
        }
    }
    Some(sub)
}

fn extension_error(
    arena: &ParseArena,
    extension: &crate::parser::ast::Extension,
) -> Option<BuiltinExtensionError> {
    let name = arena.get_string(extension.0.txt);
    if name == "error" {
        return match &extension.1 {
            crate::parser::ast::Payload::PStr(items) => {
                let item = items.first()?;
                let Some(message) = extension_eval_string(arena, item) else {
                    return Some(BuiltinExtensionError {
                        loc: extension.0.loc,
                        message: format!("Invalid syntax for extension '{name}'."),
                        sub: Vec::new(),
                    });
                };
                let inner = match items
                    .get(1)
                    .and_then(|item| extension_eval_string(arena, item))
                {
                    Some(_) => &items[2..],
                    None => &items[1..],
                };
                let sub = builtin_extension_sub_errors(arena, name, extension.0.loc, inner)?;
                Some(BuiltinExtensionError {
                    loc: extension.0.loc,
                    message,
                    sub,
                })
            }
            _ => Some(BuiltinExtensionError {
                loc: extension.0.loc,
                message: format!("Invalid syntax for extension '{name}'."),
                sub: Vec::new(),
            }),
        };
    }
    Some(BuiltinExtensionError {
        loc: extension.0.loc,
        message: format!("Uninterpreted extension '{name}'."),
        sub: Vec::new(),
    })
}

/// OCaml `Ast_raw.uninterpreted`: raw JavaScript that reached the type
/// checker, which the built-in PPX lowers before type checking.
pub fn uninterpreted_raw_error(name_loc: LocIdx, name: &str) -> TypeCoreError {
    TypeCoreError::ExtensionError(BuiltinExtensionError {
        loc: name_loc,
        message: format!("Uninterpreted extension '{name}'."),
        sub: Vec::new(),
    })
}

pub fn builtin_extension_error(
    arena: &ParseArena,
    extension: &crate::parser::ast::Extension,
) -> TypeCoreError {
    match extension_error(arena, extension) {
        Some(error) => TypeCoreError::ExtensionError(error),
        None => TypeCoreError::ExtensionAlreadyDisplayed,
    }
}

fn ocaml_hashtbl_power_2_above(mut x: usize, n: usize) -> usize {
    while x < n {
        if x > (isize::MAX as usize / 2) {
            break;
        }
        x *= 2;
    }
    x
}

fn ocaml_hash_mix_uint32(mut h: u32, mut d: u32) -> u32 {
    d = d.wrapping_mul(0xcc9e2d51);
    d = d.rotate_left(15);
    d = d.wrapping_mul(0x1b873593);
    h ^= d;
    h = h.rotate_left(13);
    h.wrapping_mul(5).wrapping_add(0xe6546b64)
}

fn ocaml_hash_final_mix(mut h: u32) -> u32 {
    h ^= h >> 16;
    h = h.wrapping_mul(0x85ebca6b);
    h ^= h >> 13;
    h = h.wrapping_mul(0xc2b2ae35);
    h ^= h >> 16;
    h
}

fn generalizable_at_level(ctx: &TypeContext, level: i32, ty: TypeExprRef) -> bool {
    fn check(ctx: &TypeContext, level: i32, ty: TypeExprRef,
        visited: &mut crate::types::type_marks::TypeNodeTable<()>) -> bool {
        let ty = ctx.repr(ty);
        let ty_level = ctx.get_level(ty);
        if ty_level < crate::types::type_expr::LOWEST_LEVEL || !visited.visit(ty) {
            return true;
        }
        if ty_level <= level {
            return false;
        }
        let mut children = Vec::new();
        crate::types::iter_type_expr(ctx, ty, |child| children.push(child));
        children.into_iter().all(|child| check(ctx, level, child, visited))
    }

    // compiler/ml/typecore.ml:2104-2120: visit each node once without
    // changing the levels of the graph being checked.
    check(ctx, level, ty, &mut crate::types::type_marks::visit_set())
}

fn ocaml_hashtbl_hash_string(s: &str) -> u32 {
    let bytes = s.as_bytes();
    let len = bytes.len();
    let mut h = 0u32;
    let mut i = 0usize;

    while i + 4 <= len {
        let w = u32::from_le_bytes([bytes[i], bytes[i + 1], bytes[i + 2], bytes[i + 3]]);
        h = ocaml_hash_mix_uint32(h, w);
        i += 4;
    }

    let rem = len & 3;
    if rem != 0 {
        let mut w = 0u32;
        if rem >= 3 {
            w |= (bytes[i + 2] as u32) << 16;
        }
        if rem >= 2 {
            w |= (bytes[i + 1] as u32) << 8;
        }
        w |= bytes[i] as u32;
        h = ocaml_hash_mix_uint32(h, w);
    }

    h ^= len as u32;
    ocaml_hash_final_mix(h) & 0x3fff_ffff
}

/// Match OCaml `Hashtbl.create 17` + `Hashtbl.fold` traversal order.
fn ocaml_hashtbl_fold_order<S: AsRef<str> + Clone>(labels: &[S]) -> Vec<S> {
    let mut buckets: Vec<Vec<usize>> = vec![Vec::new(); ocaml_hashtbl_power_2_above(16, 17)];
    let mut size = 0usize;

    for (entry_idx, label) in labels.iter().enumerate() {
        let bucket_idx = (ocaml_hashtbl_hash_string(label.as_ref()) as usize) & (buckets.len() - 1);
        buckets[bucket_idx].insert(0, entry_idx);
        size += 1;

        if size > (buckets.len() << 1) {
            let mut new_buckets = vec![Vec::new(); buckets.len() * 2];
            for bucket in &buckets {
                for &idx in bucket {
                    let new_idx = (ocaml_hashtbl_hash_string(labels[idx].as_ref()) as usize)
                        & (new_buckets.len() - 1);
                    new_buckets[new_idx].push(idx);
                }
            }
            buckets = new_buckets;
        }
    }

    let mut ordered = Vec::with_capacity(labels.len());
    for bucket in &buckets {
        for &idx in bucket {
            ordered.push(labels[idx].clone());
        }
    }
    ordered
}

/// Match OCaml `Hashtbl.replace` + `Hashtbl.fold` behavior for string keys.
fn ocaml_hashtbl_replace_fold_order(entries: &[String]) -> Vec<String> {
    let mut buckets: Vec<Vec<usize>> = vec![Vec::new(); ocaml_hashtbl_power_2_above(16, 17)];
    let mut size = 0usize;

    for (entry_idx, entry) in entries.iter().enumerate() {
        let bucket_idx = (ocaml_hashtbl_hash_string(entry) as usize) & (buckets.len() - 1);
        if let Some(existing_pos) = buckets[bucket_idx]
            .iter()
            .position(|&idx| entries[idx] == *entry)
        {
            buckets[bucket_idx].remove(existing_pos);
            size -= 1;
        }
        buckets[bucket_idx].insert(0, entry_idx);
        size += 1;

        if size > (buckets.len() << 1) {
            let mut new_buckets = vec![Vec::new(); buckets.len() * 2];
            for bucket in &buckets {
                for &idx in bucket {
                    let new_idx = (ocaml_hashtbl_hash_string(&entries[idx]) as usize)
                        & (new_buckets.len() - 1);
                    new_buckets[new_idx].insert(0, idx);
                }
            }
            buckets = new_buckets;
        }
    }

    let mut ordered = Vec::with_capacity(size);
    for bucket in &buckets {
        for &idx in bucket {
            ordered.push(entries[idx].clone());
        }
    }
    ordered
}

