/// Convert a LocIdx to a Location using the arena.
fn convert_loc(loc: LocIdx, arena: &ParseArena) -> Location {
    arena.to_location(loc)
}

/// Convert a Located<StrIdx> to a Located<String> (for typedtree which uses String).
fn convert_located_stridx(loc: &Located<StrIdx>, arena: &ParseArena) -> Located<String> {
    Located {
        txt: arena.get_string(loc.txt).to_string(),
        loc: loc.loc,
    }
}

fn has_warn_on_literal_pattern_attribute(attrs: &[crate::types::decl::Attribute]) -> bool {
    attrs
        .iter()
        .any(|attr| matches!(attr.attr_name.txt.as_str(), "warn_on_literal_pattern"))
}

fn is_dict_type_path(path: &Path) -> bool {
    // Must match the predef dict type exactly.
    // OCaml uses `Path.same tpath Predef.path_dict` which compares stamps.
    path.same(&crate::types::predef::path_dict())
}

/// `check_no_record_syntax_on_dict` (typecore.ml): record syntax on a dict,
/// e.g. `let d: dict<int> = {foo: 1}`, points to `dict{...}`. `first_lid` is
/// the label of the first field.
fn check_no_record_syntax_on_dict(
    tctx: &TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    ty: TypeExprRef,
    first_lid: Option<LidentIdx>,
) -> TypeCoreResult<()> {
    // typecore.ml:1003-1008 matches `((expand_head env ty).desc, fields)`, so
    // the type is expanded (and its path normalized, which can force a
    // persistent signature) even for an empty field list.
    let is_dict = expands_to_dict(tctx.type_ctx, env, ty);
    match first_lid {
        Some(lid) if is_dict => {
            let key = tctx
                .arena
                .get_string(tctx.arena.get_longident(lid).last_idx());
            Err(TypeCoreError::RecordSyntaxOnDictType {
                loc,
                key: key.to_string(),
            })
        }
        _ => Ok(()),
    }
}

/// `Parmatch.is_dict_pattern`: a lowered dict pattern, a record pattern of the
/// `dict` type.
fn typed_pattern_is_dict(ctx: &TypeContext, pat: &Pattern) -> bool {
    matches!(pat.pat_desc, PatternDesc::Tpat_record(..))
        && ctx
            .get_typed_env(pat.pat_env)
            .is_some_and(|env| expands_to_dict(ctx, &env, pat.pat_type))
}

/// `(expand_head env ty).desc` is `Tconstr (path, _, _)` with
/// `Path.same path Predef.path_dict`.
fn expands_to_dict(ctx: &TypeContext, env: &Env, ty: TypeExprRef) -> bool {
    let expanded = crate::types::ctype::expand_head(ctx, env, ty);
    matches!(&*ctx.get_desc(expanded), TypeDesc::Tconstr { path, .. } if is_dict_type_path(path))
}

/// Match OCaml polymorphic compare over `Longident.t`:
/// constructor order `Lident < Ldot < Lapply`, then recursive field compare.
fn compare_longident(arena: &ParseArena, left: &Longident, right: &Longident) -> Ordering {
    match (left, right) {
        (Longident::Lident(left_name), Longident::Lident(right_name)) => arena
            .get_string(*left_name)
            .cmp(arena.get_string(*right_name)),
        (Longident::Lident(_), _) => Ordering::Less,
        (_, Longident::Lident(_)) => Ordering::Greater,
        (Longident::Ldot(left_prefix, left_name), Longident::Ldot(right_prefix, right_name)) => {
            let prefix_cmp = compare_longident(arena, left_prefix, right_prefix);
            if prefix_cmp != Ordering::Equal {
                prefix_cmp
            } else {
                arena
                    .get_string(*left_name)
                    .cmp(arena.get_string(*right_name))
            }
        }
        (Longident::Ldot(_, _), _) => Ordering::Less,
        (_, Longident::Ldot(_, _)) => Ordering::Greater,
        (
            Longident::Lapply(left_functor, left_arg),
            Longident::Lapply(right_functor, right_arg),
        ) => {
            let functor_cmp = compare_longident(arena, left_functor, right_functor);
            if functor_cmp != Ordering::Equal {
                functor_cmp
            } else {
                compare_longident(arena, left_arg, right_arg)
            }
        }
    }
}

/// OCaml `Datarepr.constructor_args`' `type_params` of an inline record
/// (datarepr.ml:73-75).
pub(crate) fn inline_record_type_params(
    ctx: &TypeContext,
    labels: &[crate::types::LabelDeclaration],
) -> Vec<TypeExprRef> {
    // datarepr.ml:73-75: `free_vars ~param:true` of the fields' types, not
    // the parent declaration's parameters: a GADT constructor's fields
    // mention its own variables, existentials included.
    let field_types: Vec<TypeExprRef> = labels.iter().map(|label| label.ld_type).collect();
    crate::types::env::free_vars_param(ctx, &field_types)
}

// ============================================================================
// Error Types
// ============================================================================

/// Errors that can occur during type checking.
#[derive(Debug, Clone)]
pub enum TypeCoreError {
    /// Internal sentinel matching OCaml Typecore.Need_backtrack.
    NeedBacktrack,

    /// Polymorphic label in pattern.
    PolymorphicLabel { loc: LocIdx, lid: Longident },

    /// Constructor arity mismatch.
    ConstructorArityMismatch {
        loc: LocIdx,
        name: Longident,
        is_inline_record: bool,
        expected: usize,
        provided: usize,
    },

    /// Label mismatch in record pattern.
    LabelMismatch {
        loc: LocIdx,
        lid: Longident,
        trace: Vec<(TypeExprRef, TypeExprRef)>,
        /// The environment of the failed unification (OCaml's `Error` env,
        /// typecore.ml:4279-4281).
        env: Option<EnvRef>,
    },

    /// Pattern type clash.
    PatternTypeClash {
        loc: Option<LocIdx>,
        trace: Vec<(TypeExprRef, TypeExprRef)>,
        /// The environment of the failed unification (OCaml's `Error` env).
        env: Option<EnvRef>,
    },

    /// Or-pattern type clash.
    OrPatternTypeClash {
        loc: LocIdx,
        id: Ident,
        trace: Vec<(TypeExprRef, TypeExprRef)>,
        /// The environment of the failed unification (OCaml's `Error` env).
        env: Option<EnvRef>,
    },

    /// Variable bound multiple times.
    MultiplyBoundVariable { loc: LocIdx, name: String },

    /// A value identifier rejected by `Env.check_value_name`.
    IllegalValueName { loc: LocIdx, name: String },

    /// Variables don't match in or-pattern.
    OrpatVars {
        loc: LocIdx,
        id: Ident,
        valid_idents: Vec<Ident>,
    },

    /// Expression type clash.
    ExprTypeClash {
        loc: LocIdx,
        trace: Vec<(TypeExprRef, TypeExprRef)>,
        context: Option<TypeClashContext>,
        /// The environment of the failed unification (OCaml's `Error` env).
        env: Option<EnvRef>,
    },

    /// Subtype check failed during an explicit coercion.
    NotSubtype {
        loc: LocIdx,
        trace: Vec<(TypeExprRef, TypeExprRef)>,
        /// The failed constraint's unification trace (OCaml's `tr2`).
        trace2: Vec<(TypeExprRef, TypeExprRef)>,
        context: Option<crate::types::SubtypeContext>,
        /// The environment of the error (OCaml's `Error` env).
        env: Option<EnvRef>,
    },

    /// Applying non-function.
    ApplyNonFunction { loc: LocIdx, typ: TypeExprRef },

    /// A labeled argument was used where frontend operator syntax forbids it.
    MisplacedLabelSyntax { loc: LocIdx },

    /// Backtick tagged-template syntax used with a non-tag value.
    TaggedTemplateNonTag { loc: LocIdx, typ: TypeExprRef },
    /// typecore.ml `Jsx_unboxed_props`: the props of a JSX element have an
    /// `@unboxed` record type.
    JsxUnboxedProps { loc: LocIdx, typ: TypeExprRef },

    /// Wrong label in application.
    ApplyWrongLabel {
        loc: LocIdx,
        label: ArgLabel,
        ty: TypeExprRef,
    },

    /// Label defined multiple times.
    LabelMultiplyDefined {
        /// Location of the duplicate label.
        loc: LocIdx,
        label: String,
        jsx_component_info: Option<JsxPropErrorInfo>,
    },

    /// Missing labels in record.
    LabelsMissing {
        /// Location of the record literal.
        loc: LocIdx,
        labels: Vec<String>,
        jsx_component_info: Option<JsxPropErrorInfo>,
    },

    /// Attempting to mutate immutable field.
    LabelNotMutable { loc: LocIdx, lid: Longident },

    /// Wrong name in expression.
    WrongName {
        /// Location of the wrong name.
        loc: LocIdx,
        kind: &'static str,
        ty: TypeExprRef,
        expected: &'static str,
        path: Path,
        name: String,
        alternatives: Vec<String>,
        jsx_component_info: Option<Box<JsxPropErrorInfo>>,
        /// The environment of the error (OCaml's `Error` env), used as the
        /// printing environment.
        env: Option<EnvRef>,
    },

    /// Name/type mismatch.
    NameTypeMismatch {
        loc: LocIdx,
        kind: String,
        lid: Longident,
        expected: (Path, Path),
        alternatives: Vec<(Path, Path)>,
    },

    /// Undefined method.
    UndefinedMethod {
        loc: Option<LocIdx>,
        ty: TypeExprRef,
        method: String,
        alternatives: Option<Vec<String>>,
    },

    /// typecore.ml `Object_field_not_mutable`.
    ObjectFieldNotMutable {
        loc: LocIdx,
        ty: TypeExprRef,
        name: String,
    },

    /// Unbound value identifier.
    UnboundValue {
        loc: LocIdx,
        name: String,
        qualifier: Option<String>,
        alternatives: Vec<String>,
        module_suggestion: Option<String>,
    },

    /// Unbound module identifier.
    UnboundModule {
        loc: LocIdx,
        name: String,
        alternatives: Vec<String>,
    },

    /// Unbound module-type identifier.
    UnboundModtype {
        loc: LocIdx,
        lid: Longident,
        alternatives: Vec<String>,
    },

    /// A functor was used as if it were a structure.
    AccessFunctorAsStructure { loc: LocIdx, lid: Longident },

    /// A module path is an alias to a missing module.
    CannotScrapeAlias {
        loc: LocIdx,
        lid: Longident,
        path: Path,
    },

    /// A recursive module references one of the modules being approximated.
    IllegalReferenceToRecursiveModule { loc: LocIdx },

    /// Unbound constructor identifier.
    UnboundConstructor {
        loc: LocIdx,
        lid: Longident,
        alternatives: Vec<String>,
    },

    /// Unbound type constructor identifier.
    UnboundTypeConstructor {
        loc: LocIdx,
        lid: Longident,
        alternatives: Vec<String>,
    },

    /// Type constructor exists but is not completely defined yet.
    UnboundTypeConstructorIncomplete { loc: LocIdx, path: Path },

    /// Unbound type variable.
    UnboundTypeVariable { loc: LocIdx, name: String },

    /// Invalid type variable name.
    InvalidVariableName { loc: LocIdx, name: String },

    /// A Ptyp_poly universal variable could not be generalized.
    CannotQuantify {
        loc: LocIdx,
        name: String,
        ty: TypeExprRef,
    },

    /// Multiple constraints on the same package type.
    MultipleConstraintsOnType { loc: LocIdx, lid: Longident },

    /// A package type with constraints references a module type that is not a signature.
    SignatureExpected { loc: LocIdx },

    /// A present polymorphic variant constructor has a conjunctive type.
    PresentHasConjunction { loc: LocIdx, label: String },

    /// A present polymorphic variant constructor has no row field.
    PresentHasNoType { loc: LocIdx, label: String },

    /// A polymorphic variant constructor is duplicated with an incompatible type.
    ConstructorMismatch {
        loc: LocIdx,
        actual: TypeExprRef,
        expected: TypeExprRef,
    },

    /// A polymorphic variant inherits a type that is not a polymorphic variant.
    NotAVariant { loc: LocIdx, ty: TypeExprRef },

    /// An object type contains the same method with incompatible types.
    MethodMismatch {
        loc: LocIdx,
        label: String,
        actual: TypeExprRef,
        expected: TypeExprRef,
    },

    /// Type constructor argument does not satisfy its declared parameter constraint.
    TypeMismatch {
        loc: LocIdx,
        trace: Vec<(TypeExprRef, TypeExprRef)>,
    },

    /// Type alias reuse is incompatible with its earlier binding.
    AliasTypeMismatch {
        loc: LocIdx,
        trace: Vec<(TypeExprRef, TypeExprRef)>,
    },

    /// Type constructor arity mismatch.
    TypeArityMismatch {
        loc: LocIdx,
        lid: Longident,
        expected: usize,
        provided: usize,
    },

    /// Private type.
    PrivateType { loc: LocIdx, ty: TypeExprRef },

    /// Invalid record-rest pattern.
    RecordRest { loc: LocIdx, error: RecordRestError },

    /// Abstract wrong label.
    AbstractWrongLabel {
        loc: Location,
        label: crate::types::ArgLabel,
        ty: TypeExprRef,
    },

    /// Scoping let module.
    ScopingLetModule(String, TypeExprRef),

    /// Not a variant type.
    NotAVariantType { loc: LocIdx, lid: Longident },

    /// Incoherent label order.
    IncoherentLabelOrder { loc: LocIdx },

    /// Less general type.
    LessGeneral {
        loc: LocIdx,
        kind: String,
        trace: Vec<(TypeExprRef, TypeExprRef)>,
        /// The environment of the check (OCaml's `Error` env).
        env: Option<EnvRef>,
    },

    /// Modules not allowed.
    ModulesNotAllowed { loc: LocIdx },

    /// Cannot infer signature.
    CannotInferSignature { loc: LocIdx },

    /// Not a packed module.
    NotAPackedModule { loc: LocIdx, ty: TypeExprRef },

    /// A module expression was applied but its module type is not a functor.
    CannotApplyModule {
        loc: LocIdx,
        mty: crate::types::decl::ModuleType,
        origin: Option<Path>,
    },

    /// A module typing error surfaced while typing an expression form.
    ModuleError(Box<crate::types::typemod::TypeModError>),

    /// Unexpected existential.
    UnexpectedExistential { loc: LocIdx },

    /// Unqualified GADT pattern.
    UnqualifiedGadtPattern {
        loc: LocIdx,
        tpath: Path,
        name: String,
    },

    /// Invalid interval pattern.
    InvalidInterval { loc: LocIdx },

    /// Invalid for loop index.
    InvalidForLoopIndex { loc: LocIdx },

    /// Invalid for...of binding (only `_` or a variable allowed). Upstream #7887.
    InvalidForOfPattern { loc: LocIdx },

    /// No value clauses.
    NoValueClauses { loc: LocIdx },

    /// Exception pattern below toplevel.
    ExceptionPatternBelowToplevel { loc: LocIdx },

    /// Inlined record escape.
    InlinedRecordEscape { loc: LocIdx },

    /// Inlined record expected.
    InlinedRecordExpected { loc: LocIdx },

    /// Break outside a directly enclosing loop body.
    BreakOutsideLoop { loc: LocIdx },

    /// Continue outside a directly enclosing loop body.
    ContinueOutsideLoop { loc: LocIdx },

    /// Break that would leave a `finally` block.
    BreakOutOfFinally { loc: LocIdx },

    /// Continue that would leave a `finally` block.
    ContinueOutOfFinally { loc: LocIdx },

    /// Literal overflow.
    LiteralOverflow { loc: LocIdx, ty: String },

    /// A numeric polymorphic variant name outside the int32 range.
    PolyvarLiteralOverflow { loc: LocIdx },

    /// Unknown literal.
    UnknownLiteral {
        loc: LocIdx,
        literal: String,
        modifier: char,
    },

    /// A template segment with an invalid escape sequence.
    InvalidStringEscapeSequence { loc: LocIdx },
    /// A declaration attribute's template with an invalid escape, raised
    /// where a use reads it (`Ast_payload.semantic_string_of_expression`,
    /// ast_payload.ml:39-51); the declaration may be in another unit.
    InvalidStringEscapeAt { loc: Location },
    /// typetexp.ml `Ptyp_arrow`: `Location.raise_errorf` for a fixed argument
    /// (`Parg_fixed`), which external processing removes before typing.
    FixedArgumentOutsideExternal { loc: LocIdx },

    /// A `json` literal outside an external payload.

    /// Illegal let-rec pattern.
    IllegalLetrecPat { loc: LocIdx },

    /// Illegal let-rec right-hand side expression.
    IllegalLetrecExpr { loc: LocIdx },

    /// Empty record literal.
    EmptyRecordLiteral { loc: LocIdx },

    /// Uncurried arity mismatch.
    UncurriedArityMismatch {
        loc: LocIdx,
        function_type: TypeExprRef,
        expected_arity: usize,
        provided_arity: usize,
        provided_args: Vec<ArgLabel>,
        function_name: Option<Longident>,
        arity_suggestion: Option<String>,
    },

    /// Field not optional.
    FieldNotOptional {
        /// Location of the expression or pattern marked with `?`.
        loc: LocIdx,
        /// Field name.
        name: String,
        /// Record type containing the field.
        typ: TypeExprRef,
    },

    /// Type params not supported.
    TypeParamsNotSupported { loc: LocIdx, lid: Longident },

    /// Field access on dict type.
    FieldAccessOnDictType { loc: LocIdx },

    /// Record syntax on a dict, e.g. `let d: dict<int> = {foo: 1}`
    /// (`Record_syntax_on_dict_type`).
    RecordSyntaxOnDictType { loc: LocIdx, key: String },

    /// A key matched twice in a dict pattern (`Dict_key_multiply_defined`).
    DictKeyMultiplyDefined { loc: LocIdx, key: String },

    /// Unbound record field access.
    UnboundRecordField {
        loc: LocIdx,
        field_name: String,
        from_type: Option<TypeExprRef>,
        alternatives: Vec<String>,
    },

    /// Object type spread/inheritance used with a non-object type.
    NotAnObjectType { loc: LocIdx, ty: TypeExprRef },

    /// Object type spread/inheritance used with an open object type.
    OpenedObject { loc: LocIdx, path: Option<Path> },

    /// JSX not enabled.
    JsxNotEnabled { loc: LocIdx },

    /// typecore.ml `Jsx_component_without_make`: a JSX element names a
    /// module that defines no `make`.
    JsxComponentWithoutMake {
        loc: LocIdx,
        module_lid: String,
        /// `Typetexp.spellcheck_value` candidates for `module_lid.make`.
        alternatives: Vec<String>,
    },

    /// An extension point reached the typechecker without being handled by a PPX.
    ExtensionError(BuiltinExtensionError),

    /// OCaml's `Location.Already_displayed_error` sentinel for empty `[%error]` payloads.
    ExtensionAlreadyDisplayed,

    /// Other error (catch-all for module type checking errors propagated from typemod).
    Other(String),
}

/// Context for type clash errors.
#[derive(Debug, Clone)]
pub enum TypeClashContext {
    /// In a function call.
    FunctionCall,
    /// In a function argument.
    FunctionArgument {
        optional: bool,
        name: Option<String>,
    },
    /// In a JSX component position.
    JsxComponent,
    /// In a statement that discards a function call result.
    StatementFunctionCall,
    /// In a comparison operator.
    ComparisonOperator,
    /// In a string concatenation operator.
    StringConcat,
    /// In a mathematical operator.
    MathOperator {
        for_float: bool,
        operator: String,
        is_constant: Option<String>,
    },
    /// In a braced identifier.
    BracedIdent,
    /// In a record spread.
    RecordSpread,
    /// In a record field value.
    RecordField {
        field_name: String,
        optional: bool,
        jsx: Option<JsxPropKind>,
    },
    /// In a record field assignment.
    SetRecordField { field_name: String },
    /// In an array literal.
    ArrayLiteral,
    /// In a `${...}` interpolation of a tagged-template literal.
    TaggedTemplateValue,
    /// In a tuple.
    Tuple,
    /// In an if condition.
    IfCondition,
    /// In an if expression branch return.
    IfReturn,
    /// In a ternary expression branch return.
    TernaryReturn,
    /// In a while loop condition.
    WhileCondition,
    /// In a for loop bound.
    ForLoopCondition,
    /// In an assertion condition.
    AssertCondition,
    /// In an awaited expression.
    Await,
    /// In a switch expression.
    SwitchExpression,
    /// In a try/catch expression handler return.
    TryReturn,
    /// In a let? rewritten match return.
    LetUnwrapReturn,
}

/// Where a type clash would be reported, as the walk passes it down: handles
/// only, so passing it on copies a few words. [`ClashSite::resolve`] makes
/// the owned [`TypeClashContext`] when an error is built.
#[derive(Debug, Clone, Copy)]
pub(crate) enum ClashSite {
    /// In a function call.
    FunctionCall,
    /// In a function argument.
    FunctionArgument {
        optional: bool,
        name: Option<StrIdx>,
    },
    /// In a JSX component position.
    JsxComponent,
    /// In a statement that discards a function call result.
    StatementFunctionCall,
    /// In a comparison operator.
    ComparisonOperator,
    /// In a string concatenation operator.
    StringConcat,
    /// In a mathematical operator.
    MathOperator {
        for_float: bool,
        operator: &'static str,
        is_constant: Option<StrIdx>,
    },
    /// In a braced identifier.
    BracedIdent,
    /// In a record spread.
    RecordSpread,
    /// In a record field value.
    RecordField {
        field_name: crate::name::Name,
        optional: bool,
        jsx: Option<JsxPropKind>,
    },
    /// In a record field assignment.
    SetRecordField { field_name: crate::name::Name },
    /// In an array literal.
    ArrayLiteral,
    /// In a `${...}` interpolation of a tagged-template literal.
    TaggedTemplateValue,
    /// In a tuple.
    Tuple,
    /// In an if condition.
    IfCondition,
    /// In an if expression branch return.
    IfReturn,
    /// In a ternary expression branch return.
    TernaryReturn,
    /// In a while loop condition.
    WhileCondition,
    /// In a for loop bound.
    ForLoopCondition,
    /// In an assertion condition.
    AssertCondition,
    /// In an awaited expression.
    Await,
    /// In a switch expression.
    SwitchExpression,
    /// In a try/catch expression handler return.
    TryReturn,
    /// In a let? rewritten match return.
    LetUnwrapReturn,
}

impl ClashSite {
    /// The owned context an error carries.
    pub(crate) fn resolve(self, arena: &ParseArena) -> TypeClashContext {
        match self {
            ClashSite::FunctionCall => TypeClashContext::FunctionCall,
            ClashSite::FunctionArgument { optional, name } => TypeClashContext::FunctionArgument {
                optional,
                name: name.map(|name| arena.get_string(name).to_string()),
            },
            ClashSite::JsxComponent => TypeClashContext::JsxComponent,
            ClashSite::StatementFunctionCall => TypeClashContext::StatementFunctionCall,
            ClashSite::ComparisonOperator => TypeClashContext::ComparisonOperator,
            ClashSite::StringConcat => TypeClashContext::StringConcat,
            ClashSite::MathOperator {
                for_float,
                operator,
                is_constant,
            } => TypeClashContext::MathOperator {
                for_float,
                operator: operator.to_string(),
                is_constant: is_constant.map(|text| arena.get_string(text).to_string()),
            },
            ClashSite::BracedIdent => TypeClashContext::BracedIdent,
            ClashSite::RecordSpread => TypeClashContext::RecordSpread,
            ClashSite::RecordField {
                field_name,
                optional,
                jsx,
            } => TypeClashContext::RecordField {
                field_name: field_name.as_str().to_string(),
                optional,
                jsx,
            },
            ClashSite::SetRecordField { field_name } => TypeClashContext::SetRecordField {
                field_name: field_name.as_str().to_string(),
            },
            ClashSite::ArrayLiteral => TypeClashContext::ArrayLiteral,
            ClashSite::TaggedTemplateValue => TypeClashContext::TaggedTemplateValue,
            ClashSite::Tuple => TypeClashContext::Tuple,
            ClashSite::IfCondition => TypeClashContext::IfCondition,
            ClashSite::IfReturn => TypeClashContext::IfReturn,
            ClashSite::TernaryReturn => TypeClashContext::TernaryReturn,
            ClashSite::WhileCondition => TypeClashContext::WhileCondition,
            ClashSite::ForLoopCondition => TypeClashContext::ForLoopCondition,
            ClashSite::AssertCondition => TypeClashContext::AssertCondition,
            ClashSite::Await => TypeClashContext::Await,
            ClashSite::SwitchExpression => TypeClashContext::SwitchExpression,
            ClashSite::TryReturn => TypeClashContext::TryReturn,
            ClashSite::LetUnwrapReturn => TypeClashContext::LetUnwrapReturn,
        }
    }
}

/// JSX prop error info.
#[derive(Debug, Clone)]
pub struct JsxPropErrorInfo {
    /// Component name.
    pub component_name: Option<String>,
    /// Props.
    pub props: Vec<String>,
    /// JSX prop record kind.
    pub jsx_type: JsxPropKind,
}

/// JSX prop record kind.
#[derive(Debug, Clone, Copy)]
pub enum JsxPropKind {
    /// JSX fragment props.
    Fragment,
    /// Custom component props.
    CustomComponent,
}

/// Result type for type checking.
pub type TypeCoreResult<T> = Result<T, TypeCoreError>;

// Every typing function returns `TypeCoreResult`, so a large error makes every
// `Ok` path move the full error-sized `Result`. Box cold payloads to stay under
// this bound; `TypeModError::CoreError` embeds this type unboxed.
const _: () = assert!(std::mem::size_of::<TypeCoreError>() <= 112);

