/// How `type_pattern_inner` types a pattern; fixed for a whole pattern
/// except where an or-pattern changes the mode of its branches.
#[derive(Debug, Clone, Copy)]
struct PatternOptions {
    mode: PatternMode,
    /// Whether GADT constructors may bind existential types here.
    allow_existentials: bool,
    /// The level delayed pattern checks run at (`type_pat ~lev`).
    level: i32,
}

/// Mode for pattern type checking.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PatternMode {
    /// Normal pattern matching.
    Normal,
    /// Splitting an or-pattern.
    SplittingOr,
    /// Inside a non-split or-pattern.
    InsideOr,
    /// Always split or-patterns.
    SplitOr,
}

/// Whether recursive arguments are allowed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RecArg {
    /// Allowed.
    Allowed,
    /// Required.
    Required,
    /// Rejected.
    Rejected,
}

// ============================================================================
// Type Checking State
// ============================================================================

/// State for pattern type checking.
pub struct PatternState {
    /// Pattern variables collected.
    pattern_variables: Vec<PatternVariable>,
    /// Whether modules are allowed.
    allow_modules: bool,
    /// Module variables collected.
    module_variables: Vec<(crate::parse_arena::Located<crate::name::Name>, Location)>,
    /// Type paths whose component-table side effects must run after the whole
    /// pattern has allocated binders.
    deferred_type_path_forces: Vec<TypeExprRef>,
    /// OCaml `pattern_force` (typecore.ml:421): the closures returned by
    /// `Typetexp.transl_simple_type_delayed` for pattern constraints, in
    /// registration order.
    globalize_forces: Vec<GlobalizeForce>,
    /// OCaml `type_pat`'s `constrs <> None`: the pattern is a counter-example
    /// Parmatch built, typed again by `partial_pred` (typecore.ml:1788-1798).
    /// Its exploded wildcards are typed with `~constrs` too
    /// (typecore.ml:1270-1288), and `explode > 0` only comes from
    /// `partial_pred`, so this holds for the whole pattern.
    counter_example: bool,
    /// The alternatives the split or-patterns of a counter-example take.
    or_splits: OrSplits,
}

/// The alternative each split or-pattern of a counter-example takes, in the
/// order typing reaches the or-patterns.
///
/// OCaml's `type_pat` is in continuation-passing style: a split or-pattern
/// types its first alternative and then the rest of the whole pattern, and a
/// type error anywhere in that makes it go back and take its second
/// alternative (typecore.ml:1713-1720). Rust's pattern typing returns, so
/// `partial_pred` runs the same search from the outside: after an error it
/// types the counter-example again, with the last or-pattern that took its
/// first alternative taking its second.
#[derive(Default)]
struct OrSplits {
    /// Whether the nth split takes its second alternative.
    second: Vec<bool>,
    /// How many splits this typing of the counter-example has reached.
    reached: usize,
}

impl OrSplits {
    /// Whether the or-pattern split now takes its second alternative.
    fn take_second(&mut self) -> bool {
        if self.reached == self.second.len() {
            self.second.push(false);
        }
        self.reached += 1;
        self.second[self.reached - 1]
    }

    /// After a type error, move to the next combination of alternatives.
    /// Returns false once all of them have been tried.
    fn backtrack(&mut self) -> bool {
        self.reached = 0;
        while let Some(second) = self.second.pop() {
            if !second {
                self.second.push(true);
                return true;
            }
        }
        false
    }
}

/// One deferred unification of `Typetexp.globalize_used_variables`'s force
/// closure (typetexp.ml:682-688): `(loc, t1, t2)`.
pub(crate) type GlobalizeForce = (LocIdx, TypeExprRef, TypeExprRef);

#[derive(Clone, Copy)]
struct PatternStateCheckpoint {
    pattern_variables_len: usize,
    module_variables_len: usize,
    deferred_type_path_forces_len: usize,
    globalize_forces_len: usize,
}

/// How a pattern binds a variable (`Typecore.enter_variable`'s
/// `is_as_variable` and `is_module` flags, which never hold together).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PatternVariableKind {
    /// An ordinary variable pattern.
    Value,
    /// The name bound by an `as` alias pattern.
    Alias,
    /// A first-class module unpacked by the pattern.
    Module,
}

/// A pattern variable with its binding information.
#[derive(Debug, Clone)]
pub struct PatternVariable {
    /// The identifier.
    pub id: Ident,
    /// The type.
    pub ty: TypeExprRef,
    /// Original parser location index for this binding.
    pub loc_idx: LocIdx,
    /// The name with location.
    pub name: crate::parse_arena::Located<crate::name::Name>,
    /// The location.
    pub loc: Location,
    /// Whether this is an as-variable.
    pub is_as_variable: bool,
    /// Whether this variable is bound as an unpacked module.
    pub is_module: bool,
}

impl PatternState {
    /// Create a new pattern state.
    pub fn new() -> Self {
        PatternState {
            pattern_variables: Vec::new(),
            allow_modules: false,
            module_variables: Vec::new(),
            deferred_type_path_forces: Vec::new(),
            globalize_forces: Vec::new(),
            counter_example: false,
            or_splits: OrSplits::default(),
        }
    }

    /// The state for typing a counter-example in `partial_pred`.
    fn for_counter_example(or_splits: OrSplits) -> Self {
        PatternState {
            counter_example: true,
            or_splits,
            ..PatternState::new()
        }
    }

    /// Enter a variable into the pattern state.
    /// Takes parsed `Located<StrIdx>` (with `LocIdx`) and arena to convert to Location.
    pub fn enter_variable(
        &mut self,
        type_ctx: &crate::types::TypeContext,
        loc: LocIdx,
        name: &Located<StrIdx>,
        ty: TypeExprRef,
        kind: PatternVariableKind,
        arena: &ParseArena,
    ) -> TypeCoreResult<Ident> {
        let is_as_variable = kind == PatternVariableKind::Alias;
        let is_module = kind == PatternVariableKind::Module;
        let interned = arena.name(name.txt);
        let name_str = interned.as_str();
        // Check for duplicate binding
        if self
            .pattern_variables
            .iter()
            .any(|pv| pv.id.name_atom() == interned)
        {
            return Err(TypeCoreError::MultiplyBoundVariable {
                loc,
                name: name_str.to_string(),
            });
        }

        let id = type_ctx.create_ast_ident(arena, name.txt);
        let full_loc = arena.to_location(loc);
        let full_name = crate::parse_arena::Located {
            txt: interned,
            loc: name.loc,
        };
        self.pattern_variables.push(PatternVariable {
            id,
            ty,
            loc_idx: loc,
            name: full_name,
            loc: full_loc,
            is_as_variable,
            is_module,
        });

        if is_module {
            if !self.allow_modules {
                return Err(TypeCoreError::ModulesNotAllowed { loc });
            }
            self.module_variables.push((full_name, full_loc));
        }

        Ok(id)
    }

    /// Reset the pattern state.
    pub fn reset(&mut self, allow_modules: bool) {
        self.pattern_variables.clear();
        self.allow_modules = allow_modules;
        self.module_variables.clear();
        self.deferred_type_path_forces.clear();
        self.globalize_forces.clear();
    }

    fn add_globalize_forces(&mut self, forces: Vec<GlobalizeForce>) {
        self.globalize_forces.extend(forces);
    }

    fn take_globalize_forces(&mut self) -> Vec<GlobalizeForce> {
        std::mem::take(&mut self.globalize_forces)
    }

    fn defer_type_path_force(&mut self, ty: TypeExprRef) {
        self.deferred_type_path_forces.push(ty);
    }

    fn take_deferred_type_path_forces(&mut self) -> Vec<TypeExprRef> {
        std::mem::take(&mut self.deferred_type_path_forces)
    }

    fn checkpoint(&self) -> PatternStateCheckpoint {
        PatternStateCheckpoint {
            pattern_variables_len: self.pattern_variables.len(),
            module_variables_len: self.module_variables.len(),
            deferred_type_path_forces_len: self.deferred_type_path_forces.len(),
            globalize_forces_len: self.globalize_forces.len(),
        }
    }

    fn restore_checkpoint(&mut self, checkpoint: PatternStateCheckpoint) {
        self.pattern_variables
            .truncate(checkpoint.pattern_variables_len);
        self.module_variables
            .truncate(checkpoint.module_variables_len);
        self.deferred_type_path_forces
            .truncate(checkpoint.deferred_type_path_forces_len);
        self.globalize_forces
            .truncate(checkpoint.globalize_forces_len);
    }

    fn restore_binding_checkpoint(&mut self, checkpoint: PatternStateCheckpoint) {
        self.pattern_variables
            .truncate(checkpoint.pattern_variables_len);
        self.module_variables
            .truncate(checkpoint.module_variables_len);
    }
}

impl Default for PatternState {
    fn default() -> Self {
        Self::new()
    }
}

// ============================================================================
// Type Checking Context
// ============================================================================

/// A `Delayed_checks.add_delayed_check unused_check` closure from
/// `type_cases`/`type_function` (typecore.ml:3792-3798, 4483-4490).
struct DelayedUnusedCheck {
    env: Env,
    level: i32,
    ty_arg_check: TypeExprRef,
    cases: Vec<ParmatchCase>,
    /// `Warnings.backup ()` taken when the check was registered.
    warning_config: WarningConfig,
    /// Whether to run `Parmatch.check_ambiguous_bindings` afterwards.
    check_ambiguous: bool,
    /// Registration order among all delayed checks.
    seq: u64,
}

/// The `Delayed_checks.add_delayed_check` closure `Env.open_signature`
/// registers for a warning-tracked open (env.ml:1843-1846).
struct DelayedOpenCheck {
    slot: u32,
    /// `Path.name root`.
    root: String,
    loc: LocIdx,
    /// `Warnings.backup ()` at registration.
    warning_config: WarningConfig,
    seq: u64,
}

/// Context for type checking.
pub struct TypeCheckContext<'a> {
    /// Optional item accounting; absent in ordinary compilation.
    pub derived_census: Option<Box<crate::derived_census::Census>>,
    /// An obligation of a derived item's plan failed: the checking of the
    /// unit was abandoned, and the unit is to be compiled again with plans
    /// off, whatever the checker returned.
    pub derived_fallback: bool,
    /// Type context for allocation.
    pub type_ctx: &'a TypeContext,
    /// Parse arena for location conversion and longident allocation.
    pub arena: &'a ParseArena,
    /// Node storage of the typed tree being built. Consumers receive it
    /// through [`TypeCheckContext::take_typed_arena`] once typing is done.
    pub typed: TypedArena,
    /// Unification state.
    pub unify_state: UnifyState,
    /// Newtype level (for local type definitions).
    pub newtype_level: Option<i32>,
    /// Collected diagnostics.
    pub diagnostics: Vec<TypeCoreDiagnostic>,
    /// Collected warnings.
    pub warnings: Vec<TypeCoreWarning>,
    /// Value usage checks registered when bindings enter the environment.
    ///
    /// Mirrors OCaml Env.check_usage/Delayed_checks: lookup marks a binding as
    /// used, and the warning is emitted only when delayed checks are forced.
    value_usage_checks: Vec<ValueUsageCheck>,
    /// Type, module, constructor and extension usage checks (`Env.store_*`
    /// with `~check:true`).
    env_usage_checks: Vec<EnvUsageCheck>,
    /// The unused-identifier checks of `type_let`.
    let_value_checks: Vec<LetValueCheck>,
    /// Unused-case checks run when delayed checks are flushed.
    delayed_unused_checks: Vec<DelayedUnusedCheck>,
    /// Delayed checks whose outcome Rust computes after the fact, keyed by
    /// their `Delayed_checks.add_delayed_check` registration order.
    delayed_warnings: Vec<((u64, u32), TypeCoreWarning)>,
    /// Registration counter shared by all delayed checks, so they are forced
    /// in registration order like `Delayed_checks.force_delayed_checks`.
    delayed_check_seq: u64,
    /// The unused-open delayed checks of `Env.open_signature`
    /// (env.ml:1843-1846).
    delayed_open_checks: Vec<DelayedOpenCheck>,
    /// `Parmatch.Conv.name_counter`.
    conv_name_counter: u32,
    generated_pattern_constructors: Vec<(crate::name::Name, Arc<crate::types::ConstructorDescription>)>,
    generated_pattern_labels: Vec<(crate::name::Name, Arc<crate::types::LabelDescription>)>,
    /// Whether a wildcard of the type at each path can turn into a GADT
    /// constructor when typed again (see [`wildcard_may_reach_gadt`]).
    wildcard_reaches_gadt: HashMap<Path, bool>,
    /// Current warning configuration.
    pub warning_config: WarningConfig,
    /// Current loop nesting depth for validating break/continue.
    pub loop_depth: usize,
    /// Whether the innermost loop or function boundary is a finally block,
    /// which break and continue must not leave (typecore.ml `in_finally`).
    pub in_finally: bool,
    /// Used type variables within the current type expression (for sharing).
    /// Maps type variable names to their TypeExprRef, matching OCaml's used_variables.
    pub used_variables: HashMap<String, TypeExprRef>,
    /// Location of each used variable's first occurrence (OCaml stores
    /// `(ty, loc)` in `used_variables`).
    pub used_variable_locs: HashMap<String, LocIdx>,
    /// Universal variables currently bound by Ptyp_poly.
    /// This mirrors OCaml typetexp's `univars` stack, which is deliberately
    /// separate from `used_variables`.
    univars: Vec<(String, TypeExprRef)>,
    /// Bound type variables from the surrounding declaration context.
    /// This matches OCaml's typetexp `type_variables` table used by
    /// `globalize_used_variables` to link per-type-expression variables
    /// back to declaration-level parameters.
    pub type_variables: HashMap<String, TypeExprRef>,
    /// Whether the current type translation rejects free type variables.
    fixed_type_variables: bool,
    /// Persistent environment for loading external modules from .cmi files.
    pub persistent_env: Option<crate::cmi::persistent_env::PersistentEnv>,
    /// Active recursive value bindings currently in scope.
    /// Used to restrict recursive polymorphic-variant payload fallback to
    /// identifiers that actually resolve to recursive bindings.
    pub active_recursive_value_ids: Vec<Ident>,
    /// Mirrors OCaml's Experimental_features.LetUnwrap during type checking.
    pub experimental_let_unwrap: bool,
    /// OCaml's `?deprecated_context:FunctionCall` argument (typecore.ml:2594,
    /// 2632): set right before typing the function of an application or the
    /// tag of a tagged template, and taken by the next expression typed.
    /// Braces pass it on to their inner expression (typecore.ml:2450-2452).
    pub(crate) deprecated_function_call: bool,
    /// Mirrors OCaml's Clflags.transparent_modules from `-no-alias-deps`.
    pub transparent_modules: bool,
    /// Cached semantic module types from Tmod_apply, keyed by parsed module
    /// expression location.  Ensures that a second lookup for the same functor
    /// application reuses the types with correct path substitutions.
    pub(crate) module_expr_semantic_types:
        HashMap<crate::parse_arena::LocIdx, crate::types::decl::ModuleType>,
    /// Depth inside applicative functor bodies.
    /// Mirrors typemod.ml's `funct_body` flag for rejecting fresh module types.
    pub(crate) applicative_functor_body_depth: usize,
}

/// A diagnostic from type checking.
#[derive(Debug, Clone)]
pub struct TypeCoreDiagnostic {
    /// Location of the error.
    pub loc: Location,
    /// The error.
    pub error: TypeCoreError,
}

/// A warning from type checking.
#[derive(Debug, Clone)]
pub struct TypeCoreWarning {
    /// Location of the warning.
    pub loc: LocIdx,
    /// The warning.
    pub warning: Warning,
    /// Whether this warning is configured as an error.
    pub is_error: bool,
}

#[derive(Debug, Clone)]
/// A delayed check registered by `Env.check_usage`, `store_type` or
/// `store_extension` (env.ml:1562-1576, 1606-1665). The warning state is the
/// one current at registration (`Delayed_checks.add_delayed_check` saves it).
struct EnvUsageCheck {
    seq: u64,
    loc: LocIdx,
    is_error: bool,
    kind: EnvUsageCheckKind,
}

#[derive(Debug, Clone)]
enum EnvUsageCheckKind {
    Declaration {
        cell: crate::types::usage::UsedCell,
        warning: Warning,
    },
    Constructor {
        cell: crate::types::usage::ConstructorUsageCell,
        name: String,
        in_signature: bool,
    },
    Extension {
        cell: crate::types::usage::ConstructorUsageCell,
        name: String,
        is_exception: bool,
        in_signature: bool,
    },
}

struct ValueUsageCheck {
    name: String,
    val_loc: Location,
    warning_loc: LocIdx,
    warning: Warning,
    is_error: bool,
    cell: crate::types::usage::UsedCell,
    seq: u64,
}

/// The delayed check `Typecore.type_let` registers for a let-bound
/// identifier (typecore.ml:4613-4618): at force time, warn with `check_strict`
/// when another identifier of the pattern was used, else with `check`. The
/// warning state is the one of the binding's attributes at registration.
struct LetValueCheck {
    seq: u64,
    loc: LocIdx,
    used: crate::types::usage::UsedCell,
    some_used: crate::types::usage::UsedCell,
    /// `(warning, is_active, is_error)` for `check name`.
    normal: (Warning, bool, bool),
    /// `(warning, is_active, is_error)` for `check_strict name`.
    strict: (Warning, bool, bool),
}

/// The `check`/`check_strict` pair of a `type_let` (typecore.ml:4523-4525).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum LetCheck {
    /// `Warnings.Unused_var`/`Unused_var_strict`.
    Local,
    /// `Typecore.type_binding`: `Unused_value_declaration` for both.
    Toplevel,
    /// `type_let ~optional_default:true`, the let binding an optional
    /// parameter's default that `type_function` synthesizes: `check =
    /// check_strict`, and its match gets function-style diagnostics
    /// (typecore.ml:4930-4952, 5061-5068).
    FakeOptional,
}

/// `type_expect ?match_context` (typecore.ml:2571-2576): set where the type
/// checker itself rewrites source into a match, it says what that match
/// stands for in the source and decides the wording of its diagnostics.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum MatchContext {
    /// `` `Function ``: function-style diagnostics instead of a switch's.
    Function,
}

impl<'a> TypeCheckContext<'a> {
    /// `TypeContext::intern_loc`.
    #[inline]
    pub fn intern_loc(&self, loc: Location) -> crate::types::DeclLoc {
        self.type_ctx.intern_loc(loc)
    }

    /// Preserve the parser's allocation identities at the declaration boundary.
    pub fn intern_ast_loc(
        &self,
        arena: &ParseArena,
        index: crate::parse_arena::LocIdx,
    ) -> crate::types::DeclLoc {
        self.type_ctx.intern_ast_loc(arena, index)
    }

    /// `TypeContext::resolve_loc`.
    #[inline]
    pub fn resolve_loc(&self, loc: crate::types::DeclLoc) -> Location {
        self.type_ctx.resolve_loc(loc)
    }

    /// Create a new type check context.
    pub fn new(type_ctx: &'a TypeContext, arena: &'a ParseArena) -> Self {
        type_ctx.register_arena_longident_names(arena);
        TypeCheckContext {
            derived_census: None,
            derived_fallback: false,
            type_ctx,
            arena,
            typed: TypedArena::new(),
            unify_state: UnifyState::new(),
            newtype_level: None,
            diagnostics: Vec::new(),
            warnings: Vec::new(),
            value_usage_checks: Vec::new(),
            env_usage_checks: Vec::new(),
            let_value_checks: Vec::new(),
            delayed_unused_checks: Vec::new(),
            delayed_warnings: Vec::new(),
            delayed_check_seq: 0,
            delayed_open_checks: Vec::new(),
            conv_name_counter: 0,
            generated_pattern_constructors: Vec::new(),
            generated_pattern_labels: Vec::new(),
            wildcard_reaches_gadt: HashMap::default(),
            warning_config: WarningConfig::new(),
            loop_depth: 0,
            in_finally: false,
            used_variables: HashMap::new(),
            used_variable_locs: HashMap::new(),
            univars: Vec::new(),
            type_variables: HashMap::new(),
            fixed_type_variables: false,
            active_recursive_value_ids: Vec::new(),
            persistent_env: None,
            experimental_let_unwrap: false,
            deprecated_function_call: false,
            transparent_modules: false,
            module_expr_semantic_types: HashMap::new(),
            applicative_functor_body_depth: 0,
        }
    }

    /// Hand the typed tree's node storage to its consumers. Nodes typed
    /// afterwards go to a fresh arena.
    pub fn take_typed_arena(&mut self) -> TypedArena {
        std::mem::take(&mut self.typed)
    }

    /// Store a typed expression.
    #[inline]
    pub fn push_expr(&mut self, expr: Expression) -> TExprIdx {
        self.typed.push_expr(expr)
    }

    /// A stored typed expression.
    #[inline]
    pub fn expr(&self, idx: TExprIdx) -> &Expression {
        self.typed.expr(idx)
    }

    /// Set the environment for type alias expansion during unification.
    /// Should be called before type-checking each structure item so the
    /// unifier can expand type aliases when paths don't match.
    pub fn set_unify_env(&mut self, env: &Env) {
        self.unify_state.set_env(env);
    }

    /// Set the persistent environment for module loading.
    pub fn set_persistent_env(&mut self, env: crate::cmi::persistent_env::PersistentEnv) {
        self.type_ctx.set_persistent_env(env.clone());
        self.persistent_env = Some(env);
    }

    /// Match OCaml Typetexp.reset_type_variables (typetexp.ml:213-216):
    /// reset Ctype.global_level for fresh globals and the reified variable
    /// counter, then clear the table.
    pub fn reset_type_variables(&mut self) {
        self.type_ctx.reset_global_level();
        self.type_ctx.reset_reified_var_counter();
        self.type_variables.clear();
    }

    /// Report an error.
    pub fn report_error(&mut self, loc: Location, error: TypeCoreError) {
        self.diagnostics.push(TypeCoreDiagnostic { loc, error });
    }

    /// Report a warning.
    pub fn report_warning(&mut self, loc: LocIdx, warning: Warning) {
        self.drain_open_slot_uses();
        self.report_warning_at(self.warnings.len(), loc, warning);
    }

    /// The open part of `Env.open_signature ~used_slot ~loc ovf root`
    /// (env.ml:1832-1864): for a fresh, non-ghost open with warning 33, 44
    /// or 45 active, create the slot its opened layers carry and register the
    /// unused-open delayed check. Returns the slot to pass to the open.
    pub(crate) fn open_signature_slot(
        &mut self,
        override_flag: crate::parser::ast::OverrideFlag,
        loc: LocIdx,
    ) -> Option<u32> {
        self.drain_open_slot_uses();
        let tracked = matches!(override_flag, crate::parser::ast::OverrideFlag::Fresh)
            && !self.arena.to_location(loc).loc_ghost
            && (self.warning_config.is_active(&Warning::UnusedOpen {
                name: String::new(),
            }) || self
                .warning_config
                .is_active(&Warning::OpenShadowIdentifier {
                    kind: String::new(),
                    name: String::new(),
                })
                || self
                    .warning_config
                    .is_active(&Warning::OpenShadowLabelConstructor {
                        kind: String::new(),
                        name: String::new(),
                    }));
        if !tracked {
            return None;
        }
        let slot = self.type_ctx.new_open_slot(loc);
        let seq = self.next_delayed_check_seq();
        self.delayed_open_checks.push(DelayedOpenCheck {
            slot,
            root: String::new(),
            loc,
            warning_config: self.warning_config.clone(),
            seq,
        });
        Some(slot)
    }

    /// Record the opened root of a slot created by
    /// [`Self::open_signature_slot`] once the open resolved it.
    pub(crate) fn set_open_slot_root(&mut self, slot: Option<u32>, root: &Path) {
        let Some(slot) = slot else {
            return;
        };
        if let Some(check) = self
            .delayed_open_checks
            .iter_mut()
            .rev()
            .find(|c| c.slot == slot)
        {
            check.root = root.name();
        }
    }

    /// Run the `using` callbacks recorded by lookups (env.ml:1847-1861):
    /// report each newly shadowed `(kind, name)` at the open's location, and
    /// mark the open used.
    /// `report_deprecated ?loc p deprecated` (env.ml:989-994).
    fn report_module_deprecation(&mut self, deprecation: crate::types::context::ModuleDeprecation) {
        use crate::types::context::ModuleDeprecation;
        let (loc, name, deprecated) = match deprecation {
            ModuleDeprecation::Resolved {
                loc,
                name,
                deprecated,
            } => (loc, name, deprecated),
            ModuleDeprecation::Persistent { loc, name, target } => {
                let Some(deprecated) = self.persistent_env.as_ref().and_then(|pers_env| {
                    persistent_module_deprecated(pers_env, &target)
                }) else {
                    return;
                };
                (loc, name.name(), deprecated)
            }
        };
        let txt = if deprecated.is_empty() {
            String::new()
        } else {
            format!("\n{deprecated}")
        };
        self.report_warning_at(
            self.warnings.len(),
            loc,
            Warning::Deprecated {
                message: format!("module {name}{txt}"),
                def_loc: Location::none(),
                use_loc: Location::none(),
                can_be_automigrated: false,
            },
        );
    }

    pub(crate) fn drain_open_slot_uses(&mut self) {
        for event in self.type_ctx.take_open_slot_events() {
            let event = match event {
                crate::types::context::LookupEvent::OpenSlot(event) => event,
                crate::types::context::LookupEvent::ModuleDeprecated(deprecation) => {
                    self.report_module_deprecation(deprecation);
                    continue;
                }
            };
            let report = self.type_ctx.with_open_slot(event.slot, |state| {
                let report = if event.shadowed
                    && !state
                        .shadowed
                        .iter()
                        .any(|(kind, name)| *kind == event.kind && *name == event.name)
                {
                    state.shadowed.push((event.kind, event.name.clone()));
                    Some(state.loc)
                } else {
                    None
                };
                state.used = true;
                report
            });
            if let Some(loc) = report {
                let warning = match event.kind {
                    "label" | "constructor" => Warning::OpenShadowLabelConstructor {
                        kind: event.kind.to_string(),
                        name: event.name,
                    },
                    _ => Warning::OpenShadowIdentifier {
                        kind: event.kind.to_string(),
                        name: event.name,
                    },
                };
                self.report_warning_at(self.warnings.len(), loc, warning);
            }
        }
    }

    /// Report a warning at a specific position in the collected warning stream.
    pub fn report_warning_at(&mut self, index: usize, loc: LocIdx, warning: Warning) -> bool {
        if !self.warning_config.is_active(&warning) {
            return false;
        }
        let is_error = self.warning_config.is_error(&warning);
        let index = index.min(self.warnings.len());
        self.warnings.insert(
            index,
            TypeCoreWarning {
                loc,
                warning,
                is_error,
            },
        );
        true
    }

    pub fn value_usage_check_checkpoint(&self) -> usize {
        self.value_usage_checks.len()
    }

    pub fn truncate_value_usage_checks(&mut self, checkpoint: usize) {
        for check in self.value_usage_checks.drain(checkpoint..) {
            self.type_ctx
                .usage()
                .unregister_value_usage(&check.name, check.val_loc, check.cell);
        }
    }

    pub fn add_value_usage_check(
        &mut self,
        name: &str,
        val_loc: Location,
        warning_loc: LocIdx,
        warning: Warning,
    ) {
        // `Env.check_usage` (env.ml:1562-1576).
        if val_loc.loc_ghost || !self.warning_config.is_active(&warning) {
            return;
        }
        let Some(cell) = self.type_ctx.usage().check_value_usage(name, val_loc) else {
            return;
        };
        if !should_warn_unused_name(name) {
            return;
        }

        let is_error = self.warning_config.is_error(&warning);
        let seq = self.next_delayed_check_seq();
        self.value_usage_checks.push(ValueUsageCheck {
            name: name.to_string(),
            val_loc,
            warning_loc,
            warning,
            is_error,
            cell,
            seq,
        });
    }

    /// `check_usage loc id (fun s -> Unused_type_declaration s)
    /// type_declarations` from `Env.store_type ~check:true` (env.ml:1595-1598).
    pub(crate) fn check_type_usage(&mut self, name: &str, loc: Location, warning_loc: LocIdx) {
        let warning = Warning::UnusedTypeDeclaration {
            name: name.to_string(),
        };
        if loc.loc_ghost || !self.warning_config.is_active(&warning) {
            return;
        }
        let Some(cell) = self.type_ctx.usage().check_type_usage(name, loc) else {
            return;
        };
        if crate::types::usage::warns_for_name(name) {
            self.push_env_usage_check(
                warning_loc,
                &warning.clone(),
                EnvUsageCheckKind::Declaration { cell, warning },
            );
        }
    }

    /// `check_usage loc id (fun s -> Unused_module s) module_declarations`
    /// from `Env.store_module ~check:true` (env.ml:1675-1677).
    pub(crate) fn check_module_usage(&mut self, name: &str, loc: Location, warning_loc: LocIdx) {
        let warning = Warning::UnusedModule {
            name: name.to_string(),
        };
        if loc.loc_ghost || !self.warning_config.is_active(&warning) {
            return;
        }
        let Some(cell) = self.type_ctx.usage().check_module_usage(name, loc) else {
            return;
        };
        if crate::types::usage::warns_for_name(name) {
            self.push_env_usage_check(
                warning_loc,
                &warning.clone(),
                EnvUsageCheckKind::Declaration { cell, warning },
            );
        }
    }

    /// The constructor checks of `Env.store_type ~check:true`
    /// (env.ml:1600-1620).
    pub(crate) fn check_constructor_usages(
        &mut self,
        ty_name: &str,
        loc: Location,
        warning_loc: LocIdx,
        constructors: &[String],
        in_signature: bool,
    ) {
        let probe = Warning::UnusedConstructor {
            name: String::new(),
            used_in_pattern: false,
            is_private: false,
        };
        if loc.loc_ghost || !self.warning_config.is_active(&probe) {
            return;
        }
        for name in constructors {
            let Some(cell) = self
                .type_ctx
                .usage()
                .check_constructor_usage(ty_name, loc, name)
            else {
                continue;
            };
            if !(ty_name.is_empty() || ty_name.starts_with('_')) {
                self.push_env_usage_check(
                    warning_loc,
                    &probe,
                    EnvUsageCheckKind::Constructor {
                        cell,
                        name: name.clone(),
                        in_signature,
                    },
                );
            }
        }
    }

    /// The check of `Env.store_extension ~check:true` (env.ml:1646-1665).
    pub(crate) fn check_extension_usage(
        &mut self,
        ty_name: &str,
        name: &str,
        is_exception: bool,
        loc: Location,
        warning_loc: LocIdx,
        in_signature: bool,
    ) {
        let probe = Warning::UnusedExtension {
            name: String::new(),
            is_exception: false,
            used_in_pattern: false,
            is_private: false,
        };
        if loc.loc_ghost || !self.warning_config.is_active(&probe) {
            return;
        }
        let Some(cell) = self
            .type_ctx
            .usage()
            .check_constructor_usage(ty_name, loc, name)
        else {
            return;
        };
        self.push_env_usage_check(
            warning_loc,
            &probe,
            EnvUsageCheckKind::Extension {
                cell,
                name: name.to_string(),
                is_exception,
                in_signature,
            },
        );
    }

    fn push_env_usage_check(&mut self, loc: LocIdx, warning: &Warning, kind: EnvUsageCheckKind) {
        let is_error = self.warning_config.is_error(warning);
        let seq = self.next_delayed_check_seq();
        self.env_usage_checks.push(EnvUsageCheck {
            seq,
            loc,
            is_error,
            kind,
        });
    }

    /// Evaluate the env usage checks, whose flags are final once delayed
    /// checks are forced.
    fn resolve_env_usage_checks(&mut self) {
        let checks = std::mem::take(&mut self.env_usage_checks);
        let usage = self.type_ctx.usage();
        let mut resolved = Vec::new();
        for check in checks {
            let warning = match check.kind {
                EnvUsageCheckKind::Declaration { cell, warning } => {
                    if usage.is_used(cell) {
                        continue;
                    }
                    warning
                }
                EnvUsageCheckKind::Constructor {
                    cell,
                    name,
                    in_signature,
                } => {
                    let cu = usage.constructor_usages(cell);
                    if in_signature || cu.cu_positive {
                        continue;
                    }
                    Warning::UnusedConstructor {
                        name,
                        used_in_pattern: cu.cu_pattern,
                        is_private: cu.cu_privatize,
                    }
                }
                EnvUsageCheckKind::Extension {
                    cell,
                    name,
                    is_exception,
                    in_signature,
                } => {
                    let cu = usage.constructor_usages(cell);
                    if in_signature || cu.cu_positive {
                        continue;
                    }
                    Warning::UnusedExtension {
                        name,
                        is_exception,
                        used_in_pattern: cu.cu_pattern,
                        is_private: cu.cu_privatize,
                    }
                }
            };
            resolved.push((
                (check.seq, 0),
                TypeCoreWarning {
                    loc: check.loc,
                    warning,
                    is_error: check.is_error,
                },
            ));
        }
        for check in std::mem::take(&mut self.let_value_checks) {
            if usage.is_used(check.used) {
                continue;
            }
            let (warning, active, is_error) = if usage.is_used(check.some_used) {
                check.strict
            } else {
                check.normal
            };
            if active {
                resolved.push((
                    (check.seq, 0),
                    TypeCoreWarning {
                        loc: check.loc,
                        warning,
                        is_error,
                    },
                ));
            }
        }
        drop(usage);
        self.delayed_warnings.extend(resolved);
    }

    /// `Env.mark_value_used` (env.ml:1125-1128).
    pub fn mark_value_used(&mut self, env: &Env, name: impl crate::name::NameKey, val_loc: Location) {
        if !env.is_implicit_coercion() {
            self.type_ctx.usage().mark_value_used(name, val_loc);
        }
    }

    /// Register the `type_let` delayed check of a let-bound identifier.
    pub(crate) fn add_let_value_check(
        &mut self,
        check: LetCheck,
        name: &str,
        loc: LocIdx,
        used: crate::types::usage::UsedCell,
        some_used: crate::types::usage::UsedCell,
    ) {
        let (normal, strict) = match check {
            LetCheck::Local => (
                Warning::UnusedVariable {
                    name: name.to_string(),
                },
                Warning::UnusedVariableStrict {
                    name: name.to_string(),
                },
            ),
            LetCheck::Toplevel => (
                Warning::UnusedValueDeclaration {
                    name: name.to_string(),
                },
                Warning::UnusedValueDeclaration {
                    name: name.to_string(),
                },
            ),
            LetCheck::FakeOptional => (
                Warning::UnusedVariableStrict {
                    name: name.to_string(),
                },
                Warning::UnusedVariableStrict {
                    name: name.to_string(),
                },
            ),
        };
        let snapshot = |config: &WarningConfig, w: Warning| {
            let active = config.is_active(&w);
            let error = config.is_error(&w);
            (w, active, error)
        };
        let normal = snapshot(&self.warning_config, normal);
        let strict = snapshot(&self.warning_config, strict);
        let seq = self.next_delayed_check_seq();
        self.let_value_checks.push(LetValueCheck {
            seq,
            loc,
            used,
            some_used,
            normal,
            strict,
        });
    }

    fn next_delayed_check_seq(&mut self) -> u64 {
        self.delayed_check_seq += 1;
        self.delayed_check_seq
    }

    /// `Delayed_checks.force_delayed_checks`: run value-usage and unused-case
    /// checks in registration order.
    pub fn flush_value_usage_checks(&mut self) {
        self.drain_open_slot_uses();
        self.resolve_env_usage_checks();
        for check in std::mem::take(&mut self.delayed_open_checks) {
            let used = self.type_ctx.with_open_slot(check.slot, |state| {
                let used = state.used;
                state.used = true;
                used
            });
            let warning = Warning::UnusedOpen { name: check.root };
            if !used && check.warning_config.is_active(&warning) {
                let is_error = check.warning_config.is_error(&warning);
                self.delayed_warnings.push((
                    (check.seq, 0),
                    TypeCoreWarning {
                        loc: check.loc,
                        warning,
                        is_error,
                    },
                ));
            }
        }
        let mut usage = std::mem::take(&mut self.value_usage_checks)
            .into_iter()
            .peekable();
        let mut unused = std::mem::take(&mut self.delayed_unused_checks)
            .into_iter()
            .peekable();
        let mut resolved = std::mem::take(&mut self.delayed_warnings);
        resolved.sort_by_key(|(key, _)| *key);
        let mut resolved = resolved.into_iter().peekable();
        loop {
            let usage_key = usage.peek().map(|u| (u.seq, 0));
            let unused_key = unused.peek().map(|c| (c.seq, 0));
            let resolved_key = resolved.peek().map(|(key, _)| *key);
            let Some(min_key) = [usage_key, unused_key, resolved_key]
                .into_iter()
                .flatten()
                .min()
            else {
                break;
            };
            if resolved_key == Some(min_key) {
                let (_, warning) = resolved.next().expect("peeked");
                self.warnings.push(warning);
                continue;
            }
            let take_usage = usage_key == Some(min_key);
            if take_usage {
                let check = usage.next().expect("peeked");
                if !self.type_ctx.usage().is_used(check.cell) {
                    self.warnings.push(TypeCoreWarning {
                        loc: check.warning_loc,
                        warning: check.warning,
                        is_error: check.is_error,
                    });
                }
            } else {
                let check = unused.next().expect("peeked");
                run_delayed_unused_check(self, check);
            }
        }
    }

    /// Apply a `@warning`/`@@warning` payload.
    pub fn apply_warning_spec(&mut self, spec: &str) {
        self.drain_open_slot_uses();
        let _ = self.warning_config.parse(spec);
    }

    /// Apply a `@warnerror`/`@@warnerror` payload.
    pub fn apply_warning_error_spec(&mut self, spec: &str) {
        self.drain_open_slot_uses();
        let _ = self.warning_config.parse_as_error(spec);
    }

    /// Get the newtype level.
    pub fn get_newtype_level(&self) -> TypeCoreResult<i32> {
        self.newtype_level
            .ok_or(TypeCoreError::UnexpectedExistential {
                loc: LocIdx::none(),
            })
    }

    /// Resolve a LidentIdx to a Longident reference.
    pub fn resolve_lid(&self, idx: LidentIdx) -> &Longident {
        self.arena.get_longident(idx)
    }

    /// Get the last component name of a Longident as a string.
    /// For `Lident("int")` returns `"int"`, for `Ldot(_, "bar")` returns `"bar"`.
    pub fn longident_last_name(&self, lid: &Longident) -> crate::name::Name {
        self.arena.name(lid.last_idx())
    }

    /// Borrow the last component name of a Longident from the parse arena.
    pub fn longident_last_name_str(&self, lid: &Longident) -> &str {
        self.arena.get_string(lid.last_idx())
    }

    /// Get the full dotted name of a Longident as a string.
    /// For `Lident("int")` returns `"int"`, for `Ldot(Lident("Foo"), "bar")` returns `"Foo.bar"`.
    pub fn longident_to_string(&self, lid: &Longident) -> String {
        self.arena.longident_to_string(lid)
    }
}

/// typecore.ml `with_control_flow_boundary ~in_finally`: the code inside
/// starts without enclosing loops.
fn with_control_flow_boundary<T>(
    tctx: &mut TypeCheckContext<'_>,
    in_finally: bool,
    f: impl FnOnce(&mut TypeCheckContext<'_>) -> TypeCoreResult<T>,
) -> TypeCoreResult<T> {
    let saved_loop_depth = tctx.loop_depth;
    let saved_in_finally = tctx.in_finally;
    tctx.loop_depth = 0;
    tctx.in_finally = in_finally;
    let result = f(tctx);
    tctx.loop_depth = saved_loop_depth;
    tctx.in_finally = saved_in_finally;
    result
}

fn with_loop_depth<T>(
    tctx: &mut TypeCheckContext<'_>,
    f: impl FnOnce(&mut TypeCheckContext<'_>) -> TypeCoreResult<T>,
) -> TypeCoreResult<T> {
    let saved = tctx.loop_depth;
    tctx.loop_depth = saved + 1;
    let result = f(tctx);
    tctx.loop_depth = saved;
    result
}

// ============================================================================
// Constants
// ============================================================================

/// Type check a constant and return its type.
pub fn type_constant(ctx: &TypeContext, env: &Env, cst: &Constant) -> TypeExprRef {
    match cst {
        // Match OCaml typecore.ml type_constant: instance_def Predef.type_*
        // so each constant occurrence gets its own instantiated node.
        Constant::Int(_) => crate::types::instance(ctx, env.type_int(ctx)),
        Constant::Char(_) => crate::types::instance(ctx, env.type_char(ctx)),
        Constant::String(_) => crate::types::instance(ctx, env.type_string(ctx)),
        Constant::Float(_) => crate::types::instance(ctx, env.type_float(ctx)),
        Constant::BigInt(_, _) => crate::types::instance(ctx, env.type_bigint(ctx)),
    }
}

/// Parse an integer literal string, handling underscores and 0x/0o/0b prefixes.
/// Returns the value as i64, or None if it can't be parsed.
fn parse_int_literal(s: &str) -> Option<i64> {
    let stripped: String = s.chars().filter(|c| *c != '_').collect();
    let (negative, digits) = match stripped.strip_prefix('-') {
        Some(digits) => (true, digits),
        None => (false, &stripped[..]),
    };
    let abs_val = if digits.starts_with("0x") || digits.starts_with("0X") {
        i64::from_str_radix(&digits[2..], 16).ok()?
    } else if digits.starts_with("0o") || digits.starts_with("0O") {
        i64::from_str_radix(&digits[2..], 8).ok()?
    } else if digits.starts_with("0b") || digits.starts_with("0B") {
        i64::from_str_radix(&digits[2..], 2).ok()?
    } else {
        digits.parse::<i64>().ok()?
    };
    if negative {
        Some(-abs_val)
    } else {
        Some(abs_val)
    }
}

/// Parse a bigint literal string following OCaml Bigint_utils.parse_bigint:
/// - keep sign separately as a bool (true for positive, false for negative)
/// - remove `_` separators
/// - remove leading zeros only when followed by decimal digits
/// - preserve non-decimal heads like `00x1` (after `_` removal)
pub(crate) fn parse_bigint_literal(s: &str) -> (bool, String) {
    fn remove_leading_sign(s: &str) -> (bool, &str) {
        if s.is_empty() {
            (false, s)
        } else if let Some(rest) = s.strip_prefix('-') {
            (false, rest)
        } else if let Some(rest) = s.strip_prefix('+') {
            (true, rest)
        } else {
            (true, s)
        }
    }

    fn remove_leading_zeros(s: &str) -> String {
        // OCaml removes separators before any zero/sign logic.
        let without_underscores: String = s.chars().filter(|c| *c != '_').collect();
        let starts_with_minus = without_underscores.starts_with('-');
        let without_sign = without_underscores
            .strip_prefix('-')
            .or_else(|| without_underscores.strip_prefix('+'))
            .unwrap_or(&without_underscores);

        let processed = if without_sign.is_empty() {
            String::new()
        } else {
            let bytes = without_sign.as_bytes();
            let mut idx = 0usize;
            while idx < bytes.len() && bytes[idx] == b'0' {
                idx += 1;
            }
            if idx >= bytes.len() {
                "0".to_string()
            } else if bytes[idx].is_ascii_digit() {
                without_sign[idx..].to_string()
            } else {
                without_sign.to_string()
            }
        };

        if starts_with_minus {
            format!("-{processed}")
        } else {
            processed
        }
    }

    let (sign, digits) = remove_leading_sign(s);
    (sign, remove_leading_zeros(digits))
}

/// Wrap an i64 value to simulate OCaml's native int (63-bit on 64-bit systems).
/// OCaml's int wraps around at 2^62, so values outside [-2^62, 2^62-1] are wrapped.
/// This matches OCaml's int_of_string behavior for large integer literals.
fn wrap_to_ocaml_int(n: i64) -> i64 {
    // OCaml's native int on 64-bit is 63 bits: range is [-2^62, 2^62-1]
    // The wrapping is equivalent to: ((n + 2^62) mod 2^63) - 2^62
    let half = 1i64 << 62; // 2^62 = 4611686018427387904
    let modulus = 1i128 << 63; // 2^63 as i128 to avoid overflow
    let shifted = (n as i128) + (half as i128);
    let wrapped = shifted.rem_euclid(modulus);
    (wrapped - half as i128) as i64
}

/// OCaml `Ext_string.is_valid_hash_number`.
fn is_valid_hash_number(value: &str) -> bool {
    match value.as_bytes() {
        [] => false,
        [b'0'..=b'9'] => true,
        [b'1'..=b'9', rest @ ..] => rest.iter().all(u8::is_ascii_digit),
        _ => false,
    }
}

/// OCaml `Typecore.check_polyvar_name` (typecore.ml:290-297): a numeric
/// polymorphic variant name is its own runtime value, so it has to fit the
/// int32 range it is emitted in.
fn check_polyvar_name(loc: LocIdx, name: &str) -> TypeCoreResult<()> {
    if is_valid_hash_number(name) && !int32_literal_fits_ocaml(name) {
        return Err(TypeCoreError::PolyvarLiteralOverflow { loc });
    }
    Ok(())
}

pub(crate) fn int32_literal_fits_ocaml(s: &str) -> bool {
    let stripped: String = s.chars().filter(|c| *c != '_').collect();
    let digits = stripped.as_str();
    let (negative, digits) = if let Some(rest) = digits.strip_prefix('-') {
        (true, rest)
    } else if let Some(rest) = digits.strip_prefix('+') {
        (false, rest)
    } else {
        (false, digits)
    };
    let (base, digits) = if let Some(rest) = digits
        .strip_prefix("0x")
        .or_else(|| digits.strip_prefix("0X"))
    {
        (16, rest)
    } else if let Some(rest) = digits
        .strip_prefix("0o")
        .or_else(|| digits.strip_prefix("0O"))
    {
        (8, rest)
    } else if let Some(rest) = digits
        .strip_prefix("0b")
        .or_else(|| digits.strip_prefix("0B"))
    {
        (2, rest)
    } else {
        (10, digits)
    };
    if digits.is_empty() {
        return false;
    }
    let Ok(value) = u128::from_str_radix(digits, base) else {
        return false;
    };
    let max = if base == 10 {
        if negative {
            2_147_483_648u128
        } else {
            2_147_483_647u128
        }
    } else {
        u32::MAX as u128
    };
    value <= max
}

/// Convert a parsed constant to a typed constant.
pub fn convert_constant(
    cst: &crate::parser::ast::Constant,
    loc: LocIdx,
    arena: &ParseArena,
) -> TypeCoreResult<Constant> {
    use crate::parser::ast::Constant as ParsedConstant;

    match cst {
        ParsedConstant::Integer(_, None | Some('l')) => {
            let digits = cst.integer_digits().expect("machine integer");
            // Parse integer literal, handling underscores and 0x/0o/0b prefixes.
            // OCaml's native int is 63-bit on 64-bit systems. We parse as i64
            // and simulate 63-bit wrapping to match OCaml's int_of_string
            // behavior. After that host-dependent parsing, pattern grouping and
            // intervals must see Lambda's int32 value (`Int32.to_int
            // (Int32.of_int value)`), so -0xFFFF_FFFF and 1 are the same key.
            // This does not change overflow diagnostics.
            match parse_int_literal(arena.get_string(digits)) {
                Some(n) => Ok(Constant::Int(i64::from(wrap_to_ocaml_int(n) as i32))),
                None => Err(TypeCoreError::LiteralOverflow {
                    loc,
                    ty: "int".to_string(),
                }),
            }
        }
        ParsedConstant::Integer(s, Some('n')) => {
            let (sign, digits) = parse_bigint_literal(arena.get_string(*s));
            Ok(Constant::BigInt(sign, digits))
        }
        ParsedConstant::Integer(i, Some(c)) => Err(TypeCoreError::UnknownLiteral {
            loc,
            literal: arena.get_string(*i).to_string(),
            modifier: *c,
        }),
        ParsedConstant::Char { semantic, .. } => Ok(Constant::Char(*semantic)),
        ParsedConstant::String(payload) => {
            Ok(Constant::String(payload.semantic(arena).to_string()))
        }
        ParsedConstant::Float(f, None) => Ok(Constant::Float(arena.get_string(*f).to_string())),
        ParsedConstant::Float(f, Some(c)) => Err(TypeCoreError::UnknownLiteral {
            loc,
            literal: arena.get_string(*f).to_string(),
            modifier: *c,
        }),
    }
}

