// Core Type Translation
// ============================================================================

/// Convert a parser ArgLabel to a types ArgLabel (for TypeContext methods).
fn convert_arg_label_for_ctx(
    lbl: &crate::parser::ast::ArgLabel,
    arena: &ParseArena,
    ctx: &TypeContext,
) -> crate::types::ArgLabel {
    match lbl {
        crate::parser::ast::ArgLabel::Nolabel => crate::types::ArgLabel::Nolabel,
        crate::parser::ast::ArgLabel::Labelled(s) => crate::types::ArgLabel::labelled(
            arena.get_string(s.txt).to_string(),
            ctx.intern_ast_loc(arena, s.loc),
        ),
        crate::parser::ast::ArgLabel::Optional(s) => crate::types::ArgLabel::optional(
            arena.get_string(s.txt).to_string(),
            ctx.intern_ast_loc(arena, s.loc),
        ),
    }
}

fn alias_type_mismatch_trace(
    err: TypeError,
    inner_ty: TypeExprRef,
    alias_ty: TypeExprRef,
) -> Vec<(TypeExprRef, TypeExprRef)> {
    match err {
        TypeError::Unify(trace) => trace
            .into_iter()
            .map(|(left, right)| (right, left))
            .collect(),
        _ => vec![(inner_ty, alias_ty)],
    }
}

fn is_incomplete_type_constructor_path(env: &Env, path: &Path) -> bool {
    let PathView::Pident(id) = path.view() else {
        return false;
    };
    if id.stamp() == 0 || id.is_persistent() {
        return false;
    }
    let Ok(env_decl) = env.find_type_by_ident(id) else {
        return false;
    };
    matches!(env_decl.type_kind, crate::types::TypeKind::TypeAbstract)
        && env_decl.type_manifest.is_none()
        && env_decl
            .type_path
            .as_ref()
            .is_some_and(|decl_path| decl_path.same(path))
}

/// Translate a parsed CoreType to a TypedCoreType and its corresponding TypeExprRef.
///
/// This function converts the surface syntax type annotations into the internal
/// type representation used by the type checker.
pub fn transl_type(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    styp: &crate::parser::ast::CoreType,
) -> TypeCoreResult<(crate::types::typedtree::TypedCoreType, TypeExprRef)> {
    // `Typetexp.transl_simple_type` always runs `globalize_used_variables`
    // (typetexp.ml:659-696): new variables become global-level variables.
    transl_type_with_options(tctx, env, styp, true, false)
}

pub(crate) fn transl_type_fixed(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    styp: &crate::parser::ast::CoreType,
) -> TypeCoreResult<(crate::types::typedtree::TypedCoreType, TypeExprRef)> {
    transl_type_with_options(tctx, env, styp, true, true)
}

/// Run the deferred unifications of `Typetexp.globalize_used_variables`'s
/// force closure (typetexp.ml:682-688). `forces` is in registration order;
/// OCaml prepends each entry (and each pattern's closure to `pattern_force`),
/// so they run last-registered first.
pub(crate) fn run_globalize_forces(
    tctx: &mut TypeCheckContext<'_>,
    forces: Vec<GlobalizeForce>,
) -> TypeCoreResult<()> {
    for (loc, t1, t2) in forces.into_iter().rev() {
        if let Err(err) = crate::types::unify(tctx.type_ctx, &mut tctx.unify_state, t1, t2) {
            let trace = match err {
                TypeError::Unify(trace) => trace,
                _ => vec![(t1, t2)],
            };
            return Err(TypeCoreError::TypeMismatch { loc, trace });
        }
    }
    Ok(())
}

/// Translate a type with delayed globalization (matching OCaml's
/// transl_simple_type_delayed). When `globalize` is true, we route used
/// variables through fresh global variables before linking them in
/// `type_variables`; this matches typetexp's delayed force path.
pub fn transl_type_delayed(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    styp: &crate::parser::ast::CoreType,
    globalize: bool,
) -> TypeCoreResult<(
    crate::types::typedtree::TypedCoreType,
    TypeExprRef,
    Vec<GlobalizeForce>,
)> {
    transl_type_globalized(tctx, env, styp, globalize, false)
}

/// `Typetexp.transl_simple_type` (typetexp.ml:690-696): translate, then run
/// the `globalize_used_variables` force immediately.
fn transl_type_with_options(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    styp: &crate::parser::ast::CoreType,
    globalize: bool,
    fixed_type_variables: bool,
) -> TypeCoreResult<(crate::types::typedtree::TypedCoreType, TypeExprRef)> {
    let (typed, ty, forces) =
        transl_type_globalized(tctx, env, styp, globalize, fixed_type_variables)?;
    run_globalize_forces(tctx, forces)?;
    Ok((typed, ty))
}

fn transl_type_globalized(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    styp: &crate::parser::ast::CoreType,
    globalize: bool,
    fixed_type_variables: bool,
) -> TypeCoreResult<(
    crate::types::typedtree::TypedCoreType,
    TypeExprRef,
    Vec<GlobalizeForce>,
)> {
    // Reset used_variables for each top-level type translation (matches OCaml's transl_simple_type)
    tctx.used_variables.clear();
    tctx.used_variable_locs.clear();
    tctx.univars.clear();
    let old_fixed_type_variables = tctx.fixed_type_variables;
    tctx.fixed_type_variables = fixed_type_variables;
    let translated = transl_type_inner(tctx, env, styp);
    tctx.fixed_type_variables = old_fixed_type_variables;
    let translated = translated?;

    // Match OCaml typetexp `globalize_used_variables`: link variables seen in
    // this type expression back to declaration-level variables and register
    // new names for later constraints in the same typing scope.
    let mut forces: Vec<GlobalizeForce> = Vec::new();
    if !tctx.used_variables.is_empty() {
        // OCaml iterates the `used_variables` Tbl (a map ordered by name).
        let mut used_vars: Vec<(String, TypeExprRef)> = tctx
            .used_variables
            .iter()
            .map(|(name, ty)| (name.clone(), *ty))
            .collect();
        used_vars.sort_by(|(a, _), (b, _)| a.cmp(b));
        for (name, used_ty) in used_vars {
            let ctx = tctx.type_ctx;
            let var_loc = tctx
                .used_variable_locs
                .get(&name)
                .copied()
                .unwrap_or(styp.ptyp_loc);
            if globalize {
                // OCaml typetexp.ml:659-681 globalize_used_variables:
                //   v = new_global_var (); unify v used_ty under a snapshot
                //   (backtracked and skipped on failure); the unification of
                //   v with the table binding (or a fresh v2) is deferred to
                //   the returned force.
                let lowered_ty = ctx.new_global_var(None);
                let snapshot = ctx.snapshot_type_state();
                if crate::types::unify(ctx, &mut tctx.unify_state, lowered_ty, used_ty).is_err() {
                    ctx.restore_type_state(snapshot);
                    continue;
                }
                drop(snapshot);
                if let Some(bound_ty) = tctx.type_variables.get(&name).copied() {
                    forces.push((var_loc, lowered_ty, bound_ty));
                } else {
                    // OCaml typetexp.ml:675-676: under the Fixed policy an
                    // undeclared variable that is still a Tvar is unbound.
                    if fixed_type_variables
                        && matches!(&*ctx.borrow_desc(ctx.repr(used_ty)), TypeDesc::Tvar(..))
                    {
                        let loc = tctx
                            .used_variable_locs
                            .get(&name)
                            .copied()
                            .unwrap_or(styp.ptyp_loc);
                        tctx.used_variables.clear();
                        tctx.used_variable_locs.clear();
                        tctx.univars.clear();
                        return Err(TypeCoreError::UnboundTypeVariable {
                            loc,
                            name: format!("'{name}"),
                        });
                    }
                    let bound_ty = ctx.new_global_var(None);
                    forces.push((var_loc, lowered_ty, bound_ty));
                    tctx.type_variables.insert(name, bound_ty);
                }
            } else if let Some(bound_ty) = tctx.type_variables.get(&name).copied() {
                forces.push((var_loc, used_ty, bound_ty));
            } else {
                // OCaml typetexp.ml:675-676 (Fixed policy).
                if fixed_type_variables
                    && matches!(&*ctx.borrow_desc(ctx.repr(used_ty)), TypeDesc::Tvar(..))
                {
                    let loc = tctx
                        .used_variable_locs
                        .get(&name)
                        .copied()
                        .unwrap_or(styp.ptyp_loc);
                    tctx.used_variables.clear();
                    tctx.used_variable_locs.clear();
                    tctx.univars.clear();
                    return Err(TypeCoreError::UnboundTypeVariable {
                        loc,
                        name: format!("'{name}"),
                    });
                }
                tctx.type_variables.insert(name, used_ty);
            }
        }
    }

    tctx.used_variables.clear();
    tctx.used_variable_locs.clear();
    tctx.univars.clear();
    Ok((translated.0, translated.1, forces))
}

fn path_from_longident_persistent(lid: &Longident, arena: &ParseArena) -> Path {
    match lid {
        Longident::Lident(name_idx) => {
            let name = arena.get_string(*name_idx);
            crate::types::predef::find_predef_path(name)
                .unwrap_or_else(|| Path::pident(Ident::create_persistent(name)))
        }
        Longident::Ldot(prefix, name_idx) => {
            let prefix_path = path_from_longident_persistent(prefix, arena);
            Path::pdot(prefix_path, arena.get_string(*name_idx))
        }
        Longident::Lapply(functor, arg) => {
            let funct = path_from_longident_persistent(functor, arena);
            let arg = path_from_longident_persistent(arg, arena);
            Path::papply(funct, arg)
        }
    }
}

pub(crate) fn resolve_type_constructor_path(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    lid: &Longident,
    loc: Option<LocIdx>,
) -> (Path, Option<Arc<crate::types::decl::TypeDeclaration>>) {
    // `Env.lookup_type` (env.ml:1062-1073) marks the source name.
    mark_open_lid_use(
        tctx.type_ctx,
        env,
        tctx.arena,
        lid,
        crate::types::env::OpenLookupKind::Type,
        loc,
    );
    match lid {
        Longident::Lident(name_idx) => {
            let name = tctx.arena.get_string(*name_idx);
            match env.find_type_arc_with_path(tctx.arena.name(*name_idx)) {
                Ok((path, decl)) => (path, Some(Arc::clone(decl))),
                Err(_) => {
                    let path = crate::types::predef::find_predef_path(name)
                        .unwrap_or_else(|| Path::pident(Ident::create_persistent(name)));
                    (path, None)
                }
            }
        }
        Longident::Ldot(prefix, name_idx) => {
            let type_name = tctx.arena.get_string(*name_idx);

            // Match OCaml typetexp.ml find_component:
            // `Longident.Ldot (Longident.Lident "*predef*", s)` is looked up as
            // plain `Lident s` in the initial safe environment.
            if let Longident::Lident(prefix_idx) = prefix.as_ref() {
                if tctx.arena.get_string(*prefix_idx) == "*predef*" {
                    let predef_path = crate::types::predef::find_predef_path(type_name)
                        .unwrap_or_else(|| Path::pident(Ident::create_persistent(type_name)));
                    let predef_decl = env.lookup_type(&predef_path).ok().cloned().map(Arc::new);
                    return (predef_path, predef_decl);
                }
            }

            // OCaml compiler/ml/typetexp.ml:116-123 dispatches constructors
            // through Env.lookup_type; its Ldot case in
            // compiler/ml/env.ml:1091-1099 resolves the parent module
            // descriptor and reads the type table from that component view.
            // env.ml:1091-1099: `Pdot (p, s, pos)` around the path
            // `lookup_module_descr` returns for the prefix.
            if let Some(Some((mod_path, decl))) = with_module_descr_for_lid(
                prefix,
                tctx.arena,
                env,
                &mut tctx.persistent_env,
                tctx.type_ctx,
                |lookup_path, components| {
                    let module_path = *components.access_path();
                    if let Some((_, _, decl)) = tctx.type_ctx.find_resolved_module_type(
                        env.scope_id(),
                        &module_path,
                        type_name,
                    ) {
                        return Some((*lookup_path, decl));
                    }
                    components.lookup_type(type_name).map(|(id, decl)| {
                        let decl = decl.clone();
                        tctx.type_ctx.register_resolved_module_type(
                            env.scope_id(),
                            &module_path,
                            type_name,
                            module_path,
                            *id,
                            decl.clone(),
                        );
                        (*lookup_path, decl)
                    })
                },
            ) {
                let path = tctx.type_ctx.create_ast_dotted(
                    tctx.arena,
                    mod_path,
                    *name_idx,
                    crate::types::path::NOPOS,
                );
                return (path, Some(decl));
            }
            if let Some(module_path) = env.resolve_module_access_path_for_lid(
                prefix,
                tctx.arena,
                &mut tctx.persistent_env,
                tctx.type_ctx,
            ) {
                if let Some((resolved_module_path, _, decl)) = lookup_type_in_resolved_path(
                    &module_path,
                    type_name,
                    env,
                    &mut tctx.persistent_env,
                    tctx.type_ctx,
                ) {
                    // OCaml typetexp.ml:116-123 dispatches constructors through
                    // Env.lookup_type, whose Ldot case in env.ml:1091-1099 looks
                    // up the type table after resolving module components.
                    return (
                        Path::pdot(resolved_module_path, type_name.to_string()),
                        Some(decl),
                    );
                }
            }
            if let Some(mod_path) = env.resolve_module_access_path_for_lid(
                prefix,
                tctx.arena,
                &mut tctx.persistent_env,
                tctx.type_ctx,
            ) {
                return (Path::pdot(mod_path, type_name.to_string()), None);
            }
            (path_from_longident_persistent(lid, tctx.arena), None)
        }
        Longident::Lapply(_, _) => (path_from_longident_persistent(lid, tctx.arena), None),
    }
}

fn module_alias_error_for_lid(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Longident,
) -> Option<TypeCoreError> {
    let md = module_decl_for_lid_without_scraping(tctx, env, lid)?;
    if let crate::types::decl::ModuleType::MtyAlias(_, alias_path) = &md.md_type {
        // typetexp.ml:77-81: `Env.scrape_alias` (env.ml:1396-1406) follows the
        // alias with `find_module`; only an alias whose target cannot be found
        // is left as `Mty_alias` and reported.
        if crate::types::typemod::scrape_alias_module_type(
            &md.md_type,
            env,
            &mut tctx.persistent_env,
            tctx.type_ctx,
        )
        .is_some()
        {
            return None;
        }
        Some(TypeCoreError::CannotScrapeAlias {
            loc,
            lid: lid.clone(),
            path: **alias_path,
        })
    } else {
        None
    }
}

fn module_decl_for_lid_without_scraping(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    lid: &Longident,
) -> Option<crate::types::decl::ModuleDeclaration> {
    match lid {
        Longident::Lident(name_idx) => {
            let name = tctx.arena.get_string(*name_idx);
            env.find_module(name).ok().cloned()
        }
        Longident::Ldot(prefix, child_idx) => {
            let parent_path = env.resolve_module_access_path_for_lid(
                prefix,
                tctx.arena,
                &mut tctx.persistent_env,
                tctx.type_ctx,
            )?;
            let child_name = tctx.arena.get_string(*child_idx);
            lookup_module_in_resolved_path(
                &parent_path,
                child_name,
                env,
                &mut tctx.persistent_env,
                tctx.type_ctx,
            )
            .map(|(_, _, md)| md)
        }
        Longident::Lapply(_, _) => None,
    }
}

fn cannot_scrape_alias_type_constructor_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Longident,
) -> Option<TypeCoreError> {
    // OCaml typetexp.ml `narrow_unbound_lid_error` reports
    // Cannot_scrape_alias when the module prefix exists only as an alias to a
    // missing module, instead of falling through to Unbound_type_constructor.
    match lid {
        Longident::Ldot(prefix, _) => module_alias_error_for_lid(tctx, env, loc, prefix),
        Longident::Lapply(functor, arg) => module_alias_error_for_lid(tctx, env, loc, functor)
            .or_else(|| module_alias_error_for_lid(tctx, env, loc, arg)),
        Longident::Lident(_) => None,
    }
}

/// Inner function for type translation.
fn transl_type_inner(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    styp: &crate::parser::ast::CoreType,
) -> TypeCoreResult<(crate::types::typedtree::TypedCoreType, TypeExprRef)> {
    use crate::parser::ast::CoreTypeDesc as CTD;
    use crate::types::typedtree::{TypedCoreType, TypedCoreTypeDesc};

    let ctx = tctx.type_ctx;
    let loc = styp.ptyp_loc;

    match &styp.ptyp_desc {
        CTD::Ptyp_any => {
            if tctx.fixed_type_variables {
                return Err(TypeCoreError::UnboundTypeVariable {
                    loc,
                    name: "_".to_string(),
                });
            }
            // Wildcard type: create a fresh type variable
            let ty = ctx.new_var(None);
            let ctyp = TypedCoreType {
                ctyp_desc: TypedCoreTypeDesc::Ttyp_var(None),
                ctyp_type: ty,
                ctyp_env: EnvRef(0),
                ctyp_loc: loc,
                ctyp_attributes: styp.ptyp_attributes.clone(),
            };
            Ok((ctyp, ty))
        }

        CTD::Ptyp_var(name) => {
            // Type variable: 'a
            // Ptyp_var is ONLY for type variables (e.g., 'a in ReScript).
            // Locally abstract types (type a) are handled by Ptyp_constr,
            // not Ptyp_var. OCaml's typetexp only looks up type variables
            // (used_variables/TyVarEnv), not the type environment, for Ptyp_var.
            let name_str = tctx.arena.get_string(*name).to_string();
            if name_str.starts_with('_') {
                return Err(TypeCoreError::InvalidVariableName {
                    loc,
                    name: format!("'{name_str}"),
                });
            }
            let ty = if let Some((_, existing)) =
                tctx.univars.iter().find(|(name, _)| name == &name_str)
            {
                crate::types::instance(ctx, *existing)
            } else if let Some(&existing) = tctx.used_variables.get(&name_str) {
                crate::types::instance(ctx, existing)
            } else {
                let v = ctx.new_var(Some(crate::name::Name::new(&name_str)));
                tctx.used_variables.insert(name_str.clone(), v);
                tctx.used_variable_locs.insert(name_str.clone(), loc);
                v
            };
            let ctyp = TypedCoreType {
                ctyp_desc: TypedCoreTypeDesc::Ttyp_var(Some(name_str)),
                ctyp_type: ty,
                ctyp_env: EnvRef(0),
                ctyp_loc: loc,
                ctyp_attributes: styp.ptyp_attributes.clone(),
            };
            Ok((ctyp, ty))
        }

        CTD::Ptyp_arrow(inner) => {
            let (arg, ret_idx, arity) = &**inner;
            let source_args = tctx.arena.nary_arrow_args(arg, *arity).into_owned();
            let mut typed_args = Vec::with_capacity(source_args.len());
            let mut type_args = Vec::with_capacity(source_args.len());
            for source_arg in source_args {
                if let Some(fixed) = &source_arg.fixed {
                    return Err(TypeCoreError::FixedArgumentOutsideExternal { loc: fixed.loc });
                }
                let (typed, mut typ) =
                    transl_type_inner(tctx, env, tctx.arena.get_core_type(source_arg.typ))?;
                if source_arg.lbl.is_optional() {
                    typ = ctx.new_predef_constr(crate::types::predef::path_option(), vec![typ]);
                }
                let label = convert_arg_label_for_ctx(&source_arg.lbl, tctx.arena, tctx.type_ctx);
                type_args.push(TypeArg::new(label.clone(), typ));
                typed_args.push(ArrowArg {
                    attrs: source_arg.attrs,
                    lbl: label,
                    typ: tctx.typed.push_core_type(typed),
                });
            }
            let (typed_ret, ret) =
                transl_type_inner(tctx, env, tctx.arena.get_core_type(*ret_idx))?;
            let arrow = ctx.new_type(TypeDesc::Tarrow {
                args: ctx.new_type_args(&type_args),
                ret,
            });
            Ok((
                TypedCoreType {
                    ctyp_desc: TypedCoreTypeDesc::Ttyp_arrow(
                        typed_args,
                        tctx.typed.push_core_type(typed_ret),
                    ),
                    ctyp_type: arrow,
                    ctyp_env: EnvRef(0),
                    ctyp_loc: loc,
                    ctyp_attributes: styp.ptyp_attributes.clone(),
                },
                arrow,
            ))
        }

        CTD::Ptyp_tuple(types) => {
            // Tuple type: (T1, T2, ..., Tn)
            let mut typed_types = Vec::new();
            let mut type_refs = Vec::new();

            for t in tctx.arena.type_list(*types).iter() {
                let (ctyp, ty) = transl_type_inner(tctx, env, tctx.arena.get_core_type(*t))?;
                typed_types.push(ctyp);
                type_refs.push(ty);
            }

            let tuple_ty = ctx.new_tuple(type_refs);

            let ctyp = TypedCoreType {
                ctyp_desc: TypedCoreTypeDesc::Ttyp_tuple(tctx.typed.push_core_types(typed_types)),
                ctyp_type: tuple_ty,
                ctyp_env: EnvRef(0),
                ctyp_loc: loc,
                ctyp_attributes: styp.ptyp_attributes.clone(),
            };
            Ok((ctyp, tuple_ty))
        }

        CTD::Ptyp_constr(inner) => {
            let (ref lid, ref args) = *inner;
            // Type constructor: int, string, list<'a>, etc.
            let longident = tctx.arena.get_longident(lid.txt);

            let (path, decl) = find_type_for_lid(tctx, env, lid.loc, longident)?;
            note_type_use(tctx, lid.loc, &path, &decl)?;

            let mut parsed_args: Vec<_> = tctx
                .arena
                .type_list(*args)
                .iter()
                .map(|arg| tctx.arena.get_core_type(*arg).clone())
                .collect();
            // Match OCaml Typetexp: `t<_>` for arity>1 expands `_` to all params.
            if parsed_args.len() == 1
                && matches!(&parsed_args[0].ptyp_desc, CTD::Ptyp_any)
                && decl.type_arity > 1
            {
                parsed_args = vec![parsed_args[0].clone(); decl.type_arity as usize];
            }
            if parsed_args.len() != decl.type_arity as usize {
                return Err(TypeCoreError::TypeArityMismatch {
                    loc,
                    lid: longident.clone(),
                    expected: decl.type_arity as usize,
                    provided: parsed_args.len(),
                });
            }

            let mut typed_args = Vec::new();
            let mut arg_refs = Vec::new();

            for arg in &parsed_args {
                let (ctyp, ty) = transl_type_inner(tctx, env, arg)?;
                typed_args.push(ctyp);
                arg_refs.push(ty);
            }

            // Match OCaml Typetexp.transl_type_aux Ptyp_constr:
            // instantiate declared type parameters and unify them with the
            // translated argument types before building the constructor type.
            // OCaml uses `unify_var` when there is no manifest (or a generic
            // manifest) and `unify` otherwise; preserve that distinction.
            let use_unify_var = match decl.type_manifest {
                None => true,
                Some(manifest) => {
                    let manifest = ctx.repr(manifest);
                    ctx.get_level(manifest) == crate::types::type_expr::GENERIC_LEVEL
                }
            };
            let params = crate::types::ctype::instance_list(ctx, &decl.type_params);
            for ((param_ty, arg_ty), arg) in
                params.iter().zip(arg_refs.iter()).zip(parsed_args.iter())
            {
                let result = if use_unify_var {
                    crate::types::ctype::unify_var(ctx, &mut tctx.unify_state, *param_ty, *arg_ty)
                } else {
                    crate::types::unify(ctx, &mut tctx.unify_state, *param_ty, *arg_ty)
                };
                if let Err(err) = result {
                    let trace = match err {
                        TypeError::Unify(trace) => trace
                            .into_iter()
                            .map(|(left, right)| (right, left))
                            .collect(),
                        _ => vec![(*arg_ty, *param_ty)],
                    };
                    return Err(TypeCoreError::TypeMismatch {
                        loc: arg.ptyp_loc,
                        trace,
                    });
                }
            }

            let constr_ty = ctx.new_constr(path, arg_refs);
            // typetexp.ml:369-371: `Ctype.enforce_constraints env constr`.
            if let Err(err) =
                crate::types::ctype::try_enforce_constraints(ctx, env, constr_ty, &decl)
            {
                return Err(TypeCoreError::TypeMismatch {
                    loc,
                    trace: match err {
                        TypeError::Unify(trace) => trace,
                        _ => vec![],
                    },
                });
            }

            let ctyp = TypedCoreType {
                ctyp_desc: TypedCoreTypeDesc::Ttyp_constr(
                    path,
                    *lid,
                    tctx.typed.push_core_types(typed_args),
                ),
                ctyp_type: constr_ty,
                ctyp_env: EnvRef(0),
                ctyp_loc: loc,
                ctyp_attributes: styp.ptyp_attributes.clone(),
            };
            Ok((ctyp, constr_ty))
        }

        CTD::Ptyp_alias(inner) => {
            let (ref inner_idx, ref name) = **inner;
            let name_str = name.to_string();
            let inner = tctx.arena.get_core_type(*inner_idx);

            // Match OCaml Typetexp.transl_type_aux Ptyp_alias:
            // - reuse a Ptyp_poly universal directly, without instantiation
            // - reuse an existing alias binding via `instance` when present
            // - otherwise register a fresh alias in used_variables *before*
            //   translating the inner type, then instantiate and name its proxy.
            let existing_univar = tctx
                .univars
                .iter()
                .find(|(name, _)| name == &name_str)
                .map(|(_, ty)| *ty);
            let existing_alias = tctx.used_variables.get(&name_str).copied();

            let (inner_ctyp, alias_ty) = if let Some(univar_ty) = existing_univar {
                let (inner_ctyp, inner_ty) = transl_type_inner(tctx, env, inner)?;
                crate::types::ctype::unify_var(ctx, &mut tctx.unify_state, univar_ty, inner_ty)
                    .map_err(|err| TypeCoreError::AliasTypeMismatch {
                        loc,
                        trace: alias_type_mismatch_trace(err, inner_ty, univar_ty),
                    })?;
                (inner_ctyp, inner_ty)
            } else if let Some(existing_alias) = existing_alias {
                let alias_ty = crate::types::instance(ctx, existing_alias);
                let (inner_ctyp, inner_ty) = transl_type_inner(tctx, env, inner)?;
                crate::types::ctype::unify_var(ctx, &mut tctx.unify_state, alias_ty, inner_ty)
                    .map_err(|err| TypeCoreError::AliasTypeMismatch {
                        loc,
                        trace: alias_type_mismatch_trace(err, inner_ty, alias_ty),
                    })?;
                (inner_ctyp, inner_ty)
            } else {
                let alias_ty = ctx.new_var(None);
                tctx.used_variables.insert(name_str.clone(), alias_ty);
                tctx.used_variable_locs.insert(name_str.clone(), loc);

                let (inner_ctyp, inner_ty) = transl_type_inner(tctx, env, inner)?;

                // Keep compile coverage for recursive self-alias object types
                // (for example `type x = {...} as 'self`) until unify_var-style
                // recursive alias handling is fully ported.
                if crate::types::occurs(ctx, alias_ty, inner_ty) {
                    tctx.used_variables.remove(&name_str);
                    let fallback_alias_ty = ctx.new_var(Some(crate::name::Name::new(&name_str)));
                    crate::types::unify(ctx, &mut tctx.unify_state, fallback_alias_ty, inner_ty)
                        .map_err(|_| TypeCoreError::PatternTypeClash {
                            loc: Some(loc),
                            trace: vec![(fallback_alias_ty, inner_ty)],
                            env: tctx
                                .unify_state
                                .env()
                                .map(|env| tctx.type_ctx.store_typed_env(env)),
                        })?;
                    (inner_ctyp, inner_ty)
                } else {
                    crate::types::ctype::unify_var(ctx, &mut tctx.unify_state, alias_ty, inner_ty)
                        .map_err(|err| TypeCoreError::AliasTypeMismatch {
                            loc,
                            trace: alias_type_mismatch_trace(err, inner_ty, alias_ty),
                        })?;

                    let instantiated = crate::types::instance(ctx, alias_ty);
                    let proxy = crate::types::btype::proxy(ctx, instantiated);
                    let rename_desc = {
                        let proxy_desc = ctx.get_desc(proxy);
                        match &*proxy_desc {
                            TypeDesc::Tvar(None) => {
                                Some(TypeDesc::Tvar(
                                    Some(name_str.as_str().into())))
                            }
                            TypeDesc::Tunivar(None) => {
                                Some(TypeDesc::Tunivar(Some(name_str.as_str().into())))
                            }
                            _ => None,
                        }
                    };
                    if let Some(desc) = rename_desc {
                        ctx.set_desc(proxy, desc);
                    }
                    (inner_ctyp, instantiated)
                }
            };

            let ctyp = TypedCoreType {
                ctyp_desc: TypedCoreTypeDesc::Ttyp_alias(
                    tctx.typed.push_core_type(inner_ctyp),
                    name_str,
                ),
                ctyp_type: alias_ty,
                ctyp_env: EnvRef(0),
                ctyp_loc: loc,
                ctyp_attributes: styp.ptyp_attributes.clone(),
            };
            Ok((ctyp, alias_ty))
        }

        CTD::Ptyp_poly(inner) => {
            let (ref vars, ref body_idx) = **inner;
            // Polymorphic type: 'a 'b. T
            // OCaml typetexp.ml Ptyp_poly: creates univars, translates body,
            // generalizes, then converts Tvar→Tunivar for bound variables.
            let var_names: Vec<String> = vars
                .iter()
                .map(|v| tctx.arena.get_string(v.txt).to_string())
                .collect();

            ctx.begin_def();

            // Create type variables for each bound variable and push them onto
            // the separate universal-variable stack.
            // OCaml: new_univars = List.map (fun name -> (name, newvar ~name ())) vars
            let new_univars: Vec<(String, TypeExprRef)> = var_names
                .iter()
                .map(|name| {
                    let v = ctx.new_var(Some(crate::name::Name::new(name)));
                    (name.clone(), v)
                })
                .collect();

            // Save old univar state and prepend new ones
            // OCaml: univars := new_univars @ !univars
            let old_univars = tctx.univars.clone();
            tctx.univars = new_univars.clone();
            tctx.univars.extend(old_univars.iter().cloned());

            let body = tctx.arena.get_core_type(*body_idx);
            let (body_ctyp, body_ty) = transl_type_inner(tctx, env, body)?;

            // OCaml: univars := old_univars
            tctx.univars = old_univars;

            ctx.end_def();
            crate::types::ctype::generalize(ctx, body_ty);

            // OCaml: for each poly variable that deeply occurs in the body and is
            // at generic level, change Tvar→Tunivar (universalize)
            let mut ty_list = Vec::new();
            for (name, ty1) in &new_univars {
                let v = crate::types::btype::proxy(ctx, *ty1);
                if crate::types::ctype::deep_occur(ctx, v, body_ty) {
                    // Extract the name and check level before calling set_desc
                    // to avoid RefCell borrow conflict
                    let uni_name = {
                        let desc = ctx.get_desc(v);
                        match &*desc {
                            TypeDesc::Tvar(name)
                                if ctx.get_level(v) == crate::types::type_expr::GENERIC_LEVEL =>
                            {
                                Some(*name)
                            }
                            _ => None,
                        }
                    };
                    if let Some(name) = uni_name {
                        ctx.set_desc(
                            v,
                            TypeDesc::Tunivar(name),
                        );
                        ty_list.push(v);
                    } else {
                        return Err(TypeCoreError::CannotQuantify {
                            loc,
                            name: name.clone(),
                            ty: v,
                        });
                    }
                }
            }
            // OCaml compiler/ml/typetexp.ml:538-539 builds this node with
            // `Btype.newgenty` and immediately checks it through
            // `unify_var env (newvar ()) ty'`. The `List.rev ty_list` there
            // only restores source order after the preceding fold conses each
            // occurring variable; this Rust loop already pushes in source order.
            let poly_ty = ctx.new_generic_type(TypeDesc::Tpoly {
                body: body_ty,
                vars: ctx.new_type_list(&ty_list),
            });
            let scope_var = ctx.new_var(None);
            crate::types::ctype::unify_var(ctx, &mut tctx.unify_state, scope_var, poly_ty)
                .map_err(|_| TypeCoreError::PatternTypeClash {
                    loc: Some(loc),
                    trace: vec![(scope_var, poly_ty)],
                    env: tctx
                        .unify_state
                        .env()
                        .map(|env| tctx.type_ctx.store_typed_env(env)),
                })?;

            let ctyp = TypedCoreType {
                ctyp_desc: TypedCoreTypeDesc::Ttyp_poly(
                    var_names,
                    tctx.typed.push_core_type(body_ctyp),
                ),
                ctyp_type: poly_ty,
                ctyp_env: EnvRef(0),
                ctyp_loc: loc,
                ctyp_attributes: styp.ptyp_attributes.clone(),
            };
            Ok((ctyp, poly_ty))
        }

        CTD::Ptyp_object(inner) => {
            let (ref fields, ref closed) = **inner;
            // Object type: {. name: string, age: int }
            // Build proper Tobject(Tfield(..., Tfield(..., Tnil))) type chain
            let mut typed_fields = Vec::new();
            // Match OCaml Typetexp.transl_fields: collect unique fields in a
            // hashtable, then iterate in Hashtbl.fold order.
            /// The fields collected so far: each name's type and mutability,
            /// and the names in first-insertion order.
            #[derive(Default)]
            struct ObjectFieldTable {
                entries: HashMap<String, (TypeExprRef, crate::types::asttypes::MutableFlag)>,
                insertions: Vec<String>,
            }
            let mut field_table = ObjectFieldTable::default();

            // `add_typed_field` (typetexp.ml:571-579): skip equal types,
            // otherwise unify in the translation env.
            fn add_object_field(
                tctx: &mut TypeCheckContext<'_>,
                env: &Env,
                loc: LocIdx,
                fields: &mut ObjectFieldTable,
                field_name: String,
                field_type: TypeExprRef,
                mutability: crate::types::asttypes::MutableFlag,
            ) -> TypeCoreResult<()> {
                if let Some((existing_type, _)) = fields.entries.get(&field_name).copied() {
                    // When duplicate declarations of a field are collapsed,
                    // preserve `Mutable` if any declaration has `@set`
                    // (`Hashtbl.replace` keeps the binding's position).
                    if mutability == crate::types::asttypes::MutableFlag::Mutable {
                        fields.entries.insert(
                            field_name.clone(),
                            (existing_type, crate::types::asttypes::MutableFlag::Mutable),
                        );
                    }
                    let ctx = tctx.type_ctx;
                    if crate::types::ctype::equal(ctx, env, false, &[field_type], &[existing_type])
                    {
                        return Ok(());
                    }
                    let mut unify_state = UnifyState::new();
                    unify_state.set_env(env);
                    crate::types::unify(ctx, &mut unify_state, field_type, existing_type).map_err(
                        |_| TypeCoreError::MethodMismatch {
                            loc,
                            label: field_name,
                            actual: field_type,
                            expected: existing_type,
                        },
                    )?;
                } else {
                    fields.insertions.push(field_name.clone());
                    fields.entries.insert(field_name, (field_type, mutability));
                }
                Ok(())
            }

            // typetexp.ml `field_mutability`: `@set` with an empty payload.
            let field_mutability = |attrs: &crate::parser::ast::Attributes| {
                if attrs.iter().any(|(name, payload)| {
                    tctx.arena.get_string(name.txt) == "set"
                        && matches!(payload, crate::parser::ast::Payload::PStr(items) if items.is_empty())
                }) {
                    crate::types::asttypes::MutableFlag::Mutable
                } else {
                    crate::types::asttypes::MutableFlag::Immutable
                }
            };

            for field in fields.iter() {
                match field {
                    crate::parser::ast::ObjectField::Otag(label, attrs, field_type) => {
                        let field_ct = tctx.arena.get_core_type(*field_type);
                        // OCaml uses transl_poly_type which applies force_poly before
                        // translation: if already Ptyp_poly, translate as-is; otherwise
                        // wrap in Ptyp_poly([], t) first. We check post-translation.
                        let (inner_ctyp, inner_ty) = transl_type_inner(tctx, env, field_ct)?;

                        // Apply force_poly: if already Ttyp_poly, don't double-wrap
                        let (poly_ctyp, poly_ty) = match &inner_ctyp.ctyp_desc {
                            TypedCoreTypeDesc::Ttyp_poly(_, _) => (inner_ctyp, inner_ty),
                            _ => {
                                let poly_ty = ctx.new_poly(inner_ty, vec![]);
                                let poly_ctyp = TypedCoreType {
                                    ctyp_desc: TypedCoreTypeDesc::Ttyp_poly(
                                        vec![],
                                        tctx.typed.push_core_type(inner_ctyp),
                                    ),
                                    ctyp_type: poly_ty,
                                    ctyp_env: EnvRef(0),
                                    ctyp_loc: field_ct.ptyp_loc,
                                    ctyp_attributes: Attributes::new(),
                                };
                                (poly_ctyp, poly_ty)
                            }
                        };

                        let field_name = tctx.arena.get_string(label.txt).to_string();
                        let mutability = field_mutability(attrs);
                        add_object_field(
                            tctx,
                            env,
                            field_ct.ptyp_loc,
                            &mut field_table,
                            field_name.clone(),
                            poly_ty,
                            mutability,
                        )?;

                        typed_fields.push(crate::types::typedtree::ObjectField {
                            of_desc: crate::types::typedtree::ObjectFieldDesc::OTtag(
                                Located {
                                    txt: field_name,
                                    loc: label.loc,
                                },
                                tctx.typed.push_core_type(poly_ctyp),
                            ),
                            of_loc: label.loc,
                            of_attributes: attrs.clone(),
                        });
                    }
                    crate::parser::ast::ObjectField::Oinherit(inherit_type) => {
                        let inherit_ct = tctx.arena.get_core_type(*inherit_type);
                        let (inherit_ctyp, inherit_ty) = transl_type_inner(tctx, env, inherit_ct)?;
                        let inherit_name = {
                            let inherit_desc = ctx.get_desc(ctx.repr(inherit_ty));
                            match &*inherit_desc {
                                TypeDesc::Tconstr { path, .. } => Some(*path),
                                _ => None,
                            }
                        };

                        // Extract fields from the inherited type (OCaml's typetexp.ml lines 597-617).
                        // expand_head resolves type aliases/constructors to get the underlying object type.
                        let expanded = crate::types::ctype::expand_head(ctx, env, inherit_ty);
                        let inherited_object_fields = {
                            let expanded_desc = ctx.get_desc(expanded);
                            if let TypeDesc::Tobject { fields, .. } = &*expanded_desc {
                                let fields_desc = ctx.get_desc(ctx.repr(*fields));
                                match &*fields_desc {
                                    TypeDesc::Tfield { .. } | TypeDesc::Tnil => Some(*fields),
                                    _ => None,
                                }
                            } else {
                                None
                            }
                        };
                        if let Some(obj_fields) = inherited_object_fields {
                            if crate::types::ctype::object_row_is_structurally_open(ctx, expanded) {
                                return Err(TypeCoreError::OpenedObject {
                                    loc: inherit_ct.ptyp_loc,
                                    path: inherit_name,
                                });
                            }
                            // Walk the Tfield chain and add each field to field_entries
                            let mut current_field = obj_fields;
                            loop {
                                let fd = ctx.get_desc(ctx.repr(current_field));
                                match &*fd {
                                    TypeDesc::Tfield {
                                        name,
                                        mutability,
                                        typ,
                                        rest,
                                    } => {
                                        add_object_field(
                                            tctx,
                                            env,
                                            inherit_ct.ptyp_loc,
                                            &mut field_table,
                                            name.to_string(),
                                            *typ,
                                            ctx.mutability_repr(*mutability),
                                        )?;
                                        current_field = *rest;
                                    }
                                    TypeDesc::Tnil => break,
                                    _ => break,
                                }
                            }
                        } else {
                            if let Some(path) = inherit_name
                                && (matches!(
                                    &*ctx.borrow_desc(ctx.repr(expanded)),
                                    TypeDesc::Tvar(..)
                                ) || is_incomplete_type_constructor_path(env, &path))
                            {
                                return Err(TypeCoreError::UnboundTypeConstructorIncomplete {
                                    loc: inherit_ct.ptyp_loc,
                                    path,
                                });
                            }
                            return Err(TypeCoreError::NotAnObjectType {
                                loc: inherit_ct.ptyp_loc,
                                ty: expanded,
                            });
                        }
                        typed_fields.push(crate::types::typedtree::ObjectField {
                            of_desc: crate::types::typedtree::ObjectFieldDesc::OTinherit(
                                tctx.typed.push_core_type(inherit_ctyp),
                            ),
                            of_loc: inherit_ct.ptyp_loc,
                            of_attributes: Attributes::new(),
                        });
                    }
                }
            }

            // Build the Tfield chain terminated by Tnil (closed) or Tvar (open)
            let ty_init = match closed {
                crate::parser::ast::ClosedFlag::Closed => ctx.new_type(TypeDesc::Tnil),
                crate::parser::ast::ClosedFlag::Open => ctx.new_var(None),
            };
            let mut ordered_field_names = ocaml_hashtbl_fold_order(&field_table.insertions);
            // OCaml transl_fields uses:
            //   fields = Hashtbl.fold (fun s ty l -> (s, ty) :: l) ...
            // followed by List.fold_left building Tfield(..., acc).
            // `ocaml_hashtbl_fold_order` returns traversal order, so reverse it to
            // match the intermediate Hashtbl.fold list before the left fold.
            ordered_field_names.reverse();
            let field_entries = ordered_field_names
                .into_iter()
                .filter_map(|name| field_table.entries.remove(&name).map(|ty| (name, ty)))
                .collect::<Vec<_>>();
            // Fold fields into Tfield chain
            let fields_ty =
                field_entries
                    .iter()
                    .fold(ty_init, |rest, (name, (field_ty, mutability))| {
                        ctx.new_type(TypeDesc::Tfield {
                            name: crate::name::Name::new(name),
                            mutability: ctx.alloc_mutability(
                                crate::types::type_expr::FieldMutability::Value(*mutability),
                            ),
                            typ: *field_ty,
                            rest,
                        })
                    });
            // Wrap in Tobject
            let obj_ty = ctx.new_type(TypeDesc::Tobject { fields: fields_ty });

            let ctyp = TypedCoreType {
                ctyp_desc: TypedCoreTypeDesc::Ttyp_object(typed_fields, *closed),
                ctyp_type: obj_ty,
                ctyp_env: EnvRef(0),
                ctyp_loc: loc,
                ctyp_attributes: styp.ptyp_attributes.clone(),
            };
            Ok((ctyp, obj_ty))
        }

        CTD::Ptyp_variant(inner) => {
            let (ref rows, ref closed, ref labels) = **inner;
            // Polymorphic variant type: [> `A | `B of int ]
            let mut typed_rows = Vec::new();
            let mut row_name: Option<(Path, Vec<TypeExprRef>)> = None;
            let mut row_field_map: HashMap<
                crate::types::asttypes::Label,
                crate::types::type_expr::RowField,
            > = HashMap::new();
            let mut row_field_insertions: Vec<crate::types::asttypes::Label> = Vec::new();

            fn add_row_field(
                tctx: &mut TypeCheckContext<'_>,
                loc: LocIdx,
                row_field_map: &mut HashMap<
                    crate::types::asttypes::Label,
                    crate::types::type_expr::RowField,
                >,
                row_field_insertions: &mut Vec<crate::types::asttypes::Label>,
                label: crate::types::asttypes::Label,
                field: crate::types::type_expr::RowField,
            ) -> TypeCoreResult<()> {
                if let Some(existing_field) = row_field_map.get(&label) {
                    let ctx = tctx.type_ctx;
                    let actual = ctx.new_variant(crate::types::type_expr::RowDesc {
                        row_fields: vec![(label.clone(), field)].into(),
                        row_more: ctx.new_var(None),
                        row_closed: true,
                        row_fixed: false,
                        row_name: None,
                    });
                    let expected = ctx.new_variant(crate::types::type_expr::RowDesc {
                        row_fields: vec![(label, existing_field.clone())].into(),
                        row_more: ctx.new_var(None),
                        row_closed: true,
                        row_fixed: false,
                        row_name: None,
                    });
                    crate::types::unify(ctx, &mut tctx.unify_state, actual, expected).map_err(
                        |_| TypeCoreError::ConstructorMismatch {
                            loc,
                            actual,
                            expected,
                        },
                    )?;
                } else {
                    row_field_insertions.push(label.clone());
                    row_field_map.insert(label, field);
                }
                Ok(())
            }

            for row in rows {
                match row {
                    crate::parser::ast::RowField::Rtag(label, attrs, constant, groups) => {
                        row_name = None;
                        // typetexp.ml Rtag: a payload group of several types
                        // is checked as the tuple `Ast_helper.Typ.tuple ~loc`.
                        let args: Vec<crate::parse_arena::CoreTypeIdx> = groups
                            .iter()
                            .map(|group| match group.txt.as_slice() {
                                [arg] => *arg,
                                types => {
                                    tctx.arena
                                        .push_shared_core_type(crate::parser::ast::CoreType {
                                            ptyp_desc: crate::parser::ast::CoreTypeDesc::Ptyp_tuple(
                                                tctx.arena.push_shared_type_list(types),
                                            ),
                                            ptyp_loc: group.loc,
                                            ptyp_attributes: Attributes::new(),
                                        })
                                }
                            })
                            .collect();
                        let mut typed_args = Vec::new();
                        let mut arg_types = Vec::new();
                        for arg in &args {
                            let arg_ct = tctx.arena.get_core_type(*arg);
                            let (arg_ctyp, arg_ty) = transl_type_inner(tctx, env, arg_ct)?;
                            typed_args.push(arg_ctyp);
                            arg_types.push(arg_ty);
                        }

                        let is_reither = labels.as_ref().is_some_and(|present| {
                            !present
                                .iter()
                                .any(|present_lbl| present_lbl == label.txt.as_ref())
                        });
                        if !is_reither && (args.len() > 1 || (*constant && !args.is_empty())) {
                            return Err(TypeCoreError::PresentHasConjunction {
                                loc,
                                label: label.txt.to_string(),
                            });
                        }
                        let row_field = if is_reither {
                            crate::types::type_expr::RowField::Reither {
                                constant: *constant,
                                types: arg_types,
                                matched: false,
                                link: ctx.alloc_row_field(None),
                            }
                        } else {
                            match typed_args.first() {
                                None => crate::types::type_expr::RowField::Rpresent(None),
                                Some(first) => crate::types::type_expr::RowField::Rpresent(Some(
                                    first.ctyp_type,
                                )),
                            }
                        };
                        add_row_field(
                            tctx,
                            loc,
                            &mut row_field_map,
                            &mut row_field_insertions,
                            label.txt.to_string().into(),
                            row_field,
                        )?;

                        let typed_label = Located {
                            txt: label.txt.to_string(),
                            loc: label.loc,
                        };

                        typed_rows.push(crate::types::typedtree::RowFieldType {
                            rf_desc: crate::types::typedtree::RowFieldDesc::Rtag(
                                typed_label,
                                *constant,
                                tctx.typed.push_core_types(typed_args),
                            ),
                            rf_loc: label.loc,
                            rf_attributes: attrs.clone(),
                        });
                    }
                    crate::parser::ast::RowField::Rinherit(inherit_type) => {
                        let inherit_ct = tctx.arena.get_core_type(*inherit_type);
                        let (inherit_ctyp, inherit_ty) = transl_type_inner(tctx, env, inherit_ct)?;

                        let inherit_ty_repr = ctx.repr(inherit_ty);
                        let inherit_name = match &*ctx.get_desc(inherit_ty_repr) {
                            TypeDesc::Tconstr { path, args, .. } => {
                                Some((*path, ctx.type_list(args).to_vec()))
                            }
                            _ => None,
                        };
                        if row_field_map.is_empty() {
                            row_name = inherit_name.clone();
                        } else {
                            row_name = None;
                        }

                        let expanded = crate::types::ctype::expand_head(ctx, env, inherit_ty);
                        let inherited_fields = {
                            let expanded_desc = ctx.get_desc(expanded);
                            match &*expanded_desc {
                                TypeDesc::Tvariant(row_desc)
                                    if crate::types::btype::static_row(
                                        ctx,
                                        &ctx.row_desc(row_desc),
                                    ) =>
                                {
                                    Some(
                                        crate::types::btype::row_repr(ctx, &ctx.row_desc(row_desc))
                                            .row_fields,
                                    )
                                }
                                _ => None,
                            }
                        };
                        let Some(fields) = inherited_fields else {
                            if let Some((path, _)) = inherit_name
                                && (matches!(
                                    &*ctx.borrow_desc(ctx.repr(expanded)),
                                    TypeDesc::Tvar(..)
                                ) || is_incomplete_type_constructor_path(env, &path))
                            {
                                return Err(TypeCoreError::UnboundTypeConstructorIncomplete {
                                    loc: inherit_ct.ptyp_loc,
                                    path,
                                });
                            }
                            return Err(TypeCoreError::NotAVariant {
                                loc: inherit_ct.ptyp_loc,
                                ty: inherit_ty,
                            });
                        };
                        for (label_name, inherited_field) in fields {
                            let is_reither = labels.as_ref().is_some_and(|present| {
                                !present.iter().any(|lbl| lbl == label_name.as_str())
                            });
                            let resolved_field = if is_reither {
                                match inherited_field {
                                    crate::types::type_expr::RowField::Rpresent(Some(ty)) => {
                                        crate::types::type_expr::RowField::Reither {
                                            constant: false,
                                            types: vec![ty],
                                            matched: false,
                                            link: ctx.alloc_row_field(None),
                                        }
                                    }
                                    crate::types::type_expr::RowField::Rpresent(None) => {
                                        crate::types::type_expr::RowField::Reither {
                                            constant: true,
                                            types: vec![],
                                            matched: false,
                                            link: ctx.alloc_row_field(None),
                                        }
                                    }
                                    _ => inherited_field,
                                }
                            } else {
                                inherited_field
                            };
                            add_row_field(
                                tctx,
                                inherit_ct.ptyp_loc,
                                &mut row_field_map,
                                &mut row_field_insertions,
                                label_name,
                                resolved_field,
                            )?;
                        }
                        typed_rows.push(crate::types::typedtree::RowFieldType {
                            rf_desc: crate::types::typedtree::RowFieldDesc::Rinherit(
                                tctx.typed.push_core_type(inherit_ctyp),
                            ),
                            rf_loc: inherit_ct.ptyp_loc,
                            rf_attributes: Attributes::new(),
                        });
                    }
                }
            }

            // OCaml's Ptyp_variant uses Hashtbl.fold to collect fields,
            // which produces a hash-determined order. Match this always
            // (OCaml does not condition on attributes).
            let ordered_labels = ocaml_hashtbl_fold_order(&row_field_insertions);
            let row_fields = ordered_labels
                .into_iter()
                .filter_map(|label| row_field_map.remove(&label).map(|field| (label, field)))
                .collect::<Vec<_>>();
            if let Some(present) = labels {
                for label in present {
                    if !row_fields
                        .iter()
                        .any(|(field_label, _)| field_label.as_str() == label.as_ref())
                    {
                        return Err(TypeCoreError::PresentHasNoType {
                            loc,
                            label: label.to_string(),
                        });
                    }
                }
            }
            let row_closed = *closed == crate::parser::ast::ClosedFlag::Closed;
            let mut row = crate::types::type_expr::RowDesc {
                row_fields: row_fields.into(),
                row_more: ctx.new_var(None),
                row_closed,
                row_fixed: false,
                row_name,
            };
            // OCaml typetexp.ml:503-513: a static row ends in `Tnil`.
            if crate::types::btype::static_row(ctx, &row) {
                row.row_more = ctx.new_type(TypeDesc::Tnil);
            }
            let variant_ty = ctx.new_variant(row);

            let ctyp = TypedCoreType {
                ctyp_desc: TypedCoreTypeDesc::Ttyp_variant(
                    typed_rows,
                    *closed,
                    labels
                        .as_ref()
                        .map(|v| v.iter().map(|s| s.to_string()).collect()),
                ),
                ctyp_type: variant_ty,
                ctyp_env: EnvRef(0),
                ctyp_loc: loc,
                ctyp_attributes: styp.ptyp_attributes.clone(),
            };
            Ok((ctyp, variant_ty))
        }

        CTD::Ptyp_package(inner) => {
            let (mod_lid, constraints) = &**inner;
            // Package type: (module S with type t = T)
            // OCaml `Typetexp.transl_type` resolves the package module type
            // through `transl_modtype_longident`. Preserve the selected
            // component path here: opened namespace modules are not local
            // `Pident`s, even when their source-level name is unqualified.
            // Match OCaml Typetexp.create_package_mty (typetexp.ml:161-168),
            // which runs before the package module type is resolved
            // (typetexp.ml:548-554):
            // - sort constraints by longident
            // - reject duplicate constrained type names
            let mut sorted_constraints: Vec<_> = constraints
                .iter()
                .map(|(field_lid, field_ty)| {
                    (tctx.resolve_lid(field_lid.txt).clone(), field_lid, field_ty)
                })
                .collect();
            sorted_constraints
                .sort_by(|(left, _, _), (right, _, _)| compare_longident(tctx.arena, left, right));

            for pair in sorted_constraints.windows(2) {
                if compare_longident(tctx.arena, &pair[0].0, &pair[1].0) == Ordering::Equal {
                    return Err(TypeCoreError::MultipleConstraintsOnType {
                        loc,
                        lid: pair[0].0.clone(),
                    });
                }
            }

            let longident = tctx.resolve_lid(mod_lid.txt).clone();
            crate::types::typecore::mark_open_lid_use(
                tctx.type_ctx,
                env,
                tctx.arena,
                &longident,
                crate::types::env::OpenLookupKind::Modtype,
                Some(loc),
            );
            let pack_path = match crate::types::typemod::lookup_modtype_path_by_lid(
                &longident,
                tctx.arena,
                env,
                &mut tctx.persistent_env,
                ctx,
            ) {
                Some(path) => path,
                None => {
                    let alternatives = crate::types::typemod::unbound_modtype_alternatives(
                        &longident,
                        tctx.arena,
                        env,
                        &mut tctx.persistent_env,
                        ctx,
                    );
                    return Err(TypeCoreError::UnboundModtype {
                        loc,
                        lid: longident,
                        alternatives,
                    });
                }
            };

            // typetexp.ml:572-576: translate the module type
            // `create_package_mty true` builds, whose `with type` constraints
            // go through `merge_constraint`.
            let package_fields: Vec<_> = sorted_constraints
                .iter()
                .map(|(_, field_lid, _)| **field_lid)
                .collect();
            crate::types::typemod::transl_fake_package_modtype(
                tctx,
                env,
                tctx.arena,
                &pack_path,
                &package_fields,
                loc,
            )
            .map_err(|err| match err {
                crate::types::typemod::TypeModError::CoreError(err) => err,
                err => TypeCoreError::ModuleError(Box::new(err)),
            })?;

            let mut typed_fields = Vec::with_capacity(sorted_constraints.len());
            let mut lids = Vec::with_capacity(sorted_constraints.len());
            let mut args = Vec::with_capacity(sorted_constraints.len());
            for (_, field_lid, field_ty) in sorted_constraints {
                let (typed_field_ty, field_type_ref) =
                    transl_type_inner(tctx, env, tctx.arena.get_core_type(*field_ty))?;
                typed_fields.push((*field_lid, typed_field_ty));
                lids.push(tctx.resolve_lid(field_lid.txt).clone());
                args.push(field_type_ref);
            }

            let package_ty = ctx.new_type(TypeDesc::Tpackage {
                path: pack_path,
                lids: ctx.new_package_lids(lids),
                args: ctx.new_type_list(&args),
            });
            let ctyp = TypedCoreType {
                ctyp_desc: TypedCoreTypeDesc::Ttyp_package(crate::types::typedtree::PackageType {
                    pack_path,
                    pack_fields: typed_fields
                        .into_iter()
                        .map(|(l, ct)| (l, tctx.typed.push_core_type(ct)))
                        .collect(),
                }),
                ctyp_type: package_ty,
                ctyp_env: EnvRef(0),
                ctyp_loc: loc,
                ctyp_attributes: styp.ptyp_attributes.clone(),
            };
            Ok((ctyp, package_ty))
        }

        CTD::Ptyp_extension(extension) => Err(builtin_extension_error(tctx.arena, extension)),
    }
}

/// Reuse the newest `Lident name` in the arena, or push a fresh one.
fn existing_or_new_lident_idx(arena: &ParseArena, name: &str) -> LidentIdx {
    find_existing_lident_idx(arena, name).unwrap_or_else(|| arena.push_typecheck_lident(name))
}

/// `written_labels` (compiler/ml/typecore.ml:387-391): which labels of a
/// record with `label_count` labels a literal writes, indexed by `lbl_pos`.
fn record_written_labels(
    label_count: usize,
    written_fields: &[crate::types::typedtree::RecordField],
) -> Vec<bool> {
    let mut written = vec![false; label_count];
    for (label, _, _) in written_fields {
        written[label.lbl_pos as usize] = true;
    }
    written
}

fn find_existing_lident_idx(arena: &ParseArena, name: &str) -> Option<LidentIdx> {
    for idx in (0..arena.longident_count()).rev() {
        let lid_idx = LidentIdx(idx as u32);
        if let Longident::Lident(str_idx) = arena.get_longident(lid_idx) {
            if arena.get_string(*str_idx) == name {
                return Some(lid_idx);
            }
        }
    }
    None
}

fn push_synthetic_pat(arena: &ParseArena, pat: ParsedPattern) -> crate::parse_arena::PatIdx {
    arena.push_typecheck_pattern(pat)
}

/// typecore.ml `is_from_parmatch`: a constructor of a counter-example rebuilt
/// by `Parmatch.Conv`.
fn is_from_parmatch(arena: &ParseArena, pat: &ParsedPattern) -> bool {
    match &pat.ppat_desc {
        crate::parser::ast::PatternDesc::Ppat_construct(lid, _) => {
            match arena.get_longident(lid.txt) {
                Longident::Lident(name) => arena.get_string(*name).starts_with("#$"),
                _ => false,
            }
        }
        _ => false,
    }
}

/// typecore.ml `wrap_some`: the pattern of an optional field, `Some(pat)`.
fn wrap_some(
    arena: &ParseArena,
    pat_idx: crate::parse_arena::PatIdx,
) -> crate::parse_arena::PatIdx {
    let loc = arena.get_pat(pat_idx).ppat_loc;
    let lid = Located {
        txt: arena.predef_some_lid(),
        loc: arena.none_loc(),
    };
    push_synthetic_pat(
        arena,
        ParsedPattern {
            ppat_desc: crate::parser::ast::PatternDesc::Ppat_construct(
                lid,
                Located {
                    txt: arena.push_shared_pat_list(&[pat_idx]),
                    loc,
                },
            ),
            ppat_loc: loc,
            ppat_attributes: Attributes::new(),
        },
    )
}

/// typecore.ml `normalize_constructor_pat_args`: the parser keeps the
/// syntactic arguments; after disambiguation `C((a, b))` and `C(a, b)` are
/// equivalent, so a lone tuple spreads over a multi-argument constructor
/// and several arguments of a one-argument constructor form a tuple.
fn normalize_constructor_pat_args(
    arena: &ParseArena,
    arity: i32,
    sargs: &Located<crate::parse_arena::PatList>,
) -> Vec<crate::parse_arena::PatIdx> {
    match arena.pat_list(sargs.txt) {
        [sp] if arity > 1 => match &arena.get_pat(*sp).ppat_desc {
            crate::parser::ast::PatternDesc::Ppat_tuple(args) => arena.pat_list(*args).to_vec(),
            _ => vec![*sp],
        },
        [_, _, ..] if arity == 1 => vec![push_synthetic_pat(
            arena,
            ParsedPattern {
                ppat_desc: crate::parser::ast::PatternDesc::Ppat_tuple(sargs.txt),
                ppat_loc: sargs.loc,
                ppat_attributes: Attributes::new(),
            },
        )],
        items => items.to_vec(),
    }
}

/// typecore.ml `normalize_constructor_expr_args`.
fn normalize_constructor_expr_args(
    arena: &ParseArena,
    arity: i32,
    sargs: &Located<crate::parse_arena::ExprList>,
) -> Vec<crate::parse_arena::ExprIdx> {
    match arena.expr_list(sargs.txt) {
        [se] if arity > 1 => match &arena.get_expanded_expr(*se).pexp_desc {
            crate::parser::ast::ExpressionDesc::Pexp_tuple(args) => arena.expr_list(*args).to_vec(),
            _ => vec![*se],
        },
        [_, _, ..] if arity == 1 => vec![arena.push_shared_expr(ParsedExpression {
            pexp_desc: crate::parser::ast::ExpressionDesc::Pexp_tuple(sargs.txt),
            pexp_loc: sargs.loc,
            pexp_attributes: Attributes::new(),
        })],
        items => items.to_vec(),
    }
}

/// Build an or-pattern from a poly variant type definition.
/// Matches OCaml typecore.ml:537-609 `build_or_pat`.
///
/// Given a type like `type myvariant = [#Tag1(int) | #Tag2(bool)]`,
/// this creates a `Tpat_or(Tpat_variant("Tag1", _), Tpat_variant("Tag2", _))` pattern
/// with Reither fields in the row type.
fn build_or_pat(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Located<LidentIdx>,
) -> TypeCoreResult<(Path, Pattern, TypeExprRef)> {
    use crate::types::type_expr::{RowDesc, RowField};
    use crate::types::typedtree::RowDescRef;
    let lid_txt = tctx.resolve_lid(lid.txt).clone();

    // Step 1: Find the type declaration and get the path.
    // OCaml build_or_pat uses Typetexp.find_type followed by one fresh
    // variable per declared type parameter, even when the source pattern omits
    // the arguments (for example `#...Shadow.t` where `t` has arity 1).
    let (path, type_decl) = find_type_for_lid(tctx, env, lid.loc, &lid_txt)?;
    let ctx = tctx.type_ctx;
    let args: Vec<_> = type_decl
        .type_params
        .iter()
        .map(|_| ctx.new_var(None))
        .collect();
    let spread_ty_ref = ctx.new_constr(path, args.clone());

    // Step 2: Create fresh type variables for type params and expand to get the variant row
    // OCaml: let tyl = List.map (fun _ -> newvar()) decl.type_params
    // OCaml: let ty = expand_head env (newty (Tconstr(path, tyl, ref Mnil)))
    let expanded = crate::types::ctype::expand_head(ctx, env, spread_ty_ref);
    let expanded_desc = ctx.get_desc(expanded);
    let row0 = match &*expanded_desc {
        TypeDesc::Tvariant(row) if crate::types::btype::static_row(ctx, &ctx.row_desc(row)) => {
            crate::types::btype::row_repr(ctx, &ctx.row_desc(row))
        }
        _ => {
            return Err(TypeCoreError::NotAVariantType {
                loc: lid.loc,
                lid: lid_txt,
            });
        }
    };

    // Step 3: Build patterns and new row fields from the existing row fields
    // OCaml creates Reither fields for each Rpresent field
    let mut pats: Vec<(String, Option<Box<Pattern>>)> = Vec::new();
    let mut fields: Vec<(crate::types::asttypes::Label, RowField)> = Vec::new();

    for (label, field) in &row0.row_fields {
        match crate::types::btype::row_field_repr(ctx, field) {
            RowField::Rpresent(None) => {
                pats.push((label.to_string(), None));
                fields.push((
                    label.clone(),
                    RowField::Reither {
                        constant: true,
                        types: vec![],
                        matched: true,
                        link: ctx.alloc_row_field(None),
                    },
                ));
            }
            RowField::Rpresent(Some(ty)) => {
                let arg_pat = Pattern::new(
                    PatternDesc::Tpat_any,
                    LocIdx::none(),
                    ty,
                    tctx.type_ctx.store_typed_env(env),
                );
                pats.push((label.to_string(), Some(Box::new(arg_pat))));
                fields.push((
                    label.clone(),
                    RowField::Reither {
                        constant: false,
                        types: vec![ty],
                        matched: true,
                        link: ctx.alloc_row_field(None),
                    },
                ));
            }
            _ => {
                // Skip Reither and Rabsent fields
            }
        }
    }

    if pats.is_empty() {
        return Err(TypeCoreError::NotAVariantType { loc, lid: lid_txt });
    }

    // Step 4: Create the variant type for the patterns
    let row = RowDesc {
        row_fields: fields.into(),
        row_more: ctx.new_var(None),
        row_closed: false,
        row_fixed: false,
        row_name: Some((path, args)),
    };
    let ty = ctx.new_variant(row);

    // Step 5: Create Tpat_variant for each pattern
    // OCaml's fold_left builds pats with :: prepend, implicitly reversing them.
    // We must reverse to match OCaml's order in the or-pattern chain.
    pats.reverse();
    // typecore.ml:594: `let gloc = {loc with Location.loc_ghost = true}`.
    let ghost_loc = tctx.arena.push_typecheck_ghost_loc(loc);
    let typed_pats: Vec<Pattern> = pats
        .into_iter()
        .map(|(label, arg)| {
            Pattern::new(
                PatternDesc::Tpat_variant(
                    label,
                    arg.map(|p| tctx.typed.push_pattern(*p)),
                    RowDescRef(0),
                ),
                ghost_loc,
                ty,
                tctx.type_ctx.store_typed_env(env),
            )
        })
        .collect();

    // Step 6: Fold into Tpat_or chain
    // OCaml: List.fold_left (fun pat pat0 -> {pat_desc = Tpat_or(pat0, pat, Some row0)}) pat pats
    let mut iter = typed_pats.into_iter();
    let first = iter.next().unwrap();
    let or_pat = iter.fold(first, |acc, pat0| {
        Pattern::new(
            PatternDesc::Tpat_or(
                tctx.typed.push_pattern(pat0),
                tctx.typed.push_pattern(acc),
                None,
            ),
            ghost_loc,
            ty,
            tctx.type_ctx.store_typed_env(env),
        )
    });

    // Set the location to the original pattern location
    let result = Pattern {
        pat_loc: loc,
        ..or_pat
    };

    Ok((path, result, ty))
}

fn extract_type_from_pat_variant_spread(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    lid: &Located<LidentIdx>,
    expected_ty: TypeExprRef,
) -> TypeCoreResult<(Path, Vec<crate::types::ConstructorDeclaration>, TypeExprRef)> {
    let ctx = tctx.type_ctx;
    let lid_txt = tctx.resolve_lid(lid.txt).clone();
    let (spread_path, type_decl) = find_type_for_lid(tctx, env, lid.loc, &lid_txt)?;

    let constructors = match &type_decl.type_kind {
        crate::types::TypeKind::TypeVariant(cstrs, _) => {
            if !type_decl.type_params.is_empty() {
                return Err(TypeCoreError::TypeParamsNotSupported {
                    loc: lid.loc,
                    lid: lid_txt,
                });
            }
            cstrs.clone()
        }
        _ => {
            return Err(TypeCoreError::NotAVariantType {
                loc: lid.loc,
                lid: lid_txt,
            });
        }
    };
    let spread_ty = ctx.new_generic_constr(spread_path, vec![]);

    crate::types::ctype::subtype_now(ctx, env, spread_ty, expected_ty).map_err(|err| {
        not_subtype_error(tctx.type_ctx, env, lid.loc, err, spread_ty, expected_ty)
    })?;

    Ok((spread_path, constructors.into_vec(), spread_ty))
}

fn build_ppat_or_for_variant_spread(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pat: &ParsedPattern,
    expected_ty: TypeExprRef,
) -> TypeCoreResult<Option<(ParsedPattern, TypeExprRef)>> {
    let crate::parser::ast::PatternDesc::Ppat_variant_spread(lident) = &pat.ppat_desc else {
        return Ok(None);
    };

    let (_path, constructors, spread_ty) =
        extract_type_from_pat_variant_spread(tctx, env, lident, expected_ty)?;
    debug_assert_eq!(
        tctx.arena
            .get_string(tctx.arena.pat_from_variant_spread_attr_str()),
        PAT_FROM_VARIANT_SPREAD_ATTRIBUTE
    );
    let pat_from_variant_spread_attr = (
        Located::mknoloc(tctx.arena.pat_from_variant_spread_attr_str()),
        crate::parser::ast::Payload::PStr(Box::default()),
    );
    let mut synthetic_pattern_idxs = Vec::with_capacity(constructors.len());
    for cstr in constructors {
        // typecore.ml:655-657 builds a fresh `Longident.Lident (Ident.name c.cd_id)`.
        let cstr_lid_idx = tctx.arena.push_typecheck_lident(cstr.cd_id.name());
        let cstr_lid = Located {
            txt: cstr_lid_idx,
            loc: lident.loc,
        };
        let cstr_args = match cstr.cd_args {
            crate::types::ConstructorArguments::CstrTuple(ref args) if args.is_empty() => {
                Vec::new()
            }
            _ => vec![push_synthetic_pat(
                tctx.arena,
                ParsedPattern {
                    ppat_desc: crate::parser::ast::PatternDesc::Ppat_any,
                    ppat_loc: LocIdx::none(),
                    ppat_attributes: Attributes::new(),
                },
            )],
        };
        let parsed = ParsedPattern {
            ppat_desc: crate::parser::ast::PatternDesc::Ppat_construct(
                cstr_lid,
                tctx.arena.shared_pat_ctor_args(&cstr_args, lident.loc),
            ),
            ppat_loc: lident.loc,
            ppat_attributes: vec![pat_from_variant_spread_attr.clone()].into(),
        };
        synthetic_pattern_idxs.push(push_synthetic_pat(tctx.arena, parsed));
    }

    synthetic_pattern_idxs.reverse();
    // typecore.ml `build_ppat_or_for_variant_spread`: the constructors and the
    // or-patterns grouping them are marked, so that the ones earlier cases
    // already match aren't reported as unused. The root stands for the spread
    // the user wrote: it's reported, at the spread, when all of it is unused.
    let expanded_pattern = match synthetic_pattern_idxs.into_iter().reduce(|lhs, rhs| {
        push_synthetic_pat(
            tctx.arena,
            ParsedPattern {
                ppat_desc: crate::parser::ast::PatternDesc::Ppat_or(lhs, rhs),
                ppat_loc: lident.loc,
                ppat_attributes: vec![pat_from_variant_spread_attr.clone()].into(),
            },
        )
    }) {
        Some(pattern) => {
            let mut root = tctx.arena.get_pat(pattern).clone();
            root.ppat_loc = pat.ppat_loc;
            root.ppat_attributes = Attributes::new();
            root
        }
        None => pat.clone(),
    };

    Ok(Some((expanded_pattern, spread_ty)))
}

fn maybe_expand_variant_spread_in_pattern(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pat: &ParsedPattern,
    expected_ty: TypeExprRef,
) -> TypeCoreResult<Option<ParsedPattern>> {
    if !matches!(
        &pat.ppat_desc,
        crate::parser::ast::PatternDesc::Ppat_variant_spread(_)
    ) {
        return Ok(None);
    }

    Ok(
        build_ppat_or_for_variant_spread(tctx, env, pat, expected_ty)?
            .map(|(expanded, _)| expanded),
    )
}

// ============================================================================
// Pattern Type Checking
// ============================================================================

/// Type check a pattern against an expected type.
pub fn type_pattern(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pat: &ParsedPattern,
    expected_ty: TypeExprRef,
    mode: PatternMode,
    state: &mut PatternState,
) -> TypeCoreResult<Pattern> {
    type_pattern_with_existentials_at_level(
        tctx,
        env,
        pat,
        expected_ty,
        PatternOptions {
            mode,
            allow_existentials: true,
            level: tctx.type_ctx.current_level(),
        },
        state,
        0,
    )
}

fn type_pattern_without_existentials(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pat: &ParsedPattern,
    expected_ty: TypeExprRef,
    mode: PatternMode,
    state: &mut PatternState,
) -> TypeCoreResult<Pattern> {
    type_pattern_with_existentials_at_level(
        tctx,
        env,
        pat,
        expected_ty,
        PatternOptions {
            mode,
            allow_existentials: false,
            level: tctx.type_ctx.current_level(),
        },
        state,
        0,
    )
}

struct PatternBacktrackState<'a> {
    type_state: crate::types::context::TypeMutationSnapshot<'a>,
    unify_state: crate::types::ctype::UnifyStateSnapshot,
    pattern_state: PatternStateCheckpoint,
    newtype_level: Option<i32>,
}

fn save_pattern_backtrack_state<'a>(
    tctx: &TypeCheckContext<'a>,
    state: &PatternState,
) -> PatternBacktrackState<'a> {
    PatternBacktrackState {
        type_state: tctx.type_ctx.snapshot_type_state(),
        unify_state: tctx.unify_state.snapshot_backtrack_state(),
        pattern_state: state.checkpoint(),
        newtype_level: tctx.newtype_level,
    }
}

fn restore_pattern_backtrack_state(
    tctx: &mut TypeCheckContext<'_>,
    state: &mut PatternState,
    snapshot: PatternBacktrackState<'_>,
) {
    tctx.type_ctx.restore_type_state(snapshot.type_state);
    tctx.unify_state
        .restore_backtrack_state(snapshot.unify_state);
    state.restore_checkpoint(snapshot.pattern_state);
    tctx.newtype_level = snapshot.newtype_level;
}

fn is_need_backtrack(err: &TypeCoreError) -> bool {
    matches!(err, TypeCoreError::NeedBacktrack)
}

fn type_pattern_with_existentials_at_level(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pat: &ParsedPattern,
    expected_ty: TypeExprRef,
    options: PatternOptions,
    state: &mut PatternState,
    explode: i32,
) -> TypeCoreResult<Pattern> {
    let level = options.level;
    // Match OCaml's type_pat: delayed checks reuse the level captured by
    // type_cases rather than the level current when the queue is flushed.
    let old_newtype_level = tctx.newtype_level;
    tctx.newtype_level = Some(level);
    let mut result = type_pattern_inner(tctx, env, pat, expected_ty, options, state, explode);
    if let Ok(typed) = &mut result {
        let outer_env = tctx.type_ctx.store_typed_env(env);
        let final_env = pattern_env_ref(tctx, env);
        if final_env != outer_env {
            set_pattern_envs(&mut tctx.typed, typed, final_env);
        }
    }
    if result.is_ok() {
        for field_ty in state.take_deferred_type_path_forces() {
            // OCaml compiler/ml/typecore.ml:1192-1198 resolves and sorts record
            // fields before typing subpatterns, and compiler/ml/typecore.ml:1623-1644's
            // `type_label_pat` allocates pattern binders before any later lazy
            // field-argument module force. Keep this at the full-pattern
            // boundary so tuple siblings such as `Some(x)` get their binders
            // before nested record field paths are forced.
            force_type_paths_for_lookup_from_type(
                tctx.type_ctx,
                env,
                &mut tctx.persistent_env,
                field_ty,
                &mut crate::types::type_marks::visit_set(),
            );
        }
    }
    tctx.newtype_level = old_newtype_level;
    result
}

/// Inner pattern type checking with explode level.
fn type_pattern_inner(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pat: &ParsedPattern,
    expected_ty: TypeExprRef,
    options: PatternOptions,
    state: &mut PatternState,
    explode: i32,
) -> TypeCoreResult<Pattern> {
    let mode = options.mode;
    use crate::parser::ast::PatternDesc as PD;
    let pat_env_ref = tctx.type_ctx.store_typed_env(env);
    // OCaml's `mode'` (typecore.ml:1257): `Splitting_or` makes an or-pattern
    // split itself, and everything below this node is typed in `Normal` mode.
    let split_or = matches!(mode, PatternMode::SplitOr | PatternMode::SplittingOr);
    let mode = if mode == PatternMode::SplittingOr {
        PatternMode::Normal
    } else {
        mode
    };
    let options = PatternOptions { mode, ..options };

    let expanded_pat = maybe_expand_variant_spread_in_pattern(tctx, env, pat, expected_ty)?;
    let pat = expanded_pat.as_ref().unwrap_or(pat);
    let loc = pat.ppat_loc;
    let ctx = tctx.type_ctx;

    match &pat.ppat_desc {
        PD::Ppat_any => {
            if explode > 0 {
                let constructor_checkpoint = tctx.generated_pattern_constructors.len();
                let label_checkpoint = tctx.generated_pattern_labels.len();
                if let Some(generated) = materialize_pattern_of_type(tctx, env, expected_ty, loc) {
                    if mode == PatternMode::InsideOr {
                        tctx.generated_pattern_constructors
                            .truncate(constructor_checkpoint);
                        tctx.generated_pattern_labels.truncate(label_checkpoint);
                        return Err(TypeCoreError::NeedBacktrack);
                    }
                    let generated_is_or = matches!(
                        &tctx.arena.get_pat(generated).ppat_desc,
                        crate::parser::ast::PatternDesc::Ppat_or(_, _)
                    );
                    let next_explode = if generated_is_or {
                        explode - 5
                    } else {
                        explode - 1
                    };
                    let result = type_pattern_inner(
                        tctx,
                        env,
                        tctx.arena.get_pat(generated),
                        expected_ty,
                        options,
                        state,
                        next_explode,
                    );
                    tctx.generated_pattern_constructors
                        .truncate(constructor_checkpoint);
                    tctx.generated_pattern_labels.truncate(label_checkpoint);
                    return result;
                }
            }

            Ok({
                let typed_node = Pattern::new(PatternDesc::Tpat_any, loc, expected_ty, pat_env_ref);
                tctx.typed
                    .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
            })
        }

        PD::Ppat_var(name) => {
            // Variable pattern. typecore.ml:1239-1243 (PR#7330): the
            // counter-example placeholder `*extension*` is a fresh ident that
            // is not entered as a pattern variable.
            let id = if tctx.arena.get_string(name.txt) == "*extension*" {
                tctx.type_ctx.create_ident("*extension*")
            } else {
                state.enter_variable(
                    tctx.type_ctx,
                    loc,
                    name,
                    expected_ty,
                    PatternVariableKind::Value,
                    tctx.arena,
                )?
            };
            Ok({
                let typed_node = Pattern::new(
                    PatternDesc::Tpat_var(id, convert_located_stridx(name, tctx.arena)),
                    loc,
                    expected_ty,
                    pat_env_ref,
                );
                tctx.typed
                    .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
            })
        }

        PD::Ppat_constant(cst) => {
            // Constant pattern
            let constant = convert_constant(cst, loc, tctx.arena)?;
            let ty = type_constant(ctx, env, &constant);

            // Unify with expected type
            unify_pattern_types(tctx, loc, ty, expected_ty)?;

            Ok({
                let typed_node = Pattern::new(
                    PatternDesc::Tpat_constant(constant),
                    loc,
                    expected_ty,
                    pat_env_ref,
                );
                tctx.typed
                    .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
            })
        }

        PD::Ppat_tuple(pats) => {
            // Tuple pattern
            assert!(pats.len() >= 2, "Tuple must have at least 2 elements");

            // Create fresh type variables for each element
            let elem_types: Vec<TypeExprRef> = tctx
                .arena
                .pat_list(*pats)
                .iter()
                .map(|_| ctx.new_var(None))
                .collect();

            // Create tuple type and unify
            let tuple_ty = ctx.new_tuple(elem_types.clone());
            unify_pattern_types(tctx, loc, tuple_ty, expected_ty)?;

            // Type check each element
            let mut typed_pats = Vec::new();
            for (p, ty) in tctx.arena.pat_list(*pats).iter().zip(elem_types.iter()) {
                let typed_pat = type_pattern_inner(
                    tctx,
                    env,
                    tctx.arena.get_pat(*p),
                    *ty,
                    options,
                    state,
                    explode,
                )?;
                typed_pats.push(typed_pat);
            }

            Ok({
                let typed_node = Pattern::new(
                    PatternDesc::Tpat_tuple(tctx.typed.push_patterns(typed_pats)),
                    loc,
                    expected_ty,
                    pat_env_ref,
                );
                tctx.typed
                    .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
            })
        }

        PD::Ppat_alias(inner_pat_idx, name) => {
            // Alias pattern: P as x
            let inner_pat = tctx.arena.get_pat(*inner_pat_idx);
            let (expanded_inner, override_type_from_variant_spread) =
                if matches!(&inner_pat.ppat_desc, PD::Ppat_variant_spread(_)) {
                    match build_ppat_or_for_variant_spread(tctx, env, inner_pat, expected_ty)? {
                        Some((expanded, spread_ty)) => (Some(expanded), Some(spread_ty)),
                        None => (None, None),
                    }
                } else {
                    (None, None)
                };
            let inner_pat = expanded_inner.as_ref().unwrap_or(inner_pat);

            let typed_inner =
                type_pattern_inner(tctx, env, inner_pat, expected_ty, options, state, explode)?;

            // Build the as-type.
            // OCaml wraps in begin_def/end_def/generalize (typecore.ml:1288-1295).
            // For non-private constructors, build_as_type creates fresh types at
            // the elevated level, which then get generalized. For private constructors,
            // build_as_type returns pat.pat_type which is at the caller's level —
            // the actual generalization comes from type_cases' propagation cycle.
            let ctx = tctx.type_ctx;
            ctx.begin_def();
            let ty_var = match override_type_from_variant_spread {
                Some(ty) => ty,
                None => build_as_type(tctx, env, &typed_inner)?,
            };
            ctx.end_def();
            crate::types::ctype::generalize(ctx, ty_var);

            // Enter the variable with the as-type
            let id = state.enter_variable(
                tctx.type_ctx,
                loc,
                name,
                ty_var,
                PatternVariableKind::Alias,
                tctx.arena,
            )?;

            Ok({
                let typed_node = Pattern::new(
                    PatternDesc::Tpat_alias(
                        tctx.typed.push_pattern(typed_inner),
                        id,
                        convert_located_stridx(name, tctx.arena),
                    ),
                    loc,
                    expected_ty,
                    pat_env_ref,
                );
                tctx.typed
                    .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
            })
        }

        PD::Ppat_or(p1_idx, p2_idx) => {
            // Or-pattern: P1 | P2
            // `save_state env` (typecore.ml:1677), kept where the or-pattern
            // can be split: in a counter-example, outside `Inside_or`.
            let split_state = (state.counter_example && mode != PatternMode::InsideOr)
                .then(|| save_pattern_backtrack_state(tctx, state));
            let typed_or_result = (|| -> TypeCoreResult<Pattern> {
                if split_or {
                    return Err(TypeCoreError::NeedBacktrack);
                }

                // OCaml typecore.ml:1688-1718 types both branches of a
                // non-split or-pattern in Inside_or mode, while only
                // restoring pattern/module binders between branches.
                let initial_state = state.checkpoint();

                // Type check first branch
                let p1 = tctx.arena.get_pat(*p1_idx);
                let typed_p1 = match type_pattern_inner(
                    tctx,
                    env,
                    p1,
                    expected_ty,
                    PatternOptions {
                        mode: PatternMode::InsideOr,
                        ..options
                    },
                    state,
                    explode,
                ) {
                    Ok(pat) => Some(pat),
                    Err(err) if is_need_backtrack(&err) => None,
                    Err(err) => return Err(err),
                };

                // Save p1's variables
                let p1_vars: Vec<_> =
                    state.pattern_variables[initial_state.pattern_variables_len..].to_vec();
                let p1_module_vars: Vec<_> =
                    state.module_variables[initial_state.module_variables_len..].to_vec();

                // Reset pattern/module binders for p2 without restoring type
                // graph mutations; OCaml only uses set_state when falling back
                // to split mode.
                state.restore_binding_checkpoint(initial_state);

                // Type check second branch
                let p2 = tctx.arena.get_pat(*p2_idx);
                let typed_p2 = match type_pattern_inner(
                    tctx,
                    env,
                    p2,
                    expected_ty,
                    PatternOptions {
                        mode: PatternMode::InsideOr,
                        ..options
                    },
                    state,
                    explode,
                ) {
                    Ok(pat) => Some(pat),
                    Err(err) if is_need_backtrack(&err) => None,
                    Err(err) => return Err(err),
                };

                // Get p2's variables
                let p2_vars: Vec<_> =
                    state.pattern_variables[initial_state.pattern_variables_len..].to_vec();

                match (typed_p1, typed_p2) {
                    (None, None) => Err(TypeCoreError::NeedBacktrack),
                    (Some(typed_p1), None) => {
                        state.restore_binding_checkpoint(initial_state);
                        state.pattern_variables.extend(p1_vars.iter().cloned());
                        state
                            .module_variables
                            .extend(p1_module_vars.iter().cloned());
                        Ok(typed_p1)
                    }
                    (None, Some(typed_p2)) => Ok(typed_p2),
                    (Some(typed_p1), Some(typed_p2)) => {
                        // Match OCaml typecore.ml:
                        // - verify both branches bind the same variables,
                        // - alpha-rename branch 2 onto branch 1's ids,
                        // - keep only branch 1's bindings live after typing the or-pattern.
                        let alpha_env = merge_or_pattern_variables(tctx, loc, &p1_vars, &p2_vars)?;
                        // Without variables there is nothing to rename. Skipping
                        // the copy keeps nested or-patterns, e.g. expanded
                        // character ranges, linear.
                        let typed_p2 = if alpha_env.is_empty() {
                            typed_p2
                        } else {
                            alpha_pattern(&mut tctx.typed, &alpha_env, &typed_p2)
                        };
                        state.restore_binding_checkpoint(initial_state);
                        state.pattern_variables.extend(p1_vars.iter().cloned());
                        state
                            .module_variables
                            .extend(p1_module_vars.iter().cloned());

                        Ok({
                            let typed_node = Pattern::new(
                                PatternDesc::Tpat_or(
                                    tctx.typed.push_pattern(typed_p1),
                                    tctx.typed.push_pattern(typed_p2),
                                    None,
                                ),
                                loc,
                                expected_ty,
                                pat_env_ref,
                            );
                            tctx.typed
                                .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
                        })
                    }
                }
            })();

            match (typed_or_result, split_state) {
                (Err(TypeCoreError::NeedBacktrack), Some(entry_state)) => {
                    // typecore.ml:1713-1720: back at the entry state, type
                    // one alternative on its own. `OrSplits` stands in for
                    // the `with Error _` that moves on to the second one.
                    restore_pattern_backtrack_state(tctx, state, entry_state);
                    let alternative = if state.or_splits.take_second() {
                        *p2_idx
                    } else {
                        *p1_idx
                    };
                    let split_mode = if mode == PatternMode::SplitOr {
                        PatternMode::SplitOr
                    } else {
                        PatternMode::SplittingOr
                    };
                    type_pattern_inner(
                        tctx,
                        env,
                        tctx.arena.get_pat(alternative),
                        expected_ty,
                        PatternOptions {
                            mode: split_mode,
                            ..options
                        },
                        state,
                        explode,
                    )
                }
                (result, _) => result,
            }
        }

        PD::Ppat_array(pats) => {
            // Array pattern
            let elem_ty = ctx.new_var(None);
            let array_ty = env.type_array(ctx, elem_ty);
            unify_pattern_types(tctx, loc, array_ty, expected_ty)?;

            let mut typed_pats = Vec::new();
            for p in tctx.arena.pat_list(*pats).iter() {
                let typed_pat = type_pattern_inner(
                    tctx,
                    env,
                    tctx.arena.get_pat(*p),
                    elem_ty,
                    options,
                    state,
                    explode,
                )?;
                typed_pats.push(typed_pat);
            }

            Ok({
                let typed_node = Pattern::new(
                    PatternDesc::Tpat_array(tctx.typed.push_patterns(typed_pats)),
                    loc,
                    expected_ty,
                    pat_env_ref,
                );
                tctx.typed
                    .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
            })
        }

        PD::Ppat_dict(entries) => {
            // typecore.ml Ppat_dict: an entry matches its key's value as an
            // option, `None` when the key is absent, like an optional record
            // field.
            let mut seen = HashSet::new();
            for entry in entries.iter() {
                let key = tctx.arena.get_string(entry.pdp_key.txt);
                if !seen.insert(key) {
                    return Err(TypeCoreError::DictKeyMultiplyDefined {
                        loc: entry.pdp_key.loc,
                        key: key.to_string(),
                    });
                }
            }
            let ty_value = ctx.new_var(None);
            let ty_option =
                ctx.new_predef_constr(crate::types::predef::path_option(), vec![ty_value]);
            let mut typed_entries = Vec::with_capacity(entries.len());
            for entry in entries.iter() {
                let sarg = if entry.pdp_optional
                    || is_from_parmatch(tctx.arena, tctx.arena.get_pat(entry.pdp_pattern))
                {
                    entry.pdp_pattern
                } else {
                    wrap_some(tctx.arena, entry.pdp_pattern)
                };
                let tdp_pattern = type_pattern_inner(
                    tctx,
                    env,
                    tctx.arena.get_pat(sarg),
                    ty_option,
                    options,
                    state,
                    explode,
                )?;
                typed_entries.push(TypedDictPatternEntry {
                    tdp_key: Located {
                        txt: tctx.arena.get_string(entry.pdp_key.txt).to_string(),
                        loc: entry.pdp_key.loc,
                    },
                    tdp_pattern: tctx.typed.push_pattern(tdp_pattern),
                    tdp_optional: entry.pdp_optional,
                });
            }
            let dict_ty = ctx.new_predef_constr(crate::types::predef::path_dict(), vec![ty_value]);
            unify_pattern_types(tctx, loc, dict_ty, expected_ty)?;
            Ok(tctx.typed.with_pat_attributes(Pattern::new(
                PatternDesc::Tpat_dict(typed_entries),
                loc,
                expected_ty,
                pat_env_ref,
                ), pat.ppat_attributes.clone(),
            ))
        }

        PD::Ppat_construct(lid, sargs) => {
            // Constructor pattern: Some(x), None, etc.
            type_pattern_construct(
                tctx,
                env,
                loc,
                lid,
                sargs,
                expected_ty,
                options,
                state,
                explode,
                pat,
            )
        }

        PD::Ppat_variant(inner) => {
            let (ref label, ref sargs) = **inner;
            check_polyvar_name(loc, label)?;
            // typecore.ml Ppat_variant: several arguments form one tuple
            // payload located at the argument list.
            let sarg = match tctx.arena.pat_list(sargs.txt) {
                [] => None,
                [sarg] => Some(*sarg),
                args => Some(push_synthetic_pat(
                    tctx.arena,
                    ParsedPattern {
                        ppat_desc: PD::Ppat_tuple(tctx.arena.push_shared_pat_list(args)),
                        ppat_loc: sargs.loc,
                        ppat_attributes: Attributes::new(),
                    },
                )),
            };
            // Polymorphic variant pattern: #Red, #Blue(x)
            type_pattern_variant(
                tctx,
                env,
                loc,
                label,
                sarg.map(|idx| tctx.arena.get_pat(idx)),
                expected_ty,
                options,
                state,
                explode,
                pat,
            )
        }

        PD::Ppat_record(inner) => {
            let (ref fields, ref closed_flag, ref record_rest) = **inner;
            // Record pattern: {name, age}
            type_pattern_record(
                tctx,
                env,
                loc,
                tctx.arena.pat_field_list(*fields),
                *closed_flag,
                record_rest.as_ref(),
                expected_ty,
                options,
                state,
                explode,
                pat,
            )
        }

        PD::Ppat_constraint(inner) => {
            let (ref inner_pat_idx, ref core_type) = **inner;
            let inner_pat = tctx.arena.get_pat(*inner_pat_idx);
            let core_ty = tctx.arena.get_core_type(*core_type);

            // OCaml typecore.ml:1249-1274: Special case for Ppat_constraint(Ppat_var, Ptyp_poly)
            // Uses instance_poly ~keep_names:true to preserve type variable names.
            if let (PD::Ppat_var(name), crate::parser::ast::CoreTypeDesc::Ptyp_poly(_)) =
                (&inner_pat.ppat_desc, &core_ty.ptyp_desc)
            {
                type_pattern_constraint_poly_var(
                    tctx,
                    env,
                    loc,
                    inner_pat,
                    *name,
                    core_ty,
                    expected_ty,
                    options,
                    state,
                    explode,
                    pat,
                )
            } else {
                type_pattern_constraint(
                    tctx,
                    env,
                    loc,
                    inner_pat,
                    core_ty,
                    expected_ty,
                    options,
                    state,
                    explode,
                    pat,
                )
            }
        }

        PD::Ppat_interval(inner) => {
            let (ref c1, ref c2) = **inner;
            // Interval pattern: 'a'..'z'
            type_pattern_interval(tctx, env, loc, c1, c2, expected_ty, pat)
        }

        PD::Ppat_exception(inner_pat_idx) => {
            // Exception pattern
            let inner_pat = tctx.arena.get_pat(*inner_pat_idx);
            type_pattern_exception(
                tctx,
                env,
                loc,
                inner_pat,
                expected_ty,
                mode,
                state,
                explode,
                pat,
            )
        }

        PD::Ppat_unpack(name) => {
            // Module unpack pattern: module(M)
            let id = state.enter_variable(
                tctx.type_ctx,
                loc,
                name,
                expected_ty,
                PatternVariableKind::Module,
                tctx.arena,
            )?;
            let mut typed_pat = Pattern::new(
                PatternDesc::Tpat_var(id, convert_located_stridx(name, tctx.arena)),
                loc,
                expected_ty,
                pat_env_ref,
            );
            tctx.typed.push_pat_extra(
                &mut typed_pat,
                (
                    crate::types::typedtree::PatExtra::Tpat_unpack,
                    loc,
                    pat.ppat_attributes.clone(),
                ),
            );
            Ok(typed_pat)
        }

        // `Ppat_variant_spread` is expanded above, except for a variant
        // without constructors, which is typed (and rejected) like `#...t`.
        PD::Ppat_type(lid) | PD::Ppat_variant_spread(lid) => {
            // Poly variant type pattern: #type or used for #...spread
            // OCaml typecore.ml:1663-1671: build_or_pat expands into Tpat_variant or-patterns
            let (path, or_pat, ty) = build_or_pat(tctx, env, loc, lid)?;
            unify_pattern_types(tctx, loc, ty, expected_ty)?;
            let mut result = or_pat;
            tctx.typed.set_pat_extra(
                &mut result,
                vec![(
                    crate::types::typedtree::PatExtra::Tpat_type(path, *lid),
                    loc,
                    pat.ppat_attributes.clone(),
                )],
            );
            Ok(result)
        }

        PD::Ppat_extension(extension) => Err(builtin_extension_error(tctx.arena, extension)),
    }
}

/// Unify pattern types, raising PatternTypeClash on error.
fn unify_pattern_types(
    tctx: &mut TypeCheckContext<'_>,
    _loc: LocIdx,
    ty1: TypeExprRef,
    ty2: TypeExprRef,
) -> TypeCoreResult<()> {
    use crate::types::unify;

    match unify(tctx.type_ctx, &mut tctx.unify_state, ty1, ty2) {
        Ok(()) => Ok(()),
        Err(TypeError::Unify(trace)) => Err(TypeCoreError::PatternTypeClash {
            loc: Some(_loc),
            trace: if trace.is_empty() {
                vec![(ty1, ty2)]
            } else {
                trace
            },
            env: tctx
                .unify_state
                .env()
                .map(|env| tctx.type_ctx.store_typed_env(env)),
        }),
        Err(_) => Err(TypeCoreError::PatternTypeClash {
            loc: Some(_loc),
            trace: vec![(ty1, ty2)],
            env: tctx
                .unify_state
                .env()
                .map(|env| tctx.type_ctx.store_typed_env(env)),
        }),
    }
}

/// Add the local constraints (GADT equations) of `from` that `env` lacks.
/// Returns whether any were added.
fn add_missing_local_constraints(env: &mut Env, from: &Env) -> bool {
    let missing: Vec<_> = from
        .iter_local_constraints()
        .filter(|(path, _)| env.find_local_constraint(path).is_none())
        .map(|(path, decl)| (*path, decl.clone()))
        .collect();
    let added = !missing.is_empty();
    for (path, decl) in missing {
        env.add_local_constraint(path, decl);
    }
    added
}

/// OCaml's `!env` while a pattern is typed: the outer `env` plus the GADT
/// equations `unify_pat_types_gadt` has added so far. OCaml types a pattern
/// through one `env ref` (typecore.ml:1248-1720); Rust passes the outer `env`
/// down and keeps those equations in the unify state's env.
fn pattern_env_ref(tctx: &mut TypeCheckContext<'_>, env: &Env) -> EnvRef {
    if let Some(unify_env) = tctx.unify_state.env()
        && unify_env.id() != env.id()
        && unify_env.has_local_constraints()
    {
        let mut refined = env.clone();
        if add_missing_local_constraints(&mut refined, unify_env) {
            return tctx.type_ctx.store_typed_env(&refined);
        }
    }
    tctx.type_ctx.store_typed_env(env)
}

/// `iter_pattern (fun p -> p.pat_env <- !env) r` (typecore.ml:1779): once
/// the whole pattern is typed, every node gets the final env, so a node typed
/// before a GADT constructor sees its equations too.
fn set_pattern_envs(ta: &mut TypedArena, pat: &mut Pattern, env: EnvRef) {
    pat.pat_env = env;
    let mut todo: Vec<TPatIdx> = Vec::new();
    pattern_children(ta, pat, &mut todo);
    while let Some(idx) = todo.pop() {
        ta.pattern_mut(idx).pat_env = env;
        pattern_children(ta, ta.pattern(idx), &mut todo);
    }
}

fn pattern_children(ta: &TypedArena, pat: &Pattern, out: &mut Vec<TPatIdx>) {
    match &pat.pat_desc {
        PatternDesc::Tpat_variant(_, arg, _) => out.extend(*arg),
        PatternDesc::Tpat_alias(inner, _, _) => out.push(*inner),
        PatternDesc::Tpat_or(left, right, _) => out.extend([*left, *right]),
        PatternDesc::Tpat_tuple(items)
        | PatternDesc::Tpat_array(items)
        | PatternDesc::Tpat_construct(_, _, items) => {
            out.extend_from_slice(ta.pattern_list(*items))
        }
        PatternDesc::Tpat_record(fields, _, _) => {
            out.extend(fields.iter().map(|(_, _, field_pat, _)| *field_pat))
        }
        PatternDesc::Tpat_dict(entries) => {
            out.extend(entries.iter().map(|entry| entry.tdp_pattern))
        }
        PatternDesc::Tpat_any
        | PatternDesc::Tpat_var(_, _)
        | PatternDesc::Tpat_constant(_)
        | PatternDesc::Tpat_interval(_, _) => {}
    }
}

/// GADT-mode pattern unification: enables generate_equations and assume_injective
/// so that abstract newtypes can receive type equations. Matches OCaml's
/// unify_pat_types_gadt which calls unify_gadt.
fn unify_pattern_types_gadt(
    tctx: &mut TypeCheckContext<'_>,
    _loc: LocIdx,
    ty1: TypeExprRef,
    ty2: TypeExprRef,
) -> TypeCoreResult<()> {
    use crate::types::unify;

    // Save old state
    let old_generate = tctx.unify_state.generate_equations;
    let old_injective = tctx.unify_state.assume_injective;
    let old_mode = tctx.unify_state.mode;
    let old_newtype_level = tctx.unify_state.newtype_level;

    // Set GADT mode
    tctx.unify_state.generate_equations = true;
    tctx.unify_state.assume_injective = true;
    tctx.unify_state.mode = crate::types::UnifyMode::Pattern;
    tctx.unify_state.newtype_level = tctx.newtype_level;

    let result = unify(tctx.type_ctx, &mut tctx.unify_state, ty1, ty2);

    // Restore old state
    tctx.unify_state.generate_equations = old_generate;
    tctx.unify_state.assume_injective = old_injective;
    tctx.unify_state.mode = old_mode;
    tctx.unify_state.newtype_level = old_newtype_level;

    match result {
        Ok(()) => Ok(()),
        Err(TypeError::Unify(trace)) => Err(TypeCoreError::PatternTypeClash {
            loc: Some(_loc),
            trace: if trace.is_empty() {
                vec![(ty1, ty2)]
            } else {
                trace
            },
            env: tctx
                .unify_state
                .env()
                .map(|env| tctx.type_ctx.store_typed_env(env)),
        }),
        Err(_) => Err(TypeCoreError::PatternTypeClash {
            loc: Some(_loc),
            trace: vec![(ty1, ty2)],
            env: tctx
                .unify_state
                .env()
                .map(|env| tctx.type_ctx.store_typed_env(env)),
        }),
    }
}

fn refine_record_as_type_label(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    whole_pat: &Pattern,
    record_ty: TypeExprRef,
    label_desc: &crate::types::LabelDescription,
    field_pat: Option<TPatIdx>,
) -> TypeCoreResult<()> {
    let ctx = tctx.type_ctx;
    let (_poly_vars, ty_arg, ty_res) = crate::types::ctype::instance_label(ctx, false, label_desc);
    unify_pattern_types(tctx, whole_pat.pat_loc, record_ty, ty_res)?;

    let lbl_arg_repr = ctx.repr(label_desc.lbl_arg);
    let lbl_arg_desc = ctx.get_desc(lbl_arg_repr);
    let arg_is_poly = matches!(&*lbl_arg_desc, TypeDesc::Tpoly { .. });

    let refinable = label_desc.lbl_mut == crate::types::asttypes::MutableFlag::Immutable
        && field_pat.is_some()
        && !arg_is_poly;
    if refinable {
        let field_pat = tctx.typed.pattern(field_pat.unwrap()).clone();
        let field_pat = &field_pat;
        let field_as_ty = build_as_type(tctx, env, field_pat)?;
        unify_pattern_types(tctx, field_pat.pat_loc, field_as_ty, ty_arg)?;
    } else {
        let (_poly_vars2, ty_arg2, ty_res2) =
            crate::types::ctype::instance_label(ctx, false, label_desc);
        unify_pattern_types(tctx, whole_pat.pat_loc, ty_arg, ty_arg2)?;
        unify_pattern_types(tctx, whole_pat.pat_loc, record_ty, ty_res2)?;
    }
    Ok(())
}

/// Build the type for an as-pattern.
fn build_as_type(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pat: &Pattern,
) -> TypeCoreResult<TypeExprRef> {
    let ctx = tctx.type_ctx;
    match &pat.pat_desc {
        PatternDesc::Tpat_alias(inner, _, _) => {
            build_as_type(tctx, env, &tctx.typed.pattern(*inner).clone())
        }
        PatternDesc::Tpat_tuple(pats) => {
            let pats = tctx.typed.pattern_list(*pats).to_vec();
            let tys: Vec<_> = pats
                .into_iter()
                .map(|p| build_as_type(tctx, env, &tctx.typed.pattern(p).clone()))
                .collect::<TypeCoreResult<_>>()?;
            Ok(ctx.new_tuple(tys))
        }
        PatternDesc::Tpat_construct(_, cstr, args) => {
            let keep = cstr.cstr_private == crate::types::PrivateFlag::Private
                || !cstr.cstr_existentials.is_empty();
            if keep {
                Ok(pat.pat_type)
            } else {
                let arg_pats = tctx.typed.pattern_list(*args).to_vec();
                let arg_as_tys: Vec<_> = arg_pats
                    .into_iter()
                    .map(|arg| build_as_type(tctx, env, &tctx.typed.pattern(arg).clone()))
                    .collect::<TypeCoreResult<_>>()?;
                let (inst_arg_tys, ty_res) = crate::types::instance_constructor(ctx, cstr);
                let arg_locs: Vec<LocIdx> = tctx
                    .typed
                    .patterns(*args)
                    .map(|arg_pat| arg_pat.pat_loc)
                    .collect();
                for ((arg_loc, arg_as_ty), inst_arg_ty) in arg_locs
                    .into_iter()
                    .zip(arg_as_tys.iter())
                    .zip(inst_arg_tys.iter())
                {
                    unify_pattern_types(tctx, arg_loc, *arg_as_ty, *inst_arg_ty)?;
                }
                Ok(ty_res)
            }
        }
        PatternDesc::Tpat_record(fields, _closed, rest) => {
            if fields.is_empty() && rest.is_some() {
                return Ok(pat.pat_type);
            }
            let first_label = fields.first().map(|(_, lbl, _, _)| lbl);
            if first_label.is_some_and(|lbl| lbl.lbl_private == crate::types::PrivateFlag::Private)
            {
                Ok(pat.pat_type)
            } else {
                // OCaml build_as_type (typecore.ml:626-652): a fresh record
                // type refined through each label of `lbl.lbl_all` of the
                // first label, `Array.iter do_label lbl.lbl_all`.
                let ty = ctx.new_var(None);
                let present_fields_by_pos: HashMap<i32, TPatIdx> = fields
                    .iter()
                    .map(|(_lid, label_desc, field_pat, _optional)| {
                        (label_desc.lbl_pos, *field_pat)
                    })
                    .collect();
                let first_label = first_label.expect("a record pattern with fields");
                let family = ctx.label_family(first_label.lbl_all).unwrap_or_else(|| {
                    panic!(
                        "record pattern label `{}` carries no lbl_all array ({:?})",
                        first_label.lbl_name, first_label.lbl_all
                    )
                });
                for label in family.iter() {
                    let field_pat = present_fields_by_pos.get(&label.lbl_pos).copied();
                    refine_record_as_type_label(tctx, env, pat, ty, label, field_pat)?;
                }
                Ok(ty)
            }
        }
        PatternDesc::Tpat_variant(label, opt_arg, _) => {
            // OCaml typecore.ml:488-498: create single-field open row with Rpresent
            let opt_ty = match opt_arg {
                Some(p) => Some(build_as_type(tctx, env, &tctx.typed.pattern(*p).clone())?),
                None => None,
            };
            let row = crate::types::type_expr::RowDesc {
                row_fields: vec![(
                    label.clone().into(),
                    crate::types::type_expr::RowField::Rpresent(opt_ty),
                )]
                .into(),
                row_more: ctx.new_var(None),
                row_name: None,
                row_fixed: false,
                row_closed: false,
            };
            Ok(ctx.new_variant(row))
        }
        PatternDesc::Tpat_or(p1, p2, opt_row) => {
            // OCaml typecore.ml:526-534
            match opt_row {
                None => {
                    let ty1 = build_as_type(tctx, env, &tctx.typed.pattern(*p1).clone())?;
                    let ty2 = build_as_type(tctx, env, &tctx.typed.pattern(*p2).clone())?;
                    unify_pattern_types(tctx, tctx.typed.pattern(*p2).pat_loc, ty2, ty1)?;
                    Ok(ty1)
                }
                Some(row) => {
                    // Open the row: set row_closed=false and fresh row_more
                    let row = crate::types::btype::row_repr(ctx, row);
                    let mut new_row = row;
                    new_row.row_closed = false;
                    new_row.row_more = ctx.new_var(None);
                    Ok(ctx.new_variant(new_row))
                }
            }
        }
        _ => Ok(pat.pat_type),
    }
}

/// Merge variables from two or-pattern branches.
fn merge_or_pattern_variables(
    tctx: &mut TypeCheckContext<'_>,
    loc: LocIdx,
    p1_vars: &[PatternVariable],
    p2_vars: &[PatternVariable],
) -> TypeCoreResult<Vec<(Ident, Ident)>> {
    // Sort both by name
    let mut p1_sorted: Vec<_> = p1_vars.iter().collect();
    let mut p2_sorted: Vec<_> = p2_vars.iter().collect();
    p1_sorted.sort_by(|a, b| a.id.name().cmp(b.id.name()));
    p2_sorted.sort_by(|a, b| a.id.name().cmp(b.id.name()));

    let mut result = Vec::new();
    let mut i = 0;
    let mut j = 0;

    while i < p1_sorted.len() && j < p2_sorted.len() {
        let v1 = p1_sorted[i];
        let v2 = p2_sorted[j];

        match v1.id.name().cmp(v2.id.name()) {
            std::cmp::Ordering::Equal => {
                if !v1.id.same(&v2.id) {
                    // OCaml compiler/ml/typecore.ml:551-566
                    // `enter_orpat_variables` only calls `unify env t1 t2` in
                    // branch order before alpha-renaming branch 2.
                    match crate::types::unify(tctx.type_ctx, &mut tctx.unify_state, v1.ty, v2.ty) {
                        Ok(()) => {}
                        Err(TypeError::Unify(trace)) => {
                            return Err(TypeCoreError::OrPatternTypeClash {
                                loc,
                                id: v1.id,
                                trace: if trace.is_empty() {
                                    vec![(v1.ty, v2.ty)]
                                } else {
                                    trace
                                },
                                env: tctx
                                    .unify_state
                                    .env()
                                    .map(|env| tctx.type_ctx.store_typed_env(env)),
                            });
                        }
                        Err(_) => {
                            return Err(TypeCoreError::OrPatternTypeClash {
                                loc,
                                id: v1.id,
                                trace: vec![(v1.ty, v2.ty)],
                                env: tctx
                                    .unify_state
                                    .env()
                                    .map(|env| tctx.type_ctx.store_typed_env(env)),
                            });
                        }
                    }
                    // Match OCaml alpha_pat: rename branch-2 ids onto branch-1 ids.
                    result.push((v2.id, v1.id));
                }
                i += 1;
                j += 1;
            }
            std::cmp::Ordering::Less => {
                // v1 has no match in p2
                return Err(TypeCoreError::OrpatVars {
                    loc,
                    id: v1.id,
                    valid_idents: p2_sorted[j..].iter().map(|var| var.id).collect(),
                });
            }
            std::cmp::Ordering::Greater => {
                // v2 has no match in p1
                return Err(TypeCoreError::OrpatVars {
                    loc,
                    id: v2.id,
                    valid_idents: p1_sorted[i..].iter().map(|var| var.id).collect(),
                });
            }
        }
    }

    if i < p1_sorted.len() {
        return Err(TypeCoreError::OrpatVars {
            loc,
            id: p1_sorted[i].id,
            valid_idents: vec![],
        });
    }
    if j < p2_sorted.len() {
        return Err(TypeCoreError::OrpatVars {
            loc,
            id: p2_sorted[j].id,
            valid_idents: vec![],
        });
    }

    Ok(result)
}

fn alpha_pattern_id<'a>(alpha_env: &'a [(Ident, Ident)], id: &Ident) -> Option<&'a Ident> {
    alpha_env
        .iter()
        .find_map(|(from, to)| if from.same(id) { Some(to) } else { None })
}

/// `alpha_pat` (typecore.ml): a copy of `pat` with its variables renamed
/// through `alpha_env`. Children are copied into `ta`; the root is
/// returned for the caller to store.
fn alpha_pattern(ta: &mut TypedArena, alpha_env: &[(Ident, Ident)], pat: &Pattern) -> Pattern {
    let pat_desc = match &pat.pat_desc {
        PatternDesc::Tpat_var(id, name) => alpha_pattern_id(alpha_env, id)
            .map(|new_id| PatternDesc::Tpat_var(*new_id, name.clone()))
            .unwrap_or(PatternDesc::Tpat_any),
        PatternDesc::Tpat_alias(inner, id, name) => {
            let new_inner = alpha_child(ta, alpha_env, *inner);
            match alpha_pattern_id(alpha_env, id) {
                Some(new_id) => {
                    PatternDesc::Tpat_alias(ta.push_pattern(new_inner), *new_id, name.clone())
                }
                None => return new_inner,
            }
        }
        PatternDesc::Tpat_tuple(items) => {
            PatternDesc::Tpat_tuple(alpha_list(ta, alpha_env, *items))
        }
        PatternDesc::Tpat_construct(lid, cstr, args) => {
            PatternDesc::Tpat_construct(*lid, cstr.clone(), alpha_list(ta, alpha_env, *args))
        }
        PatternDesc::Tpat_variant(label, arg, row) => PatternDesc::Tpat_variant(
            label.clone(),
            arg.map(|arg| {
                let new_arg = alpha_child(ta, alpha_env, arg);
                ta.push_pattern(new_arg)
            }),
            *row,
        ),
        PatternDesc::Tpat_record(fields, closed, rest) => PatternDesc::Tpat_record(
            fields
                .iter()
                .map(|(lid, lbl, field_pat, opt)| {
                    let new_field = alpha_child(ta, alpha_env, *field_pat);
                    (*lid, lbl.clone(), ta.push_pattern(new_field), *opt)
                })
                .collect(),
            *closed,
            rest.as_ref().map(|rest| {
                let mut rest = rest.clone();
                if let Some(new_id) = alpha_pattern_id(alpha_env, &rest.rest_ident) {
                    rest.rest_ident = *new_id;
                }
                rest
            }),
        ),
        PatternDesc::Tpat_array(items) => {
            PatternDesc::Tpat_array(alpha_list(ta, alpha_env, *items))
        }
        PatternDesc::Tpat_or(left, right, row) => {
            let new_left = alpha_child(ta, alpha_env, *left);
            let new_left = ta.push_pattern(new_left);
            let new_right = alpha_child(ta, alpha_env, *right);
            let new_right = ta.push_pattern(new_right);
            PatternDesc::Tpat_or(new_left, new_right, row.clone())
        }
        _ => return pat.clone(),
    };
    Pattern {
        pat_desc,
        ..pat.clone()
    }
}

fn alpha_child(ta: &mut TypedArena, alpha_env: &[(Ident, Ident)], pat: TPatIdx) -> Pattern {
    let pat = ta.pattern(pat).clone();
    alpha_pattern(ta, alpha_env, &pat)
}

fn alpha_list(
    ta: &mut TypedArena,
    alpha_env: &[(Ident, Ident)],
    items: crate::types::typedtree::TPatList,
) -> crate::types::typedtree::TPatList {
    let items: smallvec::SmallVec<[TPatIdx; 8]> = ta.pattern_list(items).into();
    let renamed: smallvec::SmallVec<[TPatIdx; 8]> = items
        .into_iter()
        .map(|item| {
            let new_item = alpha_child(ta, alpha_env, item);
            ta.push_pattern(new_item)
        })
        .collect();
    ta.push_pattern_list(&renamed)
}

// ============================================================================
// Pattern Type Checking Helpers
// ============================================================================

/// Type check constructor pattern.
#[allow(clippy::too_many_arguments)]
fn type_pattern_construct(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Located<crate::parse_arena::LidentIdx>,
    sargs: &Located<crate::parse_arena::PatList>,
    expected_ty: TypeExprRef,
    options: PatternOptions,
    state: &mut PatternState,
    explode: i32,
    pat: &ParsedPattern,
) -> TypeCoreResult<Pattern> {
    let PatternOptions {
        mode,
        allow_existentials,
        ..
    } = options;
    let ctx = tctx.type_ctx;

    // Look up constructor with disambiguation following OCaml's approach:
    // 1. For module-qualified constructors (Ldot), use direct module lookup
    // 2. For unqualified constructors (Lident), use disambiguation considering expected type
    let lid_txt = tctx.arena.get_longident(lid.txt);
    let lid_name = tctx.longident_last_name(lid_txt);
    let is_qualified = matches!(lid_txt, Longident::Ldot(..));
    if is_qualified {
        // `Typetexp.find_all_constructors` marks the qualifying module
        // through `lookup_module_descr` (env.ml:1076-1089).
        mark_open_lid_use(
            ctx,
            env,
            tctx.arena,
            lid_txt,
            crate::types::env::OpenLookupKind::Component,
            Some(lid.loc),
        );
    }
    let qualified_opath = if is_qualified {
        // OCaml compiler/ml/typecore.ml:1456-1478 computes `opath`, gets
        // candidates through `Typetexp.find_all_constructors`, then still
        // calls `Constructor.disambiguate`. Its by-type path reaches
        // compare_type_path at typecore.ml:983-988 and expand_path at
        // typecore.ml:775-787, preserving Env.normalize_path side effects.
        extract_variant_type_path_from_expected_with_persistent_env(
            expected_ty,
            env,
            &mut tctx.persistent_env,
            tctx.type_ctx,
        )
    } else {
        None
    };
    let generated_constructor = (!is_qualified)
        .then(|| {
            tctx.generated_pattern_constructors
                .iter()
                .rev()
                .find(|(name, _)| name == &lid_name)
                .map(|(_, desc)| (**desc).clone())
        })
        .flatten();
    let (cstr_desc, _cstr_path) = if let Some(desc) = generated_constructor {
        (desc, Path::pident(Ident::create_persistent(lid_name)))
    } else if is_qualified {
        if let Some((path, desc)) =
            lookup_predef_option_constructor(lid_txt, tctx.arena, env, tctx.type_ctx)
        {
            if let Some((expected, alternatives)) = qualified_constructor_type_mismatch(
                qualified_opath.as_ref(),
                &desc,
                expected_ty,
                env,
                &mut tctx.persistent_env,
                tctx.type_ctx,
            ) {
                return Err(TypeCoreError::NameTypeMismatch {
                    loc: lid.loc,
                    kind: "variant".to_string(),
                    lid: lid_txt.clone(),
                    expected,
                    alternatives,
                });
            }
            (desc, path)
        } else {
            // Module-qualified: use direct lookup
            let report_ambiguous = ambiguous_name_warning_is_active(tctx);
            match lookup_constructor_in_module_with_ambiguity(
                lid_txt,
                tctx.arena,
                env,
                &mut tctx.persistent_env,
                tctx.type_ctx,
                Some(expected_ty),
                report_ambiguous,
            ) {
                Some((path, desc, ambiguous_types)) => {
                    // `NameChoice.disambiguate` (typecore.ml:913-918).
                    if !ambiguous_types.is_empty() {
                        tctx.report_warning(
                            lid.loc,
                            Warning::AmbiguousName {
                                names: vec![desc.cstr_name.clone()],
                                types: ambiguous_types,
                                is_label: false,
                            },
                        );
                    }
                    if let Some((expected, alternatives)) = qualified_constructor_type_mismatch(
                        qualified_opath.as_ref(),
                        &desc,
                        expected_ty,
                        env,
                        &mut tctx.persistent_env,
                        tctx.type_ctx,
                    ) {
                        return Err(TypeCoreError::NameTypeMismatch {
                            loc: lid.loc,
                            kind: "variant".to_string(),
                            lid: lid_txt.clone(),
                            expected,
                            alternatives,
                        });
                    }
                    (desc, path)
                }
                // OCaml `Typetexp.find_all_constructors` only reads the
                // qualifying module; a miss is a (narrowed) unbound error.
                None => {
                    return Err(unbound_constructor_lookup_error(
                        tctx, env, lid.loc, lid_txt,
                    ));
                }
            }
        }
    } else {
        // Unqualified: use disambiguation with expected type
        let report_ambiguous = ambiguous_name_warning_is_active(tctx);
        match disambiguate_constructor(
            &lid_name,
            expected_ty,
            env,
            &mut tctx.persistent_env,
            tctx.type_ctx,
            report_ambiguous,
        ) {
            Err(tpath) => {
                return Err(wrong_constructor_name_error(
                    tctx,
                    env,
                    lid.loc,
                    expected_ty,
                    tpath,
                    &lid_name,
                    "This variant pattern is expected to have",
                ));
            }
            Ok(Some(resolution)) => {
                if !resolution.ambiguous_types.is_empty() {
                    tctx.report_warning(
                        lid.loc,
                        Warning::AmbiguousName {
                            names: vec![lid_name.to_string()],
                            types: resolution.ambiguous_types.clone(),
                            is_label: false,
                        },
                    );
                }
                if let ConstructorDisambiguationSource::ExpectedType { tpath } = &resolution.source
                    && resolution.desc.cstr_generalized
                {
                    // typecore.ml:1435-1437 reports at `lid.loc`.
                    return Err(TypeCoreError::UnqualifiedGadtPattern {
                        loc: lid.loc,
                        tpath: *tpath,
                        name: resolution.desc.cstr_name.clone(),
                    });
                }
                (resolution.desc, resolution.path)
            }
            Ok(None) => {
                match lookup_constructor_in_module(
                    lid_txt,
                    tctx.arena,
                    env,
                    &mut tctx.persistent_env,
                    tctx.type_ctx,
                    Some(expected_ty),
                ) {
                    Some((path, desc)) => (desc, path),
                    None => {
                        // `Constructor.disambiguate` with no candidates and no
                        // expected type path: `unbound_name_error`
                        // (typecore.ml:752-760) at the constructor's location.
                        let alternatives = unbound_constructor_alternatives(tctx, env, lid_txt);
                        return Err(TypeCoreError::UnboundConstructor {
                            loc: lid.loc,
                            lid: lid_txt.clone(),
                            alternatives,
                        });
                    }
                }
            }
        }
    };

    // The chosen candidate's `use ()` marks its type (`Env.lookup_all_constructors`,
    // env.ml:1197-1206), then typecore.ml:1392: `Env.mark_constructor
    // Env.Pattern !env (Longident.last lid.txt) constr`.
    mark_type_path_of(tctx.type_ctx, env, cstr_desc.cstr_res);
    // typecore.ml:1444-1445: a generalized constructor of a counter-example
    // typed `Inside_or` splits the or-pattern, so each alternative is typed
    // on its own with GADT unification.
    if cstr_desc.cstr_generalized && state.counter_example && mode == PatternMode::InsideOr {
        return Err(TypeCoreError::NeedBacktrack);
    }
    mark_constructor(
        tctx.type_ctx,
        env,
        crate::types::usage::ConstructorUsage::Pattern,
        &lid_name,
        &cstr_desc,
    );
    // typecore.ml:1393: `Builtin_attributes.check_deprecated loc
    // constr.cstr_attributes constr.cstr_name`.
    record_deprecated_used(tctx, loc, &cstr_desc.cstr_attributes, None)?;
    if let Some(warning) =
        deprecated_warning_from_attrs(&cstr_desc.cstr_name, &cstr_desc.cstr_attributes)
            .map_err(|loc| invalid_escape_at(tctx.type_ctx, loc))?
    {
        tctx.report_warning(loc, warning);
    }
    if !allow_existentials && !cstr_desc.cstr_existentials.is_empty() {
        return Err(TypeCoreError::UnexpectedExistential { loc });
    }

    // typecore.ml Ppat_construct: resolve the syntactic argument grouping
    // against the constructor's arity, then replicate a lone `_`.
    let arity = cstr_desc.cstr_arity;
    let normalized = normalize_constructor_pat_args(tctx.arena, arity, sargs);
    let sargs: Vec<crate::parse_arena::PatIdx> = match normalized.as_slice() {
        [sp] if arity != 1
            && matches!(
                &tctx.arena.get_pat(*sp).ppat_desc,
                crate::parser::ast::PatternDesc::Ppat_any
            ) =>
        {
            if arity == 0 {
                tctx.report_warning(
                    tctx.arena.get_pat(*sp).ppat_loc,
                    Warning::WildcardArgToConstantConstr,
                );
            }
            vec![*sp; arity.max(0) as usize]
        }
        _ => normalized,
    };
    if let [sp] = sargs.as_slice() {
        let sp = tctx.arena.get_pat(*sp);
        if matches!(
            &sp.ppat_desc,
            crate::parser::ast::PatternDesc::Ppat_constant(_)
        ) && has_warn_on_literal_pattern_attribute(&cstr_desc.cstr_attributes)
        {
            tctx.report_warning(sp.ppat_loc, Warning::FragileLiteralPattern);
        }
    }
    if sargs.len() != arity as usize {
        return Err(TypeCoreError::ConstructorArityMismatch {
            loc,
            name: lid_txt.clone(),
            is_inline_record: cstr_desc.cstr_inlined.is_some(),
            expected: arity as usize,
            provided: sargs.len(),
        });
    }

    // Instantiate constructor: creates fresh type variables shared between
    // cstr_res and cstr_args, matching OCaml's Ctype.instance_constructor.
    // For GADT constructors with existentials, process them in pattern context.
    let (inst_arg_types, result_ty) = if !cstr_desc.cstr_existentials.is_empty() {
        if let Some(newtype_lev) = tctx.newtype_level {
            // `instance_constructor ~in_pattern:(env, get_newtype_level ())`
            // (typecore.ml:1574-1577) adds the existentials to the pattern's
            // `env ref`, the one `unify_pat_types_gadt` extends with GADT
            // equations; in Rust that is the unify state's environment.
            match tctx.unify_state.env_mut() {
                Some(pattern_env) => crate::types::instance_constructor_in_pattern(
                    ctx,
                    pattern_env,
                    newtype_lev,
                    &cstr_desc,
                ),
                None => {
                    let mut pattern_env = env.clone();
                    crate::types::instance_constructor_in_pattern(
                        ctx,
                        &mut pattern_env,
                        newtype_lev,
                        &cstr_desc,
                    )
                }
            }
        } else {
            crate::types::instance_constructor(ctx, &cstr_desc)
        }
    } else {
        crate::types::instance_constructor(ctx, &cstr_desc)
    };
    // OCaml compiler/ml/typecore.ml:1523-1527 (PR#7214): use GADT
    // unification only for generalized constructors outside non-split
    // or-patterns and when existentials are allowed.
    if cstr_desc.cstr_generalized && mode != PatternMode::InsideOr && allow_existentials {
        unify_pattern_types_gadt(tctx, loc, result_ty, expected_ty)?;
    } else {
        unify_pattern_types(tctx, loc, result_ty, expected_ty)?;
    }

    // OCaml typecore.ml:1531-1541: an inline record argument may not be
    // constrained, directly or under an or-pattern or alias.
    if cstr_desc.cstr_inlined.is_some() {
        fn check_non_escaping(arena: &ParseArena, pat: &ParsedPattern) -> TypeCoreResult<()> {
            match &pat.ppat_desc {
                crate::parser::ast::PatternDesc::Ppat_or(p1, p2) => {
                    check_non_escaping(arena, arena.get_pat(*p1))?;
                    check_non_escaping(arena, arena.get_pat(*p2))
                }
                crate::parser::ast::PatternDesc::Ppat_alias(inner, _) => {
                    check_non_escaping(arena, arena.get_pat(*inner))
                }
                crate::parser::ast::PatternDesc::Ppat_constraint(..) => {
                    Err(TypeCoreError::InlinedRecordEscape { loc: pat.ppat_loc })
                }
                _ => Ok(()),
            }
        }
        for sp in &sargs {
            check_non_escaping(tctx.arena, tctx.arena.get_pat(*sp))?;
        }
    }

    // `map_fold_cont (fun (p, t) -> type_pat p t) (List.combine sargs ty_args)`.
    let mut typed_args = Vec::with_capacity(sargs.len());
    for (sp, arg_ty) in sargs.iter().zip(inst_arg_types.iter()) {
        let arg_pat = tctx.arena.get_pat(*sp);
        typed_args.push(type_pattern_inner(
            tctx, env, arg_pat, *arg_ty, options, state, explode,
        )?);
    }

    Ok({
        let typed_node = Pattern::new(
            PatternDesc::Tpat_construct(
                *lid,
                Arc::new(cstr_desc),
                tctx.typed.push_patterns(typed_args),
            ),
            loc,
            expected_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
    })
}

fn variant_payload_type_from_expected(
    ctx: &TypeContext,
    env: &Env,
    label: &str,
    expected_ty: TypeExprRef,
) -> Option<TypeExprRef> {
    let expanded_expected = crate::types::ctype::expand_head(ctx, env, expected_ty);
    let expected_desc = ctx.get_desc(ctx.repr(expanded_expected));
    match &*expected_desc {
        TypeDesc::Tvariant(row) => {
            let row = crate::types::btype::row_repr(ctx, &ctx.row_desc(row));
            row.row_fields
                .iter()
                .find(|(field_label, _)| field_label == label)
                .and_then(
                    |(_, field)| match crate::types::btype::row_field_repr(ctx, field) {
                        crate::types::type_expr::RowField::Rpresent(Some(ty)) => Some(ty),
                        crate::types::type_expr::RowField::Reither { types, .. } => {
                            types.first().copied().filter(|_| types.len() == 1)
                        }
                        _ => None,
                    },
                )
        }
        _ => None,
    }
}

/// Type check polymorphic variant pattern.
#[allow(clippy::too_many_arguments)]
fn type_pattern_variant(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    label: &str,
    arg: Option<&ParsedPattern>,
    expected_ty: TypeExprRef,
    options: PatternOptions,
    state: &mut PatternState,
    explode: i32,
    pat: &ParsedPattern,
) -> TypeCoreResult<Pattern> {
    use crate::types::typedtree::RowDescRef;
    let ctx = tctx.type_ctx;

    // Match OCaml typecore.ml Ppat_variant:
    // - always build a single-tag row with Reither
    // - use `constant = (arg is None)`
    // - thread payload type into the row when present
    let expected_payload_ty =
        arg.and_then(|_| variant_payload_type_from_expected(ctx, env, label, expected_ty));
    let arg_ty = arg.map(|_| expected_payload_ty.unwrap_or_else(|| ctx.new_var(None)));
    let mut row_arg_types = Vec::new();
    if let Some(ty) = arg_ty {
        row_arg_types.push(ty);
    }
    let variant_ty = ctx.new_variant(crate::types::type_expr::RowDesc {
        row_fields: vec![(
            label.to_string().into(),
            crate::types::type_expr::RowField::Reither {
                constant: arg.is_none(),
                types: row_arg_types,
                matched: true,
                link: ctx.alloc_row_field(None),
            },
        )]
        .into(),
        row_more: ctx.new_var(None),
        row_closed: false,
        row_fixed: false,
        row_name: None,
    });
    unify_pattern_types(tctx, loc, variant_ty, expected_ty)?;

    let typed_arg = match (arg, arg_ty) {
        (Some(arg_pat), Some(arg_ty)) => Some(Box::new(type_pattern_inner(
            tctx, env, arg_pat, arg_ty, options, state, explode,
        )?)),
        _ => None,
    };

    Ok({
        let typed_node = Pattern::new(
            PatternDesc::Tpat_variant(
                label.to_string(),
                typed_arg.map(|p| tctx.typed.push_pattern(*p)),
                RowDescRef(0),
            ),
            loc,
            expected_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
    })
}

fn find_pattern_record_qual(
    arena: &ParseArena,
    fields: &[crate::parser::ast::PatternRecordField],
) -> Option<Longident> {
    for field in fields {
        if let Longident::Ldot(module_lid, _) = arena.get_longident(field.lid.txt) {
            return Some((**module_lid).clone());
        }
    }
    None
}

fn qualify_unqualified_pattern_record_fields(
    tctx: &mut TypeCheckContext<'_>,
    fields: &[crate::parser::ast::PatternRecordField],
) -> Vec<crate::parser::ast::PatternRecordField> {
    let Some(module_qualifier) = find_pattern_record_qual(tctx.arena, fields) else {
        return fields.to_vec();
    };

    let mut rewritten = Vec::with_capacity(fields.len());
    for field in fields {
        let mut field = *field;
        if let Longident::Lident(field_name) = tctx.arena.get_longident(field.lid.txt) {
            let qualified = Longident::Ldot(Box::new(module_qualifier.clone()), *field_name);
            let qualified_idx = tctx.arena.push_typecheck_longident(qualified);
            field.lid = Located {
                txt: qualified_idx,
                loc: field.lid.loc,
            };
        }
        rewritten.push(field);
    }
    rewritten
}

/// The error `Label.disambiguate` raises for a record pattern field whose
/// label is not found: `Wrong_name` against the expected record type for an
/// unqualified label, an unbound label otherwise.
fn record_pattern_unresolved_label_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    record_ty: TypeExprRef,
    expected_ty: TypeExprRef,
    lid: &Located<LidentIdx>,
    field_name: String,
) -> TypeCoreError {
    let ctx = tctx.type_ctx;
    let field_lid_for_error = tctx.arena.get_longident(lid.txt).clone();
    // A qualified label that is not in its module is unbound
    // (OCaml `lookup_from_type` only matches unqualified labels).
    if !matches!(field_lid_for_error, Longident::Ldot(..))
        && let Some(path) = extract_type_path_from_expected_with_persistent_env(
            record_ty,
            env,
            &mut tctx.persistent_env,
            ctx,
        )
    {
        let decl = lookup_type_decl_for_path(&path, env, &mut tctx.persistent_env, ctx);
        let (alternatives, jsx_component_info) = match decl
            .as_ref()
            .map(|decl| (&decl.type_kind, &decl.type_attributes))
        {
            Some((crate::types::TypeKind::TypeRecord(labels, _), attrs)) => (
                labels
                    .iter()
                    .map(|label| label.ld_id.name().to_string())
                    .collect::<Vec<_>>(),
                // `Typecore.report_error`'s `Wrong_name` asks
                // `get_jsx_component_props` (typecore.ml:4950-4954).
                jsx_prop_error_info_from_record_parts(&path, labels, attrs),
            ),
            _ => (Vec::new(), None),
        };
        return TypeCoreError::WrongName {
            loc: lid.loc,
            kind: "record",
            ty: expected_ty,
            expected: "This record pattern is expected to have",
            path,
            name: field_name,
            alternatives,
            jsx_component_info: jsx_component_info.map(Box::new),
            env: Some(tctx.type_ctx.store_typed_env(env)),
        };
    }
    // `Typetexp.find_all_labels` goes through `find_component`, whose
    // `narrow_unbound_lid_error` (typetexp.ml:64-86) reports a missing
    // module prefix first.
    if let Some(err) = unbound_module_prefix_error(tctx, env, lid.loc, &field_lid_for_error) {
        return err;
    }
    TypeCoreError::UnboundRecordField {
        loc: lid.loc,
        field_name: tctx.longident_to_string(&field_lid_for_error),
        from_type: None,
        // OCaml compiler/ml/typecore.ml:1118-1119 raises the unbound-label
        // error from label disambiguation; spelling suggestions are produced
        // only while reporting Typetexp.Unbound_label at
        // compiler/ml/typetexp.ml:916-959.
        alternatives: unbound_label_alternatives(
            tctx.arena,
            env,
            &mut tctx.persistent_env,
            ctx,
            &field_lid_for_error,
        ),
    }
}

/// Type check record pattern.
#[allow(clippy::too_many_arguments)]
fn type_pattern_record(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    fields: &[crate::parser::ast::PatternRecordField],
    closed_flag: crate::parser::ast::ClosedFlag,
    record_rest: Option<&crate::parser::ast::RecordPatRest>,
    expected_ty: TypeExprRef,
    options: PatternOptions,
    state: &mut PatternState,
    explode: i32,
    pat: &ParsedPattern,
) -> TypeCoreResult<Pattern> {
    let ctx = tctx.type_ctx;
    check_no_record_syntax_on_dict(
        tctx,
        env,
        loc,
        expected_ty,
        fields.first().map(|field| field.lid.txt),
    )?;
    let record_rest = record_rest.cloned();
    let fields = qualify_unqualified_pattern_record_fields(tctx, fields);

    // OCaml Ppat_record (typecore.ml:1502-1511): `opath`/`record_ty` come
    // from `extract_concrete_record env expected_ty`; a non-record expected
    // type gives `(None, newvar ())`, unified with `expected_ty` after the
    // labels (typecore.ml:1560).
    let record_is_concrete =
        extract_concrete_record_type_info(expected_ty, env, &mut tctx.persistent_env, ctx)
            .is_some();
    let record_ty = if record_is_concrete {
        expected_ty
    } else {
        ctx.new_var(None)
    };

    struct PendingRecordPatternField {
        lid: Located<LidentIdx>,
        pat: crate::parse_arena::PatIdx,
        opt: bool,
        field_name: crate::name::Name,
        source_pos: i32,
        label: Option<crate::types::LabelDescription>,
    }

    let arena = tctx.arena;
    let field_names: smallvec::SmallVec<[&str; 8]> = fields
        .iter()
        .map(|field| arena.get_string(arena.get_longident(field.lid.txt).last_idx()))
        .collect();
    let report_ambiguous_label_warnings = tctx.warning_config.is_active(&Warning::AmbiguousName {
        names: Vec::new(),
        types: Vec::new(),
        is_label: true,
    });
    let mut ambiguous_label_warnings: Vec<(String, Vec<String>, Option<Path>)> = Vec::new();
    let mut pending_fields = Vec::new();
    for (idx, field) in fields.iter().enumerate() {
        let resolved_lid = tctx.resolve_lid(field.lid.txt).clone();
        let field_name = tctx.longident_last_name(&resolved_lid);
        // `process_label` (typecore.ml:1028-1029): with no `opath`, a label
        // with nothing in scope is unbound.
        if !record_is_concrete
            && matches!(resolved_lid, Longident::Lident(_))
            && env.find_all_labels(field_name).is_empty()
            && !tctx
                .generated_pattern_labels
                .iter()
                .any(|(name, _)| name == &field_name)
        {
            return Err(TypeCoreError::UnboundRecordField {
                loc: field.lid.loc,
                field_name: tctx.longident_to_string(&resolved_lid),
                from_type: None,
                alternatives: unbound_label_alternatives(
                    tctx.arena,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                    &resolved_lid,
                ),
            });
        }

        // `Label.disambiguate` with the expected type's path: a qualified
        // label of another type raises `Name_type_mismatch`
        // (typecore.ml:925-939).
        if let Some(err) = qualified_label_name_type_mismatch(
            field.lid.loc,
            &resolved_lid,
            tctx.arena,
            env,
            &mut tctx.persistent_env,
            ctx,
            record_ty,
        ) {
            return Err(err);
        }
        // `process_label` (typecore.ml:1063-1073): with no `opath` the label
        // scope is first reduced by every field name of the pattern
        // (`disambiguate_label_by_ids`, record patterns pass `closed = false`),
        // and `Label.disambiguate` then takes the first remaining label.
        let by_ids_label = if !record_is_concrete {
            let module_labels = match &resolved_lid {
                Longident::Ldot(module_lid, _) => with_resolved_module_components_for_lid(
                    module_lid,
                    tctx.arena,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                    |components| components.lookup_labels(&field_name, ctx).as_ref().clone(),
                )
                .unwrap_or_default(),
                _ => Vec::new(),
            };
            let scope: Vec<&crate::types::LabelDescription> = match &resolved_lid {
                Longident::Ldot(..) => module_labels.iter().collect(),
                _ => env.find_all_labels(field_name),
            };
            disambiguate_label_by_ids(
                scope,
                &field_names,
                false,
                env,
                &mut tctx.persistent_env,
                ctx,
            )
            .first()
            .map(|label| (*label).clone())
        } else {
            None
        };
        // Try to look up the label from the environment for type info
        let disambiguated = tctx
            .generated_pattern_labels
            .iter()
            .rev()
            .find(|(name, _)| name == &field_name)
            .map(|(_, label)| (**label).clone())
            .or(by_ids_label)
            .or_else(|| {
                lookup_label_by_lid(
                    tctx,
                    &resolved_lid,
                    Some(field.lid.loc),
                    env,
                    Some(record_ty),
                    None,
                )
            })
            .or_else(|| {
                // OCaml `lookup_from_type` (typecore.ml:852-891) only matches
                // unqualified labels; a qualified miss stays unbound.
                if matches!(resolved_lid, Longident::Ldot(..)) {
                    return None;
                }
                disambiguate_label(
                    &field_name,
                    record_ty,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                )
            });

        let label = disambiguated;
        // `Label.disambiguate ~warn` with no `opath` (typecore.ml:910-918),
        // collected by `disambiguate_record_elem_list` (typecore.ml:1010-1016);
        // record patterns pass `closed = false` (typecore.ml:1551).
        if report_ambiguous_label_warnings
            && !record_is_concrete
            && let Some(label) = label.as_ref()
        {
            // `Typetexp.find_all_labels`: the labels in scope, or the
            // qualifying module's labels for a qualified name.
            let module_labels = match &resolved_lid {
                Longident::Ldot(module_lid, _) => with_resolved_module_components_for_lid(
                    module_lid,
                    tctx.arena,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                    |components| components.lookup_labels(&field_name, ctx).as_ref().clone(),
                )
                .unwrap_or_default(),
                _ => Vec::new(),
            };
            let candidates: Vec<&crate::types::LabelDescription> = match &resolved_lid {
                Longident::Ldot(..) => module_labels.iter().collect(),
                _ => env.find_all_labels(field_name),
            };
            if candidates.len() > 1
                && let Some(candidates) = reduce_record_label_scope_by_ids(
                    candidates,
                    &field_names,
                    false,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                )
                && let Some((types, selected_path)) = ambiguous_record_label_warning_info(
                    label,
                    &candidates,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                )
            {
                ambiguous_label_warnings.push((field_name.to_string(), types, selected_path));
            }
        }

        // `Label.disambiguate` calls the chosen label's `use ()`, which marks
        // its type and, for a label in scope through an `open`, that open
        // (`Env.lookup_all_labels`, env.ml:1230-1238; typecore.ml:912-922).
        if let Some(label) = label.as_ref() {
            mark_type_path_of(ctx, env, label.lbl_res);
            let generated = tctx
                .generated_pattern_labels
                .iter()
                .any(|(name, _)| name == &field_name);
            if matches!(resolved_lid, Longident::Lident(_)) && !generated {
                use_in_scope_label_of_type(ctx, env, field_name.as_str(), label);
            }
        }
        pending_fields.push(PendingRecordPatternField {
            lid: field.lid,
            pat: field.pat,
            opt: field.opt,
            field_name,
            source_pos: idx as i32,
            label,
        });
    }

    if report_ambiguous_label_warnings {
        emit_ambiguous_record_label_warnings(tctx, env, loc, ambiguous_label_warnings);
    }

    // OCaml `disambiguate_record_elem_list` (typecore.ml:1000-1021) resolves
    // every label, raising `Wrong_name`/unbound-label errors, before
    // `type_record_elem_list` sorts the fields and types their patterns.
    if let Some(field) = pending_fields.iter().find(|field| field.label.is_none()) {
        return Err(record_pattern_unresolved_label_error(
            tctx,
            env,
            record_ty,
            expected_ty,
            &field.lid,
            field.field_name.to_string(),
        ));
    }

    // OCaml compiler/ml/typecore.ml:1163-1200 resolves record labels, sorts
    // `lbl_a_list` by `lbl_pos`, then `map_fold_cont type_lbl_a` types the
    // field patterns. Allocate field variables and bind subpatterns in that
    // sorted order so identifier stamps follow declaration order rather than
    // source field order.
    pending_fields.sort_by_key(|field| {
        field
            .label
            .as_ref()
            .map(|label| label.lbl_pos)
            .unwrap_or(field.source_pos)
    });

    let mut typed_fields = Vec::new();
    for field in pending_fields {
        let field_lid_for_error = tctx.arena.get_longident(field.lid.txt).clone();
        let (label_desc, field_ty, poly_vars, force_label_arg_paths) =
            if let Some(env_label) = field.label {
                if field.opt && !env_label.lbl_optional {
                    return Err(TypeCoreError::FieldNotOptional {
                        loc: tctx.arena.get_pat(field.pat).ppat_loc,
                        name: env_label.lbl_name.to_string(),
                        typ: env_label.lbl_res,
                    });
                }
                // OCaml compiler/ml/typecore.ml:1623-1632 `type_label_pat`
                // creates `(vars, ty_arg, ty_res) = instance_label false label`,
                // unifies `ty_res` with the record type, then types the field
                // pattern directly against `ty_arg`. Do not insert an extra fresh
                // field variable here; that changes both sharing and lazy forcing.
                // The label already carries its `lbl_all` array there; Rust
                // populates the exact-path raw-lambda cache after all field
                // binders are allocated below, preserving OCaml's binder-before-
                // bookkeeping order from typecore.ml:1623-1644.
                ctx.begin_def();
                let (vars, ty_arg, ty_res) =
                    crate::types::ctype::instance_label(ctx, false, &env_label);
                if vars.is_empty() {
                    ctx.end_def();
                }
                // OCaml typecore.ml:1538 `unify_pat_types loc !env ty_res
                // record_ty` raises `Pattern_type_clash` at the record pattern.
                if let Err(err) = unify_pattern_types(tctx, loc, ty_res, record_ty) {
                    if !vars.is_empty() {
                        ctx.end_def();
                    }
                    return Err(err);
                }
                (env_label, ty_arg, vars, true)
            } else {
                return Err(record_pattern_unresolved_label_error(
                    tctx,
                    env,
                    record_ty,
                    expected_ty,
                    &field.lid,
                    field.field_name.to_string(),
                ));
            };

        // process_optional_label: if the label is optional and the user did NOT write '?',
        // wrap the pattern in Some(...) before type checking.
        // This matches OCaml's typecore.ml process_optional_label behavior.
        let parsed_pat = tctx.arena.get_pat(field.pat);
        // `is_from_parmatch`: Parmatch counter-examples already carry the
        // optional layer as a `#$` constructor.
        let is_from_pamatch = is_from_parmatch(tctx.arena, parsed_pat);
        let typed_pat = if label_desc.lbl_optional && !field.opt && !is_from_pamatch {
            // field_ty is option<T> — extract T to type-check the inner pattern
            let inner_ty =
                crate::types::ctype::extract_option_type(ctx, field_ty).unwrap_or(field_ty);
            let typed_inner =
                type_pattern_inner(tctx, env, parsed_pat, inner_ty, options, state, explode)?;
            // Wrap in Tpat_construct("Some", [typed_inner]) with type option<T>.
            // typecore.ml:1529 builds the constructor with
            // `mknoloc (Ldot (Lident "*predef*", "Some"))`.
            let some_lid = Located {
                txt: tctx.arena.predef_some_lid(),
                loc: tctx.arena.none_loc(),
            };
            let some_cstr = make_some_constructor(ctx);
            Pattern::new(
                PatternDesc::Tpat_construct(
                    some_lid,
                    Arc::new(some_cstr),
                    tctx.typed.push_patterns(vec![typed_inner]),
                ),
                parsed_pat.ppat_loc,
                field_ty,
                tctx.type_ctx.store_typed_env(env),
            )
        } else {
            type_pattern_inner(tctx, env, parsed_pat, field_ty, options, state, explode)?
        };
        if force_label_arg_paths {
            // OCaml compiler/ml/typecore.ml:1192-1198 and
            // compiler/ml/typecore.ml:1623-1644 allocate all binders in the
            // surrounding pattern before nested label argument paths force
            // additional module signatures. The top-level `type_pattern` drains
            // this queue after tuple/constructor siblings have been typed.
            state.defer_type_path_force(field_ty);
        }
        if !poly_vars.is_empty() {
            ctx.end_def();
            crate::types::generalize(ctx, field_ty);
            for var in &poly_vars {
                crate::types::generalize(ctx, *var);
            }
            for var in &poly_vars {
                let expanded = crate::types::ctype::expand_head(ctx, env, *var);
                let desc = ctx.get_desc(ctx.repr(expanded));
                let instantiated = !matches!(&*desc, TypeDesc::Tvar(..))
                    || ctx.get_level(ctx.repr(expanded)) != crate::types::GENERIC_LEVEL;
                if instantiated {
                    return Err(TypeCoreError::PolymorphicLabel {
                        loc: field.lid.loc,
                        lid: field_lid_for_error.clone(),
                    });
                }
            }
        }
        typed_fields.push((field.lid, Arc::new(label_desc), typed_pat, field.opt));
    }

    // Invariant: records are sorted in the typed tree (by label position)
    // Matches OCaml typecore.ml: List.sort (fun (_, lbl1, _, _) (_, lbl2, _, _) -> compare lbl1.lbl_pos lbl2.lbl_pos)
    typed_fields.sort_by_key(|(_, label_desc, _, _)| label_desc.lbl_pos);

    // OCaml `check_recordpat_labels` (compiler/ml/typecore.ml:1113-1133): a label
    // bound twice is an error reported at the first field's label location.
    if let Some((first_lid, _, _, _)) = typed_fields.first() {
        let first_loc = first_lid.loc;
        let mut defined = HashSet::new();
        for (_, label_desc, _, _) in &typed_fields {
            if !defined.insert(label_desc.lbl_pos) {
                return Err(TypeCoreError::LabelMultiplyDefined {
                    loc: first_loc,
                    label: label_desc.lbl_name.to_string(),
                    jsx_component_info: None,
                });
            }
        }
    }

    // compiler/ml/typecore.ml uses Open for the missing-field check whenever a
    // rest binding is present, while retaining the parsed closed flag in the
    // typed tree.
    // `check_recordpat_labels` (typecore.ml:1113-1117) does nothing for an
    // empty label list.
    if closed_flag == crate::parser::ast::ClosedFlag::Closed
        && record_rest.is_none()
        && !typed_fields.is_empty()
    {
        let mut present = HashSet::new();
        for (_, label_desc, _, _) in &typed_fields {
            present.insert(label_desc.lbl_name);
        }
        if let Some(all_labels) = typed_fields
            .first()
            .and_then(|(_, label_desc, _, _)| {
                get_record_labels(ctx, env, &mut tctx.persistent_env, label_desc.lbl_res)
            })
            .or_else(|| get_record_labels(ctx, env, &mut tctx.persistent_env, record_ty))
            .or_else(|| get_record_labels(ctx, env, &mut tctx.persistent_env, expected_ty))
        {
            let missing = all_labels
                .iter()
                .filter_map(|label| {
                    let name = label.ld_id.name();
                    (!present.contains(&crate::name::Name::new(name))).then(|| name.to_string())
                })
                .collect::<Vec<_>>();
            if !missing.is_empty() {
                tctx.report_warning(
                    loc,
                    Warning::NonClosedRecordPattern {
                        fields: missing.join(", "),
                    },
                );
            }
        }
    }

    // OCaml `k'` (typecore.ml:1551-1561): `check_recordpat_labels`, then
    // unify the inferred record type with the pattern expected type.
    unify_pattern_types(tctx, loc, record_ty, expected_ty)?;

    let typed_rest = match record_rest {
        Some(rest) => Some(type_record_pat_rest(
            tctx,
            env,
            loc,
            record_ty,
            &typed_fields,
            rest,
            state,
        )?),
        None => None,
    };

    Ok({
        let typed_node = Pattern::new(
            PatternDesc::Tpat_record(
                typed_fields
                    .into_iter()
                    .map(|(lid, lbl, field_pat, optional)| {
                        (lid, lbl, tctx.typed.push_pattern(field_pat), optional)
                    })
                    .collect(),
                closed_flag,
                typed_rest.map(Box::new),
            ),
            loc,
            expected_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_pat_attributes(typed_node, pat.ppat_attributes.clone())
    })
}

// ============================================================================
// Record-rest patterns (`...Type.t as name`)
// Port of compiler/ml/typecore_record_rest.ml.
// ============================================================================

/// Errors for record-rest pattern typing (compiler/ml/typecore_record_rest.ml
/// `type error`).
#[derive(Debug, Clone)]
pub enum RecordRestError {
    InvalidType,
    RequiresTypeAnnotation(String),
    NotRecord(Longident),
    FieldNotOptional(Vec<String>, Longident),
    FieldMissing(Vec<String>, Longident),
    ExtraField(String, Longident),
    FieldRuntimeNameMismatch {
        field: String,
        rest_type: Longident,
        source_runtime_name: String,
        rest_runtime_name: String,
    },
    UnboxedRecord,
    ArrayRecord,
    MutableSourceRecord,
}

impl RecordRestError {
    /// compiler/ml/typecore_record_rest.ml `report_error`.
    pub fn message(&self, arena: &ParseArena) -> String {
        let format_lid = |lid: &Longident| {
            fn loop_(arena: &ParseArena, lid: &Longident) -> String {
                match lid {
                    Longident::Lident(name) => arena.get_string(*name).to_string(),
                    Longident::Ldot(parent, name) => {
                        format!("{}.{}", loop_(arena, parent), arena.get_string(*name))
                    }
                    Longident::Lapply(functor, argument) => {
                        format!("{}({})", loop_(arena, functor), loop_(arena, argument))
                    }
                }
            }
            loop_(arena, lid)
        };
        match self {
            RecordRestError::InvalidType => {
                "Record rest pattern must have the form: ...Type.t as name".to_string()
            }
            RecordRestError::RequiresTypeAnnotation(name) => format!(
                "Record rest pattern `...{name}` requires a type annotation. Use `...Type.t as {name}`."
            ),
            RecordRestError::NotRecord(lid) => format!(
                "Type {} is not a record type and cannot be used as a record rest pattern.",
                format_lid(lid)
            ),
            RecordRestError::FieldNotOptional(fields, lid) => {
                let field_list = fields
                    .iter()
                    .map(|field| format!("\n- {field}"))
                    .collect::<String>();
                if fields.len() == 1 {
                    format!(
                        "The following field appears in both the explicit pattern and the rest type `{}`:{}\n\n\
                         This is not type-safe because the field would always be absent from \
                         the rest value. Remove it from the rest type, or match it as optional \
                         if absence is intended.",
                        format_lid(lid),
                        field_list
                    )
                } else {
                    format!(
                        "The following fields appear in both the explicit pattern and the rest type `{}`:{}\n\n\
                         This is not type-safe because these fields would always be absent \
                         from the rest value. Remove them from the rest type, or match them as \
                         optional if absence is intended.",
                        format_lid(lid),
                        field_list
                    )
                }
            }
            RecordRestError::FieldMissing(fields, lid) => {
                let field_list = fields
                    .iter()
                    .map(|field| format!("\n- {field}"))
                    .collect::<String>();
                if fields.len() == 1 {
                    format!(
                        "The following field is not part of the rest type `{}`:{}\n\n\
                         List this field in the record pattern before the spread so it's not \
                         present in the rest record.",
                        format_lid(lid),
                        field_list
                    )
                } else {
                    format!(
                        "The following fields are not part of the rest type `{}`:{}\n\n\
                         List these fields in the record pattern before the spread so they're \
                         not present in the rest record.",
                        format_lid(lid),
                        field_list
                    )
                }
            }
            RecordRestError::ExtraField(field, lid) => format!(
                "Field `{field}` in the rest type `{}` does not exist in the source record type.",
                format_lid(lid)
            ),
            RecordRestError::FieldRuntimeNameMismatch {
                field,
                source_runtime_name,
                rest_type,
                rest_runtime_name,
            } => format!(
                "Field `{field}` in the rest type `{}` has runtime representation `{rest_runtime_name}`, but \
                 in the source record type it is `{source_runtime_name}`. Runtime representations must \
                 match.",
                format_lid(rest_type)
            ),
            RecordRestError::UnboxedRecord => {
                "Record rest patterns cannot be used with unboxed record types.".to_string()
            }
            RecordRestError::ArrayRecord => "The rest of a record pattern cannot have a record type \
                 represented as an array (fields with the runtime names \"0\", \"1\", ...)."
                .to_string(),
            RecordRestError::MutableSourceRecord => {
                "Record rest patterns cannot be used on records with mutable fields.".to_string()
            }
        }
    }
}

/// Ctype.extract_concrete_typedecl (compiler/ml/ctype.ml:1248-1261) followed by
/// instance_declaration and param/arg unification
/// (compiler/ml/typecore_record_rest.ml
/// `extract_instantiated_concrete_typedecl`). Returns `None` on `Not_found`.
fn record_rest_extract_instantiated_concrete_typedecl(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    unify_loc: LocIdx,
    ty: TypeExprRef,
) -> TypeCoreResult<Option<crate::types::decl::TypeDeclaration>> {
    let ctx = tctx.type_ctx;
    // OCaml matches on `repr ty`.desc; non-Tconstr raises Not_found.
    let repr = ctx.repr(ty);
    let mut current_path = match &*ctx.get_desc(repr) {
        TypeDesc::Tconstr { path, .. } => *path,
        _ => return Ok(None),
    };

    loop {
        let decl = match lookup_type_decl_for_path(
            &current_path,
            env,
            &mut tctx.persistent_env,
            tctx.type_ctx,
        ) {
            Some(decl) => decl,
            None => return Ok(None),
        };
        if !matches!(decl.type_kind, crate::types::TypeKind::TypeAbstract) {
            // Unify the instantiated declaration params against the head args.
            let ctx = tctx.type_ctx;
            let repr = ctx.repr(ty);
            let args = match &*ctx.get_desc(repr) {
                TypeDesc::Tconstr { args, .. } => ctx.type_list(args).to_vec(),
                _ => Vec::new(),
            };
            let inst = crate::types::ctype::instance_declaration(tctx.type_ctx, &decl);
            if inst.type_params.len() == args.len() {
                for (param, arg) in inst.type_params.iter().zip(args.iter()) {
                    unify_pattern_types(tctx, unify_loc, *param, *arg)?;
                }
            }
            return Ok(Some(inst));
        }
        // Expand one step; Cannot_expand maps to Not_found.
        let ctx = tctx.type_ctx;
        let expanded = {
            let repr = ctx.repr(ty);
            match crate::types::ctype::expand_head_once(ctx, env, repr) {
                Some(next) => next,
                None => return Ok(None),
            }
        };
        let ctx = tctx.type_ctx;
        let next_repr = ctx.repr(expanded);
        let next_path = match &*ctx.get_desc(next_repr) {
            TypeDesc::Tconstr { path, .. } => *path,
            _ => return Ok(None),
        };
        if next_path == current_path {
            return Ok(None);
        }
        current_path = next_path;
    }
}

/// compiler/ml/typecore_record_rest.ml `source_fields_and_repr`. Returns the
/// source labels plus an optional inlined-record tag name to exclude at
/// runtime (`runtime_excluded_labels`).
fn record_rest_source_fields_and_repr(
    type_ctx: &crate::types::TypeContext,
    decl: &crate::types::decl::TypeDeclaration,
) -> Result<(Vec<crate::types::decl::LabelDeclaration>, Option<String>), RecordRestError> {
    match &decl.type_kind {
        crate::types::TypeKind::TypeRecord(
            _,
            crate::types::RecordRepresentation::RecordUnboxed(_),
        ) => Err(RecordRestError::UnboxedRecord),
        crate::types::TypeKind::TypeRecord(labels, repr) => {
            if labels
                .iter()
                .any(|field| field.ld_mutable == crate::types::asttypes::MutableFlag::Mutable)
            {
                Err(RecordRestError::MutableSourceRecord)
            } else {
                // compiler/ml/typecore_record_rest.ml runtime_excluded_labels:
                // only non-untagged inlined records contribute a tag exclusion.
                let tag_exclusion = match repr {
                    crate::types::RecordRepresentation::RecordInlined {
                        representation, ..
                    } => match representation.representation(type_ctx) {
                        crate::types::VariantConstructorCase::Block(
                            crate::types::VariantBlock::Tagged(block),
                        ) => Some(block.tag_name.unwrap_or_else(|| "TAG".to_string())),
                        crate::types::VariantConstructorCase::Constant(_)
                        | crate::types::VariantConstructorCase::Block(_) => None,
                    },
                    _ => None,
                };
                Ok((labels.to_vec(), tag_exclusion))
            }
        }
        // OCaml raises assert false here; callers only pass record declarations.
        _ => Err(RecordRestError::InvalidType),
    }
}

/// compiler/ml/typecore_record_rest.ml `runtime_excluded_labels`.
fn record_rest_excluded_labels(
    explicit_runtime_labels: Vec<String>,
    tag_exclusion: Option<String>,
) -> Vec<String> {
    match tag_exclusion {
        None => explicit_runtime_labels,
        Some(tag_name) => {
            if explicit_runtime_labels.contains(&tag_name) {
                explicit_runtime_labels
            } else {
                let mut out = Vec::with_capacity(explicit_runtime_labels.len() + 1);
                out.push(tag_name);
                out.extend(explicit_runtime_labels);
                out
            }
        }
    }
}

/// Type a record-rest pattern. Port of
/// compiler/ml/typecore_record_rest.ml `type_record_pat_rest`.
#[allow(clippy::too_many_arguments)]
fn type_record_pat_rest(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    record_ty: TypeExprRef,
    lbl_pat_list: &[(
        Located<LidentIdx>,
        std::sync::Arc<crate::types::LabelDescription>,
        Pattern,
        bool,
    )],
    rest: crate::parser::ast::RecordPatRest,
    state: &mut PatternState,
) -> TypeCoreResult<crate::types::typedtree::RecordPatternRest> {
    let rest_err =
        |loc: LocIdx, error: RecordRestError| Err(TypeCoreError::RecordRest { loc, error });
    let rest_loc = rest.rest_loc;

    // The annotation is required and must be a constructor type.
    let Some(core_type_idx) = rest.rest_type else {
        let name = tctx.arena.get_string(rest.rest_name.txt).to_string();
        return rest_err(rest_loc, RecordRestError::RequiresTypeAnnotation(name));
    };
    let core_type = tctx.arena.get_core_type(core_type_idx);
    let (rest_type_lid, rest_type_args_syntax): (
        Located<LidentIdx>,
        Vec<crate::parse_arena::CoreTypeIdx>,
    ) = match &core_type.ptyp_desc {
        crate::parser::ast::CoreTypeDesc::Ptyp_constr(inner) => {
            let (lid, args) = inner;
            (*lid, tctx.arena.type_list(*args).to_vec())
        }
        _ => return rest_err(rest_loc, RecordRestError::InvalidType),
    };
    let rest_type_longident = tctx.resolve_lid(rest_type_lid.txt).clone();

    // Typetexp.find_type env rest_type_lid.loc rest_type_lid.txt
    // (typecore_record_rest.ml:133-134).
    let (rest_path, rest_annotation_decl) =
        find_type_for_lid(tctx, env, rest_type_lid.loc, &rest_type_longident)?;
    let rest_annotation_decl =
        crate::types::ctype::instance_declaration(tctx.type_ctx, &rest_annotation_decl);

    // type_args_from_annotation.
    let ctx = tctx.type_ctx;
    let rest_type_args: Vec<TypeExprRef> = if rest_type_args_syntax.is_empty() {
        rest_annotation_decl
            .type_params
            .iter()
            .map(|_| ctx.new_var(None))
            .collect()
    } else {
        let n_args = rest_type_args_syntax.len();
        let n_params = rest_annotation_decl.type_params.len();
        if n_args != n_params {
            return Err(TypeCoreError::TypeArityMismatch {
                loc: rest_type_lid.loc,
                lid: rest_type_longident.clone(),
                expected: n_params,
                provided: n_args,
            });
        }
        let mut args_out = Vec::with_capacity(n_args);
        for sty_idx in &rest_type_args_syntax {
            let sty = tctx.arena.get_core_type(*sty_idx).clone();
            let (_ctyp, cty_ty, force) = transl_type_delayed(tctx, env, &sty, true)?;
            // OCaml appends the returned force to `pattern_force`
            // (typecore_record_rest.ml:69-70); the Rust PatternState drains
            // deferred forces after binder allocation.
            state.add_globalize_forces(force);
            state.defer_type_path_force(cty_ty);
            args_out.push(cty_ty);
        }
        args_out
    };

    // Btype.newgenty (Tconstr (rest_path, rest_type_args, ref Mnil)).
    let rest_type_expr = tctx
        .type_ctx
        .new_constr(rest_path, rest_type_args.clone());

    // check_not_private for the annotation declaration.
    if rest_annotation_decl.type_private == crate::types::asttypes::PrivateFlag::Private {
        return Err(TypeCoreError::PrivateType {
            loc: rest_type_lid.loc,
            ty: rest_type_expr,
        });
    }

    // Unify annotation declaration params with the supplied args.
    if rest_annotation_decl.type_params.len() == rest_type_args.len() {
        for (param, arg) in rest_annotation_decl
            .type_params
            .iter()
            .zip(rest_type_args.iter())
        {
            unify_pattern_types(tctx, rest_type_lid.loc, *param, *arg)?;
        }
    }

    // Extract the instantiated concrete typedecl behind the rest annotation.
    let rest_extract = match record_rest_extract_instantiated_concrete_typedecl(
        tctx,
        env,
        rest_type_lid.loc,
        rest_type_expr,
    ) {
        Ok(result) => result,
        Err(_) => {
            return rest_err(
                rest_type_lid.loc,
                RecordRestError::NotRecord(rest_type_longident.clone()),
            );
        }
    };
    let Some(rest_decl) = rest_extract else {
        return rest_err(
            rest_type_lid.loc,
            RecordRestError::NotRecord(rest_type_longident.clone()),
        );
    };
    if rest_decl.type_private == crate::types::asttypes::PrivateFlag::Private {
        return Err(TypeCoreError::PrivateType {
            loc: rest_type_lid.loc,
            ty: rest_type_expr,
        });
    }
    let rest_labels: Vec<crate::types::decl::LabelDeclaration> = match &rest_decl.type_kind {
        crate::types::TypeKind::TypeRecord(
            _,
            crate::types::RecordRepresentation::RecordUnboxed(_),
        ) => {
            return rest_err(rest_type_lid.loc, RecordRestError::UnboxedRecord);
        }
        // The rest is an object spread, which can't produce an array.
        crate::types::TypeKind::TypeRecord(_, crate::types::RecordRepresentation::RecordArray) => {
            return rest_err(rest_type_lid.loc, RecordRestError::ArrayRecord);
        }
        crate::types::TypeKind::TypeRecord(labels, _) => labels.to_vec(),
        _ => {
            return rest_err(
                rest_type_lid.loc,
                RecordRestError::NotRecord(rest_type_longident.clone()),
            );
        }
    };

    let explicit_fields: Vec<String> = lbl_pat_list
        .iter()
        .map(|(_, label, _, _)| label.lbl_name.to_string())
        .collect();
    let explicit_runtime_labels: Vec<String> = lbl_pat_list
        .iter()
        .map(|(_, label, _, _)| label.lbl_runtime_name.to_string())
        .collect();
    let explicit_optional_fields: Vec<String> = lbl_pat_list
        .iter()
        .filter_map(|(_, label, _, optional)| {
            if *optional {
                Some(label.lbl_name.to_string())
            } else {
                None
            }
        })
        .collect();
    let rest_field_names: Vec<String> = rest_labels
        .iter()
        .map(|label| label.ld_id.name().to_string())
        .collect();

    // resolve_source_record.
    let source_result =
        record_rest_extract_instantiated_concrete_typedecl(tctx, env, loc, record_ty);
    let (source_fields, tag_exclusion) = match source_result {
        Ok(Some(source_decl)) => {
            match record_rest_source_fields_and_repr(tctx.type_ctx, &source_decl) {
                Ok(v) => v,
                Err(err) => return rest_err(loc, err),
            }
        }
        Ok(None) | Err(_) => {
            // unify record_ty with rest_type_expr, then read fields off rest_decl.
            unify_pattern_types(tctx, rest_type_lid.loc, record_ty, rest_type_expr)?;
            match record_rest_source_fields_and_repr(tctx.type_ctx, &rest_decl) {
                Ok(v) => v,
                Err(err) => return rest_err(rest_type_lid.loc, err),
            }
        }
    };

    let overlapping_fields: Vec<String> = rest_field_names
        .iter()
        .filter(|rest_field| explicit_fields.contains(rest_field))
        .cloned()
        .collect();
    let non_optional_overlapping_fields: Vec<String> = overlapping_fields
        .iter()
        .filter(|rest_field| !explicit_optional_fields.contains(rest_field))
        .cloned()
        .collect();
    if !non_optional_overlapping_fields.is_empty() {
        return rest_err(
            rest_loc,
            RecordRestError::FieldNotOptional(non_optional_overlapping_fields, rest_type_longident),
        );
    }
    if !overlapping_fields.is_empty() {
        tctx.report_warning(
            rest_loc,
            Warning::BsRecordRestOptionalOverlap {
                fields: overlapping_fields,
            },
        );
    }
    let missing: Vec<String> = source_fields
        .iter()
        .filter_map(|field| {
            let name = field.ld_id.name().to_string();
            if !explicit_fields.contains(&name) && !rest_field_names.contains(&name) {
                Some(name)
            } else {
                None
            }
        })
        .collect();
    if !missing.is_empty() {
        return rest_err(
            rest_loc,
            RecordRestError::FieldMissing(missing, rest_type_longident),
        );
    }
    for rest_label in &rest_labels {
        let rest_field = rest_label.ld_id.name().to_string();
        let rest_runtime_name = rest_label.declaration_name().to_string();
        let source_field = source_fields
            .iter()
            .find(|field| field.ld_id.name() == rest_field);
        let Some(source_field) = source_field else {
            return rest_err(
                rest_type_lid.loc,
                RecordRestError::ExtraField(rest_field, rest_type_longident),
            );
        };
        let source_runtime_name = source_field.declaration_name().to_string();
        if source_runtime_name != rest_runtime_name {
            return rest_err(
                rest_type_lid.loc,
                RecordRestError::FieldRuntimeNameMismatch {
                    field: rest_field,
                    rest_type: rest_type_longident,
                    source_runtime_name,
                    rest_runtime_name,
                },
            );
        }
        unify_pattern_types(
            tctx,
            rest_type_lid.loc,
            rest_label.ld_type,
            source_field.ld_type,
        )?;
    }

    // enter_variable rest.rest_loc rest.rest_name rest_type_expr.
    let rest_ident = state.enter_variable(
        tctx.type_ctx,
        rest_loc,
        &rest.rest_name,
        rest_type_expr,
        PatternVariableKind::Value,
        tctx.arena,
    )?;

    Ok(crate::types::typedtree::RecordPatternRest {
        rest_ident,
        rest_loc,
        rest_name: crate::parse_arena::Located {
            txt: tctx.arena.get_string(rest.rest_name.txt).to_string(),
            loc: rest.rest_name.loc,
        },
        rest_type: rest_type_expr,
        excluded_runtime_labels: record_rest_excluded_labels(
            explicit_runtime_labels,
            tag_exclusion,
        ),
    })
}

/// Type check constraint pattern.
#[allow(clippy::too_many_arguments)]
fn type_pattern_constraint(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    inner_pat: &ParsedPattern,
    core_type: &crate::parser::ast::CoreType,
    expected_ty: TypeExprRef,
    options: PatternOptions,
    state: &mut PatternState,
    explode: i32,
    _pat: &ParsedPattern,
) -> TypeCoreResult<Pattern> {
    let ctx = tctx.type_ctx;

    // Match OCaml typecore.ml Ppat_constraint flow:
    // begin_def; transl_simple_type_delayed; end_def; generalize_structure;
    // then use two independent instances (constraint ty and inner-pattern ty).
    ctx.begin_def();
    let (typed_ctype, ctype_ty, force) = transl_type_delayed(tctx, env, core_type, true)?;
    ctx.end_def();
    let var_level = ctx.current_level();
    crate::types::generalize_structure(ctx, var_level, ctype_ty);

    let constraint_ty = crate::types::instance(ctx, ctype_ty);
    let inner_expected_ty = crate::types::instance(ctx, ctype_ty);

    unify_pattern_types(tctx, loc, constraint_ty, expected_ty)?;

    let typed_inner = type_pattern_inner(
        tctx,
        env,
        inner_pat,
        inner_expected_ty,
        options,
        state,
        explode,
    )?;
    // OCaml compiler/ml/typecore.ml:1650-1664 stores the force returned by
    // Typetexp.transl_simple_type_delayed only after the inner pattern is
    // typed. compiler/ml/typecore.ml:4270-4288 then runs those pattern forces
    // after pattern binders have been entered, so qualified constraint paths
    // such as `M.t` must not force component substitutions before `Tpat_var`.
    state.add_globalize_forces(force);
    state.defer_type_path_force(ctype_ty);

    // OCaml uses inner pattern attributes for Tpat_constraint extra.
    let constraint_extra = (
        crate::types::typedtree::PatExtra::Tpat_constraint(tctx.typed.push_core_type(typed_ctype)),
        loc,
        inner_pat.ppat_attributes.clone(),
    );

    // OCaml converts Tpat_var to Tpat_alias(Tpat_any, id, name) and replaces extras.
    // OCaml: {p with pat_desc = Tpat_any; pat_attributes = []} — keeps p.pat_type
    // which is expected_ty' (the second instance of the constraint type).
    let typed_inner = match typed_inner.pat_desc.clone() {
        crate::types::typedtree::PatternDesc::Tpat_var(id, name) => {
            // Use typed_inner.pat_type (= inner_expected_ty, instance 2)
            // to match OCaml's {p with pat_desc = Tpat_any} behavior.
            let any_pat = Pattern {
                pat_desc: crate::types::typedtree::PatternDesc::Tpat_any,
                pat_type: typed_inner.pat_type,
                ..typed_inner.clone()
            };
            let any_pat = tctx.typed.with_pat_attributes(any_pat, Attributes::new());
            let mut alias = Pattern {
                pat_desc: crate::types::typedtree::PatternDesc::Tpat_alias(
                    tctx.typed.push_pattern(any_pat),
                    id,
                    name,
                ),
                pat_type: constraint_ty,
                ..typed_inner
            };
            tctx.typed.set_pat_extra(&mut alias, vec![constraint_extra]);
            alias
        }
        _ => {
            let mut typed_inner = typed_inner;
            typed_inner.pat_type = constraint_ty;
            tctx.typed
                .prepend_pat_extra(&mut typed_inner, constraint_extra);
            typed_inner
        }
    };

    Ok(typed_inner)
}

/// Type check constraint pattern: Ppat_constraint(Ppat_var, Ptyp_poly).
/// OCaml typecore.ml:1249-1274: explicitly polymorphic type annotation.
/// Uses instance_poly ~keep_names:true to preserve type variable names.
#[allow(clippy::too_many_arguments)]
fn type_pattern_constraint_poly_var(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    inner_pat: &ParsedPattern,
    name: crate::parser::ast::StringLoc,
    core_type: &crate::parser::ast::CoreType,
    expected_ty: TypeExprRef,
    options: PatternOptions,
    state: &mut PatternState,
    _explode: i32,
    pat: &ParsedPattern,
) -> TypeCoreResult<Pattern> {
    let ctx = tctx.type_ctx;

    // OCaml: lloc = inner_pat.ppat_loc (used for unify and enter_variable)
    let lloc = inner_pat.ppat_loc;

    // OCaml: let cty, force = Typetexp.transl_simple_type_delayed !env sty in
    let (typed_ctype, ctype_ty, force) = transl_type_delayed(tctx, env, core_type, true)?;

    // OCaml: unify_pat_types lloc !env ty expected_ty
    unify_pattern_types(tctx, lloc, ctype_ty, expected_ty)?;
    // OCaml typecore.ml:1274: `pattern_force := force :: !pattern_force`.
    state.add_globalize_forces(force);

    // OCaml: match ty.desc with Tpoly(body, tyl) -> ...
    let ctype_repr = ctx.repr(ctype_ty);
    let ctype_desc = ctx.get_desc(ctype_repr);
    match &*ctype_desc {
        TypeDesc::Tpoly { body, vars } => {
            let body = *body;
            let vars: Vec<TypeExprRef> = ctx.type_list(vars).to_vec();

            // OCaml: begin_def (); let _, ty' = instance_poly ~keep_names:true false tyl body in end_def (); generalize ty'
            ctx.begin_def();
            let (_inst_vars, ty_prime) =
                crate::types::ctype::instance_poly(ctx, true, false, crate::types::type_expr::PoolSlice::from(&vars), body);
            ctx.end_def();
            crate::types::ctype::generalize(ctx, ty_prime);

            // OCaml: let id = enter_variable lloc name ty' in
            let id = state.enter_variable(
                tctx.type_ctx,
                lloc,
                &name,
                ty_prime,
                PatternVariableKind::Value,
                tctx.arena,
            )?;
            // OCaml compiler/ml/typecore.ml:1273-1289 queues the delayed
            // type-constraint force after `enter_variable` for explicit
            // polymorphic variable constraints too.
            state.defer_type_path_force(ctype_ty);

            // OCaml: pat_desc = Tpat_var(id, name); pat_type = ty (the Tpoly type)
            // pat_extra = [(Tpat_constraint cty, loc, sp.ppat_attributes)]
            let constraint_extra = (
                crate::types::typedtree::PatExtra::Tpat_constraint(
                    tctx.typed.push_core_type(typed_ctype),
                ),
                loc,
                pat.ppat_attributes.clone(),
            );

            let mut typed_pat = Pattern::new(
                PatternDesc::Tpat_var(id, convert_located_stridx(&name, tctx.arena)),
                lloc,
                ctype_ty,
                tctx.type_ctx.store_typed_env(env),
            );
            tctx.typed.push_pat_extra(&mut typed_pat, constraint_extra);
            Ok(typed_pat)
        }
        _ => {
            // Fallback: shouldn't happen for Ptyp_poly but be safe
            type_pattern_constraint(
                tctx,
                env,
                loc,
                inner_pat,
                core_type,
                expected_ty,
                options,
                state,
                _explode,
                pat,
            )
        }
    }
}

/// Type check interval pattern (typecore.ml `Ppat_interval`). `char` is an
/// alias of `int`, so bounds may mix both.
fn type_pattern_interval(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    c1: &crate::parser::ast::Constant,
    c2: &crate::parser::ast::Constant,
    expected_ty: TypeExprRef,
    pat: &ParsedPattern,
) -> TypeCoreResult<Pattern> {
    let ctx = tctx.type_ctx;
    let bound = |c: &crate::parser::ast::Constant| -> TypeCoreResult<Option<(i64, Constant)>> {
        let c = convert_constant(c, loc, tctx.arena)?;
        Ok(crate::types::parmatch::int_of_constant(&c).map(|i| (i, c)))
    };
    let (Some(b1), Some(b2)) = (bound(c1)?, bound(c2)?) else {
        return Err(TypeCoreError::InvalidInterval { loc });
    };
    let ((i1, lo), (i2, hi)) = if b1.0 <= b2.0 { (b1, b2) } else { (b2, b1) };
    let ty = match (&lo, &hi) {
        (Constant::Char(_), Constant::Char(_)) => type_constant(ctx, env, &lo),
        _ => type_constant(ctx, env, &Constant::Int(0)),
    };
    unify_pattern_types(tctx, loc, ty, expected_ty)?;
    let desc = if i1 == i2 {
        PatternDesc::Tpat_constant(lo)
    } else {
        PatternDesc::Tpat_interval(crate::types::typedtree::IntervalBound::from_constant(lo), crate::types::typedtree::IntervalBound::from_constant(hi))
    };
    Ok(tctx.typed.with_pat_attributes(Pattern::new(
        desc,
        loc,
        expected_ty,
        tctx.type_ctx.store_typed_env(env),
        ), pat.ppat_attributes.clone(),
    ))
}

/// Type check exception pattern.
#[allow(clippy::too_many_arguments)]
fn type_pattern_exception(
    _tctx: &mut TypeCheckContext<'_>,
    _env: &Env,
    loc: LocIdx,
    _inner_pat: &ParsedPattern,
    _expected_ty: TypeExprRef,
    _mode: PatternMode,
    _state: &mut PatternState,
    _explode: i32,
    _pat: &ParsedPattern,
) -> TypeCoreResult<Pattern> {
    Err(TypeCoreError::ExceptionPatternBelowToplevel { loc })
}

// ============================================================================
// Expression Type Checking
// ============================================================================

/// An inferred expression replaces an otherwise unobservable fresh expected
/// variable. Unconverted constructs still materialise that variable.
#[derive(Clone, Copy)]
enum Expected {
    Known(TypeExprRef),
    Infer { level: i32, site: InferenceSite },
}

#[derive(Clone, Copy)]
enum InferenceSite {
    Expression,
    ApplicationFunction,
}

impl From<TypeExprRef> for Expected {
    fn from(ty: TypeExprRef) -> Self {
        Self::Known(ty)
    }
}

pub(crate) fn type_exp<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    expr: &ParsedExpression,
    context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    if matches!(
        expr.pexp_desc,
        crate::parser::ast::ExpressionDesc::Pexp_constant(_)
            | crate::parser::ast::ExpressionDesc::Pexp_ident(_)
            | crate::parser::ast::ExpressionDesc::Pexp_field(..)
            | crate::parser::ast::ExpressionDesc::Pexp_apply(_)
            | crate::parser::ast::ExpressionDesc::Pexp_await(_)
    ) {
        return type_expect_full(
            tctx,
            env,
            expr,
            Expected::Infer {
                level: tctx.type_ctx.current_level(),
                site: InferenceSite::Expression,
            },
            context,
            RecArg::Rejected,
            None,
        );
    }
    if tctx.type_ctx.compiler_counters_enabled() {
        crate::perf_counters::record_expected_var(expected_var_use(expr));
    }
    let expected_ty = tctx.type_ctx.new_var(None);
    type_expect(tctx, env, expr, expected_ty, context)
}

/// For the compiler counters: the construct a fresh variable becomes the
/// expected type of, with its case in section C.9 of
/// `compiler-rust/docs/CHECKER_REDESIGN.md` (1: the construct only unifies
/// its type with the expected type at the end; 3: it passes the expected
/// type to one child in tail position; 4: it threads it to several
/// children; 5: the variable is visible to someone else meanwhile, which is
/// also the answer for every construct the design does not list).
fn expected_var_use(expr: &ParsedExpression) -> crate::perf_counters::ExpectedVar {
    use crate::parser::ast::ExpressionDesc as E;
    let (construct, case) = match &expr.pexp_desc {
        E::Pexp_ident(_) => ("ident", 1),
        E::Pexp_constant(_) => ("constant", 1),
        E::Pexp_field(..) => ("field", 1),
        E::Pexp_construct(..) => ("construct", 1),
        E::Pexp_apply(_) => ("apply", 1),
        E::Pexp_let((crate::parser::ast::RecFlag::Nonrecursive, _, _)) => ("let", 3),
        E::Pexp_let((crate::parser::ast::RecFlag::Recursive, _, _)) => ("let rec", 5),
        E::Pexp_sequence(..) => ("sequence", 3),
        E::Pexp_open(..) => ("open", 3),
        E::Pexp_letmodule(..) => ("letmodule", 3),
        E::Pexp_ifthenelse(_) | E::Pexp_ternary(_) => ("if", 4),
        E::Pexp_match(_) => ("switch", 4),
        E::Pexp_try(_) => ("try", 4),
        E::Pexp_array(_) => ("array", 4),
        E::Pexp_fun(_) => ("fun", 5),
        _ => ("other", 5),
    };
    crate::perf_counters::ExpectedVar { construct, case }
}

/// Match OCaml `type_statement`:
/// begin_def; type_exp; end_def; expand_head(exp_type); unify with unit.
fn type_statement<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    expr: &ParsedExpression,
) -> TypeCoreResult<Expression> {
    type_statement_with(tctx, env, expr, NonreturningWarning::Report)
}

/// Whether `type_statement_with` warns about a statement that never returns
/// (typecore.ml `type_statement ?nonreturning_warning`).
#[derive(Clone, Copy, PartialEq, Eq)]
enum NonreturningWarning {
    Report,
    /// A statement that ends its construct, so no code follows it: a
    /// finally block that always throws.
    Skip,
}

fn type_statement_with<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    expr: &ParsedExpression,
    nonreturning_warning: NonreturningWarning,
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    ctx.begin_def();
    let typed = type_exp(tctx, env, expr, None)?;
    ctx.end_def();

    // OCaml typecore.ml type_statement: warn when the statement's type is a
    // variable generalizable past the current level (it never returns).
    let ty = crate::types::ctype::expand_head(ctx, env, typed.exp_type);
    let tv = ctx.new_var(None);
    if nonreturning_warning == NonreturningWarning::Report
        && matches!(&*ctx.borrow_desc(ty), TypeDesc::Tvar(..))
        && ctx.get_level(ty) > ctx.get_level(tv)
    {
        let loc = final_subexpression(tctx.arena, expr).pexp_loc;
        tctx.report_warning(loc, Warning::NonreturningStatement);
    }

    let expected_ty = env.type_unit(ctx);
    let context = type_clash_context_in_statement(expr);
    unify_expression_types(
        tctx,
        proper_exp_loc(&tctx.typed, &typed),
        typed.exp_type,
        expected_ty,
        context,
    )?;
    Ok(typed)
}

/// OCaml typecore.ml `final_subexpression`.
fn final_subexpression<'e>(
    arena: &'e crate::parse_arena::ParseArena,
    mut sexp: &'e ParsedExpression,
) -> &'e ParsedExpression {
    use crate::parser::ast::ExpressionDesc as ED;
    loop {
        let next = match &sexp.pexp_desc {
            ED::Pexp_let(inner) => inner.2,
            ED::Pexp_sequence(_, e) => *e,
            ED::Pexp_try(inner) => inner.0,
            ED::Pexp_braces(braces) => braces.expr,
            ED::Pexp_ifthenelse(inner) => inner.1,
            ED::Pexp_ternary(inner) => inner.1,
            ED::Pexp_match(inner) => match arena.case_list(inner.1).first() {
                Some(case) => case.pc_rhs,
                None => return sexp,
            },
            _ => return sexp,
        };
        sexp = arena.get_expanded_expr(next);
    }
}

fn type_clash_context_in_statement(expr: &ParsedExpression) -> Option<ClashSite> {
    match &expr.pexp_desc {
        crate::parser::ast::ExpressionDesc::Pexp_apply(inner) if !inner.transformed_jsx => {
            Some(ClashSite::StatementFunctionCall)
        }
        _ => None,
    }
}

fn deprecated_warning_from_attrs(
    name: &str,
    attrs: &[crate::types::decl::Attribute],
) -> Result<Option<Warning>, crate::types::DeclLoc> {
    Ok(deprecated_attr_payload(attrs)?
        .map(|(reason, can_be_automigrated)| deprecated_warning(name, reason, can_be_automigrated)))
}

/// `deprecated_warning_from_attrs` for an item named by its path. The name is
/// printed only for a deprecated item: this runs on every use of a value or
/// type, and almost none of them is deprecated.
fn deprecated_warning_for_path(
    path: &Path,
    attrs: &[crate::types::decl::Attribute],
) -> Result<Option<Warning>, crate::types::DeclLoc> {
    Ok(
        deprecated_attr_payload(attrs)?.map(|(reason, can_be_automigrated)| {
            deprecated_warning(path.name().as_str(), reason, can_be_automigrated)
        }),
    )
}

/// `Builtin_attributes.deprecated_of_attrs` (builtin_attributes.ml:59-62):
/// `string_of_opt_payload` of the first `deprecated` attribute, the record
/// form reading as `""`; `Err` where it raises.
pub(crate) fn deprecated_of_decl_attrs(
    attrs: &[crate::types::decl::Attribute],
) -> Result<Option<String>, crate::types::DeclLoc> {
    let Some(attr) = attrs
        .iter()
        .find(|attr| matches!(attr.attr_name.txt.as_str(), "deprecated"))
    else {
        return Ok(None);
    };
    Ok(Some(attr.attr_payload.deprecated_string_of_opt_payload()?.to_string()))
}

/// The error a reader of a declaration attribute raises at `loc`.
pub(crate) fn invalid_escape_at(
    ctx: &crate::types::context::TypeContext,
    loc: crate::types::DeclLoc,
) -> TypeCoreError {
    TypeCoreError::InvalidStringEscapeAt {
        loc: ctx.resolve_loc(loc),
    }
}

/// The `deprecated` flag of the components of a module inside a loaded
/// persistent unit: the unit's `Deprecated` persistence flag
/// (env.ml:663-668), or the `md_attributes` its submodule components were
/// built from (env.ml:1527-1533).
fn persistent_module_deprecated(
    pers_env: &crate::cmi::persistent_env::PersistentEnv,
    target: &Path,
) -> Option<String> {
    let (unit, components) = persistent_path_components(target)?;
    let ps = pers_env.loaded_pers_struct(&unit)?;
    if components.is_empty() {
        return ps.ps_deprecated.clone();
    }
    signature_submodule_deprecated(pers_env, &ps.ps_sig, &components, 0)
}

fn signature_submodule_deprecated(
    pers_env: &crate::cmi::persistent_env::PersistentEnv,
    items: &[crate::types::decl::SignatureItem],
    components: &[crate::name::Name],
    depth: usize,
) -> Option<String> {
    use crate::types::decl::{ModuleType, SignatureItem};
    let (first, rest) = components.split_first()?;
    if depth > 32 {
        return None;
    }
    let md = items.iter().rev().find_map(|item| match item {
        SignatureItem::SigModule(id, md, _) if id.name_atom() == *first => Some(md),
        _ => None,
    })?;
    if rest.is_empty() {
        // `Env.store_module` (env.ml:1649) read this payload when the
        // module was defined, raising there on an invalid escape.
        return deprecated_of_decl_attrs(&md.md_attributes)
            .expect("the module's definition read its deprecated payload");
    }
    match &md.md_type {
        ModuleType::MtySignature(items) => {
            signature_submodule_deprecated(pers_env, items, rest, depth + 1)
        }
        ModuleType::MtyAlias(_, path) => {
            let (unit, mut target) = persistent_path_components(path)?;
            target.extend(rest.iter().copied());
            let ps = pers_env.loaded_pers_struct(&unit)?;
            signature_submodule_deprecated(pers_env, &ps.ps_sig, &target, depth + 1)
        }
        _ => None,
    }
}

/// A module path rooted at a persistent unit, as the unit name and the
/// submodule names below it.
fn persistent_path_components(path: &Path) -> Option<(crate::name::Name, PathComponents)> {
    match path.view() {
        PathView::Pident(id) if id.is_persistent() => Some((id.name_atom(), PathComponents::new())),
        PathView::Pdot(parent, name, _) => {
            let (unit, mut components) = persistent_path_components(parent)?;
            components.push(*name);
            Some((unit, components))
        }
        _ => None,
    }
}

/// Submodule names below a persistent unit; module paths are short.
type PathComponents = smallvec::SmallVec<[crate::name::Name; 4]>;

/// `Builtin_attributes.deprecated_of_attrs_with_migrate`
/// (builtin_attributes.ml:68-112): the first `deprecated` attribute's reason
/// and whether it can be automigrated; `Err` where a reader raises.
fn deprecated_attr_payload(
    attrs: &[crate::types::decl::Attribute],
) -> Result<Option<(&str, bool)>, crate::types::DeclLoc> {
    match attrs.iter().find(|attr| attr.attr_name.txt == "deprecated") {
        Some(attr) => attr.attr_payload.deprecated_with_migrate(),
        None => Ok(None),
    }
}

/// `Cmt_utils.record_deprecated_used` from `Builtin_attributes.check_deprecated`
/// (builtin_attributes.ml:126-133): remember a use of a deprecated item with
/// its migration templates for `rescript-tools migrate`.
fn record_deprecated_used(
    tctx: &TypeCheckContext<'_>,
    loc: LocIdx,
    attrs: &[crate::types::decl::Attribute],
    context: Option<crate::types::context::DeprecatedContext>,
) -> Result<(), TypeCoreError> {
    use crate::types::decl::AttributePayload;
    let Some(attr) = attrs
        .iter()
        .find(|attr| matches!(attr.attr_name.txt.as_str(), "deprecated"))
    else {
        return Ok(());
    };
    // builtin_attributes.ml:114-124: only a use `deprecated_of_attrs_with_migrate`
    // finds deprecated is recorded.
    let Some((text, _)) = attr
        .attr_payload
        .deprecated_with_migrate()
        .map_err(|loc| invalid_escape_at(tctx.type_ctx, loc))?
    else {
        return Ok(());
    };
    let (migrate, migrate_in_pipe_chain) = match &attr.attr_payload {
        AttributePayload::Deprecated {
            migrate,
            migrate_in_pipe_chain,
            ..
        } => (migrate.clone(), migrate_in_pipe_chain.clone()),
        _ => (None, None),
    };
    tctx.type_ctx
        .record_deprecated_used(crate::types::context::DeprecatedUse {
            source_loc: tctx.arena.to_location(loc),
            text: text.to_string(),
            migrate,
            migrate_in_pipe_chain,
            context,
        });
    Ok(())
}

fn deprecated_warning(name: &str, reason: &str, can_be_automigrated: bool) -> Warning {
    let message = if reason.is_empty() {
        name.to_string()
    } else {
        // `Builtin_attributes.cat` (builtin_attributes.ml:71-74).
        format!("{name}\n  {reason}")
    };
    Warning::Deprecated {
        message,
        def_loc: Location::none(),
        use_loc: Location::none(),
        can_be_automigrated,
    }
}

fn deprecated_warning_for_value(
    path: &Path,
    desc: &ValueDescription,
) -> Result<Option<Warning>, crate::types::DeclLoc> {
    deprecated_warning_for_path(path, &desc.val_attributes)
}

fn deprecated_warning_for_type(
    path: &Path,
    decl: &crate::types::decl::TypeDeclaration,
) -> Result<Option<Warning>, crate::types::DeclLoc> {
    deprecated_warning_for_path(path, &decl.type_attributes)
}

/// Why the lookup of an identifier expression found no value.
pub(crate) enum ValueLookupFailure {
    /// The name is not a legal value name (`Env.check_value_name`).
    IllegalName,
    /// The name is not bound.
    Unbound,
}

/// The lookup of an identifier expression (typetexp.ml `find_value`):
/// `Env.check_value_name (Longident.last lid) loc`, the use of the opens the
/// name goes through, then the lookup itself. Shared by the typing of an
/// identifier and the discharge of a derived item's value obligation.
/// Cost: one environment lookup; one shared-pointer copy of the description.
#[inline(always)]
pub(crate) fn lookup_value_ident(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    longident: &Longident,
    loc: LocIdx,
) -> Result<(Path, Arc<ValueDescription>), ValueLookupFailure> {
    let last = tctx.arena.get_string(longident.last_idx());
    if crate::types::env::check_value_name(last, tctx.arena.to_location(loc)).is_err() {
        return Err(ValueLookupFailure::IllegalName);
    }
    mark_open_lid_use(
        tctx.type_ctx,
        env,
        tctx.arena,
        longident,
        crate::types::env::OpenLookupKind::Value,
        Some(loc),
    );
    env.lookup_value_by_lid(
        longident,
        tctx.arena,
        &mut tctx.persistent_env,
        tctx.type_ctx,
    )
    .ok_or(ValueLookupFailure::Unbound)
}

/// What the use of a looked-up value records: `Env.lookup_value` marks the
/// declaration used (env.ml:1169-1172), and a deprecated value is recorded
/// and warned about (typetexp.ml:117-123 via typecore.ml:2381-2388).
/// `function_call` says whether the identifier is the callee of an
/// application.
/// Cost: O(1) plus a scan of the value's attributes.
#[inline(always)]
pub(crate) fn note_value_ident_use(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    longident: &Longident,
    loc: LocIdx,
    path: &Path,
    desc: &ValueDescription,
    function_call: bool,
) -> TypeCoreResult<()> {
    let used_name = tctx.arena.name(longident.last_idx());
    tctx.mark_value_used(env, used_name, tctx.resolve_loc(desc.val_loc));
    let deprecated_context = if function_call {
        crate::types::context::DeprecatedContext::FunctionCall
    } else {
        crate::types::context::DeprecatedContext::Reference
    };
    record_deprecated_used(
        tctx,
        loc,
        &desc.val_attributes,
        Some(deprecated_context),
    )?;
    if let Some(warning) = deprecated_warning_for_value(path, desc)
        .map_err(|loc| invalid_escape_at(tctx.type_ctx, loc))?
    {
        tctx.report_warning(loc, warning);
    }
    Ok(())
}

/// What the use of a looked-up type constructor in a type expression records
/// (typetexp.ml:104-106, `check_deprecated ~deprecated_context:Reference`).
/// Shared by the translation of a type and the discharge of a derived item's
/// type obligation.
/// Cost: O(1) plus a scan of the declaration's attributes.
#[inline(always)]
pub(crate) fn note_type_use(
    tctx: &mut TypeCheckContext<'_>,
    loc: LocIdx,
    path: &Path,
    decl: &crate::types::decl::TypeDeclaration,
) -> TypeCoreResult<()> {
    record_deprecated_used(
        tctx,
        loc,
        &decl.type_attributes,
        Some(crate::types::context::DeprecatedContext::Reference),
    )?;
    if let Some(warning) = deprecated_warning_for_type(path, decl)
        .map_err(|loc| invalid_escape_at(tctx.type_ctx, loc))?
    {
        tctx.report_warning(loc, warning);
    }
    Ok(())
}

/// Type check an expression against an expected type.
pub(crate) fn type_expect<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    expr: &ParsedExpression,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    type_expect_with_recarg(tctx, env, expr, expected_ty, context, RecArg::Rejected)
}

fn type_expect_with_recarg<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    expr: &ParsedExpression,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
    recarg: RecArg,
) -> TypeCoreResult<Expression> {
    type_expect_full(tctx, env, expr, expected_ty, context, recarg, None)
}

/// `type_expect ~context ?recarg ?match_context` (typecore.ml:2552-2569).
fn type_expect_full<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    expr: &ParsedExpression,
    expected_ty: impl Into<Expected>,
    context: Option<ClashSite>,
    recarg: RecArg,
    match_context: Option<MatchContext>,
) -> TypeCoreResult<Expression> {
    let expected_ty = expected_ty.into();
    let arena = tctx.arena;
    let no_attributes = Attributes::new();
    let mut typed = crate::types::typemod::with_warning_scope(
        tctx,
        arena,
        if matches!(expr.pexp_desc, crate::parser::ast::ExpressionDesc::Pexp_await(_)) {
            &no_attributes
        } else {
            &expr.pexp_attributes
        },
        true,
        |tctx| {
            type_expect_with_recarg_unscoped(
                tctx,
                env,
                expr,
                expected_ty,
                context,
                recarg,
                match_context,
            )
        },
    )?;
    // OCaml records `exp_env = env` on every typed expression
    // (typecore.ml type_expect_); later phases such as
    // Typeopt.type_cannot_contain_undefined (translcore.ml:822) expand the
    // expression's type in it. Nodes built without an env get the one they
    // were typed in.
    if typed.exp_env == EnvRef(0) {
        typed.exp_env = tctx.type_ctx.store_typed_env(env);
    }
    Ok(typed)
}

fn type_expect_with_recarg_unscoped<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    expr: &ParsedExpression,
    mut expected_ty: Expected,
    context: Option<ClashSite>,
    recarg: RecArg,
    match_context: Option<MatchContext>,
) -> TypeCoreResult<Expression> {
    use crate::parser::ast::ExpressionDesc as ED;

    let loc = expr.pexp_loc;
    let ctx = tctx.type_ctx;
    let exp_env_ref = ctx.store_typed_env(env);
    // Applies to this expression only; see `deprecated_function_call`.
    let deprecated_function_call = std::mem::take(&mut tctx.deprecated_function_call);
    let context = match &expr.pexp_desc {
        // Special errors for braced identifiers passed to records.
        ED::Pexp_braces(braces)
            if matches!(
                &tctx.arena.get_expanded_expr(braces.expr).pexp_desc,
                ED::Pexp_ident(_)
            ) =>
        {
            Some(ClashSite::BracedIdent)
        }
        _ => context,
    };
    // Keep alias expansion aligned with the current typing environment.
    // OCaml passes `env` through all Ctype operations; in Rust we update the
    // unify-state snapshot on each type_expect entry.
    tctx.set_unify_env(env);

    if let ED::Pexp_constant(cst) = &expr.pexp_desc {
        let constant = convert_constant(cst, loc, tctx.arena)?;
        let ty = type_constant(ctx, env, &constant);
        match expected_ty {
            Expected::Known(expected) => rue_unify(tctx, loc, ty, expected, context)?,
            Expected::Infer { level, .. } => {
                // type_constant instances a nullary predefined constructor at
                // current_level. No scope or universal variable can escape, and
                // unifying with a fresh variable at this level only links that
                // variable to this exact node (ctype.ml:2280-2286).
                debug_assert_eq!(ctx.get_level(ctx.repr(ty)), level);
            }
        }
        let node = Expression::new(
            ExpressionDesc::Texp_constant(constant),
            loc,
            ty,
            exp_env_ref,
        );
        return Ok(tctx.typed.with_exp_attributes(node, expr.pexp_attributes.clone()));
    }
    if let ED::Pexp_ident(lid) = &expr.pexp_desc {
        return type_identifier(tctx, env, expr, loc, lid, &expr.pexp_attributes,
            &mut expected_ty, context, recarg, deprecated_function_call);
    }
    if let ED::Pexp_field(record_expr_idx, field_lid) = &expr.pexp_desc {
        let record_expr = tctx.arena.get_expanded_expr(*record_expr_idx);
        let typed_field = type_field(
            tctx,
            env,
            loc,
            record_expr,
            field_lid,
            &expr.pexp_attributes,
        )?;
        // OCaml: rue { ... exp_type = ty_arg; ... }
        finish_expected(tctx, expr, typed_field.exp_type, &mut expected_ty, context)?;
        return Ok(typed_field);
    }
    if let ED::Pexp_apply(inner) = &expr.pexp_desc {
        let typed_apply =
            type_application(tctx, env, expr, inner, &mut expected_ty, context)?;
        // The two rue checks share one expected type, including when an Infer
        // request must be materialised by the first check or a lowered apply.
        finish_expected(tctx, expr, typed_apply.exp_type, &mut expected_ty, context)?;
        return Ok(typed_apply);
    }
    if let ED::Pexp_await(operand) = &expr.pexp_desc {
        let arena = tctx.arena;
        let primitive = Located {
            txt: arena.promise_await_lident(),
            loc: arena.ghost_location(arena.get_expr(*operand).pexp_loc),
        };
        return type_promise_application(tctx, env, expr, *operand, primitive, &mut expected_ty, context);
    }
    let expected_ty = materialize_expected(tctx, expr, &mut expected_ty);

    match &expr.pexp_desc {
        ED::Pexp_braces(braces) => {
            // typecore.ml: type the inner expression, then prepend the
            // braces node's attributes.
            let inner = tctx.arena.get_expanded_expr(braces.expr);
            tctx.deprecated_function_call = deprecated_function_call;
            let exp = type_expect_with_recarg(tctx, env, inner, expected_ty, context, recarg)?;
            let mut attrs = expr.pexp_attributes.clone();
            attrs.extend(tctx.typed.exp_attributes(&exp).iter().cloned());
            Ok(tctx.typed.with_exp_attributes(exp, attrs))
        }
        ED::Pexp_regexp(_) => unreachable!("Lowered by the built-in frontend mapper."),
        ED::Pexp_ident(_) => unreachable!("identifiers were typed above"),

        ED::Pexp_constant(_) => unreachable!("constants were typed above"),

        ED::Pexp_break => {
            if tctx.loop_depth == 0 {
                return Err(if tctx.in_finally {
                    TypeCoreError::BreakOutOfFinally { loc }
                } else {
                    TypeCoreError::BreakOutsideLoop { loc }
                });
            }
            let unit_ty = env.type_unit(ctx);
            // `rue`: `unify env unit (instance ty_expected)` (typecore.ml:3051-3074).
            rue_unify(tctx, loc, unit_ty, expected_ty, context)?;
            Ok({
                let typed_node =
                    Expression::new(ExpressionDesc::Texp_break, loc, unit_ty, exp_env_ref);
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        ED::Pexp_continue => {
            if tctx.loop_depth == 0 {
                return Err(if tctx.in_finally {
                    TypeCoreError::ContinueOutOfFinally { loc }
                } else {
                    TypeCoreError::ContinueOutsideLoop { loc }
                });
            }
            let unit_ty = env.type_unit(ctx);
            // `rue`: `unify env unit (instance ty_expected)` (typecore.ml:3051-3074).
            rue_unify(tctx, loc, unit_ty, expected_ty, context)?;
            Ok({
                let typed_node =
                    Expression::new(ExpressionDesc::Texp_continue, loc, unit_ty, exp_env_ref);
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        ED::Pexp_tuple(exprs) => {
            // Tuple expression
            assert!(exprs.len() >= 2, "Tuple must have at least 2 elements");

            // Create fresh type variables for each element
            let elem_types: Vec<TypeExprRef> = tctx
                .arena
                .expr_list(*exprs)
                .iter()
                .map(|_| ctx.new_var(None))
                .collect();

            // Create tuple type and unify (instance generic expected_ty to avoid corruption)
            let tuple_ty = ctx.new_tuple(elem_types.clone());
            let eff_expected = instance_if_generic(ctx, expected_ty);
            // OCaml typecore.ml:2670: `unify_exp_types ~context:None`.
            unify_expression_types(tctx, loc, tuple_ty, eff_expected, None)?;

            // Type check each element
            let mut typed_exprs = Vec::new();
            for (e, ty) in tctx.arena.expr_list(*exprs).iter().zip(elem_types.iter()) {
                let typed_expr = type_expect(tctx, env, tctx.arena.get_expanded_expr(*e), *ty, None)?;
                typed_exprs.push(typed_expr);
            }

            // Keep sharing: create fresh Ttuple from sub-expression types
            // (matches OCaml: exp_type = newty (Ttuple (List.map (fun e -> e.exp_type) expl)))
            let result_ty = ctx.new_tuple(typed_exprs.iter().map(|e| e.exp_type).collect());
            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_tuple(tctx.typed.push_exprs(typed_exprs)),
                    loc,
                    result_ty,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        ED::Pexp_let(inner) => {
            let (ref rec_flag, ref bindings, ref body_idx) = *inner;
            let arena = tctx.arena;
            if let Some(binding) = crate::parser::parsetree_viewer::single_record_binding(arena, *rec_flag, *bindings) {
                let case = crate::parser::ast::Case {
                    pc_bar: None,
                    pc_lhs: binding.pvb_pat,
                    pc_guard: None,
                    pc_rhs: *body_idx,
                };
                return crate::types::typemod::with_warning_scope(
                    tctx, arena, &binding.pvb_attributes, true, |tctx| {
                        type_match(tctx, env, loc, &expr.pexp_attributes,
                            &binding.pvb_attributes, arena.get_expanded_expr(binding.pvb_expr),
                            std::slice::from_ref(&case), expected_ty, match_context)
                    },
                );
            }
            // typecore.ml:2648-2673: a non-recursive let of one binding
            // without a type constraint whose pattern contains a GADT
            // constructor is typed as a one-case match, without the caller's
            // context and with function-style diagnostics. The binding's
            // attributes go on the case pattern, in front of its own.
            let arena = tctx.arena;
            if *rec_flag == RecFlag::Nonrecursive
                && let [binding] = arena.vb_list(*bindings)
                && arena.value_constraint(binding.pvb_pat).is_none()
                && pattern_contains_generalized_constructor(
                    tctx,
                    env,
                    arena.get_pat(binding.pvb_pat),
                )
            {
                // `pvb_attributes @ spat.ppat_attributes` is the pattern's own
                // list when the binding has none.
                let case_pat = if binding.pvb_attributes.is_empty() {
                    binding.pvb_pat
                } else {
                    let spat = arena.get_pat(binding.pvb_pat);
                    let mut attributes = Vec::with_capacity(
                        binding.pvb_attributes.len() + spat.ppat_attributes.len(),
                    );
                    attributes.extend(binding.pvb_attributes.iter().cloned());
                    attributes.extend(spat.ppat_attributes.iter().cloned());
                    arena.push_typecheck_pattern(ParsedPattern {
                        ppat_desc: spat.ppat_desc.clone(),
                        ppat_loc: spat.ppat_loc,
                        ppat_attributes: Attributes::from_vec(attributes),
                    })
                };
                let cases = arena.push_shared_case_list(&[crate::parser::ast::Case {
                    pc_bar: None,
                    pc_lhs: case_pat,
                    pc_guard: None,
                    pc_rhs: *body_idx,
                }]);
                let match_expr = ParsedExpression {
                    pexp_desc: ED::Pexp_match((binding.pvb_expr, cases)),
                    pexp_loc: expr.pexp_loc,
                    pexp_attributes: expr.pexp_attributes.clone(),
                };
                return type_expect_full(
                    tctx,
                    env,
                    &match_expr,
                    expected_ty,
                    None,
                    RecArg::Rejected,
                    Some(MatchContext::Function),
                );
            }
            // Let expression
            // OCaml does NOT reset typetexp.type_variables for local Pexp_let.
            // reset_type_variables happens at top-level expression/binding entry.
            let (typed_bindings, new_env, unpacks) = type_let_bindings(
                tctx,
                env,
                *rec_flag,
                tctx.arena.vb_list(*bindings),
                true,
                LetCheck::Local,
            )?;

            // Type check body in extended environment
            let body = tctx.arena.get_expanded_expr(*body_idx);
            let typed_body =
                type_expect_with_module_unpacks(tctx, &new_env, body, expected_ty, &unpacks, None)?;
            let body_type = typed_body.exp_type;
            // OCaml typecore.ml:2452-2458 runs Rec_check after typing the body.
            if *rec_flag == RecFlag::Recursive {
                check_recursive_bindings(&tctx.typed, tctx.type_ctx, &typed_bindings)?;
            }

            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_let(
                        *rec_flag,
                        tctx.typed.push_value_bindings(typed_bindings),
                        tctx.push_expr(typed_body),
                    ),
                    loc,
                    body_type,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        ED::Pexp_sequence(e1_idx, e2_idx) => {
            // Sequence expression: e1; e2
            let e1 = tctx.arena.get_expanded_expr(*e1_idx);
            let typed_e1 = type_statement(tctx, env, e1)?;
            if matches!(
                &typed_e1.exp_desc,
                ExpressionDesc::Texp_break | ExpressionDesc::Texp_continue
            ) {
                let loc = final_subexpression(tctx.arena, e1).pexp_loc;
                tctx.report_warning(loc, Warning::NonreturningStatement);
            }

            // e2 has the expected type
            let e2 = tctx.arena.get_expanded_expr(*e2_idx);
            let typed_e2 = type_expect(tctx, env, e2, expected_ty, None)?;
            let e2_type = typed_e2.exp_type;

            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_sequence(
                        tctx.push_expr(typed_e1),
                        tctx.push_expr(typed_e2),
                    ),
                    loc,
                    e2_type,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        ED::Pexp_ifthenelse(_) | ED::Pexp_ternary(_) => {
            // typecore.ml `(Pexp_ifthenelse _ | Pexp_ternary _) as conditional`.
            let (cond_idx, then_idx, else_idx, return_context) = match &expr.pexp_desc {
                ED::Pexp_ifthenelse(inner) => {
                    (inner.0, inner.1, inner.2, Some(ClashSite::IfReturn))
                }
                ED::Pexp_ternary(inner) => (
                    inner.0,
                    inner.1,
                    Some(inner.2),
                    Some(ClashSite::TernaryReturn),
                ),
                _ => unreachable!(),
            };
            type_conditional(tctx, env, expr, expected_ty, context, exp_env_ref,
                cond_idx, then_idx, else_idx, return_context)
        }

        ED::Pexp_while(cond_idx, body_idx) => {
            // While loop
            // OCaml passes Predef.type_bool/unit to type_expect; rue instances each.
            // Use separate unit types for body and result (matching OCaml's rue pattern).
            let bool_ty = env.type_bool(ctx);

            let cond = tctx.arena.get_expanded_expr(*cond_idx);
            let typed_cond = type_expect(
                tctx,
                env,
                cond,
                bool_ty,
                Some(ClashSite::WhileCondition),
            )?;
            let body = tctx.arena.get_expanded_expr(*body_idx);
            let typed_body = with_loop_depth(tctx, |tctx| type_statement(tctx, env, body))?;

            // OCaml typecore.ml:3082-3090: `rue { ... exp_type = instance_def
            // Predef.type_unit }`, i.e. `unify env unit (instance ty_expected)`.
            let result_unit_ty = env.type_unit(ctx);
            rue_unify(tctx, loc, result_unit_ty, expected_ty, context)?;

            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_while(
                        tctx.push_expr(typed_cond),
                        tctx.push_expr(typed_body),
                    ),
                    loc,
                    result_unit_ty,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        ED::Pexp_assert(e_idx) => {
            // Assert expression
            let bool_ty = env.type_bool(ctx);

            let e = tctx.arena.get_expanded_expr(*e_idx);
            let typed_e = type_expect(
                tctx,
                env,
                e,
                bool_ty,
                Some(ClashSite::AssertCondition),
            )?;

            // assert(false) has the expected type (polymorphic), others have type unit
            let exp_type = match &typed_e.exp_desc {
                ExpressionDesc::Texp_construct(_, cd, _) if cd.cstr_name == "false" => expected_ty,
                _ => {
                    // OCaml typecore.ml:3401-3414: `rue` unifies
                    // `instance_def Predef.type_unit` with `instance env ty_expected`.
                    let unit_ty = env.type_unit(ctx);
                    rue_unify(tctx, loc, unit_ty, expected_ty, context)?;
                    unit_ty
                }
            };

            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_assert(tctx.push_expr(typed_e)),
                    loc,
                    exp_type,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        ED::Pexp_array(exprs) => {
            // OCaml compiler/ml/typecore.ml:3027-3029 uses `newgenvar ()`
            // and `Predef.type_array`; compiler/ml/predef.ml:127 builds that
            // array constructor at generic level.
            let elem_ty = ctx.new_generic_var(None);
            let array_ty =
                ctx.new_generic_predef_constr(crate::types::predef::path_array(), vec![elem_ty]);

            unify_expression_types(tctx, loc, array_ty, expected_ty, None)?;

            let mut typed_exprs = Vec::new();
            for e in tctx.arena.expr_list(*exprs).iter() {
                let typed_e = type_expect(
                    tctx,
                    env,
                    tctx.arena.get_expanded_expr(*e),
                    elem_ty,
                    Some(ClashSite::ArrayLiteral),
                )?;
                typed_exprs.push(typed_e);
            }

            // OCaml compiler/ml/typecore.ml:3027-3038 unifies
            // `Predef.type_array ty` with `ty_expected`, types elements with
            // `ty`, then stores `exp_type = instance env ty_expected` rather
            // than the temporary array node.
            let exp_type = crate::types::instance(ctx, expected_ty);
            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_array(tctx.typed.push_exprs(typed_exprs)),
                    loc,
                    exp_type,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        // compiler/ml/typecore.ml Pexp_dict: the values have the type of the
        // dict's values, the spreads its type; both built at generic level.
        ED::Pexp_dict(entries) => {
            let dict_type =
                |ty| ctx.new_generic_predef_constr(crate::types::predef::path_dict(), vec![ty]);
            let ty = ctx.new_generic_var(None);
            unify_expression_types(tctx, loc, dict_type(ty), expected_ty, None)?;
            let mut typed_entries = Vec::with_capacity(entries.len());
            for entry in entries.iter() {
                typed_entries.push(match entry {
                    crate::parser::ast::DictEntry::Pdict_entry(key, svalue) => {
                        TypedDictEntry::Tdict_entry(
                            Located {
                                txt: tctx.arena.get_string(key.txt).to_string(),
                                loc: key.loc,
                            },
                            { let value = type_expect(tctx, env, tctx.arena.get_expanded_expr(*svalue), ty, None)?; tctx.push_expr(value) },
                        )
                    }
                    crate::parser::ast::DictEntry::Pdict_spread(sspread) => {
                        TypedDictEntry::Tdict_spread({ let value = type_expect(
                            tctx,
                            env,
                            tctx.arena.get_expanded_expr(*sspread),
                            dict_type(ty),
                            None,
                        )?; tctx.push_expr(value) })
                    }
                });
            }
            let exp_type = crate::types::instance(ctx, expected_ty);
            let node = Expression::new(
                ExpressionDesc::Texp_dict(tctx.typed.push_dict_entries(typed_entries)),
                loc,
                exp_type,
                exp_env_ref,
            );
            Ok(tctx.typed.with_exp_attributes(node, expr.pexp_attributes.clone()))
        }

        // compiler/ml/typecore.ml Pexp_spread: the literal is typed as the
        // arrays or lists it concatenates (`Ast_spread.parts`), each against a
        // fresh generic container of the element type, so the items keep the
        // errors of array and list literals.
        ED::Pexp_spread(kind, elements) => {
            let kind = *kind;
            let container_type = |ty| {
                let path = match kind {
                    crate::parser::ast::SpreadKind::Spread_array => {
                        crate::types::predef::path_array()
                    }
                    crate::parser::ast::SpreadKind::Spread_list => {
                        crate::types::predef::path_list()
                    }
                };
                ctx.new_generic_predef_constr(path, vec![ty])
            };
            let ty = ctx.new_generic_var(None);
            unify_expression_types(tctx, loc, container_type(ty), expected_ty, None)?;
            let mut store = tctx.arena;
            let sparts = crate::parser::ast_spread::parts(
                &mut store,
                kind,
                tctx.arena.spread_element_list(*elements),
            );
            let mut parts = Vec::with_capacity(sparts.len());
            for spart in sparts {
                parts.push(type_expect(
                    tctx,
                    env,
                    tctx.arena.get_expanded_expr(spart),
                    container_type(ty),
                    None,
                )?);
            }
            let exp_type = crate::types::instance(ctx, expected_ty);
            let node = Expression::new(
                ExpressionDesc::Texp_spread(kind, tctx.typed.push_exprs(parts)),
                loc,
                exp_type,
                exp_env_ref,
            );
            Ok(tctx.typed.with_exp_attributes(node, expr.pexp_attributes.clone()))
        }

        // compiler/ml/typecore.ml Pexp_template: validate every segment, type
        // the values as string-concatenation operands.
        ED::Pexp_template(template) => {
            ctx.begin_def();
            let mut segments = Vec::with_capacity(template.source_segments.len());
            for source in &template.source_segments {
                match crate::string_literal::template_from_source(tctx.arena.get_string(source.txt))
                {
                    Some(segment) => segments.push(segment),
                    None => {
                        return Err(TypeCoreError::InvalidStringEscapeSequence { loc: source.loc });
                    }
                }
            }
            let mut values = Vec::with_capacity(template.values.len());
            for value in &template.values {
                let string_ty = env.type_string(ctx);
                values.push(type_expect(
                    tctx,
                    env,
                    tctx.arena.get_expanded_expr(*value),
                    string_ty,
                    Some(ClashSite::StringConcat),
                )?);
            }
            ctx.end_def();
            let exp_type = crate::types::instance(ctx, env.type_string(ctx));
            rue_unify(tctx, loc, exp_type, expected_ty, context)?;
            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_template {
                        segments,
                        values: tctx.typed.push_exprs(values),
                    },
                    loc,
                    exp_type,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        // compiler/ml/typecore.ml Pexp_tagged_template: the tag must be a
        // value of the builtin `taggedTemplate<'param, 'output>` type.
        ED::Pexp_tagged_template(template) => {
            ctx.begin_def();
            let stag = tctx.arena.get_expanded_expr(template.tag);
            let tag_var = ctx.new_var(None);
            tctx.deprecated_function_call = true;
            let tag = type_expect(tctx, env, stag, tag_var, None)?;
            let param_ty = ctx.new_var(None);
            let output_ty = ctx.new_var(None);
            let tag_ty = ctx.new_constr(
                crate::types::predef::path_tagged_template(),
                vec![param_ty, output_ty],
            );
            tctx.set_unify_env(env);
            if crate::types::ctype::unify(
                ctx,
                &mut tctx.unify_state,
                crate::types::instance(ctx, tag.exp_type),
                tag_ty,
            )
            .is_err()
            {
                return Err(TypeCoreError::TaggedTemplateNonTag {
                    loc: tag.exp_loc,
                    typ: tag.exp_type,
                });
            }
            let mut values = Vec::with_capacity(template.values.len());
            for value in &template.values {
                values.push(type_expect(
                    tctx,
                    env,
                    tctx.arena.get_expanded_expr(*value),
                    param_ty,
                    Some(ClashSite::TaggedTemplateValue),
                )?);
            }
            unify_expression_types(tctx, loc, ctx.new_var(None), tag.exp_type, None)?;
            ctx.end_def();
            rue_unify(tctx, loc, output_ty, expected_ty, context)?;
            let raw_sources = template
                .raw_sources
                .iter()
                .map(|source| tctx.arena.get_string(source.txt).to_string())
                .collect();
            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_tagged_template {
                        tag: tctx.push_expr(tag),
                        raw_sources,
                        values: tctx.typed.push_exprs(values),
                    },
                    loc,
                    output_ty,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }

        ED::Pexp_apply(_) => unreachable!("applications were typed above"),

        ED::Pexp_match(inner) => {
            let (ref scrutinee_idx, ref cases) = *inner;
            if let Some((yes, no)) = crate::parser::parsetree_viewer::boolean_match_arms(tctx.arena, *cases) {
                return type_conditional(tctx, env, expr, expected_ty, context, exp_env_ref,
                    *scrutinee_idx, yes, Some(no), Some(ClashSite::IfReturn));
            }
            let scrutinee = tctx.arena.get_expanded_expr(*scrutinee_idx);

            // Normal match expression
            type_match(
                tctx,
                env,
                expr.pexp_loc,
                &expr.pexp_attributes,
                &[],
                scrutinee,
                tctx.arena.case_list(*cases),
                expected_ty,
                match_context,
            )
        }

        ED::Pexp_try(inner) => {
            let (ref body_idx, ref handlers, ref finally) = *inner;
            // Try expression
            let body = tctx.arena.get_expanded_expr(*body_idx);
            type_try(
                tctx,
                env,
                expr,
                body,
                tctx.arena.case_list(*handlers),
                finally.map(|finally| tctx.arena.get_expanded_expr(finally)),
                expected_ty,
            )
        }

        ED::Pexp_fun(inner) => {
            let params_bindings = tctx
                .arena
                .nary_fun_default_bindings(inner)
                .expect("function defaults prepared before type checking")
                .to_vec();
            let newtypes = tctx.arena.nary_fun_newtypes(inner).to_vec();
            let body = tctx.arena.nary_fun_body(inner);
            if newtypes.is_empty() {
                type_function_nary(
                    tctx,
                    env,
                    loc,
                    &params_bindings,
                    body,
                    inner.is_async,
                    expected_ty,
                    &expr.pexp_attributes,
                )
            } else {
                type_function_nary_with_newtypes(
                    tctx,
                    env,
                    loc,
                    &newtypes,
                    &params_bindings,
                    body,
                    inner.is_async,
                    expected_ty,
                    &expr.pexp_attributes,
                )
            }
        }

        ED::Pexp_for(inner) => {
            // For loop
            type_for(tctx, env, expr, inner, expected_ty, context)
        }

        // Upstream #7887: for-of / for-await-of typing.
        // - `for x of e { body }`: `e` should unify with `iterable<'a>`. To
        //   match OCaml's convenience fallback for raw arrays, also accept
        //   `array<'a>` if iterable unification fails.
        // - `for await x of e { body }`: `e` must unify with
        //   `asyncIterable<'a>`. (No array fallback for the await form.)
        ED::Pexp_for_of(inner) => type_for_of(tctx, env, expr, inner, expected_ty, context),
        ED::Pexp_for_await_of(inner) => type_for_of(tctx, env, expr, inner, expected_ty, context),

        ED::Pexp_construct(lid, sargs) => {
            // Constructor application
            type_construct(
                tctx,
                env,
                loc,
                lid,
                sargs,
                expected_ty,
                &expr.pexp_attributes,
            )
        }

        ED::Pexp_variant(inner) => {
            let (ref label, ref sargs) = **inner;
            check_polyvar_name(loc, label)?;
            // typecore.ml Pexp_variant: several arguments form one tuple
            // payload located at the argument list.
            let sarg = match tctx.arena.expr_list(sargs.txt) {
                [] => None,
                [sarg] => Some(*sarg),
                args => Some(tctx.arena.push_shared_expr(ParsedExpression {
                    pexp_desc: ED::Pexp_tuple(tctx.arena.push_shared_expr_list(args)),
                    pexp_loc: sargs.loc,
                    pexp_attributes: Attributes::new(),
                })),
            };
            // Polymorphic variant
            type_variant(
                tctx,
                env,
                expr,
                label,
                sarg.map(|idx| tctx.arena.get_expanded_expr(idx)),
                expected_ty,
                context,
            )
        }

        ED::Pexp_record(inner) => {
            let (_, ref base) = *inner;
            // Record expression
            // OCaml quirk: in `Pexp_record (lid_sexp_list, Some sexp)`, the pattern
            // variable `sexp` shadows the outer function parameter, so
            // `sexp.pexp_attributes` at the result uses the spread expression's
            // attributes, not the record expression's attributes.
            let attrs = match base {
                Some(base_expr) => &tctx.arena.get_expanded_expr(*base_expr).pexp_attributes,
                None => &expr.pexp_attributes,
            };
            type_record(tctx, env, loc, inner, expected_ty, attrs, recarg)
        }

        ED::Pexp_field(..) => unreachable!("field access was typed above"),

        ED::Pexp_setfield(inner) => {
            let (ref record_expr_idx, ref field_lid, ref new_value_idx) = **inner;
            // Field assignment
            let record_expr = tctx.arena.get_expanded_expr(*record_expr_idx);
            let new_value = tctx.arena.get_expanded_expr(*new_value_idx);
            type_setfield(
                tctx,
                env,
                loc,
                record_expr,
                field_lid,
                new_value,
                expected_ty,
                context,
                &expr.pexp_attributes,
            )
        }

        ED::Pexp_constraint(inner) => {
            let (ref inner_expr_idx, ref core_type) = **inner;
            // Type constraint
            let inner_expr = tctx.arena.get_expanded_expr(*inner_expr_idx);
            let core_type_ref = tctx.arena.get_core_type(*core_type);
            type_constraint(
                tctx,
                env,
                expr,
                inner_expr,
                core_type_ref,
                expected_ty,
                context,
            )
        }

        ED::Pexp_coerce(inner) => {
            let (ref inner_expr_idx, ref opt_from_type, ref to_type) = **inner;
            // Type coercion: (E :> T) or (E : T1 :> T2)
            let inner_expr = tctx.arena.get_expanded_expr(*inner_expr_idx);
            let to_type_ref = tctx.arena.get_core_type(*to_type);
            let opt_from_type_ref = opt_from_type.map(|idx| tctx.arena.get_core_type(idx));
            type_coerce(
                tctx,
                env,
                loc,
                inner_expr,
                opt_from_type_ref,
                to_type_ref,
                expected_ty,
                &expr.pexp_attributes,
            )
        }

        ED::Pexp_open(inner) => {
            let (ref override_flag, ref lid, ref body_idx) = **inner;
            // Open expression: M.{ E } or open M; E
            let body = tctx.arena.get_expanded_expr(*body_idx);
            type_open(tctx, env, expr, override_flag, lid, body, expected_ty)
        }

        ED::Pexp_newtype(inner) => {
            let (ref name, ref body_idx) = **inner;
            // Newtype expression: (type t) => E
            let body = tctx.arena.get_expanded_expr(*body_idx);
            type_newtype(
                tctx,
                env,
                loc,
                name,
                body,
                expected_ty,
                &expr.pexp_attributes,
            )
        }

        ED::Pexp_await(_) => unreachable!("await was typed above"),

        ED::Pexp_object_get(inner) => {
            let (ref obj_expr_idx, ref method) = **inner;
            // Method send: E#m
            let obj_expr = tctx.arena.get_expanded_expr(*obj_expr_idx);
            type_object_get(
                tctx,
                env,
                loc,
                obj_expr,
                method,
                expected_ty,
                context,
                &expr.pexp_attributes,
            )
        }

        ED::Pexp_object_set(inner) => {
            let (ref obj_expr_idx, ref field, ref value_idx) = **inner;
            let obj_expr = tctx.arena.get_expanded_expr(*obj_expr_idx);
            let value = tctx.arena.get_expanded_expr(*value_idx);
            type_object_set(
                tctx,
                env,
                loc,
                obj_expr,
                field,
                value,
                expected_ty,
                context,
                &expr.pexp_attributes,
            )
        }

        ED::Pexp_object_literal(fields) => type_object_literal(
            tctx,
            env,
            loc,
            fields,
            expected_ty,
            context,
            &expr.pexp_attributes,
        ),

        ED::Pexp_letexception(inner) => {
            let (ref ext_constr, ref body_idx) = **inner;
            // Let exception: { exception C; E }
            let body = tctx.arena.get_expanded_expr(*body_idx);
            type_letexception(
                tctx,
                env,
                loc,
                ext_constr,
                body,
                expected_ty,
                &expr.pexp_attributes,
            )
        }

        // typecore.ml: the built-in PPX lowers raw JavaScript before type
        // checking.
        ED::Pexp_raw(raw) => Err(uninterpreted_raw_error(
            raw.name_loc,
            crate::ast_raw::extension_name(raw.kind),
        )),
        // typecore.ml `Pexp_todo`: the built-in PPX lowers %todo before type
        // checking.
        ED::Pexp_todo(todo) => Err(uninterpreted_raw_error(
            todo.name_loc,
            crate::ast_todo::NAME,
        )),

        ED::Pexp_extension(extension) => {
            // Extension: [%id]. typecore.ml `Pexp_extension ext ->
            // raise (Error_forward (Builtin_attributes.error_of_extension ext))`.
            Err(builtin_extension_error(tctx.arena, extension))
        }

        ED::Pexp_letmodule(inner) => {
            let (ref name, ref module_expr, ref body_idx) = **inner;
            // Let module: { module M = ME; E }
            let module_expr_ref = tctx.arena.get_mod_expr(*module_expr);
            let body = tctx.arena.get_expanded_expr(*body_idx);
            type_letmodule(
                tctx,
                env,
                loc,
                name,
                module_expr_ref,
                body,
                expected_ty,
                &expr.pexp_attributes,
            )
        }

        ED::Pexp_pack(module_expr_idx) => {
            // Pack: module(ME)
            let module_expr = tctx.arena.get_mod_expr(*module_expr_idx);
            type_pack(
                tctx,
                env,
                loc,
                module_expr,
                expected_ty,
                context,
                &expr.pexp_attributes,
            )
        }

        ED::Pexp_jsx_element(_) => {
            // JSX element - typically transformed before type checking
            Err(TypeCoreError::JsxNotEnabled { loc })
        }
    }
}

/// Type a value identifier without requiring a parsed expression node.
/// Cost: the existing value lookup, instantiation and unification, then one
/// typed identifier; no additional lookup or parsed-node allocation.
#[allow(clippy::too_many_arguments)]
fn type_identifier(
    tctx: &mut TypeCheckContext<'_>, env: &Env, expr: &ParsedExpression,
    loc: LocIdx, lid: &Located<LidentIdx>, attributes: &Attributes,
    expected_ty: &mut Expected, context: Option<ClashSite>, recarg: RecArg,
    deprecated_function_call: bool,
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    let longident = tctx.arena.get_longident(lid.txt);

    // Normal identifier expression.
    let (path, desc) = match lookup_value_ident(tctx, env, longident, lid.loc) {
        Ok(result) => result,
        Err(ValueLookupFailure::IllegalName) => {
            return Err(TypeCoreError::IllegalValueName {
                loc: lid.loc,
                name: tctx.arena.get_string(longident.last_idx()).to_string(),
            });
        }
        Err(ValueLookupFailure::Unbound) => {
            if let Some(err) = unbound_module_prefix_error(tctx, env, lid.loc, longident) {
                return Err(err);
            }
            // typecore.ml Pexp_ident: `<Button />` refers to
            // `Button.make`. The module exists (otherwise the lookup
            // reports it as unbound), but it defines no component.
            if let Longident::Ldot(module_lid, last) = longident
                && matches!(context, Some(ClashSite::JsxComponent))
                && tctx.arena.get_string(*last) == "make"
            {
                let module_lid = tctx.longident_to_string(module_lid);
                let alternatives = unbound_value_alternatives(tctx, env, longident);
                return Err(TypeCoreError::JsxComponentWithoutMake {
                    loc: lid.loc,
                    module_lid,
                    alternatives,
                });
            }
            return Err(unbound_value_error(tctx, env, lid.loc, longident));
        }
    };
    note_value_ident_use(tctx, env, longident, lid.loc, &path, &desc, deprecated_function_call)?;
    check_inlined_record_escape(ctx, loc, desc.val_type, recarg)?;

    let ty = crate::types::instance(ctx, desc.val_type);
    finish_expected_at(tctx, expr, loc, ty, expected_ty, context)?;

    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_ident(path, *lid, desc),
            loc,
            ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.clone())
    })
}

/// Finish a case-1 expression. Materialise when unification would do more
/// than link the unobservable expected variable, retaining the original
/// representative choice, level updates and error traces in those cases.
fn finish_expected(
    tctx: &mut TypeCheckContext<'_>,
    expr: &ParsedExpression,
    ty: TypeExprRef,
    expected: &mut Expected,
    context: Option<ClashSite>,
) -> TypeCoreResult<()> {
    finish_expected_at(tctx, expr, expr.pexp_loc, ty, expected, context)
}

/// Finish an expected type at the construct's semantic location.
/// Cost: the existing expected-variable check and, when needed, unification;
/// no location allocation, traversal or additional type lookup.
fn finish_expected_at(
    tctx: &mut TypeCheckContext<'_>, expr: &ParsedExpression, loc: LocIdx,
    ty: TypeExprRef, expected: &mut Expected, context: Option<ClashSite>,
) -> TypeCoreResult<()> {
    if let Expected::Infer { level, .. } = *expected
        && crate::types::ctype::fresh_expected_only_links(tctx.type_ctx, ty, level)
    {
        return Ok(());
    }
    let expected = materialize_expected(tctx, expr, expected);
    rue_unify(tctx, loc, ty, expected, context)
}

fn materialize_expected(
    tctx: &TypeCheckContext<'_>,
    expr: &ParsedExpression,
    expected: &mut Expected,
) -> TypeExprRef {
    match *expected {
        Expected::Known(ty) => ty,
        Expected::Infer { level, site } => {
            if tctx.type_ctx.compiler_counters_enabled() {
                let site = match site {
                    InferenceSite::Expression => expected_var_use(expr),
                    InferenceSite::ApplicationFunction => crate::perf_counters::ExpectedVar {
                        construct: "application: function",
                        case: 1,
                    },
                };
                crate::perf_counters::record_expected_var(site);
            }
            let ty = tctx.type_ctx.new_var(None);
            tctx.type_ctx.set_level(ty, level);
            *expected = Expected::Known(ty);
            ty
        }
    }
}

/// Unify expression types, raising ExprTypeClash on error.
fn unify_expression_types(
    tctx: &mut TypeCheckContext<'_>,
    loc: LocIdx,
    ty1: TypeExprRef,
    ty2: TypeExprRef,
    context: Option<ClashSite>,
) -> TypeCoreResult<()> {
    use crate::types::unify;

    let result = unify(tctx.type_ctx, &mut tctx.unify_state, ty1, ty2);

    match result {
        Ok(()) => Ok(()),
        Err(err) => {
            // OCaml compiler/ml/typecore.ml:345-348 reports `Ctype.Unify`
            // directly from `unify_exp_types`; alias expansion and constructor
            // representative choice must already have happened inside
            // compiler/ml/ctype.ml unification, not in a typecore-side retry.
            let trace = match err {
                TypeError::Unify(trace) if !trace.is_empty() => trace,
                _ => vec![(ty1, ty2)],
            };
            let env = tctx
                .unify_state
                .env()
                .map(|env| tctx.type_ctx.store_typed_env(env));
            Err(TypeCoreError::ExprTypeClash {
                loc,
                trace,
                context: context.map(|site| site.resolve(tctx.arena)),
                env,
            })
        }
    }
}

/// Instance a type if it's at GENERIC_LEVEL, otherwise return it unchanged.
/// Used to protect generic expected types from corruption by non-rue handlers.
fn instance_if_generic(ctx: &TypeContext, ty: TypeExprRef) -> TypeExprRef {
    if ctx.get_level(ctx.repr(ty)) == crate::types::type_expr::GENERIC_LEVEL {
        crate::types::instance(ctx, ty)
    } else {
        ty
    }
}

/// OCaml's `rue` mechanism: always instance the expected type before unifying.
/// This matters even for monomorphic expected types, because OCaml still copies
/// the top-level node and preserves distinct physical identities in the typed tree.
/// `proper_exp_loc` (typecore.ml:2260-2266): the location of the outermost
/// constraint/coercion in `exp_extra`, else the expression's location.
fn proper_exp_loc(ta: &TypedArena, exp: &Expression) -> LocIdx {
    ta.exp_extra(exp)
        .iter()
        .find_map(|(extra, loc, _)| match extra {
            crate::types::typedtree::ExpExtra::Texp_constraint(_)
            | crate::types::typedtree::ExpExtra::Texp_coerce { .. } => Some(*loc),
            _ => None,
        })
        .unwrap_or(exp.exp_loc)
}

fn rue_unify(
    tctx: &mut TypeCheckContext<'_>,
    loc: LocIdx,
    exp_ty: TypeExprRef,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
) -> TypeCoreResult<()> {
    let inst = crate::types::instance(tctx.type_ctx, expected_ty);
    unify_expression_types(tctx, loc, exp_ty, inst, context)
}

// ============================================================================
// Expression Type Checking Helpers
// ============================================================================

/// Type check function application.
#[allow(clippy::too_many_arguments)]
/// Unified ops form (unary or binary).
#[derive(Clone, Copy, PartialEq)]
enum UnifiedOpForm {
    Unary,
    Binary,
}

#[derive(Clone, Copy)]
struct UnifiedOpSpecialization {
    supports_bool: bool,
    supports_float: bool,
    supports_bigint: bool,
    supports_string: bool,
}

#[derive(Clone, Copy)]
struct UnifiedOpEntry {
    form: UnifiedOpForm,
    specialization: UnifiedOpSpecialization,
}

const fn unified_op_entry(
    form: UnifiedOpForm,
    supports_float: bool,
    supports_bigint: bool,
    supports_string: bool,
) -> UnifiedOpEntry {
    UnifiedOpEntry {
        form,
        specialization: UnifiedOpSpecialization {
            supports_bool: false,
            supports_float,
            supports_bigint,
            supports_string,
        },
    }
}

/// Check if a path (by name) is a unified op, returning its OCaml entry.
/// `get_unified_op_entry` for the path `Pervasives.<op>`.
fn get_unified_op_entry_for_op(op: &str) -> Option<UnifiedOpEntry> {
    match op {
        "~+" | "~-" | "~~~" | "+" | "-" | "*" | "/" | "%" | "mod" | "**" | "<<" | ">>" | "|||"
        | "^^^" | "&&&" | ">>>" => get_unified_op_entry(&format!("Pervasives.{op}")),
        _ => None,
    }
}

fn get_unified_op_entry(path_name: &str) -> Option<UnifiedOpEntry> {
    use UnifiedOpForm::{Binary, Unary};

    // OCaml compiler/ml/unified_ops.ml:40-54 defines the specialization shape,
    // and unified_ops.ml:58-262 lists these per-operator capabilities.
    match path_name {
        "Pervasives.~+" | "Pervasives.~-" => Some(unified_op_entry(Unary, true, true, false)),
        "Pervasives.~~~" => Some(unified_op_entry(Unary, false, true, false)),
        "Pervasives.+" => Some(unified_op_entry(Binary, true, true, true)),
        "Pervasives.-" | "Pervasives.*" | "Pervasives./" | "Pervasives.%" | "Pervasives.mod"
        | "Pervasives.**" => Some(unified_op_entry(Binary, true, true, false)),
        "Pervasives.<<" | "Pervasives.>>" | "Pervasives.|||" | "Pervasives.^^^"
        | "Pervasives.&&&" => Some(unified_op_entry(Binary, false, true, false)),
        "Pervasives.>>>" => Some(unified_op_entry(Binary, false, false, false)),
        _ => None,
    }
}

/// Check if a resolved type is a Tconstr matching a specific type name.
fn is_type_named(ctx: &TypeContext, ty: TypeExprRef, name: &str) -> bool {
    let ty = ctx.repr(ty);
    let desc = ctx.get_desc(ty);
    match &*desc {
        TypeDesc::Tconstr { path, args, .. } if args.is_empty() => match path.view() {
            PathView::Pident(id) => id.name() == name,
            _ => false,
        },
        _ => false,
    }
}

fn unified_specialized_type_name(
    ctx: &TypeContext,
    ty: TypeExprRef,
    specialization: UnifiedOpSpecialization,
) -> Option<&'static str> {
    if is_type_named(ctx, ty, "int") {
        Some("int")
    } else if specialization.supports_bool && is_type_named(ctx, ty, "bool") {
        Some("bool")
    } else if specialization.supports_float && is_type_named(ctx, ty, "float") {
        Some("float")
    } else if specialization.supports_bigint && is_type_named(ctx, ty, "bigint") {
        Some("bigint")
    } else if specialization.supports_string && is_type_named(ctx, ty, "string") {
        Some("string")
    } else {
        None
    }
}

fn unified_expected_type(env: &Env, ctx: &TypeContext, type_name: &str) -> TypeExprRef {
    match type_name {
        "int" => env.type_int(ctx),
        "bool" => env.type_bool(ctx),
        "float" => env.type_float(ctx),
        "bigint" => env.type_bigint(ctx),
        "string" => env.type_string(ctx),
        _ => unreachable!("unknown unified op primitive type"),
    }
}

/// Translate unified ops: specialized type-checking for polymorphic operators.
///
/// This matches OCaml's `translate_unified_ops` in typecore.ml.
/// Unified ops like `+`, `-`, `*`, etc. are polymorphic in Pervasives
/// (type `('a, 'a) => 'a`) but get specialized based on the argument types.
/// The default fallback is `int`.
///
/// Crucially, this does NOT unify the operator's polymorphic type with the
/// concrete arg/result types, so the operator expression keeps its
/// polymorphic instance type (with shared Tvars and cycles in sexp output).
#[allow(clippy::too_many_arguments)]
fn translate_unified_ops(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    sexp: &ParsedExpression,
    loc: LocIdx,
    attributes: &[crate::parser::ast::Attribute],
    args: &[(ArgLabel, crate::parse_arena::ExprIdx)],
    transformed_jsx: bool,
    typed_funct: &Expression,
    expected_ty: &mut Expected,
    context: Option<ClashSite>,
) -> Option<TypeCoreResult<Expression>> {
    use crate::types::typedtree::ApplyArg;

    // Check if the function is a unified op (`Pervasives.<op>`).
    let path_name = match &typed_funct.exp_desc {
        ExpressionDesc::Texp_ident(path, _, _) => match path.view() {
            PathView::Pdot(parent, op, _) if matches!(parent.view(), PathView::Pident(id) if id.name() == "Pervasives") =>
            {
                get_unified_op_entry_for_op(op)?;
                path.name()
            }
            _ => return None,
        },
        _ => return None,
    };

    let entry = get_unified_op_entry(&path_name)?;

    let ctx = tctx.type_ctx;

    match entry.form {
        UnifiedOpForm::Binary if args.len() == 2 => {
            let lhs_expr = tctx.arena.get_expanded_expr(args[0].1);
            let rhs_expr = tctx.arena.get_expanded_expr(args[1].1);

            let lhs = match type_exp(tctx, env, lhs_expr, None) {
                Ok(e) => e,
                Err(e) => return Some(Err(e)),
            };
            let lhs_type = crate::types::ctype::expand_head(ctx, env, lhs.exp_type);

            let rhs = match type_exp(tctx, env, rhs_expr, None) {
                Ok(e) => e,
                Err(e) => return Some(Err(e)),
            };
            let rhs_type = crate::types::ctype::expand_head(ctx, env, rhs.exp_type);

            // OCaml compiler/ml/typecore.ml:3852-3910 first types both
            // arguments, then intentionally re-types rhs, lhs, or both
            // depending on the chosen primitive specialization. This is
            // observable for generated identifiers in discarded `%raw`
            // expressions, so do not collapse it into direct unification.
            let (lhs, rhs, result_ty) = if let Some(type_name) =
                unified_specialized_type_name(ctx, lhs_type, entry.specialization)
            {
                let rhs = match type_expect(
                    tctx,
                    env,
                    rhs_expr,
                    unified_expected_type(env, ctx, type_name),
                    None,
                ) {
                    Ok(e) => e,
                    Err(e) => return Some(Err(e)),
                };
                (lhs, rhs, unified_expected_type(env, ctx, type_name))
            } else if let Some(type_name) =
                unified_specialized_type_name(ctx, rhs_type, entry.specialization)
            {
                let lhs = match type_expect(
                    tctx,
                    env,
                    lhs_expr,
                    unified_expected_type(env, ctx, type_name),
                    None,
                ) {
                    Ok(e) => e,
                    Err(e) => return Some(Err(e)),
                };
                (lhs, rhs, unified_expected_type(env, ctx, type_name))
            } else {
                let lhs = match type_expect(tctx, env, lhs_expr, env.type_int(ctx), None) {
                    Ok(e) => e,
                    Err(e) => return Some(Err(e)),
                };
                let rhs = match type_expect(tctx, env, rhs_expr, env.type_int(ctx), None) {
                    Ok(e) => e,
                    Err(e) => return Some(Err(e)),
                };
                (lhs, rhs, env.type_int(ctx))
            };

            // OCaml: rue { ... exp_type = ty_res; ... } (unified ops are Pexp_apply)
            if let Err(e) = finish_expected(tctx, sexp, result_ty, expected_ty, context) {
                return Some(Err(e));
            }

            let typed_args = vec![
                ApplyArg {
                    label: convert_arg_label_for_ctx(&args[0].0, tctx.arena, tctx.type_ctx),
                    expression: Some(tctx.push_expr(lhs)),
                },
                ApplyArg {
                    label: convert_arg_label_for_ctx(&args[1].0, tctx.arena, tctx.type_ctx),
                    expression: Some(tctx.push_expr(rhs)),
                },
            ];

            Some(Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_apply {
                        funct: tctx.push_expr(typed_funct.clone()),
                        args: tctx.typed.push_apply_args(typed_args),
                        partial: false,
                        transformed_jsx,
                    },
                    loc,
                    result_ty,
                    tctx.type_ctx.store_typed_env(env),
                );
                tctx.typed
                    .with_exp_attributes(typed_node, attributes.to_vec().into())
            }))
        }
        UnifiedOpForm::Unary if args.len() == 1 => {
            let arg_expr = tctx.arena.get_expanded_expr(args[0].1);
            let arg = match type_exp(tctx, env, arg_expr, None) {
                Ok(e) => e,
                Err(e) => return Some(Err(e)),
            };
            let arg_type = crate::types::ctype::expand_head(ctx, env, arg.exp_type);

            // OCaml compiler/ml/typecore.ml:3821-3846 types unary unified-op
            // arguments once, expands the head, and only falls back by unifying
            // that expanded type with int.
            let result_ty = if let Some(type_name) =
                unified_specialized_type_name(ctx, arg_type, entry.specialization)
            {
                unified_expected_type(env, ctx, type_name)
            } else {
                if let Err(e) =
                    unify_expression_types(tctx, arg.exp_loc, arg_type, env.type_int(ctx), None)
                {
                    return Some(Err(e));
                }
                env.type_int(ctx)
            };

            // OCaml: rue { ... exp_type = ty_res; ... } (unified ops are Pexp_apply)
            if let Err(e) = finish_expected(tctx, sexp, result_ty, expected_ty, context) {
                return Some(Err(e));
            }

            let typed_args = vec![ApplyArg {
                label: convert_arg_label_for_ctx(&args[0].0, tctx.arena, tctx.type_ctx),
                expression: Some(tctx.push_expr(arg)),
            }];

            Some(Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_apply {
                        funct: tctx.push_expr(typed_funct.clone()),
                        args: tctx.typed.push_apply_args(typed_args),
                        partial: false,
                        transformed_jsx,
                    },
                    loc,
                    result_ty,
                    tctx.type_ctx.store_typed_env(env),
                );
                tctx.typed
                    .with_exp_attributes(typed_node, attributes.to_vec().into())
            }))
        }
        _ => None, // Wrong number of args for the form
    }
}

/// Mirrors OCaml `should_unify_expected_result_before_typing_lowered_apply`.
/// True when the application is an async wrapper whose expected result type
/// should be threaded into the call before its arguments are typed.
fn should_unify_expected_result_before_typing_lowered_apply(
    typed_funct: &Expression,
    args: &[(ArgLabel, crate::parse_arena::ExprIdx)],
) -> bool {
    match &typed_funct.exp_desc {
        ExpressionDesc::Texp_ident(path, _, _) => {
            path.name_eq("Primitive_promise.unsafe_async")
                && args.len() == 1
                && matches!(args[0].0, ArgLabel::Nolabel)
        }
        _ => false,
    }
}

fn is_comparison_operator_name(name: &str) -> bool {
    matches!(name, "==" | "===" | "!=" | "!==" | ">" | ">=" | "<" | "<=")
}

fn math_operator_from_name(name: &str) -> Option<(bool, &'static str)> {
    match name {
        "/." => Some((true, "/.")),
        "*." => Some((true, "*.")),
        "+." => Some((true, "+.")),
        "-." => Some((true, "-.")),
        "/" => Some((false, "/")),
        "*" => Some((false, "*")),
        "+" => Some((false, "+")),
        "-" => Some((false, "-")),
        _ => None,
    }
}

fn strip_arity_suffix(name: &str) -> String {
    let start_of_digits = name
        .char_indices()
        .rev()
        .find(|(_, c)| !c.is_ascii_digit())
        .map(|(idx, c)| idx + c.len_utf8())
        .unwrap_or(0);
    if start_of_digits > 0 && start_of_digits < name.len() {
        name[..start_of_digits].to_string()
    } else {
        name.to_string()
    }
}

fn function_arity_for_suggestion(ctx: &TypeContext, ty: TypeExprRef) -> usize {
    match &*ctx.get_desc(ctx.repr(ty)) {
        TypeDesc::Tarrow { args, .. } => args.len(),
        _ => 0,
    }
}

fn format_arity_suggestion_path(path: &Path) -> String {
    let name = path.name();
    name.strip_prefix("Stdlib.")
        .or_else(|| name.strip_prefix("Stdlib_"))
        .unwrap_or(&name)
        .to_string()
}

fn lookup_qualified_value_for_arity_suggestion(
    env: &Env,
    prefix: &Longident,
    value_name: &str,
    arena: &ParseArena,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &TypeContext,
) -> Option<(Path, Arc<ValueDescription>)> {
    if let Some(Some(result)) =
        with_resolved_module_components_for_lid(prefix, arena, env, pers_env, ctx, |components| {
            let module_path = *components.access_path();
            if let Some(cached) = ctx.find_resolved_module_value(&module_path, value_name) {
                return Some(cached);
            }
            components
                .lookup_value_for_access(value_name, ctx)
                .map(|(pos, _, vd)| {
                    let path = Path::pdot_pos(module_path, value_name, pos as i32);
                    let result = (path, Arc::new(vd));
                    ctx.register_resolved_module_value(
                        &module_path,
                        value_name,
                        result.0,
                        result.1.clone(),
                    );
                    result
                })
        })
    {
        return Some(result);
    }

    let module_path = env.resolve_module_access_path_for_lid(prefix, arena, pers_env, ctx)?;
    if let Some(cached) = ctx.find_resolved_module_value(&module_path, value_name) {
        return Some(cached);
    }

    if let Some(Some((mod_path, pos, vd))) =
        with_resolved_module_components_for_path(&module_path, env, pers_env, ctx, |components| {
            components
                .lookup_value_for_access(value_name, ctx)
                .map(|(pos, _, vd)| (*components.access_path(), pos, vd))
        })
    {
        let path = Path::pdot_pos(mod_path, value_name, pos as i32);
        let result = (path, Arc::new(vd));
        ctx.register_resolved_module_value(
            &module_path,
            value_name,
            result.0,
            result.1.clone(),
        );
        return Some(result);
    }

    if let Some((mod_path, sig)) = env.resolve_module_lid_raw(prefix, arena, pers_env, ctx) {
        for sig_item in sig.iter().rev() {
            if let crate::types::decl::SignatureItem::SigValue(id, vd) = sig_item
                && id.name() == value_name
            {
                let mut vd = copy_lookup_value_description_for_subst(vd, ctx);
                crate::cmi::persistent_env::substitute_type_paths_in_value_from_sig(
                    &mut vd,
                    sig.as_ref(),
                    &mod_path,
                    ctx,
                );
                let result = (
                    Path::pdot_pos(mod_path, value_name, 0),
                    Arc::new(vd),
                );
                ctx.register_resolved_module_value(
                    &module_path,
                    value_name,
                    result.0,
                    result.1.clone(),
                );
                return Some(result);
            }
        }
    }

    None
}

fn lookup_value_for_arity_suggestion(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    original_lid: &Longident,
    candidate: &str,
) -> Option<(Path, Arc<ValueDescription>)> {
    match original_lid {
        Longident::Lident(_) => {
            let value_name = candidate
                .rsplit_once('.')
                .map_or(candidate, |(_, name)| name);
            env.find_value_with_id(value_name).ok().map(|(id, desc)| {
                let path = desc.val_path.unwrap_or_else(|| Path::pident(*id));
                (path, Arc::new(desc.clone()))
            })
        }
        Longident::Ldot(prefix, _) => {
            let (candidate_prefix, value_name) = candidate.rsplit_once('.')?;
            let original_prefix = tctx.longident_to_string(prefix);
            if candidate_prefix != original_prefix {
                return None;
            }
            lookup_qualified_value_for_arity_suggestion(
                env,
                prefix,
                value_name,
                tctx.arena,
                &mut tctx.persistent_env,
                tctx.type_ctx,
            )
        }
        Longident::Lapply(_, _) => None,
    }
}

fn find_arity_suggestion_for_function(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    function_lid: &Longident,
    target_arity: usize,
) -> Result<Option<String>, TypeCoreError> {
    let function_name = tctx.longident_to_string(function_lid);
    let base_name = strip_arity_suffix(&function_name);
    let candidate = if target_arity == 1 {
        base_name
    } else {
        format!("{base_name}{target_arity}")
    };
    let Some((path, desc)) = lookup_value_for_arity_suggestion(tctx, env, function_lid, &candidate)
    else {
        return Ok(None);
    };
    // typecore.ml:5175: `deprecated_of_attrs`, raising where
    // `string_of_opt_payload` raises.
    if deprecated_of_decl_attrs(&desc.val_attributes)
        .map_err(|loc| invalid_escape_at(tctx.type_ctx, loc))?
        .is_some()
    {
        return Ok(None);
    }
    let expanded_type = crate::types::ctype::expand_head(tctx.type_ctx, env, desc.val_type);
    Ok((function_arity_for_suggestion(tctx.type_ctx, expanded_type) == target_arity)
        .then(|| format_arity_suggestion_path(&path)))
}

fn find_arity_suggestion_for_expression(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    funct: &Expression,
    target_arity: usize,
) -> Result<Option<String>, TypeCoreError> {
    let ExpressionDesc::Texp_ident(_, lid, _) = &funct.exp_desc else {
        return Ok(None);
    };
    find_arity_suggestion_for_function(tctx, env, tctx.arena.get_longident(lid.txt), target_arity)
}

fn function_argument_type_clash_context(typed_funct_value_path: Option<&Path>) -> ClashSite {
    if let Some(path) = typed_funct_value_path {
        if is_comparison_operator_name(path.head_name()) {
            return ClashSite::ComparisonOperator;
        }

        if path.head_name() == "++" {
            return ClashSite::StringConcat;
        }

        if let Some((for_float, operator)) = math_operator_from_name(path.head_name()) {
            return ClashSite::MathOperator {
                for_float,
                operator,
                is_constant: None,
            };
        }

        if path.name_eq("Primitive_promise.unsafe_await") {
            return ClashSite::Await;
        }
    }

    ClashSite::FunctionCall
}

fn math_operator_constant_text(expr: &ParsedExpression) -> Option<StrIdx> {
    match &expr.pexp_desc {
        crate::parser::ast::ExpressionDesc::Pexp_constant(
            ParsedConstant::Integer(txt, _) | ParsedConstant::Float(txt, _),
        ) => Some(*txt),
        _ => None,
    }
}

fn type_clash_context_for_function_argument(
    context: ClashSite,
    label: &ArgLabel,
    arg_expr: &ParsedExpression,
) -> ClashSite {
    match context {
        ClashSite::MathOperator {
            for_float,
            operator,
            ..
        } => ClashSite::MathOperator {
            for_float,
            operator,
            is_constant: math_operator_constant_text(arg_expr),
        },
        ClashSite::FunctionCall => ClashSite::FunctionArgument {
            optional: false,
            name: match label {
                ArgLabel::Nolabel => None,
                ArgLabel::Labelled(loc) | ArgLabel::Optional(loc) => Some(loc.txt),
            },
        },
        _ => context,
    }
}

/// One-step `filter_arrow` analogue: walk through the function type's arrows
/// `arity` times, returning the first parameter type and the ultimate result
/// type. Returns None if the type does not have at least `arity` arrows.
fn filter_arrow_for_lowered_apply(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    funct_ty: TypeExprRef,
    arity: usize,
) -> Option<(TypeExprRef, TypeExprRef)> {
    let ctx = tctx.type_ctx;
    let expanded = crate::types::ctype::expand_head(ctx, env, funct_ty);
    let desc = ctx.get_desc(expanded);
    match &*desc {
        TypeDesc::Tarrow { args, ret } if args.len() == arity => {
            Some((ctx.type_args(args).first()?.typ, *ret))
        }
        _ => None,
    }
}

/// The existing application rule, supplied with the parsed operands.
/// Cost: the existing operand/list reads followed by application typing.
fn type_application(
    tctx: &mut TypeCheckContext<'_>, env: &Env, sexp: &ParsedExpression,
    apply: &PexpApply, expected_ty: &mut Expected, context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    let arena = tctx.arena;
    type_application_parts(tctx, env, sexp, sexp.pexp_loc, &sexp.pexp_attributes,
        ApplicationCallee::Source(arena.get_expanded_expr(apply.funct)),
        arena.apply_args(apply.args), apply.partial, apply.transformed_jsx, expected_ty, context)
}

/// Borrowed source callee or a compilation-local primitive handle. Never stored.
#[derive(Clone, Copy)]
enum ApplicationCallee<'a> {
    Source(&'a ParsedExpression),
    Promise(Located<LidentIdx>),
}

/// Apply the ordinary typing rule to borrowed operands.
/// Cost: the same callee check, argument checks and typed-node writes as an
/// explicit application; no parsed node, argument list or per-node state.
#[allow(clippy::too_many_arguments)]
fn type_application_parts(
    tctx: &mut TypeCheckContext<'_>, env: &Env, sexp: &ParsedExpression,
    loc: LocIdx, attributes: &[crate::parser::ast::Attribute],
    callee: ApplicationCallee<'_>, args: &[(ArgLabel, crate::parse_arena::ExprIdx)],
    partial: bool, transformed_jsx: bool, expected_ty: &mut Expected,
    context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    use crate::types::typedtree::ApplyArg;

    // compiler/frontend/ast_exp_apply.ml:47-50 validates all arguments to
    // special infix applications before rewriting them. Keep that boundary
    // ahead of function lookup so a malformed pipe reports the label itself,
    // rather than an unbound synthetic `->` value.
    if let ApplicationCallee::Source(funct) = callee
        && let crate::parser::ast::ExpressionDesc::Pexp_ident(lid) = &funct.pexp_desc
        && tctx.arena.is_lident(lid.txt, "->")
        && let Some((_, arg_idx)) = args
            .iter()
            .find(|(label, _)| !matches!(label, ArgLabel::Nolabel))
    {
        return Err(TypeCoreError::MisplacedLabelSyntax {
            loc: tctx.arena.get_expanded_expr(*arg_idx).pexp_loc,
        });
    }

    enum ApplyArgThunk<'a> {
        Provided {
            label: crate::types::ArgLabel,
            expr: &'a ParsedExpression,
            expected_ty: TypeExprRef,
            unify_ty: TypeExprRef,
            context: ClashSite,
            enforce_optional: bool,
            /// OCaml's type_unknown_args only calls type_expect, with no
            /// subsequent unify_exp. Skip the post-typing unify for this path.
            skip_post_unify: bool,
        },
        SynthOptionalNone {
            label: crate::types::ArgLabel,
            option_ty: TypeExprRef,
        },
        Omitted {
            label: crate::types::ArgLabel,
        },
    }

    #[derive(Clone, Copy)]
    /// An omitted parameter: OCaml keeps its `lbl` (typecore.ml:4191-4200).
    struct OmittedArrow {
        param: TypeArg,
    }

    fn parser_arg_label_name<'a>(label: &ArgLabel, arena: &'a ParseArena) -> &'a str {
        match label {
            ArgLabel::Nolabel => "",
            ArgLabel::Labelled(loc) | ArgLabel::Optional(loc) => arena.get_string(loc.txt),
        }
    }

    fn extract_label_index(
        args: &[(ArgLabel, crate::parse_arena::ExprIdx)],
        remaining_args: &[usize],
        label_name: &str,
        arena: &ParseArena,
    ) -> Option<usize> {
        remaining_args
            .iter()
            .position(|&idx| parser_arg_label_name(&args[idx].0, arena) == label_name)
    }

    fn has_nolabel_arg(
        args: &[(ArgLabel, crate::parse_arena::ExprIdx)],
        remaining_args: &[usize],
    ) -> bool {
        remaining_args
            .iter()
            .any(|&idx| matches!(args[idx].0, ArgLabel::Nolabel))
    }

    fn apply_arg_label_for_param(
        param_label: crate::types::type_expr::TypeArgLabel,
        call_label: &ArgLabel,
        arena: &ParseArena,
        ctx: &TypeContext,
    ) -> crate::types::ArgLabel {
        match param_label.to_kind() {
            crate::types::type_expr::ArgLabelKind::Nolabel => crate::types::ArgLabel::Nolabel,
            crate::types::type_expr::ArgLabelKind::Labelled => match call_label {
                ArgLabel::Nolabel => crate::types::ArgLabel::Nolabel,
                ArgLabel::Labelled(loc) | ArgLabel::Optional(loc) => {
                    crate::types::ArgLabel::labelled(
                        arena.get_string(loc.txt).to_string(),
                        ctx.intern_ast_loc(arena, loc.loc),
                    )
                }
            },
            crate::types::type_expr::ArgLabelKind::Optional => match call_label {
                ArgLabel::Nolabel => crate::types::ArgLabel::Nolabel,
                ArgLabel::Labelled(loc) | ArgLabel::Optional(loc) => {
                    crate::types::ArgLabel::optional(
                        arena.get_string(loc.txt).to_string(),
                        ctx.intern_ast_loc(arena, loc.loc),
                    )
                }
            },
        }
    }

    let ctx = tctx.type_ctx;
    let total_app = !partial;

    // Match OCaml Pexp_apply staging:
    //   begin_def (); type_exp funct; let ty = instance funct.exp_type; end_def ();
    //   lower_args env [] ty;
    //   begin_def (); ... type_application/translate_unified_ops ...; end_def ();
    ctx.begin_def();
    if ctx.compiler_counters_enabled() {
        // Retain the second variable: its check below may lower the function
        // type after end_def, and must preserve escape diagnostics.
        crate::perf_counters::record_expected_var(crate::perf_counters::ExpectedVar {
            construct: "application: lowering",
            case: 1,
        });
    }
    let inferred = Expected::Infer {
        level: ctx.current_level(), site: InferenceSite::ApplicationFunction,
    };
    let typed_funct = match callee {
        ApplicationCallee::Source(funct) => {
            tctx.deprecated_function_call = true;
            type_expect_full(tctx, env, funct, inferred, None, RecArg::Rejected, None)?
        }
        ApplicationCallee::Promise(lid) => {
            tctx.set_unify_env(env);
            type_identifier(tctx, env, sexp, lid.loc, &lid, &Attributes::new(), &mut { inferred },
                None, RecArg::Rejected, true)?
        }
    };
    let funct_loc = typed_funct.exp_loc;
    let typed_funct_value_path = match &typed_funct.exp_desc {
        ExpressionDesc::Texp_ident(path, _, _) => Some(*path),
        _ => None,
    };

    // Backport of upstream #8359:
    // Lowered syntax like `dict{...}` and async wrappers becomes a regular
    // application during parsing/PPX. Thread the expected result type into
    // the application before typing its arguments so element/value types
    // can be inferred from the surrounding context.
    if should_unify_expected_result_before_typing_lowered_apply(&typed_funct, args) {
        if let Some((_arg_ty, ty_res)) =
            filter_arrow_for_lowered_apply(tctx, env, typed_funct.exp_type, args.len())
        {
            let expected = materialize_expected(tctx, sexp, expected_ty);
            let expected_inst = crate::types::instance(ctx, expected);
            unify_expression_types(tctx, loc, ty_res, expected_inst, None)?;
        }
    }
    let function_arg_context = if transformed_jsx {
        ClashSite::JsxComponent
    } else {
        function_argument_type_clash_context(typed_funct_value_path.as_ref())
    };

    let lowered_ty = crate::types::instance(ctx, typed_funct.exp_type);
    ctx.end_def();
    // OCaml compiler/ml/typecore.ml:2579-2582 instances the function type and
    // immediately runs `lower_args` (typecore.ml:2335-2342).
    crate::types::ctype::lower_args(ctx, env, lowered_ty);

    ctx.begin_def();

    // Try unified ops dispatch first (matching OCaml's translate_unified_ops)
    if let Some(result) = translate_unified_ops(
        tctx,
        env,
        sexp,
        loc,
        attributes,
        args,
        transformed_jsx,
        &typed_funct,
        expected_ty,
        context,
    ) {
        ctx.end_def();
        return result;
    }

    // compiler/ml/typecore.ml:4049-4069: a total call of an unknown
    // function commits it to one n-ary arrow matching the complete call site.
    let uncommitted_funct_ty = crate::types::ctype::expand_head(ctx, env, typed_funct.exp_type);
    if total_app && matches!(&*ctx.borrow_desc(uncommitted_funct_ty), TypeDesc::Tvar(..)) {
        let params = ctx.new_type_args_from(args
            .iter()
            .map(|(label, _)| {
                crate::types::TypeArg::new(
                    convert_arg_label_for_ctx(label, tctx.arena, tctx.type_ctx),
                    ctx.new_var(None),
                )
            }));
        let ret = ctx.new_var(None);
        let is_identity = matches!(
            &typed_funct.exp_desc,
            ExpressionDesc::Texp_ident(_, _, desc)
                if matches!(&desc.val_kind, crate::types::ValueKind::ValPrim(prim) if prim.prim_name == "%identity")
        );
        if ctx.get_level(uncommitted_funct_ty) >= ctx.get_level(ret) && !is_identity {
            for (_, arg) in args {
                tctx.report_warning(tctx.arena.get_expanded_expr(*arg).pexp_loc, Warning::UnusedArgument);
            }
        }
        let arrow = ctx.new_type(TypeDesc::Tarrow { args: params, ret });
        unify_expression_types(tctx, loc, uncommitted_funct_ty, arrow, None)?;
    }

    // compiler/ml/typecore.ml:4087-4190 scans the declared n-ary parameter
    // list directly. Labeled source arguments commute, while typed argument
    // thunks are retained and forced in declaration order.
    let expanded_funct_ty = crate::types::ctype::expand_head(ctx, env, typed_funct.exp_type);
    let function_level = ctx.get_level(ctx.repr(expanded_funct_ty));
    let (declared_params, declared_ret) = match &*ctx.borrow_desc(expanded_funct_ty) {
        TypeDesc::Tarrow { args, ret } => (*args, *ret),
        TypeDesc::Tvar(..) => {
            return Err(TypeCoreError::ApplyNonFunction {
                loc: typed_funct.exp_loc,
                typ: expanded_funct_ty,
            });
        }
        _ => {
            return Err(TypeCoreError::ApplyNonFunction {
                loc: typed_funct.exp_loc,
                typ: expanded_funct_ty,
            });
        }
    };
    let expanded_inst_ty = crate::types::ctype::expand_head(
        ctx,
        env,
        crate::types::instance(ctx, typed_funct.exp_type),
    );
    let (inst_params, inst_ret) = match &*ctx.borrow_desc(expanded_inst_ty) {
        TypeDesc::Tarrow { args, ret } if args.len() == declared_params.len() => {
            (*args, *ret)
        }
        _ => unreachable!("instancing a declared n-ary arrow preserves its shape"),
    };
    let function_arity = declared_params.len();
    if total_app && args.len() > function_arity {
        let arity_suggestion =
            find_arity_suggestion_for_expression(tctx, env, &typed_funct, args.len())?;
        return Err(TypeCoreError::UncurriedArityMismatch {
            loc: funct_loc,
            function_type: typed_funct.exp_type,
            expected_arity: function_arity,
            provided_arity: args.len(),
            provided_args: args.iter().map(|(label, _)| *label).collect(),
            function_name: None,
            arity_suggestion,
        });
    }

    let is_ignore_fn = matches!(
        &typed_funct.exp_desc,
        ExpressionDesc::Texp_ident(_, _, desc)
            if matches!(&desc.val_kind, crate::types::ValueKind::ValPrim(prim) if prim.prim_name == "%ignore")
    );
    let mut remaining_args: smallvec::SmallVec<[usize; 8]> = (0..args.len()).collect();
    let mut argument_thunks: smallvec::SmallVec<[ApplyArgThunk<'_>; 6]> = smallvec::SmallVec::new();
    let mut omitted: smallvec::SmallVec<[OmittedArrow; 2]> = smallvec::SmallVec::new();
    let mut ignored: smallvec::SmallVec<[OmittedArrow; 2]> = smallvec::SmallVec::new();

    for (param, inst_param) in ctx
        .type_args(declared_params)
        .iter()
        .zip(ctx.type_args(inst_params).iter())
    {
        let label_name = param.label().label_name().unwrap_or("");
        if let Some(match_index) =
            extract_label_index(args, &remaining_args, label_name, tctx.arena)
        {
            let arg_index = remaining_args.remove(match_index);
            let (call_label, arg_expr_idx) = &args[arg_index];
            let arg_expr = tctx.arena.get_expanded_expr(*arg_expr_idx);
            let call_is_optional = call_label.is_optional();
            if !param.label().is_optional() && call_is_optional {
                tctx.report_warning(
                    arg_expr.pexp_loc,
                    Warning::NonoptionalLabel {
                        name: label_name.to_string(),
                    },
                );
            }
            let expected_arg_ty = if param.label().is_optional() && !call_is_optional {
                crate::types::ctype::extract_option_type(ctx, param.typ).unwrap_or(param.typ)
            } else {
                param.typ
            };
            let unify_arg_ty = if param.label().is_optional() && !call_is_optional {
                crate::types::ctype::extract_option_type(ctx, inst_param.typ)
                    .unwrap_or(inst_param.typ)
            } else {
                inst_param.typ
            };
            let arg_context = if matches!(function_arg_context, ClashSite::JsxComponent) {
                if argument_thunks.is_empty() {
                    ClashSite::JsxComponent
                } else {
                    type_clash_context_for_function_argument(
                        ClashSite::FunctionCall,
                        call_label,
                        arg_expr,
                    )
                }
            } else if param.label().is_optional()
                && !call_is_optional
                && matches!(function_arg_context, ClashSite::FunctionCall)
            {
                ClashSite::FunctionArgument {
                    optional: true,
                    name: match call_label {
                        ArgLabel::Nolabel => None,
                        ArgLabel::Labelled(loc) | ArgLabel::Optional(loc) => Some(loc.txt),
                    },
                }
            } else {
                type_clash_context_for_function_argument(
                    function_arg_context,
                    call_label,
                    arg_expr,
                )
            };
            argument_thunks.push(ApplyArgThunk::Provided {
                label: apply_arg_label_for_param(
                    param.label(),
                    call_label,
                    tctx.arena,
                    tctx.type_ctx,
                ),
                expr: arg_expr,
                expected_ty: expected_arg_ty,
                unify_ty: unify_arg_ty,
                context: arg_context,
                enforce_optional: param.label().is_optional() && !call_is_optional,
                skip_post_unify: is_ignore_fn,
            });
        } else if param.label().is_optional()
            && (total_app || has_nolabel_arg(args, &remaining_args))
        {
            ignored.push(OmittedArrow { param });
            argument_thunks.push(ApplyArgThunk::SynthOptionalNone {
                label: param.label().to_arg_label(),
                option_ty: crate::types::instance(ctx, param.typ),
            });
        } else {
            omitted.push(OmittedArrow { param });
            if !remaining_args.is_empty() {
                argument_thunks.push(ApplyArgThunk::Omitted {
                    label: param.label().to_arg_label(),
                });
            }
        }
    }

    if !remaining_args.is_empty() {
        let all_ignored_optional = total_app
            && omitted.is_empty()
            && !argument_thunks.is_empty()
            && argument_thunks.len() == ignored.len();
        let unit_sentinel = remaining_args.len() == 1
            && matches!(args[remaining_args[0]].0, ArgLabel::Nolabel)
            && matches!(
                &tctx.arena.get_expanded_expr(args[remaining_args[0]].1).pexp_desc,
                crate::parser::ast::ExpressionDesc::Pexp_construct(lid, args)
                    if tctx.arena.is_lident(lid.txt, "()") && args.txt.is_empty()
            );
        if !(all_ignored_optional && unit_sentinel) {
            let (label, arg_idx) = &args[remaining_args[0]];
            let arg_expr = tctx.arena.get_expanded_expr(*arg_idx);
            let result_ty = if omitted.is_empty() && ignored.is_empty() {
                declared_ret
            } else {
                let params =
                    ctx.new_type_args_from(omitted.iter().chain(&ignored).map(|arg| arg.param));
                ctx.alloc_type_at_level(
                    TypeDesc::Tarrow {
                        args: params,
                        ret: declared_ret,
                    },
                    function_level,
                )
            };
            if matches!(
                &*ctx.borrow_desc(ctx.repr(result_ty)),
                TypeDesc::Tarrow { .. }
            ) {
                return Err(TypeCoreError::ApplyWrongLabel {
                    loc: arg_expr.pexp_loc,
                    label: *label,
                    ty: if argument_thunks.len() >= function_arity {
                        typed_funct.exp_type
                    } else {
                        result_ty
                    },
                });
            }
            return Err(TypeCoreError::ApplyNonFunction {
                loc: typed_funct.exp_loc,
                typ: expanded_funct_ty,
            });
        }
    }

    let provided = ignored.len() + args.len();
    let fully_applied = provided >= function_arity;
    let current_ty0 = inst_ret;
    let mut typed_args: smallvec::SmallVec<[ApplyArg; 6]> = smallvec::SmallVec::new();
    for pending_arg in argument_thunks.into_iter() {
        match pending_arg {
            ApplyArgThunk::Provided {
                label,
                expr,
                expected_ty,
                unify_ty,
                context,
                enforce_optional,
                skip_post_unify,
            } => {
                let arg_expected_ty = expected_ty;
                let saved_unify_env = tctx
                    .unify_state
                    .env()
                    .filter(|saved_env| saved_env.id() != env.id())
                    .cloned();
                let typed_arg_result =
                    type_expect(tctx, env, expr, arg_expected_ty, Some(context));

                let typed_arg = typed_arg_result?;
                if let Some(saved_env) = saved_unify_env {
                    tctx.unify_state.set_env(&saved_env);
                } else {
                    tctx.set_unify_env(env);
                }
                // OCaml's type_unknown_args only calls type_expect (no
                // subsequent unify_exp). Skip the post-unify for that path
                // to preserve separate physical nodes in the typed tree.
                if !skip_post_unify {
                    // OCaml compiler/ml/typecore.ml:3771-3773 `type_argument`
                    // runs this second unification for selected arguments too;
                    // alias handling belongs in Ctype/Env, not a typecore-side
                    // selected-value guard.
                    unify_expression_types(
                        tctx,
                        typed_arg.exp_loc,
                        typed_arg.exp_type,
                        unify_ty,
                        Some(context),
                    )?;
                }
                let typed_arg = if enforce_optional {
                    let wrapped_loc = typed_arg.exp_loc;
                    let wrapped_env = typed_arg.exp_env;
                    let option_ty = env.type_option(ctx, typed_arg.exp_type);
                    Expression::new(
                        // typecore.ml:298-302 `option_some`: `mknoloc (Lident "Some")`.
                        ExpressionDesc::Texp_construct(
                            Located {
                                txt: tctx.arena.plain_some_lid(),
                                loc: tctx.arena.none_loc(),
                            },
                            std::sync::Arc::new(make_some_constructor(ctx)),
                            tctx.typed.push_exprs(vec![typed_arg]),
                        ),
                        wrapped_loc,
                        option_ty,
                        wrapped_env,
                    )
                } else {
                    typed_arg
                };
                typed_args.push(ApplyArg {
                    label,
                    expression: Some(tctx.push_expr(typed_arg)),
                });
            }
            ApplyArgThunk::SynthOptionalNone { label, option_ty } => {
                let none_loc = tctx.arena.none_loc();
                let none_expr = Expression::new(
                    ExpressionDesc::Texp_construct(
                        Located {
                            txt: tctx.arena.none_lid(),
                            loc: none_loc,
                        },
                        std::sync::Arc::new(make_none_constructor(ctx)),
                        TExprList::EMPTY,
                    ),
                    none_loc,
                    option_ty,
                    tctx.type_ctx.store_typed_env(env),
                );
                typed_args.push(ApplyArg {
                    label,
                    expression: Some(tctx.push_expr(none_expr)),
                });
            }
            ApplyArgThunk::Omitted { label } => {
                typed_args.push(ApplyArg {
                    label,
                    expression: None,
                });
            }
        }
    }

    // compiler/ml/typecore.ml:4179-4190 forces argument thunks before reporting
    // a total application's missing arguments. Besides preserving diagnostic
    // precedence, this lets argument typing refine the function type printed in
    // the arity error.
    if total_app && !fully_applied {
        let arity_suggestion =
            find_arity_suggestion_for_expression(tctx, env, &typed_funct, args.len())?;
        return Err(TypeCoreError::UncurriedArityMismatch {
            loc: funct_loc,
            function_type: typed_funct.exp_type,
            expected_arity: args.len() + function_arity - provided,
            provided_arity: args.len(),
            provided_args: args.iter().map(|(label, _)| *label).collect(),
            function_name: None,
            arity_suggestion,
        });
    }

    // compiler/ml/typecore.ml:4191-4200: a partial application returns one
    // n-ary arrow containing exactly the omitted parameters, in declaration order.
    let result_ty = if fully_applied && omitted.is_empty() {
        current_ty0
    } else {
        ctx.alloc_type_at_level(
            TypeDesc::Tarrow {
                args: ctx.new_type_args_from(omitted.iter().map(|arg| arg.param)),
                ret: current_ty0,
            },
            function_level,
        )
    };

    // Match OCaml typecore.ml Pexp_apply post-application side effect:
    //   unify_var env (newvar ()) funct.exp_type
    // Keep this before unifying the application result with expected_ty.
    ctx.end_def();
    if transformed_jsx {
        check_jsx_props(tctx, env, loc, &typed_args)?;
    }
    unify_expression_types(tctx, loc, ctx.new_var(None), typed_funct.exp_type, None)?;

    // OCaml: rue { ... exp_type = ty_res; ... }
    finish_expected_at(tctx, sexp, loc, result_ty, expected_ty, context)?;

    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_apply {
                funct: tctx.push_expr(typed_funct),
                args: tctx.typed.push_apply_args(typed_args),
                partial,
                transformed_jsx,
            },
            loc,
            result_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        if attributes.is_empty() {
            typed_node
        } else {
            tctx.typed
                .with_exp_attributes(typed_node, attributes.to_vec().into())
        }
    })
}

/// typecore.ml `check_jsx_props`: the props of a JSX element, the second
/// argument of the call the JSX PPX produces, must be an object. An
/// `@unboxed` record is the value of its field.
fn check_jsx_props(
    tctx: &TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    args: &[crate::types::typedtree::ApplyArg],
) -> Result<(), TypeCoreError> {
    if let [_, props_arg, ..] = args
        && matches!(props_arg.label, crate::types::asttypes::ArgLabel::Nolabel)
        && let Some(props) = &props_arg.expression
        && let Some((_, _, decl)) =
            crate::types::ctype::extract_concrete_typedecl(tctx.type_ctx, env, tctx.typed.expr(*props).exp_type)
        && matches!(
            decl.type_kind,
            crate::types::TypeKind::TypeRecord(
                _,
                crate::types::RecordRepresentation::RecordUnboxed(_)
            )
        )
    {
        return Err(TypeCoreError::JsxUnboxedProps {
            loc,
            typ: tctx.typed.expr(*props).exp_type,
        });
    }
    Ok(())
}

fn extendable_fragile_match_path(path: &Path) -> bool {
    // OCaml Parmatch.extendable_path excludes these predef types before
    // emitting Warnings.Fragile_match.
    !(path.same(&crate::types::predef::path_bool())
        || path.same(&crate::types::predef::path_list())
        || path.same(&crate::types::predef::path_unit())
        || path.same(&crate::types::predef::path_option()))
}

/// The end of `type_cases` for exception cases and `try` handlers, which
/// OCaml types with `partial_flag = false` (typecore.ml:2681-2685): no
/// exhaustiveness check, but the `init_env` stamps, the result unification
/// and the unused-case check still run.
fn finish_non_gadt_type_cases(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    ty_res: TypeExprRef,
    ty_arg: TypeExprRef,
    parsed_cases: &[&crate::parser::ast::Case],
    typed_cases: &[crate::types::typedtree::Case],
) -> TypeCoreResult<()> {
    let ctx = tctx.type_ctx;
    let needs_exhaust_check = !matches!(
        parsed_cases,
        [case] if is_simple_variable_pattern(tctx.arena, tctx.arena.get_pat(case.pc_lhs))
    );
    let mut unused_check_level = ctx.current_level();
    let mut unused_expected_ty = ty_arg;
    if needs_exhaust_check {
        // OCaml compiler/ml/typecore.ml:4511-4535 runs init_env after
        // type_cases body typing, even when partial_flag is false (for try
        // handlers from typecore.ml:2681-2685). Ident.set_current_time reserves
        // stamps before later binders are named.
        ctx.begin_def();
        ctx.set_current_time(ctx.current_level());
        let lev = ctx.current_stamp();
        ctx.init_def(lev + 1000);
        unused_check_level = lev;
        unused_expected_ty = crate::types::ctype::subst_for_saving_copy(ctx, ty_arg);
        ctx.end_def();
        unify_expression_types(
            tctx,
            loc,
            crate::types::instance(ctx, ty_res),
            ctx.new_var(None),
            None,
        )?;
    }

    // type_cases always schedules check_unused, including try handlers where
    // partial_flag is false (typecore.ml:4483-4496).
    let contains_polyvars = parsed_cases.iter().any(|case| {
        parsed_pattern_contains_polymorphic_variant(tctx.arena, tctx.arena.get_pat(case.pc_lhs))
    });
    report_unused_match_cases(
        tctx,
        env,
        typed_cases,
        needs_exhaust_check || contains_polyvars,
        unused_check_level,
        unused_expected_ty,
        true,
    );
    Ok(())
}

fn pattern_from_variant_spread_attr(arena: &ParseArena, attrs: &Attributes) -> bool {
    attrs
        .iter()
        .any(|attr| arena.get_string(attr.0.txt) == PAT_FROM_VARIANT_SPREAD_ATTRIBUTE)
}

/// `Parmatch.ppat_of_type env ty` (parmatch.ml:2034-2038); `None` stands
/// for the `Ppat_any` case.
fn materialize_pattern_of_type(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    expected_ty: TypeExprRef,
    _loc: LocIdx,
) -> Option<crate::parse_arena::PatIdx> {
    // The exported pattern's sub-patterns go to a scratch arena (see
    // [`PatCase`]).
    // `Parmatch.ppat_of_type !env expected_ty` (typecore.ml:1278).
    let pat_env = pattern_env_ref(tctx, env);
    let ta = std::mem::take(&mut tctx.typed);
    let oracle = TypecoreParmatchOracle {
        tctx: &mut *tctx,
        env,
        expected_ty,
        level: 0,
        partial_explode: 0,
        none_type: None,
    };
    let mut pm = crate::types::parmatch::Parmatch::new(oracle, &ta);
    let pats = pm.pats_of_type(false, pat_env, expected_ty);
    let result = if let [p] = pats.as_slice()
        && pm.is_any(*p)
    {
        None
    } else {
        let orified = pm.orify_many(&pats);
        let typed = pm.export(orified);
        drop(pm);
        Some(conv_counter_example(tctx, &typed, None))
    };
    tctx.typed = ta;
    result
}

fn report_unused_match_cases(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    cases: &[crate::types::typedtree::Case],
    delayed: bool,
    level: i32,
    ty_arg_check: TypeExprRef,
    check_ambiguous: bool,
) {
    // `unused_check ()` (typecore.ml:4483-4490): delayed when the match
    // contains polymorphic variants or needed `init_env`.
    let check_ambiguous = check_ambiguous
        && tctx
            .warning_config
            .is_active(&Warning::AmbiguousPattern { vars: Vec::new() });
    if !unused_check_is_active(tctx) && !check_ambiguous {
        return;
    }
    if let [case] = cases
        && unused_check_is_trivial(tctx.type_ctx, &tctx.typed, tctx.typed.pattern(case.c_lhs), case.c_guard.is_some())
    {
        return;
    }
    let check_cases: Vec<UnusedCheckCase> = cases
        .iter()
        .map(|case| UnusedCheckCase {
            lhs: case.c_lhs,
            guarded: case.c_guard.is_some(),
            guard_idents: case.c_guard.as_ref().map(|guard| {
                let mut ids = Vec::new();
                collect_expression_ident_heads(&tctx.typed, *guard, &mut ids);
                ids.into_iter().collect()
            }),
        })
        .collect();
    register_unused_match_check(
        tctx,
        env,
        check_cases,
        delayed,
        level,
        ty_arg_check,
        check_ambiguous,
    );
}

/// [`report_unused_match_cases`] for a single unguarded pattern, such as a
/// function parameter, without building a `Case` around it.
fn report_unused_match_pattern(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    lhs: TPatIdx,
    delayed: bool,
    level: i32,
    ty_arg_check: TypeExprRef,
) {
    if !unused_check_is_active(tctx) || unused_check_is_trivial(tctx.type_ctx, &tctx.typed, tctx.typed.pattern(lhs), false) {
        return;
    }
    let case = UnusedCheckCase {
        lhs,
        guarded: false,
        guard_idents: None,
    };
    register_unused_match_check(tctx, env, vec![case], delayed, level, ty_arg_check, false);
}

/// `check_unused` of one unguarded case without or-patterns: with no
/// earlier rows `every_satisfiables` answers `Used`, the refinement is
/// skipped (`pref = []`) and `check_ambiguous_bindings` only looks at
/// guarded or-patterns, so nothing can be reported.
fn unused_check_is_trivial(ctx: &TypeContext, ta: &TypedArena, lhs: &Pattern, guarded: bool) -> bool {
    // A shadowed payload is reported even in a single case without
    // or-patterns (parmatch.ml `check_shadowed_payloads`).
    !guarded
        && !pattern_contains_or(ta, lhs)
        && !crate::types::parmatch::has_shadowed_payloads(ctx, ta, lhs)
}

/// parmatch.ml `check_unused` runs when warning 11 or 12 is active: the
/// shadowed-payload check reports through either.
fn unused_check_is_active(tctx: &TypeCheckContext<'_>) -> bool {
    tctx.warning_config.is_active(&Warning::UnusedMatch {
        reason: String::new(),
    }) || tctx.warning_config.is_active(&Warning::UnusedPat {
        reason: String::new(),
    })
}

/// A borrowed match case for the unused/ambiguous Parmatch checks.
struct UnusedCheckCase {
    lhs: TPatIdx,
    guarded: bool,
    /// `all_rhs_idents` of the guard.
    guard_idents: Option<std::collections::BTreeSet<Ident>>,
}

fn register_unused_match_check(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    cases: Vec<UnusedCheckCase>,
    delayed: bool,
    level: i32,
    ty_arg_check: TypeExprRef,
    check_ambiguous: bool,
) {
    let warning_config = tctx.warning_config.clone();
    if delayed {
        let seq = tctx.next_delayed_check_seq();
        tctx.delayed_unused_checks.push(DelayedUnusedCheck {
            env: env.clone(),
            level,
            ty_arg_check,
            cases: cases
                .into_iter()
                .map(|case| ParmatchCase {
                    lhs: case.lhs,
                    guarded: case.guarded,
                    guard_idents: case.guard_idents,
                })
                .collect(),
            warning_config,
            check_ambiguous,
            seq,
        });
    } else {
        run_unused_check(
            tctx,
            env,
            level,
            ty_arg_check,
            cases,
            warning_config,
            check_ambiguous,
        );
    }
}

fn run_delayed_unused_check(tctx: &mut TypeCheckContext<'_>, check: DelayedUnusedCheck) {
    let cases = check
        .cases
        .iter()
        .map(|case| UnusedCheckCase {
            lhs: case.lhs,
            guarded: case.guarded,
            guard_idents: if check.check_ambiguous {
                case.guard_idents.clone()
            } else {
                None
            },
        })
        .collect();
    run_unused_check(
        tctx,
        &check.env,
        check.level,
        check.ty_arg_check,
        cases,
        check.warning_config,
        check.check_ambiguous,
    );
}

fn run_unused_check(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    level: i32,
    ty_arg_check: TypeExprRef,
    cases: Vec<UnusedCheckCase>,
    warning_config: WarningConfig,
    check_ambiguous: bool,
) {
    tctx.drain_open_slot_uses();
    let saved = std::mem::replace(&mut tctx.warning_config, warning_config);
    let expected_ty = crate::types::instance(tctx.type_ctx, ty_arg_check);
    // The checker retypes counter-examples through `tctx` while it reads the
    // case patterns; see [`PatCase`].
    let mut ta = std::mem::take(&mut tctx.typed);
    let refs: Vec<_> = cases.iter().map(|case| PatCase { lhs: case.lhs, guarded: case.guarded }).collect();
    parmatch_check_unused(tctx, &mut ta, env, level, expected_ty, &refs);
    if check_ambiguous {
        // Parmatch.check_ambiguous_bindings (typecore.ml:4486), which lowers
        // the dict patterns of the cases.
        let pats: Vec<&Pattern> = cases.iter().map(|case| ta.pattern(case.lhs)).collect();
        let lowering = crate::types::dict_pattern::Lowering::new(tctx.type_ctx, &ta, &pats);
        let lowered: Vec<_> = cases.iter().map(|case| lowering.lower(&mut ta, case.lhs)).collect();
        let oracle = TypecoreParmatchOracle {
            tctx: &mut *tctx,
            env,
            expected_ty,
            level,
            partial_explode: 0,
            none_type: None,
        };
        let mut pm = crate::types::parmatch::Parmatch::new(oracle, &ta);
        let cases: Vec<_> = cases
            .into_iter()
            .zip(&lowered)
            .map(|(case, lhs)| crate::types::parmatch::AmbiguousCase {
                lhs: ta.pattern(*lhs),
                guard_idents: case.guard_idents,
            })
            .collect();
        pm.check_ambiguous_bindings(&cases);
    }
    tctx.typed = ta;
    tctx.drain_open_slot_uses();
    tctx.warning_config = saved;
}

fn collect_expression_ident_heads(ta: &TypedArena, exp: TExprIdx, ids: &mut Vec<Ident>) {
    match &ta.expr(exp).exp_desc {
        ExpressionDesc::Texp_ident(path, _, _) => {
            ids.extend(path.heads().into_iter().cloned());
        }
        ExpressionDesc::Texp_let(_, bindings, body) => {
            for binding in ta.value_bindings(*bindings) {
                collect_expression_ident_heads(ta, binding.vb_expr, ids);
            }
            collect_expression_ident_heads(ta, *body, ids);
        }
        ExpressionDesc::Texp_function { body, .. } => {
            collect_expression_ident_heads(ta, *body, ids);
        }
        ExpressionDesc::Texp_apply { funct, args, .. } => {
            collect_expression_ident_heads(ta, *funct, ids);
            for arg in ta.apply_args(*args) {
                if let Some(expr) = arg.expression {
                    collect_expression_ident_heads(ta, expr, ids);
                }
            }
        }
        ExpressionDesc::Texp_tagged_template { tag, values, .. } => {
            collect_expression_ident_heads(ta, *tag, ids);
            for value in ta.expr_list(*values) {
                collect_expression_ident_heads(ta, *value, ids);
            }
        }
        ExpressionDesc::Texp_template { values, .. } => {
            for value in ta.expr_list(*values) {
                collect_expression_ident_heads(ta, *value, ids);
            }
        }
        ExpressionDesc::Texp_match(scrutinee, cases, exn_cases, _) => {
            collect_expression_ident_heads(ta, *scrutinee, ids);
            collect_case_expression_ident_heads(ta, ta.cases(*cases), ids);
            collect_case_expression_ident_heads(ta, ta.cases(*exn_cases), ids);
        }
        ExpressionDesc::Texp_try(scrutinee, cases, finally) => {
            collect_expression_ident_heads(ta, *scrutinee, ids);
            collect_case_expression_ident_heads(ta, ta.cases(*cases), ids);
            if let Some(finally) = finally {
                collect_expression_ident_heads(ta, *finally, ids);
            }
        }
        ExpressionDesc::Texp_tuple(items)
        | ExpressionDesc::Texp_array(items)
        | ExpressionDesc::Texp_spread(_, items) => {
            for item in ta.expr_list(*items) {
                collect_expression_ident_heads(ta, *item, ids);
            }
        }
        ExpressionDesc::Texp_dict(entries) => {
            for entry in ta.dict_entries(*entries) {
                match entry {
                    TypedDictEntry::Tdict_entry(_, e) | TypedDictEntry::Tdict_spread(e) => {
                        collect_expression_ident_heads(ta, *e, ids)
                    }
                }
            }
        }
        ExpressionDesc::Texp_construct(_, _, args) => {
            for arg in ta.expr_list(*args) {
                collect_expression_ident_heads(ta, *arg, ids);
            }
        }
        ExpressionDesc::Texp_variant(_, Some(arg)) => {
            collect_expression_ident_heads(ta, *arg, ids);
        }
        ExpressionDesc::Texp_record {
            fields,
            extended_expression,
            ..
        } => {
            for (_, _, expr) in ta.record_fields(*fields) {
                collect_expression_ident_heads(ta, *expr, ids);
            }
            if let Some(expr) = extended_expression {
                collect_expression_ident_heads(ta, *expr, ids);
            }
        }
        ExpressionDesc::Texp_field(expr, _, _) | ExpressionDesc::Texp_assert(expr) => {
            collect_expression_ident_heads(ta, *expr, ids);
        }
        ExpressionDesc::Texp_setfield(expr1, _, _, expr2)
        | ExpressionDesc::Texp_sequence(expr1, expr2)
        | ExpressionDesc::Texp_while(expr1, expr2)
        | ExpressionDesc::Texp_for_of(_, _, expr1, expr2)
        | ExpressionDesc::Texp_for_await_of(_, _, expr1, expr2) => {
            collect_expression_ident_heads(ta, *expr1, ids);
            collect_expression_ident_heads(ta, *expr2, ids);
        }
        ExpressionDesc::Texp_ifthenelse(cond, then_, else_) => {
            collect_expression_ident_heads(ta, *cond, ids);
            collect_expression_ident_heads(ta, *then_, ids);
            if let Some(else_) = else_ {
                collect_expression_ident_heads(ta, *else_, ids);
            }
        }
        ExpressionDesc::Texp_for(_, _, start, stop, _, body) => {
            collect_expression_ident_heads(ta, *start, ids);
            collect_expression_ident_heads(ta, *stop, ids);
            collect_expression_ident_heads(ta, *body, ids);
        }
        ExpressionDesc::Texp_object_get(receiver, _) => {
            collect_expression_ident_heads(ta, *receiver, ids);
        }
        ExpressionDesc::Texp_object_set(receiver, _, value) => {
            collect_expression_ident_heads(ta, *receiver, ids);
            collect_expression_ident_heads(ta, *value, ids);
        }
        ExpressionDesc::Texp_object_literal(fields) => {
            for (_, field) in fields {
                collect_expression_ident_heads(ta, *field, ids);
            }
        }
        ExpressionDesc::Texp_letmodule(_, _, module_expr, body) => {
            collect_module_expr_ident_heads(ta, ta.module_expr(*module_expr), ids);
            collect_expression_ident_heads(ta, *body, ids);
        }
        ExpressionDesc::Texp_letexception(_, body) => {
            collect_expression_ident_heads(ta, *body, ids);
        }
        ExpressionDesc::Texp_pack(module_expr) => {
            collect_module_expr_ident_heads(ta, ta.module_expr(*module_expr), ids);
        }
        ExpressionDesc::Texp_constant(_)
        | ExpressionDesc::Texp_variant(_, None)
        | ExpressionDesc::Texp_break
        | ExpressionDesc::Texp_continue => {}
    }
}

fn collect_case_expression_ident_heads(
    ta: &TypedArena,
    cases: &[crate::types::typedtree::Case],
    ids: &mut Vec<Ident>,
) {
    for case in cases {
        if let Some(guard) = case.c_guard {
            collect_expression_ident_heads(ta, guard, ids);
        }
        collect_expression_ident_heads(ta, case.c_rhs, ids);
    }
}

fn collect_module_expr_ident_heads(
    ta: &TypedArena,
    module_expr: &ModuleExpr,
    ids: &mut Vec<Ident>,
) {
    match &module_expr.mod_desc {
        ModuleExprDesc::Tmod_ident(_, _) => {}
        ModuleExprDesc::Tmod_structure(structure) => {
            for item in ta.structure_items(structure.str_items) {
                match &item.str_desc {
                    StructureItemDesc::Tstr_eval(expr, _) => {
                        collect_expression_ident_heads(ta, *expr, ids);
                    }
                    StructureItemDesc::Tstr_value(_, bindings) => {
                        for binding in ta.value_bindings(*bindings) {
                            collect_expression_ident_heads(ta, binding.vb_expr, ids);
                        }
                    }
                    StructureItemDesc::Tstr_module(binding) => {
                        collect_module_expr_ident_heads(ta, ta.module_expr(binding.mb_expr), ids);
                    }
                    StructureItemDesc::Tstr_recmodule(bindings) => {
                        for binding in bindings {
                            collect_module_expr_ident_heads(
                                ta,
                                ta.module_expr(binding.mb_expr),
                                ids,
                            );
                        }
                    }
                    StructureItemDesc::Tstr_include(include) => {
                        collect_module_expr_ident_heads(ta, ta.module_expr(include.incl_mod), ids);
                    }
                    StructureItemDesc::Tstr_primitive(_)
                    | StructureItemDesc::Tstr_type(_, _)
                    | StructureItemDesc::Tstr_typext(_)
                    | StructureItemDesc::Tstr_exception(_)
                    | StructureItemDesc::Tstr_modtype(_)
                    | StructureItemDesc::Tstr_open(_)
                    | StructureItemDesc::Tstr_attribute(_) => {}
                    // The identifiers of a derived item are the values its
                    // obligations resolved.
                    StructureItemDesc::Tstr_derived(idx) => {
                        for bound in ta.derived.bound(*idx) {
                            for path in ta.derived.values_of(&bound) {
                                path.for_each_head(&mut |id| ids.push(*id));
                            }
                        }
                    }
                }
            }
        }
        ModuleExprDesc::Tmod_apply(functor, arg, _) => {
            collect_module_expr_ident_heads(ta, ta.module_expr(*functor), ids);
            collect_module_expr_ident_heads(ta, ta.module_expr(*arg), ids);
        }
        ModuleExprDesc::Tmod_functor(_, _, mty, body) => {
            if let Some(mty) = mty {
                collect_module_type_ident_heads(ta, ta.module_type(*mty), ids);
            }
            collect_module_expr_ident_heads(ta, ta.module_expr(*body), ids);
        }
        ModuleExprDesc::Tmod_constraint(module_expr, _, constraint, _) => {
            collect_module_expr_ident_heads(ta, ta.module_expr(*module_expr), ids);
            if let ModuleTypeConstraint::Tmodtype_explicit(mty) = constraint {
                collect_module_type_ident_heads(ta, ta.module_type(*mty), ids);
            }
        }
        ModuleExprDesc::Tmod_unpack(expr, _) => {
            collect_expression_ident_heads(ta, *expr, ids);
        }
    }
}

fn collect_module_type_ident_heads(
    ta: &TypedArena,
    module_type: &ModuleType,
    ids: &mut Vec<Ident>,
) {
    match &module_type.mty_desc {
        ModuleTypeDesc::Tmty_typeof(module_expr) => {
            collect_module_expr_ident_heads(ta, ta.module_expr(*module_expr), ids);
        }
        ModuleTypeDesc::Tmty_functor(_, _, param, body) => {
            if let Some(param) = param {
                collect_module_type_ident_heads(ta, ta.module_type(*param), ids);
            }
            collect_module_type_ident_heads(ta, ta.module_type(*body), ids);
        }
        ModuleTypeDesc::Tmty_with(module_type, _) => {
            collect_module_type_ident_heads(ta, ta.module_type(*module_type), ids);
        }
        ModuleTypeDesc::Tmty_ident(_, _)
        | ModuleTypeDesc::Tmty_signature(_)
        | ModuleTypeDesc::Tmty_alias(_, _) => {}
    }
}

fn type_match_cases_sequential(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    cases: &[&crate::parser::ast::Case],
    scrutinee: CaseScrutinee,
    body_ty: TypeExprRef,
    body_context: Option<ClashSite>,
    lev: i32,
) -> TypeCoreResult<Vec<crate::types::typedtree::Case>> {
    // OCaml compiler/ml/typecore.ml:4420-4438 builds `pat_env_list` for all
    // cases before typecore.ml:4473-4505 types any case body. Keep the same
    // two-phase order for the GADT fallback path; otherwise constructors in
    // later patterns are forced after binders in earlier bodies, shifting
    // strict typedtree stamps.
    let mut pending_cases = Vec::with_capacity(cases.len());
    for case in cases {
        pending_cases.push(type_case_pattern(tctx, env, case, scrutinee, lev)?);
    }

    // OCaml typecore.ml:4441-4444: `unify_pats ty_arg'` once every pattern is
    // typed, each under its own extended environment, before any body.
    let ty_arg_prime = tctx.type_ctx.new_var(None);
    let unified = pending_cases.iter().try_for_each(|pending| {
        tctx.unify_state.set_env(&pending.case_env);
        unify_pattern_types(
            tctx,
            pending.typed_pat.pat_loc,
            pending.typed_pat.pat_type,
            ty_arg_prime,
        )
    });
    tctx.unify_state.set_env(env);
    unified?;
    // OCaml typecore.ml:4407, 4423: the cases' pattern forces run together
    // after `unify_pats`.
    let pattern_forces: Vec<GlobalizeForce> = pending_cases
        .iter_mut()
        .flat_map(|pending| std::mem::take(&mut pending.pattern_forces))
        .collect();
    run_globalize_forces(tctx, pattern_forces)?;

    let mut typed_cases = Vec::with_capacity(pending_cases.len());
    for pending in pending_cases {
        typed_cases.push(type_pending_case_body(
            tctx,
            env,
            pending,
            body_ty,
            body_context,
        )?);
    }
    Ok(typed_cases)
}

struct PendingMatchCase<'a> {
    parsed_case: &'a crate::parser::ast::Case,
    typed_pat: Pattern,
    case_env: Env,
    unpacks: Vec<PatternVariable>,
}

struct PendingSequentialMatchCase<'a> {
    parsed_case: &'a crate::parser::ast::Case,
    typed_pat: Pattern,
    case_env: Env,
    unpacks: Vec<PatternVariable>,
    case_has_gadt: bool,
    pattern_forces: Vec<GlobalizeForce>,
}

fn pressure_matrix_close_variant_type(tctx: &mut TypeCheckContext<'_>, env: &Env, ty: TypeExprRef) {
    let ctx = tctx.type_ctx;
    let expanded = crate::types::ctype::expand_head(ctx, env, ty);
    let repr = ctx.repr(expanded);
    let desc = ctx.get_desc(repr);
    let row = match &*desc {
        TypeDesc::Tvariant(row) => crate::types::btype::row_repr(ctx, &ctx.row_desc(row)),
        _ => return,
    };

    if crate::types::btype::row_fixed(ctx, &row) {
        return;
    }

    let mut row_name = row.row_name.clone();
    for (_, field) in &row.row_fields {
        if let Some(link) = crate::types::btype::row_field_unmatched_reither_link(ctx, field) {
            ctx.set_row_field(link, crate::types::type_expr::RowField::Rabsent);
            row_name = None;
        }
    }

    if !row.row_closed || row_name != row.row_name {
        let closed_row = crate::types::type_expr::RowDesc {
            row_fields: vec![].into(),
            row_more: ctx.new_generic_var(None),
            row_closed: true,
            row_fixed: row.row_fixed,
            row_name,
        };
        let closed_ty = ctx.new_generic_type(TypeDesc::Tvariant(ctx.new_row_desc(closed_row)));
        let _ = crate::types::unify(ctx, &mut tctx.unify_state, row.row_more, closed_ty);
    }
}

fn typed_pattern_has_variant(ta: &TypedArena, pat: &Pattern) -> bool {
    match &pat.pat_desc {
        PatternDesc::Tpat_variant(_, _, _) => true,
        PatternDesc::Tpat_alias(inner, _, _) => typed_pattern_has_variant(ta, ta.pattern(*inner)),
        PatternDesc::Tpat_or(left, right, _) => {
            typed_pattern_has_variant(ta, ta.pattern(*left))
                || typed_pattern_has_variant(ta, ta.pattern(*right))
        }
        PatternDesc::Tpat_tuple(items) | PatternDesc::Tpat_array(items) => ta
            .patterns(*items)
            .any(|p| typed_pattern_has_variant(ta, p)),
        PatternDesc::Tpat_construct(_, _, args) => {
            ta.patterns(*args).any(|p| typed_pattern_has_variant(ta, p))
        }
        PatternDesc::Tpat_record(fields, _, _) => fields
            .iter()
            .any(|(_, _, field_pat, _)| typed_pattern_has_variant(ta, ta.pattern(*field_pat))),
        PatternDesc::Tpat_dict(entries) => entries
            .iter()
            .any(|entry| typed_pattern_has_variant(ta, ta.pattern(entry.tdp_pattern))),
        PatternDesc::Tpat_any
        | PatternDesc::Tpat_var(_, _)
        | PatternDesc::Tpat_constant(_)
        | PatternDesc::Tpat_interval(..) => false,
    }
}

fn pressure_variants_on_match_cases(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pending_cases: &[PendingMatchCase<'_>],
) {
    let patl: Vec<&Pattern> = pending_cases
        .iter()
        .map(|pending| &pending.typed_pat)
        .collect();
    parmatch_pressure_variants(tctx, env, &patl);
}

/// `Parmatch.pressure_variants env patl` (parmatch.ml:1392-1395).
fn parmatch_pressure_variants(tctx: &mut TypeCheckContext<'_>, env: &Env, patl: &[&Pattern]) {
    let Some(first) = patl.first() else {
        return;
    };
    let tdefs = tctx.type_ctx.store_typed_env(env);
    let expected_ty = first.pat_type;
    let mut ta = std::mem::take(&mut tctx.typed);
    let lowering = crate::types::dict_pattern::Lowering::new(tctx.type_ctx, &ta, patl);
    let lowered: Vec<_> = patl.iter().map(|pat| {
        let id = ta.push_pattern((*pat).clone());
        lowering.lower(&mut ta, id)
    }).collect();
    let oracle = TypecoreParmatchOracle {
        tctx: &mut *tctx,
        env,
        expected_ty,
        level: 0,
        partial_explode: 0,
        none_type: None,
    };
    let mut pm = crate::types::parmatch::Parmatch::new(oracle, &ta);
    let imported: Vec<_> = lowered.iter().map(|pat| pm.import(ta.pattern(*pat))).collect();
    pm.pressure_variants(tdefs, &imported);
    drop(pm);
    tctx.typed = ta;
}

fn add_pattern_variable_value(
    tctx: &mut TypeCheckContext<'_>,
    env: &mut Env,
    pv: &PatternVariable,
) {
    let desc = ValueDescription {
        val_type: pv.ty,
        val_kind: crate::types::ValueKind::ValReg,
        val_loc: tctx.intern_ast_loc(tctx.arena, pv.loc_idx),
        val_attributes: Default::default(),
        val_path: None,
    };
    env.add_value(pv.id, desc);

    if !pv.is_module {
        let name = pv.id.name();
        let warning = if pv.is_as_variable {
            Warning::UnusedVariable {
                name: name.to_string(),
            }
        } else {
            Warning::UnusedVariableStrict {
                name: name.to_string(),
            }
        };
        tctx.add_value_usage_check(name, pv.loc, pv.loc_idx, warning);
    }
}

fn type_match_cases_batch_non_gadt<'a>(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    cases: &[&'a crate::parser::ast::Case],
    scrutinee: CaseScrutinee,
    body_ty: TypeExprRef,
    body_context: Option<ClashSite>,
) -> TypeCoreResult<Vec<crate::types::typedtree::Case>> {
    let CaseScrutinee {
        ty: ty_arg,
        generic_ty: generic_scrutinee_ty,
        erase_either,
    } = scrutinee;
    if cases.is_empty() {
        return Ok(Vec::new());
    }

    let ctx = tctx.type_ctx;
    // OCaml compiler/ml/typecore.ml:4396-4397: without GADTs, `lev` is the
    // level before the propagation `begin_def`, and typecore.ml:4434 passes it
    // to `type_pattern ~lev`.
    let lev = ctx.current_level();
    let single_var_case = matches!(
        cases,
        [case] if is_simple_variable_pattern(tctx.arena, tctx.arena.get_pat(case.pc_lhs))
    );
    // Match OCaml: ty_arg is always generic for Pexp_match (generalized by caller),
    // so propagate is always true. Use generic_scrutinee_ty for the level check.
    let propagate = ctx.get_level(ctx.repr(generic_scrutinee_ty)) == crate::types::GENERIC_LEVEL
        || !single_var_case;

    let mut scope_open = false;
    let batch_result = (|| -> TypeCoreResult<Vec<crate::types::typedtree::Case>> {
        if propagate {
            ctx.begin_def();
            scope_open = true;
        }

        let mut pending_cases: Vec<PendingMatchCase<'a>> = Vec::with_capacity(cases.len());
        let mut pattern_forces: Vec<GlobalizeForce> = Vec::new();
        for case in cases {
            // Match OCaml type_cases: instance the GENERIC scrutinee type inside
            // begin_def. This creates fresh copies at the elevated level (L+1).
            // After end_def + generalize, pattern types become GENERIC, preventing
            // body unification from contaminating pattern types.
            let case_scrutinee_ty = if erase_either {
                instance_for_erase_either_patterns(ctx, ty_arg)
            } else if propagate {
                crate::types::instance(ctx, generic_scrutinee_ty)
            } else {
                crate::types::instance(ctx, ty_arg)
            };
            let mut state = PatternState::new();
            state.reset(true);
            let typed_pat = type_pattern_with_existentials_at_level(
                tctx,
                env,
                tctx.arena.get_pat(case.pc_lhs),
                case_scrutinee_ty,
                PatternOptions {
                    mode: PatternMode::Normal,
                    allow_existentials: true,
                    level: lev,
                },
                &mut state,
                0,
            )?;
            let mut case_env = env.clone();
            let mut unpacks: Vec<PatternVariable> = Vec::new();
            // typecore.ml:1964-1972: the unused-variable checks are set up in
            // the pattern's warning scope.
            let pattern_attributes = &tctx.arena.get_pat(case.pc_lhs).ppat_attributes;
            crate::types::typemod::with_warning_scope(
                tctx,
                tctx.arena,
                pattern_attributes,
                false,
                |tctx| {
                    for pv in &state.pattern_variables {
                        add_pattern_variable_value(tctx, &mut case_env, pv);
                        if pv.is_module {
                            // Match OCaml order in wrap_unpacks (`x :: module_variables`).
                            unpacks.insert(0, pv.clone());
                        }
                    }
                    Ok::<(), TypeCoreError>(())
                },
            )?;

            // OCaml typecore.ml:4407: `pattern_force := force @ !pattern_force`.
            pattern_forces.extend(state.take_globalize_forces());
            pending_cases.push(PendingMatchCase {
                parsed_case: case,
                typed_pat,
                case_env,
                unpacks,
            });
        }

        // Match OCaml type_cases delayed unification (`unify_pats ty_arg'`).
        let ty_arg_prime = ctx.new_var(None);
        let unify_pats_result = (|| -> TypeCoreResult<()> {
            for pending in &pending_cases {
                // OCaml uses `unify_pat ext_env ...` where each pattern is
                // unified under its own extended environment.
                tctx.unify_state.set_env(&pending.case_env);
                // OCaml compiler/ml/typecore.ml:4441-4444 delays pattern
                // unification until every case has been typed, then runs
                // `unify_pat ext_env pat ty_arg'` in case order.
                unify_pattern_types(
                    tctx,
                    pending.typed_pat.pat_loc,
                    pending.typed_pat.pat_type,
                    ty_arg_prime,
                )?;
            }
            Ok(())
        })();
        tctx.unify_state.set_env(env);
        unify_pats_result?;

        // Match OCaml type_cases ordering exactly: pressure_variants mutates the
        // original pattern row types through the recursive pattern matrix before
        // finalize_variant converts still-open Reither fields.
        if pending_cases
            .iter()
            .any(|pending| typed_pattern_has_variant(&tctx.typed, &pending.typed_pat))
        {
            pressure_variants_on_match_cases(tctx, env, &pending_cases);
            for pending in pending_cases.iter_mut() {
                finalize_variant_in_pattern(tctx, env, &pending.typed_pat, false);
            }
        }
        // OCaml typecore.ml:4422-4423: "Contaminating" unifications start here.
        run_globalize_forces(tctx, std::mem::take(&mut pattern_forces))?;

        if propagate || erase_either {
            let propagated_ty = if erase_either {
                crate::types::instance(ctx, ty_arg)
            } else {
                crate::types::instance(ctx, generic_scrutinee_ty)
            };
            let propagate_result = (|| -> TypeCoreResult<()> {
                for pending in &pending_cases {
                    tctx.unify_state.set_env(&pending.case_env);
                    // OCaml compiler/ml/typecore.ml:4455-4457 repeats
                    // `unify_pats propagated` after variant finalization.
                    unify_pattern_types(
                        tctx,
                        pending.typed_pat.pat_loc,
                        pending.typed_pat.pat_type,
                        propagated_ty,
                    )?;
                }
                Ok(())
            })();
            tctx.unify_state.set_env(env);
            propagate_result?;
        }

        if propagate {
            // Match OCaml type_cases:
            //   List.iter (iter_pattern (fun {pat_type=t} -> unify_var env t (newvar ()))) patl;
            // before end_def/generalize.
            let lower_result = (|| -> TypeCoreResult<()> {
                for pending in &pending_cases {
                    tctx.unify_state.set_env(&pending.case_env);
                    let mut nodes: Vec<(LocIdx, TypeExprRef)> = Vec::new();
                    iter_typed_pattern(&tctx.typed, &pending.typed_pat, &mut |pat| {
                        nodes.push((pat.pat_loc, pat.pat_type));
                    });
                    for (pat_loc, pat_type) in nodes {
                        let fresh = ctx.new_var(None);
                        unify_pattern_types(tctx, pat_loc, pat_type, fresh)?;
                    }
                }
                Ok(())
            })();
            tctx.unify_state.set_env(env);
            lower_result?;

            ctx.end_def();
            scope_open = false;
            for pending in &pending_cases {
                iter_typed_pattern(&tctx.typed, &pending.typed_pat, &mut |pat| {
                    crate::types::generalize(tctx.type_ctx, pat.pat_type);
                });
            }
        }

        let mut typed_cases = Vec::with_capacity(pending_cases.len());
        for pending in pending_cases {
            let typed_guard = if let Some(guard) = &pending.parsed_case.pc_guard {
                let bool_ty = env.type_bool(ctx);
                let guard_expr = tctx.arena.get_expanded_expr(*guard);
                Some(type_expect_with_module_unpacks(
                    tctx,
                    &pending.case_env,
                    guard_expr,
                    bool_ty,
                    &pending.unpacks,
                    Some(ClashSite::IfCondition),
                )?)
            } else {
                None
            };

            let case_has_gadt = pattern_contains_generalized_constructor(
                tctx,
                env,
                tctx.arena.get_pat(pending.parsed_case.pc_lhs),
            );
            let case_body_ty = if case_has_gadt {
                crate::types::ctype::subst_identity_copy(ctx, body_ty)
            } else {
                body_ty
            };

            let body_expr = tctx.arena.get_expanded_expr(pending.parsed_case.pc_rhs);
            let typed_body = type_expect_with_module_unpacks(
                tctx,
                &pending.case_env,
                body_expr,
                case_body_ty,
                &pending.unpacks,
                body_context,
            )?;
            // Match OCaml type_cases: `exp_type = instance env ty_res'` where
            // `ty_res'` is corrected per-case when the pattern contains GADTs.
            let case_exp_ty = crate::types::instance(ctx, case_body_ty);
            let typed_body = Expression {
                exp_type: case_exp_ty,
                ..typed_body
            };
            typed_cases.push(crate::types::typedtree::Case {
                c_lhs: tctx.typed.push_pattern(pending.typed_pat),
                c_guard: typed_guard.map(|e| tctx.push_expr(e)),
                c_rhs: tctx.push_expr(typed_body),
            });
        }
        Ok(typed_cases)
    })();

    if scope_open {
        ctx.end_def();
    }

    batch_result
}

/// Type a conditional, including the two-case boolean match rule.
/// Cost: one condition and at most two branch checks, then one typed node;
/// no parsed node, list, lookup table or traversal is allocated here.
#[allow(clippy::too_many_arguments)]
fn type_conditional(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    expr: &ParsedExpression,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
    exp_env_ref: EnvRef,
    cond_idx: crate::parse_arena::ExprIdx,
    then_idx: crate::parse_arena::ExprIdx,
    else_idx: Option<crate::parse_arena::ExprIdx>,
    return_context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    let loc = expr.pexp_loc;
    let (cond_idx, then_idx, else_idx) = (&cond_idx, &then_idx, &else_idx);
    // If expression
    let bool_ty = env.type_bool(ctx);

    // Condition should be bool
    let cond = tctx.arena.get_expanded_expr(*cond_idx);
    let typed_cond = type_expect(
        tctx,
        env,
        cond,
        bool_ty,
        Some(ClashSite::IfCondition),
    )?;
    let then_branch = tctx.arena.get_expanded_expr(*then_idx);
    let else_branch = else_idx.map(|idx| tctx.arena.get_expanded_expr(idx));

    match else_branch {
        Some(else_branch) => {
            // OCaml keeps sharing by unifying else with then.exp_type.
            let typed_then =
                type_expect(tctx, env, then_branch, expected_ty, return_context)?;
            let typed_else =
                type_expect(tctx, env, else_branch, expected_ty, return_context)?;
            unify_expression_types(
                tctx,
                loc,
                typed_else.exp_type,
                typed_then.exp_type,
                return_context,
            )?;
            let then_exp_type = typed_then.exp_type;

            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_ifthenelse(
                        tctx.push_expr(typed_cond),
                        tctx.push_expr(typed_then),
                        Some(tctx.push_expr(typed_else)),
                    ),
                    loc,
                    then_exp_type,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }
        None => {
            // Match OCaml Pexp_ifthenelse without else:
            // `type_expect ... sifso Predef.type_unit`
            // The then-branch must be typed against the generic
            // predef unit scheme itself, not a fresh unit instance,
            // so inner applications/matches still instance it lazily.
            let typed_then =
                type_expect(tctx, env, then_branch, ctx.predef_unit(), return_context)?;
            let then_exp_type = typed_then.exp_type;
            rue_unify(tctx, loc, then_exp_type, expected_ty, context)?;

            Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_ifthenelse(
                        tctx.push_expr(typed_cond),
                        tctx.push_expr(typed_then),
                        None,
                    ),
                    loc,
                    then_exp_type,
                    exp_env_ref,
                );
                tctx.typed
                    .with_exp_attributes(typed_node, expr.pexp_attributes.clone())
            })
        }
    }
}

/// Type check match expression.
#[allow(clippy::too_many_arguments)]
fn type_match(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    attributes: &[crate::parser::ast::Attribute],
    binding_attributes: &[crate::parser::ast::Attribute],
    scrutinee: &ParsedExpression,
    cases: &[crate::parser::ast::Case],
    expected_ty: TypeExprRef,
    match_context: Option<MatchContext>,
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    // typecore.ml:2855-2864: a match the type checker synthesized says what it
    // stands for; otherwise only the parsed `let?` is marked, by
    // `let.unwrap`.
    let body_context = match match_context {
        Some(MatchContext::Function) => None,
        None => {
            if attributes
                .iter()
                .chain(binding_attributes)
                .any(|attr| tctx.arena.get_string(attr.0.txt) == "let.unwrap")
            {
                Some(ClashSite::LetUnwrapReturn)
            } else {
                Some(ClashSite::SwitchExpression)
            }
        }
    };

    // Match OCaml typecore.ml Pexp_match:
    // begin_def (); type_exp scrutinee; end_def ();
    // generalize_expansive (if needed); generalize;
    ctx.begin_def();
    let scrutinee_ty = ctx.new_var(None);
    let typed_scrutinee = match type_expect(tctx, env, scrutinee, scrutinee_ty, None) {
        Ok(expr) => expr,
        Err(err) => {
            ctx.end_def();
            return Err(err);
        }
    };
    ctx.end_def();
    let is_expansive = !is_nonexpansive_node(tctx, &typed_scrutinee);
    if is_expansive {
        crate::types::ctype::generalize_expansive(ctx, env, typed_scrutinee.exp_type);
    }
    crate::types::ctype::generalize(ctx, typed_scrutinee.exp_type);
    // OCaml split_cases: separate exception cases from value cases.
    // Exception cases have their Ppat_exception wrapper unwrapped, and
    // are typed against Predef.type_exn instead of the scrutinee type.
    let mut val_caselist: Vec<&crate::parser::ast::Case> = Vec::new();
    let mut exn_caselist: Vec<crate::parser::ast::Case> = Vec::new();
    for case in cases {
        let lhs_pat = tctx.arena.get_pat(case.pc_lhs);
        if let crate::parser::ast::PatternDesc::Ppat_exception(inner_pat) = &lhs_pat.ppat_desc {
            // Unwrap the Ppat_exception: replace pc_lhs with the inner pattern
            let unwrapped_case = crate::parser::ast::Case {
                pc_bar: case.pc_bar,
                pc_lhs: *inner_pat,
                pc_guard: case.pc_guard,
                pc_rhs: case.pc_rhs,
            };
            exn_caselist.push(unwrapped_case);
        } else {
            val_caselist.push(case);
        }
    }
    if val_caselist.is_empty() && !exn_caselist.is_empty() {
        return Err(TypeCoreError::NoValueClauses { loc });
    }

    let has_generalized_value_patterns = val_caselist.iter().any(|case| {
        pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(case.pc_lhs))
    });
    // Match OCaml type_cases: pass the generalized scrutinee type directly.
    // OCaml applies correct_levels/instance inside type_cases.
    let ty_arg = typed_scrutinee.exp_type;
    // Pass the GENERIC scrutinee type so instance() inside begin_def creates
    // fresh copies at the elevated level, matching OCaml's type_cases flow.
    let generic_scrutinee_ty = typed_scrutinee.exp_type;
    let contains_polyvars = val_caselist.iter().any(|case| {
        parsed_pattern_contains_polymorphic_variant(tctx.arena, tctx.arena.get_pat(case.pc_lhs))
    });
    let erase_either = contains_polyvars && type_contains_variant_either(ctx, ty_arg);
    let ty_arg = if has_generalized_value_patterns || erase_either {
        crate::types::ctype::subst_identity_copy(ctx, ty_arg)
    } else {
        ty_arg
    };
    let ty_res = if has_generalized_value_patterns {
        crate::types::ctype::subst_identity_copy(ctx, expected_ty)
    } else {
        expected_ty
    };
    let duplicated_case_env;
    let val_case_env = if has_generalized_value_patterns {
        duplicated_case_env = duplicate_ident_types_for_gadt_cases(tctx, env, &val_caselist);
        &duplicated_case_env
    } else {
        env
    };

    let gadt_match_env;
    let mut gadt_scope_open = false;
    let mut gadt_lev = ctx.current_level();
    let val_case_env = if has_generalized_value_patterns {
        // OCaml compiler/ml/typecore.ml:4387-4403 calls `init_env` before
        // pattern typing when `has_gadts`, and keeps that begin_def scope open
        // until typecore.ml:4511-4535 finishes body typing, exhaustiveness, and
        // the escaping-result check. Keep the raised level live while Rust
        // types case bodies so nested matches allocate binders after the same
        // `Ident.set_current_time (get_current_level ())` reservation.
        ctx.begin_def();
        gadt_scope_open = true;
        ctx.set_current_time(ctx.current_level());
        gadt_lev = ctx.current_stamp();
        ctx.init_def(gadt_lev + 1000);
        let mut scoped_env = val_case_env.clone();
        scoped_env.add_gadt_instance_level();
        gadt_match_env = scoped_env;
        &gadt_match_env
    } else {
        val_case_env
    };

    let value_usage_checkpoint = tctx.value_usage_check_checkpoint();
    let typed_val_cases_result = if has_generalized_value_patterns {
        // OCaml compiler/ml/typecore.ml:4376-4378 replaces `ty_arg` with
        // `correct_levels ty_arg` when the cases contain GADTs, and
        // typecore.ml:4432 instances that corrected type for every pattern.
        type_match_cases_sequential(
            tctx,
            val_case_env,
            &val_caselist,
            CaseScrutinee {
                ty: ty_arg,
                generic_ty: ty_arg,
                erase_either,
            },
            ty_res,
            body_context,
            gadt_lev,
        )
    } else {
        match type_match_cases_batch_non_gadt(
            tctx,
            env,
            &val_caselist,
            CaseScrutinee {
                ty: ty_arg,
                generic_ty: generic_scrutinee_ty,
                erase_either,
            },
            ty_res,
            body_context,
        ) {
            Ok(cases) => Ok(cases),
            Err(err) => {
                tctx.truncate_value_usage_checks(value_usage_checkpoint);
                Err(err)
            }
        }
    };
    let typed_val_cases = match typed_val_cases_result {
        Ok(cases) => cases,
        Err(err) => {
            if gadt_scope_open {
                ctx.end_def();
            }
            return Err(err);
        }
    };

    // Match OCaml type_cases:
    //   if has_gadts then
    //     let ty_res' = instance env ty_res in
    //     List.iter (fun c -> unify_exp ~context:None env c.c_rhs ty_res') cases
    // This links per-case body result copies back through one shared node.
    if has_generalized_value_patterns {
        let shared_case_body_ty = crate::types::instance(ctx, expected_ty);
        for case in &typed_val_cases {
            let rhs = tctx.expr(case.c_rhs);
            let (rhs_loc, rhs_type) = (rhs.exp_loc, rhs.exp_type);
            unify_expression_types(tctx, rhs_loc, rhs_type, shared_case_body_ty, None)?;
        }
    }

    // OCaml type_cases: `unify_pats (instance env ty_arg)` propagation happens
    // INSIDE begin_def scope (line 3993), already handled by the per-case
    // `instance` in type_match_cases_batch_non_gadt. Do NOT directly unify pattern types with
    // typed_scrutinee.exp_type — that creates false node sharing between scrutinee
    // and pattern types (OCaml keeps them separate via fresh instances).

    let needs_exhaust_check = !matches!(
        val_caselist.as_slice(),
        [case] if is_simple_variable_pattern(tctx.arena, tctx.arena.get_pat(case.pc_lhs))
    );
    let mut unused_check_level = ctx.current_level();
    let mut unused_expected_ty = ty_arg;
    let partial = if has_generalized_value_patterns {
        unused_check_level = gadt_lev;
        unused_expected_ty = crate::types::ctype::subst_for_saving_copy(ctx, ty_arg);
        let partial = parmatch_check_partial(
            tctx,
            val_case_env,
            gadt_lev,
            None,
            unused_expected_ty,
            loc,
            &case_refs(&typed_val_cases),
        );
        ctx.end_def();
        unify_expression_types(
            tctx,
            loc,
            crate::types::instance(ctx, ty_res),
            ctx.new_var(None),
            None,
        )?;
        partial
    } else if needs_exhaust_check {
        // OCaml compiler/ml/typecore.ml:4387-4399 computes
        // `needs_exhaust_check` and defines `init_env`, then
        // typecore.ml:4511-4535 runs that init before `check_partial`
        // and closes it with `end_def` plus the escaping-result check.
        // `Ident.set_current_time (get_current_level ())` is observable:
        // it advances later binder stamps when a previous begin_def raised
        // the type level beyond the current ident stamp.
        ctx.begin_def();
        ctx.set_current_time(ctx.current_level());
        let lev = ctx.current_stamp();
        ctx.init_def(lev + 1000);
        unused_check_level = lev;
        unused_expected_ty = crate::types::ctype::subst_for_saving_copy(ctx, ty_arg);
        let partial = parmatch_check_partial(
            tctx,
            val_case_env,
            lev,
            None,
            unused_expected_ty,
            loc,
            &case_refs(&typed_val_cases),
        );
        ctx.end_def();
        unify_expression_types(
            tctx,
            loc,
            crate::types::instance(ctx, ty_res),
            ctx.new_var(None),
            None,
        )?;
        partial
    } else {
        parmatch_check_partial(
            tctx,
            val_case_env,
            unused_check_level,
            None,
            ty_arg,
            loc,
            &case_refs(&typed_val_cases),
        )
    };
    report_unused_match_cases(
        tctx,
        val_case_env,
        &typed_val_cases,
        has_generalized_value_patterns || needs_exhaust_check || contains_polyvars,
        unused_check_level,
        unused_expected_ty,
        true,
    );

    // Type check exception cases against exn type.
    // OCaml routes exception cases through type_cases with Predef.type_exn,
    // which includes the propagation cycle (begin_def/end_def/generalize on
    // all pattern types). This ensures as-bound variables get generalized types
    // so instance() creates fresh copies at use sites.
    let typed_exn_cases = if !exn_caselist.is_empty() {
        let ctx = tctx.type_ctx;
        let exn_ty = crate::types::ctype::instance(ctx, ctx.predef_exn());
        let generic_exn_ty = ctx.predef_exn();
        let exn_case_refs: Vec<&crate::parser::ast::Case> = exn_caselist.iter().collect();
        let typed = type_match_cases_batch_non_gadt(
            tctx,
            env,
            &exn_case_refs,
            CaseScrutinee {
                ty: exn_ty,
                generic_ty: generic_exn_ty,
                erase_either: false,
            },
            expected_ty,
            body_context,
        )?;
        // `type_cases ... Predef.type_exn ty_expected false loc exn_caselist`
        // runs after the value cases were checked, and also checks unused
        // cases (typecore.ml:2638-2641, 4483-4496).
        finish_non_gadt_type_cases(
            tctx,
            env,
            loc,
            expected_ty,
            exn_ty,
            &exn_case_refs,
            &typed,
        )?;
        typed
    } else {
        Vec::new()
    };

    // Keep sharing: match OCaml's `exp_type = instance env ty_expected`
    let result_ty = crate::types::instance(ctx, expected_ty);
    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_match(
                tctx.push_expr(typed_scrutinee),
                tctx.typed.push_cases(typed_val_cases),
                tctx.typed.push_cases(typed_exn_cases),
                partial,
            ),
            loc,
            result_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.iter().chain(binding_attributes).cloned().collect::<Vec<_>>().into())
    })
}

/// Finalize variant patterns: convert Reither fields to Rpresent in open rows.
/// Matches OCaml's finalize_variant (typecore.ml:358-385).
fn finalize_variant_in_pattern(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pat: &Pattern,
    convert_closed_reither: bool,
) {
    let node = FinalizeVariantNode::of(&tctx.typed, pat);
    finalize_variant_node(tctx, env, node, convert_closed_reither);
}

/// What [`finalize_variant_in_pattern`] reads from one pattern node, copied
/// out so the walk can update the type checker while it descends.
struct FinalizeVariantNode {
    variant: Option<(String, Option<TPatIdx>)>,
    pat_type: TypeExprRef,
    children: smallvec::SmallVec<[TPatIdx; 4]>,
}

impl FinalizeVariantNode {
    fn of(ta: &TypedArena, pat: &Pattern) -> Self {
        let variant = match &pat.pat_desc {
            PatternDesc::Tpat_variant(tag, arg, _) => Some((tag.clone(), *arg)),
            _ => None,
        };
        let mut children: smallvec::SmallVec<[TPatIdx; 4]> = smallvec::SmallVec::new();
        match &pat.pat_desc {
            PatternDesc::Tpat_variant(_, arg, _) => children.extend(*arg),
            PatternDesc::Tpat_alias(inner, _, _) => children.push(*inner),
            PatternDesc::Tpat_or(left, right, _) => children.extend([*left, *right]),
            PatternDesc::Tpat_tuple(items)
            | PatternDesc::Tpat_array(items)
            | PatternDesc::Tpat_construct(_, _, items) => {
                children.extend_from_slice(ta.pattern_list(*items))
            }
            PatternDesc::Tpat_record(fields, _, _) => {
                children.extend(fields.iter().map(|(_, _, field_pat, _)| *field_pat))
            }
            PatternDesc::Tpat_dict(entries) => children.extend(entries.iter().map(|e| e.tdp_pattern)),
            PatternDesc::Tpat_interval(..) | PatternDesc::Tpat_any | PatternDesc::Tpat_var(_, _) | PatternDesc::Tpat_constant(_) => {
            }
        }
        FinalizeVariantNode {
            variant,
            pat_type: pat.pat_type,
            children,
        }
    }
}

fn finalize_variant_node(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    node: FinalizeVariantNode,
    convert_closed_reither: bool,
) {
    let FinalizeVariantNode {
        variant,
        pat_type,
        children,
    } = node;
    if let Some((tag, arg)) = &variant {
        let ctx = tctx.type_ctx;
        let expanded = crate::types::ctype::expand_head(ctx, env, pat_type);
        let repr = ctx.repr(expanded);
        let desc = ctx.get_desc(repr);
        if let TypeDesc::Tvariant(row) = &*desc {
            let row = crate::types::btype::row_repr(ctx, &ctx.row_desc(row));
            let row_is_fixed = crate::types::btype::row_fixed(ctx, &row);
            let field_repr = crate::types::btype::row_field(ctx, tag, &row);
            match field_repr {
                crate::types::type_expr::RowField::Rabsent => {}
                crate::types::type_expr::RowField::Reither {
                    constant: true,
                    types,
                    link,
                    ..
                } if !row.row_closed && types.is_empty() => {
                    ctx.set_row_field(link, crate::types::type_expr::RowField::Rpresent(None));
                }
                crate::types::type_expr::RowField::Reither {
                    constant: false,
                    types,
                    link,
                    ..
                } if !row.row_closed && !types.is_empty() => {
                    let head = types[0];
                    ctx.set_row_field(
                        link,
                        crate::types::type_expr::RowField::Rpresent(Some(head)),
                    );
                    if let Some(arg_pat) = arg.as_ref() {
                        for ty in types {
                            let _ = unify_pattern_types(
                                tctx,
                                tctx.typed.pattern(*arg_pat).pat_loc,
                                tctx.typed.pattern(*arg_pat).pat_type,
                                ty,
                            );
                        }
                    }
                }
                // Keep erase_either fallback for closed rows.
                crate::types::type_expr::RowField::Reither {
                    constant: true,
                    types,
                    link,
                    ..
                } if convert_closed_reither && row.row_closed && types.is_empty() => {
                    ctx.set_row_field(link, crate::types::type_expr::RowField::Rpresent(None));
                }
                crate::types::type_expr::RowField::Reither {
                    constant: false,
                    types,
                    link,
                    ..
                } if convert_closed_reither && row.row_closed && !types.is_empty() => {
                    let head = types[0];
                    ctx.set_row_field(
                        link,
                        crate::types::type_expr::RowField::Rpresent(Some(head)),
                    );
                }
                // OCaml finalize_variant case 3:
                // Reither (c, _l, true, e) when not (row_fixed row) ->
                //   set_row_field e (Reither (c, [], false, ref None))
                crate::types::type_expr::RowField::Reither {
                    constant,
                    matched: true,
                    link,
                    ..
                } if !row_is_fixed => {
                    ctx.set_row_field(
                        link,
                        crate::types::type_expr::RowField::Reither {
                            constant,
                            types: vec![],
                            matched: false,
                            link: ctx.alloc_row_field(None),
                        },
                    );
                }
                _ => {}
            }
        }
    }

    for child in children {
        let child = FinalizeVariantNode::of(&tctx.typed, tctx.typed.pattern(child));
        finalize_variant_node(tctx, env, child, convert_closed_reither);
    }
}

fn pattern_contains_generalized_constructor(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pat: &ParsedPattern,
) -> bool {
    match &pat.ppat_desc {
        crate::parser::ast::PatternDesc::Ppat_construct(lid, arg) => {
            let lid_txt = tctx.resolve_lid(lid.txt).clone();
            let lid_name = tctx.longident_last_name(&lid_txt);
            let is_qualified = matches!(lid_txt, Longident::Ldot(..));
            // `Env.lookup_all_constructors` on a qualified name marks its head
            // through `lookup_module_descr` (env.ml:1076-1089).
            // typecore.ml:2172: `Env.lookup_all_constructors lid.txt env`,
            // without `?loc`.
            mark_open_lid_use(
                tctx.type_ctx,
                env,
                tctx.arena,
                &lid_txt,
                crate::types::env::OpenLookupKind::Component,
                None,
            );
            let is_generalized = if is_qualified {
                lookup_predef_option_constructor(&lid_txt, tctx.arena, env, tctx.type_ctx)
                    .map(|(_, desc)| desc.cstr_generalized)
                    .or_else(|| {
                        lookup_constructor_in_module(
                            &lid_txt,
                            tctx.arena,
                            env,
                            &mut tctx.persistent_env,
                            tctx.type_ctx,
                            None,
                        )
                        .map(|(_, desc)| desc.cstr_generalized)
                    })
                    .unwrap_or(false)
            } else {
                // Match OCaml contains_gadt: lookup_all_constructors and
                // treat the pattern as generalized if ANY candidate is generalized.
                env.find_all_constructors(lid_name)
                    .iter()
                    .any(|desc| desc.cstr_generalized)
            };
            is_generalized
                || tctx.arena.pat_list(arg.txt).iter().any(|inner| {
                    pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(*inner))
                })
        }
        crate::parser::ast::PatternDesc::Ppat_alias(inner, _) => {
            pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(*inner))
        }
        crate::parser::ast::PatternDesc::Ppat_tuple(items)
        | crate::parser::ast::PatternDesc::Ppat_array(items) => {
            tctx.arena.pat_list(*items).iter().any(|item| {
                pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(*item))
            })
        }
        crate::parser::ast::PatternDesc::Ppat_record(inner) => {
            tctx.arena.pat_field_list(inner.0).iter().any(|field| {
                pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(field.pat))
            })
        }
        crate::parser::ast::PatternDesc::Ppat_dict(entries) => entries.iter().any(|entry| {
            pattern_contains_generalized_constructor(
                tctx,
                env,
                tctx.arena.get_pat(entry.pdp_pattern),
            )
        }),
        crate::parser::ast::PatternDesc::Ppat_or(left, right) => {
            pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(*left))
                || pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(*right))
        }
        crate::parser::ast::PatternDesc::Ppat_constraint(inner) => {
            pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(inner.0))
        }
        crate::parser::ast::PatternDesc::Ppat_exception(inner) => {
            pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(*inner))
        }
        _ => false,
    }
}

fn collect_lident_idents_in_module_expr(
    arena: &ParseArena,
    mod_expr: &crate::parser::ast::ModuleExpr,
    out: &mut Vec<String>,
) {
    use crate::parser::ast::ModuleExprDesc as MED;
    use crate::parser::ast::StructureItemDesc as SID;

    match &mod_expr.pmod_desc {
        MED::Pmod_ident(_) | MED::Pmod_extension(_) => {}
        MED::Pmod_structure(items) => {
            for item in items.iter() {
                match &item.pstr_desc {
                    SID::Pstr_eval(inner) => {
                        collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.0), out);
                    }
                    SID::Pstr_value(inner) => {
                        for binding in arena.vb_list(inner.1).iter() {
                            collect_lident_idents_in_expression(
                                arena,
                                arena.get_expanded_expr(binding.pvb_expr),
                                out,
                            );
                        }
                    }
                    // The identifiers of a derived item are the names of its
                    // value obligations.
                    SID::Pstr_derived(idx) => {
                        for name in crate::binary_ast::derive::value_names(arena, *idx) {
                            if let Longident::Lident(id) = arena.get_longident(name) {
                                out.push(arena.get_string(*id).to_string());
                            }
                        }
                    }
                    SID::Pstr_module(binding) => {
                        collect_lident_idents_in_module_expr(
                            arena,
                            arena.get_mod_expr(binding.pmb_expr),
                            out,
                        );
                    }
                    SID::Pstr_recmodule(bindings) => {
                        for binding in bindings.iter() {
                            collect_lident_idents_in_module_expr(
                                arena,
                                arena.get_mod_expr(binding.pmb_expr),
                                out,
                            );
                        }
                    }
                    SID::Pstr_include(include_decl) => {
                        collect_lident_idents_in_module_expr(
                            arena,
                            arena.get_mod_expr(include_decl.pincl_mod),
                            out,
                        );
                    }
                    SID::Pstr_primitive(_)
                    | SID::Pstr_type(_)
                    | SID::Pstr_typext(_)
                    | SID::Pstr_exception(_)
                    | SID::Pstr_modtype(_)
                    | SID::Pstr_open(_)
                    | SID::Pstr_attribute(_)
                    | SID::Pstr_extension(_)
                    | SID::Pstr_raw(_) => {}
                }
            }
        }
        MED::Pmod_functor(inner) => {
            collect_lident_idents_in_module_expr(arena, arena.get_mod_expr(inner.2), out);
        }
        MED::Pmod_apply(lhs, rhs) => {
            collect_lident_idents_in_module_expr(arena, arena.get_mod_expr(*lhs), out);
            collect_lident_idents_in_module_expr(arena, arena.get_mod_expr(*rhs), out);
        }
        MED::Pmod_constraint(inner, _) | MED::Pmod_await(inner) => {
            collect_lident_idents_in_module_expr(arena, arena.get_mod_expr(*inner), out);
        }
        MED::Pmod_unpack(expr) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*expr), out);
        }
    }
}

fn collect_lident_idents_in_expression(
    arena: &ParseArena,
    expr: &ParsedExpression,
    out: &mut Vec<String>,
) {
    use crate::parser::ast::ExpressionDesc as ED;
    use crate::parser::ast::JsxElement;
    use crate::parser::ast::JsxProp;

    match &expr.pexp_desc {
        ED::Pexp_ident(lid) => {
            if let Longident::Lident(id) = arena.get_longident(lid.txt) {
                out.push(arena.get_string(*id).to_string());
            }
        }
        ED::Pexp_constant(_)
        | ED::Pexp_extension(_)
        | ED::Pexp_raw(_)
        | ED::Pexp_todo(_)
        | ED::Pexp_break
        | ED::Pexp_continue => {}
        ED::Pexp_let(inner) => {
            for binding in arena.vb_list(inner.1).iter() {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(binding.pvb_expr), out);
            }
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.2), out);
        }
        ED::Pexp_fun(inner) => {
            if let Some(default) = inner.default {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(default), out);
            }
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.rhs), out);
        }
        ED::Pexp_apply(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.funct), out);
            for (_label, arg) in arena.apply_args(inner.args) {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*arg), out);
            }
        }
        ED::Pexp_template(template) => {
            for value in &template.values {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*value), out);
            }
        }
        ED::Pexp_tagged_template(template) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(template.tag), out);
            for value in &template.values {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*value), out);
            }
        }
        ED::Pexp_match((scrutinee, cases)) | ED::Pexp_try((scrutinee, cases, None)) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*scrutinee), out);
            for case in arena.case_list(*cases).iter() {
                if let Some(guard) = case.pc_guard {
                    collect_lident_idents_in_expression(arena, arena.get_expanded_expr(guard), out);
                }
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(case.pc_rhs), out);
            }
        }
        // typecore.ml `iter_expression`: `expr e; List.iter case pel; Option.iter expr finally`.
        ED::Pexp_try((body, cases, Some(finally))) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*body), out);
            for case in arena.case_list(*cases).iter() {
                if let Some(guard) = case.pc_guard {
                    collect_lident_idents_in_expression(arena, arena.get_expanded_expr(guard), out);
                }
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(case.pc_rhs), out);
            }
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*finally), out);
        }
        ED::Pexp_tuple(items) | ED::Pexp_array(items) => {
            for item in arena.expr_list(*items).iter() {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*item), out);
            }
        }
        ED::Pexp_dict(entries) => {
            for entry in entries.iter() {
                match entry {
                    crate::parser::ast::DictEntry::Pdict_entry(_, e)
                    | crate::parser::ast::DictEntry::Pdict_spread(e) => {
                        collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*e), out)
                    }
                }
            }
        }
        ED::Pexp_spread(_, elements) => {
            for element in arena.spread_element_list(*elements) {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(element.expr()), out);
            }
        }
        ED::Pexp_construct(_, args) => {
            for arg in arena.expr_list(args.txt).iter() {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*arg), out);
            }
        }
        ED::Pexp_variant(inner) => {
            for arg in arena.expr_list(inner.1.txt).iter() {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*arg), out);
            }
        }
        ED::Pexp_record(inner) => {
            for field in arena.expr_field_list(inner.0).iter() {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(field.expr), out);
            }
            if let Some(base) = inner.1 {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(base), out);
            }
        }
        ED::Pexp_field(expr, _) | ED::Pexp_assert(expr) | ED::Pexp_await(expr) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*expr), out);
        }
        ED::Pexp_setfield(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.0), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.2), out);
        }
        ED::Pexp_ifthenelse(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.0), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.1), out);
            if let Some(else_expr) = inner.2 {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(else_expr), out);
            }
        }
        ED::Pexp_ternary(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.0), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.1), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.2), out);
        }
        ED::Pexp_braces(braces) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(braces.expr), out);
        }
        ED::Pexp_regexp(_) => {}
        ED::Pexp_sequence(lhs, rhs) | ED::Pexp_while(lhs, rhs) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*lhs), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*rhs), out);
        }
        ED::Pexp_for(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.1), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.2), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.4), out);
        }
        ED::Pexp_for_of(inner) | ED::Pexp_for_await_of(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.1), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.2), out);
        }
        ED::Pexp_constraint(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.0), out);
        }
        ED::Pexp_coerce(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.0), out);
        }
        ED::Pexp_object_get(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.0), out);
        }
        ED::Pexp_object_set(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.0), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.2), out);
        }
        ED::Pexp_object_literal(fields) => {
            for (_, field) in fields.iter() {
                collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*field), out);
            }
        }
        ED::Pexp_letmodule(inner) => {
            collect_lident_idents_in_module_expr(arena, arena.get_mod_expr(inner.1), out);
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.2), out);
        }
        ED::Pexp_letexception(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.1), out);
        }
        ED::Pexp_newtype(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.1), out);
        }
        ED::Pexp_pack(mod_expr) => {
            collect_lident_idents_in_module_expr(arena, arena.get_mod_expr(*mod_expr), out);
        }
        ED::Pexp_open(inner) => {
            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(inner.2), out);
        }
        ED::Pexp_jsx_element(inner) => match &**inner {
            JsxElement::Fragment(fragment) => {
                for child in fragment.children.iter() {
                    collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*child), out);
                }
            }
            JsxElement::Unary(unary) => {
                for prop in unary.props.iter() {
                    match prop {
                        JsxProp::Punning { .. } => {}
                        JsxProp::Value { value, .. } => {
                            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*value), out);
                        }
                        JsxProp::Spreading { expr, .. } => {
                            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*expr), out);
                        }
                    }
                }
            }
            JsxElement::Container(container) => {
                for prop in container.props.iter() {
                    match prop {
                        JsxProp::Punning { .. } => {}
                        JsxProp::Value { value, .. } => {
                            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*value), out);
                        }
                        JsxProp::Spreading { expr, .. } => {
                            collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*expr), out);
                        }
                    }
                }
                for child in container.children.iter() {
                    collect_lident_idents_in_expression(arena, arena.get_expanded_expr(*child), out);
                }
            }
        },
    }
}

fn all_idents_cases_with_generalized_constructor_order(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    cases: &[&crate::parser::ast::Case],
) -> Vec<String> {
    let mut encountered = Vec::new();
    for case in cases {
        let lhs = tctx.arena.get_pat(case.pc_lhs);
        if !pattern_contains_generalized_constructor(tctx, env, lhs) {
            continue;
        }
        if let Some(guard) = case.pc_guard {
            collect_lident_idents_in_expression(
                tctx.arena,
                tctx.arena.get_expanded_expr(guard),
                &mut encountered,
            );
        }
        collect_lident_idents_in_expression(
            tctx.arena,
            tctx.arena.get_expanded_expr(case.pc_rhs),
            &mut encountered,
        );
    }
    ocaml_hashtbl_replace_fold_order(&encountered)
}

fn duplicate_ident_types_for_gadt_cases(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    cases: &[&crate::parser::ast::Case],
) -> Env {
    let mut copied_env = env.clone();
    let idents = all_idents_cases_with_generalized_constructor_order(tctx, env, cases);
    for ident in idents {
        let current_ty = copied_env
            .find_value_with_id(&ident)
            .ok()
            .map(|(_, desc)| desc.val_type);
        if let Some(ty) = current_ty {
            let copied_ty = crate::types::ctype::subst_identity_copy(tctx.type_ctx, ty);
            let _ = copied_env.update_value_type_by_name(&ident, copied_ty);
        }
    }
    copied_env
}

fn is_simple_variable_pattern(arena: &ParseArena, pat: &ParsedPattern) -> bool {
    match &pat.ppat_desc {
        crate::parser::ast::PatternDesc::Ppat_any
        | crate::parser::ast::PatternDesc::Ppat_var(_) => true,
        crate::parser::ast::PatternDesc::Ppat_alias(inner, _) => {
            is_simple_variable_pattern(arena, arena.get_pat(*inner))
        }
        _ => false,
    }
}

fn parsed_pattern_contains_polymorphic_variant(arena: &ParseArena, pat: &ParsedPattern) -> bool {
    match &pat.ppat_desc {
        crate::parser::ast::PatternDesc::Ppat_variant(_)
        | crate::parser::ast::PatternDesc::Ppat_type(_) => true,
        crate::parser::ast::PatternDesc::Ppat_array(pats)
        | crate::parser::ast::PatternDesc::Ppat_tuple(pats) => {
            arena.pat_list(*pats).iter().any(|pat_idx| {
                parsed_pattern_contains_polymorphic_variant(arena, arena.get_pat(*pat_idx))
            })
        }
        crate::parser::ast::PatternDesc::Ppat_or(p1, p2) => {
            parsed_pattern_contains_polymorphic_variant(arena, arena.get_pat(*p1))
                || parsed_pattern_contains_polymorphic_variant(arena, arena.get_pat(*p2))
        }
        crate::parser::ast::PatternDesc::Ppat_construct(_, args) => {
            arena.pat_list(args.txt).iter().any(|pat_idx| {
                parsed_pattern_contains_polymorphic_variant(arena, arena.get_pat(*pat_idx))
            })
        }
        crate::parser::ast::PatternDesc::Ppat_record(inner) => {
            arena.pat_field_list(inner.0).iter().any(|field| {
                parsed_pattern_contains_polymorphic_variant(arena, arena.get_pat(field.pat))
            })
        }
        crate::parser::ast::PatternDesc::Ppat_dict(entries) => entries.iter().any(|entry| {
            parsed_pattern_contains_polymorphic_variant(arena, arena.get_pat(entry.pdp_pattern))
        }),
        crate::parser::ast::PatternDesc::Ppat_exception(inner)
        | crate::parser::ast::PatternDesc::Ppat_alias(inner, _) => {
            parsed_pattern_contains_polymorphic_variant(arena, arena.get_pat(*inner))
        }
        crate::parser::ast::PatternDesc::Ppat_constraint(inner) => {
            parsed_pattern_contains_polymorphic_variant(arena, arena.get_pat(inner.0))
        }
        crate::parser::ast::PatternDesc::Ppat_any
        | crate::parser::ast::PatternDesc::Ppat_var(_)
        | crate::parser::ast::PatternDesc::Ppat_constant(_)
        | crate::parser::ast::PatternDesc::Ppat_interval(_)
        | crate::parser::ast::PatternDesc::Ppat_variant_spread(_)
        | crate::parser::ast::PatternDesc::Ppat_unpack(_)
        | crate::parser::ast::PatternDesc::Ppat_extension(_) => false,
    }
}

fn type_contains_variant_either(ctx: &TypeContext, ty: TypeExprRef) -> bool {
    let mut worklist = vec![ctx.repr(ty)];
    let mut visited = TypeExprRefSet::new();
    while let Some(current) = worklist.pop() {
        let current = ctx.repr(current);
        if !visited.insert(current) {
            continue;
        }
        if ctx.get_level(current) < crate::types::LOWEST_LEVEL {
            continue;
        }
        let desc = ctx.get_desc(current);
        if let TypeDesc::Tvariant(row) = &*desc {
            let row = crate::types::btype::row_repr(ctx, &ctx.row_desc(row));
            if !row.row_fixed {
                for (_, field) in &row.row_fields {
                    if matches!(
                        crate::types::btype::row_field_repr(ctx, field),
                        crate::types::type_expr::RowField::Reither { .. }
                    ) {
                        return true;
                    }
                }
            }
        }
        crate::types::iter_type_expr(ctx, current, |child| worklist.push(child));
    }
    false
}

/// Match OCaml `instance ~partial:false` behavior in `type_cases` for
/// polymorphic variant pattern instantiation (`erase_either`): when a copied
/// variant row is closed, non-fixed, and still has `Reither` fields, reopen
/// the row and drop those `Reither` fields.
fn instance_for_erase_either_patterns(ctx: &TypeContext, ty: TypeExprRef) -> TypeExprRef {
    crate::types::ctype::instance_partial(ctx, ty, false)
}

/// The scrutinee a list of cases is typed against.
#[derive(Clone, Copy)]
struct CaseScrutinee {
    /// The scrutinee type the patterns unify with.
    ty: TypeExprRef,
    /// The scrutinee type before instantiation, for the exhaustiveness check.
    generic_ty: TypeExprRef,
    /// `type_cases`'s `erase_either`: reopen closed polymorphic-variant
    /// rows of pattern instances.
    erase_either: bool,
}

fn type_case_pattern<'a>(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    case: &'a crate::parser::ast::Case,
    scrutinee: CaseScrutinee,
    lev: i32,
) -> TypeCoreResult<PendingSequentialMatchCase<'a>> {
    let case_has_gadt =
        pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(case.pc_lhs));
    match type_case_pattern_impl(tctx, env, case, scrutinee, false, lev) {
        Ok(case) => Ok(case),
        Err(TypeCoreError::PatternTypeClash { .. }) if !case_has_gadt => {
            type_case_pattern_impl(tctx, env, case, scrutinee, true, lev)
        }
        Err(err) => Err(err),
    }
}

fn type_case_pattern_impl<'a>(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    case: &'a crate::parser::ast::Case,
    scrutinee: CaseScrutinee,
    force_case_local_constraints: bool,
    lev: i32,
) -> TypeCoreResult<PendingSequentialMatchCase<'a>> {
    let CaseScrutinee {
        ty: scrutinee_ty,
        generic_ty: generic_scrutinee_ty,
        erase_either,
    } = scrutinee;
    let mut case_env = env.clone();
    let case_has_gadt =
        pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(case.pc_lhs));
    let needs_case_local_constraints = force_case_local_constraints || case_has_gadt;

    let mut state = PatternState::new();
    state.reset(true);

    // For GADT cases, set the unify state env to a fresh clone of case_env.
    // OCaml passes a per-case `env ref` to unify_gadt; in Rust, we must
    // reset the shared unify_state env so equations from prior cases don't leak.
    // Save old env to restore after propagation.
    let saved_unify_env = if needs_case_local_constraints {
        let saved = tctx
            .unify_state
            .env()
            .cloned();
        tctx.unify_state.set_env(&case_env);
        saved
    } else {
        None
    };
    tctx.type_ctx.begin_def();
    // OCaml compiler/ml/typecore.ml:4430-4433 instances the generic
    // scrutinee type while the propagation begin_def is active. This creates
    // fresh copies at the elevated level (L+1). After typecore.ml:4465-4470
    // closes propagation and generalizes, pattern types become GENERIC,
    // preventing body unification from contaminating pattern types.
    let case_scrutinee_ty = if erase_either {
        instance_for_erase_either_patterns(tctx.type_ctx, scrutinee_ty)
    } else {
        crate::types::instance(tctx.type_ctx, generic_scrutinee_ty)
    };
    // OCaml compiler/ml/typecore.ml:4420-4434: `type_pattern ~lev`, where
    // `lev` is the `init_env` level (typecore.ml:4387-4395), not the raised
    // pattern level.
    let typed_pat_result = type_pattern_with_existentials_at_level(
        tctx,
        &case_env,
        tctx.arena.get_pat(case.pc_lhs),
        case_scrutinee_ty,
        PatternOptions {
            mode: PatternMode::Normal,
            allow_existentials: true,
            level: lev,
        },
        &mut state,
        0,
    );
    tctx.type_ctx.end_def();
    let typed_pat = match typed_pat_result {
        Ok(typed_pat) => typed_pat,
        Err(err) => {
            if let Some(old_env) = saved_unify_env {
                tctx.unify_state.set_env(&old_env);
            }
            return Err(err);
        }
    };
    // `type_pattern` returns the pattern's `env ref` (typecore.ml:1960-1969):
    // the case environment with the existentials, reified abstract types and
    // GADT equations the pattern introduced. Rust's pattern unification
    // extended the unify state's copy of the case environment; it becomes
    // the case environment, then the original unify state env is restored.
    if needs_case_local_constraints {
        if let Some(unify_env) = tctx.unify_state.env() {
            case_env = unify_env.clone();
        }
        // Restore the original unify state env
        if let Some(old_env) = saved_unify_env {
            tctx.unify_state.set_env(&old_env);
        }
    }

    // `type_pattern` extends that environment with the pattern bindings, in
    // the pattern's warning scope, before the caller unifies or generalizes
    // the pattern (typecore.ml:1960-1975, 4831-4863).
    let mut unpacks: Vec<PatternVariable> = Vec::new();
    crate::types::typemod::with_warning_scope(
        tctx,
        tctx.arena,
        &tctx.arena.get_pat(case.pc_lhs).ppat_attributes,
        false,
        |tctx| {
            for pv in &state.pattern_variables {
                add_pattern_variable_value(tctx, &mut case_env, pv);
                if pv.is_module {
                    // OCaml records unpack vars in reverse insertion order
                    // (`module_variables := x :: module_variables`).
                    unpacks.insert(0, pv.clone());
                }
            }
            Ok::<(), TypeCoreError>(())
        },
    )?;
    iter_typed_pattern(&tctx.typed, &typed_pat, &mut |pat| {
        crate::types::generalize(tctx.type_ctx, pat.pat_type);
    });

    let pattern_forces = state.take_globalize_forces();
    Ok(PendingSequentialMatchCase {
        parsed_case: case,
        typed_pat,
        case_env,
        unpacks,
        case_has_gadt,
        pattern_forces,
    })
}

fn type_pending_case_body(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    pending: PendingSequentialMatchCase<'_>,
    body_ty: TypeExprRef,
    body_context: Option<ClashSite>,
) -> TypeCoreResult<crate::types::typedtree::Case> {
    // OCaml compiler/ml/typecore.ml:4473-4505 types guards and bodies only
    // after every pattern in `pat_env_list` has been built.
    // Type check the guard if present.
    let typed_guard = if let Some(guard) = &pending.parsed_case.pc_guard {
        let bool_ty = env.type_bool(tctx.type_ctx);
        let guard_expr = tctx.arena.get_expanded_expr(*guard);
        Some(type_expect_with_module_unpacks(
            tctx,
            &pending.case_env,
            guard_expr,
            bool_ty,
            &pending.unpacks,
            Some(ClashSite::IfCondition),
        )?)
    } else {
        None
    };

    // Type check the body
    let case_body_ty = if pending.case_has_gadt {
        crate::types::ctype::subst_identity_copy(tctx.type_ctx, body_ty)
    } else {
        body_ty
    };
    let body_expr = tctx.arena.get_expanded_expr(pending.parsed_case.pc_rhs);
    let typed_body = type_expect_with_module_unpacks(
        tctx,
        &pending.case_env,
        body_expr,
        case_body_ty,
        &pending.unpacks,
        body_context,
    )?;
    let case_exp_ty = crate::types::instance(tctx.type_ctx, case_body_ty);
    let typed_body = Expression {
        exp_type: case_exp_ty,
        ..typed_body
    };
    Ok(crate::types::typedtree::Case {
        c_lhs: tctx.typed.push_pattern(pending.typed_pat),
        c_guard: typed_guard.map(|e| tctx.push_expr(e)),
        c_rhs: tctx.push_expr(typed_body),
    })
}

/// Type check try expression.
fn type_try(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    sexp: &ParsedExpression,
    body: &ParsedExpression,
    handlers: &[crate::parser::ast::Case],
    finally: Option<&ParsedExpression>,
    expected_ty: TypeExprRef,
) -> TypeCoreResult<Expression> {
    let loc = sexp.pexp_loc;
    let attributes: &[crate::parser::ast::Attribute] = &sexp.pexp_attributes;
    let ctx = tctx.type_ctx;

    // Type check the body with expected type
    let typed_body = type_expect(tctx, env, body, expected_ty, None)?;

    // Type check each handler against exn type.
    // OCaml routes try-catch handlers through type_cases with Predef.type_exn,
    // which includes the propagation cycle (begin_def/end_def/generalize on
    // all pattern types). This ensures as-bound variables (e.g. `| exn as e`)
    // get generalized types so instance() creates fresh copies at use sites.
    let handler_refs: Vec<&crate::parser::ast::Case> = handlers.iter().collect();
    // OCaml compiler/ml/typecore.ml:2657-2661 routes try handlers through
    // type_cases, and typecore.ml:4370-4373 scans all patterns for GADTs before
    // typecore.ml:4420-4434 types any pattern. That scan performs constructor
    // lookup, so qualified exception patterns such as Js.Exn.Error force their
    // module before binders in earlier cases are allocated.
    for case in &handler_refs {
        if pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(case.pc_lhs)) {
            break;
        }
    }
    let exn_ty = crate::types::ctype::instance(ctx, ctx.predef_exn());
    let generic_exn_ty = ctx.predef_exn();
    let typed_handlers = type_match_cases_batch_non_gadt(
        tctx,
        env,
        &handler_refs,
        CaseScrutinee {
            ty: exn_ty,
            generic_ty: generic_exn_ty,
            erase_either: false,
        },
        expected_ty,
        Some(ClashSite::TryReturn),
    )?;
    finish_non_gadt_type_cases(
        tctx,
        env,
        loc,
        expected_ty,
        exn_ty,
        &handler_refs,
        &typed_handlers,
    )?;

    // JavaScript runs the finally block after the body or catch has already
    // decided how the try is left, so a break or continue there would cancel
    // a pending exception or result (typecore.ml Pexp_try). A finally block
    // that always throws ends the try with no code after it, so it gets no
    // nonreturning-statement warning.
    let typed_finally = match finally {
        Some(finally) => Some(Box::new(with_control_flow_boundary(tctx, true, |tctx| {
            type_statement_with(tctx, env, finally, NonreturningWarning::Skip)
        })?)),
        None => None,
    };

    // Keep sharing: use typed_body.exp_type instead of expected_ty
    // (matches OCaml: exp_type = body.exp_type)
    let result_ty = typed_body.exp_type;
    let node = Expression::new(
        ExpressionDesc::Texp_try(tctx.push_expr(typed_body), tctx.typed.push_cases(typed_handlers), typed_finally.map(|e| tctx.push_expr(*e))),
        loc, result_ty, tctx.type_ctx.store_typed_env(env),
    );
    Ok(tctx.typed.with_exp_attributes(node, attributes.to_vec().into()))
}

fn desugar_nary_function_defaults(
    arena: &mut crate::parse_arena::ParseArena,
    loc: LocIdx,
    params: &[crate::parser::ast::FunParam],
) -> Vec<(
    crate::parser::ast::FunParam,
    Option<crate::parser::ast::ValueBinding>,
)> {
    use crate::parser::ast::{ExpressionDesc as ED, PatternDesc as PD};

    params
        .iter()
        .map(|param| {
            let Some(default_idx) = param.p_default else {
                return (param.clone(), None);
            };
            let crate::parser::ast::ArgLabel::Optional(label) = param.p_lbl else {
                unreachable!("defaults are only valid on optional parameters");
            };
            let default_loc = arena.get_expanded_expr(default_idx).pexp_loc;
            let source_pat_loc = arena.get_pat(param.p_pat).ppat_loc;
            let sloc_start = arena.loc_start_idx(source_pat_loc);
            let sloc_end = arena.loc_end_idx(default_loc);
            // typecore.ml:3567-3573: from the pattern's start to the
            // default's end, ghost.
            let sloc = arena.push_loc(sloc_start, sloc_end, true);

            let label_name = arena.get_string(label.txt).to_owned();
            // typecore.ml:3550-3582 names the synthesized binders with `mknoloc`.
            let noloc = arena.none_loc();
            let opt_name = arena.intern_string(&format!("*opt_{label_name}*"));
            let opt_lid = arena.push_longident(Longident::Lident(opt_name));
            let sth_name = arena.intern_string("*sth*");
            let sth_lid = arena.push_longident(Longident::Lident(sth_name));
            let matched_pat = arena.push_pat(ParsedPattern {
                // typecore.ml:3558 `Pat.var ~loc:default_loc (mknoloc "*sth*")`.
                ppat_desc: PD::Ppat_var(Located {
                    txt: sth_name,
                    loc: noloc,
                }),
                ppat_loc: default_loc,
                ppat_attributes: Attributes::new(),
            });
            let some_pat = arena.push_pat(ParsedPattern {
                ppat_desc: PD::Ppat_construct(
                    Located {
                        txt: arena.predef_some_lid(),
                        loc: noloc,
                    },
                    arena.shared_pat_ctor_args(&[matched_pat], default_loc),
                ),
                ppat_loc: default_loc,
                ppat_attributes: Attributes::new(),
            });
            let none_pat = arena.push_pat(ParsedPattern {
                ppat_desc: PD::Ppat_construct(
                    Located {
                        txt: arena.predef_none_lid(),
                        loc: noloc,
                    },
                    crate::parse_arena::Located::new(
                        crate::parse_arena::PatList::EMPTY,
                        default_loc,
                    ),
                ),
                ppat_loc: default_loc,
                ppat_attributes: Attributes::new(),
            });
            let some_rhs = arena.push_expr(ParsedExpression {
                pexp_desc: ED::Pexp_ident(Located {
                    txt: sth_lid,
                    loc: noloc,
                }),
                pexp_loc: default_loc,
                pexp_attributes: Attributes::new(),
            });
            let scrutinee = arena.push_expr(ParsedExpression {
                pexp_desc: ED::Pexp_ident(Located {
                    txt: opt_lid,
                    loc: noloc,
                }),
                pexp_loc: loc,
                pexp_attributes: Attributes::new(),
            });
            let match_expr = arena.push_expr(ParsedExpression {
                pexp_desc: ED::Pexp_match((
                    scrutinee,
                    arena.push_shared_case_list(&[
                        crate::parser::ast::Case {
                            pc_bar: None,
                            pc_lhs: some_pat,
                            pc_guard: None,
                            pc_rhs: some_rhs,
                        },
                        crate::parser::ast::Case {
                            pc_bar: None,
                            pc_lhs: none_pat,
                            pc_guard: None,
                            pc_rhs: default_idx,
                        },
                    ]),
                )),
                pexp_loc: sloc,
                pexp_attributes: Attributes::new(),
            });
            let rewritten = crate::parser::ast::FunParam {
                p_attrs: param.p_attrs.clone(),
                p_lbl: param.p_lbl,
                p_default: None,
                p_pat: arena.push_pat(ParsedPattern {
                    // typecore.ml:3582 `Pat.var ~loc:sloc (mknoloc opt_name)`.
                    ppat_desc: PD::Ppat_var(Located {
                        txt: opt_name,
                        loc: noloc,
                    }),
                    ppat_loc: sloc,
                    ppat_attributes: Attributes::new(),
                }),
            };
            (
                rewritten,
                Some(crate::parser::ast::ValueBinding {
                    pvb_pat: param.p_pat,
                    pvb_expr: match_expr,
                    pvb_jsx_component: None,
                    pvb_attributes: Attributes::new(),
                    pvb_loc: arena.none_loc(),
                }),
            )
        })
        .collect()
}

/// Prepare OCaml-shaped synthetic AST while the parse arena is exclusively borrowed.
///
/// Type checking only receives a shared arena reference, so every rewrite whose
/// shape is already known is allocated here. Environment-dependent pattern
/// rewrites use the arena's stable append-only synthetic storage.
pub fn prepare_typecheck_arena(arena: &mut ParseArena) {
    // `wrap_unpacks` may attach this internal attribute after environment-driven
    // first-class-module discovery. Its spelling is known up front, so intern it
    // while the arena is still exclusively borrowed.
    arena.intern_string("#modulepat");

    let functions = arena.nary_functions();
    for (fun, loc) in functions {
        if arena.nary_fun_default_bindings(&fun).is_some() {
            continue;
        }
        let params = arena.nary_fun_params(&fun).into_owned();
        let bindings = desugar_nary_function_defaults(arena, loc, &params);
        arena.set_nary_fun_default_bindings(fun.lhs, bindings);
    }
    // Optional-default AST is allocated above while the arena is exclusive.
    // Prepare stable append-only storage afterward for environment-dependent
    // pattern rewrites performed during type checking (for example variants).
    arena.reserve_typecheck_synthetic_capacity();
}

/// Type an n-ary function with its locally abstract types in scope.
///
/// This follows `compiler/ml/typecore.ml:2468-2487`: each newtype installs a
/// fresh abstract constructor while the remainder is typed, then replaces that
/// constructor in the copied result type. The caller's expectation is unified
/// only after all newtype scopes have been peeled.
#[allow(clippy::too_many_arguments)]
fn type_function_nary_with_newtypes(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    newtypes: &[(
        crate::parser::ast::StringLoc,
        crate::parser::ast::Attributes,
    )],
    params_bindings: &[(
        crate::parser::ast::FunParam,
        Option<crate::parser::ast::ValueBinding>,
    )],
    body: crate::parse_arena::ExprIdx,
    is_async: bool,
    expected_ty: TypeExprRef,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    #[allow(clippy::too_many_arguments)]
    fn peel(
        tctx: &mut TypeCheckContext<'_>,
        env: &Env,
        loc: LocIdx,
        newtypes: &[(
            crate::parser::ast::StringLoc,
            crate::parser::ast::Attributes,
        )],
        params_bindings: &[(
            crate::parser::ast::FunParam,
            Option<crate::parser::ast::ValueBinding>,
        )],
        body: crate::parse_arena::ExprIdx,
        is_async: bool,
        attributes: &[crate::parser::ast::Attribute],
    ) -> TypeCoreResult<Expression> {
        let Some(((name, newtype_attributes), rest)) = newtypes.split_first() else {
            let fresh_expectation = tctx.type_ctx.new_var(None);
            return type_function_nary(
                tctx,
                env,
                loc,
                params_bindings,
                body,
                is_async,
                fresh_expectation,
                attributes,
            );
        };

        let arena = tctx.arena;
        crate::types::typemod::with_warning_scope(tctx, arena, newtype_attributes, false, |tctx| {
            let ctx = tctx.type_ctx;
            let name_str = tctx.arena.get_string(name.txt).to_string();
            let replacement_ty = ctx.new_var(None);
            ctx.begin_def();
            let result = (|| -> TypeCoreResult<Expression> {
                let level = ctx.current_level();
                let mut new_env = env.clone();
                ctx.set_current_time(ctx.get_level(replacement_ty));
                let newtype_id = ctx.create_ident(&name_str);
                new_env.add_type(
                    newtype_id,
                    crate::types::decl::TypeDeclaration {
                        type_params: vec![],
                        type_arity: 0,
                        type_kind: crate::types::decl::TypeKind::TypeAbstract,
                        type_private: crate::types::asttypes::PrivateFlag::Public,
                        type_manifest: None,
                        type_variance: vec![],
                        type_newtype_level: Some((level, level)),
                        type_loc: tctx.intern_ast_loc(tctx.arena, loc),
                        type_attributes: vec![],
                        type_immediate: false,
                        type_representation: crate::types::decl::TypeRepresentation::Boxed,
                        type_shape: crate::types::ValueShape::Unstated,
                        type_inlined_types: vec![],
                        type_path: None,
                    },
                );
                // `Env.enter_type` registers the unused-type check (env.ml:1593-1597,
                // 1562-1572); lookups of the type mark it used.
                tctx.check_type_usage(&name_str, convert_loc(loc, tctx.arena), loc);
                ctx.init_def(ctx.current_stamp());

                let typed_body = peel(
                    tctx,
                    &new_env,
                    loc,
                    rest,
                    params_bindings,
                    body,
                    is_async,
                    attributes,
                )?;
                let rewritten_ty =
                    crate::types::ctype::subst_identity_copy(ctx, typed_body.exp_type);

                fn replace_newtype_path(
                    ctx: &TypeContext,
                    ty: TypeExprRef,
                    target_id: &Ident,
                    replacement_ty: TypeExprRef,
                    seen: &mut HashSet<TypeExprRef>,
                    used: &mut bool,
                ) {
                    let ty = ctx.repr(ty);
                    if !seen.insert(ty) {
                        return;
                    }
                    if matches!(
                        &*ctx.get_desc(ty),
                        TypeDesc::Tconstr { path, .. }
                            if path.as_pident().is_some_and(|id| id.same(target_id))
                    ) {
                        *used = true;
                        crate::types::link_type(ctx, ty, replacement_ty);
                        return;
                    }
                    crate::types::iter_type_expr(ctx, ty, |child| {
                        replace_newtype_path(ctx, child, target_id, replacement_ty, seen, used);
                    });
                }

                let mut seen = HashSet::new();
                let mut used = false;
                replace_newtype_path(
                    ctx,
                    rewritten_ty,
                    &newtype_id,
                    replacement_ty,
                    &mut seen,
                    &mut used,
                );
                Ok(Expression {
                    exp_loc: loc,
                    exp_type: rewritten_ty,
                    ..typed_body
                })
            })();
            ctx.end_def();
            result
        })
    }

    let typed = peel(
        tctx,
        env,
        loc,
        newtypes,
        params_bindings,
        body,
        is_async,
        attributes,
    )?;
    rue_unify(tctx, loc, typed.exp_type, expected_ty, None)?;
    Ok(typed)
}

/// Type an n-ary function in one pass, matching typecore.ml:3590-3823.
///
/// Defaults need the adjacent typed-let flow and currently continue through the
/// single-parameter fallback below; ordinary n-ary parameters take this direct
/// path so patterns are entered left-to-right and the body is typed exactly once.
#[allow(clippy::too_many_arguments)]
fn type_function_nary(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    params_bindings: &[(
        crate::parser::ast::FunParam,
        Option<crate::parser::ast::ValueBinding>,
    )],
    body: crate::parse_arena::ExprIdx,
    is_async: bool,
    expected_ty: TypeExprRef,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    use crate::types::typedtree::{FunctionParam, Partial};

    let params = params_bindings
        .iter()
        .map(|(param, _)| param)
        .collect::<Vec<_>>();
    let ctx = tctx.type_ctx;
    let labels = params
        .iter()
        .map(|param| convert_arg_label_for_ctx(&param.p_lbl, tctx.arena, tctx.type_ctx))
        .collect::<Vec<_>>();

    // compiler/ml/typecore.ml:3594-3613 checks labels against an existing
    // expected arrow before committing the source function shape. This keeps
    // label mismatches on the dedicated Abstract_wrong_label diagnostic path.
    let expanded_expected = crate::types::ctype::expand_head(ctx, env, expected_ty);
    let expected_arrow = match &*ctx.get_desc(expanded_expected) {
        TypeDesc::Tarrow { args, ret } if args.len() == labels.len() => Some((*args, *ret)),
        _ => None,
    };
    if let Some((expected_args, expected_ret)) = expected_arrow {
        for (index, (param, label)) in params.iter().zip(&labels).enumerate() {
            if !crate::types::type_expr::TypeArgLabel::new(label)
                .same_label(ctx.type_args(expected_args).at(index).label())
            {
                let remainder = ctx.new_type(TypeDesc::Tarrow {
                    args: ctx.new_type_args(
                        &ctx.type_args(expected_args).slice(index..).to_smallvec::<4>(),
                    ),
                    ret: expected_ret,
                });
                let param_loc = tctx.arena.get_pat(param.p_pat).ppat_loc;
                let mut error_loc = tctx.arena.to_location(loc);
                error_loc.loc_start = tctx.arena.to_location(param_loc).loc_start;
                return Err(TypeCoreError::AbstractWrongLabel {
                    loc: error_loc,
                    label: label.clone(),
                    ty: remainder,
                });
            }
        }
    }

    let fun_args = labels
        .iter()
        .cloned()
        .map(|label| TypeArg::new(label, ctx.new_var(None)))
        .collect::<Vec<_>>();
    let fun_ret = ctx.new_var(None);
    let fun_ty = ctx.new_type(TypeDesc::Tarrow {
        args: ctx.new_type_args(&fun_args),
        ret: fun_ret,
    });
    unify_expression_types(tctx, loc, fun_ty, expected_ty, None)?;

    // typecore.ml:3954-3974: with local constraints in scope, the parameter
    // and result types are taken at a raised level and their structure
    // generalized.
    let separate = env.has_local_constraints();
    if separate {
        ctx.begin_def();
    }
    let inst = crate::types::instance(ctx, fun_ty);
    let expanded = crate::types::ctype::expand_head_unif(ctx, env, inst);
    let (mut parameter_types, result_type) = {
        let desc = ctx.get_desc(expanded);
        match &*desc {
            TypeDesc::Tarrow { args, ret } => (
                ctx.type_args(args)
                    .iter()
                    .map(|arg| arg.typ)
                    .collect::<Vec<_>>(),
                *ret,
            ),
            _ => unreachable!("fresh function type did not remain an arrow"),
        }
    };
    for (param, typ) in params.iter().zip(parameter_types.iter_mut()) {
        if param.p_lbl.is_optional() {
            let inner = ctx.new_var(None);
            let option_for_unify = env.type_option(ctx, inner);
            unify_expression_types(tctx, loc, *typ, option_for_unify, None)?;
            *typ = env.type_option(ctx, inner);
        }
    }
    if separate {
        ctx.end_def();
        for &typ in &parameter_types {
            crate::types::generalize_structure(ctx, ctx.current_level(), typ);
        }
        crate::types::generalize_structure(ctx, ctx.current_level(), result_type);
    }

    // typecore.ml:3978-4013: what `type_cases` does for one pattern without
    // a guard, with GADT patterns correcting levels, duplicating the types
    // of the identifiers the body uses, and raising the level for
    // existentials before any parameter is typed.
    let contains_polyvars = params.iter().any(|source| {
        parsed_pattern_contains_polymorphic_variant(tctx.arena, tctx.arena.get_pat(source.p_pat))
    });
    let has_gadts = params.iter().any(|source| {
        pattern_contains_generalized_constructor(tctx, env, tctx.arena.get_pat(source.p_pat))
    });
    let duplicated_env;
    let (result_type, env) = if has_gadts {
        let synth_cases = params
            .iter()
            .map(|source| crate::parser::ast::Case {
                pc_bar: None,
                pc_lhs: source.p_pat,
                pc_guard: None,
                pc_rhs: body,
            })
            .collect::<Vec<_>>();
        let synth_case_refs = synth_cases.iter().collect::<Vec<_>>();
        duplicated_env = duplicate_ident_types_for_gadt_cases(tctx, env, &synth_case_refs);
        (
            crate::types::ctype::subst_identity_copy(ctx, result_type),
            &duplicated_env,
        )
    } else {
        (result_type, env)
    };
    // `init_env` (typecore.ml:4003-4010).
    fn init_env(ctx: &TypeContext, env: &Env) -> (i32, Env) {
        ctx.begin_def();
        ctx.set_current_time(ctx.current_level());
        let lev = ctx.current_stamp();
        ctx.init_def(lev + 1000);
        let mut env = env.clone();
        env.add_gadt_instance_level();
        (lev, env)
    }
    let gadt_env;
    let (lev, env) = if has_gadts {
        let (lev, scoped) = init_env(ctx, env);
        gadt_env = scoped;
        (lev, &gadt_env)
    } else {
        (ctx.current_level(), env)
    };

    let mut body_env = env.clone();
    let mut typed_patterns = Vec::with_capacity(params.len());
    let mut unpacks = Vec::new();
    let mut default_lets = Vec::new();
    // typecore.ml `with_reset_control_flow`: a function body starts without
    // enclosing loops, outside any finally block.
    let saved_loop_depth = tctx.loop_depth;
    let saved_in_finally = tctx.in_finally;
    tctx.loop_depth = 0;
    tctx.in_finally = false;
    for ((param, default_binding), typ) in
        params_bindings.iter().zip(parameter_types.iter().copied())
    {
        // typecore.ml:4019-4049.
        let parsed_pattern = tctx.arena.get_pat(param.p_pat);
        let erase_either = parsed_pattern_contains_polymorphic_variant(tctx.arena, parsed_pattern)
            && type_contains_variant_either(ctx, typ);
        let ty_arg_c = if has_gadts || erase_either {
            crate::types::ctype::subst_identity_copy(ctx, typ)
        } else {
            typ
        };
        let simple = is_simple_variable_pattern(tctx.arena, parsed_pattern);
        let propagate = has_gadts
            || ctx.get_level(ctx.repr(ty_arg_c)) == crate::types::GENERIC_LEVEL
            || !simple;
        if propagate {
            ctx.begin_def();
        }
        let mut state = PatternState::new();
        state.reset(true);
        let ty_arg_i = if erase_either {
            instance_for_erase_either_patterns(ctx, ty_arg_c)
        } else {
            crate::types::instance(ctx, ty_arg_c)
        };
        // `type_pattern ~lev env spat ty_arg_i` returns the pattern's
        // environment with the GADT equations it introduced; Rust's GADT
        // unification records them in the unify state's environment.
        if has_gadts {
            tctx.unify_state.set_env(&body_env);
        }
        let typed = type_pattern_with_existentials_at_level(
            tctx,
            &body_env,
            parsed_pattern,
            ty_arg_i,
            PatternOptions {
                mode: PatternMode::Normal,
                allow_existentials: true,
                level: lev,
            },
            &mut state,
            0,
        );
        // The pattern's `env ref` (typecore.ml:1960-1969), extended in the
        // unify state's copy of the parameter environment.
        if has_gadts && let Some(unify_env) = tctx.unify_state.env() {
            body_env = unify_env.clone();
        }
        let mut typed = match typed {
            Ok(typed) => typed,
            Err(err) => {
                if propagate {
                    ctx.end_def();
                }
                return Err(err);
            }
        };
        // `type_pattern` adds the pattern variables to that environment, in
        // the pattern's warning scope, before `type_params` unifies, forces
        // or generalizes the pattern (typecore.ml:1960-1975, 4050-4063):
        // `ext_env` already binds them.
        let registered: TypeCoreResult<()> = if state.pattern_variables.is_empty() {
            Ok(())
        } else {
            let mut next_env = body_env.clone();
            // `unpacks_acc @ unpacks` (typecore.ml:4119), where a parameter's
            // `unpacks` are its `module_variables`, latest first.
            let mut param_unpacks = Vec::new();
            let registered = crate::types::typemod::with_warning_scope(
                tctx,
                tctx.arena,
                &parsed_pattern.ppat_attributes,
                false,
                |tctx| {
                    for variable in &state.pattern_variables {
                        add_pattern_variable_value(tctx, &mut next_env, variable);
                        if variable.is_module {
                            param_unpacks.insert(0, variable.clone());
                        }
                    }
                    Ok::<(), TypeCoreError>(())
                },
            );
            unpacks.extend(param_unpacks);
            body_env = next_env;
            registered
        };
        if let Err(err) = registered {
            if propagate {
                ctx.end_def();
            }
            return Err(err);
        }
        let result: TypeCoreResult<()> = (|| {
            // `unify_pat ext_env pat ty_arg'` (typecore.ml:4038-4039).
            tctx.set_unify_env(&body_env);
            unify_pattern_types(tctx, typed.pat_loc, typed.pat_type, ctx.new_var(None))?;
            // typecore.ml:4040-4042.
            if typed_pattern_has_variant(&tctx.typed, &typed) {
                parmatch_pressure_variants(tctx, env, &[&typed]);
                finalize_variant_in_pattern(tctx, env, &typed, false);
            }
            // typecore.ml:4043: `List.iter (fun f -> f ()) !pattern_force`.
            run_globalize_forces(tctx, state.take_globalize_forces())?;
            if propagate || erase_either {
                tctx.set_unify_env(&body_env);
                let parameter_instance = crate::types::instance(ctx, ty_arg_c);
                unify_pattern_types(tctx, typed.pat_loc, typed.pat_type, parameter_instance)?;
            }
            Ok(())
        })();
        if let Err(err) = result {
            if propagate {
                ctx.end_def();
            }
            return Err(err);
        }
        if propagate {
            // typecore.ml:4046-4049.
            tctx.set_unify_env(env);
            let mut pattern_types = Vec::new();
            iter_typed_pattern(&tctx.typed, &typed, &mut |pat| pattern_types.push(pat.pat_type));
            for pattern_type in pattern_types {
                let fresh = ctx.new_var(None);
                if let Err(err) =
                    crate::types::ctype::unify_var(ctx, &mut tctx.unify_state, pattern_type, fresh)
                {
                    ctx.end_def();
                    let trace = match err {
                        TypeError::Unify(trace) if !trace.is_empty() => trace,
                        _ => vec![(pattern_type, fresh)],
                    };
                    return Err(TypeCoreError::PatternTypeClash {
                        loc: Some(typed.pat_loc),
                        trace,
                        env: Some(ctx.store_typed_env(env)),
                    });
                }
            }
            ctx.end_def();
            iter_typed_pattern(&tctx.typed, &typed, &mut |pat| {
                crate::types::generalize(ctx, pat.pat_type)
            });
        }
        let mut opt_param = None;
        if let Some(default_binding) = default_binding {
            let let_env = body_env.clone();
            // typecore.ml:4078-4080: `type_let ~optional_default:true`.
            let (typed_bindings, next_env, let_unpacks) = type_let_bindings(
                tctx,
                &body_env,
                RecFlag::Nonrecursive,
                std::slice::from_ref(default_binding),
                true,
                LetCheck::FakeOptional,
            )?;
            body_env = next_env;
            unpacks.extend(let_unpacks);
            // typecore.ml:3731-3795: the pattern binds the option carrier
            // under the unspellable `*opt_<label>*`; replace it with a fresh
            // `<label>Opt` ident at its binder and at its single use, the
            // scrutinee of the synthetic match.
            let crate::parser::ast::ArgLabel::Optional(label) = param.p_lbl else {
                unreachable!("defaults are only valid on optional parameters");
            };
            let param_id = ctx.create_ident(format!("{}Opt", tctx.arena.get_string(label.txt)));
            match &mut typed.pat_desc {
                PatternDesc::Tpat_var(id, name) => {
                    *id = param_id;
                    name.txt = param_id.name().to_string();
                }
                _ => unreachable!("an optional default's carrier is a variable pattern"),
            }
            let mut typed_bindings = typed_bindings;
            match typed_bindings.as_mut_slice() {
                [vb] => match tctx.typed.expr(vb.vb_expr).exp_desc {
                    ExpressionDesc::Texp_match(scrut, _, _, _) => {
                        match &mut tctx.typed.expr_mut(scrut).exp_desc {
                            ExpressionDesc::Texp_ident(path, _, _) => {
                                *path = Path::pident(param_id);
                            }
                            _ => unreachable!("an optional default's scrutinee is its carrier"),
                        }
                    }
                    _ => unreachable!("an optional default binds a match"),
                },
                _ => unreachable!("an optional default is a single binding"),
            }
            default_lets.push((typed_bindings, let_env));
            opt_param = Some(param_id);
        }
        typed_patterns.push((typed, opt_param, ty_arg_c));
    }

    // typecore.ml:4125-4135: the body, typed against a corrected copy of the
    // result type when a parameter has a GADT pattern.
    let body_result_type = if has_gadts {
        crate::types::ctype::subst_identity_copy(ctx, result_type)
    } else {
        result_type
    };
    let async_body = if is_async {
        let pattern = tctx.arena.get_pat(params[0].p_pat);
        let loc = match &pattern.ppat_desc {
            crate::parser::ast::PatternDesc::Ppat_var(name) => name.loc,
            _ => pattern.ppat_loc,
        };
        Some((body, loc))
    } else {
        None
    };
    let typed_body = type_body_with_module_unpacks(
        tctx, &body_env, tctx.arena.get_expanded_expr(body),
        body_result_type, &unpacks, None, async_body,
    )?;
    let mut typed_body = Expression {
        exp_type: crate::types::instance(ctx, body_result_type),
        ..typed_body
    };
    if has_gadts {
        // typecore.ml:4136-4138.
        let shared_result = crate::types::instance(ctx, result_type);
        tctx.set_unify_env(env);
        unify_expression_types(
            tctx,
            typed_body.exp_loc,
            typed_body.exp_type,
            shared_result,
            None,
        )?;
    }
    for (typed_bindings, _let_env) in default_lets.into_iter().rev() {
        let body_type = typed_body.exp_type;
        typed_body = Expression::new(
            ExpressionDesc::Texp_let(
                RecFlag::Nonrecursive,
                tctx.typed.push_value_bindings(typed_bindings),
                tctx.push_expr(typed_body),
            ),
            loc,
            body_type,
            EnvRef(0),
        );
    }

    fn parameter_ident(ta: &TypedArena, ctx: &TypeContext, pat: &Pattern) -> Option<Ident> {
        match &pat.pat_desc {
            PatternDesc::Tpat_var(id, _) | PatternDesc::Tpat_alias(_, id, _) => Some(*id),
            PatternDesc::Tpat_construct(_, _, args) if args.len() == 1 => {
                parameter_ident(ta, ctx, ta.pattern(ta.pattern_list(*args)[0]))
                    .map(|id| ctx.rename_ident(&id))
            }
            _ => None,
        }
    }

    // typecore.ml:4160-4198.
    let needs_exhaust_check = params
        .iter()
        .any(|source| !is_simple_variable_pattern(tctx.arena, tctx.arena.get_pat(source.p_pat)));
    let do_init = has_gadts || needs_exhaust_check;
    let check_env;
    let (check_level, env) = if do_init && !has_gadts {
        let (lev, scoped) = init_env(ctx, env);
        check_env = scoped;
        (lev, &check_env)
    } else {
        (lev, env)
    };
    let mut typed_params = Vec::with_capacity(params.len());
    for ((source, (typed, opt_param, ty_arg_c)), label) in
        params.iter().zip(typed_patterns).zip(labels.iter())
    {
        let typed = tctx.typed.push_pattern(typed);
        let partial = if is_simple_variable_pattern(tctx.arena, tctx.arena.get_pat(source.p_pat)) {
            Partial::Total
        } else {
            let ty_arg_check = if do_init {
                crate::types::ctype::subst_for_saving_copy(ctx, ty_arg_c)
            } else {
                ty_arg_c
            };
            // The checks read only the pattern side of the case.
            let partial = parmatch_check_partial(
                tctx,
                env,
                check_level,
                None,
                ty_arg_check,
                loc,
                &[PatCase {
                    lhs: typed,
                    guarded: false,
                }],
            );
            report_unused_match_pattern(
                tctx,
                env,
                typed,
                do_init || contains_polyvars,
                check_level,
                ty_arg_check,
            );
            partial
        };
        let fp_has_default = opt_param.is_some();
        let fp_param = match opt_param {
            Some(id) => id,
            None => parameter_ident(&tctx.typed, ctx, tctx.typed.pattern(typed))
                .unwrap_or_else(|| ctx.create_ident("param")),
        };
        typed_params.push(FunctionParam {
            fp_lbl: label.clone(),
            fp_param,
            fp_pat: typed,
            fp_partial: partial,
            fp_has_default,
        });
    }

    if do_init {
        // Ensure that existential types do not escape (typecore.ml:4195-4198).
        ctx.end_def();
        let result_instance = crate::types::instance(ctx, result_type);
        tctx.set_unify_env(env);
        unify_expression_types(tctx, loc, result_instance, ctx.new_var(None), None)?;
    }

    let exp_type = crate::types::instance(
        ctx,
        ctx.new_generic_type(TypeDesc::Tarrow {
            args: ctx.new_type_args_from(
                labels
                    .into_iter()
                    .zip(parameter_types)
                    .map(|(label, typ)| TypeArg::new(label, typ)),
            ),
            ret: result_type,
        }),
    );
    tctx.loop_depth = saved_loop_depth;
    tctx.in_finally = saved_in_finally;
    let node = Expression::new(
        ExpressionDesc::Texp_function {
            params: tctx.typed.push_function_params(typed_params),
            body: tctx.push_expr(typed_body),
            async_: is_async,
        },
        loc,
        exp_type,
        EnvRef(0),
    );
    Ok(tctx.typed.with_exp_attributes(node, attributes.to_vec().into()))
}

/// The payload of `Pexp_for`: index pattern, bounds, direction and body.
type ForLoop = (
    crate::parse_arena::PatIdx,
    crate::parse_arena::ExprIdx,
    crate::parse_arena::ExprIdx,
    crate::parser::ast::DirectionFlag,
    crate::parse_arena::ExprIdx,
);

fn type_for(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    sexp: &ParsedExpression,
    for_loop: &ForLoop,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    let loc = sexp.pexp_loc;
    let attributes: &[crate::parser::ast::Attribute] = &sexp.pexp_attributes;
    let arena = tctx.arena;
    let (pat, start_expr, end_expr, direction, body) = *for_loop;
    let pat = arena.get_pat(pat);
    let start_expr = arena.get_expanded_expr(start_expr);
    let end_expr = arena.get_expanded_expr(end_expr);
    let body = arena.get_expanded_expr(body);
    let ctx = tctx.type_ctx;
    // OCaml passes Predef.type_int (generic singleton) to type_expect for each bound.
    // Inside type_expect, `rue` calls instance(ty_expected) — creating a FRESH copy
    // for each expression. Match this by creating separate int types per bound.
    let start_int_ty = env.type_int(ctx);
    let end_int_ty = env.type_int(ctx);

    // Type check bounds with separate expected types
    let typed_start = type_expect(
        tctx,
        env,
        start_expr,
        start_int_ty,
        Some(ClashSite::ForLoopCondition),
    )?;
    let typed_end = type_expect(
        tctx,
        env,
        end_expr,
        end_int_ty,
        Some(ClashSite::ForLoopCondition),
    )?;

    // OCaml only accepts `_` or a variable for `for` loop indices.
    if !matches!(
        &pat.ppat_desc,
        crate::parser::ast::PatternDesc::Ppat_any | crate::parser::ast::PatternDesc::Ppat_var(_)
    ) {
        return Err(TypeCoreError::InvalidForLoopIndex { loc: pat.ppat_loc });
    }

    // Type check pattern with a fresh int type (separate from loop bounds),
    // matching OCaml where loop bounds and loop variable don't share the same node.
    let loop_index_ty = env.type_int(ctx);
    let mut state = PatternState::new();
    let typed_pat = type_pattern(
        tctx,
        env,
        pat,
        loop_index_ty,
        PatternMode::Normal,
        &mut state,
    )?;

    // The loop variable
    let loop_var_id = match &pat.ppat_desc {
        crate::parser::ast::PatternDesc::Ppat_any => {
            if !state.pattern_variables.is_empty() {
                return Err(TypeCoreError::InvalidForLoopIndex { loc: pat.ppat_loc });
            }
            ctx.create_ident("_for")
        }
        crate::parser::ast::PatternDesc::Ppat_var(_) if state.pattern_variables.len() == 1 => {
            state.pattern_variables[0].id
        }
        _ => return Err(TypeCoreError::InvalidForLoopIndex { loc: pat.ppat_loc }),
    };

    // Extend environment with loop variable
    // Match OCaml add_pattern_variables: `_` keeps the original env.
    let mut body_env = env.clone();
    for pv in &state.pattern_variables {
        let val_loc = tctx.arena.to_location(loc);
        let desc = ValueDescription {
            val_type: pv.ty,
            val_kind: crate::types::ValueKind::ValReg,
            // Match OCaml `type_for`: for-index value descriptions use the
            // enclosing `for` expression location.
            val_loc: tctx.intern_ast_loc(tctx.arena, loc),
            val_attributes: Default::default(),
            val_path: None,
        };
        body_env.add_value(pv.id, desc);
        let name = pv.id.name();
        tctx.add_value_usage_check(
            name,
            val_loc,
            loc,
            Warning::UnusedForIndex {
                name: name.to_string(),
            },
        );
    }

    // OCaml uses type_statement for for-loop bodies and instance_def(type_unit)
    // for the loop expression result.
    let typed_body = with_loop_depth(tctx, |tctx| type_statement(tctx, &body_env, body))?;

    // OCaml typecore.ml:3117-3126: `rue { ... exp_type = instance_def
    // Predef.type_unit }`, i.e. `unify env unit (instance ty_expected)`.
    let result_unit_ty = env.type_unit(ctx);
    rue_unify(tctx, loc, result_unit_ty, expected_ty, context)?;

    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_for(
                loop_var_id,
                tctx.typed.push_pattern(typed_pat),
                tctx.push_expr(typed_start),
                tctx.push_expr(typed_end),
                direction,
                tctx.push_expr(typed_body),
            ),
            loc,
            result_unit_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

/// Type check a `for ... of` / `for await ... of` loop. Mirrors
/// `compiler/ml/typecore.ml` (#7887): types the iterable against
/// `iterable<'a>` (or `array<'a>` as a fallback) for plain for-of, or
/// `asyncIterable<'a>` for the await form. The loop var is bound to the
/// element type in the body env. The whole expression has type `unit`.
#[allow(clippy::too_many_arguments)]
/// typecore.ml `unify_exp_types_through_private`: like `unify_exp_types`, but
/// a private abbreviation such as `Generator.t` also unifies through its
/// expansion, as an explicit `:>` would. A failure reports the type as
/// written: the first unification's error.
fn unify_through_private(
    ctx: &TypeContext,
    env: &Env,
    ty: TypeExprRef,
    expected_ty: TypeExprRef,
) -> Result<(), TypeError> {
    let unify = |ty| {
        let mut state = UnifyState::new();
        state.set_env(env);
        crate::types::ctype::unify(ctx, &mut state, ty, expected_ty)
    };
    let snapshot = ctx.snapshot_type_state();
    let error = match unify(ty) {
        Ok(()) => return Ok(()),
        Err(error) => error,
    };
    ctx.restore_type_state(snapshot);
    // Restoring returned to the state before the first attempt; a new
    // snapshot here is the same point OCaml's `restore` backtracks to.
    let snapshot = ctx.snapshot_type_state();
    let expanded = crate::types::ctype::expand_head_opt(ctx, env, ty);
    if ctx.repr(expanded) == ctx.repr(crate::types::ctype::expand_head(ctx, env, ty)) {
        return Err(error);
    }
    match unify(expanded) {
        Ok(()) => Ok(()),
        Err(_) => {
            ctx.restore_type_state(snapshot);
            Err(error)
        }
    }
}

/// The payload of `Pexp_for_of` and `Pexp_for_await_of`: binding pattern,
/// iterable and body.
type ForOfLoop = (
    crate::parse_arena::PatIdx,
    crate::parse_arena::ExprIdx,
    crate::parse_arena::ExprIdx,
);

/// Type check a `for ... of` loop, or a `for await ... of` loop.
fn type_for_of(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    sexp: &ParsedExpression,
    for_of: &ForOfLoop,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    let loc = sexp.pexp_loc;
    let attributes: &[crate::parser::ast::Attribute] = &sexp.pexp_attributes;
    let await_kw = matches!(
        sexp.pexp_desc,
        crate::parser::ast::ExpressionDesc::Pexp_for_await_of(_)
    );
    let arena = tctx.arena;
    let (pat, iterable_expr, body) = *for_of;
    let pat = arena.get_pat(pat);
    let iterable_expr = arena.get_expanded_expr(iterable_expr);
    let body = arena.get_expanded_expr(body);
    let ctx = tctx.type_ctx;

    // OCaml only accepts `_` or a variable for the for-of binding.
    if !matches!(
        &pat.ppat_desc,
        crate::parser::ast::PatternDesc::Ppat_any | crate::parser::ast::PatternDesc::Ppat_var(_)
    ) {
        return Err(TypeCoreError::InvalidForOfPattern { loc: pat.ppat_loc });
    }

    let ty_elem = ctx.new_var(None);

    // Type-check the iterable. For `for await ... of`, expect
    // `asyncIterable<ty_elem>` directly. For `for ... of`, type without an
    // expected type and then unify with `iterable<ty_elem>`. If that fails,
    // try the `array<ty_elem>` fallback (OCaml accepts raw arrays as a
    // convenience).
    let typed_iterable = if await_kw {
        // typecore.ml `Pexp_for_await_of`: type the collection, then
        // `unify_exp_types_through_private` with `asyncIterable<'a>`.
        let typed = type_exp(tctx, env, iterable_expr, None)?;
        let async_iter_ty = env.type_async_iterable(ctx, ty_elem);
        if let Err(error) = unify_through_private(ctx, env, typed.exp_type, async_iter_ty) {
            let trace = match error {
                TypeError::Unify(trace) => trace,
                _ => vec![(typed.exp_type, async_iter_ty)],
            };
            return Err(TypeCoreError::ExprTypeClash {
                loc: iterable_expr.pexp_loc,
                trace,
                context: None,
                env: Some(tctx.type_ctx.store_typed_env(env)),
            });
        }
        typed
    } else {
        let typed = type_exp(tctx, env, iterable_expr, None)?;
        // OCaml compiler/ml/typecore.ml:3187-3211 snapshots type mutation
        // state before trying `iterable<'a>`, backtracks on an Expr_type_clash,
        // then tries the raw-array convenience fallback under a second
        // snapshot. Keep the same order instead of peeking at constructor
        // heads after a failed unify.
        let iterable_snapshot = ctx.snapshot_type_state();
        let iterable_ty = env.type_iterable(ctx, ty_elem);
        match unify_through_private(ctx, env, typed.exp_type, iterable_ty) {
            Ok(()) => typed,
            Err(iterable_error) => {
                ctx.restore_type_state(iterable_snapshot);

                let array_snapshot = ctx.snapshot_type_state();
                let array_ty = env.type_array(ctx, ty_elem);
                let mut array_unify_state = UnifyState::new();
                array_unify_state.set_env(env);
                match crate::types::ctype::unify(
                    ctx,
                    &mut array_unify_state,
                    typed.exp_type,
                    array_ty,
                ) {
                    Ok(()) => typed,
                    Err(_) => {
                        ctx.restore_type_state(array_snapshot);
                        let trace = match iterable_error {
                            TypeError::Unify(trace) => trace,
                            _ => vec![(typed.exp_type, iterable_ty)],
                        };
                        return Err(TypeCoreError::ExprTypeClash {
                            loc: iterable_expr.pexp_loc,
                            trace,
                            context: None,
                            env: Some(tctx.type_ctx.store_typed_env(env)),
                        });
                    }
                }
            }
        }
    };

    // Bind the loop variable (if any) into the body environment.
    let mut state = PatternState::new();
    let _typed_pat = type_pattern(tctx, env, pat, ty_elem, PatternMode::Normal, &mut state)?;
    let loop_var_id = match &pat.ppat_desc {
        crate::parser::ast::PatternDesc::Ppat_any => {
            if !state.pattern_variables.is_empty() {
                return Err(TypeCoreError::InvalidForOfPattern { loc: pat.ppat_loc });
            }
            if await_kw {
                ctx.create_ident("_for_await_of")
            } else {
                ctx.create_ident("_for_of")
            }
        }
        crate::parser::ast::PatternDesc::Ppat_var(_) if state.pattern_variables.len() == 1 => {
            state.pattern_variables[0].id
        }
        _ => return Err(TypeCoreError::InvalidForOfPattern { loc: pat.ppat_loc }),
    };

    let mut body_env = env.clone();
    for pv in &state.pattern_variables {
        let val_loc = tctx.arena.to_location(loc);
        let desc = ValueDescription {
            val_type: pv.ty,
            val_kind: crate::types::ValueKind::ValReg,
            val_loc: tctx.intern_ast_loc(tctx.arena, loc),
            val_attributes: Default::default(),
            val_path: None,
        };
        body_env.add_value(pv.id, desc);
        let name = pv.id.name();
        tctx.add_value_usage_check(
            name,
            val_loc,
            loc,
            Warning::UnusedForIndex {
                name: name.to_string(),
            },
        );
    }

    let typed_body = with_loop_depth(tctx, |tctx| type_statement(tctx, &body_env, body))?;

    // OCaml `rue { ... exp_type = instance_def Predef.type_unit }`, i.e.
    // `unify env unit (instance ty_expected)`.
    let result_unit_ty = env.type_unit(ctx);
    rue_unify(tctx, loc, result_unit_ty, expected_ty, context)?;

    let pat_box = Box::new(pat.clone());
    let desc = if await_kw {
        ExpressionDesc::Texp_for_await_of(
            loop_var_id,
            pat_box,
            tctx.push_expr(typed_iterable),
            tctx.push_expr(typed_body),
        )
    } else {
        ExpressionDesc::Texp_for_of(
            loop_var_id,
            pat_box,
            tctx.push_expr(typed_iterable),
            tctx.push_expr(typed_body),
        )
    };

    Ok({
        let typed_node = Expression::new(
            desc,
            loc,
            result_unit_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

/// Type check constructor application.
fn type_construct(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Located<LidentIdx>,
    sargs: &Located<crate::parse_arena::ExprList>,
    expected_ty: TypeExprRef,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    let longident = tctx.resolve_lid(lid.txt).clone();
    // Look up constructor with disambiguation following OCaml's approach:
    // 1. For module-qualified constructors (Ldot), use direct module lookup
    // 2. For unqualified constructors (Lident), use disambiguation considering expected type
    let lid_name = tctx.longident_last_name(&longident);
    let is_qualified = matches!(longident, Longident::Ldot(..));
    if is_qualified {
        // `Typetexp.find_all_constructors` marks the qualifying module
        // through `lookup_module_descr` (env.ml:1076-1089).
        mark_open_lid_use(
            ctx,
            env,
            tctx.arena,
            &longident,
            crate::types::env::OpenLookupKind::Component,
            Some(lid.loc),
        );
    }
    let qualified_opath = if is_qualified {
        // OCaml compiler/ml/typecore.ml:4244-4253 computes `opath`, gathers
        // candidates with `Typetexp.find_all_constructors`, then still calls
        // `Constructor.disambiguate`. For an expected variant path that calls
        // typecore.ml:982-988 `disambiguate_by_type`, whose
        // `compare_type_path` reaches typecore.ml:776-787 `expand_path` and
        // forces Env.normalize_path lazies at compiler/ml/env.ml:903-926.
        extract_variant_type_path_from_expected_with_persistent_env(
            expected_ty,
            env,
            &mut tctx.persistent_env,
            tctx.type_ctx,
        )
    } else {
        None
    };
    let (_cstr_path, cstr_desc) = if is_qualified {
        if let Some((path, desc)) =
            lookup_predef_option_constructor(&longident, tctx.arena, env, tctx.type_ctx)
        {
            if let Some((expected, alternatives)) = qualified_constructor_type_mismatch(
                qualified_opath.as_ref(),
                &desc,
                expected_ty,
                env,
                &mut tctx.persistent_env,
                tctx.type_ctx,
            ) {
                return Err(TypeCoreError::NameTypeMismatch {
                    loc: lid.loc,
                    kind: "variant".to_string(),
                    lid: longident.clone(),
                    expected,
                    alternatives,
                });
            }
            (path, desc)
        } else {
            // Module-qualified: use direct lookup
            let report_ambiguous = ambiguous_name_warning_is_active(tctx);
            match lookup_constructor_in_module_with_ambiguity(
                &longident,
                tctx.arena,
                env,
                &mut tctx.persistent_env,
                tctx.type_ctx,
                Some(expected_ty),
                report_ambiguous,
            ) {
                Some((path, desc, ambiguous_types)) => {
                    // `NameChoice.disambiguate` (typecore.ml:913-918) warns
                    // before the constructor is typed.
                    if !ambiguous_types.is_empty() {
                        tctx.report_warning(
                            lid.loc,
                            Warning::AmbiguousName {
                                names: vec![lid_name.to_string()],
                                types: ambiguous_types,
                                is_label: false,
                            },
                        );
                    }
                    if let Some((expected, alternatives)) = qualified_constructor_type_mismatch(
                        qualified_opath.as_ref(),
                        &desc,
                        expected_ty,
                        env,
                        &mut tctx.persistent_env,
                        tctx.type_ctx,
                    ) {
                        return Err(TypeCoreError::NameTypeMismatch {
                            loc: lid.loc,
                            kind: "variant".to_string(),
                            lid: longident.clone(),
                            expected,
                            alternatives,
                        });
                    }
                    (path, desc)
                }
                // OCaml `Typetexp.find_all_constructors` only reads the
                // qualifying module; a miss is a (narrowed) unbound error.
                None => {
                    return Err(unbound_constructor_lookup_error(
                        tctx, env, lid.loc, &longident,
                    ));
                }
            }
        }
    } else {
        // Unqualified: use disambiguation with expected type
        let report_ambiguous = ambiguous_name_warning_is_active(tctx);
        match disambiguate_constructor(
            &lid_name,
            expected_ty,
            env,
            &mut tctx.persistent_env,
            tctx.type_ctx,
            report_ambiguous,
        ) {
            Err(tpath) => {
                return Err(wrong_constructor_name_error(
                    tctx,
                    env,
                    lid.loc,
                    expected_ty,
                    tpath,
                    &lid_name,
                    "This variant expression is expected to have",
                ));
            }
            Ok(Some(resolution)) => {
                if !resolution.ambiguous_types.is_empty() {
                    tctx.report_warning(
                        lid.loc,
                        Warning::AmbiguousName {
                            names: vec![lid_name.to_string()],
                            types: resolution.ambiguous_types.clone(),
                            is_label: false,
                        },
                    );
                }
                (resolution.path, resolution.desc)
            }
            Ok(None) => {
                match lookup_constructor_in_module(
                    &longident,
                    tctx.arena,
                    env,
                    &mut tctx.persistent_env,
                    tctx.type_ctx,
                    Some(expected_ty),
                ) {
                    Some((path, desc)) => (path, desc),
                    None => {
                        let alternatives = unbound_constructor_alternatives(tctx, env, &longident);
                        return Err(TypeCoreError::UnboundConstructor {
                            loc: lid.loc,
                            lid: longident,
                            alternatives,
                        });
                    }
                }
            }
        }
    };

    // The chosen candidate's `use ()` marks its type (`Env.lookup_all_constructors`,
    // env.ml:1197-1206), then typecore.ml:4228: `Env.mark_constructor
    // Env.Positive env (Longident.last lid.txt) constr`.
    mark_type_path_of(tctx.type_ctx, env, cstr_desc.cstr_res);
    mark_constructor(
        tctx.type_ctx,
        env,
        crate::types::usage::ConstructorUsage::Positive,
        tctx.longident_last_name_str(&longident),
        &cstr_desc,
    );
    // typecore.ml:4229: `Builtin_attributes.check_deprecated loc
    // constr.cstr_attributes constr.cstr_name`.
    record_deprecated_used(tctx, loc, &cstr_desc.cstr_attributes, None)?;
    if let Some(warning) =
        deprecated_warning_from_attrs(&cstr_desc.cstr_name, &cstr_desc.cstr_attributes)
            .map_err(|loc| invalid_escape_at(tctx.type_ctx, loc))?
    {
        tctx.report_warning(loc, warning);
    }
    let sargs = normalize_constructor_expr_args(tctx.arena, cstr_desc.cstr_arity, sargs);
    if sargs.len() != cstr_desc.cstr_arity as usize {
        return Err(TypeCoreError::ConstructorArityMismatch {
            loc,
            name: longident.clone(),
            is_inline_record: cstr_desc.cstr_inlined.is_some(),
            expected: cstr_desc.cstr_arity as usize,
            provided: sargs.len(),
        });
    }

    // Match OCaml type_construct:
    // - optional separate begin_def/generalization around constructor instance
    // - second instance_list pass producing (ty_res, ty_args0)
    // - type arguments against ty_args, then unify against ty_args0
    let separate = env.has_local_constraints();
    if separate {
        ctx.begin_def();
        ctx.begin_def();
    }

    let (inst_arg_types, result_ty_raw) = crate::types::instance_constructor(ctx, &cstr_desc);
    let mut result_ty = result_ty_raw;
    let arg_types_for_expect = inst_arg_types;

    if separate {
        ctx.end_def();
        let var_level = ctx.current_level();
        crate::types::generalize_structure(ctx, var_level, result_ty);
        let result_ty_inst = crate::types::ctype::instance(ctx, result_ty);
        let expected_inst = crate::types::ctype::instance(ctx, expected_ty);
        unify_expression_types(tctx, loc, result_ty_inst, expected_inst, None)?;
        ctx.end_def();

        let var_level = ctx.current_level();
        for arg_ty in &arg_types_for_expect {
            crate::types::generalize_structure(ctx, var_level, *arg_ty);
        }
        crate::types::generalize_structure(ctx, var_level, result_ty);
    }

    let mut inst_list = Vec::with_capacity(1 + arg_types_for_expect.len());
    inst_list.push(result_ty);
    inst_list.extend(arg_types_for_expect.iter().copied());
    let mut instanced = crate::types::ctype::instance_list(ctx, &inst_list);
    result_ty = instanced.remove(0);
    let arg_types_for_unify = instanced;

    if !separate {
        let expected_inst = crate::types::ctype::instance(ctx, expected_ty);
        unify_expression_types(tctx, loc, result_ty, expected_inst, None)?;
    }

    let recarg = if cstr_desc.cstr_inlined.is_none() {
        RecArg::Rejected
    } else {
        let inline_record_arg_shape = matches!(sargs.as_slice(), [arg_idx] if match &tctx.arena.get_expanded_expr(*arg_idx).pexp_desc {
            crate::parser::ast::ExpressionDesc::Pexp_ident(_) => true,
            crate::parser::ast::ExpressionDesc::Pexp_record(inner) => {
                let (_, base) = inner;
                match base {
                    None => true,
                    Some(base_idx) => matches!(
                        &tctx.arena.get_expanded_expr(*base_idx).pexp_desc,
                        crate::parser::ast::ExpressionDesc::Pexp_ident(_)
                    ),
                }
            }
            _ => false,
        });
        if inline_record_arg_shape {
            RecArg::Required
        } else {
            return Err(TypeCoreError::InlinedRecordExpected { loc });
        }
    };

    // `List.map2 (fun e (t, t0) -> type_argument ~context ~recarg env e t t0)
    // sargs (List.combine ty_args ty_args0)`.
    let mut typed_args = Vec::with_capacity(sargs.len());
    for ((arg_idx, arg_ty), arg_ty0) in sargs
        .iter()
        .zip(arg_types_for_expect.iter())
        .zip(arg_types_for_unify.iter())
    {
        let arg_expr = tctx.arena.get_expanded_expr(*arg_idx);
        let typed_arg = type_expect_with_recarg(tctx, env, arg_expr, *arg_ty, None, recarg)?;
        unify_expression_types(tctx, loc, typed_arg.exp_type, *arg_ty0, None)?;
        typed_args.push(typed_arg);
    }

    if cstr_desc.cstr_private == crate::types::PrivateFlag::Private {
        return Err(TypeCoreError::PrivateType { loc, ty: result_ty });
    }

    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_construct(
                *lid,
                std::sync::Arc::new(cstr_desc),
                tctx.typed.push_exprs(typed_args),
            ),
            loc,
            result_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

/// Type check polymorphic variant.
fn type_variant(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    sexp: &ParsedExpression,
    label: &str,
    arg: Option<&ParsedExpression>,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    let loc = sexp.pexp_loc;
    let attributes: &[crate::parser::ast::Attribute] = &sexp.pexp_attributes;
    let ctx = tctx.type_ctx;

    if let Some(arg_expr) = arg {
        // OCaml fast path: when expected type is already a variant row with
        // this label carrying payload, type the payload against that row slot
        // and keep `exp_type = instance expected_ty`.
        let expected_inst = crate::types::ctype::instance(ctx, expected_ty);
        let expanded_expected = crate::types::ctype::expand_head(ctx, env, expected_ty);
        let expanded_expected_inst = crate::types::ctype::expand_head(ctx, env, expected_inst);

        let expected_payload = {
            let expected_desc = ctx.get_desc(ctx.repr(expanded_expected));
            let expected_inst_desc = ctx.get_desc(ctx.repr(expanded_expected_inst));
            match (&*expected_desc, &*expected_inst_desc) {
                (TypeDesc::Tvariant(row), TypeDesc::Tvariant(row0)) => {
                    let row = crate::types::btype::row_repr(ctx, &ctx.row_desc(row));
                    let row0 = crate::types::btype::row_repr(ctx, &ctx.row_desc(row0));
                    let field = row
                        .row_fields
                        .iter()
                        .find(|(l, _)| l == label)
                        .map(|(_, rf)| crate::types::btype::row_field_repr(ctx, rf));
                    let field0 = row0
                        .row_fields
                        .iter()
                        .find(|(l, _)| l == label)
                        .map(|(_, rf)| crate::types::btype::row_field_repr(ctx, rf));
                    match (field, field0) {
                        (
                            Some(crate::types::type_expr::RowField::Rpresent(Some(ty))),
                            Some(crate::types::type_expr::RowField::Rpresent(Some(ty0))),
                        ) => Some((ty, ty0)),
                        _ => None,
                    }
                }
                _ => None,
            }
        };

        if let Some((arg_ty, arg_ty0)) = expected_payload {
            let typed_arg = type_expect(tctx, env, arg_expr, arg_ty, None)?;
            unify_expression_types(tctx, loc, typed_arg.exp_type, arg_ty0, None)?;
            return Ok({
                let typed_node = Expression::new(
                    ExpressionDesc::Texp_variant(
                        label.to_string(),
                        Some(tctx.push_expr(typed_arg)),
                    ),
                    loc,
                    expected_inst,
                    tctx.type_ctx.store_typed_env(env),
                );
                tctx.typed
                    .with_exp_attributes(typed_node, attributes.to_vec().into())
            });
        }

        let arg_ty = ctx.new_var(None);
        let typed_arg = type_expect(tctx, env, arg_expr, arg_ty, None)?;
        // OCaml (typecore.ml:2596-2605) always creates a proper Tvariant with
        // Rpresent for variant expression types, including recursive payloads.
        let variant_ty = ctx.new_variant(crate::types::type_expr::RowDesc {
            row_fields: vec![(
                label.to_string().into(),
                crate::types::type_expr::RowField::Rpresent(Some(typed_arg.exp_type)),
            )]
            .into(),
            row_more: ctx.new_var(None),
            row_closed: false,
            row_fixed: false,
            row_name: None,
        });
        // OCaml: rue { ... exp_type = variant_row; ... }
        rue_unify(tctx, loc, variant_ty, expected_ty, context)?;
        return Ok({
            let typed_node = Expression::new(
                ExpressionDesc::Texp_variant(label.to_string(), Some(tctx.push_expr(typed_arg))),
                loc,
                variant_ty,
                tctx.type_ctx.store_typed_env(env),
            );
            tctx.typed
                .with_exp_attributes(typed_node, attributes.to_vec().into())
        });
    }

    // Constant polymorphic variants (`#Tag`) use an explicit one-field open row.
    let variant_ty = ctx.new_variant(crate::types::type_expr::RowDesc {
        row_fields: vec![(
            label.to_string().into(),
            crate::types::type_expr::RowField::Rpresent(None),
        )]
        .into(),
        row_more: ctx.new_var(None),
        row_closed: false,
        row_fixed: false,
        row_name: None,
    });
    // OCaml: rue { ... exp_type = variant_row; ... }
    rue_unify(tctx, loc, variant_ty, expected_ty, context)?;

    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_variant(label.to_string(), None),
            loc,
            variant_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

fn record_labels_match_ids(
    labels: &[crate::types::decl::LabelDeclaration],
    field_names: &[&str],
    closed_record: bool,
) -> bool {
    record_labels_have_field_ids(labels, field_names)
        && (!closed_record || record_labels_satisfy_closed(labels, field_names))
}

fn record_labels_have_field_ids(
    labels: &[crate::types::decl::LabelDeclaration],
    field_names: &[&str],
) -> bool {
    if field_names.len() <= 8 {
        if !field_names
            .iter()
            .all(|name| labels.iter().any(|ld| ld.ld_id.name() == *name))
        {
            return false;
        }
    } else {
        let label_names: HashSet<&str> = labels.iter().map(|ld| ld.ld_id.name()).collect();
        if !field_names.iter().all(|name| label_names.contains(*name)) {
            return false;
        }
    }

    true
}

fn record_labels_satisfy_closed(
    labels: &[crate::types::decl::LabelDeclaration],
    field_names: &[&str],
) -> bool {
    let mandatory_count = labels.iter().filter(|ld| !ld.ld_optional).count();
    let has_optional = labels.iter().any(|ld| ld.ld_optional);
    if has_optional {
        field_names.len() >= mandatory_count
    } else {
        field_names.len() == labels.len()
    }
}

#[derive(Clone)]
struct RecordLabelDescriptionsInfo {
    /// The registered `lbl_all` array of `labels`.
    family: crate::types::LabelArrayRef,
    labels: Arc<Vec<crate::types::LabelDescription>>,
    summary: Arc<crate::types::context::RecordLabelDescriptionSummary>,
}

impl RecordLabelDescriptionsInfo {
    #[inline]
    fn label_by_name(&self, name: &str) -> Option<crate::types::LabelDescription> {
        self.summary
            .label_index(name)
            .and_then(|idx| self.labels.get(idx))
            .cloned()
    }

    #[inline]
    fn matches_field_names(&self, field_names: &[&str], closed_record: bool) -> bool {
        if !field_names
            .iter()
            .all(|name| self.summary.contains_label(name))
        {
            return false;
        }

        if !closed_record {
            return true;
        }

        if self.summary.has_optional {
            field_names.len() >= self.summary.mandatory_count
        } else {
            field_names.len() == self.labels.len()
        }
    }
}

fn record_label_from_info(
    info: Option<&RecordLabelDescriptionsInfo>,
    field_name: &str,
) -> Option<crate::types::LabelDescription> {
    info.and_then(|info| info.label_by_name(field_name))
}

fn fast_exact_unqualified_opath_record_label(
    field_name: &str,
    record_opath_ty: TypeExprRef,
    label_info: Option<&RecordLabelDescriptionsInfo>,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &TypeContext,
) -> Option<crate::types::LabelDescription> {
    let target_path =
        extract_type_path_from_expected_with_persistent_env(record_opath_ty, env, pers_env, ctx)?;
    // OCaml compiler/ml/typecore.ml:1010-1058 passes the expected record
    // `opath` directly to Label.disambiguate; compiler/ml/env.ml:781-813 can
    // resolve applicative functor paths through `find_module_descr`. This
    // Rust-only exact shortcut only applies to paths with a normal head.
    let Ok((target_head, _)) = target_path.flatten() else {
        return None;
    };
    if target_head.is_persistent() {
        return None;
    }

    let labels = env.find_all_labels(field_name);
    let first_label = labels.first()?;
    let first_path = label_result_path(ctx, first_label)?;
    if !first_path.same(&target_path) {
        return None;
    }

    // `disambiguate_by_type` chose the first label in scope; `Label.disambiguate`
    // calls its `use ()` callback (typecore.ml:912-922).
    if let Some((desc, mark)) = env.find_all_labels_marking(field_name).into_iter().next() {
        use_label_candidate(ctx, env, field_name, desc, mark);
    }
    record_label_from_info(label_info, field_name).or_else(|| Some((*first_label).clone()))
}

/// Whether warning 41 (`Ambiguous_name`) is reported here. It is off by
/// default, and finding the types a name is ambiguous between compares every
/// candidate in scope with the ones kept so far, so callers only look for
/// them when this holds.
fn ambiguous_name_warning_is_active(tctx: &TypeCheckContext<'_>) -> bool {
    tctx.warning_config.is_active(&Warning::AmbiguousName {
        names: Vec::new(),
        types: Vec::new(),
        is_label: false,
    })
}

/// The end of `disambiguate_record_elem_list` (typecore.ml:1037-1050): the
/// `Ambiguous_name` warnings collected while disambiguating the labels are
/// reported once for the record when all selected labels have the same type,
/// `Label.disambiguate` with no `opath` (typecore.ml:910-918) warns
/// `Ambiguous_name ([name], ambiguous_types env lbl rest, false)` at the
/// label when the labels in scope belong to several types.
fn warn_ambiguous_label_access(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    name: &str,
    selected: &crate::types::LabelDescription,
) {
    let warning = Warning::AmbiguousName {
        names: Vec::new(),
        types: Vec::new(),
        is_label: false,
    };
    if !tctx.warning_config.is_active(&warning) {
        return;
    }
    let candidates = env.find_all_labels(name);
    if candidates.len() <= 1 {
        return;
    }
    if let Some((types, _)) = ambiguous_record_label_warning_info(
        selected,
        &candidates,
        env,
        &mut tctx.persistent_env,
        tctx.type_ctx,
    ) {
        tctx.report_warning(
            loc,
            Warning::AmbiguousName {
                names: vec![name.to_string()],
                types,
                is_label: false,
            },
        );
    }
}

/// else one per label, at the record's location.
fn emit_ambiguous_record_label_warnings(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    ambiguous_label_warnings: Vec<(String, Vec<String>, Option<Path>)>,
) {
    let ctx = tctx.type_ctx;
    let Some((_, first_types, first_path)) = ambiguous_label_warnings.first().cloned() else {
        return;
    };
    let same_selected_path = ambiguous_label_warnings.iter().all(|(_, _, path)| {
        match (first_path.as_ref(), path.as_ref()) {
            (Some(first), Some(path)) => compare_type_paths_for_label_disambiguation(
                first,
                path,
                env,
                &mut tctx.persistent_env,
                ctx,
            ),
            (None, None) => true,
            _ => false,
        }
    });
    if same_selected_path {
        tctx.report_warning(
            loc,
            Warning::AmbiguousName {
                names: ambiguous_label_warnings
                    .iter()
                    .map(|(name, _, _)| name.clone())
                    .collect(),
                types: first_types,
                is_label: true,
            },
        );
    } else {
        for (name, types, _) in ambiguous_label_warnings {
            tctx.report_warning(
                loc,
                Warning::AmbiguousName {
                    names: vec![name],
                    types,
                    is_label: false,
                },
            );
        }
    }
}

fn ambiguous_record_label_warning_info(
    selected: &crate::types::LabelDescription,
    candidates: &[&crate::types::LabelDescription],
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &TypeContext,
) -> Option<(Vec<String>, Option<Path>)> {
    let selected_path = label_result_path(ctx, selected)?;
    let mut paths = vec![selected_path];
    for candidate in candidates {
        let Some(candidate_path) = label_result_path(ctx, candidate) else {
            continue;
        };
        if paths.iter().any(|path| {
            compare_type_paths_for_label_disambiguation(&candidate_path, path, env, pers_env, ctx)
        }) {
            continue;
        }
        paths.push(candidate_path);
    }
    if paths.len() <= 1 {
        return None;
    }

    // `List.map Printtyp.string_of_path tpaths` (typecore.ml:888-891).
    let printer = crate::types::printtyp::Printtyp::new(ctx);
    let types = paths
        .iter()
        .map(|path| printer.string_of_path(path))
        .collect();
    Some((types, Some(selected_path)))
}

/// OCaml `disambiguate_label_by_ids` (typecore.ml:1017-1041): keep the
/// labels whose record has every id (`labels'`), then those passing the
/// closed-record check (`labels''`); a filter that leaves nothing falls back
/// to the previous list.
fn disambiguate_label_by_ids<'a>(
    labels: Vec<&'a crate::types::LabelDescription>,
    ids: &[&str],
    closed: bool,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a TypeContext,
) -> Vec<&'a crate::types::LabelDescription> {
    let mut with_ids = Vec::new();
    let mut with_closed = Vec::new();
    for label in &labels {
        let Some(info) = build_record_label_descriptions_info(label.lbl_res, env, pers_env, ctx)
        else {
            continue;
        };
        if !ids.iter().all(|name| info.summary.contains_label(name)) {
            continue;
        }
        with_ids.push(*label);
        if info.matches_field_names(ids, closed) {
            with_closed.push(*label);
        }
    }
    if with_ids.is_empty() {
        labels
    } else if with_closed.is_empty() {
        with_ids
    } else {
        with_closed
    }
}

fn reduce_record_label_scope_by_ids<'a>(
    candidates: Vec<&'a crate::types::LabelDescription>,
    field_names: &[&str],
    closed_record: bool,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a TypeContext,
) -> Option<Vec<&'a crate::types::LabelDescription>> {
    // OCaml compiler/ml/typecore.ml:1071-1095 filters the visible label scope
    // with every field name before Label.disambiguate can call
    // compiler/ml/typecore.ml:975-1006 `ambiguous_types`. Use the same reduced
    // scope for warnings; comparing the full scope forces unrelated component
    // signatures before OCaml would.
    let mut matching_ids = false;
    let mut matching_closed = Vec::new();
    for label in candidates {
        let Some(info) = build_record_label_descriptions_info(label.lbl_res, env, pers_env, ctx)
        else {
            continue;
        };
        if !field_names
            .iter()
            .all(|name| info.summary.contains_label(name))
        {
            continue;
        }
        matching_ids = true;
        if info.matches_field_names(field_names, closed_record) {
            matching_closed.push(label);
        }
    }
    if !matching_ids {
        return None;
    }

    if matching_closed.is_empty() {
        None
    } else {
        Some(matching_closed)
    }
}

fn force_unqualified_record_label_disambiguate_by_type_compare(
    field_name: &str,
    record_opath_ty: Option<TypeExprRef>,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &TypeContext,
) {
    let Some(record_ty) = record_opath_ty else {
        return;
    };
    let Some(target_path) =
        extract_type_path_from_expected_with_persistent_env(record_ty, env, pers_env, ctx)
    else {
        return;
    };

    let labels = env.find_all_labels(field_name);
    if labels.is_empty() {
        return;
    }

    for label in labels {
        let Some(label_path) = label_result_path(ctx, label) else {
            continue;
        };
        // OCaml compiler/ml/typecore.ml:1098-1132 passes the full unqualified
        // label scope to `Label.disambiguate` when `opath` is present. That
        // reaches typecore.ml:983-988 `disambiguate_by_type`, calling
        // `compare_type_path env tpath lbl_tpath` until the first match. The
        // Rust expected-record fast path below already knows the selected
        // label, so replay the comparison side effects without constructing a
        // throwaway label for every large JSX prop.
        if compare_type_paths_for_label_disambiguation(
            &target_path,
            &label_path,
            env,
            pers_env,
            ctx,
        ) {
            break;
        }
    }
}

fn select_record_type_for_fields(
    ctx: &TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    field_names: &[&str],
    expected_ty: TypeExprRef,
    base_ty: Option<TypeExprRef>,
    closed_record: bool,
) -> Option<TypeExprRef> {
    for candidate_ty in [Some(expected_ty), base_ty].into_iter().flatten() {
        // OCaml compiler/ml/typecore.ml:1163-1198 disambiguates against the
        // shared label array carried by label descriptions. Reuse Rust's
        // reconstructed shared array here instead of cloning the full record
        // declaration just to check whether field names fit a candidate.
        if let Some(info) = build_record_label_descriptions_info(candidate_ty, env, pers_env, ctx) {
            if info.matches_field_names(field_names, closed_record) {
                return Some(candidate_ty);
            }
        }
    }

    // OCaml compiler/ml/typecore.ml:981-1005 `disambiguate_label_by_ids`
    // keeps the labels in scope whose record has every field (`labels'`),
    // then those satisfying the closed-record check (`labels''`), falling back
    // to the previous list when a filter leaves nothing; `Label.disambiguate`
    // (typecore.ml:900-918) then takes the first remaining label.
    let first_name = *field_names.first()?;
    let candidates = env.find_all_labels(first_name);
    let mut with_ids = Vec::new();
    let mut closed = Vec::new();
    for label in candidates {
        if let Some(info) = build_record_label_descriptions_info(label.lbl_res, env, pers_env, ctx)
        {
            if !field_names
                .iter()
                .all(|name| info.summary.contains_label(name))
            {
                continue;
            }
            with_ids.push(label.lbl_res);
            if info.matches_field_names(field_names, closed_record) {
                closed.push(label.lbl_res);
            }
        }
    }
    closed.first().or_else(|| with_ids.first()).copied()
}

fn select_record_type_from_qualified_label_scope(
    ctx: &TypeContext,
    arena: &ParseArena,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    fields: &[crate::parser::ast::ExpressionRecordField],
    field_names: &[&str],
    closed_record: bool,
) -> Option<TypeExprRef> {
    if field_names.len() <= 1 {
        return None;
    }

    let first_field = fields.first()?;
    let first_lid = arena.get_longident(first_field.lid.txt);
    let Longident::Ldot(module_lid, label_idx) = first_lid else {
        return None;
    };
    let label_name = arena.get_string(*label_idx);

    // OCaml compiler/ml/typecore.ml:1098-1125 first calls
    // `Typetexp.find_all_labels`, then typecore.ml:1071-1095
    // `disambiguate_label_by_ids` reduces that label scope by the full record
    // field set. `find_all_labels` reaches compiler/ml/env.ml:1114-1120 and
    // env.ml:1138-1142, reading the module component `comp_labels` table
    // without forcing env.ml:865-875's persistent `ps_sig` lazy.
    let candidates = with_resolved_module_components_for_lid(
        module_lid.as_ref(),
        arena,
        env,
        pers_env,
        ctx,
        |components| {
            let labels = components.lookup_labels(label_name, ctx);
            (!labels.is_empty()).then(|| labels.as_ref().clone())
        },
    )
    .flatten()?;

    let mut matching: Vec<(Option<Path>, TypeExprRef)> = Vec::new();
    for label in candidates {
        if let Some(labels) = get_record_labels(ctx, env, pers_env, label.lbl_res) {
            if record_labels_match_ids(&labels, field_names, closed_record) {
                let key = extract_type_path_from_expected(label.lbl_res, env, ctx);
                if matching.iter().any(|(existing, _)| *existing == key) {
                    continue;
                }
                matching.push((key, label.lbl_res));
            }
        }
    }

    if matching.len() == 1 {
        Some(matching[0].1)
    } else {
        None
    }
}

fn find_record_qual(
    arena: &ParseArena,
    fields: &[crate::parser::ast::ExpressionRecordField],
) -> Option<Longident> {
    for field in fields {
        if let Longident::Ldot(module_lid, _) = arena.get_longident(field.lid.txt) {
            return Some((**module_lid).clone());
        }
    }
    None
}

fn qualify_unqualified_record_fields<'a>(
    tctx: &mut TypeCheckContext<'_>,
    fields: &'a [crate::parser::ast::ExpressionRecordField],
) -> Cow<'a, [crate::parser::ast::ExpressionRecordField]> {
    let Some(module_qualifier) = find_record_qual(tctx.arena, fields) else {
        // OCaml keeps the original `record_elem_list` when no qualifier is
        // present (`compiler/ml/typecore.ml:1178-1180`). Borrow the parser
        // slice in the same common case instead of cloning every record field.
        return Cow::Borrowed(fields);
    };

    let mut rewritten = Vec::with_capacity(fields.len());
    for field in fields {
        let mut field = *field;
        if let Longident::Lident(field_name) = tctx.arena.get_longident(field.lid.txt) {
            let qualified = Longident::Ldot(Box::new(module_qualifier.clone()), *field_name);
            let qualified_idx = tctx.arena.push_typecheck_longident(qualified);
            field.lid = Located {
                txt: qualified_idx,
                loc: field.lid.loc,
            };
        }
        rewritten.push(field);
    }
    Cow::Owned(rewritten)
}

/// Type check record expression.
fn type_record(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    record: &(
        crate::parse_arena::ExprFieldList,
        Option<crate::parse_arena::ExprIdx>,
    ),
    expected_ty: TypeExprRef,
    attributes: &[crate::parser::ast::Attribute],
    recarg: RecArg,
) -> TypeCoreResult<Expression> {
    let arena = tctx.arena;
    let fields = arena.expr_field_list(record.0);
    let base = record.1.map(|idx| arena.get_expanded_expr(idx));
    let ctx = tctx.type_ctx;
    // typecore.ml Pexp_record: record syntax on a dict points to `dict{...}`,
    // checked against the expected type and, with a spread, its type.
    let first_lid = fields.first().map(|field| field.lid.txt);
    check_no_record_syntax_on_dict(tctx, env, loc, expected_ty, first_lid)?;
    // Protect a generic expected type from record typing side effects.
    let expected_ty = instance_if_generic(ctx, expected_ty);

    // Type check base expression if present.
    // Match OCaml: type the base with type_exp (no expected type constraint),
    // then defer unification with expected_ty until after label processing.
    // This preserves separate type identity between the base expression's
    // type chain and the expected type chain, matching OCaml's cycle structure.
    let mut typed_base = if let Some(base_expr) = base {
        let base_ty = ctx.new_var(None);
        let typed = type_expect_with_recarg(tctx, env, base_expr, base_ty, None, recarg)?;
        check_no_record_syntax_on_dict(tctx, env, loc, typed.exp_type, first_lid)?;
        Some(typed)
    } else {
        None
    };

    let mut record_ty = expected_ty;
    // OCaml compiler/ml/typecore.ml:2745-2752 and 2869-2891 keep
    // `opath` separate from the `ty_record` used to type the fields. In
    // particular, a record type selected later from the field set
    // (typecore.ml:1098-1126) is not passed as `opath` to
    // `Label.disambiguate`; otherwise typecore.ml:983-988 would force
    // `compare_type_path` too early for qualified labels.
    let expected_record_info =
        extract_concrete_record_type_info(expected_ty, env, &mut tctx.persistent_env, ctx);
    let mut record_opath_ty = expected_record_info.as_ref().map(|_| expected_ty);
    // OCaml Pexp_record(None) (typecore.ml:2740-2746): `ty_record` is the
    // expected type only when it is a concrete record, else `newvar ()`; it is
    // unified with `instance env ty_expected` after the labels are typed.
    if typed_base.is_none() && record_opath_ty.is_none() {
        record_ty = ctx.new_var(None);
    }
    // Match OCaml Pexp_record(Some exp):
    // when expected type does not reveal a concrete record path, but the base
    // expression does, use a fresh constructor instance from the base path as
    // the record typing anchor (`ty_record`) instead of reusing base.exp_type.
    if let Some(base_expr) = typed_base.as_ref() {
        if record_opath_ty.is_none() {
            let base_record_path = extract_type_path_from_expected_with_persistent_env(
                base_expr.exp_type,
                env,
                &mut tctx.persistent_env,
                ctx,
            )
            .and_then(|path| {
                lookup_type_decl_for_path(&path, env, &mut tctx.persistent_env, ctx).and_then(
                    |decl| match decl.type_kind {
                        crate::types::TypeKind::TypeRecord(_, _) => Some((path, decl)),
                        _ => None,
                    },
                )
            });

            if let Some((path, decl)) = base_record_path {
                ctx.begin_def();
                let ty = ctx.new_constr(
                    path,
                    crate::types::ctype::instance_list(ctx, &decl.type_params),
                );
                ctx.end_def();
                crate::types::generalize_structure(ctx, ctx.current_level(), ty);
                record_ty = ty;
                record_opath_ty = Some(record_ty);
            } else {
                record_ty = ctx.new_var(None);
            }
        }
    }

    let fields = qualify_unqualified_record_fields(tctx, fields);
    let qualified_label_scope =
        find_record_qual(tctx.arena, &fields).is_some() && record_opath_ty.is_none();

    let arena = tctx.arena;
    let field_names: Vec<&str> = fields
        .iter()
        .map(|field| {
            let lid = arena.get_longident(field.lid.txt);
            arena.get_string(lid.last_idx())
        })
        .collect();
    let closed_record = typed_base.is_none();
    let disambiguation_ty = if qualified_label_scope {
        // OCaml compiler/ml/typecore.ml:1075-1104 rewrites unqualified fields
        // using `find_record_qual`, then compiler/ml/typecore.ml:1098-1126
        // resolves labels from that qualified longident scope. It does not run
        // an unqualified `find_all_labels` preselection for the record family;
        // the selected label's `lbl_all` becomes available after the
        // typecore.ml:3535-3575 `type_label_exp` path has typed fields in
        // label-position order.
        typed_base
            .as_ref()
            .map(|expr| expr.exp_type)
            .unwrap_or(record_ty)
    } else {
        select_record_type_for_fields(
            ctx,
            env,
            &mut tctx.persistent_env,
            &field_names,
            record_ty,
            typed_base.as_ref().map(|expr| expr.exp_type),
            closed_record,
        )
        .or_else(|| {
            select_record_type_from_qualified_label_scope(
                ctx,
                tctx.arena,
                env,
                &mut tctx.persistent_env,
                &fields,
                &field_names,
                closed_record,
            )
        })
        .unwrap_or_else(|| {
            typed_base
                .as_ref()
                .map(|expr| expr.exp_type)
                .unwrap_or(record_ty)
        })
    };
    // OCaml record typing reads the shared `lbl_all` array directly
    // (`compiler/ml/typecore.ml:2802, 2840-2842`). Keep the Rust fallback as a
    // shared array too; building per-record name maps for JSX prop records
    // turns every small JSX literal into a full-props allocation.
    let disambiguation_label_descriptions =
        build_record_label_descriptions_info(disambiguation_ty, env, &mut tctx.persistent_env, ctx);
    let expected_label_descriptions =
        build_record_label_descriptions_info(expected_ty, env, &mut tctx.persistent_env, ctx);
    let jsx_component_error_info = record_opath_ty
        .and_then(|record_ty| jsx_prop_error_info_for_record_ty(tctx, env, record_ty));

    // OCaml `type_label_a_list` (typecore.ml:3613-3640) types the written
    // fields sorted by `lbl_pos` (`explicit_fields` below) and returns them in
    // that order: they become the `Texp_record` fields (`record_fields`,
    // typecore.ml:393-402).
    let mut explicit_entries: Vec<crate::types::typedtree::RecordField> =
        Vec::with_capacity(fields.len());
    let mut first_disambiguated_label: Option<crate::types::LabelDescription> = None;
    let mut ambiguous_label_warnings: Vec<(String, Vec<String>, Option<Path>)> = Vec::new();
    let report_ambiguous_label_warnings = tctx.warning_config.is_active(&Warning::AmbiguousName {
        names: Vec::new(),
        types: Vec::new(),
        is_label: true,
    });

    struct ExplicitField<'a> {
        original_index: usize,
        field: &'a crate::parser::ast::ExpressionRecordField,
        field_name: &'a str,
        disambiguated: Option<crate::types::LabelDescription>,
    }

    // Match OCaml typecore.ml type_record_elem_list:
    // 1) disambiguate labels
    // 2) sort by lbl_pos before typing each field
    let mut explicit_fields: Vec<ExplicitField<'_>> = Vec::with_capacity(fields.len());
    let mut last_marked_label_path: Option<Path> = None;
    for (idx, field) in fields.iter().enumerate() {
        let resolved_lid = arena.get_longident(field.lid.txt);
        let field_name = arena.get_string(resolved_lid.last_idx());
        // `process_label` (typecore.ml:1028-1029): with no `opath`, a label
        // with nothing in scope is unbound.
        if record_opath_ty.is_none()
            && matches!(resolved_lid, Longident::Lident(_))
            && env.find_label(field_name).is_err()
        {
            let resolved_lid = resolved_lid.clone();
            return Err(TypeCoreError::UnboundRecordField {
                loc: field.lid.loc,
                field_name: field_name.to_string(),
                from_type: None,
                alternatives: unbound_label_alternatives(
                    tctx.arena,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                    &resolved_lid,
                ),
            });
        }
        // `Label.disambiguate` with the expected record path: a qualified
        // label of another type raises `Name_type_mismatch`
        // (typecore.ml:919-939).
        if let Some(record_opath_ty) = record_opath_ty
            && let Some(err) = qualified_label_name_type_mismatch(
                field.lid.loc,
                resolved_lid,
                tctx.arena,
                env,
                &mut tctx.persistent_env,
                ctx,
                record_opath_ty,
            )
        {
            return Err(err);
        }
        let unqualified_with_opath =
            record_opath_ty.is_some() && matches!(resolved_lid, Longident::Lident(_));
        if matches!(resolved_lid, Longident::Lident(_)) {
            force_unqualified_record_label_disambiguate_by_type_compare(
                field_name,
                record_opath_ty,
                env,
                &mut tctx.persistent_env,
                ctx,
            );
        }
        let disambiguated = if unqualified_with_opath {
            // OCaml compiler/ml/typecore.ml:2745-2752 computes `opath` from
            // the expected record type, then typecore.ml:1098-1125 passes the
            // full unqualified label scope to `Label.disambiguate`. That
            // reaches typecore.ml:983-988 `disambiguate_by_type`, so aliases
            // such as `type view = t = {...}` can select the later `view`
            // label family even when the expected type is `t`.
            let record_opath_ty = record_opath_ty.expect("checked above");
            fast_exact_unqualified_opath_record_label(
                field_name,
                record_opath_ty,
                expected_label_descriptions.as_ref(),
                env,
                &mut tctx.persistent_env,
                ctx,
            )
            .or_else(|| {
                disambiguate_label(
                    field_name,
                    record_opath_ty,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                )
            })
        } else {
            None
        };
        if unqualified_with_opath && disambiguated.is_none() {
            if let Some(record_opath_ty) = record_opath_ty {
                if let Some(err) = wrong_record_field_name_error(
                    tctx,
                    env,
                    field.lid.loc,
                    record_opath_ty,
                    field_name,
                    "This record expression is expected to have",
                ) {
                    return Err(err);
                }
            }
        }
        let disambiguated = disambiguated
            .or_else(|| {
                lookup_label_by_lid(
                    tctx,
                    resolved_lid,
                    Some(field.lid.loc),
                    env,
                    record_opath_ty,
                    Some((&field_names, closed_record)),
                )
            })
            .or_else(|| {
                // OCaml compiler/ml/typecore.ml:1098-1126 first collects the visible
                // label scope and runs `Label.disambiguate`; if that cannot select a
                // label, typecore.ml:942-967 `lookup_from_type` falls back to the
                // expected record type. Keep this fallback after the scope lookup in
                // every mode so typedtree output and normal compilation share the same
                // lazy force order. `lookup_from_type` only matches unqualified labels.
                if matches!(resolved_lid, Longident::Ldot(..)) {
                    return None;
                }
                let label =
                    record_label_from_info(disambiguation_label_descriptions.as_ref(), field_name)?;
                use_in_scope_label_of_type(ctx, env, field_name, &label);
                Some(label)
            })
            .or_else(|| {
                if matches!(resolved_lid, Longident::Ldot(..)) {
                    return None;
                }
                disambiguate_label(
                    field_name,
                    disambiguation_ty,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                )
            });
        if report_ambiguous_label_warnings
            && record_opath_ty.is_none()
            && matches!(resolved_lid, Longident::Lident(_))
            && let Some(label) = disambiguated.as_ref()
        {
            let candidates = env.find_all_labels(field_name);
            if candidates.len() > 1
                && let Some(candidates) = reduce_record_label_scope_by_ids(
                    candidates,
                    &field_names,
                    closed_record,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                )
                && let Some((types, selected_path)) = ambiguous_record_label_warning_info(
                    label,
                    &candidates,
                    env,
                    &mut tctx.persistent_env,
                    ctx,
                )
            {
                ambiguous_label_warnings.push((field_name.to_string(), types, selected_path));
            }
        }
        // `Label.disambiguate` calls the chosen label's `use ()`, which marks
        // its type (`Env.lookup_all_labels`, env.ml:1230-1238). The fields of
        // one record usually share that type: mark it once.
        if let Some(path) = disambiguated
            .as_ref()
            .and_then(|label| label_result_path(ctx, label))
            && !last_marked_label_path.is_some_and(|marked| marked.same(&path))
        {
            mark_type_path(ctx, env, &path);
            last_marked_label_path = Some(path);
        }
        explicit_fields.push(ExplicitField {
            original_index: idx,
            field,
            field_name,
            disambiguated,
        });
    }
    if report_ambiguous_label_warnings {
        emit_ambiguous_record_label_warnings(tctx, env, loc, ambiguous_label_warnings);
    }
    explicit_fields.sort_by_key(|entry| {
        entry
            .disambiguated
            .as_ref()
            .map(|label| label.lbl_pos)
            .unwrap_or(entry.original_index as i32)
    });

    // The label parameter pairing of the previous field, reused while the
    // fields belong to the same record type.
    let mut label_param_subst: Option<crate::types::ctype::LabelParamSubst> = None;

    // Type check explicitly written fields in lbl_pos order.
    for explicit_field in explicit_fields.iter() {
        let field = explicit_field.field;
        let field_name = explicit_field.field_name;
        let disambiguated = explicit_field.disambiguated.clone();
        let prefer_expected_closed_record_label = typed_base.is_none();
        if first_disambiguated_label.is_none() {
            first_disambiguated_label = disambiguated.clone();
        }

        // OCaml compiler/ml/typecore.ml:3677-3711 (`type_label_exp`) opens a
        // definition scope before instantiating the label and keeps it open
        // through `type_argument`; functions inside record fields therefore see
        // the raised level until the field value is fully typed.
        ctx.begin_def();
        let field_result = (|| -> TypeCoreResult<(
            crate::types::LabelDescription,
            TypeExprRef,
            TypeExprRef,
            Vec<TypeExprRef>,
            Expression,
        )> {
            // Build label description (prefer env-disambiguated metadata).
            let (label_desc, field_input_ty, less_general_expected_ty, poly_vars) =
                if let Some(env_label) = disambiguated {
                    let expected_label = expected_label_descriptions
                        .as_ref()
                        .and_then(|info| info.label_by_name(field_name))
                        .or_else(|| {
                            if qualified_label_scope {
                                // OCaml compiler/ml/typecore.ml:1075-1104 has
                                // already selected the descriptor from the
                                // qualified longident scope before
                                // compiler/ml/typecore.ml:3535-3575
                                // `type_label_exp` receives it. Do not run a
                                // second expected-type label lookup here: that
                                // reaches typecore.ml:983-988 path comparison
                                // and forces applicative components before the
                                // reference compiler does.
                                None
                            } else {
                                lookup_label_by_expected_type(
                                    field_name,
                                    expected_ty,
                                    env,
                                    &mut tctx.persistent_env,
                                    ctx,
                                )
                            }
                        });
                    let env_label = expected_label
                        .filter(|expected_label| {
                            if prefer_expected_closed_record_label
                                && should_force_expected_closed_record_label(
                                    expected_ty,
                                    expected_label,
                                    &env_label,
                                    env,
                                    &mut tctx.persistent_env,
                                    ctx,
                                )
                            {
                                return true;
                            }
                            should_prefer_expected_record_label(
                                expected_label,
                                &env_label,
                                env,
                                &mut tctx.persistent_env,
                                ctx,
                            )
                        })
                        .unwrap_or(env_label);

                    if field.opt && !env_label.lbl_optional {
                        return Err(TypeCoreError::FieldNotOptional {
                            loc: tctx.arena.get_expanded_expr(field.expr).pexp_loc,
                            name: env_label.lbl_name.to_string(),
                            typ: env_label.lbl_res,
                        });
                    }
                    let original_label_arg = env_label.lbl_arg;

                    let separate = env.has_local_constraints();
                    if separate {
                        // OCaml compiler/ml/typecore.ml:3681-3694 opens two
                        // nested scopes for local constraints, closes one after
                        // `instance_label`, then generalizes label result nodes.
                        ctx.begin_def();
                        ctx.begin_def();
                    }

                    // When the record type is already an application of this
                    // label's type constructor, the unification below can only
                    // bind the label's fresh type parameters to the record
                    // type's arguments: substitute them directly instead of
                    // copying and unifying every parameter for every field.
                    let substituted_ty_arg = if separate
                        || matches!(
                            &*ctx.borrow_desc(ctx.repr(env_label.lbl_arg)),
                            TypeDesc::Tpoly { .. }
                        ) {
                        None
                    } else {
                        if !label_param_subst
                            .as_ref()
                            .is_some_and(|subst| subst.is_for(ctx, env_label.lbl_res, record_ty))
                        {
                            label_param_subst = crate::types::ctype::record_label_param_subst(
                                ctx,
                                env_label.lbl_res,
                                record_ty,
                            );
                        }
                        label_param_subst.as_ref().map(|subst| {
                            crate::types::ctype::instance_label_arg_at(
                                ctx,
                                env_label.lbl_arg,
                                subst,
                            )
                        })
                    };

                    let (poly_vars, ty_arg) = if let Some(ty_arg) = substituted_ty_arg {
                        (Vec::new(), ty_arg)
                    } else {
                        let (poly_vars, ty_arg0, ty_res0) =
                            crate::types::ctype::instance_label(ctx, true, &env_label);
                        if separate {
                            ctx.end_def();
                            crate::types::generalize_structure(ctx, ctx.current_level(), ty_arg0);
                            crate::types::generalize_structure(ctx, ctx.current_level(), ty_res0);
                        }

                        // Match OCaml typecore.ml:3695-3698:
                        //   unify env (instance_def ty_res) (instance env ty_expected)
                        //   let ty_arg = instance_def ty_arg
                        let ty_res = crate::types::ctype::instance(ctx, ty_res0);
                        let expected_record_ty = crate::types::ctype::instance(ctx, record_ty);
                        if let Err(err) = crate::types::unify(
                            ctx,
                            &mut tctx.unify_state,
                            ty_res,
                            expected_record_ty,
                        ) {
                            let trace = match err {
                                TypeError::Unify(trace) => trace,
                                _ => vec![(ty_res, expected_record_ty)],
                            };
                            return Err(TypeCoreError::LabelMismatch {
                                loc: field.lid.loc,
                                lid: tctx.arena.get_longident(field.lid.txt).clone(),
                                trace,
                                env: Some(tctx.type_ctx.store_typed_env(env)),
                            });
                        }
                        (poly_vars, crate::types::ctype::instance(ctx, ty_arg0))
                    };

                    if separate {
                        // OCaml compiler/ml/typecore.ml:3699-3702 closes the
                        // second local-constraint scope after `ty_arg` is
                        // instantiated, then generalizes the argument type.
                        ctx.end_def();
                        crate::types::generalize_structure(ctx, ctx.current_level(), ty_arg);
                    }

                    let input_ty = if env_label.lbl_optional && !field.opt {
                        crate::types::ctype::extract_option_type(ctx, ty_arg).unwrap_or(ty_arg)
                    } else {
                        ty_arg
                    };

                    if env_label.lbl_private == crate::types::PrivateFlag::Private {
                        return Err(TypeCoreError::PrivateType { loc, ty: record_ty });
                    }

                    (
                        crate::types::LabelDescription {
                            lbl_name: env_label.lbl_name,
                            lbl_runtime_name: env_label.lbl_runtime_name,
                            lbl_res: record_ty,
                            lbl_arg: ty_arg,
                            lbl_mut: env_label.lbl_mut,
                            lbl_optional: env_label.lbl_optional,
                            lbl_pos: env_label.lbl_pos,
                            lbl_all: env_label.lbl_all,
                            lbl_repres: env_label.lbl_repres.clone(),
                            lbl_private: env_label.lbl_private,
                            lbl_loc: env_label.lbl_loc,
                        },
                        input_ty,
                        original_label_arg,
                        poly_vars,
                    )
                } else {
                    let resolved_lid = tctx.arena.get_longident(field.lid.txt).clone();
                    // `Typetexp.find_all_labels` narrows a missing module
                    // prefix first (typetexp.ml:64-86).
                    if let Some(err) =
                        unbound_module_prefix_error(tctx, env, field.lid.loc, &resolved_lid)
                    {
                        return Err(err);
                    }
                    let resolved_lid = &resolved_lid;
                    return Err(TypeCoreError::UnboundRecordField {
                        loc: field.lid.loc,
                        // OCaml prints the label as written (`B.x`).
                        field_name: tctx.longident_to_string(resolved_lid),
                        from_type: None,
                        // OCaml compiler/ml/typecore.ml:1107-1125 performs
                        // record-label disambiguation while typing, but
                        // compiler/ml/typetexp.ml:916-959 computes spelling
                        // alternatives only when reporting Typetexp.Unbound_label.
                        // Do not resolve the whole qualifier signature for
                        // diagnostics after a label has already been resolved.
                        alternatives: unbound_label_alternatives(
                            tctx.arena,
                            env,
                            &mut tctx.persistent_env,
                            ctx,
                            resolved_lid,
                        ),
                    });
                };

            let field_context = Some(ClashSite::RecordField {
                field_name: crate::name::Name::new(field_name),
                optional: label_desc.lbl_optional && !field.opt,
                jsx: jsx_component_error_info
                    .as_ref()
                    .map(|info| info.jsx_type),
            });
            let typed_expr = type_expect(
                tctx,
                env,
                tctx.arena.get_expanded_expr(field.expr),
                field_input_ty,
                field_context,
            )?;
            // OCaml `type_argument`: after typing against `ty_expected'`, unify with
            // a fresh `instance` of that type to preserve sharing behavior.
            let field_input_ty_inst = crate::types::ctype::instance(ctx, field_input_ty);
            unify_expression_types(
                tctx,
                loc,
                typed_expr.exp_type,
                field_input_ty_inst,
                field_context,
            )?;
            Ok((label_desc, field_input_ty, less_general_expected_ty, poly_vars, typed_expr))
        })();
        ctx.end_def();
        let (label_desc, _field_input_ty, less_general_expected_ty, poly_vars, typed_expr) =
            field_result?;

        // OCaml check_univars: convert fresh Tvars back to Tunivar for poly fields
        // or report Less_general if a universal variable was specialized.
        if !poly_vars.is_empty() {
            check_univars_or_less_general(
                tctx,
                env,
                true,
                "field value",
                &typed_expr,
                less_general_expected_ty,
                &poly_vars,
            )?;
        }

        // process_optional_label: wrap optional fields in Some(...) only when the
        // user did not write the `?` form.
        let final_expr = if label_desc.lbl_optional && !field.opt {
            let some_cstr = make_some_constructor(ctx);
            let some_lid = Located::mknoloc(tctx.arena.predef_some_lid());
            // typecore.ml:2373-2379 builds `Some e` with `~loc:e.pexp_loc`
            // before typing, so it keeps the field expression's own location
            // (for `{ open M; body }` the block's, not the body's).
            let wrapped_loc = tctx.arena.get_expanded_expr(field.expr).pexp_loc;
            let wrapped_env = typed_expr.exp_env;
            Expression::new(
                ExpressionDesc::Texp_construct(
                    some_lid,
                    std::sync::Arc::new(some_cstr),
                    tctx.typed.push_exprs(vec![typed_expr]),
                ),
                wrapped_loc,
                label_desc.lbl_arg,
                wrapped_env,
            )
        } else {
            typed_expr
        };
        // OCaml `type_label_exp` returns `{arg with exp_type = instance env arg.exp_type}`
        // (compiler/ml/typecore.ml:1185-1198). That is a shallow record update;
        // mutate the owned Rust expression instead of deep-cloning its desc.
        let mut final_expr = final_expr;
        final_expr.exp_type = crate::types::ctype::instance(ctx, final_expr.exp_type);

        explicit_entries.push((std::sync::Arc::new(label_desc), field.lid, tctx.push_expr(final_expr)));
    }

    // `lbl.lbl_all` of the first written label (typecore.ml:3058-3059,
    // 3137-3138): the array `Datarepr.label_descrs` tied when the label was
    // described.
    let record_family = explicit_entries.first().map(|(label, _, _)| {
        ctx.label_family(label.lbl_all).unwrap_or_else(|| {
            panic!(
                "written record label `{}` carries no lbl_all array ({:?})",
                label.lbl_name, label.lbl_all
            )
        })
    });

    // OCaml: unify_exp_types ty_record (instance env ty_expected)
    let expected_inst_for_record = crate::types::instance(ctx, expected_ty);
    unify_expression_types(tctx, loc, record_ty, expected_inst_for_record, None)?;
    // OCaml `check_duplicates` (compiler/ml/typecore.ml:2232-2245) runs after
    // every field is typed and the record type is unified with the expected
    // type (typecore.ml:3054-3055, 3134-3135), over the lbl_pos-sorted list.
    for pair in explicit_entries.windows(2) {
        let [(lbl1, _, _), (lbl2, lid2, _)] = pair else {
            continue;
        };
        if lbl1.lbl_pos == lbl2.lbl_pos {
            return Err(TypeCoreError::LabelMultiplyDefined {
                loc: lid2.loc,
                label: lbl1.lbl_name.to_string(),
                jsx_component_info: jsx_component_error_info.clone(),
            });
        }
    }

    if typed_base.is_none() {
        let labels_missing: Vec<String> = match record_family.as_ref() {
            // `written_labels` and `labels_missing` (typecore.ml:387-391,
            // 3081-3097): the mandatory labels the literal does not write, in
            // `lbl_all` order. A record whose labels are all optional, like
            // the hundreds of host element props of JsxDOM.domProps, cannot
            // miss one, so it skips the per-label `written` table.
            Some(family) if family.iter().all(|label| label.lbl_optional) => Vec::new(),
            Some(family) => {
                let written = record_written_labels(family.len(), &explicit_entries);
                family
                    .iter()
                    .filter(|label| !written[label.lbl_pos as usize] && !label.lbl_optional)
                    .map(|label| label.lbl_name.to_string())
                    .collect()
            }
            // OCaml typecore.ml:3060-3080: `{}` of the expected concrete
            // record misses its mandatory fields; with none it is
            // `Empty_record_literal`.
            _ => match expected_record_info.as_ref().map(|(_, _, decl)| &decl.type_kind) {
                Some(crate::types::TypeKind::TypeRecord(labels, _)) => labels
                    .iter()
                    .filter(|ld| !ld.ld_optional)
                    .map(|ld| ld.ld_id.name().to_string())
                    .collect(),
                _ => return Err(TypeCoreError::EmptyRecordLiteral { loc }),
            },
        };
        if !labels_missing.is_empty() {
            return Err(TypeCoreError::LabelsMissing {
                loc,
                labels: labels_missing,
                jsx_component_info: jsx_component_error_info.clone(),
            });
        }
    }

    // Match OCaml's unify_kept (typecore.ml:2755-2770):
    // For each label in the record type, create two instance_label calls.
    // Instance 1 connects to the base expression type.
    // For non-overridden labels, instance 2 connects to the expected type,
    // with ty_arg1 = ty_arg2 bridging them. This propagates type constraints
    // from the expected type (e.g., component<stateless, noRetainedProps, _>)
    // through to the base expression's type params.
    fn constr_path_is_persistent(path: &Path) -> bool {
        match path.view() {
            PathView::Pident(id) => id.is_persistent(),
            PathView::Pdot(parent, _, _) => constr_path_is_persistent(parent),
            PathView::Papply(_, _) => false,
        }
    }

    if let Some(ref mut typed_base_expr) = typed_base {
        // OCaml: let ty_exp = instance env exp.exp_type
        let mut ty_exp = crate::types::instance(ctx, typed_base_expr.exp_type);
        // Keep OCaml's identity split for persistent constructor heads only.
        // Local constructor families (e.g. mario_game viewport) should keep
        // sharing to avoid over-allocation and id drift.
        if ctx.repr(ty_exp) == ctx.repr(typed_base_expr.exp_type) {
            let repr = ctx.repr(ty_exp);
            let desc = ctx.get_desc(repr);
            if let TypeDesc::Tconstr { path, .. } = &*desc {
                if constr_path_is_persistent(path) {
                    let fresh = ctx.new_type(*desc);
                    if ctx.get_level(fresh) != ctx.get_level(repr) {
                        ctx.set_level(fresh, ctx.get_level(repr));
                    }
                    ty_exp = fresh;
                }
            }
        }
        typed_base_expr.exp_type = ty_exp;

        // `unify_kept` over `lbl.lbl_all` of the first written label
        // (typecore.ml:3137-3151); a spread literal writes at least one field.
        let family = record_family
            .as_ref()
            .expect("a record spread writes a label of a declared record");
        let base_loc = typed_base_expr.exp_loc;
        // `written_labels lbl.lbl_all lbl_exp_list` (typecore.ml:3138).
        let written = record_written_labels(family.len(), &explicit_entries);
        for env_label in family.iter() {
            // Instance 1: connect to the base expression; OCaml `unify_kept`
            // raises from each unification.
            let (_poly1, ty_arg1, ty_res1) =
                crate::types::ctype::instance_label(ctx, false, env_label);
            unify_expression_types(tctx, base_loc, ty_exp, ty_res1, None)?;

            // Do not connect result types for written labels.
            if !written[env_label.lbl_pos as usize] {
                // Instance 2: connect to the expected type, bridging the two
                // instances through their argument types.
                let (_poly2, ty_arg2, ty_res2) =
                    crate::types::ctype::instance_label(ctx, false, env_label);
                unify_expression_types(tctx, loc, ty_arg1, ty_arg2, None)?;
                let expected_inst = crate::types::instance(ctx, expected_ty);
                unify_expression_types(tctx, loc, expected_inst, ty_res2, None)?;
            }
        }
    }

    if typed_base.is_some() {
        // typecore.ml:3154-3165    if typed_base.is_some() {
        // typecore.ml:3154-3165 reads `Array.length lbl.lbl_all` of the first
        // label.
        let num_fields = record_family.as_ref().map(|family| family.len());
        if num_fields.is_some_and(|num_fields| fields.len() == num_fields) {
            tctx.report_warning(loc, Warning::UselessRecordWith);
            typed_base = None;
        }
    }

    // Preserve OCaml-style identity split between the record expression result
    // type and the `with` base expression type for persistent constructor
    // families only.
    if let Some(base_expr) = typed_base.as_mut() {
        let mut output_ty = crate::types::instance(ctx, base_expr.exp_type);
        if ctx.repr(output_ty) == ctx.repr(record_ty) {
            let repr = ctx.repr(output_ty);
            let desc = ctx.get_desc(repr);
            if let TypeDesc::Tconstr { path, .. } = &*desc {
                if constr_path_is_persistent(path) {
                    let fresh = ctx.new_type(*desc);
                    if ctx.get_level(fresh) != ctx.get_level(repr) {
                        ctx.set_level(fresh, ctx.get_level(repr));
                    }
                    output_ty = fresh;
                }
            }
        }
        base_expr.exp_type = output_ty;
    }

    // OCaml compiler/ml/typecore.ml:2788 unifies `ty_record` with
    // `instance env ty_expected`, then typecore.ml:2859-2866 stores the
    // record expression with `exp_type = instance env ty_expected`. The
    // record-update branch repeats the same shape at typecore.ml:2926 and
    // typecore.ml:2983-2990. Keep this as a fresh post-unify instance rather
    // than the original expected node so later application unification observes
    // the same typedtree sharing and force order.
    let record_exp_ty = crate::types::instance(ctx, expected_ty);

    // `record_fields lbl_exp_list` (typecore.ml:393-402): only the written
    // fields, already in `lbl_pos` order.
    // OCaml typecore.ml:3058-3063: `{}` takes the expected concrete record's
    // representation (`repr_opt` from `extract_concrete_record`); written
    // fields carry theirs in their labels.
    let empty_representation = explicit_entries.is_empty().then(|| {
        Box::new(
            expected_record_info
                .as_ref()
                .and_then(|(_, _, decl)| match &decl.type_kind {
                    crate::types::TypeKind::TypeRecord(_, repr) => Some(repr.clone()),
                    _ => None,
                })
                .unwrap_or(crate::types::RecordRepresentation::RecordRegular),
        )
    });
    let exp_desc = ExpressionDesc::Texp_record {
        fields: tctx.typed.push_record_fields(explicit_entries),
        empty_representation,
        extended_expression: typed_base.map(|e| tctx.push_expr(e)),
    };

    Ok({
        let typed_node = Expression::new(
            exp_desc,
            loc,
            record_exp_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

fn attributes_include_jsx_component_props(attrs: &[crate::types::decl::Attribute]) -> bool {
    attrs
        .iter()
        .any(|attr| attr.attr_name.txt == "res.jsxComponentProps")
}

/// `Error_message_utils.path_to_jsx_component_name` (error_message_utils.ml:888-891):
/// the path segment before a final `props`.
fn jsx_component_name_from_props_path(path: &Path) -> Option<String> {
    let name = path.name();
    let mut segments = name.split('.').rev();
    match (segments.next(), segments.next()) {
        (Some("props"), Some(component_name)) => Some(component_name.to_string()),
        _ => None,
    }
}

fn jsx_prop_error_info_from_record_parts(
    path: &Path,
    labels: &[crate::types::decl::LabelDeclaration],
    attrs: &[crate::types::decl::Attribute],
) -> Option<JsxPropErrorInfo> {
    let jsx_type = if path.last() == "fragmentProps" {
        JsxPropKind::Fragment
    } else if path.last() == "props" && attributes_include_jsx_component_props(attrs) {
        JsxPropKind::CustomComponent
    } else {
        return None;
    };

    Some(JsxPropErrorInfo {
        component_name: jsx_component_name_from_props_path(path),
        props: labels
            .iter()
            .map(|label| label.ld_id.name().to_string())
            .collect(),
        jsx_type,
    })
}

fn jsx_prop_error_info_for_record_ty(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    record_ty: TypeExprRef,
) -> Option<JsxPropErrorInfo> {
    let (path, _args, decl) =
        extract_concrete_record_type_info(record_ty, env, &mut tctx.persistent_env, tctx.type_ctx)?;
    let crate::types::TypeKind::TypeRecord(labels, _repr) = &decl.type_kind else {
        return None;
    };
    jsx_prop_error_info_from_record_parts(&path, labels, &decl.type_attributes)
}

fn wrong_record_field_name_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    record_ty: TypeExprRef,
    field_name: &str,
    expected: &'static str,
) -> Option<TypeCoreError> {
    let (path, _args, decl) =
        extract_concrete_record_type_info(record_ty, env, &mut tctx.persistent_env, tctx.type_ctx)?;
    let crate::types::TypeKind::TypeRecord(labels, _repr) = &decl.type_kind else {
        return None;
    };
    let alternatives = labels
        .iter()
        .map(|label| label.ld_id.name().to_string())
        .collect::<Vec<_>>();
    let jsx_component_info =
        jsx_prop_error_info_from_record_parts(&path, labels, &decl.type_attributes);

    Some(TypeCoreError::WrongName {
        loc,
        kind: "record",
        ty: record_ty,
        expected,
        path,
        name: field_name.to_string(),
        alternatives,
        jsx_component_info: jsx_component_info.map(Box::new),
        env: Some(tctx.type_ctx.store_typed_env(env)),
    })
}

/// Create a ConstructorDescription for the `Some` constructor.
fn make_some_constructor(ctx: &TypeContext) -> crate::types::ConstructorDescription {
    let (inner_ty, option_ty) = ctx.predef_option_scheme();
    crate::types::ConstructorDescription {
        cstr_name: "Some".to_string(),
        cstr_res: option_ty,
        cstr_existentials: vec![],
        cstr_args: vec![inner_ty],
        cstr_arity: 1,
        cstr_kind: crate::types::ConstructorKind::Ordinary(crate::types::ConstructorReference {
            variant: ctx.predef_option_layout(),
            position: 1,
        }),
        cstr_generalized: false,
        cstr_private: crate::types::PrivateFlag::Public,
        cstr_loc: crate::types::DeclLoc::none(),
        cstr_attributes: vec![crate::types::decl::internal_optional_attr()],
        cstr_inlined: None,
    }
}

/// Create a ConstructorDescription for the `None` constructor.
fn make_none_constructor(ctx: &TypeContext) -> crate::types::ConstructorDescription {
    let (_, option_ty) = ctx.predef_option_scheme();
    crate::types::ConstructorDescription {
        cstr_name: "None".to_string(),
        cstr_res: option_ty,
        cstr_existentials: vec![],
        cstr_args: vec![],
        cstr_arity: 0,
        cstr_kind: crate::types::ConstructorKind::Ordinary(crate::types::ConstructorReference {
            variant: ctx.predef_option_layout(),
            position: 0,
        }),
        cstr_generalized: false,
        cstr_private: crate::types::PrivateFlag::Public,
        cstr_loc: crate::types::DeclLoc::none(),
        cstr_attributes: vec![crate::types::decl::internal_optional_attr()],
        cstr_inlined: None,
    }
}

/// Get all label declarations for a record type from the environment.
fn get_record_labels(
    ctx: &TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ty: TypeExprRef,
) -> Option<Vec<crate::types::decl::LabelDeclaration>> {
    with_record_labels(ctx, env, pers_env, ty, <[_]>::to_vec)
}

/// `get_record_labels` that lends the labels to `f` instead of copying them.
fn with_record_labels<R>(
    ctx: &TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ty: TypeExprRef,
    f: impl FnOnce(&[crate::types::decl::LabelDeclaration]) -> R,
) -> Option<R> {
    if let Some((_path, _actual_args, type_decl)) =
        extract_concrete_record_type_info(ty, env, pers_env, ctx)
    {
        if let crate::types::TypeKind::TypeRecord(ref labels, _) = type_decl.type_kind {
            return Some(f(labels));
        }
    }

    let repr = ctx.repr(ty);
    let desc = ctx.get_desc(repr);
    if let crate::types::TypeDesc::Tconstr { ref path, .. } = *desc {
        // For inline records in extension/exception constructors, the type path
        // is the constructor path. Match the constructor by path, not by bare
        // name, otherwise exception/extension inline records pick up unrelated
        // constructors with the same short name.
        let cstr_name = path.last();
        let mut matches_inline_record_path =
            |cstr: &crate::types::decl::ConstructorDescription| match &cstr.cstr_kind {
                crate::types::ConstructorKind::Extension(ext_path) => ext_path.same(path),
                crate::types::ConstructorKind::Ordinary(_) => {
                    let cstr_res = ctx.repr(cstr.cstr_res);
                    let cstr_res_desc = ctx.get_desc(cstr_res);
                    let Some(matches_parent) = (match &*cstr_res_desc {
                        TypeDesc::Tconstr { path: res_path, .. } => match path.view() {
                            PathView::Pdot(parent, name, _) if name == &cstr.cstr_name => Some(
                                parent.same(res_path)
                                    || compare_type_paths_for_disambiguation(
                                        parent, res_path, env, pers_env, ctx,
                                    ),
                            ),
                            _ => None,
                        },
                        _ => None,
                    }) else {
                        return false;
                    };
                    matches_parent
                }
            };

        for cstr in env.find_all_constructors(cstr_name).iter().rev() {
            if matches_inline_record_path(cstr) {
                if let Some(ref inlined) = cstr.cstr_inlined {
                    if let crate::types::TypeKind::TypeRecord(ref labels, _) = inlined.type_kind {
                        return Some(f(labels));
                    }
                }
            }
        }
    }
    None
}

fn constructor_matches_inline_record_path(
    path: &Path,
    cstr: &crate::types::decl::ConstructorDescription,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> bool {
    if cstr.cstr_inlined.is_none() {
        return false;
    }

    match &cstr.cstr_kind {
        crate::types::ConstructorKind::Extension(ext_path) => ext_path.same(path),
        crate::types::ConstructorKind::Ordinary(_) => {
            let cstr_res = ctx.repr(cstr.cstr_res);
            let cstr_res_desc = ctx.get_desc(cstr_res);
            match &*cstr_res_desc {
                TypeDesc::Tconstr { path: res_path, .. } => match path.view() {
                    PathView::Pdot(parent, name, _) if name == &cstr.cstr_name => {
                        parent.same(res_path)
                            || compare_type_paths_for_disambiguation(
                                parent, res_path, env, pers_env, ctx,
                            )
                    }
                    _ => false,
                },
                _ => false,
            }
        }
    }
}

fn inline_record_decl_from_variant_type(
    ctx: &crate::types::context::TypeContext,
    type_decl: &crate::types::TypeDeclaration,
    cstr_name: &str,
) -> Option<crate::types::TypeDeclaration> {
    let crate::types::TypeKind::TypeVariant(ref constrs, layout) = type_decl.type_kind else {
        return None;
    };

    for (position, cd) in constrs.iter().enumerate() {
        if cd.cd_id.name() == cstr_name {
            let crate::types::ConstructorArguments::CstrRecord(ref labels) = cd.cd_args else {
                return None;
            };
            let inline_params = inline_record_type_params(ctx, labels);
            let inline_repr =
                if type_decl.type_representation == crate::types::TypeRepresentation::Unboxed {
                    // compiler/ml/datarepr.ml:163-164: unboxed inline records use `Record_unboxed true`.
                    crate::types::RecordRepresentation::RecordUnboxed(true)
                } else {
                    crate::types::RecordRepresentation::RecordInlined {
                        name: cstr_name.to_string(),
                        representation: crate::types::ConstructorReference {
                            variant: layout,
                            position,
                        },
                    }
                };
            return Some(crate::types::TypeDeclaration {
                type_params: inline_params.clone(),
                type_arity: inline_params.len() as i32,
                type_kind: crate::types::TypeKind::TypeRecord(
                    crate::types::decl::SharedVec::from(labels.clone()),
                    inline_repr,
                ),
                type_private: type_decl.type_private,
                type_manifest: None,
                type_variance: inline_params
                    .iter()
                    .map(|_| crate::types::variance::Variance::full())
                    .collect(),
                type_newtype_level: None,
                type_loc: cd.cd_loc,
                type_attributes: vec![],
                type_immediate: false,
                type_representation: crate::types::TypeRepresentation::Boxed,
                type_shape: crate::types::ValueShape::Unstated,
                type_inlined_types: vec![],
                type_path: None,
            });
        }
    }

    None
}

fn lookup_inline_record_decl_for_path(
    path: &Path,
    actual_args: &[TypeExprRef],
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, Vec<TypeExprRef>, Arc<crate::types::TypeDeclaration>)> {
    if let PathView::Pdot(parent_path, cstr_name, _) = path.view() {
        if let Some(parent_decl) = lookup_type_decl_for_path(parent_path, env, pers_env, ctx) {
            if let Some(inline_decl) =
                inline_record_decl_from_variant_type(ctx, &parent_decl, cstr_name)
            {
                return Some((*path, actual_args.to_vec(), Arc::new(inline_decl)));
            }
        }
    }

    for cstr in env.find_all_constructors(path.last()).iter().rev() {
        if constructor_matches_inline_record_path(path, cstr, env, pers_env, ctx) {
            if let Some(inlined) = &cstr.cstr_inlined {
                return Some((
                    *path,
                    actual_args.to_vec(),
                    Arc::new((**inlined).clone()),
                ));
            }
        }
    }

    None
}

/// Type check field access.
fn type_field(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    record_expr: &ParsedExpression,
    field_lid: &Located<LidentIdx>,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let resolved_lid = tctx.resolve_lid(field_lid.txt).clone();
    let field_name = tctx.longident_last_name(&resolved_lid);

    // Match OCaml type_label_access: type record first, then disambiguate.
    let typed_record = type_expect_with_recarg(
        tctx,
        env,
        record_expr,
        tctx.type_ctx.new_var(None),
        None,
        RecArg::Allowed,
    )?;
    let ty_exp = typed_record.exp_type;
    // typecore.ml `type_label_access`: `someDict.name` points to `Dict.get`.
    if expands_to_dict(tctx.type_ctx, env, ty_exp) {
        return Err(TypeCoreError::FieldAccessOnDictType { loc: field_lid.loc });
    }
    // OCaml typecore.ml:3648-3669 computes `opath` with
    // `extract_concrete_typedecl`, but only keeps it for concrete records.
    // Non-record constructors such as option/array must not drive label
    // disambiguation; if a label with the requested name is in scope, OCaml
    // selects it and lets the receiver unification report the type clash.
    let record_type_info =
        extract_concrete_record_type_info(ty_exp, env, &mut tctx.persistent_env, tctx.type_ctx);
    let label_expected_record_ty = record_type_info.as_ref().map(|_| ty_exp);

    if let Some(err) = label_expected_record_ty.and_then(|expected_record_ty| {
        qualified_label_name_type_mismatch(
            field_lid.loc,
            &resolved_lid,
            tctx.arena,
            env,
            &mut tctx.persistent_env,
            tctx.type_ctx,
            expected_record_ty,
        )
    }) {
        return Err(err);
    }

    // Disambiguate label: use the record expression's type to find the right label
    let env_label = if let Some(label) = lookup_label_by_lid(
        tctx,
        &resolved_lid,
        Some(field_lid.loc),
        env,
        label_expected_record_ty,
        None,
    ) {
        Some(label)
    } else if matches!(resolved_lid, Longident::Ldot(..)) {
        // OCaml `find_all_labels` on a qualified label only reads that module's
        // labels, and `Name_choice.lookup_from_type` (typecore.ml:852-891) only
        // matches unqualified names, so a miss is `Unbound_label (lid, Some ty)`.
        if let Some(err) = unbound_module_prefix_error(tctx, env, field_lid.loc, &resolved_lid) {
            return Err(err);
        }
        let ty_exp_repr = tctx.type_ctx.repr(ty_exp);
        return Err(TypeCoreError::UnboundRecordField {
            loc: field_lid.loc,
            field_name: tctx.longident_to_string(&resolved_lid),
            from_type: Some(ty_exp_repr),
            alternatives: unbound_label_alternatives(
                tctx.arena,
                env,
                &mut tctx.persistent_env,
                tctx.type_ctx,
                &resolved_lid,
            ),
        });
    } else {
        disambiguate_label(
            &field_name,
            label_expected_record_ty.unwrap_or_else(|| tctx.type_ctx.new_var(None)),
            env,
            &mut tctx.persistent_env,
            tctx.type_ctx,
        )
    };
    if label_expected_record_ty.is_none()
        && matches!(resolved_lid, Longident::Lident(_))
        && let Some(label) = env_label.as_ref()
    {
        warn_ambiguous_label_access(tctx, env, field_lid.loc, &field_name, label);
    }

    let (label_desc, field_ty, ty_res) = if let Some(env_label) = env_label {
        let (_poly_vars, ty_arg, ty_res) =
            crate::types::ctype::instance_label(tctx.type_ctx, false, &env_label);
        let module_access_path = {
            let ty_res_repr = tctx.type_ctx.repr(ty_res);
            let ty_res_desc = tctx.type_ctx.get_desc(ty_res_repr);

            if let TypeDesc::Tconstr { path, .. } = &*ty_res_desc {
                path.parent()
            } else {
                None
            }
        };
        if let Some(module_path) = module_access_path {
            if is_local_module_access_path(&module_path) {
                let mut visited_arg = HashSet::new();
                qualify_module_local_type_paths_from_module_descr_in_place(
                    tctx.type_ctx,
                    env,
                    &mut tctx.persistent_env,
                    ty_arg,
                    &module_path,
                    &mut visited_arg,
                );
                let mut visited_res = HashSet::new();
                qualify_module_local_type_paths_from_module_descr_in_place(
                    tctx.type_ctx,
                    env,
                    &mut tctx.persistent_env,
                    ty_res,
                    &module_path,
                    &mut visited_res,
                );
            }
        }
        (env_label, ty_arg, ty_res)
    } else {
        if let Some(err) = wrong_record_field_name_error(
            tctx,
            env,
            field_lid.loc,
            ty_exp,
            &field_name,
            "This expression has",
        ) {
            return Err(err);
        }
        // OCaml `type_label_access` (compiler/ml/typecore.ml:3848) calls
        // `Typetexp.find_all_labels`, which raises `Unbound_label` when no
        // label with this name is in scope, whatever the receiver type is.
        let ty_exp_repr = tctx.type_ctx.repr(ty_exp);
        let from_type = matches!(
            &*tctx.type_ctx.borrow_desc(ty_exp_repr),
            TypeDesc::Tconstr { .. }
        )
        .then_some(ty_exp_repr);
        return Err(TypeCoreError::UnboundRecordField {
            loc: field_lid.loc,
            field_name: tctx.longident_to_string(&resolved_lid),
            from_type,
            alternatives: unbound_label_alternatives(
                tctx.arena,
                env,
                &mut tctx.persistent_env,
                tctx.type_ctx,
                &resolved_lid,
            ),
        });
    };

    // OCaml compiler/ml/typecore.ml:2993-3005 types `Pexp_field` by
    // `type_label_access`, `instance_label`, and `unify_exp`, then returns
    // `ty_arg` without recursively forcing paths inside the field argument type.
    unify_expression_types(
        tctx,
        proper_exp_loc(&tctx.typed, &typed_record),
        ty_exp,
        ty_res,
        None,
    )?;
    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_field(
                tctx.push_expr(typed_record),
                *field_lid,
                std::sync::Arc::new(label_desc),
            ),
            loc,
            field_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

/// Type check field assignment.
#[allow(clippy::too_many_arguments)]
fn type_setfield(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    record_expr: &ParsedExpression,
    field_lid: &Located<LidentIdx>,
    new_value: &ParsedExpression,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    let unit_ty = env.type_unit(ctx);
    let resolved_lid = tctx.resolve_lid(field_lid.txt).clone();
    let field_name = tctx.longident_last_name(&resolved_lid);
    let field_context_name = field_name;
    // Match field-access disambiguation: type the record expression first,
    // then pick the label based on the resolved record type.
    let record_ty = ctx.new_var(None);
    // OCaml compiler/ml/typecore.ml:3006-3013 routes setfield receivers through
    // `type_label_access`, which types the receiver with `recarg:Allowed` at
    // compiler/ml/typecore.ml:3648-3650 so inline-record payload variables may be
    // used for field updates without escaping their constructor scope.
    let typed_record =
        type_expect_with_recarg(tctx, env, record_expr, record_ty, None, RecArg::Allowed)?;
    let ty_exp = typed_record.exp_type;
    // typecore.ml `type_label_access`: `someDict.name` points to `Dict.get`.
    if expands_to_dict(ctx, env, ty_exp) {
        return Err(TypeCoreError::FieldAccessOnDictType { loc: field_lid.loc });
    }
    // `type_label_access` (typecore.ml:3648-3669): `opath` is only the
    // receiver's concrete record path; other types (option, ...) do not drive
    // label disambiguation, and the receiver unification reports the clash.
    let record_type_info =
        extract_concrete_record_type_info(ty_exp, env, &mut tctx.persistent_env, ctx);
    let label_expected_record_ty = record_type_info.as_ref().map(|_| ty_exp);

    if let Some(err) = label_expected_record_ty.and_then(|expected_record_ty| {
        qualified_label_name_type_mismatch(
            field_lid.loc,
            &resolved_lid,
            tctx.arena,
            env,
            &mut tctx.persistent_env,
            ctx,
            expected_record_ty,
        )
    }) {
        return Err(err);
    }

    let env_label = lookup_label_by_lid(
        tctx,
        &resolved_lid,
        Some(field_lid.loc),
        env,
        label_expected_record_ty,
        None,
    )
    .or_else(|| {
        disambiguate_label(
            &field_name,
            label_expected_record_ty.unwrap_or_else(|| ctx.new_var(None)),
            env,
            &mut tctx.persistent_env,
            ctx,
        )
    });
    if matches!(resolved_lid, Longident::Lident(_))
        && let Some(label) = env_label.as_ref()
        && extract_concrete_record_type_info(ty_exp, env, &mut tctx.persistent_env, ctx).is_none()
    {
        warn_ambiguous_label_access(tctx, env, field_lid.loc, &field_name, label);
    }
    // `Label.disambiguate` calls the chosen label's `use ()`, which marks its
    // type (`Env.lookup_all_labels`, env.ml:1230-1238).
    if let Some(label) = env_label.as_ref() {
        mark_type_path_of(tctx.type_ctx, env, label.lbl_res);
    }
    // OCaml typecore.ml:2948: `let ty_record = if opath = None then newvar ()
    // else record.exp_type`, where `opath` is the receiver's concrete record
    // path (`type_label_access`).
    let ty_record = if extract_concrete_record_type_info(ty_exp, env, &mut tctx.persistent_env, ctx)
        .is_some()
    {
        ty_exp
    } else {
        ctx.new_var(None)
    };
    // OCaml compiler/ml/typecore.ml:3703-3743 (`type_label_exp`) opens a
    // definition scope before `instance_label` and keeps it open through
    // `type_argument`; setfield values must see the same raised level as record
    // literal fields.
    ctx.begin_def();
    let field_result =
        (|| -> TypeCoreResult<(crate::types::LabelDescription, Vec<TypeExprRef>, Expression)> {
            let (label_desc, field_ty, poly_vars) = if let Some(env_label) = env_label {
                let separate = env.has_local_constraints();
                if separate {
                    // OCaml compiler/ml/typecore.ml:3706-3716 opens two extra scopes
                    // for local constraints around `instance_label`.
                    ctx.begin_def();
                    ctx.begin_def();
                }
                // OCaml compiler/ml/typecore.ml:3711 uses `instance_label true` for
                // both record creation and setfield.
                let (poly_vars, ty_arg0, ty_res0) =
                    crate::types::ctype::instance_label(ctx, true, &env_label);
                if separate {
                    ctx.end_def();
                    crate::types::generalize_structure(ctx, ctx.current_level(), ty_arg0);
                    crate::types::generalize_structure(ctx, ctx.current_level(), ty_res0);
                }

                let module_access_path = {
                    let ty_res_repr = ctx.repr(ty_res0);
                    let ty_res_desc = ctx.get_desc(ty_res_repr);

                    if let TypeDesc::Tconstr { path, .. } = &*ty_res_desc {
                        path.parent()
                    } else {
                        None
                    }
                };
                if let Some(module_path) = module_access_path {
                    if is_local_module_access_path(&module_path) {
                        let mut visited_arg = HashSet::new();
                        qualify_module_local_type_paths_from_module_descr_in_place(
                            ctx,
                            env,
                            &mut tctx.persistent_env,
                            ty_arg0,
                            &module_path,
                            &mut visited_arg,
                        );
                        let mut visited_res = HashSet::new();
                        qualify_module_local_type_paths_from_module_descr_in_place(
                            ctx,
                            env,
                            &mut tctx.persistent_env,
                            ty_res0,
                            &module_path,
                            &mut visited_res,
                        );
                    }
                }

                // OCaml compiler/ml/typecore.ml:3717-3721 unifies an instance of the
                // label result with the expected record type (raising
                // `Label_mismatch` at the label), then instances the field
                // argument before typing the assigned value.
                let ty_res = crate::types::ctype::instance(ctx, ty_res0);
                let expected_record_ty = crate::types::ctype::instance(ctx, ty_record);
                let label_result_unify =
                    crate::types::unify(ctx, &mut tctx.unify_state, ty_res, expected_record_ty)
                        .map_err(|err| TypeCoreError::LabelMismatch {
                            loc: field_lid.loc,
                            lid: resolved_lid.clone(),
                            trace: match err {
                                TypeError::Unify(trace) => trace,
                                _ => vec![(ty_res, expected_record_ty)],
                            },
                            env: Some(tctx.type_ctx.store_typed_env(env)),
                        });
                let field_ty = crate::types::ctype::instance(ctx, ty_arg0);

                if separate {
                    // OCaml compiler/ml/typecore.ml:3722-3725 closes the second local
                    // constraint scope after instantiating the field argument.
                    ctx.end_def();
                    crate::types::generalize_structure(ctx, ctx.current_level(), field_ty);
                }
                label_result_unify?;

                (env_label, field_ty, poly_vars)
            } else {
                if let Some(err) = wrong_record_field_name_error(
                    tctx,
                    env,
                    field_lid.loc,
                    ty_exp,
                    &field_name,
                    "This expression has",
                ) {
                    return Err(err);
                }
                // OCaml `type_label_access` (compiler/ml/typecore.ml:3848):
                // `Typetexp.find_all_labels` raises `Unbound_label`.
                let ty_exp_repr = ctx.repr(ty_exp);
                let from_type = matches!(&*ctx.borrow_desc(ty_exp_repr), TypeDesc::Tconstr { .. })
                    .then_some(ty_exp_repr);
                return Err(TypeCoreError::UnboundRecordField {
                    loc: field_lid.loc,
                    field_name: tctx.longident_to_string(&resolved_lid),
                    from_type,
                    alternatives: unbound_label_alternatives(
                        tctx.arena,
                        env,
                        &mut tctx.persistent_env,
                        tctx.type_ctx,
                        &resolved_lid,
                    ),
                });
            };

            let field_context = Some(ClashSite::SetRecordField {
                field_name: crate::name::Name::new(&field_context_name),
            });
            let typed_value = type_expect(tctx, env, new_value, field_ty, field_context)?;
            // OCaml compiler/ml/typecore.ml:3740-3743 uses `type_argument`, which
            // types against `ty_arg` and then unifies with `instance env ty_arg`.
            let field_ty_inst = crate::types::ctype::instance(ctx, field_ty);
            unify_expression_types(tctx, loc, typed_value.exp_type, field_ty_inst, None)?;

            Ok((label_desc, poly_vars, typed_value))
        })();
    ctx.end_def();
    let (label_desc, poly_vars, mut typed_value) = field_result?;

    if !poly_vars.is_empty() {
        crate::types::ctype::check_univars(ctx, &poly_vars);
    }
    // OCaml compiler/ml/typecore.ml:3779 returns `{arg with exp_type =
    // instance env arg.exp_type}` from `type_label_exp`.
    typed_value.exp_type = crate::types::ctype::instance(ctx, typed_value.exp_type);
    // OCaml typecore.ml:2953: `unify_exp env record ty_record`.
    unify_expression_types(
        tctx,
        proper_exp_loc(&tctx.typed, &typed_record),
        typed_record.exp_type,
        ty_record,
        None,
    )?;

    if label_desc.lbl_mut == crate::types::MutableFlag::Immutable {
        return Err(TypeCoreError::LabelNotMutable {
            loc,
            lid: resolved_lid,
        });
    }
    if label_desc.lbl_private == crate::types::PrivateFlag::Private
        && extract_concrete_record_type_info(
            label_desc.lbl_res,
            env,
            &mut tctx.persistent_env,
            tctx.type_ctx,
        )
        .is_some_and(|(_, _, decl)| decl.type_private == crate::types::PrivateFlag::Private)
    {
        tctx.report_warning(
            field_lid.loc,
            Warning::BsPrivateRecordMutation {
                field_name: field_context_name.to_string(),
            },
        );
    }

    // OCaml typecore.ml:2961-2969: `rue { ... exp_type = instance_def
    // Predef.type_unit }`, i.e. `unify_exp env exp (instance env ty_expected)`.
    rue_unify(tctx, loc, unit_ty, expected_ty, context)?;

    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_setfield(
                tctx.push_expr(typed_record),
                *field_lid,
                std::sync::Arc::new(label_desc),
                tctx.push_expr(typed_value),
            ),
            loc,
            unit_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

/// Type check type constraint.
fn type_constraint(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    sexp: &ParsedExpression,
    inner_expr: &ParsedExpression,
    core_type: &crate::parser::ast::CoreType,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    let loc = sexp.pexp_loc;
    let attributes: &[crate::parser::ast::Attribute] = &sexp.pexp_attributes;
    let ctx = tctx.type_ctx;

    // Match OCaml typecore.ml Pexp_constraint:
    // begin_def; transl_simple_type; end_def; generalize_structure;
    // type_argument env sarg ty (instance env ty); exp_type = instance env ty.
    ctx.begin_def();
    let (typed_ctype, ctype_ty) = transl_type(tctx, env, core_type)?;
    ctx.end_def();
    let var_level = ctx.current_level();
    crate::types::generalize_structure(ctx, var_level, ctype_ty);

    // Match OCaml's right-to-left tuple evaluation order in Pexp_constraint:
    //   (type_argument env sarg ty (instance env ty), instance env ty)
    // evaluates as:
    //   1. result_ty = instance env ty     (second element first)
    //   2. arg_unify_ty = instance env ty  (arg to type_argument)
    //   3. type_expect env sarg ty         (inside type_argument)
    //   4. unify_exp env texp arg_unify_ty (type_argument's post-unify)
    //   5. rue { exp_type = result_ty }    (outer rue)
    //
    // Both instances are created BEFORE type_expect runs, so they see the
    // GENERIC ctype_ty before any handler can consume it via unification.
    let result_ty = crate::types::instance(ctx, ctype_ty);
    let arg_unify_ty = crate::types::instance(ctx, ctype_ty);

    // Pass the GENERIC constraint type to type_expect (matches OCaml).
    // Rue handlers create per-expression instances via rue_unify.
    // Non-rue handlers (tuple, array, construct) use instance_if_generic
    // to avoid corrupting the generic type.
    let typed_inner = type_expect(tctx, env, inner_expr, ctype_ty, None)?;
    unify_expression_types(tctx, loc, typed_inner.exp_type, arg_unify_ty, None)?;

    rue_unify(tctx, loc, result_ty, expected_ty, context)?;

    let mut result = typed_inner;
    result.exp_type = result_ty;
    let extra = (
        crate::types::typedtree::ExpExtra::Texp_constraint(tctx.typed.push_core_type(typed_ctype)),
        loc,
        attributes.to_vec().into(),
    );
    tctx.typed.prepend_exp_extra(&mut result, extra);
    Ok(result)
}

/// OCaml stores expression extras with list-cons, so outer wrappers appear
/// before inner wrappers in `exp_extra`.
fn prepend_exp_extra(
    ta: &mut TypedArena,
    mut expr: Expression,
    extra: crate::types::typedtree::ExpExtra,
    loc: LocIdx,
    attrs: Attributes,
) -> Expression {
    ta.prepend_exp_extra(&mut expr, (extra, loc, attrs));
    expr
}

/// Type check type coercion.
#[allow(clippy::too_many_arguments)]
fn type_coerce(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    inner_expr: &ParsedExpression,
    opt_from_type: Option<&crate::parser::ast::CoreType>,
    to_type: &crate::parser::ast::CoreType,
    expected_ty: TypeExprRef,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    // Translate the target type.
    let (to_typed_ctype, to_ty) = transl_type(tctx, env, to_type)?;

    let (typed_inner, trial_ok) = if let Some(from_type) = opt_from_type {
        let (_from_typed_ctype, from_ty) = transl_type(tctx, env, from_type)?;
        (type_expect(tctx, env, inner_expr, from_ty, None)?, false)
    } else {
        // OCaml compiler/ml/typecore.ml:3295-3339 always separates coercion
        // argument typing: begin_def(), type_exp, end_def(), then
        // generalizable/unify_var before the non-generalizable fast coercion
        // attempt calls compiler/ml/ctype.ml:2797 `Ctype.unify`.
        ctx.begin_def();
        let typed_inner = type_exp(tctx, env, inner_expr, None)?;
        ctx.end_def();

        let scope_var = ctx.new_var(None);
        let is_generalizable =
            generalizable_at_level(ctx, ctx.get_level(scope_var), typed_inner.exp_type);
        crate::types::ctype::unify_var(ctx, &mut tctx.unify_state, scope_var, typed_inner.exp_type)
            .map_err(|err| TypeCoreError::ExprTypeClash {
                loc,
                trace: match err {
                    TypeError::Unify(trace) => trace,
                    _ => vec![(scope_var, typed_inner.exp_type)],
                },
                context: None,
                env: Some(tctx.type_ctx.store_typed_env(env)),
            })?;

        // typecore.ml `Pexp_coerce`: for a non-generalizable source, first
        // try unification with an enlarged approximation of the target
        // (`Ctype.enlarge_type`) under a snapshot; on failure backtrack and
        // fall back to subtype constraints.
        let trial_ok = !is_generalizable && {
            let coerce_snapshot = ctx.snapshot_type_state();
            let (enlarged, _) = crate::types::ctype::enlarge_type(ctx, env, to_ty);
            let mut coerce_unify_state = UnifyState::new();
            coerce_unify_state.set_env(env);
            let coerce_result =
                crate::types::unify(ctx, &mut coerce_unify_state, typed_inner.exp_type, enlarged);
            if coerce_result.is_err() {
                ctx.restore_type_state(coerce_snapshot);
                false
            } else {
                true
            }
        };
        (typed_inner, trial_ok)
    };

    if !trial_ok {
        // OCaml typecore.ml: `let force' = subtype env arg.exp_type ty' in
        // force (); force' ()`.
        let subtype_cstrs = crate::types::ctype::subtype(ctx, env, typed_inner.exp_type, to_ty)
            .map_err(|err| not_subtype_error(ctx, env, loc, err, typed_inner.exp_type, to_ty))?;
        crate::types::ctype::force_subtype(ctx, env, subtype_cstrs)
            .map_err(|err| not_subtype_error(ctx, env, loc, err, typed_inner.exp_type, to_ty))?;
    }

    // typecore.ml Pexp_coerce builds `Texp_coerce {source_type =
    // expand_head env arg.exp_type; target = cty'; target_type = expand_head
    // env ty'}` before `rue`; the record's fields evaluate right to left.
    let target_type = crate::types::ctype::expand_head(ctx, env, to_ty);
    let source_type = crate::types::ctype::expand_head(ctx, env, typed_inner.exp_type);

    // OCaml `rue { exp_type = ty'; ... }` (typecore.ml:3295-3305, 2369-2371)
    // after the coercion check: `unify_exp` at the coercion's location
    // (`proper_exp_loc`) of `ty'` with `instance env ty_expected`.
    let inst_expected = instance_if_generic(ctx, expected_ty);
    unify_expression_types(tctx, loc, to_ty, inst_expected, None)?;

    // Return the inner expression with the coercion as exp_extra
    // The expression type becomes the target type after coercion
    let target = tctx.typed.push_core_type(to_typed_ctype);
    let mut result = prepend_exp_extra(
        &mut tctx.typed,
        typed_inner,
        crate::types::typedtree::ExpExtra::Texp_coerce {
            source_type,
            target,
            target_type,
        },
        loc,
        attributes.to_vec().into(),
    );
    result.exp_type = to_ty;
    Ok(result)
}

/// Type check open expression.
fn type_open(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    sexp: &ParsedExpression,
    override_flag: &crate::parser::ast::OverrideFlag,
    lid: &Located<LidentIdx>,
    body: &ParsedExpression,
    expected_ty: TypeExprRef,
) -> TypeCoreResult<Expression> {
    let loc = sexp.pexp_loc;
    let attributes: &[crate::parser::ast::Attribute] = &sexp.pexp_attributes;
    // Open the module's bindings into scope for the body
    let open_lid = tctx.arena.get_longident(lid.txt);
    let mut open_env = env.clone();
    // OCaml `type_open_` (typemod.ml:88-95): `Typetexp.lookup_module`, then
    // `Env.open_signature ~loc ovf path env`.
    mark_open_lid_use(
        tctx.type_ctx,
        env,
        tctx.arena,
        open_lid,
        crate::types::env::OpenLookupKind::Module,
        Some(lid.loc),
    );
    let slot = tctx.open_signature_slot(*override_flag, loc);

    let persistent_root_open = match open_lid {
        Longident::Lident(mod_idx) => {
            let mod_name = tctx.arena.get_string(*mod_idx);
            if env.find_module(mod_name).is_err() {
                if let Some(pers) = tctx.persistent_env.as_mut() {
                    // OCaml compiler/ml/typemod.ml:88-90 implements
                    // expression `open` through `Typetexp.lookup_module`
                    // followed by `Env.open_signature`. For persistent roots,
                    // compiler/ml/env.ml:658-672 precomputes `ps_comps`, and
                    // env.ml:1874-1877 opens those components. The component
                    // builder at env.ml:1516-1588 applies prefix substitution
                    // and `Subst.modtype_declaration` through the cached
                    // component table instead of forcing `ps_sig`.
                    // env.ml:1012: `Pident (Ident.create_persistent s)`.
                    let root =
                        Path::pident(tctx.type_ctx.create_ast_persistent_ident(tctx.arena, *mod_idx));
                    if pers.open_module(mod_name, root, &mut open_env, tctx.type_ctx, slot) {
                        Some(root)
                    } else {
                        None
                    }
                } else {
                    None
                }
            } else {
                None
            }
        }
        _ => None,
    };

    // Resolve through Env alias scraping and rewritten signatures so opened
    // bindings preserve OCaml-style module prefixes in types.
    let path = if let Some(path) = persistent_root_open {
        path
    } else if let Some(path) = open_module_lid_components_into_env(
        open_lid,
        tctx.arena,
        &env.clone(),
        &mut open_env,
        &mut tctx.persistent_env,
        tctx.type_ctx,
        slot,
    ) {
        path
    } else {
        let open_lid = open_lid.clone();
        match crate::types::typemod::open_failure_path(tctx, env, tctx.arena, &open_lid, lid.loc) {
            Ok(path) => path,
            Err(crate::types::typemod::TypeModError::CoreError(err)) => return Err(err),
            Err(err) => return Err(TypeCoreError::ModuleError(Box::new(err))),
        }
    };

    tctx.set_open_slot_root(slot, &path);

    // Type check the body expression in the extended environment
    let typed_body = type_expect(tctx, &open_env, body, expected_ty, None)?;

    // Return expression with Texp_open in exp_extra (matching OCaml)
    Ok(prepend_exp_extra(
        &mut tctx.typed,
        typed_body,
        crate::types::typedtree::ExpExtra::Texp_open(*override_flag, path, *lid, EnvRef(0)),
        loc,
        attributes.to_vec().into(),
    ))
}

/// `type_expression` of `type_let` (typecore.ml:5061-5081): an unconstrained
/// binding of the let `type_function` synthesizes for an optional parameter's
/// default is typed with the `` `Function `` match context.
fn type_value_binding_expression(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    binding: &crate::parser::ast::ValueBinding,
    expected_ty: TypeExprRef,
    let_check: LetCheck,
) -> TypeCoreResult<Expression> {
    if let Some(expression) = tctx
        .arena
        .value_constraint(binding.pvb_pat)
        .and_then(|constraint| constraint.pvc_expression)
    {
        let expression = tctx.arena.get_expanded_expr(expression).clone();
        type_expect(tctx, env, &expression, expected_ty, None)
    } else {
        let expression = tctx.arena.get_expanded_expr(binding.pvb_expr).clone();
        let match_context = (let_check == LetCheck::FakeOptional).then_some(MatchContext::Function);
        type_expect_full(
            tctx,
            env,
            &expression,
            expected_ty,
            None,
            RecArg::Rejected,
            match_context,
        )
    }
}

/// `Error (loc, env, Not_subtype (tr1, tr2, ctx))` from a `Ctype.Subtype`.
fn not_subtype_error(
    ctx: &TypeContext,
    env: &Env,
    loc: LocIdx,
    err: TypeError,
    ty1: TypeExprRef,
    ty2: TypeExprRef,
) -> TypeCoreError {
    let (trace, trace2, context) = match err {
        TypeError::Subtype {
            trace,
            trace2,
            context,
        } => (trace, trace2, context),
        _ => (vec![(ty1, ty2)], Vec::new(), None),
    };
    TypeCoreError::NotSubtype {
        loc,
        trace,
        trace2,
        context,
        env: Some(ctx.store_typed_env(env)),
    }
}

/// Type check newtype expression.
fn type_newtype(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    name: &Located<StrIdx>,
    body: &ParsedExpression,
    expected_ty: TypeExprRef,
    _attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    let name_str = tctx.arena.get_string(name.txt).to_string();
    let replacement_ty = ctx.new_var(None);

    // Match OCaml compiler/ml/typecore.ml:3462-3488:
    // create the replacement type, begin a definition scope, reserve the
    // replacement type's level in the ident stamp counter, enter the local
    // abstract type, then reset the definition level to Ident.current_time()
    // before typing the body.
    ctx.begin_def();
    let result = (|| -> TypeCoreResult<Expression> {
        let level = ctx.current_level();
        let mut new_env = env.clone();
        ctx.set_current_time(ctx.get_level(replacement_ty));
        // Use the shared stamp counter (ctx.create_ident) so the newtype ident
        // participates in the same stamp sequence as other typed-tree idents.
        // This matches OCaml where Env.enter_type uses Ident.create.
        let newtype_id = ctx.create_ident(&name_str);
        new_env.add_type(
            newtype_id,
            crate::types::decl::TypeDeclaration {
                type_params: vec![],
                type_arity: 0,
                type_kind: crate::types::decl::TypeKind::TypeAbstract,
                type_private: crate::types::asttypes::PrivateFlag::Public,
                type_manifest: None,
                type_variance: vec![],
                type_newtype_level: Some((level, level)),
                type_loc: tctx.intern_ast_loc(tctx.arena, loc),
                type_attributes: vec![],
                type_immediate: false,
                type_representation: crate::types::decl::TypeRepresentation::Boxed,
                type_shape: crate::types::ValueShape::Unstated,
                type_inlined_types: vec![],
                type_path: None,
            },
        );
        // `Env.enter_type` registers the unused-type check (env.ml:1593-1597,
        // 1562-1572); lookups of the type mark it used.
        tctx.check_type_usage(&name_str, convert_loc(loc, tctx.arena), loc);
        ctx.init_def(ctx.current_stamp());

        // OCaml types the newtype body with type_exp (no expected type).
        // Use a fresh variable here to avoid constraining the body early.
        let body_ty = ctx.new_var(None);
        let typed_body = type_expect(tctx, &new_env, body, body_ty, None)?;

        // Subst.type_expr Subst.identity in OCaml: full structural copy
        // (copies ALL nodes regardless of level, unlike copy_type which
        // returns identity for non-generic nodes). This ensures
        // replace_newtype_path only modifies the copy, not shared originals.
        let rewritten_ty = crate::types::ctype::subst_identity_copy(ctx, typed_body.exp_type);

        fn replace_newtype_path(
            ctx: &TypeContext,
            ty: TypeExprRef,
            target_id: &Ident,
            replacement_ty: TypeExprRef,
            seen: &mut HashSet<TypeExprRef>,
            used: &mut bool,
        ) {
            let ty = ctx.repr(ty);
            if !seen.insert(ty) {
                return;
            }

            let should_replace = matches!(
                &*ctx.get_desc(ty),
                TypeDesc::Tconstr { path, .. }
                    if path.as_pident().is_some_and(|id| id.same(target_id))
            );

            if should_replace {
                *used = true;
                crate::types::link_type(ctx, ty, replacement_ty);
                return;
            }

            crate::types::iter_type_expr(ctx, ty, |child| {
                replace_newtype_path(ctx, child, target_id, replacement_ty, seen, used);
            });
        }

        let mut seen = HashSet::new();
        let mut used = false;
        replace_newtype_path(
            ctx,
            rewritten_ty,
            &newtype_id,
            replacement_ty,
            &mut seen,
            &mut used,
        );

        // OCaml: rue { ... exp_type = ety; ... }
        rue_unify(tctx, loc, rewritten_ty, expected_ty, None)?;

        Ok(Expression {
            exp_loc: loc,
            exp_type: rewritten_ty,
            ..typed_body
        })
    })();
    ctx.end_def();
    result
}

/// Type check await expression.
#[allow(clippy::too_many_arguments)]
/// Type a promise primitive using the ordinary application rule.
/// Cost: one existing primitive lookup and one operand check; the one-argument
/// slice is stack borrowed, with no parsed node, list or location allocation.
fn type_promise_application(
    tctx: &mut TypeCheckContext<'_>, env: &Env, source: &ParsedExpression,
    operand: crate::parse_arena::ExprIdx, primitive: Located<LidentIdx>,
    expected: &mut Expected, context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    tctx.set_unify_env(env);
    let result = type_application_parts(tctx, env, source, primitive.loc, &[],
        ApplicationCallee::Promise(primitive), &[(ArgLabel::Nolabel, operand)],
        false, false, expected, context)?;
    finish_expected_at(tctx, source, primitive.loc, result.exp_type, expected, context)?;
    Ok(result)
}

/// typecore.ml `object_valid_fields`.
fn object_valid_fields(ctx: &TypeContext, env: &Env, ty: TypeExprRef) -> Option<Vec<String>> {
    let expanded = crate::types::ctype::expand_head(ctx, env, ty);
    let fields = match &*ctx.get_desc(expanded) {
        TypeDesc::Tobject { fields } => *fields,
        _ => return None,
    };
    // `List.fold_left collect_fields []` over `Ctype.flatten_fields fields`
    // (sorted by name), prepending each field.
    let (fields, _) = crate::types::ctype::flatten_fields(ctx, fields);
    Some(
        fields
            .into_iter()
            .rev()
            .map(|field| field.name.to_string())
            .collect(),
    )
}

fn method_name_is_plain_ident(name: &str) -> bool {
    let mut chars = name.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if !first.is_ascii_alphabetic() {
        return false;
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

/// typecore.ml `object_field_use_type`: eliminate an object-field scheme for
/// a read. A declared field payload is wrapped in `Tpoly`: an empty binder
/// list needs ordinary instantiation, a nonempty list polymorphic
/// instantiation. An inferred field whose scheme is not known yet can still
/// be a variable; constrain it to the ordinary, empty-binder form.
fn object_field_use_type(
    tctx: &mut TypeCheckContext<'_>,
    typ: TypeExprRef,
) -> Result<TypeExprRef, TypeError> {
    let ctx = tctx.type_ctx;
    let typ = ctx.repr(typ);
    let desc = *ctx.get_desc(typ);
    match desc {
        TypeDesc::Tpoly { body, vars } if vars.is_empty() => {
            Ok(crate::types::ctype::instance(ctx, body))
        }
        TypeDesc::Tpoly { body, vars } => {
            Ok(crate::types::ctype::instance_poly(ctx, false, false, ctx.type_list(vars), body).1)
        }
        TypeDesc::Tvar(..) => {
            let ty2 = ctx.new_var(None);
            let poly = ctx.new_poly(ty2, vec![]);
            let inst = crate::types::ctype::copy_type(ctx, typ);
            crate::types::unify(ctx, &mut tctx.unify_state, inst, poly)?;
            Ok(ty2)
        }
        _ => unreachable!("object_field_use_type"),
    }
}

/// typecore.ml `Pexp_object_get`.
#[allow(clippy::too_many_arguments)]
fn type_object_get(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    obj_expr: &ParsedExpression,
    field: &Located<std::borrow::Cow<'static, str>>,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;

    // Type the object expression first (OCaml `type_exp` path).
    let obj_ty = ctx.new_var(None);
    let mut typed_obj = type_expect(tctx, env, obj_expr, obj_ty, None)?;
    if let ExpressionDesc::Texp_ident(_, _, desc) = &typed_obj.exp_desc {
        if let crate::types::ValueKind::ValPrim(prim) = &desc.val_kind {
            let val_ty = ctx.repr(desc.val_type);
            let val_desc = ctx.get_desc(val_ty);
            if method_name_is_plain_ident(&prim.prim_name)
                && method_name_is_plain_ident(field.txt.as_ref())
                && matches!(&*val_desc, TypeDesc::Tconstr { args, .. } if args.is_empty())
            {
                typed_obj.exp_type = desc.val_type;
            }
        }
    }

    // Lookup constrains an open object row to contain the field, without
    // requiring or adding write capability.
    let field_ty = crate::types::ctype::filter_method(ctx, env, &field.txt, typed_obj.exp_type)
        .and_then(|typ| object_field_use_type(tctx, typ));
    let field_ty = match field_ty {
        Ok(ty) => ty,
        Err(_) => {
            return Err(TypeCoreError::UndefinedMethod {
                loc: Some(obj_expr.pexp_loc),
                ty: typed_obj.exp_type,
                method: field.txt.to_string(),
                alternatives: object_valid_fields(ctx, env, typed_obj.exp_type),
            });
        }
    };

    rue_unify(tctx, loc, field_ty, expected_ty, context)?;

    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_object_get(
                tctx.push_expr(typed_obj),
                Located {
                    txt: field.txt.to_string(),
                    loc: field.loc,
                },
            ),
            loc,
            field_ty,
            EnvRef(0),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

/// typecore.ml `Pexp_object_set`.
#[allow(clippy::too_many_arguments)]
fn type_object_set(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    obj_expr: &ParsedExpression,
    field: &Located<std::borrow::Cow<'static, str>>,
    svalue: &ParsedExpression,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    let obj_ty = ctx.new_var(None);
    let typed_obj = type_expect(tctx, env, obj_expr, obj_ty, None)?;
    // Assignment can add or promote a field only while its object row is
    // open. The result distinguishes a missing field from a closed immutable
    // field so the two cases retain their respective diagnostics.
    let field_typ = crate::types::ctype::filter_object_field_for_write(
        ctx,
        env,
        &field.txt,
        typed_obj.exp_type,
    )
    .unwrap_or(Err(
        crate::types::ctype::ObjectFieldWriteError::OwriteMissing,
    ));
    let typ = match field_typ {
        Err(crate::types::ctype::ObjectFieldWriteError::OwriteMissing) => {
            return Err(TypeCoreError::UndefinedMethod {
                loc: Some(obj_expr.pexp_loc),
                ty: typed_obj.exp_type,
                method: field.txt.to_string(),
                alternatives: object_valid_fields(ctx, env, typed_obj.exp_type),
            });
        }
        Err(crate::types::ctype::ObjectFieldWriteError::OwriteNotMutable) => {
            return Err(TypeCoreError::ObjectFieldNotMutable {
                loc,
                ty: typed_obj.exp_type,
                name: field.txt.to_string(),
            });
        }
        Ok(typ) => typ,
    };
    let value = type_object_field_value(tctx, env, svalue, typ)?;
    let unit_ty = env.type_unit(ctx);
    rue_unify(tctx, loc, unit_ty, expected_ty, context)?;
    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_object_set(
                tctx.push_expr(typed_obj),
                Located {
                    txt: field.txt.to_string(),
                    loc: field.loc,
                },
                tctx.push_expr(value),
            ),
            loc,
            unit_ty,
            EnvRef(0),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

/// typecore.ml `type_object_field_value`: introduce the right-hand side of an
/// object-field assignment at the field's scheme. A polymorphic field accepts
/// only a value at least as general as the scheme.
fn type_object_field_value(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    svalue: &ParsedExpression,
    typ: TypeExprRef,
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    let typ = ctx.repr(typ);
    let poly = match &*ctx.get_desc(typ) {
        TypeDesc::Tpoly { body, vars } if !vars.is_empty() => {
            Some((*body, ctx.type_list(vars).to_vec()))
        }
        _ => None,
    };
    match poly {
        Some((body, vars)) => {
            ctx.begin_def();
            let (vars, ty2) = crate::types::ctype::instance_poly(ctx, false, true, crate::types::type_expr::PoolSlice::from(&vars), body);
            let value = type_expect(tctx, env, svalue, ty2, None);
            ctx.end_def();
            let mut value = value?;
            check_univars_or_less_general(tctx, env, true, "field value", &value, typ, &vars)?;
            value.exp_type = crate::types::ctype::instance(ctx, value.exp_type);
            Ok(value)
        }
        None => {
            let typ =
                object_field_use_type(tctx, typ).map_err(|err| TypeCoreError::ExprTypeClash {
                    loc: svalue.pexp_loc,
                    trace: match err {
                        TypeError::Unify(trace) => trace,
                        _ => vec![],
                    },
                    context: None,
                    env: Some(tctx.type_ctx.store_typed_env(env)),
                })?;
            type_expect(tctx, env, svalue, typ, None)
        }
    }
}

/// typecore.ml `Pexp_object_literal`: fields are typed in source order. A
/// duplicate name is typed against the first occurrence's type and appears
/// once in the row.
fn type_object_literal(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    sfields: &[(
        Located<std::borrow::Cow<'static, str>>,
        crate::parse_arena::ExprIdx,
    )],
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    let mut seen: HashMap<String, TypeExprRef> = HashMap::new();
    let mut fields: Vec<(Located<String>, TExprIdx)> = Vec::with_capacity(sfields.len());
    for (name, sfield) in sfields {
        let sfield = tctx.arena.get_expanded_expr(*sfield);
        let field = match seen.get(name.txt.as_ref()).copied() {
            Some(ty) => type_expect(tctx, env, sfield, ty, None)?,
            None => {
                let field = type_exp(tctx, env, sfield, None)?;
                seen.insert(name.txt.to_string(), field.exp_type);
                field
            }
        };
        fields.push((
            Located {
                txt: name.txt.to_string(),
                loc: name.loc,
            },
            tctx.push_expr(field),
        ));
    }
    let mut emitted: HashSet<&str> = HashSet::new();
    let mut row = ctx.new_type(TypeDesc::Tnil);
    for (name, field) in fields.iter().rev() {
        if !emitted.insert(name.txt.as_str()) {
            continue;
        }
        let typ = ctx.new_poly(tctx.expr(*field).exp_type, vec![]);
        row = ctx.new_type(TypeDesc::Tfield {
            name: crate::name::Name::new(&name.txt),
            mutability: ctx.alloc_mutability(crate::types::type_expr::FieldMutability::Value(
                crate::types::asttypes::MutableFlag::Immutable,
            )),
            typ,
            rest: row,
        });
    }
    let exp_type = ctx.new_type(TypeDesc::Tobject { fields: row });
    rue_unify(tctx, loc, exp_type, expected_ty, context)?;
    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_object_literal(fields),
            loc,
            exp_type,
            EnvRef(0),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

/// Type check let exception.
fn type_letexception(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    ext_constr: &crate::parser::ast::ExtensionConstructor,
    body: &ParsedExpression,
    expected_ty: TypeExprRef,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let ctx = tctx.type_ctx;
    let arena = tctx.arena;

    let name_str = arena.get_string(ext_constr.pext_name.txt).to_string();
    let id = ctx.create_ident(&name_str);

    // Match OCaml's transl_exception: begin_def before creating arg types,
    // end_def + generalize after, so instance_constructor creates fresh copies.
    ctx.begin_def();
    let (typed_args, typed_ret, ext_args, cstr_args, cstr_inlined, ext_ret_ty) = match &ext_constr
        .pext_kind
    {
        crate::parser::ast::ExtensionConstructorKind::Pext_decl(args, ret) => {
            let mut arg_ty_refs = Vec::new();
            let (typed_args, ext_args, cstr_args, cstr_inlined) = match args {
                crate::parser::ast::ConstructorArguments::Pcstr_tuple(types) => {
                    let mut typed = Vec::new();
                    for ty in types {
                        let (typed_ct, ty_ref) = transl_type(tctx, env, arena.get_core_type(*ty))?;
                        arg_ty_refs.push(ty_ref);
                        typed.push(typed_ct);
                    }
                    (
                        crate::types::typedtree::ConstructorArgument::Cstr_tuple(
                            tctx.typed.push_core_types(typed),
                        ),
                        crate::types::ConstructorArguments::CstrTuple(arg_ty_refs.clone()),
                        arg_ty_refs.clone(),
                        None,
                    )
                }
                crate::parser::ast::ConstructorArguments::Pcstr_record(labels) => {
                    let mut typed_labels = Vec::new();
                    let mut decl_labels = Vec::new();
                    for label in labels {
                        let label_name = arena.get_string(label.pld_name.txt).to_string();
                        let (typed_ct, ty_ref) =
                            transl_type(tctx, env, arena.get_core_type(label.pld_type))?;
                        let poly_ty_ref = ctx.new_poly(ty_ref, vec![]);
                        let poly_typed_ct = crate::types::typedtree::TypedCoreType {
                            ctyp_desc: crate::types::typedtree::TypedCoreTypeDesc::Ttyp_poly(
                                vec![],
                                tctx.typed.push_core_type(typed_ct.clone()),
                            ),
                            ctyp_type: poly_ty_ref,
                            ctyp_env: typed_ct.ctyp_env,
                            ctyp_loc: typed_ct.ctyp_loc,
                            ctyp_attributes: Attributes::new(),
                        };
                        let label_id = ctx.create_ast_ident(arena, label.pld_name.txt);
                        typed_labels.push(crate::types::typedtree::LabelDeclaration {
                            ld_id: label_id,
                            ld_name: crate::parse_arena::Located {
                                txt: label_name.clone(),
                                loc: label.pld_name.loc,
                            },
                            ld_runtime_name: crate::types::record_runtime::parsetree_runtime_name(
                                label, arena,
                            ),
                            ld_mutable: label.pld_mutable,
                            ld_optional: label.pld_optional,
                            ld_type: tctx.typed.push_core_type(poly_typed_ct),
                            ld_loc: label.pld_loc,
                            ld_attributes: label.pld_attributes.clone(),
                        });
                        decl_labels.push(crate::types::decl::LabelDeclaration {
                            ld_id: label_id,
                            ld_runtime_name: crate::types::record_runtime::parsetree_runtime_name(
                                label, arena,
                            ),
                            ld_mutable: match label.pld_mutable {
                                crate::parser::ast::MutableFlag::Immutable => {
                                    crate::types::MutableFlag::Immutable
                                }
                                crate::parser::ast::MutableFlag::Mutable => {
                                    crate::types::MutableFlag::Mutable
                                }
                            },
                            ld_optional: label.pld_optional,
                            ld_type: poly_ty_ref,
                            ld_loc: tctx.intern_ast_loc(arena, label.pld_loc),
                            ld_attributes: vec![],
                        });
                    }
                    let inline_path = Path::pident(id);
                    // Match OCaml's newgenconstr: create at generic_level
                    let inline_ty = ctx.new_generic_constr(inline_path, vec![]);
                    let inline_decl = crate::types::TypeDeclaration {
                        type_params: vec![],
                        type_arity: 0,
                        type_kind: crate::types::TypeKind::TypeRecord(
                            crate::types::decl::SharedVec::from(decl_labels.clone()),
                            crate::types::RecordRepresentation::RecordExtension,
                        ),
                        type_private: crate::types::PrivateFlag::Public,
                        type_manifest: None,
                        type_variance: vec![],
                        type_newtype_level: None,
                        type_loc: crate::types::DeclLoc::none(),
                        type_attributes: vec![],
                        type_immediate: false,
                        type_representation: crate::types::TypeRepresentation::Boxed,
                        type_shape: crate::types::ValueShape::Unstated,
                        type_inlined_types: vec![],
                        type_path: None,
                    };
                    (
                        crate::types::typedtree::ConstructorArgument::Cstr_record(typed_labels),
                        crate::types::ConstructorArguments::CstrRecord(decl_labels),
                        vec![inline_ty],
                        Some(Box::new(inline_decl)),
                    )
                }
            };
            let (typed_ret, ext_ret_ty) = match ret {
                Some(ct) => {
                    let (typed_ct, ty_ref) = transl_type(tctx, env, arena.get_core_type(*ct))?;
                    (Some(typed_ct), Some(ty_ref))
                }
                None => (None, None),
            };
            (
                typed_args,
                typed_ret,
                ext_args,
                cstr_args,
                cstr_inlined,
                ext_ret_ty,
            )
        }
        crate::parser::ast::ExtensionConstructorKind::Pext_rebind(_lid) => (
            crate::types::typedtree::ConstructorArgument::Cstr_tuple(
                tctx.typed.push_core_types(vec![]),
            ),
            None,
            crate::types::ConstructorArguments::CstrTuple(vec![]),
            vec![],
            None,
            None,
        ),
    };
    ctx.end_def();

    // Generalize constructor arg types (matching OCaml's iter_type_expr_cstr_args generalize)
    match &ext_args {
        crate::types::ConstructorArguments::CstrTuple(types) => {
            for ty in types {
                crate::types::generalize(ctx, *ty);
            }
        }
        crate::types::ConstructorArguments::CstrRecord(labels) => {
            for label in labels {
                crate::types::generalize(ctx, label.ld_type);
            }
        }
    }
    if let Some(ret_ty) = ext_ret_ty {
        crate::types::generalize(ctx, ret_ty);
    }

    let exn_ty = ctx.new_generic_predef_constr(crate::types::predef::path_exn(), vec![]);
    let exn_path = Path::pident(id);
    let cstr_desc = crate::types::decl::ConstructorDescription {
        cstr_name: name_str.clone(),
        cstr_res: exn_ty,
        cstr_existentials: vec![],
        cstr_args: cstr_args.clone(),
        cstr_arity: cstr_args.len() as i32,
        cstr_kind: crate::types::ConstructorKind::Extension(exn_path),
        cstr_generalized: false,
        cstr_private: crate::types::PrivateFlag::Public,
        // `Datarepr.extension_descr`: `cstr_loc = ext.ext_loc = pext_loc`.
        cstr_loc: tctx.intern_ast_loc(arena, ext_constr.pext_loc),
        cstr_attributes: vec![],
        cstr_inlined: cstr_inlined.clone(),
    };

    let mut new_env = env.clone();
    // OCaml compiler/ml/env.ml:1693-1716 registers extension/exception
    // constructors through compiler/ml/datarepr.ml:190-214
    // `extension_descr`; inline-record labels stay in `cstr_inlined` and are
    // not inserted into `env.labels`.
    // typedecl.ml:1863: `Env.add_extension ~check:true`.
    tctx.check_extension_usage(
        "exn",
        &name_str,
        true,
        arena.to_location(ext_constr.pext_loc),
        ext_constr.pext_loc,
        env.is_in_signature(),
    );
    new_env.add_constructor(id, cstr_desc);

    let typed_body = type_expect(tctx, &new_env, body, expected_ty, None)?;

    let typed_ext_constr = crate::types::typedtree::ExtensionConstructor {
        ext_id: id,
        ext_name: crate::parse_arena::Located {
            txt: name_str,
            loc: ext_constr.pext_name.loc,
        },
        ext_type: crate::types::ExtensionConstructor {
            ext_type_path: crate::types::predef::path_exn(),
            ext_type_params: vec![],
            ext_args,
            ext_ret_type: ext_ret_ty,
            ext_private: crate::types::PrivateFlag::Public,
            ext_loc: tctx.intern_ast_loc(arena, ext_constr.pext_loc),
            ext_attributes: vec![],
            ext_is_exception: true,
        },
        ext_kind: crate::types::typedtree::ExtensionConstructorKind::Text_decl(
            typed_args,
            typed_ret.map(|ct| tctx.typed.push_core_type(ct)),
        ),
        ext_loc: ext_constr.pext_loc,
        ext_attributes: ext_constr.pext_attributes.clone(),
    };
    let body_ty = typed_body.exp_type;

    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_letexception(
                tctx.typed.push_extension_constructor(typed_ext_constr),
                tctx.push_expr(typed_body),
            ),
            loc,
            body_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

fn letmodule_path_root_is_module(path: &Path, module_id: &Ident) -> bool {
    match path.view() {
        PathView::Pident(id) => id.same(module_id),
        PathView::Pdot(prefix, _, _) => letmodule_path_root_is_module(prefix, module_id),
        PathView::Papply(_, _) => false,
    }
}

fn letmodule_replace_module_root_path(path: &Path, module_id: &Ident, alias_root: &Path) -> Path {
    match path.view() {
        PathView::Pident(id) => {
            if id.same(module_id) {
                *alias_root
            } else {
                *path
            }
        }
        PathView::Pdot(prefix, name, _) => {
            let rewritten_prefix =
                letmodule_replace_module_root_path(prefix, module_id, alias_root);
            if rewritten_prefix == *prefix {
                *path
            } else {
                Path::pdot(rewritten_prefix, *name)
            }
        }
        PathView::Papply(_, _) => *path,
    }
}

fn resolve_alias_root_from_module_type(
    env: &Env,
    mty: &crate::types::decl::ModuleType,
    visited: &mut HashSet<String>,
) -> Option<Path> {
    use crate::types::decl::ModuleType as DeclMty;

    match mty {
        DeclMty::MtyAlias(_, alias_path) => Some(**alias_path),
        DeclMty::MtyIdent(path) => match path.view() {
            PathView::Pident(id) => {
                let name = id.name();
                if !visited.insert(name.to_string()) {
                    return None;
                }

                if let Ok(mtd) = env.find_modtype(name) {
                    if let Some(inner_mty) = &mtd.mtd_type {
                        if let Some(alias_root) =
                            resolve_alias_root_from_module_type(env, inner_mty, visited)
                        {
                            return Some(alias_root);
                        }
                    }
                }

                if let Ok(md) = env.find_module(name) {
                    if let Some(alias_root) =
                        resolve_alias_root_from_module_type(env, &md.md_type, visited)
                    {
                        return Some(alias_root);
                    }
                }

                None
            }
            _ => Some(*path),
        },
        _ => None,
    }
}

fn resolve_letmodule_alias_root(env: &Env, module_id: &Ident) -> Option<Path> {
    let md = env.find_module(module_id.name_atom()).ok()?;
    let mut visited = HashSet::new();
    resolve_alias_root_from_module_type(env, &md.md_type, &mut visited)
}

fn replace_letmodule_local_paths(
    ctx: &TypeContext,
    env: &Env,
    ty: TypeExprRef,
    module_id: &Ident,
    seen: &mut HashSet<TypeExprRef>,
) {
    let ty = ctx.repr(ty);
    if !seen.insert(ty) {
        return;
    }

    let local_constr = match &*ctx.get_desc(ty) {
        TypeDesc::Tconstr { path, args, .. } if letmodule_path_root_is_module(path, module_id) => {
            Some((*path, *args))
        }
        _ => None,
    };

    if let Some((local_path, local_args)) = local_constr {
        // Match OCaml `Ctype.nondep_type`: for local module-rooted paths,
        // first try one-step abbreviation expansion.
        if let Some(expanded) = crate::types::ctype::expand_head_once(ctx, env, ty) {
            let expanded = ctx.repr(expanded);
            if expanded != ty {
                crate::types::link_type(ctx, ty, expanded);
                replace_letmodule_local_paths(ctx, env, expanded, module_id, seen);
                return;
            }
        }

        // If expansion is unavailable, try replacing the local root module
        // with its underlying alias root path (`MS.t` -> `Belt_MapString.t`).
        if let Some(alias_root) = resolve_letmodule_alias_root(env, module_id) {
            let rewritten_path =
                letmodule_replace_module_root_path(&local_path, module_id, &alias_root);
            if rewritten_path != local_path {
                let rewritten_ty =
                    ctx.new_constr(rewritten_path, ctx.type_list(local_args).to_vec());
                crate::types::link_type(ctx, ty, rewritten_ty);
                replace_letmodule_local_paths(ctx, env, rewritten_ty, module_id, seen);
                return;
            }
        }

        // OCaml keeps truly local abstract types visible here so the scoping
        // check can report that the type constructor would escape.
        return;
    }

    crate::types::iter_type_expr(ctx, ty, |child| {
        replace_letmodule_local_paths(ctx, env, child, module_id, seen);
    });
}

fn apply_letmodule_local_path_cleanup(
    ctx: &TypeContext,
    env: &Env,
    body_env: &Env,
    module_id: &Ident,
    rewritten_ty: TypeExprRef,
    expected_ty: TypeExprRef,
) {
    let mut seen: HashSet<TypeExprRef> = HashSet::new();
    replace_letmodule_local_paths(ctx, body_env, rewritten_ty, module_id, &mut seen);
    replace_letmodule_local_paths(ctx, body_env, expected_ty, module_id, &mut seen);
    for (_id, value_desc) in env.iter_values() {
        replace_letmodule_local_paths(ctx, body_env, value_desc.val_type, module_id, &mut seen);
    }
}

fn unbound_value_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Longident,
) -> TypeCoreError {
    let (name, qualifier) = match lid {
        Longident::Ldot(prefix, idx) => (
            tctx.arena.get_string(*idx).to_string(),
            Some(tctx.longident_to_string(prefix)),
        ),
        _ => (tctx.longident_to_string(lid), None),
    };
    let alternatives = unbound_value_alternatives(tctx, env, lid);
    let module_suggestion = unbound_value_module_suggestion(tctx, env, lid);
    TypeCoreError::UnboundValue {
        loc,
        name,
        qualifier,
        alternatives,
        module_suggestion,
    }
}

fn capitalize_ascii(name: &str) -> String {
    let mut chars = name.chars();
    let Some(first) = chars.next() else {
        return String::new();
    };
    let mut capitalized = first.to_ascii_uppercase().to_string();
    capitalized.push_str(chars.as_str());
    capitalized
}

/// typetexp.ml:853-862: `Env.lookup_module ~load:false (Lident (capitalize
/// name))`, which also finds a persistent unit other than the current one
/// (env.ml:1022-1048).
fn unbound_value_module_suggestion(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    lid: &Longident,
) -> Option<String> {
    let Longident::Lident(idx) = lid else {
        return None;
    };
    let candidate = capitalize_ascii(tctx.arena.get_string(*idx));
    if let Ok((path, _)) = env.find_module_with_path(&candidate) {
        // `Env.lookup_module` marks the module (and an open providing it)
        // used, which can report an open-shadowing warning right away.
        let lid = tctx
            .arena
            .get_longident(tctx.arena.push_typecheck_lident(&candidate))
            .clone();
        mark_open_lid_use(
            tctx.type_ctx,
            env,
            tctx.arena,
            &lid,
            crate::types::env::OpenLookupKind::Module,
            None,
        );
        return Some(format_arity_suggestion_path(&path));
    }
    let ctx = tctx.type_ctx;
    let pers = tctx.persistent_env.as_mut()?;
    if pers.compiling_module_name() == Some(candidate.as_str()) {
        return None;
    }
    pers.find_pers_struct(&candidate, ctx).map(|_| candidate)
}

/// OCaml `Typetexp.find_type` (compiler/ml/typetexp.ml): resolve a type
/// constructor or raise the narrowed unbound-module / unbound-type error.
pub(crate) fn find_type_for_lid(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    longident: &Longident,
) -> TypeCoreResult<(Path, Arc<crate::types::decl::TypeDeclaration>)> {
    let (path, type_decl) = resolve_type_constructor_path(tctx, env, longident, Some(loc));
    // `Env.lookup_type` marks the declaration used (env.ml:1174-1177).
    if let Some(decl) = type_decl.as_ref() {
        mark_type_used(
            tctx.type_ctx,
            env,
            tctx.longident_last_name_str(longident),
            tctx.resolve_loc(decl.type_loc),
        );
    }
    let Some(decl) = type_decl else {
        if let Some(error) = unbound_module_prefix_error(tctx, env, loc, longident) {
            return Err(error);
        }
        if let Some(error) = cannot_scrape_alias_type_constructor_error(tctx, env, loc, longident) {
            return Err(error);
        }
        return Err(TypeCoreError::UnboundTypeConstructor {
            loc,
            lid: longident.clone(),
            alternatives: unbound_type_constructor_alternatives(tctx, env, longident),
        });
    };
    Ok((path, decl))
}

pub(crate) fn unbound_module_prefix_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Longident,
) -> Option<TypeCoreError> {
    let Longident::Ldot(prefix, _) = lid else {
        return None;
    };
    narrowed_module_lookup_error(tctx, env, loc, prefix)
}

pub(crate) fn unbound_module_lookup_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Longident,
) -> TypeCoreError {
    narrowed_module_lookup_error(tctx, env, loc, lid).unwrap_or_else(|| {
        let alternatives = unbound_module_alternatives(tctx, env, lid);
        TypeCoreError::UnboundModule {
            loc,
            name: tctx.longident_to_string(lid),
            alternatives,
        }
    })
}

pub(crate) fn unbound_constructor_lookup_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Longident,
) -> TypeCoreError {
    if let Some(error) = unbound_module_prefix_error(tctx, env, loc, lid) {
        return error;
    }
    let alternatives = unbound_constructor_alternatives(tctx, env, lid);
    TypeCoreError::UnboundConstructor {
        loc,
        lid: lid.clone(),
        alternatives,
    }
}

// OCaml Typetexp.find_component narrows failed qualified lookups by checking
// each module prefix before reporting the original unbound identifier.
fn narrowed_module_lookup_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Longident,
) -> Option<TypeCoreError> {
    if let Longident::Ldot(prefix, _) = lid
        && let Some(error) = narrowed_module_lookup_error(tctx, env, loc, prefix)
    {
        return Some(error);
    }
    // `check_module` (compiler/ml/typetexp.ml:66-72): `Env.lookup_module`
    // raises `Recmodule` for a recursive module bound to its `#recmod#`
    // placeholder (compiler/ml/env.ml:1031-1034).
    if let Longident::Lident(name) = lid
        && let Ok((_, md)) = env.find_module_with_id(tctx.arena.get_string(*name))
        && crate::types::typemod::is_recursive_module_placeholder_type(&md.md_type)
    {
        return Some(TypeCoreError::IllegalReferenceToRecursiveModule { loc });
    }

    let Some(module_path) = env.resolve_module_access_path_for_lid(
        lid,
        tctx.arena,
        &mut tctx.persistent_env,
        tctx.type_ctx,
    ) else {
        let alternatives = unbound_module_alternatives(tctx, env, lid);
        return Some(TypeCoreError::UnboundModule {
            loc,
            name: tctx.longident_to_string(lid),
            alternatives,
        });
    };

    module_structure_lookup_error(tctx, env, loc, lid, &module_path)
}

/// Spelling-hint candidates for an unbound name: the local env table for
/// `Lident`, or the matching items of the prefix module's signature in
/// `Tbl.fold` order for `Ldot`.
fn unbound_name_alternatives(
    arena: &ParseArena,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &TypeContext,
    lid: &Longident,
    local_names: impl FnOnce(&Env) -> Vec<String>,
    mut item_names: impl FnMut(&crate::types::decl::SignatureItem, &mut Vec<String>),
) -> Vec<String> {
    match lid {
        Longident::Lident(_) => local_names(env),
        Longident::Ldot(prefix, _) => tbl_fold_names_list(
            env.resolve_module_lid_raw(prefix, arena, pers_env, ctx)
                .map(|(_, sig)| {
                    let mut names = Vec::new();
                    for item in sig.iter() {
                        item_names(item, &mut names);
                    }
                    names
                })
                .unwrap_or_default(),
        ),
        Longident::Lapply(_, _) => Vec::new(),
    }
}

fn unbound_module_alternatives(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    lid: &Longident,
) -> Vec<String> {
    unbound_name_alternatives(
        tctx.arena,
        env,
        &mut tctx.persistent_env,
        tctx.type_ctx,
        lid,
        Env::fold_module_names,
        |item, names| {
            if let crate::types::decl::SignatureItem::SigModule(id, _, _) = item {
                names.push(id.name().to_string());
            }
        },
    )
}

/// The name list a `Tbl.fold` over a structure's components builds by consing
/// (compiler/ml/env.ml:1938-1945): one entry per name, visited in ascending
/// name order, so the list is descending.
fn tbl_fold_names_list(mut names: Vec<String>) -> Vec<String> {
    names.sort_unstable_by(|a, b| b.as_bytes().cmp(a.as_bytes()));
    names.dedup();
    names
}

fn unbound_type_constructor_alternatives(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    lid: &Longident,
) -> Vec<String> {
    unbound_name_alternatives(
        tctx.arena,
        env,
        &mut tctx.persistent_env,
        tctx.type_ctx,
        lid,
        Env::fold_type_names,
        |item, names| {
            if let crate::types::decl::SignatureItem::SigType(id, _, _) = item {
                names.push(id.name().to_string());
            }
        },
    )
}

fn unbound_constructor_alternatives(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    lid: &Longident,
) -> Vec<String> {
    unbound_name_alternatives(
        tctx.arena,
        env,
        &mut tctx.persistent_env,
        tctx.type_ctx,
        lid,
        Env::fold_constructor_names,
        |item, names| match item {
            crate::types::decl::SignatureItem::SigType(_, decl, _) => {
                if let crate::types::decl::TypeKind::TypeVariant(constructors, _) = &decl.type_kind
                {
                    names.extend(
                        constructors
                            .iter()
                            .map(|cstr| cstr.cd_id.name().to_string()),
                    );
                }
            }
            crate::types::decl::SignatureItem::SigTypext(id, _, _) => {
                names.push(id.name().to_string());
            }
            _ => {}
        },
    )
}

fn unbound_label_alternatives(
    arena: &ParseArena,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &TypeContext,
    lid: &Longident,
) -> Vec<String> {
    unbound_name_alternatives(
        arena,
        env,
        pers_env,
        ctx,
        lid,
        Env::fold_label_names,
        |item, names| {
            if let crate::types::decl::SignatureItem::SigType(_, decl, _) = item
                && let crate::types::decl::TypeKind::TypeRecord(labels, _) = &decl.type_kind
            {
                names.extend(labels.iter().map(|label| label.ld_id.name().to_string()));
            }
        },
    )
}

fn module_structure_lookup_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    lid: &Longident,
    module_path: &Path,
) -> Option<TypeCoreError> {
    let Ok(md) = env.lookup_module(module_path) else {
        return None;
    };

    match crate::types::typemod::scrape_alias_module_type(
        &md.md_type,
        env,
        &mut tctx.persistent_env,
        tctx.type_ctx,
    ) {
        Some(crate::types::decl::ModuleType::MtyFunctor { .. }) => {
            Some(TypeCoreError::AccessFunctorAsStructure {
                loc,
                lid: lid.clone(),
            })
        }
        None => module_alias_error_for_lid(tctx, env, loc, lid),
        Some(_) => None,
    }
}

fn unbound_value_alternatives(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    lid: &Longident,
) -> Vec<String> {
    unbound_name_alternatives(
        tctx.arena,
        env,
        &mut tctx.persistent_env,
        tctx.type_ctx,
        lid,
        Env::fold_value_names,
        |item, names| {
            if let crate::types::decl::SignatureItem::SigValue(id, _) = item {
                names.push(id.name().to_string());
            }
        },
    )
}

pub(crate) fn check_inlined_record_escape(
    ctx: &TypeContext,
    loc: LocIdx,
    ty: TypeExprRef,
    recarg: RecArg,
) -> TypeCoreResult<()> {
    if matches!(recarg, RecArg::Allowed) {
        return Ok(());
    }

    {
        let desc = ctx.borrow_desc(ty);
        match (recarg, &*desc) {
            (RecArg::Rejected, TypeDesc::Tconstr { path, .. }) => {
                if path.is_constructor_typath() {
                    return Err(TypeCoreError::InlinedRecordEscape { loc });
                }
                return Ok(());
            }
            (RecArg::Rejected, TypeDesc::Tlink(_)) => {}
            (RecArg::Rejected, _) => return Ok(()),
            (RecArg::Required, TypeDesc::Tconstr { path, .. }) => {
                if !path.is_constructor_typath() {
                    return Err(TypeCoreError::InlinedRecordEscape { loc });
                }
                return Ok(());
            }
            (RecArg::Required, TypeDesc::Tvar(..)) => {
                return Err(TypeCoreError::InlinedRecordEscape { loc });
            }
            (RecArg::Required, TypeDesc::Tlink(_)) => {}
            (RecArg::Required, _) => return Ok(()),
            (RecArg::Allowed, _) => return Ok(()),
        }
    }

    let repr = ctx.repr(ty);
    let desc = ctx.borrow_desc(repr);
    let is_recarg = match &*desc {
        TypeDesc::Tconstr { path, .. } => path.is_constructor_typath(),
        _ => false,
    };
    let escapes = match (is_recarg, recarg, &*desc) {
        (_, RecArg::Allowed, _) => false,
        (true, RecArg::Required, _) | (false, RecArg::Rejected, _) => false,
        (true, RecArg::Rejected, _)
        | (false, RecArg::Required, TypeDesc::Tvar(..) | TypeDesc::Tconstr { .. }) => true,
        (false, RecArg::Required, _) => false,
    };

    if escapes {
        Err(TypeCoreError::InlinedRecordEscape { loc })
    } else {
        Ok(())
    }
}

/// Type check let module expression.
#[allow(clippy::too_many_arguments)]
fn type_letmodule(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    name: &Located<StrIdx>,
    module_expr: &crate::parser::ast::ModuleExpr,
    body: &ParsedExpression,
    expected_ty: TypeExprRef,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    let arena = tctx.arena;
    let ctx = tctx.type_ctx;
    let mod_name_str = arena.get_string(name.txt).to_string();
    let letmodule_ty = ctx.new_var(None);

    // Match OCaml `Pexp_letmodule` level scoping (`begin_def`/`end_def`).
    // Mirror Typetexp.narrow()/widen() so module typing does not clobber
    // outer expression type variables (e.g. `'self` in @this callbacks).
    let narrow_global_level = ctx.increase_global_level();
    let saved_type_variables = tctx.type_variables.clone();
    ctx.begin_def();
    // OCaml advances the ident stamp to the fresh let-module result type's
    // level before typing the module expression.
    ctx.set_current_time(ctx.get_level(letmodule_ty));
    let letmodule_def_level = ctx.current_level();
    let scoped_result = (|| -> TypeCoreResult<(
        crate::types::typedtree::ModuleExpr,
        Ident,
        Env,
        Expression,
        TypeExprRef,
    )> {
        // OCaml compiler/ml/typecore.ml:3399-3406 calls the Typemod hook for
        // every `Pexp_letmodule`, then passes `modl.mod_type` directly to
        // `Env.enter_module`. That route is important for Pmod_structure because
        // compiler/ml/typemod.ml:1263-1282 inserts an implicit Tmod_constraint
        // when `simplify_signature` removes duplicate value names.
        let typed_mod = crate::types::typemod::type_module_expr_with_alias_mode(
            tctx,
            env,
            arena,
            module_expr,
            true,
        )
        .map_err(|e| TypeCoreError::ModuleError(Box::new(e)))?;
        let mut mod_sig = typed_mod.mod_type.clone();

        // Keep let-module member lookups stable for direct module aliases
        // (`module M = List` / constrained direct idents) by materializing
        // aliases/identifiers to signatures when the environment can resolve them.
        let materialize_alias_sig = match &module_expr.pmod_desc {
            crate::parser::ast::ModuleExprDesc::Pmod_ident(_) => true,
            crate::parser::ast::ModuleExprDesc::Pmod_constraint(inner, _) => {
                matches!(
                    &arena.get_mod_expr(*inner).pmod_desc,
                    crate::parser::ast::ModuleExprDesc::Pmod_ident(_)
                )
            }
            _ => false,
        };
        if materialize_alias_sig
            && matches!(
                &mod_sig,
                crate::types::decl::ModuleType::MtyIdent(_)
            )
        {
            if let Some(sig) = crate::types::typemod::resolve_mod_type_to_sig(
                &mod_sig,
                Some(env),
                &mut tctx.persistent_env,
                ctx,
            ) {
                mod_sig = crate::types::decl::ModuleType::MtySignature(Arc::new(sig));
            }
        }

        // Add the module to the environment so the body can access M.value
        let mod_id = ctx.create_ident(&mod_name_str);
        let mut body_env = env.clone();
        let md_decl = crate::types::decl::ModuleDeclaration {
            md_type: mod_sig,
            md_attributes: vec![],
            md_loc: crate::types::DeclLoc::none(),
            md_path: None,
        };
        body_env.add_module(mod_id, md_decl);

        // Match OCaml `Ctype.init_def(Ident.current_time())` + Typetexp.widen()
        // after module typing
        // and before body typing. type_structure calls init_def per-item which
        // trashes the current_level from our begin_def. Restore it here.
        // OCaml uses init_def(Ident.current_time()) here, and current_time is
        // monotonic/increasing. Rust stamp tracking can lag behind nested
        // begin_def scopes, so never restore below the surrounding letmodule
        // definition level.
        let restored_level = std::cmp::max(ctx.current_stamp(), letmodule_def_level);
        ctx.init_def(restored_level);
        ctx.restore_global_level(narrow_global_level);
        tctx.type_variables = saved_type_variables.clone();

        // Type check the body in the extended environment. Match OCaml let-module
        // scoping by abstracting local module-rooted type paths out of the exposed
        // expression type before unifying with the surrounding expectation.
        // OCaml typecore.ml `Pexp_letmodule` types the body with `new_env`,
        // and every unification inside it runs in that env: `update_level`
        // (ctype.ml:568-578) expands `M.t` before deciding it would escape.
        let saved_unify_env = tctx
            .unify_state
            .env()
            .cloned();
        tctx.unify_state.set_env(&body_env);
        let typed_body = type_expect(tctx, &body_env, body, expected_ty, None);
        match saved_unify_env {
            Some(saved) => tctx.unify_state.set_env(&saved),
            None => {
                tctx.unify_state.take_env();
            }
        }
        let typed_body = typed_body?;
        let rewritten_ty = typed_body.exp_type;
        apply_letmodule_local_path_cleanup(
            ctx,
            env,
                        &body_env,
            &mod_id,
            rewritten_ty,
            expected_ty,
        );
        // NOTE: OCaml does NOT unify body.exp_type with ty_expected here.
        // type_expect already connected them internally. Unifying here would
        // merge the Pexp_tuple's result_ty with the filter_arrow's return_ty,
        // collapsing two distinct Ttuple nodes that OCaml keeps separate.
        // OCaml only does unify_var(ty, body.exp_type) after end_def (below).
        Ok((typed_mod, mod_id, body_env, typed_body, rewritten_ty))
    })();
    if scoped_result.is_err() {
        ctx.restore_global_level(narrow_global_level);
        tctx.type_variables = saved_type_variables;
    }
    ctx.end_def();

    let (typed_mod, mod_id, body_env, typed_body, rewritten_ty) = scoped_result?;
    tctx.set_unify_env(&body_env);
    unify_expression_types(tctx, loc, letmodule_ty, rewritten_ty, None)?;

    Ok({
        let typed_node = Expression::new(
            crate::types::typedtree::ExpressionDesc::Texp_letmodule(
                mod_id,
                Located {
                    txt: mod_name_str.clone(),
                    loc: name.loc,
                },
                tctx.typed.push_module_expr(typed_mod),
                tctx.push_expr(typed_body),
            ),
            loc,
            letmodule_ty,
            EnvRef(0),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

fn pack_type_path_has_local_module_dependency(
    ctx: &TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    path: &Path,
    visited: &mut HashSet<TypeExprRef>,
) -> bool {
    if matches!(path.view(), PathView::Pdot(..))
        && matches!(
            path_root_module(path).view(),
            PathView::Pident(id) if !id.is_persistent() && id.name() == "%M"
        )
    {
        let Some(decl) = lookup_type_decl_for_path(path, env, pers_env, ctx) else {
            return true;
        };
        let Some(manifest) = decl.type_manifest else {
            return true;
        };
        return pack_type_contains_local_module_dependency(ctx, env, pers_env, manifest, visited);
    }
    false
}

fn pack_type_contains_local_module_dependency(
    ctx: &TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ty: TypeExprRef,
    visited: &mut HashSet<TypeExprRef>,
) -> bool {
    let repr = ctx.repr(ty);
    if !visited.insert(repr) {
        return false;
    }

    let desc = ctx.get_desc(repr);
    match &*desc {
        TypeDesc::Tconstr { path, args, .. } => {
            pack_type_path_has_local_module_dependency(ctx, env, pers_env, path, visited)
                || ctx.type_list(args).iter().any(|arg| {
                    pack_type_contains_local_module_dependency(ctx, env, pers_env, arg, visited)
                })
        }
        TypeDesc::Tarrow { args, ret } => {
            ctx.type_args(args).iter().any(|arg| {
                pack_type_contains_local_module_dependency(ctx, env, pers_env, arg.typ, visited)
            }) || pack_type_contains_local_module_dependency(ctx, env, pers_env, *ret, visited)
        }
        TypeDesc::Ttuple(items) => ctx.type_list(items).iter().any(|item| {
            pack_type_contains_local_module_dependency(ctx, env, pers_env, item, visited)
        }),
        TypeDesc::Tlink(target) | TypeDesc::Tsubst(target) => {
            pack_type_contains_local_module_dependency(ctx, env, pers_env, *target, visited)
        }
        TypeDesc::Tobject { fields } => {
            pack_type_contains_local_module_dependency(ctx, env, pers_env, *fields, visited)
        }
        TypeDesc::Tfield { typ, rest, .. } => {
            pack_type_contains_local_module_dependency(ctx, env, pers_env, *typ, visited)
                || pack_type_contains_local_module_dependency(ctx, env, pers_env, *rest, visited)
        }
        TypeDesc::Tvariant(row) => {
            let row = &ctx.row_desc(row);
            for (_, field) in &row.row_fields {
                match field {
                    RowField::Rpresent(Some(ty)) => {
                        if pack_type_contains_local_module_dependency(
                            ctx, env, pers_env, *ty, visited,
                        ) {
                            return true;
                        }
                    }
                    RowField::Reither { types, .. }
                        if types.iter().any(|ty| {
                            pack_type_contains_local_module_dependency(
                                ctx, env, pers_env, *ty, visited,
                            )
                        }) =>
                    {
                        return true;
                    }
                    _ => {}
                }
            }
            if pack_type_contains_local_module_dependency(ctx, env, pers_env, row.row_more, visited)
            {
                return true;
            }
            if let Some((path, args)) = &row.row_name {
                return pack_type_path_has_local_module_dependency(
                    ctx, env, pers_env, path, visited,
                ) || args.iter().any(|arg| {
                    pack_type_contains_local_module_dependency(ctx, env, pers_env, *arg, visited)
                });
            }
            false
        }
        TypeDesc::Tpoly { body, vars } => {
            if pack_type_contains_local_module_dependency(ctx, env, pers_env, *body, visited) {
                return true;
            }
            ctx.type_list(vars).iter().any(|var| {
                pack_type_contains_local_module_dependency(ctx, env, pers_env, var, visited)
            })
        }
        TypeDesc::Tpackage { path, args, .. } => {
            pack_type_path_has_local_module_dependency(ctx, env, pers_env, path, visited)
                || ctx.type_list(args).iter().any(|arg| {
                    pack_type_contains_local_module_dependency(ctx, env, pers_env, arg, visited)
                })
        }
        TypeDesc::Tvar(..) | TypeDesc::Tunivar(..) | TypeDesc::Tnil => false,
    }
}

fn type_pack(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    module_expr: &crate::parser::ast::ModuleExpr,
    expected_ty: TypeExprRef,
    context: Option<ClashSite>,
    attributes: &[crate::parser::ast::Attribute],
) -> TypeCoreResult<Expression> {
    // Matches OCaml `Pexp_pack` in compiler/ml/typecore.ml:3518-3525:
    // instance the expected type, expand it to a package, then call
    // Typemod.type_package for the module expression and package arguments.
    let ctx = tctx.type_ctx;
    let expected_inst = crate::types::ctype::instance(ctx, expected_ty);
    let expanded = crate::types::ctype::expand_head(ctx, env, expected_inst);
    let (pack_path, pack_lids, expected_pack_args) = {
        let desc = ctx.get_desc(ctx.repr(expanded));
        match &*desc {
            TypeDesc::Tpackage { path, lids, args } => (*path, *lids, *args),
            TypeDesc::Tvar(..) | TypeDesc::Tunivar(..) => {
                return Err(TypeCoreError::CannotInferSignature { loc });
            }
            _ => {
                return Err(TypeCoreError::NotAPackedModule {
                    loc,
                    ty: expected_ty,
                });
            }
        }
    };
    let pack_lids_ref = pack_lids;
    let pack_lids = ctx.package_lids(pack_lids_ref);
    // OCaml compiler/ml/typecore.ml:3518-3525 expands `instance env ty_expected`
    // before entering Typemod.type_package. That expansion reaches qualified
    // type declarations through Env.find_type_full/find_module_descr
    // (compiler/ml/env.ml:781-813), whose component-table force runs
    // Subst.modtype_declaration for sibling module types
    // (compiler/ml/env.ml:1513-1519,1581-1585). Rust may reconstruct the
    // Tpackage from a raw persistent type item, so force the same parent
    // component table before the Ident.set_current_time below.
    if let PathView::Pdot(parent, _, _) = pack_path.view() {
        let _ = with_resolved_module_components_for_path(
            parent,
            env,
            &mut tctx.persistent_env,
            ctx,
            |_| (),
        );
    }
    // Matches compiler/ml/typemod.ml:1676-1685: type_package uses
    // Pexp_letmodule-style scoping, sets the ident clock to the saved type
    // level, types the module, then reinitializes from Ident.current_time().
    let package_level = ctx.current_level();
    ctx.begin_def();
    ctx.set_current_time(package_level);
    let typed_module_result = crate::types::typemod::type_module_expr_with_alias_mode(
        tctx,
        env,
        tctx.arena,
        module_expr,
        false,
    )
    .map_err(|e| match e {
        crate::types::typemod::TypeModError::CannotApply { loc, mty, origin } => {
            TypeCoreError::CannotApplyModule { loc, mty, origin }
        }
        other => TypeCoreError::ModuleError(Box::new(other)),
    });
    if typed_module_result.is_err() {
        ctx.end_def();
    }
    let typed_module = typed_module_result?;
    ctx.init_def(ctx.current_stamp());

    fn mkpath_from_pack_lid(
        base: &Path,
        lid: &Longident,
        arena: &ParseArena,
        ctx: &TypeContext,
    ) -> Option<Path> {
        match lid {
            Longident::Lident(name) => Some(Path::pdot(
                *base,
                ctx.resolve_longident_component(arena, *name),
            )),
            Longident::Ldot(prefix, name) => {
                let prefix_path = mkpath_from_pack_lid(base, prefix, arena, ctx)?;
                Some(Path::pdot(
                    prefix_path,
                    ctx.resolve_longident_component(arena, *name),
                ))
            }
            Longident::Lapply(_, _) => None,
        }
    }

    fn packed_module_path_from_expr(
        ta: &TypedArena,
        expr: &crate::types::typedtree::ModuleExpr,
    ) -> Option<Path> {
        match &expr.mod_desc {
            crate::types::typedtree::ModuleExprDesc::Tmod_ident(path, _) => Some(*path),
            // Matches compiler/ml/typemod.ml:1687-1691 exactly: OCaml accepts
            // one implicit constraint only when it wraps a direct Tmod_ident.
            crate::types::typedtree::ModuleExprDesc::Tmod_constraint(
                inner,
                _,
                crate::types::typedtree::ModuleTypeConstraint::Tmodtype_implicit,
                _,
            ) => match &ta.module_expr(*inner).mod_desc {
                crate::types::typedtree::ModuleExprDesc::Tmod_ident(path, _) => Some(*path),
                _ => None,
            },
            _ => None,
        }
    }

    // Matches compiler/ml/typemod.ml:1686-1694: use a direct module path for
    // identifiers and implicit constraints over identifiers; otherwise enter a
    // fresh `%M` module before building constrained package paths.
    let packed_module_path = packed_module_path_from_expr(&tctx.typed, &typed_module);
    let (pack_arg_base_path, package_env) = match packed_module_path {
        Some(path) => (Some(path), env.clone()),
        None => {
            let temp_id = ctx.create_ident("%M");
            let mut package_env = env.clone();
            package_env.add_module(
                temp_id,
                crate::types::decl::ModuleDeclaration {
                    md_type: typed_module.mod_type.clone(),
                    md_attributes: vec![],
                    md_loc: crate::types::DeclLoc::none(),
                    md_path: None,
                },
            );
            (Some(Path::pident(temp_id)), package_env)
        }
    };
    let pack_args = if let Some(pack_module_path) = pack_arg_base_path.as_ref() {
        let mut rebuilt_args = Vec::with_capacity(pack_lids.len());
        let mut can_rebuild = true;
        for lid in pack_lids.iter() {
            match mkpath_from_pack_lid(pack_module_path, lid, tctx.arena, ctx) {
                Some(path) => rebuilt_args.push(ctx.new_generic_constr(path, vec![])),
                None => {
                    can_rebuild = false;
                    break;
                }
            }
        }
        if can_rebuild && rebuilt_args.len() == pack_lids.len() {
            rebuilt_args
        } else {
            ctx.type_list(expected_pack_args).to_vec()
        }
    } else {
        ctx.type_list(expected_pack_args).to_vec()
    };
    // Matches compiler/ml/typemod.ml:1701-1709: build `tl'` while still inside
    // the package definition scope, then return to the original level before
    // computing the module-type constraint.
    ctx.end_def();
    let typed_module_loc = typed_module.mod_loc;
    // Matches compiler/ml/typemod.ml:1710-1719: unconstrained packages use
    // `Mty_ident p`; constrained packages call modtype_of_package and then
    // wrap the module in an implicit module-type constraint.
    let decl_package_mty = if pack_lids.is_empty() {
        crate::types::decl::ModuleType::MtyIdent(pack_path)
    } else {
        let package_mty = crate::types::typemod::modtype_of_package(
            &package_env,
            &pack_path,
            &pack_lids,
            &pack_args,
            tctx.arena,
            &mut tctx.persistent_env,
            ctx,
        )
        .unwrap_or(crate::types::decl::ModuleType::MtyIdent(pack_path));
        // Matches compiler/ml/typemod.ml:1713-1718: after constructing the
        // constrained module type, each package argument is unified with a
        // fresh variable under the shadowed package env from
        // compiler/ml/typemod.ml:1686-1694. That env contains the synthetic
        // `%M` module used by compiler/ml/typemod.ml:1692-1694, so paths such as
        // `%M.t` can expand to manifests before `rue` unifies the package.
        let saved_unify_env = tctx
            .unify_state
            .env()
            .cloned();
        tctx.unify_state.set_env(&package_env);
        let mut package_arg_unify_result: TypeCoreResult<()> = Ok(());
        for (lid, package_arg) in pack_lids.iter().zip(&pack_args) {
            if crate::types::unify(ctx, &mut tctx.unify_state, *package_arg, ctx.new_var(None))
                .is_err()
            {
                package_arg_unify_result = Err(TypeCoreError::ModuleError(Box::new(
                    crate::types::typemod::TypeModError::ScopingPack {
                        loc: module_expr.pmod_loc,
                        lid: lid.clone(),
                        ty: *package_arg,
                    },
                )));
                break;
            }
        }
        if let Some(saved_env) = saved_unify_env {
            tctx.unify_state.set_env(&saved_env);
        }
        package_arg_unify_result?;
        for (lid, package_arg) in pack_lids.iter().zip(&pack_args) {
            if pack_type_contains_local_module_dependency(
                ctx,
                &package_env,
                &mut tctx.persistent_env,
                *package_arg,
                &mut HashSet::new(),
            ) {
                return Err(TypeCoreError::ModuleError(Box::new(
                    crate::types::typemod::TypeModError::ScopingPack {
                        loc: module_expr.pmod_loc,
                        lid: lid.clone(),
                        ty: *package_arg,
                    },
                )));
            }
        }
        package_mty
    };
    let constraint_arg_mty =
        crate::types::typemod::decl_module_type_from_typed_module_expr_for_constraint_arg(
            &typed_module,
        );
    let arg_mty = constraint_arg_mty
        .clone()
        .or_else(|| {
            crate::types::typemod::extract_module_type_from_mod_expr_with_ctx(
                &tctx.typed,
                &typed_module,
                Some(&package_env),
                ctx,
            )
        })
        .unwrap_or(crate::types::decl::ModuleType::MtySignature(
            std::sync::Arc::new(vec![]),
        ));
    // OCaml compiler/ml/typemod.ml:1710-1719 calls `wrap_constraint` for
    // every packed module.
    // typemod.ml `wrap_constraint`: an inclusion failure is `Not_included`
    // at the packed module expression.
    let mut inclusion_warnings = Vec::new();
    let coercion_result = crate::types::includemod::modtypes_with_warnings(
        ctx,
        &package_env,
        &arg_mty,
        &decl_package_mty,
        &mut inclusion_warnings,
    );
    crate::types::typemod::report_inclusion_warnings(tctx, typed_module_loc, inclusion_warnings);
    let coercion_result = crate::types::includemod::escaped(ctx, coercion_result)?;
    let coercion = coercion_result.map_err(|error| {
        TypeCoreError::ModuleError(Box::new(
            crate::types::typemod::TypeModError::SignatureMismatch {
                loc: typed_module_loc,
                error: Box::new(error),
            },
        ))
    })?;
    // typemod.ml `type_package`: `wrap_constraint env` builds the constraint
    // in the package environment (the original one, or the one with `%M`).
    let wrapped_env = if packed_module_path.is_some() {
        typed_module.mod_env
    } else {
        ctx.store_typed_env(&package_env)
    };
    let wrapped_module = crate::types::typedtree::ModuleExpr {
        mod_desc: crate::types::typedtree::ModuleExprDesc::Tmod_constraint(
            tctx.typed.push_module_expr(typed_module),
            decl_package_mty.clone(),
            crate::types::typedtree::ModuleTypeConstraint::Tmodtype_implicit,
            coercion,
        ),
        mod_loc: typed_module_loc,
        mod_type: decl_package_mty,
        mod_env: wrapped_env,
        mod_attributes: Attributes::new(),
    };
    let packed_type = ctx.new_type(TypeDesc::Tpackage {
        path: pack_path,
        lids: pack_lids_ref,
        args: ctx.new_type_list(&pack_args),
    });
    // Matches compiler/ml/typecore.ml:3525-3531: `Pexp_pack` returns via
    // `rue`, whose helper at compiler/ml/typecore.ml:2408-2410 unifies the
    // fresh package expression type with `instance env ty_expected`.
    let saved_unify_env = tctx
        .unify_state
        .env()
        .cloned();
    tctx.unify_state.set_env(&package_env);
    let rue_result = rue_unify(tctx, loc, packed_type, expected_ty, context);
    if let Some(saved_env) = saved_unify_env {
        tctx.unify_state.set_env(&saved_env);
    }
    rue_result?;

    Ok({
        let typed_node = Expression::new(
            ExpressionDesc::Texp_pack(tctx.typed.push_module_expr(wrapped_module)),
            loc,
            packed_type,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, attributes.to_vec().into())
    })
}

/// The module type of `Pmod_unpack` on a module pattern variable, as typed
/// by the `let module` that `wrap_unpacks` builds (typemod.ml:1357-1370).
fn module_type_from_package_binding(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    ty: TypeExprRef,
    loc: LocIdx,
) -> TypeCoreResult<crate::types::decl::ModuleType> {
    let ctx = tctx.type_ctx;
    let expanded = crate::types::ctype::expand_head(ctx, env, ty);
    let package_info = {
        let desc = ctx.get_desc(ctx.repr(expanded));
        match &*desc {
            TypeDesc::Tpackage { path, lids, args } => {
                Ok((*path, *lids, *args))
            }
            TypeDesc::Tvar(..) => Err(TypeCoreError::CannotInferSignature { loc }),
            _ => Err(TypeCoreError::ModuleError(Box::new(
                crate::types::typemod::TypeModError::NotAPackedModule { loc, ty: expanded },
            ))),
        }
    };
    let (path, lids, args) = package_info?;
    if ctx
        .type_list(args)
        .iter()
        .any(|arg| crate::types::typemod::type_expr_has_free_variables(ctx, arg))
    {
        return Err(TypeCoreError::ModuleError(Box::new(
            crate::types::typemod::TypeModError::IncompletePackedModule { loc, ty: expanded },
        )));
    }
    Ok(crate::types::typemod::modtype_of_package(
        env,
        &path,
        &ctx.package_lids(lids),
        &ctx.type_list(args).to_smallvec::<4>(),
        tctx.arena,
        &mut tctx.persistent_env,
        ctx,
    )
    .unwrap_or(crate::types::decl::ModuleType::MtyIdent(path)))
}

/// Type an ordinary body under unpacked parameter modules.
/// Cost: the existing unpack recursion and body check; no additional walk.
fn type_expect_with_module_unpacks(
    tctx: &mut TypeCheckContext<'_>, env: &Env, body: &ParsedExpression,
    expected_ty: TypeExprRef, unpacks: &[PatternVariable], context: Option<ClashSite>,
) -> TypeCoreResult<Expression> {
    type_body_with_module_unpacks(tctx, env, body, expected_ty, unpacks, context, None)
}

/// Type a function body, optionally adding its promise result, under unpacks.
/// Cost: one existing module-unpack scope per parameter unpack, then one body
/// check. The promise wrapper adds no traversal or parsed nodes.
fn type_body_with_module_unpacks(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    body: &ParsedExpression,
    expected_ty: TypeExprRef,
    unpacks: &[PatternVariable],
    context: Option<ClashSite>,
    async_body: Option<(crate::parse_arena::ExprIdx, LocIdx)>,
) -> TypeCoreResult<Expression> {
    fn ensure_string_idx(arena: &ParseArena, s: &str) -> StrIdx {
        if let Some(idx) = arena.find_string_idx(s) {
            return idx;
        }
        arena.push_typecheck_string(s.to_owned())
    }

    // `wrap_unpacks` (typecore.ml:2097-2108) folds left over the unpacks, so
    // the last one is the outermost `let module`.
    let Some((unpack, rest)) = unpacks.split_last() else {
        return if let Some((operand, loc)) = async_body {
            let primitive = Located { txt: tctx.arena.promise_async_lident(), loc };
            type_promise_application(tctx, env, body, operand, primitive,
                &mut Expected::Known(expected_ty), context)
        } else {
            type_expect(tctx, env, body, expected_ty, context)
        };
    };

    let decl_mty = module_type_from_package_binding(tctx, env, unpack.ty, unpack.loc_idx)?;
    // `wrap_unpacks` builds a real `Pexp_letmodule` (typecore.ml:2097-2108),
    // typed with its level scoping (typecore.ml:3352-3375): a result
    // variable at the outer level, `begin_def`, the ident clock set to that
    // level, and `init_def (Ident.current_time ())` once the module is bound.
    let ctx = tctx.type_ctx;
    let letmodule_ty = ctx.new_var(None);
    ctx.begin_def();
    ctx.set_current_time(ctx.get_level(letmodule_ty));
    // Match OCaml Env.enter_module: create one fresh ident used for
    // both the body environment binding and the Texp_letmodule node.
    let letmod_id = tctx.type_ctx.create_ident(unpack.id.name());
    // The unpack's `Pexp_ident` is typed (typecore.ml:3357) before the body;
    // `Env.lookup_value` marks the pattern variable used (env.ml:1169-1172).
    if let Ok(desc) = env.find_value(unpack.id.name()) {
        let val_loc = desc.val_loc;
        tctx.mark_value_used(env, unpack.id.name_atom(), tctx.resolve_loc(val_loc));
    }
    // Note: OCaml applies prefix_idents/Subst.signature here via lazy
    // components_of_module_maker, rewriting Pident paths to Pdot(Reducer, ...).
    // This affects which path form becomes the representative after unification.
    // Implementing this in Rust causes widespread crashes (426/657 files) because
    // the Pdot paths can't always be expanded back through the env.
    // The remaining cosmetic difference (Pident vs Pdot for first-class module
    // type paths) is accepted as a known limitation.
    let mut body_env = env.clone();
    body_env.add_module(
        letmod_id,
        crate::types::decl::ModuleDeclaration {
            md_type: decl_mty.clone(),
            md_attributes: vec![],
            md_loc: crate::types::DeclLoc::none(),
            md_path: None,
        },
    );
    ctx.init_def(ctx.current_stamp());
    let typed_body =
        type_body_with_module_unpacks(tctx, &body_env, body, expected_ty, rest, context, async_body);
    ctx.end_def();
    let typed_body = typed_body?;
    apply_letmodule_local_path_cleanup(
        tctx.type_ctx,
        env,
        &body_env,
        &letmod_id,
        typed_body.exp_type,
        expected_ty,
    );

    let lid = existing_or_new_lident_idx(tctx.arena, &unpack.name.txt);
    let located_lid = Located {
        txt: lid,
        loc: unpack.name.loc,
    };
    let value_desc = env
        .find_value(unpack.id.name())
        .cloned()
        .unwrap_or(ValueDescription {
            val_type: unpack.ty,
            val_kind: crate::types::ValueKind::ValReg,
            val_loc: tctx.intern_ast_loc(tctx.arena, unpack.loc_idx),
            val_attributes: Default::default(),
            val_path: None,
        });

    // OCaml's wrap_unpacks types the unpack as Pexp_ident through type_expect,
    // which calls instance() on the looked-up type. Match that by instancing here.
    let unpack_inst_ty = crate::types::instance(tctx.type_ctx, unpack.ty);
    let unpack_expr = Expression::new(
        ExpressionDesc::Texp_ident(Path::pident(unpack.id), located_lid, Arc::new(value_desc)),
        unpack.loc_idx,
        unpack_inst_ty,
        tctx.type_ctx.store_typed_env(env),
    );
    let unpack_module = crate::types::typedtree::ModuleExpr {
        mod_desc: crate::types::typedtree::ModuleExprDesc::Tmod_unpack(
            tctx.push_expr(unpack_expr),
            decl_mty.clone(),
        ),
        mod_loc: unpack.loc_idx,
        mod_type: decl_mty,
        mod_env: EnvRef(0),
        mod_attributes: Attributes::new(),
    };

    // OCaml `wrap_unpacks` uses the source expression location (`sexp.pexp_loc`)
    // for each generated `let module` wrapper.
    let modulepat_attrs = vec![(
        Located {
            txt: ensure_string_idx(tctx.arena, "#modulepat"),
            loc: tctx.arena.none_loc(),
        },
        crate::parser::ast::Payload::PStr(Box::default()),
    )];
    // typecore.ml:3373-3375: the body type must not mention the module.
    tctx.set_unify_env(&body_env);
    if crate::types::ctype::unify_var(
        tctx.type_ctx,
        &mut tctx.unify_state,
        letmodule_ty,
        typed_body.exp_type,
    )
    .is_err()
    {
        return Err(TypeCoreError::ScopingLetModule(
            unpack.name.txt.to_string(),
            typed_body.exp_type,
        ));
    }
    let wrapped_ty = letmodule_ty;
    Ok({
        let typed_node = Expression::new(
            crate::types::typedtree::ExpressionDesc::Texp_letmodule(
                letmod_id,
                Located {
                    txt: unpack.name.txt.to_string(),
                    loc: unpack.name.loc,
                },
                tctx.typed.push_module_expr(unpack_module),
                tctx.push_expr(typed_body),
            ),
            async_body.map_or(body.pexp_loc, |(_, loc)| loc),
            wrapped_ty,
            tctx.type_ctx.store_typed_env(env),
        );
        tctx.typed
            .with_exp_attributes(typed_node, modulepat_attrs.into())
    })
}

fn has_internal_expansive_attribute(
    arena: &ParseArena,
    attrs: &[crate::parser::ast::Attribute],
) -> bool {
    attrs
        .iter()
        .any(|attr| arena.get_string(attr.0.txt) == "internal.expansive")
}

fn is_nonexpansive_expression(tctx: &mut TypeCheckContext<'_>, exp: TExprIdx) -> bool {
    let ta = std::mem::take(&mut tctx.typed);
    let result = nonexpansive_expr(tctx, &ta, exp);
    tctx.typed = ta;
    result
}

fn is_nonexpansive_node(tctx: &mut TypeCheckContext<'_>, exp: &Expression) -> bool {
    let ta = std::mem::take(&mut tctx.typed);
    let result = nonexpansive_node(tctx, &ta, exp);
    tctx.typed = ta;
    result
}

fn nonexpansive_expr(tctx: &mut TypeCheckContext<'_>, ta: &TypedArena, exp: TExprIdx) -> bool {
    nonexpansive_node(tctx, ta, ta.expr(exp))
}

fn nonexpansive_node(tctx: &mut TypeCheckContext<'_>, ta: &TypedArena, exp: &Expression) -> bool {
    if has_internal_expansive_attribute(tctx.arena, ta.exp_attributes(exp)) {
        return true;
    }

    match &exp.exp_desc {
        ExpressionDesc::Texp_ident(_, _, _) => true,
        ExpressionDesc::Texp_constant(_) => true,
        ExpressionDesc::Texp_template { values, .. } if values.is_empty() => true,
        ExpressionDesc::Texp_let(_, bindings, body) => {
            ta
                .value_bindings(*bindings)
                .iter()
                .all(|binding| nonexpansive_expr(tctx, ta, binding.vb_expr))
                && nonexpansive_expr(tctx, ta, *body)
        }
        ExpressionDesc::Texp_function { .. } => true,
        ExpressionDesc::Texp_match(scrutinee, cases, exn_cases, _) => {
            exn_cases.is_empty()
                && nonexpansive_expr(tctx, ta, *scrutinee)
                && ta.cases(*cases).iter().all(|case| {
                    case.c_guard
                        .as_ref()
                        .is_none_or(|guard| nonexpansive_expr(tctx, ta, *guard))
                        && nonexpansive_expr(tctx, ta, case.c_rhs)
                })
        }
        ExpressionDesc::Texp_tuple(items) => ta
            .expr_list(*items)
            .iter()
            .all(|item| nonexpansive_expr(tctx, ta, *item)),
        ExpressionDesc::Texp_construct(_, _, items) => ta
            .expr_list(*items)
            .iter()
            .all(|item| nonexpansive_expr(tctx, ta, *item)),
        ExpressionDesc::Texp_variant(_, maybe_arg) => maybe_arg
            .as_ref()
            .is_none_or(|arg| nonexpansive_expr(tctx, ta, *arg)),
        ExpressionDesc::Texp_record {
            fields,
            extended_expression,
            ..
        } => {
            let fields = ta.record_fields(*fields);
            // typecore.ml:2088-2108
            if !(fields
                .iter()
                .all(|(_, _, expr)| nonexpansive_expr(tctx, ta, *expr))
                && extended_expression
                    .as_ref()
                    .is_none_or(|expr| nonexpansive_expr(tctx, ta, *expr)))
            {
                return false;
            }
            // The literal allocates every field of the record: written,
            // copied from the spread, or left out.
            if fields.is_empty() {
                // `{}` has no field to find the record's labels through:
                // `extract_concrete_record exp.exp_env exp.exp_type`,
                // `Not_found -> false` (typecore.ml:2097-2105).
                let ctx = tctx.type_ctx;
                let Some(env) = ctx.get_typed_env(exp.exp_env) else {
                    return false;
                };
                match extract_concrete_record_type_info(
                    exp.exp_type,
                    &env,
                    &mut tctx.persistent_env,
                    ctx,
                ) {
                    Some((_, _, decl)) => match &decl.type_kind {
                        crate::types::TypeKind::TypeRecord(labels, _) => labels
                            .iter()
                            .all(|ld| ld.ld_mutable == crate::types::MutableFlag::Immutable),
                        _ => false,
                    },
                    None => false,
                }
            } else {
                // `Array.for_all ... lbl.lbl_all` of the first written label.
                crate::types::typedtree::record_all_labels(tctx.type_ctx, fields)
                    .expect("a non-empty record literal has the lbl_all of its labels")
                    .iter()
                    .all(|label| label.lbl_mut == crate::types::MutableFlag::Immutable)
            }
        }
        ExpressionDesc::Texp_field(expr, _, _) => nonexpansive_expr(tctx, ta, *expr),
        ExpressionDesc::Texp_array(_) => false,
        ExpressionDesc::Texp_ifthenelse(_, ifso, ifnot) => {
            nonexpansive_expr(tctx, ta, *ifso)
                && ifnot
                    .as_ref()
                    .is_none_or(|expr| nonexpansive_expr(tctx, ta, *expr))
        }
        ExpressionDesc::Texp_sequence(_, expr) => nonexpansive_expr(tctx, ta, *expr),
        ExpressionDesc::Texp_letmodule(_, _, module_expr, expr) => {
            is_nonexpansive_module_expr(tctx, ta, ta.module_expr(*module_expr))
                && nonexpansive_expr(tctx, ta, *expr)
        }
        ExpressionDesc::Texp_pack(module_expr) => {
            is_nonexpansive_module_expr(tctx, ta, ta.module_expr(*module_expr))
        }
        ExpressionDesc::Texp_assert(expr) => nonexpansive_expr(tctx, ta, *expr),
        ExpressionDesc::Texp_apply {
            funct,
            args,
            partial,
            ..
        } => {
            // compiler/ml/typecore.ml:1840-1859: `%component_identity` is an
            // abstract typed coercion and preserves the nonexpansiveness of
            // the component function value supplied to it.
            if matches!(
                &ta.expr(*funct).exp_desc,
                ExpressionDesc::Texp_ident(_, _, desc)
                    if matches!(
                        &desc.val_kind,
                        crate::types::ValueKind::ValPrim(prim)
                            if prim.prim_name == "%component_identity"
                    )
            ) {
                return ta.apply_args(*args).iter().all(|arg| {
                    arg.expression
                        .as_ref()
                        .is_none_or(|expr| nonexpansive_expr(tctx, ta, *expr))
                });
            }
            // typecore.ml `is_nonexpansive`: a partial application
            // (`foo(args, ...)`) evaluates its callee and supplied arguments
            // once, when it is created, and the resulting function shares
            // them, so it is nonexpansive only when they are.
            if *partial {
                return nonexpansive_expr(tctx, ta, *funct)
                    && ta.apply_args(*args).iter().all(|arg| {
                        arg.expression
                            .as_ref()
                            .is_none_or(|expr| nonexpansive_expr(tctx, ta, *expr))
                    });
            }
            if let Some((first_arg, rest_args)) = ta.apply_args(*args).split_first() {
                if first_arg.expression.is_none() {
                    return nonexpansive_expr(tctx, ta, *funct)
                        && rest_args.iter().all(|arg| {
                            arg.expression
                                .as_ref()
                                .is_none_or(|expr| nonexpansive_expr(tctx, ta, *expr))
                        });
                }
            }

            if let ExpressionDesc::Texp_ident(_, _, desc) = &ta.expr(*funct).exp_desc {
                if let crate::types::ValueKind::ValPrim(prim) = &desc.val_kind {
                    if prim.prim_name == "%raise"
                        && args.len() == 1
                        && matches!(
                            ta.apply_args(*args)[0].label,
                            crate::types::ArgLabel::Nolabel
                        )
                    {
                        if let Some(arg_expr) = &ta.apply_args(*args)[0].expression {
                            return nonexpansive_expr(tctx, ta, *arg_expr);
                        }
                    }
                }
            }
            false
        }
        _ => false,
    }
}

fn is_nonexpansive_module_expr(
    tctx: &mut TypeCheckContext<'_>,
    ta: &TypedArena,
    module_expr: &crate::types::typedtree::ModuleExpr,
) -> bool {
    match &module_expr.mod_desc {
        crate::types::typedtree::ModuleExprDesc::Tmod_ident(_, _) => true,
        crate::types::typedtree::ModuleExprDesc::Tmod_functor(_, _, _, _) => true,
        crate::types::typedtree::ModuleExprDesc::Tmod_unpack(expr, _) => {
            nonexpansive_expr(tctx, ta, *expr)
        }
        crate::types::typedtree::ModuleExprDesc::Tmod_constraint(inner, _, _, _) => {
            is_nonexpansive_module_expr(tctx, ta, ta.module_expr(*inner))
        }
        crate::types::typedtree::ModuleExprDesc::Tmod_structure(structure) => ta
            .structure_items(structure.str_items)
            .iter()
            .all(|item| match &item.str_desc {
                crate::types::typedtree::StructureItemDesc::Tstr_eval(_, _) => true,
                crate::types::typedtree::StructureItemDesc::Tstr_primitive(_) => true,
                crate::types::typedtree::StructureItemDesc::Tstr_type(_, _) => true,
                crate::types::typedtree::StructureItemDesc::Tstr_modtype(_) => true,
                crate::types::typedtree::StructureItemDesc::Tstr_open(_) => true,
                crate::types::typedtree::StructureItemDesc::Tstr_attribute(_) => true,
                // Every binding of a derived item is a function.
                crate::types::typedtree::StructureItemDesc::Tstr_derived(_) => true,
                crate::types::typedtree::StructureItemDesc::Tstr_value(_, bindings) => ta
                    .value_bindings(*bindings)
                    .iter()
                    .all(|binding| nonexpansive_expr(tctx, ta, binding.vb_expr)),
                crate::types::typedtree::StructureItemDesc::Tstr_module(binding) => {
                    is_nonexpansive_module_expr(tctx, ta, ta.module_expr(binding.mb_expr))
                }
                crate::types::typedtree::StructureItemDesc::Tstr_include(include_decl) => {
                    is_nonexpansive_module_expr(tctx, ta, ta.module_expr(include_decl.incl_mod))
                }
                crate::types::typedtree::StructureItemDesc::Tstr_recmodule(bindings) => {
                    bindings.iter().all(|binding| {
                        is_nonexpansive_module_expr(tctx, ta, ta.module_expr(binding.mb_expr))
                    })
                }
                crate::types::typedtree::StructureItemDesc::Tstr_exception(ext) => matches!(
                    ta.extension_constructor(*ext).ext_kind,
                    crate::types::typedtree::ExtensionConstructorKind::Text_rebind(_, _)
                ),
                crate::types::typedtree::StructureItemDesc::Tstr_typext(type_extension) => {
                    type_extension.tyext_constructors.iter().all(|ext| {
                        matches!(
                            ext.ext_kind,
                            crate::types::typedtree::ExtensionConstructorKind::Text_rebind(_, _)
                        )
                    })
                }
            }),
        crate::types::typedtree::ModuleExprDesc::Tmod_apply(_, _, _) => false,
    }
}

fn check_univars_or_less_general(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    expans: bool,
    kind: &str,
    exp: &Expression,
    ty_expected: TypeExprRef,
    vars: &[TypeExprRef],
) -> TypeCoreResult<()> {
    let ctx = tctx.type_ctx;
    if expans && !is_nonexpansive_node(tctx, exp) {
        crate::types::ctype::generalize_expansive(ctx, env, exp.exp_type);
    }

    // typecore.ml:2045-2047: "need to expand twice? cf. Ctype.unify2".
    let vars: Vec<TypeExprRef> = vars
        .iter()
        .map(|var| crate::types::ctype::expand_head(ctx, env, *var))
        .map(|var| crate::types::ctype::expand_head(ctx, env, var))
        .collect();
    let mut universal_vars = Vec::new();
    for var in &vars {
        let var = ctx.repr(*var);
        crate::types::ctype::generalize(ctx, var);
        let var_name = {
            let desc = ctx.get_desc(var);
            match &*desc {
                TypeDesc::Tvar(name)
                    if ctx.get_level(var) == crate::types::type_expr::GENERIC_LEVEL =>
                {
                    Some(*name)
                }
                _ => None,
            }
        };
        if let Some(name) = var_name {
            ctx.set_desc(
                var,
                TypeDesc::Tunivar(name),
            );
            universal_vars.push(var);
        }
    }

    if universal_vars.len() == vars.len() {
        Ok(())
    } else {
        // typecore.ml:2059-2067.
        let actual = ctx.new_generic_type(TypeDesc::Tpoly {
            body: ctx.repr(exp.exp_type),
            vars: ctx.new_type_list(&universal_vars),
        });
        let expected = ctx.repr(ty_expected);
        Err(TypeCoreError::LessGeneral {
            loc: exp.exp_loc,
            kind: kind.to_string(),
            trace: vec![(actual, actual), (expected, expected)],
            env: Some(ctx.store_typed_env(env)),
        })
    }
}

/// OCaml typecore.ml `approx_type`: approximate a parsed core type for recursive let pre-unification.
fn approx_type_for_rec_let(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    sty: &crate::parser::ast::CoreType,
) -> TypeExprRef {
    use crate::parser::ast::CoreTypeDesc as CTD;

    let ctx = tctx.type_ctx;

    match &sty.ptyp_desc {
        CTD::Ptyp_arrow(inner) => {
            let (arg, ret, arity) = &**inner;
            let args =
                ctx.new_type_args_from(tctx.arena.nary_arrow_args(arg, *arity).iter().map(|arg| {
                    let typ = if arg.lbl.is_optional() {
                        let inner = ctx.new_var(None);
                        env.type_option(ctx, inner)
                    } else {
                        ctx.new_var(None)
                    };
                    TypeArg::new(
                        convert_arg_label_for_ctx(&arg.lbl, tctx.arena, tctx.type_ctx),
                        typ,
                    )
                }));
            let ret = approx_type_for_rec_let(tctx, env, tctx.arena.get_core_type(*ret));
            ctx.new_type(TypeDesc::Tarrow { args, ret })
        }
        CTD::Ptyp_tuple(args) => {
            let tys = tctx
                .arena
                .type_list(*args)
                .iter()
                .map(|arg| approx_type_for_rec_let(tctx, env, tctx.arena.get_core_type(*arg)))
                .collect();
            ctx.new_tuple(tys)
        }
        CTD::Ptyp_constr(inner) => {
            let (lid, args) = inner;
            let longident = tctx.resolve_lid(lid.txt).clone();
            // typecore.ml:1988: `Env.lookup_type lid.txt env`, without `?loc`.
            let (path, decl) = resolve_type_constructor_path(tctx, env, &longident, None);
            if let Some(decl) = decl {
                if args.len() == decl.type_arity as usize {
                    let tys = tctx
                        .arena
                        .type_list(*args)
                        .iter()
                        .map(|arg| {
                            approx_type_for_rec_let(tctx, env, tctx.arena.get_core_type(*arg))
                        })
                        .collect();
                    return ctx.new_constr(path, tys);
                }
            }
            ctx.new_var(None)
        }
        CTD::Ptyp_poly(inner) => {
            let (_, inner) = &**inner;
            approx_type_for_rec_let(tctx, env, tctx.arena.get_core_type(*inner))
        }
        _ => ctx.new_var(None),
    }
}

/// OCaml typecore.ml `type_approx`: approximate an expression type for recursive let pre-unification.
fn type_approx_for_rec_let(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    sexp: &ParsedExpression,
) -> TypeCoreResult<TypeExprRef> {
    use crate::parser::ast::ExpressionDesc as ED;

    let ctx = tctx.type_ctx;
    let loc = sexp.pexp_loc;

    match &sexp.pexp_desc {
        ED::Pexp_braces(braces) => {
            type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(braces.expr))
        }
        ED::Pexp_let(inner) => {
            let (_, _, body) = inner;
            type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(*body))
        }
        ED::Pexp_fun(inner) => {
            let params = tctx.arena.nary_fun_params(inner).into_owned();
            let body = tctx.arena.nary_fun_body(inner);
            let args = ctx.new_type_args_from(params.iter().map(|param| {
                let typ = if param.p_lbl.is_optional() {
                    let inner = ctx.new_var(None);
                    env.type_option(ctx, inner)
                } else {
                    ctx.new_var(None)
                };
                TypeArg::new(
                    convert_arg_label_for_ctx(&param.p_lbl, tctx.arena, tctx.type_ctx),
                    typ,
                )
            }));
            // The return annotation constrains the operand of unsafe_async,
            // not the function's promise result. Approximate that application
            // with a fresh variable, as for every other application below.
            let ret = if inner.is_async {
                ctx.new_var(None)
            } else {
                type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(body))?
            };
            Ok(ctx.new_type(TypeDesc::Tarrow { args, ret }))
        }
        ED::Pexp_match(inner) => {
            let (_, cases) = inner;
            // The direct boolean rule is a conditional: pre-unification must
            // approximate its true arm even when false appears first in source.
            if let Some((ifso, _)) = crate::parser::parsetree_viewer::boolean_match_arms(tctx.arena, *cases) {
                return type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(ifso));
            }
            match tctx.arena.case_list(*cases).first() {
                Some(case) => type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(case.pc_rhs)),
                None => Ok(ctx.new_var(None)),
            }
        }
        ED::Pexp_try(inner) => {
            let (expr, _, _) = inner;
            type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(*expr))
        }
        ED::Pexp_tuple(items) => {
            let tys: TypeCoreResult<Vec<_>> = tctx
                .arena
                .expr_list(*items)
                .iter()
                .map(|item| type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(*item)))
                .collect();
            Ok(ctx.new_tuple(tys?))
        }
        ED::Pexp_ifthenelse(inner) => {
            let (_, then_expr, _) = &**inner;
            type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(*then_expr))
        }
        ED::Pexp_ternary(inner) => type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(inner.1)),
        ED::Pexp_sequence(_, expr) => {
            type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(*expr))
        }
        ED::Pexp_constraint(inner) => {
            let (expr, sty) = &**inner;
            let ty = type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(*expr))?;
            let ty1 = approx_type_for_rec_let(tctx, env, tctx.arena.get_core_type(*sty));
            unify_expression_types(tctx, loc, ty, ty1, None)?;
            Ok(ty1)
        }
        ED::Pexp_coerce(inner) => {
            let (expr, _sty1, sty2) = &**inner;
            let ty = type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(*expr))?;
            let ty1 = ctx.new_var(None);
            let ty2 = approx_type_for_rec_let(tctx, env, tctx.arena.get_core_type(*sty2));
            unify_expression_types(tctx, loc, ty, ty1, None)?;
            Ok(ty2)
        }
        _ => Ok(ctx.new_var(None)),
    }
}

fn iter_typed_pattern<F: FnMut(&Pattern)>(ta: &TypedArena, pat: &Pattern, f: &mut F) {
    f(pat);
    match &pat.pat_desc {
        PatternDesc::Tpat_variant(_, arg, _) => {
            if let Some(arg_pat) = arg {
                iter_typed_pattern(ta, ta.pattern(*arg_pat), f);
            }
        }
        PatternDesc::Tpat_alias(inner, _, _) => {
            iter_typed_pattern(ta, ta.pattern(*inner), f);
        }
        PatternDesc::Tpat_or(left, right, _) => {
            iter_typed_pattern(ta, ta.pattern(*left), f);
            iter_typed_pattern(ta, ta.pattern(*right), f);
        }
        PatternDesc::Tpat_tuple(items) | PatternDesc::Tpat_array(items) => {
            for item in ta.patterns(*items) {
                iter_typed_pattern(ta, item, f);
            }
        }
        PatternDesc::Tpat_construct(_, _, args) => {
            for arg in ta.patterns(*args) {
                iter_typed_pattern(ta, arg, f);
            }
        }
        PatternDesc::Tpat_record(fields, _, _) => {
            for (_, _, field_pat, _) in fields {
                iter_typed_pattern(ta, ta.pattern(*field_pat), f);
            }
        }
        PatternDesc::Tpat_dict(entries) => {
            for entry in entries {
                iter_typed_pattern(ta, ta.pattern(entry.tdp_pattern), f);
            }
        }
        PatternDesc::Tpat_any
        | PatternDesc::Tpat_var(_, _)
        | PatternDesc::Tpat_constant(_)
        | PatternDesc::Tpat_interval(..) => {}
    }
}

/// Bound identifiers of a typed pattern in OCaml `pat_bound_idents` order.
///
/// OCaml compiler/ml/typedtree.ml:444-457 `bound_idents` conses each
/// identifier onto a shared accumulator and returns it directly from
/// `pat_bound_idents`, so the observable warning order is the cons order
/// (reverse traversal order). typecore.ml:4652-4670 iterates that list when
/// registering unused-binding checks.
fn typed_pattern_bound_idents<'a>(
    ta: &'a TypedArena,
    pat: &'a Pattern,
) -> Vec<(&'a Ident, &'a str, LocIdx)> {
    let mut out = Vec::new();
    collect_typed_pattern_idents(ta, pat, &mut out);
    out.reverse();
    out
}

/// Collects bound identifiers in traversal order.
fn collect_typed_pattern_idents<'a>(
    ta: &'a TypedArena,
    pat: &'a Pattern,
    out: &mut Vec<(&'a Ident, &'a str, LocIdx)>,
) {
    match &pat.pat_desc {
        PatternDesc::Tpat_var(id, name) => {
            out.push((id, id.name(), name.loc));
        }
        PatternDesc::Tpat_alias(inner, id, name) => {
            collect_typed_pattern_idents(ta, ta.pattern(*inner), out);
            out.push((id, id.name(), name.loc));
        }
        PatternDesc::Tpat_tuple(items) | PatternDesc::Tpat_array(items) => {
            for item in ta.patterns(*items) {
                collect_typed_pattern_idents(ta, item, out);
            }
        }
        PatternDesc::Tpat_construct(_, _, args) => {
            for arg in ta.patterns(*args) {
                collect_typed_pattern_idents(ta, arg, out);
            }
        }
        PatternDesc::Tpat_variant(_, Some(arg), _) => {
            collect_typed_pattern_idents(ta, ta.pattern(*arg), out);
        }
        PatternDesc::Tpat_record(fields, _, rest) => {
            if let Some(rest) = rest {
                out.push((
                    &rest.rest_ident,
                    rest.rest_name.txt.as_str(),
                    rest.rest_name.loc,
                ));
            }
            for (_, _, field_pat, _) in fields {
                collect_typed_pattern_idents(ta, ta.pattern(*field_pat), out);
            }
        }
        PatternDesc::Tpat_dict(entries) => {
            for entry in entries {
                collect_typed_pattern_idents(ta, ta.pattern(entry.tdp_pattern), out);
            }
        }
        PatternDesc::Tpat_or(left, _, _) => {
            collect_typed_pattern_idents(ta, ta.pattern(*left), out);
        }
        PatternDesc::Tpat_any
        | PatternDesc::Tpat_constant(_)
        | PatternDesc::Tpat_interval(..)
        | PatternDesc::Tpat_variant(_, None, _) => {}
    }
}

fn typed_case_uses_ident(
    ta: &TypedArena,
    case: &crate::types::typedtree::Case,
    target: &Ident,
) -> bool {
    case.c_guard
        .as_ref()
        .is_some_and(|guard| typed_expression_uses_ident(ta, *guard, target))
        || typed_expression_uses_ident(ta, case.c_rhs, target)
}

pub(crate) fn typed_expression_uses_ident(ta: &TypedArena, expr: TExprIdx, target: &Ident) -> bool {
    let expr = ta.expr(expr);
    match &expr.exp_desc {
        ExpressionDesc::Texp_ident(path, _, _) => {
            matches!(path.view(), crate::types::path::PathView::Pident(id) if id.same(target))
        }
        ExpressionDesc::Texp_let(_, bindings, body) => {
            ta.value_bindings(*bindings)
                .iter()
                .any(|binding| typed_expression_uses_ident(ta, binding.vb_expr, target))
                || typed_expression_uses_ident(ta, *body, target)
        }
        ExpressionDesc::Texp_function { body, .. } => {
            typed_expression_uses_ident(ta, *body, target)
        }
        ExpressionDesc::Texp_apply { funct, args, .. } => {
            typed_expression_uses_ident(ta, *funct, target)
                || ta.apply_args(*args).iter().any(|arg| {
                    arg.expression
                        .as_ref()
                        .is_some_and(|expr| typed_expression_uses_ident(ta, *expr, target))
                })
        }
        ExpressionDesc::Texp_tagged_template { tag, values, .. } => {
            typed_expression_uses_ident(ta, *tag, target)
                || ta
                    .expr_list(*values)
                    .iter()
                    .any(|value| typed_expression_uses_ident(ta, *value, target))
        }
        ExpressionDesc::Texp_template { values, .. } => ta
            .expr_list(*values)
            .iter()
            .any(|value| typed_expression_uses_ident(ta, *value, target)),
        ExpressionDesc::Texp_match(scrutinee, value_cases, exn_cases, _) => {
            typed_expression_uses_ident(ta, *scrutinee, target)
                || ta
                    .cases(*value_cases)
                    .iter()
                    .chain(ta.cases(*exn_cases).iter())
                    .any(|case| typed_case_uses_ident(ta, case, target))
        }
        ExpressionDesc::Texp_try(body, cases, finally) => {
            typed_expression_uses_ident(ta, *body, target)
                || ta.cases(*cases).iter().any(|case| typed_case_uses_ident(ta, case, target))
                || finally
                    .as_ref()
                    .is_some_and(|finally| typed_expression_uses_ident(ta, *finally, target))
        }
        ExpressionDesc::Texp_tuple(items)
        | ExpressionDesc::Texp_array(items)
        | ExpressionDesc::Texp_spread(_, items)
        | ExpressionDesc::Texp_construct(_, _, items) => ta.expr_list(*items).iter()
            .any(|item| typed_expression_uses_ident(ta, *item, target)),
        ExpressionDesc::Texp_dict(entries) => ta.dict_entries(*entries).iter().any(|entry| match entry {
            TypedDictEntry::Tdict_entry(_, e) | TypedDictEntry::Tdict_spread(e) => {
                typed_expression_uses_ident(ta, *e, target)
            }
        }),
        ExpressionDesc::Texp_variant(_, payload) => payload
            .as_ref()
            .is_some_and(|expr| typed_expression_uses_ident(ta, *expr, target)),
        ExpressionDesc::Texp_record {
            fields,
            extended_expression,
            ..
        } => {
            ta.record_fields(*fields).iter()
                .any(|(_, _, expr)| typed_expression_uses_ident(ta, *expr, target))
                || extended_expression
                .as_ref()
                .is_some_and(|expr| typed_expression_uses_ident(ta, *expr, target))
        }
        ExpressionDesc::Texp_field(base, _, _) | ExpressionDesc::Texp_assert(base) => {
            typed_expression_uses_ident(ta, *base, target)
        }
        ExpressionDesc::Texp_setfield(base, _, _, value) => {
            typed_expression_uses_ident(ta, *base, target)
                || typed_expression_uses_ident(ta, *value, target)
        }
        ExpressionDesc::Texp_ifthenelse(cond, then_expr, else_expr) => {
            typed_expression_uses_ident(ta, *cond, target)
                || typed_expression_uses_ident(ta, *then_expr, target)
                || else_expr
                    .as_ref()
                    .is_some_and(|expr| typed_expression_uses_ident(ta, *expr, target))
        }
        ExpressionDesc::Texp_sequence(first, second)
        | ExpressionDesc::Texp_while(first, second)
        | ExpressionDesc::Texp_for_of(_, _, first, second)
        | ExpressionDesc::Texp_for_await_of(_, _, first, second) => {
            typed_expression_uses_ident(ta, *first, target)
                || typed_expression_uses_ident(ta, *second, target)
        }
        ExpressionDesc::Texp_for(_, _, start, stop, _, body) => {
            typed_expression_uses_ident(ta, *start, target)
                || typed_expression_uses_ident(ta, *stop, target)
                || typed_expression_uses_ident(ta, *body, target)
        }
        ExpressionDesc::Texp_object_get(receiver, _) => {
            typed_expression_uses_ident(ta, *receiver, target)
        }
        ExpressionDesc::Texp_object_set(receiver, _, value) => {
            typed_expression_uses_ident(ta, *receiver, target)
                || typed_expression_uses_ident(ta, *value, target)
        }
        ExpressionDesc::Texp_object_literal(fields) => fields
            .iter()
            .any(|(_, field)| typed_expression_uses_ident(ta, *field, target)),
        ExpressionDesc::Texp_letmodule(_, _, module_expr, body) => {
            // OCaml compiler/ml/typecore.ml:4610-4655 records value-use
            // callbacks while typing the RHS, and typecore.ml:3399-3425 /
            // typemod.ml:1358-1377 type the let-module RHS before the body.
            typed_module_expr_uses_ident(ta, ta.module_expr(*module_expr), target)
                || typed_expression_uses_ident(ta, *body, target)
        }
        ExpressionDesc::Texp_letexception(_, body) => {
            typed_expression_uses_ident(ta, *body, target)
        }
        ExpressionDesc::Texp_pack(module_expr) => {
            // OCaml compiler/ml/typecore.ml:3518-3528 and
            // typemod.ml:1358-1377 type packed module expressions by typing
            // the underlying module expression, so local value uses inside
            // `Pmod_unpack` count for warning 26/27.
            typed_module_expr_uses_ident(ta, ta.module_expr(*module_expr), target)
        }
        ExpressionDesc::Texp_constant(_)
        | ExpressionDesc::Texp_break
        | ExpressionDesc::Texp_continue => false,
    }
}

fn typed_module_expr_uses_ident(ta: &TypedArena, module_expr: &ModuleExpr, target: &Ident) -> bool {
    match &module_expr.mod_desc {
        ModuleExprDesc::Tmod_structure(structure) => ta
            .structure_items(structure.str_items)
            .iter()
            .any(|item| typed_structure_item_uses_ident(ta, item, target)),
        ModuleExprDesc::Tmod_apply(func, arg, _) => {
            typed_module_expr_uses_ident(ta, ta.module_expr(*func), target)
                || typed_module_expr_uses_ident(ta, ta.module_expr(*arg), target)
        }
        ModuleExprDesc::Tmod_functor(_, _, arg, body) => {
            arg.is_some_and(|arg| typed_module_type_uses_ident(ta, ta.module_type(arg), target))
                || typed_module_expr_uses_ident(ta, ta.module_expr(*body), target)
        }
        ModuleExprDesc::Tmod_constraint(inner, _, constraint, _) => {
            typed_module_expr_uses_ident(ta, ta.module_expr(*inner), target)
                || match constraint {
                    ModuleTypeConstraint::Tmodtype_explicit(module_type) => {
                        typed_module_type_uses_ident(ta, ta.module_type(*module_type), target)
                    }
                    ModuleTypeConstraint::Tmodtype_implicit => false,
                }
        }
        ModuleExprDesc::Tmod_unpack(expr, _) => typed_expression_uses_ident(ta, *expr, target),
        ModuleExprDesc::Tmod_ident(_, _) => false,
    }
}

fn typed_module_type_uses_ident(ta: &TypedArena, module_type: &ModuleType, target: &Ident) -> bool {
    match &module_type.mty_desc {
        ModuleTypeDesc::Tmty_typeof(module_expr) => {
            typed_module_expr_uses_ident(ta, ta.module_expr(*module_expr), target)
        }
        ModuleTypeDesc::Tmty_functor(_, _, arg, body) => {
            arg.is_some_and(|arg| typed_module_type_uses_ident(ta, ta.module_type(arg), target))
                || typed_module_type_uses_ident(ta, ta.module_type(*body), target)
        }
        ModuleTypeDesc::Tmty_with(inner, _) => {
            typed_module_type_uses_ident(ta, ta.module_type(*inner), target)
        }
        ModuleTypeDesc::Tmty_signature(signature) => ta
            .signature_items(signature.sig_items)
            .iter()
            .any(|item| typed_signature_item_uses_ident(ta, item, target)),
        ModuleTypeDesc::Tmty_ident(_, _) | ModuleTypeDesc::Tmty_alias(_, _) => false,
    }
}

fn typed_signature_item_uses_ident(
    ta: &TypedArena,
    item: &TypedSignatureItem,
    target: &Ident,
) -> bool {
    match &item.sig_desc {
        TypedSignatureItemDesc::Tsig_module(decl) => {
            typed_module_type_uses_ident(ta, ta.module_type(decl.md_type), target)
        }
        TypedSignatureItemDesc::Tsig_recmodule(decls) => decls
            .iter()
            .any(|decl| typed_module_type_uses_ident(ta, ta.module_type(decl.md_type), target)),
        TypedSignatureItemDesc::Tsig_modtype(decl) => {
            decl.mtd_type.as_ref().is_some_and(|module_type| {
                typed_module_type_uses_ident(ta, ta.module_type(*module_type), target)
            })
        }
        TypedSignatureItemDesc::Tsig_include(include) => {
            typed_module_type_uses_ident(ta, ta.module_type(include.incl_mod), target)
        }
        TypedSignatureItemDesc::Tsig_value(_)
        | TypedSignatureItemDesc::Tsig_type(_, _)
        | TypedSignatureItemDesc::Tsig_typext(_)
        | TypedSignatureItemDesc::Tsig_exception(_)
        | TypedSignatureItemDesc::Tsig_open(_)
        | TypedSignatureItemDesc::Tsig_attribute(_) => false,
    }
}

fn typed_structure_item_uses_ident(ta: &TypedArena, item: &StructureItem, target: &Ident) -> bool {
    match &item.str_desc {
        StructureItemDesc::Tstr_eval(expr, _) => typed_expression_uses_ident(ta, *expr, target),
        StructureItemDesc::Tstr_value(_, bindings) => ta
            .value_bindings(*bindings)
            .iter()
            .any(|binding| typed_expression_uses_ident(ta, binding.vb_expr, target)),
        StructureItemDesc::Tstr_module(binding) => {
            typed_module_expr_uses_ident(ta, ta.module_expr(binding.mb_expr), target)
        }
        StructureItemDesc::Tstr_recmodule(bindings) => bindings.iter().any(|binding| {
            typed_module_expr_uses_ident(ta, ta.module_expr(binding.mb_expr), target)
        }),
        StructureItemDesc::Tstr_modtype(decl) => {
            decl.mtd_type.as_ref().is_some_and(|module_type| {
                typed_module_type_uses_ident(ta, ta.module_type(*module_type), target)
            })
        }
        StructureItemDesc::Tstr_include(include) => {
            typed_module_expr_uses_ident(ta, ta.module_expr(include.incl_mod), target)
        }
        StructureItemDesc::Tstr_primitive(_)
        | StructureItemDesc::Tstr_type(_, _)
        | StructureItemDesc::Tstr_typext(_)
        | StructureItemDesc::Tstr_exception(_)
        | StructureItemDesc::Tstr_open(_)
        | StructureItemDesc::Tstr_attribute(_) => false,
        StructureItemDesc::Tstr_derived(idx) => ta.derived.bound(*idx).any(|bound| {
            ta.derived.values_of(&bound).any(|path| {
                matches!(path.view(), crate::types::path::PathView::Pident(id) if id.same(target))
            })
        }),
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RecAccess {
    Guarded,
    Unguarded,
    Dereferenced,
}

type RecUse = HashMap<Ident, RecAccess>;
type RecEnv = HashMap<Ident, RecUse>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RecExpressionClass {
    Static,
    Dynamic,
}

fn rec_access_join(left: RecAccess, right: RecAccess) -> RecAccess {
    match (left, right) {
        (RecAccess::Dereferenced, _) | (_, RecAccess::Dereferenced) => RecAccess::Dereferenced,
        (RecAccess::Unguarded, _) | (_, RecAccess::Unguarded) => RecAccess::Unguarded,
        (RecAccess::Guarded, RecAccess::Guarded) => RecAccess::Guarded,
    }
}

fn rec_use_join(mut left: RecUse, right: RecUse) -> RecUse {
    for (id, access) in right {
        left.entry(id)
            .and_modify(|existing| *existing = rec_access_join(*existing, access))
            .or_insert(access);
    }
    left
}

fn rec_use_single(id: Ident, access: RecAccess) -> RecUse {
    let mut use_ = RecUse::default();
    use_.insert(id, access);
    use_
}

fn rec_use_map(use_: RecUse, f: impl Fn(RecAccess) -> RecAccess) -> RecUse {
    use_.into_iter()
        .map(|(id, access)| (id, f(access)))
        .collect()
}

fn rec_use_guard(use_: RecUse) -> RecUse {
    rec_use_map(use_, |access| match access {
        RecAccess::Dereferenced => RecAccess::Dereferenced,
        RecAccess::Guarded | RecAccess::Unguarded => RecAccess::Guarded,
    })
}

fn rec_use_inspect(use_: RecUse) -> RecUse {
    rec_use_map(use_, |_| RecAccess::Dereferenced)
}

fn rec_use_delay(use_: RecUse) -> RecUse {
    rec_use_map(use_, |_| RecAccess::Guarded)
}

fn rec_use_discard(use_: RecUse) -> RecUse {
    rec_use_guard(use_)
}

fn rec_env_join(mut left: RecEnv, right: RecEnv) -> RecEnv {
    for (id, use_) in right {
        match left.entry(id) {
            std::collections::hash_map::Entry::Occupied(mut existing) => {
                let existing = existing.get_mut();
                *existing = rec_use_join(std::mem::take(existing), use_);
            }
            std::collections::hash_map::Entry::Vacant(slot) => {
                slot.insert(use_);
            }
        }
    }
    left
}

fn rec_pattern_variables(ta: &TypedArena, pat: &Pattern) -> Vec<Ident> {
    fn collect(ta: &TypedArena, pat: &Pattern, vars: &mut Vec<Ident>) {
        match &pat.pat_desc {
            PatternDesc::Tpat_var(id, _) => vars.push(*id),
            PatternDesc::Tpat_alias(inner, id, _) => {
                collect(ta, ta.pattern(*inner), vars);
                vars.push(*id);
            }
            PatternDesc::Tpat_tuple(items) | PatternDesc::Tpat_array(items) => {
                for item in ta.patterns(*items) {
                    collect(ta, item, vars);
                }
            }
            PatternDesc::Tpat_construct(_, _, args) => {
                for arg in ta.patterns(*args) {
                    collect(ta, arg, vars);
                }
            }
            PatternDesc::Tpat_variant(_, Some(arg), _) => collect(ta, ta.pattern(*arg), vars),
            PatternDesc::Tpat_record(fields, _, _) => {
                for (_, _, field_pat, _) in fields {
                    collect(ta, ta.pattern(*field_pat), vars);
                }
            }
            PatternDesc::Tpat_dict(entries) => {
                for entry in entries {
                    collect(ta, ta.pattern(entry.tdp_pattern), vars);
                }
            }
            PatternDesc::Tpat_or(left, right, _) => {
                collect(ta, ta.pattern(*left), vars);
                collect(ta, ta.pattern(*right), vars);
            }
            PatternDesc::Tpat_any
            | PatternDesc::Tpat_constant(_)
            | PatternDesc::Tpat_interval(..)
            | PatternDesc::Tpat_variant(_, None, _) => {}
        }
    }
    let mut vars = Vec::new();
    collect(ta, pat, &mut vars);
    vars
}

fn rec_pattern_is_destructuring(ta: &TypedArena, pat: &Pattern) -> bool {
    match &pat.pat_desc {
        PatternDesc::Tpat_any | PatternDesc::Tpat_var(_, _) => false,
        PatternDesc::Tpat_alias(inner, _, _) => {
            rec_pattern_is_destructuring(ta, ta.pattern(*inner))
        }
        PatternDesc::Tpat_constant(_)
        | PatternDesc::Tpat_interval(..)
        | PatternDesc::Tpat_tuple(_)
        | PatternDesc::Tpat_construct(_, _, _)
        | PatternDesc::Tpat_variant(_, _, _)
        | PatternDesc::Tpat_record(_, _, _)
        | PatternDesc::Tpat_dict(_)
        | PatternDesc::Tpat_array(_) => true,
        PatternDesc::Tpat_or(left, right, _) => {
            rec_pattern_is_destructuring(ta, ta.pattern(*left))
                || rec_pattern_is_destructuring(ta, ta.pattern(*right))
        }
    }
}

fn rec_path(env: &RecEnv, path: &Path) -> RecUse {
    match path.view() {
        PathView::Pident(id) => env.get(id).cloned().unwrap_or_default(),
        PathView::Pdot(prefix, _, _) => rec_use_inspect(rec_path(env, prefix)),
        PathView::Papply(functor, arg) => {
            rec_use_inspect(rec_use_join(rec_path(env, functor), rec_path(env, arg)))
        }
    }
}

fn rec_is_ref_value(desc: &ValueDescription) -> bool {
    matches!(
        &desc.val_kind,
        crate::types::ValueKind::ValPrim(prim)
            if prim.prim_name == "%makeref" && prim.prim_arity == 1
    )
}

fn rec_expression_class(ta: &TypedArena, expr: TExprIdx) -> RecExpressionClass {
    let expr = ta.expr(expr);
    match &expr.exp_desc {
        ExpressionDesc::Texp_let(_, _, body)
        | ExpressionDesc::Texp_letmodule(_, _, _, body)
        | ExpressionDesc::Texp_sequence(_, body)
        | ExpressionDesc::Texp_letexception(_, body) => rec_expression_class(ta, *body),
        ExpressionDesc::Texp_ident(_, _, _)
        | ExpressionDesc::Texp_constant(_)
        | ExpressionDesc::Texp_tuple(_)
        | ExpressionDesc::Texp_array(_)
        | ExpressionDesc::Texp_construct(_, _, _)
        | ExpressionDesc::Texp_variant(_, _)
        | ExpressionDesc::Texp_record { .. }
        | ExpressionDesc::Texp_object_literal(_)
        | ExpressionDesc::Texp_setfield(_, _, _, _)
        | ExpressionDesc::Texp_while(_, _)
        | ExpressionDesc::Texp_for(_, _, _, _, _, _)
        | ExpressionDesc::Texp_for_of(_, _, _, _)
        | ExpressionDesc::Texp_for_await_of(_, _, _, _)
        | ExpressionDesc::Texp_pack(_)
        | ExpressionDesc::Texp_function { .. }
        | ExpressionDesc::Texp_break
        | ExpressionDesc::Texp_continue => RecExpressionClass::Static,
        ExpressionDesc::Texp_apply { funct, .. } => {
            if matches!(&ta.expr(*funct).exp_desc, ExpressionDesc::Texp_ident(_, _, desc) if rec_is_ref_value(desc))
            {
                RecExpressionClass::Static
            } else {
                RecExpressionClass::Dynamic
            }
        }
        // A dict literal is built by the `Pmakedict` and `Pdict_spread`
        // primitives, and an array or list literal with spreads by
        // `Parray_spread` or `Plist_spread`, see `Translcore`
        // (compiler/ml/rec_check.ml `classify_expression`).
        ExpressionDesc::Texp_dict(_)
        | ExpressionDesc::Texp_spread(_, _)
        | ExpressionDesc::Texp_match(_, _, _, _)
        | ExpressionDesc::Texp_ifthenelse(_, _, _)
        | ExpressionDesc::Texp_object_get(_, _)
        | ExpressionDesc::Texp_object_set(_, _, _)
        | ExpressionDesc::Texp_field(_, _, _)
        | ExpressionDesc::Texp_assert(_)
        | ExpressionDesc::Texp_try(_, _, _)
        | ExpressionDesc::Texp_tagged_template { .. }
        | ExpressionDesc::Texp_template { .. } => RecExpressionClass::Dynamic,
    }
}

fn rec_option_expression(
    ta: &TypedArena,
    ctx: &TypeContext,
    env: &RecEnv,
    expr: Option<&TExprIdx>,
) -> RecUse {
    expr.map_or_else(RecUse::default, |expr| rec_expression(ta, ctx, env, *expr))
}

fn rec_case(
    ta: &TypedArena,
    ctx: &TypeContext,
    env: &RecEnv,
    case: &crate::types::typedtree::Case,
    scrutinee: RecUse,
) -> RecUse {
    let scrutinee = if rec_pattern_is_destructuring(ta, ta.pattern(case.c_lhs)) {
        rec_use_inspect(scrutinee)
    } else {
        rec_use_discard(scrutinee)
    };
    let vars = rec_pattern_variables(ta, ta.pattern(case.c_lhs));
    let case_env = if vars.is_empty() {
        std::borrow::Cow::Borrowed(env)
    } else {
        let mut case_env = env.clone();
        for id in vars {
            case_env.insert(id, scrutinee.clone());
        }
        std::borrow::Cow::Owned(case_env)
    };
    rec_use_join(
        scrutinee,
        rec_use_join(
            rec_expression(ta, ctx, &case_env, case.c_rhs),
            rec_use_inspect(rec_option_expression(
                ta,
                ctx,
                &case_env,
                case.c_guard.as_ref(),
            )),
        ),
    )
}

fn rec_value_binding(
    ta: &TypedArena,
    ctx: &TypeContext,
    env: &RecEnv,
    binding: &ValueBinding,
) -> (RecEnv, RecUse) {
    let vars = rec_pattern_variables(ta, ta.pattern(binding.vb_pat));
    let mut use_ = rec_expression(ta, ctx, env, binding.vb_expr);
    if rec_pattern_is_destructuring(ta, ta.pattern(binding.vb_pat)) {
        use_ = rec_use_inspect(use_);
    }
    let mut binding_env = RecEnv::default();
    for id in vars {
        binding_env.insert(id, use_.clone());
    }
    (binding_env, use_)
}

fn rec_value_bindings(
    ta: &TypedArena,
    ctx: &TypeContext,
    rec_flag: RecFlag,
    env: &RecEnv,
    bindings: &[ValueBinding],
) -> (RecEnv, RecUse) {
    match rec_flag {
        RecFlag::Recursive => {
            let mut ids = Vec::new();
            let mut use_ = RecUse::default();
            for binding in bindings {
                ids.extend(rec_pattern_variables(ta, ta.pattern(binding.vb_pat)));
                use_ = rec_use_join(use_, rec_expression(ta, ctx, env, binding.vb_expr));
            }
            let mut binding_env = RecEnv::default();
            for id in ids {
                binding_env.insert(id, use_.clone());
            }
            (binding_env, use_)
        }
        RecFlag::Nonrecursive => {
            let mut out_env = RecEnv::default();
            let mut use_ = RecUse::default();
            let mut current_env = env.clone();
            for binding in bindings {
                let (binding_env, binding_use) = rec_value_binding(ta, ctx, &current_env, binding);
                current_env = rec_env_join(current_env, binding_env.clone());
                out_env = rec_env_join(out_env, binding_env);
                use_ = rec_use_join(use_, binding_use);
            }
            (out_env, use_)
        }
    }
}

fn rec_module_expr(
    ta: &TypedArena,
    ctx: &TypeContext,
    env: &RecEnv,
    module_expr: &crate::types::typedtree::ModuleExpr,
) -> RecUse {
    match &module_expr.mod_desc {
        crate::types::typedtree::ModuleExprDesc::Tmod_ident(path, _) => rec_path(env, path),
        crate::types::typedtree::ModuleExprDesc::Tmod_structure(structure) => {
            rec_use_guard(rec_structure(ta, ctx, env, structure))
        }
        crate::types::typedtree::ModuleExprDesc::Tmod_functor(_, _, _, body) => {
            rec_use_delay(rec_module_expr(ta, ctx, env, ta.module_expr(*body)))
        }
        crate::types::typedtree::ModuleExprDesc::Tmod_apply(functor, arg, _) => rec_use_join(
            rec_use_inspect(rec_module_expr(ta, ctx, env, ta.module_expr(*functor))),
            rec_use_inspect(rec_module_expr(ta, ctx, env, ta.module_expr(*arg))),
        ),
        crate::types::typedtree::ModuleExprDesc::Tmod_constraint(inner, _, _, coercion) => {
            let use_ = rec_module_expr(ta, ctx, env, ta.module_expr(*inner));
            if matches!(
                coercion,
                crate::types::typedtree::ModuleCoercion::Tcoerce_none
            ) {
                use_
            } else {
                rec_use_inspect(use_)
            }
        }
        crate::types::typedtree::ModuleExprDesc::Tmod_unpack(expr, _) => {
            rec_expression(ta, ctx, env, *expr)
        }
    }
}

fn rec_structure(
    ta: &TypedArena,
    ctx: &TypeContext,
    env: &RecEnv,
    structure: &crate::types::typedtree::Structure,
) -> RecUse {
    let mut current_env = env.clone();
    let mut use_ = RecUse::default();
    for item in ta.structure_items(structure.str_items) {
        let (item_env, item_use) = rec_structure_item(ta, ctx, &current_env, item);
        current_env = rec_env_join(current_env, item_env);
        use_ = rec_use_join(use_, item_use);
    }
    use_
}

fn rec_structure_item(
    ta: &TypedArena,
    ctx: &TypeContext,
    env: &RecEnv,
    item: &crate::types::typedtree::StructureItem,
) -> (RecEnv, RecUse) {
    match &item.str_desc {
        crate::types::typedtree::StructureItemDesc::Tstr_eval(expr, _) => {
            (RecEnv::default(), rec_expression(ta, ctx, env, *expr))
        }
        crate::types::typedtree::StructureItemDesc::Tstr_value(rec_flag, bindings) => {
            rec_value_bindings(ta, ctx, *rec_flag, env, ta.value_bindings(*bindings))
        }
        crate::types::typedtree::StructureItemDesc::Tstr_module(binding) => {
            let use_ = rec_module_expr(ta, ctx, env, ta.module_expr(binding.mb_expr));
            let mut item_env = RecEnv::default();
            item_env.insert(binding.mb_id, use_.clone());
            (item_env, use_)
        }
        crate::types::typedtree::StructureItemDesc::Tstr_recmodule(bindings) => {
            let use_ = bindings.iter().fold(RecUse::default(), |use_, binding| {
                rec_use_join(
                    use_,
                    rec_module_expr(ta, ctx, env, ta.module_expr(binding.mb_expr)),
                )
            });
            (RecEnv::default(), rec_use_inspect(use_))
        }
        crate::types::typedtree::StructureItemDesc::Tstr_include(include_decl) => (
            RecEnv::default(),
            rec_use_inspect(rec_module_expr(
                ta,
                ctx,
                env,
                ta.module_expr(include_decl.incl_mod),
            )),
        ),
        crate::types::typedtree::StructureItemDesc::Tstr_primitive(_)
        | crate::types::typedtree::StructureItemDesc::Tstr_type(_, _)
        | crate::types::typedtree::StructureItemDesc::Tstr_typext(_)
        | crate::types::typedtree::StructureItemDesc::Tstr_exception(_)
        | crate::types::typedtree::StructureItemDesc::Tstr_modtype(_)
        | crate::types::typedtree::StructureItemDesc::Tstr_open(_)
        | crate::types::typedtree::StructureItemDesc::Tstr_attribute(_) => {
            (RecEnv::default(), RecUse::default())
        }
        // Each binding of a derived item is a function whose body uses the
        // values its obligations resolved: a non-recursive group of
        // `Texp_function` bindings (`rec_value_bindings`).
        crate::types::typedtree::StructureItemDesc::Tstr_derived(idx) => {
            let mut item_env = RecEnv::default();
            let mut item_use = RecUse::default();
            for bound in ta.derived.bound(*idx) {
                let use_ = rec_use_delay(
                    ta.derived
                        .values_of(&bound)
                        .fold(RecUse::default(), |use_, path| {
                            rec_use_join(use_, rec_path(env, &path))
                        }),
                );
                item_env.insert(bound.ident, use_.clone());
                item_use = rec_use_join(item_use, use_);
            }
            (item_env, item_use)
        }
    }
}

fn rec_expression(ta: &TypedArena, ctx: &TypeContext, env: &RecEnv, expr: TExprIdx) -> RecUse {
    let expr = ta.expr(expr);
    match &expr.exp_desc {
        ExpressionDesc::Texp_function { body, .. } => rec_use_delay(rec_expression(ta, ctx, env, *body)),
        ExpressionDesc::Texp_ident(path, _, _) => rec_path(env, path),
        ExpressionDesc::Texp_let(rec_flag, bindings, body) => {
            let (binding_env, binding_use) =
                rec_value_bindings(ta, ctx, *rec_flag, env, ta.value_bindings(*bindings));
            rec_use_join(
                rec_use_discard(binding_use),
                rec_expression(ta, ctx, &rec_env_join(env.clone(), binding_env), *body),
            )
        }
        ExpressionDesc::Texp_letmodule(id, _, module_expr, body) => {
            let module_use = rec_module_expr(ta, ctx, env, ta.module_expr(*module_expr));
            let mut body_env = env.clone();
            body_env.insert(*id, module_use.clone());
            rec_use_join(
                rec_use_discard(module_use),
                rec_expression(ta, ctx, &body_env, *body),
            )
        }
        ExpressionDesc::Texp_match(scrutinee, value_cases, exn_cases, _) => {
            let scrutinee_use = rec_expression(ta, ctx, env, *scrutinee);
            let value_use = ta
                .cases(*value_cases)
                .iter()
                .fold(RecUse::default(), |use_, case| {
                    rec_use_join(use_, rec_case(ta, ctx, env, case, scrutinee_use.clone()))
                });
            let exn_use = ta
                .cases(*exn_cases)
                .iter()
                .fold(RecUse::default(), |use_, case| {
                    rec_use_join(use_, rec_expression(ta, ctx, env, case.c_rhs))
                });
            rec_use_join(value_use, exn_use)
        }
        ExpressionDesc::Texp_for(_, _, start, stop, _, body) => rec_use_join(
            rec_use_join(
                rec_use_inspect(rec_expression(ta, ctx, env, *start)),
                rec_use_inspect(rec_expression(ta, ctx, env, *stop)),
            ),
            rec_use_discard(rec_expression(ta, ctx, env, *body)),
        ),
        ExpressionDesc::Texp_for_of(_, _, iterable, body)
        | ExpressionDesc::Texp_for_await_of(_, _, iterable, body) => rec_use_join(
            rec_use_inspect(rec_expression(ta, ctx, env, *iterable)),
            rec_use_discard(rec_expression(ta, ctx, env, *body)),
        ),
        ExpressionDesc::Texp_constant(_)
        | ExpressionDesc::Texp_break
        | ExpressionDesc::Texp_continue => RecUse::default(),
        ExpressionDesc::Texp_apply { funct, args, .. } => {
            if matches!(&ta.expr(*funct).exp_desc, ExpressionDesc::Texp_ident(_, _, desc) if rec_is_ref_value(desc))
                && args.len() == 1
                && ta.apply_args(*args)[0].expression.is_some()
            {
                return rec_use_guard(rec_expression(
                    ta,
                    ctx,
                    env,
                    ta.apply_args(*args)[0].expression.expect("checked is_some"),
                ));
            }
            let args_use = ta
                .apply_args(*args)
                .iter()
                .fold(RecUse::default(), |use_, arg| {
                    rec_use_join(
                        use_,
                        rec_option_expression(ta, ctx, env, arg.expression.as_ref()),
                    )
                });
            rec_use_join(
                rec_use_inspect(rec_expression(ta, ctx, env, *funct)),
                rec_use_inspect(args_use),
            )
        }
        ExpressionDesc::Texp_tagged_template { tag, values, .. } => {
            let values_use = ta
                .expr_list(*values)
                .iter()
                .fold(RecUse::default(), |use_, value| {
                    rec_use_join(use_, rec_expression(ta, ctx, env, *value))
                });
            rec_use_join(
                rec_use_inspect(rec_expression(ta, ctx, env, *tag)),
                rec_use_inspect(values_use),
            )
        }
        ExpressionDesc::Texp_template { values, .. } => {
            rec_use_guard(ta.expr_list(*values).iter().fold(RecUse::default(), |use_, value| {
                rec_use_join(use_, rec_expression(ta, ctx, env, *value))
            }))
        }
        ExpressionDesc::Texp_tuple(items) | ExpressionDesc::Texp_array(items) => {
            rec_use_guard(ta.expr_list(*items).iter().fold(RecUse::default(), |use_, item| {
                rec_use_join(use_, rec_expression(ta, ctx, env, *item))
            }))
        }
        // compiler/ml/rec_check.ml: `Use.inspect (list expression env parts)`.
        ExpressionDesc::Texp_spread(_, parts) => {
            rec_use_inspect(ta.expr_list(*parts).iter().fold(RecUse::default(), |use_, part| {
                rec_use_join(use_, rec_expression(ta, ctx, env, *part))
            }))
        }
        ExpressionDesc::Texp_dict(entries) => {
            rec_use_inspect(ta.dict_entries(*entries).iter().fold(RecUse::default(), |use_, entry| {
                let (TypedDictEntry::Tdict_entry(_, e) | TypedDictEntry::Tdict_spread(e)) = entry;
                rec_use_join(use_, rec_expression(ta, ctx, env, *e))
            }))
        }
        ExpressionDesc::Texp_construct(_, desc, items) => {
            let args_use = ta
                .expr_list(*items)
                .iter()
                .fold(RecUse::default(), |use_, item| {
                    rec_use_join(use_, rec_expression(ta, ctx, env, *item))
                });
            let payload_is_unboxed = match desc.cstr_kind {
                crate::types::ConstructorKind::Ordinary(reference) => matches!(
                    reference.representation(ctx),
                    crate::types::VariantConstructorCase::Block(ref block) if block.is_untagged()
                ),
                crate::types::ConstructorKind::Extension(_) => false,
            };
            let args_use = if payload_is_unboxed {
                args_use
            } else {
                rec_use_guard(args_use)
            };
            let constructor_use = match &desc.cstr_kind {
                crate::types::ConstructorKind::Extension(path) => {
                    rec_use_inspect(rec_path(env, path))
                }
                crate::types::ConstructorKind::Ordinary(_) => RecUse::default(),
            };
            rec_use_join(constructor_use, args_use)
        }
        ExpressionDesc::Texp_variant(_, payload) => {
            rec_use_guard(rec_option_expression(ta, ctx, env, payload.as_ref()))
        }
        ExpressionDesc::Texp_record {
            fields,
            empty_representation,
            extended_expression,
        } => {
            // rec_check.ml:291-300: each written field's use, joined.
            let fields = ta.record_fields(*fields);
            let fields_use = fields
                .iter()
                .fold(RecUse::default(), |use_, (_, _, expr)| {
                    rec_use_join(use_, rec_expression(ta, ctx, env, *expr))
                });
            let record_use = rec_use_join(
                fields_use,
                rec_option_expression(ta, ctx, env, extended_expression.as_ref()),
            );
            let unboxed = matches!(
                crate::types::typedtree::record_representation(
                    fields,
                    empty_representation.as_deref()
                ),
                Some(crate::types::decl::RecordRepresentation::RecordUnboxed(_))
            );
            if unboxed {
                record_use
            } else {
                rec_use_guard(record_use)
            }
        }
        ExpressionDesc::Texp_ifthenelse(cond, ifso, ifnot) => rec_use_join(
            rec_use_inspect(rec_expression(ta, ctx, env, *cond)),
            rec_use_join(
                rec_expression(ta, ctx, env, *ifso),
                rec_option_expression(ta, ctx, env, ifnot.as_ref()),
            ),
        ),
        ExpressionDesc::Texp_setfield(base, _, _, value) => rec_use_join(
            rec_use_inspect(rec_expression(ta, ctx, env, *base)),
            rec_use_inspect(rec_expression(ta, ctx, env, *value)),
        ),
        ExpressionDesc::Texp_sequence(first, second) => rec_use_join(
            rec_use_discard(rec_expression(ta, ctx, env, *first)),
            rec_expression(ta, ctx, env, *second),
        ),
        ExpressionDesc::Texp_while(cond, body) => rec_use_join(
            rec_use_inspect(rec_expression(ta, ctx, env, *cond)),
            rec_use_discard(rec_expression(ta, ctx, env, *body)),
        ),
        ExpressionDesc::Texp_object_get(receiver, _) => {
            rec_use_inspect(rec_expression(ta, ctx, env, *receiver))
        }
        ExpressionDesc::Texp_object_set(receiver, _, value) => rec_use_join(
            rec_use_inspect(rec_expression(ta, ctx, env, *receiver)),
            rec_use_inspect(rec_expression(ta, ctx, env, *value)),
        ),
        ExpressionDesc::Texp_object_literal(fields) => {
            rec_use_inspect(fields.iter().fold(RecUse::default(), |use_, (_, field)| {
                rec_use_join(use_, rec_expression(ta, ctx, env, *field))
            }))
        }
        ExpressionDesc::Texp_field(base, _, _) | ExpressionDesc::Texp_assert(base) => {
            rec_use_inspect(rec_expression(ta, ctx, env, *base))
        }
        ExpressionDesc::Texp_letexception(_, body) => rec_expression(ta, ctx, env, *body),
        ExpressionDesc::Texp_pack(module_expr) => {
            rec_module_expr(ta, ctx, env, ta.module_expr(*module_expr))
        }
        ExpressionDesc::Texp_try(body, cases, finally) => {
            let cases_use = ta.cases(*cases).iter().fold(RecUse::default(), |use_, case| {
                rec_use_join(use_, rec_expression(ta, ctx, env, case.c_rhs))
            });
            // rec_check.ml: the finally block's value is discarded.
            let finally_use = match finally {
                None => RecUse::default(),
                Some(finally) => rec_use_discard(rec_expression(ta, ctx, env, *finally)),
            };
            rec_use_join(rec_use_join(rec_expression(ta, ctx, env, *body), cases_use), finally_use)
        }
    }
}

fn rec_binding_rhs_is_exempt(ta: &TypedArena, ctx: &TypeContext, expr: &Expression) -> bool {
    match &expr.exp_desc {
        ExpressionDesc::Texp_function { .. } => true,
        // rec_check.ml:497-502: a record of a single field, a function.
        ExpressionDesc::Texp_record { fields, .. } => {
            matches!(
                ta.record_fields(*fields),
                [(_, _, expr)] if matches!(ta.expr(*expr).exp_desc, ExpressionDesc::Texp_function { .. })
            ) && crate::types::typedtree::record_all_labels(ctx, ta.record_fields(*fields))
                .is_some_and(|labels| labels.len() == 1)
        }
        _ => false,
    }
}

fn check_recursive_expression(
    ta: &TypedArena,
    ctx: &TypeContext,
    idlist: &[Ident],
    expr: TExprIdx,
) -> TypeCoreResult<()> {
    let expr_idx = expr;
    let expr = ta.expr(expr_idx);
    let env = idlist
        .iter()
        .cloned()
        .fold(RecEnv::default(), |mut env, id| {
            env.insert(id, rec_use_single(id, RecAccess::Unguarded));
            env
        });
    let use_ = rec_expression(ta, ctx, &env, expr_idx);
    let has_unguarded = use_
        .values()
        .any(|access| matches!(access, RecAccess::Unguarded | RecAccess::Dereferenced));
    let has_dependency = !use_.is_empty();
    if has_unguarded
        || (has_dependency && rec_expression_class(ta, expr_idx) == RecExpressionClass::Dynamic)
    {
        Err(TypeCoreError::IllegalLetrecExpr { loc: expr.exp_loc })
    } else {
        Ok(())
    }
}

fn check_recursive_bindings(
    ta: &TypedArena,
    ctx: &TypeContext,
    bindings: &[ValueBinding],
) -> TypeCoreResult<()> {
    let ids = bindings
        .iter()
        .flat_map(|binding| rec_pattern_variables(ta, ta.pattern(binding.vb_pat)))
        .collect::<Vec<_>>();
    for binding in bindings {
        if !rec_binding_rhs_is_exempt(ta, ctx, ta.expr(binding.vb_expr)) {
            check_recursive_expression(ta, ctx, &ids, binding.vb_expr)?;
        }
    }
    Ok(())
}

fn should_warn_unused_name(name: &str) -> bool {
    !name.is_empty() && !name.starts_with('_') && !name.starts_with('#')
}

fn report_let_partial_match_warnings<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    bindings: &[ValueBinding],
) -> Result<(), TypeCoreError> {
    let arena = tctx.arena;
    for binding in bindings {
        // typecore.ml:5051-5053: each check runs in the binding's warning
        // scope (`Builtin_attributes.warning_scope ~ppwarning:false attrs`).
        crate::types::typemod::with_warning_scope(
            tctx,
            arena,
            &binding.vb_attributes,
            false,
            |tctx| {
                report_let_partial_match_warning(tctx, env, binding);
                Ok::<(), TypeCoreError>(())
            },
        )?;
    }
    Ok(())
}

fn report_let_partial_match_warning<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    binding: &ValueBinding,
) {
    let ctx = tctx.type_ctx;
    {
        // OCaml compiler/ml/typecore.ml:4680-4700 computes the LetUnwrap
        // partial-match warning hint before calling `check_partial`, and before
        // typecore.ml:4715 `end_def ()`. That `Ctype.expand_head` side effect
        // is observable because persistent type aliases may be forced while
        // identifiers for later bindings have not been allocated.
        let hint = if tctx.experimental_let_unwrap {
            let expanded = crate::types::ctype::expand_head(
                ctx,
                env,
                tctx.typed.pattern(binding.vb_pat).pat_type,
            );
            let desc = ctx.get_desc(ctx.repr(expanded));
            match &*desc {
                TypeDesc::Tconstr { path, .. }
                    if path.same(&crate::types::predef::path_option())
                        || path.same(&crate::types::predef::path_result()) =>
                {
                    Some("Hint: You can use `let?` to automatically unwrap this expression.")
                }
                _ => None,
            }
        } else {
            None
        };
        let case = PatCase {
            lhs: binding.vb_pat,
            guarded: false,
        };
        parmatch_check_partial(
            tctx,
            env,
            ctx.current_level(),
            hint,
            tctx.typed.pattern(binding.vb_pat).pat_type,
            tctx.typed.pattern(binding.vb_pat).pat_loc,
            &[case],
        );
    }
}

/// Type check let bindings.
fn type_let_bindings(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    rec_flag: RecFlag,
    bindings: &[crate::parser::ast::ValueBinding],
    allow_modules: bool,
    let_check: LetCheck,
) -> TypeCoreResult<(Vec<ValueBinding>, Env, Vec<PatternVariable>)> {
    let previous_recursive_value_count = tctx.active_recursive_value_ids.len();
    // OCaml typecore.ml:4503-4514 maps `Ast_helper.Typ.varify_constructors`
    // over the bindings before `begin_def`; a type variable that names one of
    // the locally abstract types escapes as an uncaught `Syntaxerr.Error`.
    if bindings.iter().any(|binding| {
        tctx.arena
            .value_constraint_varify_error(binding.pvb_pat)
            .is_some()
    }) {
        crate::misc::raise_uncaught("Syntaxerr.Error(_)");
    }
    let result = (|| -> TypeCoreResult<(Vec<ValueBinding>, Env, Vec<PatternVariable>)> {
        let ctx = tctx.type_ctx;

        // Begin a new definition level
        ctx.begin_def();

        // Create type variables for all bindings
        let binding_types: Vec<TypeExprRef> = bindings.iter().map(|_| ctx.new_var(None)).collect();

        // OCaml typecore.ml:4503-4514 turns `pvb_constraint` into a
        // polymorphic pattern constraint before typing the let patterns. The
        // immutable typechecker arena reads the equivalent parser-side cache.
        let binding_patterns = bindings
            .iter()
            .map(|binding| {
                tctx.arena
                    .value_constraint(binding.pvb_pat)
                    .and_then(|constraint| constraint.pvc_pattern)
                    .unwrap_or(binding.pvb_pat)
            })
            .collect::<Vec<_>>();

        // Match OCaml type_let: pattern typing always starts in the original
        // environment. Recursive RHS typing switches to the environment built
        // from the actual pattern-bound identifiers, not placeholder copies.
        let mut typing_env = env.clone();

        // Type check each pattern first, collecting pattern variables per binding.
        // Matches OCaml `type_let`: recursive pre-unification runs on typed patterns
        // before typing right-hand-side expressions.
        let mut typed_patterns = Vec::new();
        let mut state = PatternState::new();
        // OCaml typecore.ml:4560-4568 calls reset_pattern once in
        // type_pattern_list, then types every pattern in the let group through
        // the same pattern_variables table. This makes duplicate binders across
        // `and` bindings observable at enter_variable and preserves the group
        // binder order used by add_pattern_variables.
        state.reset(allow_modules);
        let mut all_pattern_vars: Vec<Vec<PatternVariable>> = Vec::new();

        for ((binding, pattern), ty) in bindings
            .iter()
            .zip(binding_patterns.iter())
            .zip(binding_types.iter())
        {
            let binding_state = state.checkpoint();

            // OCaml typecore.ml:1809-1811 scopes each binding's warning
            // attributes around pattern typing (without emitting ppwarning).
            let arena = tctx.arena;
            let typed_pat = crate::types::typemod::with_warning_scope(
                tctx,
                arena,
                &binding.pvb_attributes,
                false,
                |tctx| {
                    type_pattern_without_existentials(
                        tctx,
                        &typing_env,
                        arena.get_pat(*pattern),
                        *ty,
                        PatternMode::Normal,
                        &mut state,
                    )
                },
            )?;

            typed_patterns.push(typed_pat);

            // Save pattern variables from this binding
            all_pattern_vars
                .push(state.pattern_variables[binding_state.pattern_variables_len..].to_vec());
        }

        // OCaml `type_pattern_list` calls `add_pattern_variables` immediately
        // after typing every pattern. `Env.add_value` validates each binder at
        // that point, before recursive approximation and RHS typing.
        for pvars in &all_pattern_vars {
            for pv in pvars {
                if crate::types::env::check_value_name(pv.id.name(), pv.loc).is_err() {
                    return Err(TypeCoreError::IllegalValueName {
                        loc: pv.loc_idx,
                        name: pv.id.name().to_string(),
                    });
                }
            }
        }

        // Match OCaml type_let/type_pattern_list: recursive RHS typing uses the
        // environment returned by pattern typing, which contains the real
        // pattern-bound identifiers and types.
        if rec_flag == RecFlag::Recursive {
            for pvars in &all_pattern_vars {
                for pv in pvars {
                    let desc = ValueDescription {
                        val_type: pv.ty,
                        val_kind: crate::types::ValueKind::ValReg,
                        val_loc: tctx.intern_ast_loc(tctx.arena, pv.loc_idx),
                        val_attributes: Default::default(),
                        val_path: None,
                    };
                    typing_env.add_value(pv.id, desc);
                    tctx.active_recursive_value_ids.push(pv.id);
                }
            }
        }

        if rec_flag == RecFlag::Recursive {
            for (typed_pat, binding) in typed_patterns.iter().zip(bindings.iter()) {
                let approx_ty =
                    type_approx_for_rec_let(tctx, env, tctx.arena.get_expanded_expr(binding.pvb_expr))?;
                let pat_ty_for_unify = {
                    let pat_ty = typed_pat.pat_type;
                    let pat_repr = ctx.repr(pat_ty);
                    let desc = ctx.get_desc(pat_repr);
                    match &*desc {
                        TypeDesc::Tpoly { body, vars } => {
                            let body = *body;
                            let vars = *vars;
                            let (_, instantiated) = crate::types::ctype::instance_poly(
                                ctx,
                                true,
                                false,
                                ctx.type_list(vars),
                                body,
                            );
                            instantiated
                        }
                        _ => pat_ty,
                    }
                };
                unify_pattern_types(tctx, typed_pat.pat_loc, pat_ty_for_unify, approx_ty)?;
            }
        }

        // Match OCaml typecore.ml `type_let`: close/finalize polymorphic variant
        // rows in let patterns before typing RHS expressions.
        // typecore.ml:4562-4567.
        for typed_pat in typed_patterns.iter_mut() {
            if typed_pattern_has_variant(&tctx.typed, typed_pat) {
                parmatch_pressure_variants(tctx, env, &[&*typed_pat]);
                finalize_variant_in_pattern(tctx, env, typed_pat, false);
            }
        }
        // typecore.ml:4569: `List.iter (fun f -> f ()) force`.
        run_globalize_forces(tctx, state.take_globalize_forces())?;

        // typecore.ml:4572-4632: the unused-binding detection. Uses of a
        // bound identifier call its callback; within a recursive group they
        // only record a dependency in the slot of the binding being typed.
        let is_recursive = rec_flag == RecFlag::Recursive;
        let group = tctx.type_ctx.usage().new_let_group();
        let (check_probe, check_strict_probe) = match let_check {
            LetCheck::Local => (
                Warning::UnusedVariable {
                    name: String::new(),
                },
                Warning::UnusedVariableStrict {
                    name: String::new(),
                },
            ),
            LetCheck::Toplevel => (
                Warning::UnusedValueDeclaration {
                    name: String::new(),
                },
                Warning::UnusedValueDeclaration {
                    name: String::new(),
                },
            ),
            LetCheck::FakeOptional => (
                Warning::UnusedVariableStrict {
                    name: String::new(),
                },
                Warning::UnusedVariableStrict {
                    name: String::new(),
                },
            ),
        };
        let arena = tctx.arena;
        let mut warn_about_unused_bindings = false;
        for binding in bindings {
            let active = crate::types::typemod::with_warning_scope(
                tctx,
                arena,
                &binding.pvb_attributes,
                false,
                |tctx| {
                    Ok::<bool, TypeCoreError>(
                        tctx.warning_config.is_active(&check_probe)
                            || tctx.warning_config.is_active(&check_strict_probe)
                            || (is_recursive
                                && tctx.warning_config.is_active(&Warning::UnusedRecFlag)),
                    )
                },
            )?;
            if active {
                warn_about_unused_bindings = true;
                break;
            }
        }
        let mut let_slots: Vec<Option<crate::types::usage::LetSlot>> = Vec::new();
        for ((binding, typed_pat), pvars) in bindings
            .iter()
            .zip(typed_patterns.iter())
            .zip(all_pattern_vars.iter())
        {
            let slot = crate::types::typemod::with_warning_scope(
                tctx,
                arena,
                &binding.pvb_attributes,
                false,
                |tctx| {
                    if !warn_about_unused_bindings {
                        return Ok::<_, TypeCoreError>(None);
                    }
                    let (some_used, slot) = {
                        let mut usage = tctx.type_ctx.usage();
                        (usage.new_cell(), usage.new_let_slot())
                    };
                    // Owned, since the checks below update `tctx`; variable
                    // names are the identifiers' static names.
                    let bound: Vec<(Ident, std::borrow::Cow<'static, str>)> =
                        typed_pattern_bound_idents(&tctx.typed, typed_pat)
                            .into_iter()
                            .map(|(id, name, _)| {
                                let name = if name == id.name() {
                                    std::borrow::Cow::Borrowed(id.name())
                                } else {
                                    std::borrow::Cow::Owned(name.to_string())
                                };
                                (*id, name)
                            })
                            .collect();
                    for (id, name) in bound {
                        let id = &id;
                        let name: &str = &name;
                        let Some(pv) = pvars.iter().find(|pv| pv.id.same(id)) else {
                            continue;
                        };
                        let used = tctx.type_ctx.usage().new_cell();
                        if should_warn_unused_name(name) && !pv.loc.loc_ghost {
                            tctx.add_let_value_check(let_check, name, pv.loc_idx, used, some_used);
                        }
                        tctx.type_ctx.usage().set_let_value_used_callback(
                            name, pv.loc, group, slot, used, some_used,
                        );
                    }
                    Ok(Some(slot))
                },
            )?;
            let_slots.push(slot);
        }

        // Type check expressions after recursive approximation unification.
        // OCaml typecore.ml type_let lines 4189-4211
        let mut typed_bindings = Vec::new();
        for (((binding, typed_pat), _ty), slot) in bindings
            .iter()
            .zip(typed_patterns)
            .zip(binding_types.iter())
            .zip(let_slots.iter())
        {
            // typecore.ml:4641: `if is_recursive then current_slot := slot`.
            if is_recursive {
                tctx.type_ctx.usage().set_let_current_slot(group, *slot);
            }
            // OCaml typecore.ml lines 4196-4209: Tpoly pattern types get special handling
            let pat_ty = typed_pat.pat_type;
            let pat_repr = ctx.repr(pat_ty);
            let pat_desc = ctx.get_desc(pat_repr);
            let arena = tctx.arena;
            let typed_expr = crate::types::typemod::with_warning_scope(
                tctx,
                arena,
                &binding.pvb_attributes,
                true,
                |tctx| match &*pat_desc {
                    TypeDesc::Tpoly { body, vars } => {
                        let body = *body;
                        let vars = *vars;
                        // OCaml: begin_def(); let vars, ty' = instance_poly ~keep_names:true true tl ty
                        ctx.begin_def();
                        let (inst_vars, inst_ty) =
                            crate::types::ctype::instance_poly(ctx, true, true, ctx.type_list(vars), body);
                        let exp = type_value_binding_expression(
                            tctx,
                            &typing_env,
                            binding,
                            inst_ty,
                            let_check,
                        )?;
                        ctx.end_def();
                        // OCaml: check_univars env true "definition" exp pat.pat_type vars
                        check_univars_or_less_general(
                            tctx,
                            env,
                            true,
                            "definition",
                            &exp,
                            pat_ty,
                            &inst_vars,
                        )?;
                        // OCaml: {exp with exp_type = instance env exp.exp_type}
                        let new_exp_type = crate::types::ctype::instance(ctx, exp.exp_type);
                        Ok(Expression {
                            exp_type: new_exp_type,
                            ..exp
                        })
                    }
                    _ => {
                        // OCaml: type_expect ~context exp_env sexp pat.pat_type
                        type_value_binding_expression(tctx, &typing_env, binding, pat_ty, let_check)
                    }
                },
            )?;
            typed_bindings.push(ValueBinding::new(
                tctx.typed.push_pattern(typed_pat),
                tctx.push_expr(typed_expr),
                binding.pvb_loc,
                // typecore.ml type_let: as written, like a value
                // description's in `Typedecl`.
                crate::ast_jsx_component::binding_attributes(arena, binding),
            ));
        }

        // typecore.ml:4671-4680: `current_slot := None`, then the unused rec
        // flag when no use was recorded while typing the group.
        tctx.type_ctx.usage().set_let_current_slot(group, None);
        if is_recursive
            && !tctx.type_ctx.usage().let_rec_needed(group)
            && tctx.warning_config.is_active(&Warning::UnusedRecFlag)
            && let Some(first) = bindings.first()
        {
            // `List.hd spat_sexp_list` after the `pvb_constraint` rewrite
            // (typecore.ml:4505-4514), whose pattern spans the binding.
            let pat_loc = tctx.arena.get_pat(binding_patterns[0]).ppat_loc;
            crate::types::typemod::with_warning_scope(
                tctx,
                arena,
                &first.pvb_attributes,
                false,
                |tctx| {
                    tctx.report_warning(pat_loc, Warning::UnusedRecFlag);
                    Ok::<(), TypeCoreError>(())
                },
            )?;
        }

        report_let_partial_match_warnings(tctx, env, &typed_bindings)?;

        // End definition level
        ctx.end_def();
        // Match OCaml typecore.ml `type_let`: generalize over every typed
        // subpattern (not just root binding types) using iter_pattern.
        for binding in typed_bindings.iter() {
            let is_nonexp = is_nonexpansive_expression(tctx, binding.vb_expr);
            if !is_nonexp {
                iter_typed_pattern(
                    &tctx.typed,
                    tctx.typed.pattern(binding.vb_pat),
                    &mut |pat| {
                        crate::types::ctype::generalize_expansive(ctx, env, pat.pat_type);
                    },
                );
            }
        }

        for binding in &typed_bindings {
            iter_typed_pattern(
                &tctx.typed,
                tctx.typed.pattern(binding.vb_pat),
                &mut |pat| {
                    crate::types::generalize(ctx, pat.pat_type);
                },
            );
        }

        if rec_flag == RecFlag::Recursive {
            for binding in &typed_bindings {
                match &tctx.typed.pattern(binding.vb_pat).pat_desc {
                    PatternDesc::Tpat_var(_, _) => {}
                    PatternDesc::Tpat_alias(inner, _, _)
                        if matches!(tctx.typed.pattern(*inner).pat_desc, PatternDesc::Tpat_any) => {
                    }
                    _ => {
                        return Err(TypeCoreError::IllegalLetrecPat {
                            loc: tctx.typed.pattern(binding.vb_pat).pat_loc,
                        });
                    }
                }
            }
        }

        // Build final environment from all collected pattern variables.
        // Module unpack bindings are first bound as values (package type), then
        // lowered into nested Texp_letmodule wrappers around the let body.
        let mut new_env = env.clone();
        let mut unpacks: Vec<PatternVariable> = Vec::new();
        for pvars in all_pattern_vars.iter() {
            for pv in pvars {
                let desc = ValueDescription {
                    val_type: pv.ty,
                    val_kind: crate::types::ValueKind::ValReg,
                    val_loc: tctx.intern_ast_loc(tctx.arena, pv.loc_idx),
                    val_attributes: Default::default(),
                    val_path: None,
                };
                new_env.add_value(pv.id, desc);
                if pv.is_module {
                    // OCaml records unpack vars in reverse insertion order
                    // (`module_variables := x :: module_variables`).
                    unpacks.insert(0, pv.clone());
                }
            }
        }

        Ok((typed_bindings, new_env, unpacks))
    })();

    tctx.active_recursive_value_ids
        .truncate(previous_recursive_value_count);
    result
}

// ============================================================================
// Top-Level Entry Points
// ============================================================================

/// typecore.ml:4753-4758: `Printtyp.type_expr` into a buffer formatter.
fn format_toplevel_return_type(ctx: &TypeContext, ty: TypeExprRef) -> String {
    crate::types::printtyp::Printtyp::new(ctx).type_expr(ty)
}

/// Type check a top-level expression.
pub fn type_expression<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    expr: &ParsedExpression,
) -> TypeCoreResult<Expression> {
    let type_ctx = tctx.type_ctx;
    // Match OCaml Typecore.type_expression -> Typetexp.reset_type_variables.
    tctx.reset_type_variables();

    // Begin a definition scope
    type_ctx.begin_def();

    // Type with a fresh variable
    let expected_ty = type_ctx.new_var(None);
    let typed_expr = type_expect(tctx, env, expr, expected_ty, None)?;

    // OCaml Typecore.type_expression warns when a toplevel expression cannot
    // be coerced to unit, and the default warn-error set turns warning 109 into
    // a compilation error.
    let warning_probe = Warning::BsToplevelExpressionUnit {
        return_type: None,
        is_function_call: false,
    };
    if tctx.warning_config.is_active(&warning_probe) {
        let unit_ty = env.type_unit(type_ctx);
        match crate::types::unify(
            type_ctx,
            &mut tctx.unify_state,
            typed_expr.exp_type,
            unit_ty,
        ) {
            Ok(()) => {}
            Err(TypeError::Unify(_)) => {
                tctx.report_warning(
                    expr.pexp_loc,
                    Warning::BsToplevelExpressionUnit {
                        return_type: Some(format_toplevel_return_type(
                            type_ctx,
                            typed_expr.exp_type,
                        )),
                        is_function_call: matches!(
                            &expr.pexp_desc,
                            crate::parser::ast::ExpressionDesc::Pexp_apply(_)
                        ),
                    },
                );
            }
            Err(TypeError::TagsConflict(_, _)) => {
                tctx.report_warning(expr.pexp_loc, warning_probe);
            }
            Err(_) => {}
        }
    }

    // End definition scope
    type_ctx.end_def();

    if !is_nonexpansive_node(tctx, &typed_expr) {
        crate::types::ctype::generalize_expansive(type_ctx, env, typed_expr.exp_type);
    }

    // Generalize the type
    crate::types::generalize(type_ctx, typed_expr.exp_type);

    Ok(typed_expr)
}

/// Type check a top-level binding.
pub fn type_binding<'a>(
    tctx: &mut TypeCheckContext<'a>,
    env: &Env,
    rec_flag: RecFlag,
    bindings: &[crate::parser::ast::ValueBinding],
) -> TypeCoreResult<(Vec<ValueBinding>, Env)> {
    // Match OCaml Typecore.type_binding -> Typetexp.reset_type_variables.
    tctx.reset_type_variables();
    let (typed_bindings, new_env, _unpacks) =
        type_let_bindings(tctx, env, rec_flag, bindings, false, LetCheck::Toplevel)?;
    // OCaml typemod.ml:1411-1415 runs Rec_check right after type_binding.
    if rec_flag == RecFlag::Recursive {
        check_recursive_bindings(&tctx.typed, tctx.type_ctx, &typed_bindings)?;
    }
    Ok((typed_bindings, new_env))
}

fn clone_copy_lookup_path(path: &Path) -> Path {
    *path
}

/// `Subst.module_path` of an alias target with no substitution
/// (subst.ml:69-75): a `Pident` target is the block itself, a dotted one is
/// rebuilt around its prefix.
pub(crate) fn copy_alias_target(path: &std::sync::Arc<Path>) -> std::sync::Arc<Path> {
    match path.view() {
        PathView::Pident(_) => path.clone(),
        _ => std::sync::Arc::new(**path),
    }
}

/// `Subst.type_expr` with a type/module path map: copies the graph keeping
/// generic levels and physical sharing, rewriting paths through `map_path`.
pub(crate) fn copy_type_expr_mapping_paths<TP: Fn(&Path) -> Path>(
    ctx: &TypeContext,
    ty: TypeExprRef,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    map_path: &TP,
) -> TypeExprRef {
    if ctx.counts_this_call() {
        return ctx.counted_copy(crate::perf_counters::CopyCause::Lookup, || {
            copy_type_expr_mapping_paths(ctx, ty, cache, map_path)
        });
    }
    copy_lookup_type_expr_with_paths(ctx, ty, cache, map_path)
}

fn copy_lookup_type_expr_with_paths<TP>(
    ctx: &TypeContext,
    ty: TypeExprRef,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
) -> TypeExprRef
where
    TP: Fn(&Path) -> Path,
{
    use crate::types::type_expr::{MutabilityRef, RowDesc, RowField};

    enum CopyRowFieldPlan {
        Rpresent(Option<TypeExprRef>),
        Reither {
            constant: bool,
            types: Vec<TypeExprRef>,
            matched: bool,
            link: crate::types::type_expr::RowFieldRef,
        },
        Rabsent,
    }

    enum CopyTypeExprPlan {
        Tvar(Option<crate::name::Name>),
        Tarrow {
            args: crate::types::type_expr::TypeArgList,
            ret: TypeExprRef,
        },
        Ttuple(crate::types::type_expr::TypeRefList),
        Tconstr {
            path: Path,
            args: crate::types::type_expr::TypeRefList,
        },
        Tobject {
            fields: TypeExprRef,
        },
        Tfield {
            name: crate::name::Name,
            mutability: MutabilityRef,
            typ: TypeExprRef,
            rest: TypeExprRef,
        },
        Tnil,
        Tlink(TypeExprRef),
        Tsubst(TypeExprRef),
        Tvariant {
            row_fields: Vec<(crate::types::asttypes::Label, CopyRowFieldPlan)>,
            row_more: TypeExprRef,
            row_closed: bool,
            row_fixed: bool,
            row_name: Option<(Path, Vec<TypeExprRef>)>,
        },
        Tunivar(Option<crate::name::Name>),
        Tpoly {
            body: TypeExprRef,
            vars: crate::types::type_expr::TypeRefList,
        },
        Tpackage {
            path: Path,
            lids: Vec<Longident>,
            args: crate::types::type_expr::TypeRefList,
        },
    }

    let ty = ctx.repr(ty);
    if let Some(&copied) = cache.get(ty) {
        return copied;
    }

    // OCaml compiler/ml/subst.ml:130-141 `Subst.typexp` short-circuits Tvar
    // and Tunivar by returning the original type when `s.for_saving` is false
    // and `ty.id >= 0`. The `for_saving` flag is only set during CMI write,
    // so during normal substitution and `Subst.identity` freshening (which is
    // what these copy helpers mirror) every Tvar/Tunivar is shared with the
    // source. Allocating fresh nodes here advances the typedtree stamp stream
    // ahead of OCaml's typedtree stamp stream when copying shared row variables.
    {
        let desc = ctx.borrow_desc(ty);
        if matches!(*desc, TypeDesc::Tvar(..) | TypeDesc::Tunivar(..)) {
            cache.insert(ty, ty);
            return ty;
        }
    }

    let level = ctx.get_level(ty);
    let placeholder = ctx.new_type(TypeDesc::Tvar(None));
    ctx.set_level(placeholder, level);
    cache.insert(ty, placeholder);

    let plan = {
        let desc = ctx.borrow_desc(ty);
        match &*desc {
            // subst.ml:135-143: `newty2 ty.level desc` keeps the descriptor.
            TypeDesc::Tvar(name) => {
                CopyTypeExprPlan::Tvar(*name)
            }
            TypeDesc::Tarrow { args, ret } => CopyTypeExprPlan::Tarrow {
                args: *args,
                ret: *ret,
            },
            TypeDesc::Ttuple(types) => CopyTypeExprPlan::Ttuple(*types),
            TypeDesc::Tconstr {
                path,
                args,

                ..
            } => {
                let new_path = type_path(path);
                CopyTypeExprPlan::Tconstr {
                    path: new_path,
                    args: *args,
                }
            }
            TypeDesc::Tobject { fields } => CopyTypeExprPlan::Tobject { fields: *fields },
            TypeDesc::Tfield {
                name,
                mutability,
                typ,
                rest,
            } => CopyTypeExprPlan::Tfield {
                name: *name,
                mutability: *mutability,
                typ: *typ,
                rest: *rest,
            },
            TypeDesc::Tnil => CopyTypeExprPlan::Tnil,
            TypeDesc::Tlink(target) => CopyTypeExprPlan::Tlink(*target),
            TypeDesc::Tsubst(target) => CopyTypeExprPlan::Tsubst(*target),
            TypeDesc::Tvariant(row) => {
                let row = ctx.row_desc(*row);
                CopyTypeExprPlan::Tvariant {
                row_fields: row
                    .row_fields
                    .iter()
                    .map(|(label, field)| {
                        let field = match field {
                            RowField::Rpresent(ty) => CopyRowFieldPlan::Rpresent(*ty),
                            RowField::Reither {
                                constant,
                                types,
                                matched,
                                link,
                            } => CopyRowFieldPlan::Reither {
                                constant: *constant,
                                types: types.clone(),
                                matched: *matched,
                                link: *link,
                            },
                            RowField::Rabsent => CopyRowFieldPlan::Rabsent,
                        };
                        (label.clone(), field)
                    })
                    .collect(),
                row_more: row.row_more,
                row_closed: row.row_closed,
                row_fixed: row.row_fixed,
                row_name: row.row_name.clone(),
                }
            },
            TypeDesc::Tunivar(name) => {
                CopyTypeExprPlan::Tunivar(*name)
            }
            TypeDesc::Tpoly { body, vars } => CopyTypeExprPlan::Tpoly {
                body: *body,
                vars: *vars,
            },
            TypeDesc::Tpackage { path, lids, args } => CopyTypeExprPlan::Tpackage {
                path: type_path(path),
                lids: ctx.package_lids(*lids).to_vec(),
                args: *args,
            },
        }
    };

    let copied_desc = {
        match plan {
            CopyTypeExprPlan::Tvar(name) => TypeDesc::Tvar(name),
            CopyTypeExprPlan::Tarrow { args, ret } => {
                let args = ctx.new_type_args_from(ctx.type_args(args).iter().map(|arg| {
                    let mut arg = arg;
                    arg.typ = copy_lookup_type_expr_with_paths(ctx, arg.typ, cache, type_path);
                    arg
                }));
                let ret = copy_lookup_type_expr_with_paths(ctx, ret, cache, type_path);
                TypeDesc::Tarrow { args, ret }
            }
            CopyTypeExprPlan::Ttuple(types) => {
                let copied_items = ctx.new_type_list_from(
                    ctx.type_list(types)
                        .iter()
                        .map(|t| copy_lookup_type_expr_with_paths(ctx, t, cache, type_path)),
                );
                TypeDesc::Ttuple(copied_items)
            }
            CopyTypeExprPlan::Tconstr { path, args } => {
                let copied_args = ctx.new_type_list_from(
                    ctx.type_list(args)
                        .iter()
                        .map(|t| copy_lookup_type_expr_with_paths(ctx, t, cache, type_path)),
                );
                TypeDesc::Tconstr {
                    path,
                    args: copied_args,
                    abbrev: ctx.alloc_abbrev_nil(),
                }
            }
            CopyTypeExprPlan::Tobject { fields } => TypeDesc::Tobject {
                fields: copy_lookup_type_expr_with_paths(ctx, fields, cache, type_path),
            },
            CopyTypeExprPlan::Tfield {
                name,
                mutability,
                typ,
                rest,
            } => {
                // btype.ml copy_type_desc (subst.ml typexp_rec): classify the
                // row before copying either child.
                let mutability = {
                    let cache = &*cache;
                    ctx.copy_field_mutability(mutability, rest, false, &|t| cache.get(t).copied())
                };
                let copied_typ = copy_lookup_type_expr_with_paths(ctx, typ, cache, type_path);
                let copied_rest = copy_lookup_type_expr_with_paths(ctx, rest, cache, type_path);
                TypeDesc::Tfield {
                    name,
                    mutability,
                    typ: copied_typ,
                    rest: copied_rest,
                }
            }
            CopyTypeExprPlan::Tnil => TypeDesc::Tnil,
            CopyTypeExprPlan::Tlink(target) => {
                let copied = copy_lookup_type_expr_with_paths(ctx, target, cache, type_path);
                ctx.set_desc(placeholder, TypeDesc::Tlink(copied));
                cache.insert(ty, copied);
                return copied;
            }
            CopyTypeExprPlan::Tsubst(target) => {
                let copied_target = copy_lookup_type_expr_with_paths(ctx, target, cache, type_path);
                TypeDesc::Tsubst(copied_target)
            }
            CopyTypeExprPlan::Tvariant {
                row_fields,
                row_more,
                row_closed,
                row_fixed,
                row_name,
            } => {
                let copied_row = RowDesc {
                    row_fields: row_fields
                        .into_iter()
                        .map(|(label, field)| {
                            let copied_field = match field {
                                CopyRowFieldPlan::Rpresent(Some(ty)) => RowField::Rpresent(Some(
                                    copy_lookup_type_expr_with_paths(ctx, ty, cache, type_path),
                                )),
                                CopyRowFieldPlan::Rpresent(None) => RowField::Rpresent(None),
                                CopyRowFieldPlan::Reither {
                                    constant,
                                    types,
                                    matched,
                                    link,
                                } => RowField::Reither {
                                    constant,
                                    types: types
                                        .iter()
                                        .map(|t| {
                                            copy_lookup_type_expr_with_paths(
                                                ctx, *t, cache, type_path,
                                            )
                                        })
                                        .collect(),
                                    matched,
                                    link,
                                },
                                CopyRowFieldPlan::Rabsent => RowField::Rabsent,
                            };
                            (label, copied_field)
                        })
                        .collect(),
                    row_more: copy_lookup_type_expr_with_paths(ctx, row_more, cache, type_path),
                    row_closed,
                    row_fixed,
                    // `Subst.typexp` maps the row name's path like a
                    // `Tconstr` path (compiler/ml/subst.ml:226-231).
                    row_name: row_name.as_ref().map(|(path, args)| {
                        (
                            type_path(path),
                            args.iter()
                                .map(|t| {
                                    copy_lookup_type_expr_with_paths(ctx, *t, cache, type_path)
                                })
                                .collect(),
                        )
                    }),
                };
                TypeDesc::Tvariant(ctx.new_row_desc(copied_row))
            }
            CopyTypeExprPlan::Tunivar(name) => TypeDesc::Tunivar(name),
            CopyTypeExprPlan::Tpoly { body, vars } => {
                let copied_body = copy_lookup_type_expr_with_paths(ctx, body, cache, type_path);
                let copied_vars = ctx.new_type_list_from(
                    ctx.type_list(vars)
                        .iter()
                        .map(|t| copy_lookup_type_expr_with_paths(ctx, t, cache, type_path)),
                );
                TypeDesc::Tpoly {
                    body: copied_body,
                    vars: copied_vars,
                }
            }
            CopyTypeExprPlan::Tpackage { path, lids, args } => {
                let copied_args = ctx.new_type_list_from(
                    ctx.type_list(args)
                        .iter()
                        .map(|t| copy_lookup_type_expr_with_paths(ctx, t, cache, type_path)),
                );
                TypeDesc::Tpackage {
                    path,
                    lids: ctx.new_package_lids(lids),
                    args: copied_args,
                }
            }
        }
    };

    // OCaml compiler/ml/ctype.ml:893-925 creates one stub with `newvar`,
    // stores it in `Tsubst`, then fills `t.desc` in place. Returning the same
    // placeholder preserves that sharing and avoids allocating a second node
    // plus a Tlink for every copied type.
    ctx.set_desc(placeholder, copied_desc);
    placeholder
}

fn copy_lookup_constructor_args_with_paths<TP>(
    args: &crate::types::decl::ConstructorArguments,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
) -> crate::types::decl::ConstructorArguments
where
    TP: Fn(&Path) -> Path,
{
    match args {
        crate::types::decl::ConstructorArguments::CstrTuple(items) => {
            crate::types::decl::ConstructorArguments::CstrTuple(
                items
                    .iter()
                    .map(|t| copy_lookup_type_expr_with_paths(ctx, *t, cache, type_path))
                    .collect(),
            )
        }
        crate::types::decl::ConstructorArguments::CstrRecord(labels) => {
            crate::types::decl::ConstructorArguments::CstrRecord(
                labels
                    .iter()
                    .map(|label| crate::types::decl::LabelDeclaration {
                        ld_id: label.ld_id,
                        ld_runtime_name: label.ld_runtime_name.clone(),
                        ld_mutable: label.ld_mutable,
                        ld_optional: label.ld_optional,
                        ld_type: copy_lookup_type_expr_with_paths(
                            ctx,
                            label.ld_type,
                            cache,
                            type_path,
                        ),
                        ld_loc: label.ld_loc,
                        ld_attributes: label.ld_attributes.clone(),
                    })
                    .collect(),
            )
        }
    }
}

fn copy_lookup_constructor_args(
    args: &crate::types::decl::ConstructorArguments,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::ConstructorArguments {
    copy_lookup_constructor_args_with_paths(args, ctx, cache, &clone_copy_lookup_path)
}

fn copy_lookup_type_kind_with_paths<TP>(
    kind: &crate::types::decl::TypeKind,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
) -> crate::types::decl::TypeKind
where
    TP: Fn(&Path) -> Path,
{
    match kind {
        crate::types::decl::TypeKind::TypeAbstract => crate::types::decl::TypeKind::TypeAbstract,
        crate::types::decl::TypeKind::TypeOpen => crate::types::decl::TypeKind::TypeOpen,
        crate::types::decl::TypeKind::TypeRecord(labels, repr) => {
            crate::types::decl::TypeKind::TypeRecord(
                labels
                    .iter()
                    .map(|label| crate::types::decl::LabelDeclaration {
                        ld_id: label.ld_id,
                        ld_runtime_name: label.ld_runtime_name.clone(),
                        ld_mutable: label.ld_mutable,
                        ld_optional: label.ld_optional,
                        ld_type: copy_lookup_type_expr_with_paths(
                            ctx,
                            label.ld_type,
                            cache,
                            type_path,
                        ),
                        ld_loc: label.ld_loc,
                        ld_attributes: label.ld_attributes.clone(),
                    })
                    .collect(),
                repr.clone(),
            )
        }
        crate::types::decl::TypeKind::TypeVariant(constructors, layout) => {
            crate::types::decl::TypeKind::TypeVariant(
                constructors
                    .iter()
                    .map(|constructor| crate::types::decl::ConstructorDeclaration {
                        cd_id: constructor.cd_id,
                        cd_runtime_tag: constructor.cd_runtime_tag.clone(),
                        cd_args: copy_lookup_constructor_args_with_paths(
                            &constructor.cd_args,
                            ctx,
                            cache,
                            type_path,
                        ),
                        cd_res: constructor
                            .cd_res
                            .map(|t| copy_lookup_type_expr_with_paths(ctx, t, cache, type_path)),
                        cd_loc: constructor.cd_loc,
                        cd_attributes: constructor.cd_attributes.clone(),
                    })
                    .collect(),
                *layout,
            )
        }
    }
}

fn copy_lookup_type_kind(
    kind: &crate::types::decl::TypeKind,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::TypeKind {
    copy_lookup_type_kind_with_paths(kind, ctx, cache, &clone_copy_lookup_path)
}

fn copy_lookup_type_inlined_with_paths<TP>(
    inlined: &crate::types::decl::TypeInlinedType,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
) -> crate::types::decl::TypeInlinedType
where
    TP: Fn(&Path) -> Path,
{
    match inlined {
        crate::types::decl::TypeInlinedType::Record { type_name, labels } => {
            crate::types::decl::TypeInlinedType::Record {
                type_name: type_name.clone(),
                labels: labels
                    .iter()
                    .map(|label| crate::types::decl::LabelDeclaration {
                        ld_id: label.ld_id,
                        ld_runtime_name: label.ld_runtime_name.clone(),
                        ld_mutable: label.ld_mutable,
                        ld_optional: label.ld_optional,
                        ld_type: copy_lookup_type_expr_with_paths(
                            ctx,
                            label.ld_type,
                            cache,
                            type_path,
                        ),
                        ld_loc: label.ld_loc,
                        ld_attributes: label.ld_attributes.clone(),
                    })
                    .collect(),
            }
        }
    }
}

fn copy_lookup_type_inlined(
    inlined: &crate::types::decl::TypeInlinedType,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::TypeInlinedType {
    copy_lookup_type_inlined_with_paths(inlined, ctx, cache, &clone_copy_lookup_path)
}

fn copy_lookup_type_decl_with_paths<TP>(
    decl: &crate::types::decl::TypeDeclaration,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
) -> crate::types::decl::TypeDeclaration
where
    TP: Fn(&Path) -> Path,
{
    crate::types::decl::TypeDeclaration {
        type_params: decl
            .type_params
            .iter()
            .map(|t| copy_lookup_type_expr_with_paths(ctx, *t, cache, type_path))
            .collect(),
        type_arity: decl.type_arity,
        type_kind: copy_lookup_type_kind_with_paths(&decl.type_kind, ctx, cache, type_path),
        type_private: decl.type_private,
        type_manifest: decl
            .type_manifest
            .map(|t| copy_lookup_type_expr_with_paths(ctx, t, cache, type_path)),
        type_variance: decl.type_variance.clone(),
        type_newtype_level: decl.type_newtype_level,
        type_loc: decl.type_loc,
        type_attributes: decl.type_attributes.clone(),
        type_immediate: decl.type_immediate,
        type_representation: decl.type_representation,
        type_shape: decl.type_shape.clone(),
        type_inlined_types: decl
            .type_inlined_types
            .iter()
            .map(|inlined| copy_lookup_type_inlined_with_paths(inlined, ctx, cache, type_path))
            .collect(),
        type_path: decl.type_path.as_ref().map(type_path),
    }
}

fn copy_lookup_type_decl(
    decl: &crate::types::decl::TypeDeclaration,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::TypeDeclaration {
    copy_lookup_type_decl_with_paths(decl, ctx, cache, &clone_copy_lookup_path)
}

pub(crate) fn copy_lookup_type_decl_for_subst(
    decl: &crate::types::decl::TypeDeclaration,
    ctx: &TypeContext,
) -> crate::types::decl::TypeDeclaration {
    if ctx.counts_this_call() {
        return ctx.counted_copy(crate::perf_counters::CopyCause::Lookup, || {
            copy_lookup_type_decl_for_subst(decl, ctx)
        });
    }
    let mut cache = TypeExprRefMap::new();
    ctx.with_copy_session(|| copy_lookup_type_decl(decl, ctx, &mut cache))
}

fn copy_lookup_value_description_with_paths<TP>(
    desc: &crate::types::decl::ValueDescription,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
) -> crate::types::decl::ValueDescription
where
    TP: Fn(&Path) -> Path,
{
    crate::types::decl::ValueDescription {
        val_type: copy_lookup_type_expr_with_paths(ctx, desc.val_type, cache, type_path),
        val_kind: desc.val_kind.clone(),
        val_loc: desc.val_loc,
        val_attributes: desc.val_attributes.clone(),
        val_path: desc.val_path.as_ref().map(type_path),
    }
}

pub(crate) fn copy_lookup_value_description_for_subst(
    desc: &crate::types::decl::ValueDescription,
    ctx: &TypeContext,
) -> crate::types::decl::ValueDescription {
    if ctx.counts_this_call() {
        return ctx.counted_copy(crate::perf_counters::CopyCause::Lookup, || {
            copy_lookup_value_description_for_subst(desc, ctx)
        });
    }
    let mut cache = TypeExprRefMap::new();
    ctx.with_copy_session(|| {
        copy_lookup_value_description_with_paths(desc, ctx, &mut cache, &clone_copy_lookup_path)
    })
}

fn copy_lookup_extension_constructor_with_paths<TP>(
    ext: &crate::types::decl::ExtensionConstructor,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
) -> crate::types::decl::ExtensionConstructor
where
    TP: Fn(&Path) -> Path,
{
    crate::types::decl::ExtensionConstructor {
        ext_type_path: type_path(&ext.ext_type_path),
        ext_type_params: ext
            .ext_type_params
            .iter()
            .map(|t| copy_lookup_type_expr_with_paths(ctx, *t, cache, type_path))
            .collect(),
        ext_args: copy_lookup_constructor_args_with_paths(&ext.ext_args, ctx, cache, type_path),
        ext_ret_type: ext
            .ext_ret_type
            .map(|t| copy_lookup_type_expr_with_paths(ctx, t, cache, type_path)),
        ext_private: ext.ext_private,
        ext_loc: ext.ext_loc,
        ext_attributes: ext.ext_attributes.clone(),
        ext_is_exception: ext.ext_is_exception,
    }
}

fn copy_lookup_extension_constructor(
    ext: &crate::types::decl::ExtensionConstructor,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::ExtensionConstructor {
    copy_lookup_extension_constructor_with_paths(ext, ctx, cache, &clone_copy_lookup_path)
}

fn copy_lookup_module_type_with_paths<TP, MP>(
    module_type: &crate::types::decl::ModuleType,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
    module_path: &MP,
) -> crate::types::decl::ModuleType
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&std::sync::Arc<Path>) -> std::sync::Arc<Path>,
{
    match module_type {
        crate::types::decl::ModuleType::MtyIdent(path) => {
            crate::types::decl::ModuleType::MtyIdent(type_path(path))
        }
        crate::types::decl::ModuleType::MtyAlias(alias, path) => {
            crate::types::decl::ModuleType::MtyAlias(*alias, module_path(path))
        }
        crate::types::decl::ModuleType::MtyFunctor {
            param,
            param_type,
            result,
        } => crate::types::decl::ModuleType::MtyFunctor {
            param: *param,
            param_type: param_type.as_ref().map(|inner| {
                Box::new(copy_lookup_module_type_with_paths(
                    inner,
                    ctx,
                    cache,
                    type_path,
                    module_path,
                ))
            }),
            result: Box::new(copy_lookup_module_type_with_paths(
                result,
                ctx,
                cache,
                type_path,
                module_path,
            )),
        },
        crate::types::decl::ModuleType::MtySignature(sig_items) => {
            crate::types::decl::ModuleType::MtySignature(std::sync::Arc::new(
                copy_lookup_signature_with_paths(sig_items, ctx, cache, type_path, module_path),
            ))
        }
    }
}

fn copy_lookup_module_type(
    module_type: &crate::types::decl::ModuleType,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::ModuleType {
    copy_lookup_module_type_with_paths(
        module_type,
        ctx,
        cache,
        &clone_copy_lookup_path,
        &copy_alias_target,
    )
}

fn copy_lookup_signature_with_paths<TP, MP>(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
    module_path: &MP,
) -> crate::types::decl::Signature
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&std::sync::Arc<Path>) -> std::sync::Arc<Path>,
{
    copy_lookup_signature_with_paths_and_idents(
        sig_items,
        ctx,
        cache,
        type_path,
        module_path,
        None::<std::vec::IntoIter<Option<Ident>>>,
    )
}

fn copy_lookup_signature_with_paths_and_idents<TP, MP, I>(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
    module_path: &MP,
    mut new_idents: Option<I>,
) -> crate::types::decl::Signature
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&std::sync::Arc<Path>) -> std::sync::Arc<Path>,
    I: Iterator<Item = Option<Ident>>,
{
    sig_items
        .iter()
        .map(|item| {
            let new_id = new_idents
                .as_mut()
                .and_then(|idents| idents.next())
                .flatten();
            match item {
                crate::types::decl::SignatureItem::SigValue(id, desc) => {
                    crate::types::decl::SignatureItem::SigValue(
                        new_id.unwrap_or(*id),
                        copy_lookup_value_description_with_paths(desc, ctx, cache, type_path),
                    )
                }
                crate::types::decl::SignatureItem::SigType(id, decl, rec_status) => {
                    crate::types::decl::SignatureItem::SigType(
                        new_id.unwrap_or(*id),
                        std::sync::Arc::new(copy_lookup_type_decl_with_paths(
                            decl, ctx, cache, type_path,
                        )),
                        *rec_status,
                    )
                }
                crate::types::decl::SignatureItem::SigTypext(id, ext, ext_status) => {
                    crate::types::decl::SignatureItem::SigTypext(
                        new_id.unwrap_or(*id),
                        copy_lookup_extension_constructor_with_paths(ext, ctx, cache, type_path),
                        *ext_status,
                    )
                }
                crate::types::decl::SignatureItem::SigModule(id, md, rec_status) => {
                    crate::types::decl::SignatureItem::SigModule(
                        new_id.unwrap_or(*id),
                        crate::types::decl::ModuleDeclaration {
                            md_type: copy_lookup_module_type_with_paths(
                                &md.md_type,
                                ctx,
                                cache,
                                type_path,
                                module_path,
                            ),
                            md_attributes: md.md_attributes.clone(),
                            md_loc: md.md_loc,
                            md_path: md.md_path.as_ref().map(type_path),
                        },
                        *rec_status,
                    )
                }
                crate::types::decl::SignatureItem::SigModtype(id, mtd) => {
                    crate::types::decl::SignatureItem::SigModtype(
                        new_id.unwrap_or(*id),
                        crate::types::decl::ModtypeDeclaration {
                            mtd_type: mtd.mtd_type.as_ref().map(|mty| {
                                copy_lookup_module_type_with_paths(
                                    mty,
                                    ctx,
                                    cache,
                                    type_path,
                                    module_path,
                                )
                            }),
                            mtd_attributes: mtd.mtd_attributes.clone(),
                            mtd_loc: mtd.mtd_loc,
                        },
                    )
                }
                crate::types::decl::SignatureItem::SigClass => {
                    crate::types::decl::SignatureItem::SigClass
                }
                crate::types::decl::SignatureItem::SigClassType => {
                    crate::types::decl::SignatureItem::SigClassType
                }
            }
        })
        .collect()
}

fn copy_lookup_signature(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::Signature {
    copy_lookup_signature_with_paths(
        sig_items,
        ctx,
        cache,
        &clone_copy_lookup_path,
        &copy_alias_target,
    )
}

fn should_rewrite_nested_alias_self_path(
    ctx: &crate::types::context::TypeContext,
    old_name: &str,
    parent_path: &Path,
) -> bool {
    fn same_or_descendant(path: &Path, prefix: &Path) -> bool {
        if path.same(prefix) {
            return true;
        }
        match path.view() {
            PathView::Pdot(parent, _, _) => same_or_descendant(parent, prefix),
            PathView::Pident(_) | PathView::Papply(_, _) => false,
        }
    }

    // OCaml compiler/ml/env.ml:1517 discovers flattened backing units by
    // scraping explicit aliases, then env.ml:1530 prefixes the selected
    // component path. env.ml:1573-1578 stores child components under that
    // selected path. If the resolved name is a registered backing unit for the
    // parent component, or for one of its selected child components, leave it
    // for that alias path; do not infer descendants from flattened spelling.
    let old_path = Path::pident(Ident::create_persistent(old_name));
    let old_name_is_parent_source = ctx
        .alias_sources_for_component_path(parent_path)
        .into_iter()
        .any(|source| source.same(&old_path));
    let old_name_is_registered_component_child = ctx
        .component_paths_for_alias_source(&old_path)
        .into_iter()
        .any(|component_path| same_or_descendant(&component_path, parent_path));
    !(old_name_is_parent_source || old_name_is_registered_component_child)
}

fn rewrite_flattened_alias_child_prefixes(
    sig: &[crate::types::decl::SignatureItem],
    qualified_alias_path: &Path,
    flattened_access_path: &Path,
    ctx: &crate::types::context::TypeContext,
) {
    rewrite_child_module_prefixes_from_sig(
        sig,
        sig,
        qualified_alias_path,
        flattened_access_path,
        None,
        ctx,
    );
}

fn rewrite_flattened_alias_head_prefixes(
    sig: &mut [crate::types::decl::SignatureItem],
    qualified_alias_path: &Path,
    access_path: &Path,
    pers_env: Option<&crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) {
    let mut source_prefixes = Vec::new();
    let mut add_source_prefix = |source_prefix: Path| {
        if !source_prefix.same(qualified_alias_path)
            && !source_prefixes
                .iter()
                .any(|existing: &Path| existing.same(&source_prefix))
        {
            source_prefixes.push(source_prefix);
        }
    };

    fn append_components(mut path: Path, components: &[&str]) -> Path {
        for component in components {
            path = Path::pdot(path, *component);
        }
        path
    }

    if let Ok((head, components)) = qualified_alias_path.flatten() {
        for split in 1..=components.len() {
            let prefix_components = &components[..split];
            let remaining_components = &components[split..];
            let mut qualified_prefix = Path::pident(*head);
            for component in prefix_components {
                qualified_prefix = Path::pdot(qualified_prefix, *component);
            }

            let flat_heads = pers_env
                .map(|pers| pers.flattened_alias_heads_for_path(&qualified_prefix))
                .unwrap_or_default();
            // OCaml compiler/ml/env.ml:1516-1538 discovers alias backing paths by
            // scraping real module declarations, and env.ml:1567-1578 stores the
            // selected child component path in the component table. Do not
            // synthesize flattened names from path spelling here; every source
            // prefix must come from the persistent alias table or the component
            // relation registered while building that table.
            for flat_head in flat_heads {
                add_source_prefix(append_components(
                    Path::pident(Ident::create_persistent(&flat_head)),
                    remaining_components,
                ));
            }
            for alias_source in ctx.alias_sources_for_component_path(&qualified_prefix) {
                let source_prefix = append_components(alias_source, remaining_components);
                add_source_prefix(source_prefix);
            }
        }
    }

    let rewrite_target = std::sync::Arc::new(*access_path);
    for source_prefix in source_prefixes {
        // OCaml compiler/ml/env.ml:1517 scrapes aliases before
        // env.ml:1530-1538 `prefix_idents`, then compiler/ml/subst.ml:303-309
        // rewrites value descriptions through the selected path. ReScript CMI
        // files can save a nested alias target like `Webapi.Fetch.Response`
        // under the flattened parent prefix `Webapi__Fetch.Response`; rewrite
        // those flattened-prefix-plus-tail paths to the same selected path.
        crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
            sig,
            &source_prefix,
            &rewrite_target,
            ctx,
        );
        crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
            sig,
            &source_prefix,
            &rewrite_target,
            ctx,
        );
    }
}

fn rewrite_child_module_prefixes_from_sig(
    sig_to_rewrite: &[crate::types::decl::SignatureItem],
    source_sig: &[crate::types::decl::SignatureItem],
    old_parent_path: &Path,
    new_parent_path: &Path,
    skip_child_name: Option<&str>,
    ctx: &crate::types::context::TypeContext,
) {
    let new_parent_path = Arc::new(*new_parent_path);
    let mut prefixes = Vec::new();
    for item in source_sig {
        if let crate::types::decl::SignatureItem::SigModule(id, _, _) = item {
            if skip_child_name == Some(id.name()) {
                continue;
            }
            let old_prefix = Path::pdot(*old_parent_path, id.name().to_string());
            let new_prefix =
                ctx.dotted_from_ident(new_parent_path.clone(), *id, crate::types::path::NOPOS);
            prefixes.push((old_prefix, new_prefix));
        }
    }
    crate::cmi::persistent_env::rewrite_sig_by_path_prefixes(sig_to_rewrite, &prefixes, ctx);
}

#[track_caller]
pub(crate) fn copy_lookup_signature_for_subst(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
) -> crate::types::decl::Signature {
    if ctx.counts_this_call() {
        return ctx.counted_copy(crate::perf_counters::CopyCause::Lookup, || {
            copy_lookup_signature_for_subst(sig_items, ctx)
        });
    }
    if ctx.compiler_counters_enabled() {
        crate::perf_counters::record_signature_copy(
            std::panic::Location::caller(),
            sig_items.len(),
        );
    }
    let mut cache = TypeExprRefMap::new();
    ctx.with_copy_session(|| copy_lookup_signature(sig_items, ctx, &mut cache))
}

#[track_caller]
pub(crate) fn copy_lookup_signature_for_subst_with_paths<TP, MP>(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    type_path: &TP,
    module_path: &MP,
) -> crate::types::decl::Signature
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&std::sync::Arc<Path>) -> std::sync::Arc<Path>,
{
    if ctx.counts_this_call() {
        return ctx.counted_copy(crate::perf_counters::CopyCause::Lookup, || {
            copy_lookup_signature_for_subst_with_paths(sig_items, ctx, type_path, module_path)
        });
    }
    if ctx.compiler_counters_enabled() {
        crate::perf_counters::record_signature_copy(
            std::panic::Location::caller(),
            sig_items.len(),
        );
    }
    let mut cache = TypeExprRefMap::new();
    ctx.with_copy_session(|| {
        copy_lookup_signature_with_paths(sig_items, ctx, &mut cache, type_path, module_path)
    })
}

#[track_caller]
pub(crate) fn copy_lookup_signature_for_subst_with_paths_and_idents<TP, MP>(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    type_path: &TP,
    module_path: &MP,
    new_idents: Vec<Option<Ident>>,
) -> crate::types::decl::Signature
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&std::sync::Arc<Path>) -> std::sync::Arc<Path>,
{
    if ctx.counts_this_call() {
        return ctx.counted_copy(crate::perf_counters::CopyCause::Lookup, || {
            copy_lookup_signature_for_subst_with_paths_and_idents(
                sig_items,
                ctx,
                type_path,
                module_path,
                new_idents,
            )
        });
    }
    if ctx.compiler_counters_enabled() {
        crate::perf_counters::record_signature_copy(
            std::panic::Location::caller(),
            sig_items.len(),
        );
    }
    let mut cache = TypeExprRefMap::new();
    ctx.with_copy_session(|| {
        copy_lookup_signature_with_paths_and_idents(
            sig_items,
            ctx,
            &mut cache,
            type_path,
            module_path,
            Some(new_idents.into_iter()),
        )
    })
}

/// Deep-copy a module type, creating new type expression nodes.
/// Used to avoid in-place modification of shared type expressions
/// when applying path substitutions (matching OCaml's lazy deep-copy
/// behavior in `components_of_module_maker` + `Subst.type_declaration`).
pub(crate) fn copy_lookup_module_type_for_subst(
    module_type: &crate::types::decl::ModuleType,
    ctx: &TypeContext,
) -> crate::types::decl::ModuleType {
    if ctx.counts_this_call() {
        return ctx.counted_copy(crate::perf_counters::CopyCause::Lookup, || {
            copy_lookup_module_type_for_subst(module_type, ctx)
        });
    }
    let mut cache = TypeExprRefMap::new();
    ctx.with_copy_session(|| copy_lookup_module_type(module_type, ctx, &mut cache))
}

// ============================================================================
// Environment Extensions for Built-in Types
// ============================================================================

impl Env {
    /// Get a fresh int type instance.
    /// Uses cached generic singleton + instance(), matching OCaml's
    /// `instance_def Predef.type_int` pattern.
    pub fn type_int(&self, ctx: &TypeContext) -> TypeExprRef {
        crate::types::ctype::instance(ctx, ctx.predef_int())
    }

    /// Get a fresh char type instance.
    pub fn type_char(&self, ctx: &TypeContext) -> TypeExprRef {
        crate::types::ctype::instance(ctx, ctx.predef_char())
    }

    /// Get a fresh string type instance.
    pub fn type_string(&self, ctx: &TypeContext) -> TypeExprRef {
        crate::types::ctype::instance(ctx, ctx.predef_string())
    }

    /// Get a fresh float type instance.
    pub fn type_float(&self, ctx: &TypeContext) -> TypeExprRef {
        crate::types::ctype::instance(ctx, ctx.predef_float())
    }

    /// Get a fresh bigint type instance.
    pub fn type_bigint(&self, ctx: &TypeContext) -> TypeExprRef {
        crate::types::ctype::instance(ctx, ctx.predef_bigint())
    }

    /// Get a fresh unit type instance.
    pub fn type_unit(&self, ctx: &TypeContext) -> TypeExprRef {
        crate::types::ctype::instance(ctx, ctx.predef_unit())
    }

    /// Get a fresh bool type instance.
    pub fn type_bool(&self, ctx: &TypeContext) -> TypeExprRef {
        crate::types::ctype::instance(ctx, ctx.predef_bool())
    }

    /// Get the array type.
    pub fn type_array(&self, ctx: &TypeContext, elem_ty: TypeExprRef) -> TypeExprRef {
        ctx.new_predef_constr(crate::types::predef::path_array(), vec![elem_ty])
    }

    /// Get the iterable type (upstream #7887).
    pub fn type_iterable(&self, ctx: &TypeContext, elem_ty: TypeExprRef) -> TypeExprRef {
        ctx.new_predef_constr(crate::types::predef::path_iterable(), vec![elem_ty])
    }

    /// Get the asyncIterable type (upstream #7887).
    pub fn type_async_iterable(&self, ctx: &TypeContext, elem_ty: TypeExprRef) -> TypeExprRef {
        ctx.new_predef_constr(crate::types::predef::path_async_iterable(), vec![elem_ty])
    }

    /// Get the option type.
    pub fn type_option(&self, ctx: &TypeContext, elem_ty: TypeExprRef) -> TypeExprRef {
        ctx.new_predef_constr(crate::types::predef::path_option(), vec![elem_ty])
    }

    /// Look up a value by longident. `None` means the value is unbound; the
    /// caller builds the user-facing error.
    // Inlined into its two callers: the typing of an identifier expression,
    // which is hot and had this body inline when it was the only caller, and
    // the discharge of a derived item.
    #[inline(always)]
    pub fn lookup_value_by_lid(
        &self,
        lid: &Longident,
        arena: &crate::parse_arena::ParseArena,
        pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
        ctx: &crate::types::context::TypeContext,
    ) -> Option<(Path, Arc<ValueDescription>)> {
        match lid {
            Longident::Lident(idx) => {
                self.find_value_arc_with_path(arena.name(*idx))
                    .ok()
                    .map(|(access_path, desc)| (access_path, desc.clone()))
            }
            Longident::Ldot(prefix, idx) => {
                let value_name = arena.get_string(*idx);

                // OCaml compiler/ml/env.ml:800-812 routes qualified value lookup
                // through `find_module_descr` and the component value table; it
                // does not force env.ml:865-881's module declaration thunk first.
                if let Some(Some(result)) = with_resolved_module_components_for_lid(
                    prefix,
                    arena,
                    self,
                    pers_env,
                    ctx,
                    |components| {
                        let module_path = *components.access_path();
                        if let Some(cached) =
                            ctx.find_resolved_module_value(&module_path, value_name)
                        {
                            return Some(cached);
                        }
                        components
                            .lookup_value_for_access(value_name, ctx)
                            .map(|(pos, _, vd)| {
                                let path =
                                    Path::pdot_pos(module_path, value_name, pos as i32);
                                let result = (path, Arc::new(vd));
                                ctx.register_resolved_module_value(
                                    &module_path,
                                    value_name,
                                    result.0,
                                    result.1.clone(),
                                );
                                result
                            })
                    },
                ) {
                    return Some(result);
                }
                if let Some(module_path) =
                    self.resolve_module_access_path_for_lid(prefix, arena, pers_env, ctx)
                {
                    if let Some(cached) = ctx.find_resolved_module_value(&module_path, value_name) {
                        return Some(cached);
                    }
                    if let Some(Some((mod_path, pos, vd))) =
                        with_resolved_module_components_for_path(
                            &module_path,
                            self,
                            pers_env,
                            ctx,
                            |components| {
                                components
                                    .lookup_value_for_access(value_name, ctx)
                                    .map(|(pos, _, vd)| (*components.access_path(), pos, vd))
                            },
                        )
                    {
                        let path = Path::pdot_pos(mod_path, value_name, pos as i32);
                        let result = (path, Arc::new(vd));
                        ctx.register_resolved_module_value(
                            &module_path,
                            value_name,
                            result.0,
                            result.1.clone(),
                        );
                        return Some(result);
                    }

                    return None;
                }

                // OCaml compiler/ml/env.ml:1091-1100 only resolves qualified
                // values by first resolving the module prefix through
                // `lookup_module_descr`, then reading the selected component
                // table. It does not fall back to an unqualified value with the
                // same leaf name when the prefix is unavailable.
                None
            }
            Longident::Lapply(_, _) => None,
        }
    }

    /// Resolve a module longident to its signature and path.
    /// Applies path rewriting/substitution for downstream value/module lookups.
    pub(crate) fn resolve_module_lid(
        &self,
        lid: &Longident,
        arena: &crate::parse_arena::ParseArena,
        pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
        ctx: &crate::types::context::TypeContext,
    ) -> Option<(Path, Arc<crate::types::decl::Signature>)> {
        self.resolve_module_lid_impl(lid, arena, pers_env, ctx, true)
    }

    pub(crate) fn resolve_module_lid_raw(
        &self,
        lid: &Longident,
        arena: &crate::parse_arena::ParseArena,
        pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
        ctx: &crate::types::context::TypeContext,
    ) -> Option<(Path, Arc<crate::types::decl::Signature>)> {
        self.resolve_module_lid_impl(lid, arena, pers_env, ctx, false)
    }

    fn resolve_module_access_path_for_lid(
        &self,
        lid: &Longident,
        arena: &crate::parse_arena::ParseArena,
        pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
        ctx: &crate::types::context::TypeContext,
    ) -> Option<Path> {
        match lid {
            Longident::Lident(mod_idx) => {
                let mod_name = arena.get_string(*mod_idx);
                if let Ok((module_path, _)) = self.find_module_with_path(mod_name) {
                    Some(module_path)
                } else {
                    let module_path = Path::pident(Ident::create_persistent(mod_name));
                    with_resolved_module_components_for_path(
                        &module_path,
                        self,
                        pers_env,
                        ctx,
                        |components| *components.access_path(),
                    )
                }
            }
            Longident::Ldot(prefix, submod_idx) => {
                let parent_path =
                    self.resolve_module_access_path_for_lid(prefix, arena, pers_env, ctx)?;
                let submod_name = arena.get_string(*submod_idx);
                if let Some(cached) = ctx.find_resolved_child_module_path(&parent_path, submod_name)
                {
                    return Some(cached);
                }
                if let Some(result) = with_resolved_module_components_for_lid(
                    lid,
                    arena,
                    self,
                    pers_env,
                    ctx,
                    |components| *components.access_path(),
                ) {
                    ctx.register_resolved_child_module_path(
                        &parent_path,
                        submod_name,
                        result,
                    );
                    return Some(result);
                }
                let result = with_resolved_module_components_for_path(
                    &parent_path,
                    self,
                    pers_env,
                    ctx,
                    |components| {
                        components.lookup_module(submod_name).map(|(pos, _, _md)| {
                            // OCaml compiler/ml/env.ml:1008-1013
                            // `lookup_module_descr_aux` and env.ml:1064-1073
                            // `lookup_module` construct the selected child
                            // access path as `Pdot(parent, name, pos)`. The
                            // module declaration's `md_path` is the alias
                            // target; using it here leaks the backing unit
                            // into typedtree paths.
                            Path::pdot_pos(parent_path, submod_name, pos as i32)
                        })
                    },
                )
                .flatten()?;
                ctx.register_resolved_child_module_path(&parent_path, submod_name, result);
                Some(result)
            }
            Longident::Lapply(_, _) => None,
        }
    }

    /// Resolve a module longident to path+signature, optionally applying
    /// rewrite/substitution to contained type paths.
    fn resolve_module_lid_impl(
        &self,
        lid: &Longident,
        arena: &crate::parse_arena::ParseArena,
        pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
        ctx: &crate::types::context::TypeContext,
        apply_subst: bool,
    ) -> Option<(Path, Arc<crate::types::decl::Signature>)> {
        match lid {
            Longident::Lident(mod_idx) => {
                let mod_name = arena.get_string(*mod_idx);
                // First try local environment
                if let Ok((access_path_hint, md)) = self.find_module_with_path(mod_name) {
                    let (module_cache_key, scope) = path_cache_key(&access_path_hint)
                        .map(|key| {
                            (
                                format!("module::access::{}::subst{}", key, apply_subst as u8),
                                scope_local_module_cache_key(&access_path_hint, self),
                            )
                        })
                        .unwrap_or_else(|| {
                            (
                                format!("module::lident::{}::subst{}", mod_name, apply_subst as u8),
                                None,
                            )
                        });
                    if let Some(cached) = ctx.find_resolved_module_sig(&module_cache_key, scope) {
                        return Some(cached);
                    }
                    if apply_subst {
                        let (resolved_path, resolved_sig) =
                            resolve_module_signature_for_path_shared(
                                &access_path_hint,
                                self,
                                pers_env,
                                ctx,
                            )?;
                        ctx.register_resolved_module_sig(
                            &module_cache_key,
                            scope,
                            resolved_path,
                            resolved_sig.clone(),
                        );
                        return Some((resolved_path, resolved_sig));
                    }
                    // Raw lookup: keep the declaration's signature as-is.
                    if let Some((sig, _)) = self.resolve_module_type(
                        &md.md_type,
                        pers_env,
                        ctx,
                        ComponentLookupApi::LookupModule,
                    ) {
                        let path = access_path_hint;
                        let sig = Arc::new(sig);
                        ctx.register_resolved_module_sig(
                            &module_cache_key,
                            scope,
                            path,
                            sig.clone(),
                        );
                        return Some((path, sig));
                    }
                }
                // Then try persistent environment (external modules)
                if let Some(pers) = pers_env.as_mut() {
                    if let Some(renamed_sig) = pers.get_renamed_sig_shared(mod_name, ctx) {
                        let module_path = Path::pident(Ident::create_persistent(mod_name));
                        let sig = copy_lookup_signature_for_subst(renamed_sig.as_ref(), ctx);
                        if let Some(qualified_alias_path) =
                            pers.qualified_alias_path_for_flattened_head(mod_name)
                        {
                            rewrite_flattened_alias_child_prefixes(
                                &sig,
                                &qualified_alias_path,
                                &module_path,
                                ctx,
                            );
                        }
                        crate::types::ctype::force_generalize_signature_values(ctx, &sig);
                        return Some((module_path, Arc::new(sig)));
                    }
                }
                None
            }
            Longident::Ldot(prefix, submod_idx) => {
                let submod_name = arena.get_string(*submod_idx);
                if apply_subst {
                    if let Some(result) = with_resolved_module_components_for_lid(
                        lid,
                        arena,
                        self,
                        pers_env,
                        ctx,
                        |components| (*components.access_path(), components.signature_arc()),
                    ) {
                        return Some(result);
                    }
                    let parent_path =
                        self.resolve_module_access_path_for_lid(prefix, arena, pers_env, ctx)?;
                    let (_, sub_path, _) = lookup_module_in_resolved_path(
                        &parent_path,
                        submod_name,
                        self,
                        pers_env,
                        ctx,
                    )?;
                    return with_resolved_module_components_for_path(
                        &sub_path,
                        self,
                        pers_env,
                        ctx,
                        |components| (*components.access_path(), components.signature_arc()),
                    );
                }
                // Raw lookup: recursively resolve the prefix, then select the
                // sub-module using OCaml runtime slot accounting.
                let (parent_path, parent_sig) =
                    self.resolve_module_lid_impl(prefix, arena, pers_env, ctx, false)?;
                let (pos, sub_md) =
                    crate::types::decl::signature_runtime_module(parent_sig.as_ref(), submod_name)?;
                let sub_path = Path::pdot_pos(parent_path, submod_name, pos as i32);
                let (sig, _) = self.resolve_module_type(
                    &sub_md.md_type,
                    pers_env,
                    ctx,
                    ComponentLookupApi::LookupModule,
                )?;
                Some((sub_path, Arc::new(sig)))
            }
            _ => None,
        }
    }

    /// Resolve a module type to a signature, following aliases and loading from persistent env.
    /// Returns (signature, Option<resolved_module_name>) where resolved_module_name is Some
    /// when an alias was followed (so the caller can rewrite paths).
    pub(crate) fn resolve_module_type(
        &self,
        mty: &crate::types::decl::ModuleType,
        pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
        ctx: &crate::types::context::TypeContext,
        cache_mode: ComponentLookupApi,
    ) -> Option<(crate::types::decl::Signature, Option<String>)> {
        use HashSet;

        fn resolve_module_type_inner(
            env: &Env,
            mty: &crate::types::decl::ModuleType,
            pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
            ctx: &crate::types::context::TypeContext,
            visiting: &mut HashSet<Path>,
            cache_mode: ComponentLookupApi,
        ) -> Option<(crate::types::decl::Signature, Option<String>)> {
            match mty {
                crate::types::decl::ModuleType::MtySignature(sig) => Some(((**sig).clone(), None)),
                crate::types::decl::ModuleType::MtyAlias(_, path) => {
                    resolve_path(env, path, pers_env, ctx, visiting, cache_mode)
                }
                crate::types::decl::ModuleType::MtyIdent(path) => {
                    // Match OCaml Env.scrape_alias: resolve Mty_ident via module-type
                    // expansion first, then fall back to module-path resolution.
                    resolve_modtype_path(env, path, pers_env, ctx, visiting, cache_mode)
                        .or_else(|| resolve_path(env, path, pers_env, ctx, visiting, cache_mode))
                }
                _ => None,
            }
        }

        fn resolve_modtype_path(
            env: &Env,
            path: &Path,
            pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
            ctx: &crate::types::context::TypeContext,
            visiting: &mut HashSet<Path>,
            cache_mode: ComponentLookupApi,
        ) -> Option<(crate::types::decl::Signature, Option<String>)> {
            use crate::types::decl::SignatureItem;

            if !visiting.insert(*path) {
                return None;
            }

            if let PathView::Pdot(parent, modtype_name, _) = path.view() {
                if let Some((_, mtd)) = lookup_modtype_in_resolved_path(
                    parent,
                    modtype_name.as_str(),
                    env,
                    pers_env,
                    ctx,
                ) {
                    let result = mtd.mtd_type.as_ref().and_then(|mty| {
                        resolve_module_type_inner(env, mty, pers_env, ctx, visiting, cache_mode)
                    });
                    visiting.remove(path);
                    return result;
                }
            }

            let result = match path.view() {
                PathView::Pident(id) => {
                    let modtype_name = id.name();
                    match env.find_modtype(modtype_name) {
                        Ok(mtd) => mtd.mtd_type.as_ref().and_then(|mty| {
                            resolve_module_type_inner(env, mty, pers_env, ctx, visiting, cache_mode)
                        }),
                        Err(_) => None,
                    }
                }
                PathView::Pdot(parent, modtype_name, _) => {
                    let (_, parent_sig) = match resolve_module_signature_for_path_shared(
                        parent, env, pers_env, ctx,
                    ) {
                        Some(x) => x,
                        None => {
                            visiting.remove(path);
                            return None;
                        }
                    };
                    parent_sig.iter().find_map(|sig_item| {
                        if let SignatureItem::SigModtype(id, mtd) = sig_item {
                            if id.name() == modtype_name.as_str() {
                                return mtd.mtd_type.as_ref().and_then(|mty| {
                                    resolve_module_type_inner(
                                        env, mty, pers_env, ctx, visiting, cache_mode,
                                    )
                                });
                            }
                        }
                        None
                    })
                }
                PathView::Papply(_, _) => None,
            };

            visiting.remove(path);
            result
        }

        /// Resolve the module type of the selected child `parent.submod_name`
        /// (declared as `sub_md`, selected through `access_path`).
        #[allow(clippy::too_many_arguments)]
        fn resolve_selected_child_md(
            env: &Env,
            parent: &Path,
            submod_name: &str,
            sub_md: &crate::types::decl::ModuleDeclaration,
            access_path: &Path,
            pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
            ctx: &crate::types::context::TypeContext,
            visiting: &mut HashSet<Path>,
            cache_mode: ComponentLookupApi,
        ) -> Option<(crate::types::decl::Signature, Option<String>)> {
            use crate::types::decl::{ModuleType, SignatureItem};
            let self_alias = matches!(
                &sub_md.md_type,
                ModuleType::MtyAlias(_, target) if target.same(access_path)
            );
            if self_alias
                && let PathView::Pident(parent_id) = parent.view()
                && (parent_id.is_persistent() || parent_id.stamp() == 0)
                && let Some(pers) = pers_env.as_mut()
                && let Some(parent_ps) = pers.find_pers_struct(parent_id.name(), ctx)
            {
                let raw_parent_sig = parent_ps.ps_sig.clone();
                if let Some((raw_id, raw_md)) = raw_parent_sig.iter().find_map(|item| match item {
                    SignatureItem::SigModule(id, md, _) if id.name() == submod_name => {
                        Some((*id, md.clone()))
                    }
                    _ => None,
                }) {
                    // OCaml compiler/ml/env.ml:1440-1446 `scrape_alias` resolves
                    // the selected module through env.ml:865-882 `find_module`;
                    // for persistent parents that reaches env.ml:1568's lazy
                    // module-declaration thunk, which starts from the raw parent
                    // item before compiler/ml/mtype.ml:98-102 can expose a
                    // strengthened self-alias. Apply the same
                    // compiler/ml/subst.ml:352-400 child-module freshening here,
                    // then continue from the real module type instead of
                    // resolving the strengthened alias to itself.
                    let md = if let Some((_, cached_md)) =
                        ctx.find_qualified_module_decl(parent, submod_name)
                        && !matches!(
                            &cached_md.md_type,
                            ModuleType::MtyAlias(_, target) if target.same(access_path)
                        ) {
                        cached_md
                    } else {
                        let (_, md) =
                            crate::types::env_lazy::force_component_module_declaration_thunk(
                                parent,
                                submod_name,
                                parent,
                                raw_parent_sig.as_ref(),
                                raw_id,
                                raw_md,
                                ctx,
                            );
                        md
                    };
                    return resolve_module_type_inner(
                        env,
                        &md.md_type,
                        pers_env,
                        ctx,
                        visiting,
                        cache_mode,
                    );
                }
            }
            let result = resolve_module_type_inner(
                env,
                &sub_md.md_type,
                pers_env,
                ctx,
                visiting,
                cache_mode,
            );
            if module_type_has_hidden_unpack_ident(&sub_md.md_type) {
                result.map(|(sig, resolved_name)| {
                    let mut sig = copy_lookup_signature_for_subst(&sig, ctx);
                    rebind_direct_sig_type_family_to_access_path(ctx, access_path, &mut sig);
                    crate::cmi::persistent_env::substitute_type_paths_in_sig(
                        &sig,
                        access_path,
                        ctx,
                    );
                    (sig, resolved_name)
                })
            } else {
                result
            }
        }

        fn resolve_path(
            env: &Env,
            path: &Path,
            pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
            ctx: &crate::types::context::TypeContext,
            visiting: &mut HashSet<Path>,
            cache_mode: ComponentLookupApi,
        ) -> Option<(crate::types::decl::Signature, Option<String>)> {
            use crate::types::decl::SignatureItem;
            if !visiting.insert(*path) {
                return None;
            }

            if let PathView::Pdot(parent, submod_name, _) = path.view() {
                // OCaml compiler/ml/env.ml:1573-1578 builds child component
                // tables from the selected alias path. Rust can additionally
                // see flattened backing paths such as `Layout__Types.Component`;
                // keep those on the component-table lookup path below so normal
                // compilation and typedtree dumping follow the same lazy order.
                let flattened_alias_component_child =
                    flattened_alias_component_parent(parent, pers_env.as_ref(), ctx);

                if !flattened_alias_component_child
                    && let Some((_, access_path, sub_md)) = lookup_module_in_resolved_path(
                        parent,
                        submod_name.as_str(),
                        env,
                        pers_env,
                        ctx,
                    )
                {
                    let result = resolve_selected_child_md(
                        env,
                        parent,
                        submod_name.as_str(),
                        &sub_md,
                        &access_path,
                        pers_env,
                        ctx,
                        visiting,
                        cache_mode,
                    );
                    visiting.remove(path);
                    return result;
                }
            }

            match path.view() {
                PathView::Pident(id) => {
                    let mod_name = id.name();
                    if let Ok(md) = env.find_module_same(id) {
                        let result = resolve_module_type_inner(
                            env,
                            &md.md_type,
                            pers_env,
                            ctx,
                            visiting,
                            cache_mode,
                        );
                        visiting.remove(path);
                        return result;
                    }
                    if let Some(pers) = pers_env.as_mut() {
                        // OCaml compiler/ml/env.ml:1435-1446 `scrape_alias`
                        // resolves Mty_alias through `find_module`; for
                        // persistent Pidents, env.ml:872-875 returns an
                        // Mty_signature after forcing ps_sig, which is
                        // initialized as `Subst.signature Subst.identity sign`
                        // at env.ml:677.
                        let renamed_sig = pers.get_renamed_sig_shared(mod_name, ctx)?;
                        let sig = copy_lookup_signature_for_subst(renamed_sig.as_ref(), ctx);
                        let result = Some((sig, Some(mod_name.to_string())));
                        visiting.remove(path);
                        return result;
                    }
                    visiting.remove(path);
                    None
                }
                PathView::Pdot(parent, submod_name, _) => {
                    let (_, parent_sig) = match resolve_module_signature_for_path_shared(
                        parent, env, pers_env, ctx,
                    ) {
                        Some(x) => x,
                        None => {
                            visiting.remove(path);
                            return None;
                        }
                    };
                    for sig_item in parent_sig.iter() {
                        if let SignatureItem::SigModule(id, sub_md, _) = sig_item {
                            if id.name() == submod_name.as_str() {
                                let result = resolve_selected_child_md(
                                    env,
                                    parent,
                                    submod_name.as_str(),
                                    sub_md,
                                    path,
                                    pers_env,
                                    ctx,
                                    visiting,
                                    cache_mode,
                                );
                                visiting.remove(path);
                                return result;
                            }
                        }
                    }
                    visiting.remove(path);
                    None
                }
                PathView::Papply(_, _) => {
                    visiting.remove(path);
                    None
                }
            }
        }

        // Follow aliases through both local and persistent modules, while avoiding cycles.
        let mut visiting = HashSet::new();
        resolve_module_type_inner(self, mty, pers_env, ctx, &mut visiting, cache_mode)
    }
}

/// Look up a constructor in a module-qualified path (e.g., Nullable.Value).
/// For Ldot paths, resolves the module and searches its type declarations.
pub(crate) fn lookup_constructor_in_module(
    lid: &Longident,
    arena: &ParseArena,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    expected_ty: Option<TypeExprRef>,
) -> Option<(Path, crate::types::decl::ConstructorDescription)> {
    lookup_constructor_in_module_with_ambiguity(lid, arena, env, pers_env, ctx, expected_ty, false)
        .map(|(path, desc, _)| (path, desc))
}

/// `lookup_constructor_in_module`, also returning the `ambiguous_types` that
/// `NameChoice.disambiguate` reports as warning 41 when no expected variant
/// path selects the constructor (typecore.ml:884-918).
pub(crate) fn lookup_constructor_in_module_with_ambiguity(
    lid: &Longident,
    arena: &ParseArena,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    expected_ty: Option<TypeExprRef>,
    report_ambiguous: bool,
) -> Option<(
    Path,
    crate::types::decl::ConstructorDescription,
    Vec<String>,
)> {
    use crate::parser::longident::Longident;
    match lid {
        Longident::Ldot(module_lid, cstr_idx) => {
            let cstr_name = arena.get_string(*cstr_idx);
            // OCaml compiler/ml/typecore.ml:1463-1468 calls
            // Typetexp.find_all_constructors, which reaches env.ml:1132-1137.
            // For Ldot, env.ml:1114-1119 reads the already-forced component
            // table; it does not rebuild or copy the module signature here.
            let candidates = with_resolved_module_components_for_lid(
                module_lid,
                arena,
                env,
                pers_env,
                ctx,
                |components| {
                    let descs = components.lookup_constructors(cstr_name, ctx);
                    (!descs.is_empty()).then(|| {
                        descs
                            .iter()
                            .map(|desc| {
                                (
                                    Path::pident(Ident::create_persistent(cstr_name)),
                                    desc.clone(),
                                )
                            })
                            .collect::<Vec<_>>()
                    })
                },
            )
            .flatten()?;
            if candidates.is_empty() {
                return None;
            }

            if let Some(expected_ty) = expected_ty {
                if let Some(target_path) =
                    extract_variant_type_path_from_expected_with_persistent_env(
                        expected_ty,
                        env,
                        pers_env,
                        ctx,
                    )
                {
                    for (path, desc) in &candidates {
                        let res_repr = ctx.repr(desc.cstr_res);
                        let res_desc = ctx.get_desc(res_repr);
                        if let TypeDesc::Tconstr {
                            path: cstr_path, ..
                        } = &*res_desc
                        {
                            if cstr_path.same(&target_path)
                                || compare_type_paths_for_disambiguation(
                                    cstr_path,
                                    &target_path,
                                    env,
                                    pers_env,
                                    ctx,
                                )
                            {
                                return Some((*path, desc.clone(), Vec::new()));
                            }
                        }
                    }
                }
            }

            // OCaml compiler/ml/typecore.ml:990-1008 `NameChoice.disambiguate`
            // takes the first candidate when `opath = None` and warns with
            // `ambiguous_types` of the others.
            let (selected_path, selected_desc) = candidates.first().cloned()?;
            let ambiguous = if report_ambiguous {
                ambiguous_constructor_warning_types(
                    &selected_desc,
                    candidates.iter().skip(1).map(|(_, desc)| desc),
                    env,
                    pers_env,
                    ctx,
                )
            } else {
                Vec::new()
            };
            Some((selected_path, selected_desc, ambiguous))
        }
        _ => None,
    }
}

fn lookup_predef_option_constructor(
    lid: &Longident,
    arena: &ParseArena,
    _env: &Env,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, crate::types::decl::ConstructorDescription)> {
    let (prefix, cstr_idx) = match lid {
        Longident::Ldot(prefix, cstr_idx) => (prefix, cstr_idx),
        _ => return None,
    };
    let module_name = match &**prefix {
        Longident::Lident(mod_idx) => arena.get_string(*mod_idx),
        _ => return None,
    };
    if module_name != "*predef*" {
        return None;
    }

    let cstr_name = arena.get_string(*cstr_idx);
    let (inner_ty, option_ty) = ctx.predef_option_scheme();
    let (arity, args, position) = match cstr_name {
        "Some" => (1, vec![inner_ty], 1),
        "None" => (0, vec![], 0),
        _ => return None,
    };

    let desc = crate::types::decl::ConstructorDescription {
        cstr_name: cstr_name.to_string(),
        cstr_res: option_ty,
        cstr_existentials: vec![],
        cstr_args: args,
        cstr_arity: arity,
        cstr_kind: crate::types::ConstructorKind::Ordinary(crate::types::ConstructorReference {
            variant: ctx.predef_option_layout(),
            position,
        }),
        cstr_generalized: false,
        cstr_private: crate::types::PrivateFlag::Public,
        cstr_loc: crate::types::DeclLoc::none(),
        cstr_attributes: vec![crate::types::decl::internal_optional_attr()],
        cstr_inlined: None,
    };
    let path = Path::pident(Ident::create_persistent(cstr_name));
    Some((path, desc))
}

/// Extract the type path from a type expression if it's a concrete type constructor.
/// Follows repr/Tlink chains, and for abstract types tries to expand through aliases.
/// Returns the path from the Tconstr if found.
fn extract_type_path_from_expected(
    expected_ty: TypeExprRef,
    env: &Env,
    ctx: &crate::types::context::TypeContext,
) -> Option<Path> {
    let mut no_persistent_env = None;
    extract_type_path_from_expected_with_persistent_env(
        expected_ty,
        env,
        &mut no_persistent_env,
        ctx,
    )
}

fn extract_type_path_from_expected_with_persistent_env(
    expected_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<Path> {
    let mut visited_types = ChainVisited::default();
    let mut visited_paths = ChainVisited::default();
    extract_type_path_from_expected_inner(
        expected_ty,
        env,
        pers_env,
        ctx,
        &mut visited_types,
        &mut visited_paths,
    )
}

/// A visited set for walks along a short manifest chain (a few steps at
/// most): membership by linear scan, no hashing and no heap allocation for
/// the common case.
struct ChainVisited<T>(smallvec::SmallVec<[T; 4]>);

impl<T> Default for ChainVisited<T> {
    fn default() -> Self {
        ChainVisited(smallvec::SmallVec::new())
    }
}

impl<T: PartialEq> ChainVisited<T> {
    /// Add `item`; false when it was already present (like `HashSet::insert`).
    #[inline]
    fn insert(&mut self, item: T) -> bool {
        if self.0.contains(&item) {
            return false;
        }
        self.0.push(item);
        true
    }
}

fn extract_type_path_from_expected_inner(
    expected_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    visited_types: &mut ChainVisited<usize>,
    visited_paths: &mut ChainVisited<Path>,
) -> Option<Path> {
    let ty = ctx.repr(expected_ty);
    if !visited_types.insert(ty.key()) {
        return None; // Already visited this type expression — break the cycle
    }
    let desc = ctx.borrow_desc(ty);
    match &*desc {
        TypeDesc::Tconstr { path, .. } => {
            // Track visited paths to detect cycles through type declaration manifests.
            // Different TypeExprRefs can point to the same path via manifests, so
            // tracking type expression IDs alone is not sufficient.
            if !visited_paths.insert(*path) {
                return None; // Already expanded through this path — break the cycle
            }
            // Check if this is a concrete (non-abstract) type
            if let Some(decl) = lookup_type_decl_for_path(path, env, pers_env, ctx) {
                match &decl.type_kind {
                    crate::types::TypeKind::TypeAbstract => {
                        // Abstract type - try to expand through manifest
                        if let Some(manifest) = decl.type_manifest {
                            return extract_type_path_from_expected_inner(
                                manifest,
                                env,
                                pers_env,
                                ctx,
                                visited_types,
                                visited_paths,
                            );
                        }
                        None
                    }
                    _ => Some(*path),
                }
            } else {
                // Can't find decl, but the path might still work for matching
                Some(*path)
            }
        }
        _ => None,
    }
}

/// Extract variant type path for constructor disambiguation.
///
/// OCaml `extract_concrete_variant` first resolves through type abbreviations,
/// then checks the resulting head is variant-like. Mirror that behavior here,
/// while keeping label/path extraction logic unchanged.
fn extract_variant_type_path_from_expected_with_persistent_env(
    expected_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<Path> {
    fn resolve_variant_type_path(
        path: &Path,
        env: &Env,
        pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
        ctx: &crate::types::context::TypeContext,
    ) -> Option<Path> {
        let mut current = *path;
        let mut visited = PathNameSet::default();
        loop {
            // Don't normalize module aliases at the top of the loop — this would
            // flatten qualified paths like Pdot(Pdot(Pident("Stdlib"), "JSON"), "t")
            // into Pdot(Pident("Stdlib_JSON"), "t"), losing the module-qualified
            // structure. lookup_type_decl_for_path handles module aliases internally
            // via resolve_module_signature_for_path. Module alias normalization is
            // only used as a fallback for self-manifest cycles (below).
            if !visited.insert(current) {
                return None;
            }
            let Some(decl) = lookup_type_decl_for_path(&current, env, pers_env, ctx) else {
                // If the declaration is unavailable, keep the path for
                // env-based constructor path comparison.
                return Some(current);
            };
            match decl.type_kind {
                crate::types::TypeKind::TypeVariant(_, _) | crate::types::TypeKind::TypeOpen => {
                    return Some(current);
                }
                crate::types::TypeKind::TypeAbstract => {
                    let manifest = decl.type_manifest?;
                    let manifest_repr = ctx.repr(manifest);
                    let manifest_desc = ctx.get_desc(manifest_repr);
                    let next_path = match &*manifest_desc {
                        TypeDesc::Tconstr { path, .. } => *path,
                        _ => return None,
                    };
                    if next_path.same(&current) {
                        // Self-manifest cycle: try normalize_path as fallback
                        let normalized = env.normalize_path(ctx, &current);
                        if normalized.same(&current) {
                            return None;
                        }
                        current = normalized;
                        continue;
                    }
                    current = next_path;
                }
                _ => {
                    return None;
                }
            }
        }
    }

    let opath =
        extract_type_path_from_expected_with_persistent_env(expected_ty, env, pers_env, ctx);
    if let Some(path) = opath {
        if let Some(resolved) = resolve_variant_type_path(&path, env, pers_env, ctx) {
            return Some(resolved);
        }
    }
    None
}

/// Paths visited by a type-path expansion, compared by `Path.name` (the
/// expansions stop at a name they have seen). Short, so a list.
#[derive(Default)]
struct PathNameSet(smallvec::SmallVec<[Path; 4]>);

impl PathNameSet {
    /// Adds `path`; `false` when a path with the same name is already in.
    fn insert(&mut self, path: Path) -> bool {
        if self.0.iter().any(|seen| seen.name_equals(&path)) {
            return false;
        }
        self.0.push(path);
        true
    }

    fn remove(&mut self, path: &Path) {
        self.0.retain(|seen| !seen.name_equals(path));
    }
}

/// OCaml `typecore.ml` compares constructor/label type paths with
/// `compare_type_path`, which expands type manifests and normalizes aliases.
/// Mirror that behavior for constructor disambiguation.
fn expand_type_path_for_compare(
    path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    depth: usize,
    visiting: &mut PathNameSet,
    force_env_normalize: bool,
) -> Path {
    if depth > 50 {
        return *path;
    }

    if !visiting.insert(*path) {
        return *path;
    }

    if let Some(decl) = lookup_type_decl_for_path(path, env, pers_env, ctx) {
        if let Some(manifest) = decl.type_manifest {
            let manifest_path = {
                let manifest_desc = ctx.get_desc(ctx.repr(manifest));
                match &*manifest_desc {
                    TypeDesc::Tconstr {
                        path: manifest_path,
                        ..
                    } => Some(*manifest_path),
                    _ => None,
                }
            };
            if let Some(manifest_path) = manifest_path {
                if manifest_path.same(path) {
                    if let Some(stored_path) = decl.type_path.as_ref() {
                        if !stored_path.same(path) {
                            let expanded = expand_type_path_for_compare(
                                stored_path,
                                env,
                                pers_env,
                                ctx,
                                depth + 1,
                                visiting,
                                force_env_normalize,
                            );
                            visiting.remove(path);
                            return expanded;
                        }
                    }
                    if let PathView::Pdot(parent, leaf_name, _) = path.view() {
                        if let Some(alias_target) =
                            alias_target_for_module_path(parent, env, pers_env, ctx)
                        {
                            let target_path = Path::pdot(alias_target, leaf_name.as_str());
                            let expanded = expand_type_path_for_compare(
                                &target_path,
                                env,
                                pers_env,
                                ctx,
                                depth + 1,
                                visiting,
                                force_env_normalize,
                            );
                            visiting.remove(path);
                            return expanded;
                        }
                    }
                }
                let expanded = expand_type_path_for_compare(
                    &manifest_path,
                    env,
                    pers_env,
                    ctx,
                    depth + 1,
                    visiting,
                    force_env_normalize,
                );
                visiting.remove(path);
                return expanded;
            }
        }
    }

    let normalized = if force_env_normalize {
        // OCaml compiler/ml/typecore.ml:776-784 `expand_path` falls back to
        // `Env.normalize_path`; compiler/ml/env.ml:903-914 then reaches
        // env.ml:865-880, forcing local module-declaration and persistent
        // `ps_sig` lazies at that exact compare point. Bypass Rust's structural
        // normalized-path cache here: an earlier component-table probe may have
        // cached the same path before the OCaml-equivalent lazy force.
        crate::types::ctype::force_normalize_path_full_side_effects(ctx, env, path)
    } else {
        env.normalize_path(ctx, path)
    };
    if !normalized.same(path) {
        let expanded = expand_type_path_for_compare(
            &normalized,
            env,
            pers_env,
            ctx,
            depth + 1,
            visiting,
            force_env_normalize,
        );
        visiting.remove(path);
        return expanded;
    }

    visiting.remove(path);
    *path
}

fn resolve_type_item_identity(
    path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(i32, usize)> {
    match path.view() {
        PathView::Pident(id) => {
            if id.stamp() == 0 {
                return None;
            }
            let arity = env.lookup_type(path).ok()?.type_params.len();
            Some((id.stamp(), arity))
        }
        PathView::Pdot(parent, type_name, _) => {
            lookup_type_in_resolved_path(parent, type_name.as_str(), env, pers_env, ctx).and_then(
                |(_, id, decl)| {
                    if id.stamp() == 0 {
                        None
                    } else {
                        Some((id.stamp(), decl.type_params.len()))
                    }
                },
            )
        }
        PathView::Papply(_, _) => None,
    }
}

fn resolved_type_items_share_identity(
    left: &Path,
    right: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> bool {
    let Some((left_stamp, left_arity)) = resolve_type_item_identity(left, env, pers_env, ctx)
    else {
        return false;
    };
    let Some((right_stamp, right_arity)) = resolve_type_item_identity(right, env, pers_env, ctx)
    else {
        return false;
    };

    left_stamp == right_stamp && left_arity == right_arity
}

fn compare_type_paths_for_disambiguation(
    left: &Path,
    right: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> bool {
    compare_type_paths_for_disambiguation_impl(left, right, env, pers_env, ctx, false)
}

fn compare_type_paths_for_label_disambiguation(
    left: &Path,
    right: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> bool {
    compare_type_paths_for_disambiguation_impl(left, right, env, pers_env, ctx, true)
}

fn compare_type_paths_for_constructor_disambiguation(
    left: &Path,
    right: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> bool {
    compare_type_paths_for_disambiguation_impl(left, right, env, pers_env, ctx, true)
}

fn compare_type_paths_for_disambiguation_impl(
    left: &Path,
    right: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    force_env_normalize: bool,
) -> bool {
    if !force_env_normalize && left.same(right) {
        return true;
    }
    let env_id = env.scope_id();
    if force_env_normalize
        && let Some(cached) = ctx.find_forced_type_path_compare(env_id, left, right)
    {
        return cached;
    }
    let mut left_visiting = PathNameSet::default();
    let mut right_visiting = PathNameSet::default();
    let left_expanded = expand_type_path_for_compare(
        left,
        env,
        pers_env,
        ctx,
        0,
        &mut left_visiting,
        force_env_normalize,
    );
    let right_expanded = expand_type_path_for_compare(
        right,
        env,
        pers_env,
        ctx,
        0,
        &mut right_visiting,
        force_env_normalize,
    );
    let same = left_expanded.same(&right_expanded);
    if force_env_normalize {
        // OCaml still performs the first `compare_type_path` expansion at this
        // call site. Once that side-effectful comparison has run for this
        // environment, repeated record-label comparisons with the same paths
        // can reuse the stable result.
        ctx.register_forced_type_path_compare(env_id, left, right, same);
    }
    same
}

fn label_result_path(
    ctx: &crate::types::context::TypeContext,
    label: &crate::types::LabelDescription,
) -> Option<Path> {
    let res = ctx.repr(label.lbl_res);
    match &*ctx.borrow_desc(res) {
        TypeDesc::Tconstr { path, .. } => Some(*path),
        _ => None,
    }
}

fn should_prefer_expected_record_label(
    expected_label: &crate::types::LabelDescription,
    env_label: &crate::types::LabelDescription,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> bool {
    let Some(expected_path) = label_result_path(ctx, expected_label) else {
        return false;
    };
    let Some(env_path) = label_result_path(ctx, env_label) else {
        return false;
    };

    if expected_path.same(&env_path) {
        return false;
    }

    if !compare_type_paths_for_disambiguation(&expected_path, &env_path, env, pers_env, ctx) {
        return false;
    }

    is_local_module_access_path(&expected_path) && !is_local_module_access_path(&env_path)
}

fn should_force_expected_closed_record_label(
    expected_ty: TypeExprRef,
    expected_label: &crate::types::LabelDescription,
    env_label: &crate::types::LabelDescription,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> bool {
    let Some(_expected_record_info) =
        extract_concrete_record_type_info(expected_ty, env, pers_env, ctx)
    else {
        return false;
    };

    let Some(expected_path) = label_result_path(ctx, expected_label) else {
        return false;
    };
    let Some(env_path) = label_result_path(ctx, env_label) else {
        return false;
    };

    if expected_path.same(&env_path) {
        return false;
    }

    if compare_type_paths_for_disambiguation(&expected_path, &env_path, env, pers_env, ctx) {
        return false;
    }

    // For closed record literals typed against a concrete expected record,
    // OCaml prefers the expected record's labels over unrelated same-named
    // labels that happen to be in lexical scope.
    is_local_module_access_path(&env_path)
}

fn path_root_module(path: &Path) -> Path {
    match path.view() {
        PathView::Pident(id) => Path::pident(*id),
        PathView::Pdot(prefix, _, _) => path_root_module(prefix),
        PathView::Papply(_, _) => *path,
    }
}

fn path_non_apply_root_ident(path: &Path) -> Option<&Ident> {
    match path.view() {
        PathView::Pident(id) => Some(id),
        PathView::Pdot(prefix, _, _) => path_non_apply_root_ident(prefix),
        PathView::Papply(_, _) => None,
    }
}

fn path_non_apply_root_is_persistent(path: &Path) -> bool {
    path_non_apply_root_ident(path).is_some_and(Ident::is_persistent)
}

fn path_non_apply_root_is_persistent_or_global(path: &Path) -> bool {
    path_non_apply_root_ident(path).is_some_and(|id| id.is_persistent() || id.stamp() == 0)
}

fn is_local_module_access_path(path: &Path) -> bool {
    matches!(path_root_module(path).view(), crate::types::path::PathView::Pident(id) if !id.is_persistent())
}

fn type_contains_unresolved_local_path(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ty: TypeExprRef,
    visited: &mut TypeExprRefSet,
) -> bool {
    use crate::types::type_expr::RowField;

    let repr = ctx.repr(ty);
    if !visited.insert(repr) {
        return false;
    }

    let desc = ctx.borrow_desc(repr);
    match &*desc {
        TypeDesc::Tconstr { path, args, .. } => {
            let has_local_head = matches!(path_root_module(path).view(), crate::types::path::PathView::Pident(id) if !id.is_persistent());
            // OCaml compiler/ml/env.ml:781-813 reads component descriptors for
            // type lookup without forcing env.ml:1568's module-declaration
            // thunk. This unresolved-path probe uses the explicit no-publish
            // cache mode so it does not make alias children such as
            // `Functions.Types` earlier than OCaml would.
            let local_path_is_unresolved =
                has_local_head && lookup_type_decl_for_path(path, env, pers_env, ctx).is_none();
            if local_path_is_unresolved {
                return true;
            }
            ctx.type_list(args)
                .iter()
                .any(|arg| type_contains_unresolved_local_path(ctx, env, pers_env, arg, visited))
        }
        TypeDesc::Tarrow { args, ret } => {
            ctx.type_args(args).iter().any(|arg| {
                type_contains_unresolved_local_path(ctx, env, pers_env, arg.typ, visited)
            }) || type_contains_unresolved_local_path(ctx, env, pers_env, *ret, visited)
        }
        TypeDesc::Ttuple(items) => ctx
            .type_list(items)
            .iter()
            .any(|item| type_contains_unresolved_local_path(ctx, env, pers_env, item, visited)),
        TypeDesc::Tlink(target) | TypeDesc::Tsubst(target) => {
            type_contains_unresolved_local_path(ctx, env, pers_env, *target, visited)
        }
        TypeDesc::Tobject { fields } => {
            type_contains_unresolved_local_path(ctx, env, pers_env, *fields, visited)
        }
        TypeDesc::Tfield { typ, rest, .. } => {
            type_contains_unresolved_local_path(ctx, env, pers_env, *typ, visited)
                || type_contains_unresolved_local_path(ctx, env, pers_env, *rest, visited)
        }
        TypeDesc::Tvariant(row) => {
            let row = &ctx.row_desc(row);
            for (_, field) in &row.row_fields {
                match field {
                    RowField::Rpresent(Some(ty)) => {
                        if type_contains_unresolved_local_path(ctx, env, pers_env, *ty, visited) {
                            return true;
                        }
                    }
                    RowField::Reither { types, .. }
                        if types.iter().any(|ty| {
                            type_contains_unresolved_local_path(ctx, env, pers_env, *ty, visited)
                        }) =>
                    {
                        return true;
                    }
                    _ => {}
                }
            }
            if type_contains_unresolved_local_path(ctx, env, pers_env, row.row_more, visited) {
                return true;
            }
            if let Some((_, args)) = &row.row_name {
                return args.iter().any(|arg| {
                    type_contains_unresolved_local_path(ctx, env, pers_env, *arg, visited)
                });
            }
            false
        }
        TypeDesc::Tpoly { body, vars } => {
            if type_contains_unresolved_local_path(ctx, env, pers_env, *body, visited) {
                return true;
            }
            ctx.type_list(vars)
                .iter()
                .any(|var| type_contains_unresolved_local_path(ctx, env, pers_env, var, visited))
        }
        TypeDesc::Tpackage { args, .. } => ctx
            .type_list(args)
            .iter()
            .any(|arg| type_contains_unresolved_local_path(ctx, env, pers_env, arg, visited)),
        TypeDesc::Tvar(..) | TypeDesc::Tunivar(..) | TypeDesc::Tnil => false,
    }
}


struct DisambiguatedConstructor {
    path: Path,
    desc: crate::types::decl::ConstructorDescription,
    source: ConstructorDisambiguationSource,
    ambiguous_types: Vec<String>,
}

enum ConstructorDisambiguationSource {
    InScope,
    ExpectedType { tpath: Path },
}

/// `Env.mark_type_used` (env.ml:1130-1133).
pub(crate) fn mark_type_used(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    name: impl crate::name::NameKey,
    type_loc: Location,
) {
    if !env.is_implicit_coercion() {
        ctx.usage().mark_type_used(name, type_loc);
    }
}

/// `Env.mark_constructor usage env name desc` (env.ml:1210-1224).
pub(crate) fn mark_constructor(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    usage: crate::types::usage::ConstructorUsage,
    name: &str,
    desc: &crate::types::decl::ConstructorDescription,
) {
    if env.is_implicit_coercion() {
        return;
    }
    let path = match &*ctx.get_desc(ctx.repr(desc.cstr_res)) {
        TypeDesc::Tconstr { path, .. } => *path,
        _ => return,
    };
    let loc = match &desc.cstr_kind {
        crate::types::decl::ConstructorKind::Extension(_) => Some(desc.cstr_loc),
        crate::types::decl::ConstructorKind::Ordinary(_) => {
            crate::types::ctype::lookup_type_decl_for_path(ctx, env, &path)
                .map(|decl| decl.type_loc)
        }
    };
    if let Some(loc) = loc {
        ctx.usage()
            .mark_constructor_used(usage, path.last_name(), ctx.resolve_loc(loc), name);
    }
}

/// `Env.mark_type_path` (env.ml:1180-1184).
pub(crate) fn mark_type_path(ctx: &crate::types::context::TypeContext, env: &Env, path: &Path) {
    let type_loc =
        crate::types::ctype::lookup_type_decl_for_path(ctx, env, path).map(|decl| decl.type_loc);
    if let Some(type_loc) = type_loc {
        mark_type_used(ctx, env, path.last_name(), ctx.resolve_loc(type_loc));
    }
}

/// `Env.mark_type_path env (ty_path ty)` on the result type of a
/// constructor or label.
pub(crate) fn mark_type_path_of(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    ty: TypeExprRef,
) {
    let path = match &*ctx.borrow_desc(ctx.repr(ty)) {
        TypeDesc::Tconstr { path, .. } => *path,
        _ => return,
    };
    mark_type_path(ctx, env, &path);
}

/// The `use ()` callback of a chosen in-scope constructor candidate: the
/// `wrap_use` of `Env.lookup_all_constructors` (env.ml:1197-1206) around
/// `TycompTbl.mk_callback` then `Env.check_shadowing` (env.ml:198-204,
/// 457-460).
fn use_constructor_candidate(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    name: &str,
    desc: &crate::types::decl::ConstructorDescription,
    mark: Option<(u32, Option<&crate::types::decl::ConstructorDescription>)>,
) {
    mark_type_path_of(ctx, env, desc.cstr_res);
    if let Some((slot, hidden)) = mark {
        let shadowed = hidden.is_some_and(|hidden| {
            !crate::types::ctype::same_constr(ctx, env, desc.cstr_res, hidden.cstr_res)
        });
        ctx.record_open_slot_use(slot, "constructor", name, shadowed);
    }
}

/// `disambiguate_by_type` (typecore.ml:875-880) picks the first label in
/// scope of the selected record type and `Label.disambiguate` calls its
/// `use ()` callback (typecore.ml:912-922). Candidates are matched by
/// `Path.same` on the result type.
fn use_in_scope_label_of_type(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    name: &str,
    selected: &crate::types::LabelDescription,
) {
    let Some(selected_path) = label_result_path(ctx, selected) else {
        return;
    };
    if let Some((desc, mark)) = env
        .find_all_labels_marking(name)
        .into_iter()
        .find(|(desc, _)| {
            label_result_path(ctx, desc).is_some_and(|path| path.same(&selected_path))
        })
    {
        use_label_candidate(ctx, env, name, desc, mark);
    }
}

/// The `use ()` callback of a chosen in-scope label candidate, with the
/// `wrap_use` of `Env.lookup_all_labels` (env.ml:1230-1238).
fn use_label_candidate(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    name: &str,
    desc: &crate::types::decl::LabelDescription,
    mark: Option<(u32, Option<&crate::types::decl::LabelDescription>)>,
) {
    mark_type_path_of(ctx, env, desc.lbl_res);
    if let Some((slot, hidden)) = mark {
        let shadowed = hidden.is_some_and(|hidden| {
            !crate::types::ctype::same_constr(ctx, env, desc.lbl_res, hidden.lbl_res)
        });
        ctx.record_open_slot_use(slot, "label", name, shadowed);
    }
}

/// Disambiguate a constructor by name, considering both the environment and
/// the expected type. Follows OCaml's disambiguate pattern:
/// 1. Try to extract the concrete variant type from expected_ty
/// 2. Find all constructors with the given name in the env
/// 3. If we have a type path from expected_ty, prefer the constructor matching that type
/// 4. Otherwise fall back to the first constructor in scope
fn disambiguate_constructor(
    cstr_name: &str,
    expected_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    report_ambiguous: bool,
) -> Result<Option<DisambiguatedConstructor>, Path> {
    // Step 1: Try to extract the variant type path from the expected type
    let opath = extract_variant_type_path_from_expected_with_persistent_env(
        expected_ty,
        env,
        pers_env,
        ctx,
    );

    // Step 2: Find all constructors with this name
    let marked_constrs = env.find_all_constructors_marking(cstr_name);
    let all_constrs: Vec<&crate::types::decl::ConstructorDescription> =
        marked_constrs.iter().map(|(desc, _)| *desc).collect();

    if all_constrs.is_empty() {
        // No constructors found in env - try type-directed lookup
        let Some(target_path) = opath else {
            return Ok(None);
        };
        return match lookup_constructor_by_expected_type(cstr_name, expected_ty, env, pers_env, ctx)
        {
            Some((path, desc)) => Ok(Some(DisambiguatedConstructor {
                path,
                desc,
                source: ConstructorDisambiguationSource::ExpectedType { tpath: target_path },
                ambiguous_types: Vec::new(),
            })),
            None if expected_type_constructor_names(&target_path, env, pers_env, ctx).is_some() => {
                Err(target_path)
            }
            None => Ok(None),
        };
    }

    // Step 3: If we have a target type path, try to disambiguate
    if let Some(ref target_path) = opath {
        // Match OCaml NameChoice.disambiguate_by_type: choose the first
        // path-compatible constructor in scope order, with compare_type_path
        // semantics (alias-expanded path compare).
        for (index, cstr) in all_constrs.iter().enumerate() {
            let cstr_ty = ctx.repr(cstr.cstr_res);
            let cstr_desc = ctx.get_desc(cstr_ty);
            if let TypeDesc::Tconstr {
                path: cstr_path, ..
            } = &*cstr_desc
            {
                // OCaml compiler/ml/typecore.ml:1238-1247 instantiates the
                // same `NameChoice.disambiguate_by_type` functor as labels;
                // typecore.ml:982-988 then calls `compare_type_path`, whose
                // `expand_path` (typecore.ml:776-784) uses side-effectful
                // `Env.normalize_path` even for already-equal paths.
                if compare_type_paths_for_constructor_disambiguation(
                    cstr_path,
                    target_path,
                    env,
                    pers_env,
                    ctx,
                ) {
                    use_constructor_candidate(ctx, env, cstr_name, cstr, marked_constrs[index].1);
                    let path = Path::pident(Ident::create_persistent(cstr_name));
                    return Ok(Some(DisambiguatedConstructor {
                        path,
                        desc: (*cstr).clone(),
                        source: ConstructorDisambiguationSource::InScope,
                        ambiguous_types: Vec::new(),
                    }));
                }
            }
        }
        // No constructor in env matched the expected type - try type-directed lookup
        // (the type might be defined in another module loaded from CMI)
        if let Some(result) =
            lookup_constructor_by_expected_type(cstr_name, expected_ty, env, pers_env, ctx)
        {
            let (path, desc) = result;
            return Ok(Some(DisambiguatedConstructor {
                path,
                desc,
                source: ConstructorDisambiguationSource::ExpectedType {
                    tpath: *target_path,
                },
                ambiguous_types: Vec::new(),
            }));
        }
        // OCaml `lookup_from_type` (typecore.ml:852-877) raises `Wrong_name`
        // when the expected type's descriptors do not contain the name.
        if expected_type_constructor_names(target_path, env, pers_env, ctx).is_some() {
            return Err(*target_path);
        }
    }

    // Step 4: Fall back to the first constructor in scope. OCaml
    // compiler/ml/typecore.ml:990-1008 warns with `ambiguous_types` of the
    // others in this `opath = None` branch.
    let cstr = all_constrs.first().unwrap();
    use_constructor_candidate(ctx, env, cstr_name, cstr, marked_constrs[0].1);
    let ambiguous_types = if report_ambiguous {
        ambiguous_constructor_warning_types(
            cstr,
            all_constrs.iter().skip(1).copied(),
            env,
            pers_env,
            ctx,
        )
    } else {
        Vec::new()
    };
    let path = Path::pident(Ident::create_persistent(cstr_name));
    Ok(Some(DisambiguatedConstructor {
        path,
        desc: (*cstr).clone(),
        source: ConstructorDisambiguationSource::InScope,
        ambiguous_types,
    }))
}

/// Constructor names of the expected variant type for OCaml `lookup_from_type`'s
/// `Wrong_name` (typecore.ml:852-877); `None` when the declaration is not found.
fn expected_type_constructor_names(
    tpath: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<Vec<String>> {
    let decl = lookup_type_decl_for_path(tpath, env, pers_env, ctx)?;
    Some(match &decl.type_kind {
        crate::types::TypeKind::TypeVariant(cstrs, _) => {
            cstrs.iter().map(|c| c.cd_id.name().to_string()).collect()
        }
        _ => Vec::new(),
    })
}

/// OCaml `wrap_disambiguate kind ty (Constructor.disambiguate ...)` turning
/// `lookup_from_type`'s `Wrong_name` into a located error.
fn wrong_constructor_name_error(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    loc: LocIdx,
    expected_ty: TypeExprRef,
    tpath: Path,
    name: &str,
    expected: &'static str,
) -> TypeCoreError {
    let alternatives =
        expected_type_constructor_names(&tpath, env, &mut tctx.persistent_env, tctx.type_ctx)
            .unwrap_or_default();
    TypeCoreError::WrongName {
        loc,
        kind: "constructor",
        ty: expected_ty,
        expected,
        path: tpath,
        name: name.to_string(),
        alternatives,
        jsx_component_info: None,
        env: Some(tctx.type_ctx.store_typed_env(env)),
    }
}

/// `Constructor.disambiguate` for a qualified constructor with an expected
/// type path (typecore.ml:914-944): the candidate is kept only when
/// `disambiguate_by_type` accepts it; `lookup_from_type` raises `Not_found`
/// for a qualified name, so the result is `Name_type_mismatch` with
/// `tp = (tpath0, expand_path tpath)` and the candidates' `(tp0, expand_path
/// tp0)`.
/// A type path and its expansion (`(tp, expand_path tp)`).
type ExpandedPath = (Path, Path);

fn qualified_constructor_type_mismatch(
    opath: Option<&Path>,
    cstr: &crate::types::decl::ConstructorDescription,
    expected_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(ExpandedPath, Vec<ExpandedPath>)> {
    let target_path = opath?;
    let cstr_path = constructor_result_path(ctx, cstr)?;
    if compare_type_paths_for_constructor_disambiguation(
        target_path,
        &cstr_path,
        env,
        pers_env,
        ctx,
    ) {
        return None;
    }
    let mut expand = |path: &Path| {
        expand_type_path_for_compare(path, env, pers_env, ctx, 0, &mut PathNameSet::default(), true)
    };
    let tpath0 = match &*ctx.get_desc(ctx.repr(expected_ty)) {
        TypeDesc::Tconstr { path, .. } => *path,
        _ => *target_path,
    };
    let expected = (tpath0, expand(target_path));
    let candidate = (cstr_path, expand(&cstr_path));
    Some((expected, vec![candidate]))
}

fn force_constructor_disambiguate_by_type_compare(
    opath: Option<&Path>,
    cstr: &crate::types::decl::ConstructorDescription,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) {
    let Some(target_path) = opath else {
        return;
    };
    let Some(cstr_path) = constructor_result_path(ctx, cstr) else {
        return;
    };
    let _ = compare_type_paths_for_constructor_disambiguation(
        target_path,
        &cstr_path,
        env,
        pers_env,
        ctx,
    );
}

fn constructor_result_path(
    ctx: &crate::types::context::TypeContext,
    cstr: &crate::types::decl::ConstructorDescription,
) -> Option<Path> {
    let res = ctx.repr(cstr.cstr_res);
    let desc = ctx.get_desc(res);
    match &*desc {
        TypeDesc::Tconstr { path, .. } => Some(*path),
        _ => None,
    }
}

fn ambiguous_constructor_warning_types<'a, 'b, I>(
    selected: &crate::types::decl::ConstructorDescription,
    others: I,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> Vec<String>
where
    I: IntoIterator<Item = &'b crate::types::decl::ConstructorDescription>,
{
    let Some(selected_path) = constructor_result_path(ctx, selected) else {
        return Vec::new();
    };
    let mut paths = vec![selected_path];
    for other in others {
        let Some(other_path) = constructor_result_path(ctx, other) else {
            continue;
        };
        if paths.iter().any(|path| {
            compare_type_paths_for_constructor_disambiguation(&other_path, path, env, pers_env, ctx)
        }) {
            continue;
        }
        paths.push(other_path);
    }

    if paths.len() <= 1 {
        Vec::new()
    } else {
        // `List.map Printtyp.string_of_path tpaths` (typecore.ml:888-891).
        let printer = crate::types::printtyp::Printtyp::new(ctx);
        paths
            .iter()
            .map(|path| printer.string_of_path(path))
            .collect()
    }
}

/// Type-directed label disambiguation when the label is not in scope.
///
/// OCaml's `Label.disambiguate` can still resolve labels using `opath` even
/// when `find_all_labels` is empty. Mirror that by inspecting the expected
/// record type declaration directly.
fn lookup_label_by_lid(
    tctx: &mut TypeCheckContext<'_>,
    lid: &Longident,
    loc: Option<LocIdx>,
    env: &Env,
    expected_record_ty: Option<TypeExprRef>,
    record_field_names: Option<(&[&str], bool)>,
) -> Option<crate::types::LabelDescription> {
    let arena = tctx.arena;
    let ctx = tctx.type_ctx;
    let pers_env = &mut tctx.persistent_env;
    let Longident::Ldot(module_lid, label_idx) = lid else {
        return None;
    };
    // `Typetexp.find_all_labels` marks the qualifying module through
    // `lookup_module_descr` (env.ml:1076-1089).
    mark_open_lid_use(
        ctx,
        env,
        arena,
        lid,
        crate::types::env::OpenLookupKind::Component,
        loc,
    );

    let label_name = arena.get_string(*label_idx);
    // OCaml compiler/ml/typecore.ml:1107-1126 calls
    // `Typetexp.find_all_labels` before `Label.disambiguate`; for qualified
    // labels that reaches compiler/ml/env.ml:1114-1120/1138-1142 and reads the
    // module component `comp_labels` table, whose label types went through
    // `prefix_idents`/`Subst` (env.ml:1516-1559).
    let mut candidates = with_resolved_module_components_for_lid(
        module_lid,
        arena,
        env,
        pers_env,
        ctx,
        |components| {
            let labels = components.lookup_labels(label_name, ctx);
            (!labels.is_empty()).then(|| labels.as_ref().clone())
        },
    )
    .flatten()?;

    if candidates.is_empty() {
        return None;
    }

    if let Some(record_ty) = expected_record_ty {
        if let Some(target_path) =
            extract_type_path_from_expected_with_persistent_env(record_ty, env, pers_env, ctx)
        {
            for candidate in &candidates {
                let cand_ty = ctx.repr(candidate.lbl_res);
                let cand_desc = ctx.get_desc(cand_ty);
                if let TypeDesc::Tconstr { path, .. } = &*cand_desc {
                    // OCaml compiler/ml/typecore.ml:983-988
                    // `disambiguate_by_type` calls `compare_type_path` directly
                    // for label selection. That reaches typecore.ml:776-787
                    // `expand_path`, whose Env.normalize_path fallback forces
                    // persistent ps_sig lazies through compiler/ml/env.ml:903-926
                    // and env.ml:865-875. Do not short-circuit exact paths here:
                    // the force timing affects later typedtree identifier stamps.
                    if compare_type_paths_for_label_disambiguation(
                        &target_path,
                        path,
                        env,
                        pers_env,
                        ctx,
                    ) {
                        return Some(candidate.clone());
                    }
                }
            }
        }
    }

    if expected_record_ty.is_none() {
        if let Some((field_names, closed_record)) = record_field_names {
            // OCaml compiler/ml/typecore.ml:1098-1126 passes qualified label
            // scope through `disambiguate_label_by_ids` before
            // `Label.disambiguate` when `opath = None`. That helper first keeps
            // labels whose `lbl_all` contains every source field
            // (typecore.ml:1071-1077), then applies the closed-record check
            // (typecore.ml:1078-1095). Do the same narrowing without calling
            // typecore.ml:983-988 `disambiguate_by_type`, so qualified labels do
            // not force `compare_type_path` earlier than the reference compiler.
            let matching_ids: Vec<_> = candidates
                .iter()
                .filter(|label| {
                    get_record_labels(ctx, env, pers_env, label.lbl_res)
                        .is_some_and(|labels| record_labels_have_field_ids(&labels, field_names))
                })
                .cloned()
                .collect();
            if !matching_ids.is_empty() {
                if closed_record {
                    let matching_closed: Vec<_> = matching_ids
                        .iter()
                        .filter(|label| {
                            get_record_labels(ctx, env, pers_env, label.lbl_res).is_some_and(
                                |labels| record_labels_satisfy_closed(&labels, field_names),
                            )
                        })
                        .cloned()
                        .collect();
                    candidates = if matching_closed.is_empty() {
                        matching_ids
                    } else {
                        matching_closed
                    };
                } else {
                    candidates = matching_ids;
                }
            }
        }
    }

    let selected = candidates.first().cloned()?;
    Some(selected)
}

fn qualified_label_name_type_mismatch(
    loc: LocIdx,
    lid: &Longident,
    arena: &ParseArena,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    expected_record_ty: TypeExprRef,
) -> Option<TypeCoreError> {
    let Longident::Ldot(module_lid, label_idx) = lid else {
        return None;
    };
    let expected_path = extract_type_path_from_expected_with_persistent_env(
        expected_record_ty,
        env,
        pers_env,
        ctx,
    )?;
    let label_name = arena.get_string(*label_idx);
    let candidates = with_resolved_module_components_for_lid(
        module_lid,
        arena,
        env,
        pers_env,
        ctx,
        |components| {
            let labels = components.lookup_labels(label_name, ctx);
            (!labels.is_empty()).then(|| labels.as_ref().clone())
        },
    )
    .flatten()?;

    if candidates.is_empty() {
        return None;
    }

    let mut alternatives = Vec::new();
    for candidate in &candidates {
        let Some(candidate_path) = label_result_path(ctx, candidate) else {
            continue;
        };
        if compare_type_paths_for_label_disambiguation(
            &expected_path,
            &candidate_path,
            env,
            pers_env,
            ctx,
        ) {
            return None;
        }
        alternatives.push((candidate_path, candidate_path));
    }

    if alternatives.is_empty() {
        return None;
    }

    Some(TypeCoreError::NameTypeMismatch {
        loc,
        kind: "record".to_string(),
        lid: lid.clone(),
        expected: (expected_path, expected_path),
        alternatives,
    })
}

fn extract_concrete_record_type_info(
    record_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, Vec<TypeExprRef>, Arc<crate::types::TypeDeclaration>)> {
    let mut current = ctx.repr(record_ty);
    let mut visited_types = ChainVisited::default();
    let mut visited_paths = ChainVisited::default();

    loop {
        current = ctx.repr(current);
        if !visited_types.insert(current.key()) {
            return None;
        }

        let desc = ctx.get_desc(current);
        match &*desc {
            TypeDesc::Tconstr { path, args, .. } => {
                let path = *path;
                let args = *args;

                if !visited_paths.insert(path) {
                    return None;
                }

                let decl = match lookup_type_decl_for_path(&path, env, pers_env, ctx) {
                    Some(decl) => decl,
                    None => {
                        if let Some((inline_path, inline_args, inline_decl)) =
                            lookup_inline_record_decl_for_path(
                                &path,
                                &ctx.type_list(args).to_smallvec::<4>(),
                                env,
                                pers_env,
                                ctx,
                            )
                        {
                            return Some((inline_path, inline_args, inline_decl));
                        }
                        return None;
                    }
                };
                match decl.type_kind {
                    crate::types::TypeKind::TypeRecord(_, _) => {
                        return Some((path, ctx.type_list(args).to_vec(), decl));
                    }
                    crate::types::TypeKind::TypeAbstract => {
                        // `try_expand_once` uses `Env.find_type_expansion`
                        // (env.ml:944-956): a private abstract type expands
                        // only when its body has a constructor row.
                        if let Some(manifest) = decl.type_manifest
                            && decl.type_private == crate::types::PrivateFlag::Private
                            && !crate::types::btype::has_constr_row(ctx, manifest)
                        {
                            return None;
                        }
                        let expanded = if let Some(manifest) = decl.type_manifest {
                            crate::types::ctype::subst_type_params(
                                ctx,
                                &decl.type_params,
                                &ctx.type_list(args).to_smallvec::<4>(),
                                manifest,
                            )
                        } else {
                            crate::types::ctype::expand_head(ctx, env, current)
                        };
                        let expanded = ctx.repr(expanded);
                        if expanded == current {
                            return None;
                        }
                        current = expanded;
                    }
                    _ => return None,
                }
            }
            TypeDesc::Tlink(target) | TypeDesc::Tsubst(target) => {
                current = *target;
            }
            _ => return None,
        }
    }
}

/// `snd (Env.find_type_descrs path env)` for the record declaration `decl`
/// found at `path` (compiler/ml/env.ml:782-828), as a label array.
///
/// A regular path names the labels installed with the type: `store_type`
/// for a local type (env.ml:1561-1569), the component table for a type of a
/// module (env.ml:1470-1485). Both are the arrays label lookup by name
/// returns. An inline-record constructor path describes the record afresh
/// (`type_of_cstr`, env.ml:782-784). A local constraint has no labels
/// (env.ml:790-791).
fn find_type_label_family(
    path: &Path,
    decl: &crate::types::TypeDeclaration,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<crate::types::LabelArrayRef> {
    use crate::types::path::Typath;
    // A record without labels describes no array.
    if !matches!(&decl.type_kind, crate::types::TypeKind::TypeRecord(labels, _) if !labels.is_empty())
    {
        return None;
    }
    match path.constructor_typath() {
        Typath::Regular(_) => {
            if env.find_local_constraint(path).is_some() {
                return None;
            }
            let family = match path.view() {
                PathView::Pident(id) => env.type_label_family(id),
                PathView::Pdot(parent, type_name, _) => {
                    with_resolved_module_components_for_path_with_cache_mode(
                        parent,
                        env,
                        pers_env,
                        ctx,
                        ComponentLookupApi::FindType,
                        |components| components.type_label_family(type_name, ctx),
                    )
                    .flatten()
                }
                PathView::Papply(..) => None,
            };
            Some(family.unwrap_or_else(|| {
                panic!(
                    "record type `{}` was found without the labels installed with it",
                    path.name()
                )
            }))
        }
        Typath::Cstr(..) | Typath::Ext(..) | Typath::LocalExt(_) => {
            let res_ty = ctx.new_generic_constr(*path, decl.type_params.clone());
            crate::types::env_lazy::label_descrs(res_ty, decl, decl.type_private, ctx, |_| {})
                .first()
                .map(|label| label.lbl_all)
        }
    }
}

fn build_record_label_descriptions(
    record_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<std::sync::Arc<Vec<crate::types::LabelDescription>>> {
    build_record_label_descriptions_info(record_ty, env, pers_env, ctx).map(|info| info.labels)
}

fn build_record_label_descriptions_info(
    record_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<RecordLabelDescriptionsInfo> {
    // OCaml reads the labels of the record `extract_concrete_typedecl` finds
    // through `Env.find_type_descrs` (compiler/ml/typecore.ml:976-977,
    // env.ml:828): the array installed with the declaration.
    let (record_path, _actual_args, decl) =
        extract_concrete_record_type_info(record_ty, env, pers_env, ctx)?;
    let family = find_type_label_family(&record_path, &decl, env, pers_env, ctx)?;
    Some(RecordLabelDescriptionsInfo {
        family,
        labels: ctx.label_family(family)?,
        summary: ctx.label_family_summary(family)?,
    })
}

fn lookup_label_by_expected_type(
    label_name: &str,
    record_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<crate::types::LabelDescription> {
    let visible_path =
        extract_type_path_from_expected_with_persistent_env(record_ty, env, pers_env, ctx)?;

    let env_labels = env.find_all_labels(label_name);
    for env_label in env_labels.iter() {
        let label_res = ctx.repr(env_label.lbl_res);
        let label_path = {
            let label_desc = ctx.get_desc(label_res);
            match &*label_desc {
                TypeDesc::Tconstr { path, .. } => *path,
                _ => continue,
            }
        };

        if label_path.same(&visible_path)
            || compare_type_paths_for_disambiguation(&label_path, &visible_path, env, pers_env, ctx)
        {
            // `disambiguate_by_type` returns the label as found, then `use ()`
            // (compiler/ml/typecore.ml:1002-1007, 1031-1034).
            mark_type_path(ctx, env, &label_path);
            return Some((*env_label).clone());
        }
    }

    let (concrete_path, _actual_args, type_decl) =
        extract_concrete_record_type_info(record_ty, env, pers_env, ctx)?;
    // `lookup_from_type` marks the type used (typecore.ml:852-854).
    mark_type_used(
        ctx,
        env,
        concrete_path.last(),
        ctx.resolve_loc(type_decl.type_loc),
    );
    let crate::types::TypeKind::TypeRecord(labels, _) = &type_decl.type_kind else {
        return None;
    };
    let pos = labels.iter().position(|ld| ld.ld_id.name() == label_name)?;
    // `lookup_from_type`: the labels of `Env.find_type_descrs tpath`
    // (compiler/ml/typecore.ml:976-981), the array installed with the type.
    let family = find_type_label_family(&concrete_path, &type_decl, env, pers_env, ctx)?;
    Some(ctx.label_family(family)?[pos].clone())
}

fn force_type_paths_for_lookup_from_type(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ty: TypeExprRef,
    seen: &mut crate::types::type_marks::TypeVisitSet,
) {
    use crate::types::type_expr::RowField;

    let ty = ctx.repr(ty);
    if !seen.visit(ty) {
        return;
    }

    let desc = ctx.get_desc(ty).into_desc();
    match desc {
        TypeDesc::Tconstr { path, args, .. } => {
            force_type_path_for_lookup_from_type(ctx, env, pers_env, &path);
            for arg in ctx.type_list(args) {
                force_type_paths_for_lookup_from_type(ctx, env, pers_env, arg, seen);
            }
        }
        TypeDesc::Tarrow { args, ret } => {
            for arg in ctx.type_args(args) {
                force_type_paths_for_lookup_from_type(ctx, env, pers_env, arg.typ, seen);
            }
            force_type_paths_for_lookup_from_type(ctx, env, pers_env, ret, seen);
        }
        TypeDesc::Ttuple(args) | TypeDesc::Tpackage { args, .. } => {
            for arg in ctx.type_list(args) {
                force_type_paths_for_lookup_from_type(ctx, env, pers_env, arg, seen);
            }
        }
        TypeDesc::Tobject { fields } => {
            force_type_paths_for_lookup_from_type(ctx, env, pers_env, fields, seen);
        }
        TypeDesc::Tfield { typ, rest, .. } => {
            force_type_paths_for_lookup_from_type(ctx, env, pers_env, typ, seen);
            force_type_paths_for_lookup_from_type(ctx, env, pers_env, rest, seen);
        }
        TypeDesc::Tvariant(row) => {
            let row = ctx.row_desc(row);
            force_type_paths_for_lookup_from_type(ctx, env, pers_env, row.row_more, seen);
            for (_label, field) in row.row_fields {
                match field {
                    RowField::Rpresent(Some(ty)) => {
                        force_type_paths_for_lookup_from_type(ctx, env, pers_env, ty, seen);
                    }
                    RowField::Reither { types, .. } => {
                        for ty in types {
                            force_type_paths_for_lookup_from_type(ctx, env, pers_env, ty, seen);
                        }
                    }
                    RowField::Rpresent(None) | RowField::Rabsent => {}
                }
            }
            if let Some((_path, args)) = row.row_name {
                for arg in args {
                    force_type_paths_for_lookup_from_type(ctx, env, pers_env, arg, seen);
                }
            }
        }
        TypeDesc::Tpoly { body, vars } => {
            force_type_paths_for_lookup_from_type(ctx, env, pers_env, body, seen);
            for var in ctx.type_list(vars) {
                force_type_paths_for_lookup_from_type(ctx, env, pers_env, var, seen);
            }
        }
        TypeDesc::Tlink(target) | TypeDesc::Tsubst(target) => {
            force_type_paths_for_lookup_from_type(ctx, env, pers_env, target, seen);
        }
        TypeDesc::Tvar(..) | TypeDesc::Tunivar(..) | TypeDesc::Tnil => {}
    }
}

fn force_type_path_for_lookup_from_type(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    path: &Path,
) {
    if let PathView::Pdot(parent, type_name, _) = path.view() {
        // OCaml compiler/ml/typecore.ml:942-967 `lookup_from_type` reaches
        // compiler/ml/env.ml:786-817 `find_type_descrs`/`find_type`, which
        // navigates persistent `ps_comps` built at env.ml:669-678. It does not
        // call `Env.normalize_path` or force `ps_sig`, so this side-effect pass
        // must stay at the component-table level instead of freshening every
        // sibling in the owning persistent signature.
        let _ =
            with_resolved_module_components_for_path(parent, env, pers_env, ctx, |components| {
                components.lookup_type(type_name.as_str()).is_some()
            });
    }
}

/// Disambiguate a label by name, considering the record expression's type.
/// Follows OCaml's Label.disambiguate pattern:
/// 1. Get all labels with the given name from the env
/// 2. Extract the type path from the record expression's type
/// 3. If we have a type path, prefer the label from that type
/// 4. Otherwise fall back to the first label in scope
fn disambiguate_label(
    label_name: &str,
    record_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<crate::types::LabelDescription> {
    // Extract type path from the record expression's type
    let opath = extract_type_path_from_expected_with_persistent_env(record_ty, env, pers_env, ctx);

    let lookup_name = label_name;

    // Find all labels with this name
    let all_labels = env.find_all_labels(lookup_name);
    if all_labels.is_empty() {
        return lookup_label_by_expected_type(
            lookup_name,
            record_ty,
            env,
            pers_env,
            ctx,
        );
    }

    let mut selected = None;

    // If we have a target type path, try to disambiguate by exact path identity.
    // Prefer the first matching label in OCaml scope order.
    if let Some(ref target_path) = opath {
        for label in all_labels.iter() {
            let lbl_ty = ctx.repr(label.lbl_res);
            let lbl_desc = ctx.get_desc(lbl_ty);
            if let TypeDesc::Tconstr { path: lbl_path, .. } = &*lbl_desc {
                // OCaml compiler/ml/typecore.ml:982-988 calls
                // `disambiguate_by_type`, whose `compare_type_path` reaches
                // typecore.ml:776-784 `expand_path`. That path uses
                // `Env.normalize_path` even for already-equal paths, so
                // preserve its lazy persistent-signature force here for
                // direct label disambiguation.
                if compare_type_paths_for_label_disambiguation(
                    lbl_path,
                    target_path,
                    env,
                    pers_env,
                    ctx,
                ) {
                    selected = Some((*label).clone());
                    break;
                }
            }
        }

        // OCaml disambiguation prefers exact-path matches and then falls back to
        // expected-type-directed lookup. Avoid name-based path matching here.
        if selected.is_none() {
            selected = lookup_label_by_expected_type(
                lookup_name,
                record_ty,
                env,
                pers_env,
                ctx,
            );
        }
    }

    // Keep expected-type fallback before defaulting to lexical shadowing order.
    if selected.is_none() {
        selected = lookup_label_by_expected_type(
            lookup_name,
            record_ty,
            env,
            pers_env,
            ctx,
        );
    }

    // In React component bodies, generated `props` labels can leak into the
    // global label scope and overshadow local record labels when no concrete
    // record type is known yet. Prefer a non-`props` candidate in that
    // unresolved case, then fall back to normal scope order.
    if selected.is_none() && opath.is_none() {
        let mut has_props = false;
        let mut non_props: Vec<&crate::types::LabelDescription> = Vec::new();
        for label in all_labels.iter() {
            let lbl_ty = ctx.repr(label.lbl_res);
            let lbl_desc = ctx.get_desc(lbl_ty);
            match &*lbl_desc {
                TypeDesc::Tconstr { path, .. } if path.last().trim_end_matches('!') == "props" => {
                    has_props = true;
                }
                _ => non_props.push(label),
            }
        }

        if has_props {
            selected = non_props.first().map(|label| (*label).clone());
        }
    }

    if selected.is_none() && opath.is_none() {
        selected = all_labels.first().map(|l| (*l).clone());
    }

    // `Label.disambiguate` calls the `use ()` callback of a candidate chosen
    // from the scope (typecore.ml:912-922).
    if let Some(label) = selected.as_ref() {
        if let Some((desc, mark)) = env
            .find_all_labels_marking(lookup_name)
            .into_iter()
            .find(|(desc, _)| desc.lbl_res == label.lbl_res && desc.lbl_pos == label.lbl_pos)
        {
            use_label_candidate(ctx, env, lookup_name, desc, mark);
        }
    }

    selected
}

/// Type-directed constructor disambiguation.
///
/// When a constructor like `A` is used without qualification and is not found
/// in the local env, look at the expected type to find which type defines it.
/// For example, if the expected type is `M.t` and `M.t` is defined as `A | B(int)`,
/// we can resolve the unqualified `A` constructor.
// Rust-side path qualification for copied label/constructor type nodes.
// The alias lookup callback mirrors OCaml's two environment paths:
// compiler/ml/env.ml:865-882 `find_module ~alias` forces `comp_modules`;
// compiler/ml/env.ml:781-793 `find_module_descr` reads component descriptors
// without forcing child module declarations.
type FindModuleAliasTarget<'a> = fn(
    &Path,
    &Env,
    &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    &'a crate::types::context::TypeContext,
) -> Option<Path>;

fn qualify_module_local_type_paths_in_place(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ty: TypeExprRef,
    module_access_path: &Path,
    visited: &mut HashSet<TypeExprRef>,
) {
    qualify_module_local_type_paths_with_alias_lookup_in_place(
        ctx,
        env,
        pers_env,
        ty,
        module_access_path,
        alias_target_for_module_path,
        visited,
    );
}

fn qualify_module_local_type_paths_from_module_descr_in_place(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ty: TypeExprRef,
    module_access_path: &Path,
    visited: &mut HashSet<TypeExprRef>,
) {
    qualify_module_local_type_paths_with_alias_lookup_in_place(
        ctx,
        env,
        pers_env,
        ty,
        module_access_path,
        raw_alias_target_for_module_path,
        visited,
    );
}

fn qualify_module_local_type_paths_with_alias_lookup_in_place<'a>(
    ctx: &'a crate::types::context::TypeContext,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ty: TypeExprRef,
    module_access_path: &Path,
    alias_target_lookup: FindModuleAliasTarget<'a>,
    visited: &mut HashSet<TypeExprRef>,
) {
    use crate::types::type_expr::RowField;

    // Rebuilt dots keep their suffix strings (compiler/ml/subst.ml:69-100).
    fn rewrite_path_prefix(
        ctx: &TypeContext,
        path: &Path,
        old_prefix: &Path,
        new_prefix: &Path,
    ) -> Option<Path> {
        if path.same(old_prefix) {
            return Some(*new_prefix);
        }
        match path.view() {
            PathView::Pdot(prefix, _, _) => rewrite_path_prefix(ctx, prefix, old_prefix, new_prefix)
                .map(|rewritten| ctx.copy_dotted_with_prefix(path, std::sync::Arc::new(rewritten))),
            _ => None,
        }
    }

    fn rewrite_flattened_head_prefix(
        ctx: &TypeContext,
        path: &Path,
        flat_head: &str,
        new_prefix: &Path,
    ) -> Option<Path> {
        match path.view() {
            PathView::Pident(id) if id.name() == flat_head => Some(*new_prefix),
            PathView::Pdot(prefix, _, _) => {
                rewrite_flattened_head_prefix(ctx, prefix, flat_head, new_prefix).map(|rewritten| {
                    ctx.copy_dotted_with_prefix(path, std::sync::Arc::new(rewritten))
                })
            }
            _ => None,
        }
    }

    fn path_has_suffix(path: &Path, suffix: &Path) -> bool {
        let Ok((path_head, path_components)) = path.flatten() else {
            return false;
        };
        let Ok((suffix_head, suffix_components)) = suffix.flatten() else {
            return false;
        };

        if path_components.len() + 1 < suffix_components.len() + 1 {
            return false;
        }

        let mut path_rev = path_components
            .iter()
            .rev()
            .map(|component| component.as_ref())
            .chain(std::iter::once(path_head.name()));
        suffix_components
            .iter()
            .rev()
            .map(|component| component.as_ref())
            .chain(std::iter::once(suffix_head.name()))
            .all(|suffix_component| path_rev.next() == Some(suffix_component))
    }

    fn flattened_alias_heads_from_persistent(
        pers_env: &Option<crate::cmi::persistent_env::PersistentEnv>,
        qualified_path: &Path,
    ) -> Vec<String> {
        let Some(pers) = pers_env.as_ref() else {
            return Vec::new();
        };
        pers.flattened_alias_heads_for_path(qualified_path)
    }

    fn rewrite_with_flattened_heads(
        ctx: &TypeContext,
        path: &Path,
        alias_path: &Path,
        module_access_path: &Path,
        pers_env: &Option<crate::cmi::persistent_env::PersistentEnv>,
    ) -> Option<Path> {
        let mut flat_heads = Vec::new();
        for flat in flattened_alias_heads_from_persistent(pers_env, alias_path) {
            if !flat_heads.iter().any(|existing| existing == &flat) {
                flat_heads.push(flat);
            }
        }

        for flat_head in flat_heads {
            let rewritten =
                rewrite_flattened_head_prefix(ctx, path, &flat_head, module_access_path);
            if rewritten.is_some() {
                return rewritten;
            }
        }
        None
    }

    fn prepend_module_prefix(ctx: &TypeContext, path: &Path, prefix: &Path) -> Option<Path> {
        match path.view() {
            PathView::Pident(id) => Some(ctx.dotted_from_ident(
                std::sync::Arc::new(*prefix),
                *id,
                crate::types::path::NOPOS,
            )),
            PathView::Pdot(parent, _, _) => prepend_module_prefix(ctx, parent, prefix)
                .map(|rewritten| ctx.copy_dotted_with_prefix(path, std::sync::Arc::new(rewritten))),
            PathView::Papply(_, _) => None,
        }
    }

    fn lookup_type_decl_for_qualification_probe(
        type_path: &Path,
        env: &Env,
        pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
        ctx: &crate::types::context::TypeContext,
    ) -> Option<Arc<crate::types::decl::TypeDeclaration>> {
        // OCaml compiler/ml/subst.ml:87-95 rewrites paths from the explicit
        // substitution map while env.ml:800-813 qualified type lookup reads
        // component type tables through `find_module_descr`. These
        // qualification probes only check whether a rewritten path exists; they
        // must not force env.ml:1568 module-declaration thunks or populate the
        // normal Rust lookup caches before the later real lookup reaches them.
        lookup_type_decl_for_path(type_path, env, pers_env, ctx)
    }

    let repr = ctx.repr(ty);
    if !visited.insert(repr) {
        return;
    }

    let desc = ctx.get_desc(repr).into_desc();
    match desc {
        TypeDesc::Tconstr {
            path, args, abbrev, ..
        } => {
            for arg in ctx.type_list(args).iter() {
                qualify_module_local_type_paths_with_alias_lookup_in_place(
                    ctx,
                    env,
                    pers_env,
                    arg,
                    module_access_path,
                    alias_target_lookup,
                    visited,
                );
            }
            let mut rewritten_path: Option<Path> = None;

            let alias_target = if path_non_apply_root_is_persistent_or_global(module_access_path) {
                // OCaml compiler/ml/env.ml:781-793 and env.ml:1000-1007
                // navigate persistent component paths through
                // `find_module_descr`, reading `ps_comps` or child
                // `comp_components` without forcing env.ml:1568's
                // `comp_modules` thunk. Local aliases such as
                // `module J = Js.Json` are non-persistent and still use
                // env.ml:865-882's forcing module-declaration lookup.
                raw_alias_target_for_module_path(module_access_path, env, pers_env, ctx)
            } else {
                alias_target_lookup(module_access_path, env, pers_env, ctx)
            };

            if let Some(alias_target) = alias_target {
                let direct_alias_target_parent = if let PathView::Pdot(parent, _, _) = path.view() {
                    Some(parent)
                } else {
                    None
                };
                let mut normalized_alias_target = None;
                let mut direct_alias_target_type =
                    direct_alias_target_parent.is_some_and(|parent| parent.same(&alias_target));
                if !direct_alias_target_type {
                    let normalized = env.normalize_path(ctx, &alias_target);
                    direct_alias_target_type =
                        direct_alias_target_parent.is_some_and(|parent| parent.same(&normalized));
                    normalized_alias_target = Some(normalized);
                }
                let direct_alias_target_reexported_by_parent = if direct_alias_target_type {
                    match (module_access_path.view(), path.view()) {
                        (
                            PathView::Pdot(selected_parent, _, _),
                            PathView::Pdot(_, type_name, _),
                        ) => env.find_type_with_path(type_name).ok().is_some_and(
                            |(selected_path, _)| {
                                selected_path
                                    .parent()
                                    .is_some_and(|parent| parent.same(selected_parent))
                            },
                        ),
                        _ => false,
                    }
                } else {
                    false
                };
                if !direct_alias_target_type || !direct_alias_target_reexported_by_parent {
                    // OCaml compiler/ml/env.ml:1517 scrapes aliases before
                    // compiler/ml/env.ml:1530-1538 applies the component
                    // substitution. compiler/ml/mtype.ml:41-49 leaves value
                    // descriptions unchanged while strengthening aliases, and
                    // compiler/ml/subst.ml:87-95 only rewrites the module
                    // prefix of dotted paths through explicit substitution maps.
                    // If the current environment already exposes the same
                    // opened type through compiler/ml/env.ml:1834-1881
                    // include/open handling, a direct target reference such as
                    // WasmBindings__Types.mouseEvent belongs to the included
                    // backing signature and stays on that backing unit. Read the
                    // existing opened binding only; forcing the parent component
                    // table here would create identifiers earlier than
                    // compiler/ml/env.ml:1568's lazy component thunk. Direct
                    // binders that are not re-exported by the parent, such as
                    // WasmBindings__Functions.err, are the selected module's
                    // own component and are rebased below.
                    let normalized_alias_target = normalized_alias_target
                        .unwrap_or_else(|| env.normalize_path(ctx, &alias_target));
                    rewritten_path =
                        rewrite_path_prefix(ctx, &path, &alias_target, module_access_path);
                    if rewritten_path.is_none() {
                        rewritten_path = rewrite_with_flattened_heads(
                            ctx,
                            &path,
                            &alias_target,
                            module_access_path,
                            pers_env,
                        );
                    }
                    if rewritten_path.is_none() && !normalized_alias_target.same(&alias_target) {
                        rewritten_path = rewrite_with_flattened_heads(
                            ctx,
                            &path,
                            &normalized_alias_target,
                            module_access_path,
                            pers_env,
                        );
                    }
                }
            }

            if rewritten_path.is_none() {
                if let PathView::Pdot(parent, type_name, _) = path.view() {
                    if path_has_suffix(parent, module_access_path) {
                        let candidate = Path::pdot(*module_access_path, type_name.as_str());
                        if !candidate.same(&path)
                            && lookup_type_decl_for_qualification_probe(
                                &candidate, env, pers_env, ctx,
                            )
                            .is_some()
                        {
                            rewritten_path = Some(candidate);
                        }
                    }
                }
            }

            if rewritten_path.is_none() {
                if let PathView::Pident(id) = path.view() {
                    // OCaml compiler/ml/env.ml:1530-1538 substitutes the
                    // component's own `Sig_type` binders (subst.ml:87-95
                    // matches by ident identity); a same-name type from
                    // outside the module, such as predef `array`, is kept.
                    let is_component_binder =
                        with_resolved_module_components_for_path_with_cache_mode(
                            module_access_path,
                            env,
                            pers_env,
                            ctx,
                            ComponentLookupApi::FindType,
                            |components| {
                                components
                                    .lookup_type(id.name())
                                    .is_some_and(|(binder, _)| binder.same(id))
                            },
                        )
                        .unwrap_or(false);
                    let candidate = Path::pdot(*module_access_path, id.name());
                    if is_component_binder
                        && lookup_type_decl_for_qualification_probe(&candidate, env, pers_env, ctx)
                            .is_some()
                    {
                        rewritten_path = Some(candidate);
                    }
                }
            }

            if rewritten_path.is_none() {
                // OCaml compiler/ml/subst.ml:91-95 rewrites the module prefix
                // of an existing `Pdot`; it does not prepend the selected
                // module again when the copied path already ends in that
                // module path. Avoid speculative `M.M.t` lookups that would
                // force unrelated persistent CMIs just to reject the candidate.
                let path_parent_has_module_suffix = match path.view() {
                    PathView::Pdot(parent, _, _) => path_has_suffix(parent, module_access_path),
                    _ => false,
                };
                // A bare `Pident` is only rewritten when it is the component's
                // own binder (checked above).
                if !path_parent_has_module_suffix
                    && !matches!(path.view(), PathView::Pident(_))
                    && let Some(candidate) = prepend_module_prefix(ctx, &path, module_access_path)
                    && !candidate.same(&path)
                    && lookup_type_decl_for_qualification_probe(&candidate, env, pers_env, ctx)
                        .is_some()
                {
                    rewritten_path = Some(candidate);
                }
            }

            if let Some(rewritten) = rewritten_path {
                ctx.set_desc(
                    repr,
                    TypeDesc::Tconstr {
                        path: rewritten,
                        args,
                        abbrev,
                    },
                );
            }
        }
        TypeDesc::Tarrow { args, ret } => {
            for arg in ctx.type_args(args) {
                qualify_module_local_type_paths_with_alias_lookup_in_place(
                    ctx,
                    env,
                    pers_env,
                    arg.typ,
                    module_access_path,
                    alias_target_lookup,
                    visited,
                );
            }
            qualify_module_local_type_paths_with_alias_lookup_in_place(
                ctx,
                env,
                pers_env,
                ret,
                module_access_path,
                alias_target_lookup,
                visited,
            );
        }
        TypeDesc::Ttuple(types) => {
            for item in ctx.type_list(types).iter() {
                qualify_module_local_type_paths_with_alias_lookup_in_place(
                    ctx,
                    env,
                    pers_env,
                    item,
                    module_access_path,
                    alias_target_lookup,
                    visited,
                );
            }
        }
        TypeDesc::Tlink(target) | TypeDesc::Tsubst(target) => {
            qualify_module_local_type_paths_with_alias_lookup_in_place(
                ctx,
                env,
                pers_env,
                target,
                module_access_path,
                alias_target_lookup,
                visited,
            );
        }
        TypeDesc::Tobject { fields } => {
            qualify_module_local_type_paths_with_alias_lookup_in_place(
                ctx,
                env,
                pers_env,
                fields,
                module_access_path,
                alias_target_lookup,
                visited,
            );
        }
        TypeDesc::Tfield { typ, rest, .. } => {
            qualify_module_local_type_paths_with_alias_lookup_in_place(
                ctx,
                env,
                pers_env,
                typ,
                module_access_path,
                alias_target_lookup,
                visited,
            );
            qualify_module_local_type_paths_with_alias_lookup_in_place(
                ctx,
                env,
                pers_env,
                rest,
                module_access_path,
                alias_target_lookup,
                visited,
            );
        }
        TypeDesc::Tvariant(row) => {
            let row = &ctx.row_desc(row);
            for (_label, field) in &row.row_fields {
                match field {
                    RowField::Rpresent(Some(ty)) => {
                        qualify_module_local_type_paths_with_alias_lookup_in_place(
                            ctx,
                            env,
                            pers_env,
                            *ty,
                            module_access_path,
                            alias_target_lookup,
                            visited,
                        );
                    }
                    RowField::Reither { types, .. } => {
                        for ty in types {
                            qualify_module_local_type_paths_with_alias_lookup_in_place(
                                ctx,
                                env,
                                pers_env,
                                *ty,
                                module_access_path,
                                alias_target_lookup,
                                visited,
                            );
                        }
                    }
                    _ => {}
                }
            }
            qualify_module_local_type_paths_with_alias_lookup_in_place(
                ctx,
                env,
                pers_env,
                row.row_more,
                module_access_path,
                alias_target_lookup,
                visited,
            );
            if let Some((_, args)) = &row.row_name {
                for item in args {
                    qualify_module_local_type_paths_with_alias_lookup_in_place(
                        ctx,
                        env,
                        pers_env,
                        *item,
                        module_access_path,
                        alias_target_lookup,
                        visited,
                    );
                }
            }
        }
        TypeDesc::Tpoly { body, vars } => {
            qualify_module_local_type_paths_with_alias_lookup_in_place(
                ctx,
                env,
                pers_env,
                body,
                module_access_path,
                alias_target_lookup,
                visited,
            );
            for var in ctx.type_list(vars).iter() {
                qualify_module_local_type_paths_with_alias_lookup_in_place(
                    ctx,
                    env,
                    pers_env,
                    var,
                    module_access_path,
                    alias_target_lookup,
                    visited,
                );
            }
        }
        TypeDesc::Tpackage { args, .. } => {
            for item in ctx.type_list(args).iter() {
                qualify_module_local_type_paths_with_alias_lookup_in_place(
                    ctx,
                    env,
                    pers_env,
                    item,
                    module_access_path,
                    alias_target_lookup,
                    visited,
                );
            }
        }
        TypeDesc::Tvar(..) | TypeDesc::Tunivar(..) | TypeDesc::Tnil => {}
    }
}

fn lookup_constructor_from_type_descrs(
    cstr_name: &str,
    type_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, crate::types::decl::ConstructorDescription)> {
    let PathView::Pdot(parent, type_name, _) = type_path.view() else {
        return None;
    };

    // OCaml compiler/ml/typecore.ml:942-959 implements
    // `NameChoice.lookup_from_type` by calling `Env.find_type_descrs`.
    // For dotted paths, compiler/ml/env.ml:804-817 reaches the parent module
    // component table (`ps_comps`) before selecting constructors for exactly
    // this type; it does not call env.ml:865-882 `find_module` and therefore
    // does not force the persistent `ps_sig` binder-renaming thunk here.
    let desc = with_resolved_module_components_for_path(parent, env, pers_env, ctx, |components| {
        let (_, _) = components.lookup_type(type_name.as_str())?;
        let component_type_path = Path::pdot(*components.access_path(), type_name.as_str());
        let constructors = components.lookup_constructors(cstr_name, ctx);
        constructors.iter().find_map(|desc| {
            let res_repr = ctx.repr(desc.cstr_res);
            let res_desc = ctx.get_desc(res_repr);
            let matches = match &*res_desc {
                TypeDesc::Tconstr { path, .. } => path.same(&component_type_path),
                _ => false,
            };
            matches.then(|| desc.clone())
        })
    })
    .flatten()?;

    Some((Path::pident(Ident::create_persistent(cstr_name)), desc))
}

fn lookup_constructor_by_expected_type(
    cstr_name: &str,
    expected_ty: TypeExprRef,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, crate::types::decl::ConstructorDescription)> {
    // Match OCaml's disambiguation behavior: first expand expected type aliases
    // (extract_concrete_variant), then inspect constructors on the concrete path.
    let type_path = extract_variant_type_path_from_expected_with_persistent_env(
        expected_ty,
        env,
        pers_env,
        ctx,
    )?;

    // `lookup_from_type` marks the type used (typecore.ml:852-854).
    mark_type_path(ctx, env, &type_path);
    if let Some(result) =
        lookup_constructor_from_type_descrs(cstr_name, &type_path, env, pers_env, ctx)
    {
        return Some(result);
    }

    // Look up the type declaration.
    let concrete_type_decl = lookup_type_decl_for_path(&type_path, env, pers_env, ctx)?;
    // Prefer declaration-carried canonical path (e.g. opened `t` -> `J.t`)
    // so constructor result heads match OCaml's qualified paths.
    let concrete_type_path = concrete_type_decl
        .type_path
        .unwrap_or(type_path);
    // OCaml `extract_concrete_typedecl` returns both the original expected path
    // and the expanded concrete path (compiler/ml/ctype.ml:1449-1460), but
    // `NameChoice.lookup_from_type` fetches constructors from the concrete path
    // (compiler/ml/typecore.ml:948-958). `instance_constructor` then copies that
    // concrete constructor result unchanged (compiler/ml/ctype.ml:1109-1130).
    let result_type_path = concrete_type_path;

    // Check if it's a variant type with a matching constructor
    if let crate::types::TypeKind::TypeVariant(ref constrs, layout) = concrete_type_decl.type_kind {
        for (position, cd) in constrs.iter().enumerate() {
            if cd.cd_id.name() == cstr_name {
                let mut inst_cache = HashMap::new();
                let constructor_module_access_path = concrete_type_path.parent();
                let result_module_access_path = result_type_path.parent();
                let (cstr_args, cstr_arity, cstr_inlined) = match &cd.cd_args {
                    crate::types::ConstructorArguments::CstrTuple(args) => {
                        let mut copied_args = Vec::with_capacity(args.len());
                        for arg in args {
                            let copied =
                                crate::types::ctype::copy_type_deep(ctx, *arg, &mut inst_cache);
                            if let Some(module_path) = constructor_module_access_path.as_ref() {
                                let mut visited = HashSet::new();
                                qualify_module_local_type_paths_in_place(
                                    ctx,
                                    env,
                                    pers_env,
                                    copied,
                                    module_path,
                                    &mut visited,
                                );
                            }
                            copied_args.push(copied);
                        }
                        (copied_args, args.len() as i32, None)
                    }
                    crate::types::ConstructorArguments::CstrRecord(labels) => {
                        let copied_labels: Vec<crate::types::decl::LabelDeclaration> = labels
                            .iter()
                            .map(|label| {
                                let mut copied = label.clone();
                                copied.ld_type = crate::types::ctype::copy_type_deep(
                                    ctx,
                                    label.ld_type,
                                    &mut inst_cache,
                                );
                                if let Some(module_path) = constructor_module_access_path.as_ref() {
                                    let mut visited = HashSet::new();
                                    qualify_module_local_type_paths_in_place(
                                        ctx,
                                        env,
                                        pers_env,
                                        copied.ld_type,
                                        module_path,
                                        &mut visited,
                                    );
                                }
                                copied
                            })
                            .collect();
                        // The parameters are the original labels' free variables
                        // (datarepr.ml:73-75), deep-copied with the labels' cache
                        // so that they match the copied labels.
                        let inline_params = inline_record_type_params(ctx, labels)
                            .into_iter()
                            .map(|param| {
                                let copied = crate::types::ctype::copy_type_deep(
                                    ctx,
                                    param,
                                    &mut inst_cache,
                                );
                                if let Some(module_path) = constructor_module_access_path.as_ref()
                                {
                                    let mut visited = HashSet::new();
                                    qualify_module_local_type_paths_in_place(
                                        ctx,
                                        env,
                                        pers_env,
                                        copied,
                                        module_path,
                                        &mut visited,
                                    );
                                }
                                copied
                            })
                            .collect::<Vec<_>>();
                        let inline_path =
                            Path::pdot(concrete_type_path, cstr_name.to_string());
                        let inline_constr =
                            ctx.new_generic_constr(inline_path, inline_params.clone());
                        let inline_decl = crate::types::TypeDeclaration {
                            type_params: inline_params.clone(),
                            type_arity: inline_params.len() as i32,
                            type_kind: crate::types::TypeKind::TypeRecord(
                                crate::types::decl::SharedVec::from(copied_labels),
                                if concrete_type_decl.type_representation
                                    == crate::types::TypeRepresentation::Unboxed
                                {
                                    // compiler/ml/datarepr.ml:163-164: unboxed inline records use `Record_unboxed true`.
                                    crate::types::RecordRepresentation::RecordUnboxed(true)
                                } else {
                                    crate::types::RecordRepresentation::RecordInlined {
                                        name: cstr_name.to_string(),
                                        representation: crate::types::ConstructorReference {
                                            variant: layout,
                                            position,
                                        },
                                    }
                                },
                            ),
                            type_private: concrete_type_decl.type_private,
                            type_manifest: None,
                            type_variance: inline_params
                                .iter()
                                .map(|_| crate::types::variance::Variance::full())
                                .collect(),
                            type_newtype_level: None,
                            type_loc: cd.cd_loc,
                            type_attributes: vec![],
                            type_immediate: false,
                            type_representation: crate::types::TypeRepresentation::Boxed,
                            type_shape: crate::types::ValueShape::Unstated,
                            type_inlined_types: vec![],
                            type_path: None,
                        };
                        (vec![inline_constr], 1, Some(Box::new(inline_decl)))
                    }
                };
                // Use the type path's head ident for the result type
                let cstr_res = if let Some(res) = cd.cd_res {
                    // Match lookup_constructor_in_module + OCaml substitution:
                    // when constructor result is a specialized Tconstr (GADT),
                    // remap the head path to the concrete expected type path,
                    // while preserving copied/shared argument nodes.
                    let res_repr = ctx.repr(res);
                    let res_desc = ctx.get_desc(res_repr);
                    match &*res_desc {
                        crate::types::TypeDesc::Tconstr { args, .. } => {
                            let args = *args;
                            let mapped_args = ctx
                                .type_list(args)
                                .iter()
                                .map(|arg| {
                                    let copied = crate::types::ctype::copy_type_deep(
                                        ctx,
                                        arg,
                                        &mut inst_cache,
                                    );
                                    if let Some(module_path) = result_module_access_path.as_ref() {
                                        let mut visited = HashSet::new();
                                        qualify_module_local_type_paths_in_place(
                                            ctx,
                                            env,
                                            pers_env,
                                            copied,
                                            module_path,
                                            &mut visited,
                                        );
                                    }
                                    copied
                                })
                                .collect();
                            ctx.new_generic_constr(result_type_path, mapped_args)
                        }
                        _ => {
                            let copied =
                                crate::types::ctype::copy_type_deep(ctx, res, &mut inst_cache);
                            if let Some(module_path) = result_module_access_path.as_ref() {
                                let mut visited = HashSet::new();
                                qualify_module_local_type_paths_in_place(
                                    ctx,
                                    env,
                                    pers_env,
                                    copied,
                                    module_path,
                                    &mut visited,
                                );
                            }
                            copied
                        }
                    }
                } else {
                    let result_params = concrete_type_decl
                        .type_params
                        .iter()
                        .map(|param| {
                            let copied =
                                crate::types::ctype::copy_type_deep(ctx, *param, &mut inst_cache);
                            if let Some(module_path) = result_module_access_path.as_ref() {
                                let mut visited = HashSet::new();
                                qualify_module_local_type_paths_in_place(
                                    ctx,
                                    env,
                                    pers_env,
                                    copied,
                                    module_path,
                                    &mut visited,
                                );
                            }
                            copied
                        })
                        .collect();
                    ctx.new_generic_constr(result_type_path, result_params)
                };
                let desc = crate::types::decl::ConstructorDescription {
                    cstr_name: cstr_name.to_string(),
                    cstr_res,
                    cstr_existentials: vec![],
                    cstr_args,
                    cstr_arity,
                    cstr_kind: crate::types::ConstructorKind::Ordinary(
                        crate::types::ConstructorReference {
                            variant: layout,
                            position,
                        },
                    ),
                    cstr_generalized: cd.cd_res.is_some(),
                    cstr_private: concrete_type_decl.type_private,
                    cstr_loc: cd.cd_loc,
                    cstr_attributes: crate::types::decl::constructor_description_attrs_for_variant(
                        constrs, cd,
                    ),
                    cstr_inlined,
                };
                let path = Path::pident(Ident::create_persistent(cstr_name));
                return Some((path, desc));
            }
        }
    }
    None
}

pub(crate) fn strengthen_type_decl_for_module_access_path(
    ctx: &crate::types::context::TypeContext,
    module_access_path: &Path,
    id: &Ident,
    decl: &crate::types::decl::TypeDeclaration,
) -> crate::types::decl::TypeDeclaration {
    strengthen_type_decl_with_shared_prefix(ctx, &Arc::new(*module_access_path), id, decl)
}

pub(crate) fn strengthen_type_decl_with_shared_prefix(
    ctx: &crate::types::context::TypeContext,
    module_access_path: &Arc<Path>,
    id: &Ident,
    decl: &crate::types::decl::TypeDeclaration,
) -> crate::types::decl::TypeDeclaration {
    // Match OCaml mtype.ml strengthen_sig:
    // keep existing manifests for public types and private record/variant
    // types; otherwise attach a self-manifest alias for this access path.
    let keep_manifest = matches!(
        (&decl.type_manifest, decl.type_private, &decl.type_kind),
        (Some(_), crate::types::PrivateFlag::Public, _)
            | (
                Some(_),
                crate::types::PrivateFlag::Private,
                crate::types::TypeKind::TypeRecord(..) | crate::types::TypeKind::TypeVariant(..),
            )
    );

    if keep_manifest {
        return decl.clone();
    }

    let mut strengthened = decl.clone();
    let manifest_path =
        ctx.dotted_from_ident(module_access_path.clone(), *id, crate::types::path::NOPOS);
    let manifest = ctx.new_generic_constr(manifest_path, decl.type_params.clone());
    strengthened.type_manifest = Some(manifest);
    if matches!(decl.type_kind, crate::types::TypeKind::TypeAbstract) {
        strengthened.type_private = crate::types::PrivateFlag::Public;
    }
    strengthened
}

fn strengthen_sig_for_module_access_path(
    ctx: &crate::types::context::TypeContext,
    module_access_path: &Path,
    sig_items: &[crate::types::decl::SignatureItem],
) -> crate::types::decl::Signature {
    let module_access_path = &Arc::new(*module_access_path);
    let mut strengthened = Vec::with_capacity(sig_items.len());
    let mut runtime_pos = 0i32;

    let mut index = 0usize;
    while index < sig_items.len() {
        let item = &sig_items[index];
        if let crate::types::decl::SignatureItem::SigType(id, decl, _) = item
            && matches!(decl.type_kind, crate::types::TypeKind::TypeAbstract)
            && let Some(crate::types::decl::SignatureItem::SigType(next_id, next_decl, _)) =
                sig_items.get(index + 1)
            && next_decl.type_private == crate::types::PrivateFlag::Private
            && id.name().strip_suffix("#row") == Some(next_id.name())
        {
            index += 1;
            continue;
        }
        match item {
            crate::types::decl::SignatureItem::SigValue(id, desc) => {
                strengthened.push(crate::types::decl::SignatureItem::SigValue(
                    *id,
                    desc.clone(),
                ));
                if !matches!(desc.val_kind, crate::types::decl::ValueKind::ValPrim(_)) {
                    runtime_pos += 1;
                }
            }
            crate::types::decl::SignatureItem::SigType(id, decl, rec_status) => {
                // OCaml compiler/ml/mtype.ml:56-71 strengthens type
                // declarations by adding a self manifest at `Pdot(p, id)`.
                strengthened.push(crate::types::decl::SignatureItem::SigType(
                    *id,
                    std::sync::Arc::new(strengthen_type_decl_with_shared_prefix(
                        ctx,
                        module_access_path,
                        id,
                        decl,
                    )),
                    *rec_status,
                ));
            }
            crate::types::decl::SignatureItem::SigTypext(id, ext, ext_status) => {
                strengthened.push(crate::types::decl::SignatureItem::SigTypext(
                    *id,
                    ext.clone(),
                    *ext_status,
                ));
                runtime_pos += 1;
            }
            crate::types::decl::SignatureItem::SigModule(id, md, rec_status) => {
                // OCaml compiler/ml/mtype.ml:76-80 calls
                // `strengthen_decl ~aliasable` while walking the signature, and
                // compiler/ml/mtype.ml:98-102 replaces non-alias child modules
                // with `Mty_alias(Mta_present, Pdot(p, id, pos))` immediately.
                // Do this before any component substitution so parent-level
                // rewrites cannot descend into nested signatures that OCaml has
                // already hidden behind the child alias thunk.
                let mut strengthened_md = md.clone();
                if !matches!(
                    strengthened_md.md_type,
                    crate::types::decl::ModuleType::MtyAlias(..)
                ) {
                    strengthened_md.md_type = crate::types::decl::ModuleType::MtyAlias(
                        crate::types::decl::AliasPresence::MtaPresent,
                        std::sync::Arc::new(ctx.dotted_from_ident(
                            module_access_path.clone(),
                            *id,
                            runtime_pos,
                        )),
                    );
                }
                strengthened.push(crate::types::decl::SignatureItem::SigModule(
                    *id,
                    strengthened_md,
                    *rec_status,
                ));
                runtime_pos += 1;
            }
            crate::types::decl::SignatureItem::SigModtype(id, decl) => {
                // OCaml compiler/ml/mtype.ml:83-91 gives abstract module
                // types a manifest `Mty_ident(Pdot(p, id, nopos))`.
                let mut strengthened_decl = decl.clone();
                if strengthened_decl.mtd_type.is_none() {
                    strengthened_decl.mtd_type = Some(crate::types::decl::ModuleType::MtyIdent(
                        ctx.dotted_from_ident(
                            module_access_path.clone(),
                            *id,
                            crate::types::path::NOPOS,
                        ),
                    ));
                }
                strengthened.push(crate::types::decl::SignatureItem::SigModtype(
                    *id,
                    strengthened_decl,
                ));
            }
            crate::types::decl::SignatureItem::SigClass => {
                strengthened.push(crate::types::decl::SignatureItem::SigClass);
                runtime_pos += 1;
            }
            crate::types::decl::SignatureItem::SigClassType => {
                strengthened.push(crate::types::decl::SignatureItem::SigClassType);
            }
        }
        index += 1;
    }

    strengthened
}

fn strengthen_sig_module_decls_for_module_access_path(
    sig_items: &mut [crate::types::decl::SignatureItem],
    module_access_path: &Path,
    ctx: &TypeContext,
) {
    let module_access_path = Arc::new(*module_access_path);
    let mut runtime_pos = 0i32;

    for item in sig_items.iter_mut() {
        match item {
            crate::types::decl::SignatureItem::SigValue(_, desc) => {
                if !matches!(desc.val_kind, crate::types::decl::ValueKind::ValPrim(_)) {
                    runtime_pos += 1;
                }
            }
            crate::types::decl::SignatureItem::SigType(_, _, _) => {}
            crate::types::decl::SignatureItem::SigTypext(_, _, _) => {
                runtime_pos += 1;
            }
            crate::types::decl::SignatureItem::SigModule(id, md, _) => {
                // OCaml compiler/ml/mtype.ml:76-80 calls
                // `strengthen_decl ~aliasable` with the runtime component
                // path, and compiler/ml/mtype.ml:98-102 turns non-alias
                // children into `Mty_alias(Mta_present, Pdot(p, id, pos))`.
                if !matches!(md.md_type, crate::types::decl::ModuleType::MtyAlias(..)) {
                    md.md_type = crate::types::decl::ModuleType::MtyAlias(
                        crate::types::decl::AliasPresence::MtaPresent,
                        std::sync::Arc::new(ctx.dotted_from_ident(
                            module_access_path.clone(),
                            *id,
                            runtime_pos,
                        )),
                    );
                }
                runtime_pos += 1;
            }
            crate::types::decl::SignatureItem::SigModtype(_, _) => {}
            crate::types::decl::SignatureItem::SigClass => {
                runtime_pos += 1;
            }
            crate::types::decl::SignatureItem::SigClassType => {}
        }
    }
}

fn module_type_has_hidden_unpack_ident(mty: &crate::types::decl::ModuleType) -> bool {
    match mty.ident_or_alias_path().map(|p| p.view()) {
        Some(PathView::Pident(id)) => id.name().starts_with("__") || id.is_persistent(),
        _ => false,
    }
}

fn should_rebind_direct_sig_type_family(
    mty: &crate::types::decl::ModuleType,
    access_path: &Path,
) -> bool {
    use crate::types::decl::ModuleType as DeclMty;

    // OCaml compiler/ml/path.ml:61 makes `Path.head` invalid for `Papply`,
    // while compiler/ml/env.ml:1744-1751 passes `Papply` roots for applicative
    // functor components into the same env.ml:1530-1538 prefixing path.
    if path_non_apply_root_is_persistent(access_path) {
        return false;
    }

    match mty {
        // Module aliases and module-type references can expose direct type-family
        // paths through declaration `type_path` fields or direct self-manifests
        // after lookup/substitution. Do not infer paths by scanning unrelated
        // signature contents.
        DeclMty::MtyAlias(_, _) | DeclMty::MtyIdent(_) => true,
        _ => false,
    }
}

pub(crate) fn rebind_direct_sig_type_family_to_access_path(
    ctx: &crate::types::context::TypeContext,
    access_path: &Path,
    sig_items: &mut [crate::types::decl::SignatureItem],
) {
    use crate::types::decl::SignatureItem;

    let access_path = Arc::new(*access_path);
    let mut rewrites = Vec::<(Path, Path)>::new();
    for item in sig_items.iter() {
        if let SignatureItem::SigType(id, decl, _) = item {
            let rebound_path =
                ctx.dotted_from_ident(access_path.clone(), *id, crate::types::path::NOPOS);
            if let Some(old_path) = decl.type_path.as_ref() {
                if !old_path.same(&rebound_path) {
                    rewrites.push((*old_path, rebound_path));
                }
            }
        }
    }

    rewrites.sort_by(|(left_old, left_new), (right_old, right_new)| {
        left_old
            .name()
            .cmp(&right_old.name())
            .then_with(|| left_new.name().cmp(&right_new.name()))
    });
    rewrites.dedup_by(|(left_old, left_new), (right_old, right_new)| {
        left_old.same(right_old) && left_new.same(right_new)
    });

    for (old_path, rebound_path) in rewrites {
        let rewrite_target = std::sync::Arc::new(rebound_path);
        crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
            sig_items,
            &old_path,
            &rewrite_target,
            ctx,
        );
        // OCaml compiler/ml/env.ml:1530-1538 builds the component substitution
        // for both declaration descriptors and the identifier paths stored in
        // those declarations; compiler/ml/subst.ml:87-100 applies the same
        // path map to `type_path`. Keep Rust declaration paths in step with
        // the rewritten type expressions so later Env/Ctype lookups do not
        // force a separate functor-application component view.
        crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
            sig_items,
            &old_path,
            &rewrite_target,
            ctx,
        );
    }
}

fn path_cache_key(path: &Path) -> Option<String> {
    // Match `Path.flatten` in compiler/ml/path.ml:63-69: any nested
    // `Papply` is `Contains_apply`, so cache keys that need a single head
    // identifier are only valid for regular dotted paths.
    fn dotted_head(path: &Path) -> Option<&Ident> {
        match path.view() {
            PathView::Pident(id) => Some(id),
            PathView::Pdot(prefix, _, _) => dotted_head(prefix),
            PathView::Papply(_, _) => None,
        }
    }
    let head = dotted_head(path)?;
    let mut key = String::with_capacity(48);
    path.write_name_with_paren(&mut key, |_| false);
    if !(head.is_persistent() || head.stamp() == 0) {
        use std::fmt::Write as _;
        let _ = write!(key, "#{}", head.stamp());
    }
    Some(key)
}

fn module_path_requires_env_scoped_cache(env: &Env, module_path: &Path) -> bool {
    env.module_path_requires_env_scoped_cache(module_path)
}

fn scope_local_module_cache_key(module_path: &Path, env: &Env) -> Option<super::env::ScopeId> {
    module_path_requires_env_scoped_cache(env, module_path).then_some(env.scope_id())
}

fn module_components_cache_key(
    module_path: &Path,
    env: &Env,
) -> Option<crate::types::context::QualifiedModuleComponentsCacheKey> {
    if matches!(module_path.view(), PathView::Papply(_, _)) {
        // OCaml compiler/ml/env.ml:1744-1756 caches
        // `components_of_functor_appl` per argument path in `fcomp_cache`.
        // A Papply has no stable flattened head, but the full path is still
        // the cache identity; the cache belongs to the functor components, so
        // cloned Rust Env values must not allocate a second application view.
        return Some(
            crate::types::context::QualifiedModuleComponentsCacheKey::new(
                *module_path,
                None,
            ),
        );
    }
    // Match `Path.flatten` in compiler/ml/path.ml:63-69: dotted paths whose
    // parent is a functor application have no single stable cache head.
    if module_path.has_apply_prefix() {
        return None;
    }
    let env_id = match module_path.view() {
        // OCaml compiler/ml/path.ml:20-24 and env.ml:781-793 identify a local
        // module path by its `Pident` stamp. Cloned Rust Env values can have
        // different env ids while still pointing at the same local module
        // identity, so do not env-scope this cache key for a stamped Pident.
        PathView::Pident(id) if !id.is_persistent() && id.stamp() != 0 => None,
        // Component resolution reads only module-level bindings.
        _ => module_path_requires_env_scoped_cache(env, module_path).then_some(env.scope_id()),
    };
    Some(crate::types::context::QualifiedModuleComponentsCacheKey::new(*module_path, env_id))
}

fn with_resolved_child_module_components<R>(
    parent_components: crate::types::env_lazy::Components<'_>,
    child_name: &str,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
    f: impl FnOnce(i32, crate::types::env_lazy::Components<'_>) -> R,
) -> Option<R> {
    let mut f = Some(f);
    let step_pos = |path: &Path| match path.view() {
        PathView::Pdot(_, _, pos) => *pos,
        _ => unreachable!("a child module's access path is dotted"),
    };
    // OCaml compiler/ml/env.ml:1454-1491 builds dotted component paths with
    // `prefix_idents`, then env.ml:1568 and env.ml:1573-1578 store a child
    // module's `comp_modules` and `comp_components` as separate thunks. Direct
    // persistent-unit descent such as `Inner_define.N` follows env.ml:1000-1007
    // through `comp_components` only, and explicit opens keep that lazy order.
    // Module-declaration forcing must come from the actual env.ml:865-882
    // lookup/normalization path, not from inspecting the child signature shape.
    // Alias children are the direct `scrape_alias` case: env.ml:1517 calls
    // `scrape_alias`, and env.ml:1441-1444 forces `find_module path env`
    // through env.ml:865-882 before the aliased component table is built.
    if let Some((runtime_pos, stored)) = parent_components.lookup_child_components(child_name, ctx)
    {
        let access_path = if parent_components.access_path().head().is_persistent()
            || parent_components.access_path().head().stamp() == 0
        {
            Path::pdot(
                *parent_components.access_path(),
                child_name.to_string(),
            )
        } else {
            Path::pdot_pos(
                *parent_components.access_path(),
                child_name.to_string(),
                runtime_pos as i32,
            )
        };
        let pos = step_pos(&access_path);
        ctx.register_resolved_child_module_path(
            parent_components.access_path(),
            child_name,
            access_path,
        );
        return stored.with_components(pers_env, ctx, cache_mode, |components| {
            (f.take()
                .expect("qualified child module components callback reused"))(pos, components)
        });
    }

    let (runtime_pos, _, md) = parent_components.lookup_qualified_module(child_name, ctx)?;
    let access_path = qualified_submodule_access_path(
        parent_components.access_path(),
        child_name,
        runtime_pos,
        &md,
    );
    ctx.register_resolved_child_module_path(
        parent_components.access_path(),
        child_name,
        access_path,
    );

    let pos = step_pos(&access_path);
    let module_key = module_components_cache_key(&access_path, env);
    if let Some(module_key) = module_key.as_ref() {
        if let Some(result) = ctx.with_qualified_module_components(module_key, |components| {
            (f.take()
                .expect("qualified child module components callback reused"))(pos, components)
        }) {
            return Some(result);
        }
    }

    let components = match md.md_type {
        crate::types::decl::ModuleType::MtySignature(sig) => {
            crate::types::env_lazy::QualifiedModuleComponents::new(
                access_path,
                std::sync::Arc::unwrap_or_clone(sig),
                ctx,
            )
        }
        _ => {
            let sig = build_qualified_signature_for_access_path(
                env,
                &access_path,
                &md.md_type,
                pers_env,
                ctx,
                cache_mode,
            )?;
            crate::types::env_lazy::QualifiedModuleComponents::new(access_path, sig, ctx)
        }
    };
    let result = (f
        .take()
        .expect("qualified child module components callback reused"))(
        pos,
        crate::types::env_lazy::Components::Local(&components),
    );
    if let Some(module_key) = module_key {
        ctx.register_qualified_module_components(module_key, components);
    }
    Some(result)
}

/// OCaml `IdTbl.find_name ~mark:true` (env.ml:292-312) for an unqualified
/// source name: call the `using` callback of the opened layer it resolves to.
pub(crate) fn mark_open_name_use(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    kind: crate::types::env::OpenLookupKind,
    name: impl crate::name::NameKey,
) {
    if let Some(slot_use) = env.open_slot_use(kind, name) {
        ctx.record_open_slot_use(slot_use.slot, kind.shadow_kind(), name.text(), slot_use.shadowed);
    }
}

/// The `find_name` marking of `Env.lookup`/`lookup_module` for a source
/// longident (env.ml:1000-1014, 1036-1074): the name itself when
/// unqualified, else the head module through `lookup_module_descr`. The
/// `*predef*` prefix is looked up in the initial environment
/// (typetexp.ml:87-91), which has no opens.
pub(crate) fn mark_open_lid_use(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    arena: &ParseArena,
    lid: &Longident,
    kind: crate::types::env::OpenLookupKind,
    loc: Option<LocIdx>,
) {
    // `Env.lookup_module` marks the module itself; every other lookup marks
    // the modules of its prefix through `lookup_module_descr`. Both report
    // deprecated modules along the way when the lookup carries `?loc`.
    let predef = matches!(
        lid,
        Longident::Ldot(prefix, _)
            if matches!(prefix.as_ref(), Longident::Lident(head) if arena.get_string(*head) == "*predef*")
    );
    let mut deprecations = Vec::new();
    let mut report = match loc {
        Some(loc) if !predef => Some((loc, &mut deprecations)),
        _ => None,
    };
    match (lid, kind) {
        (_, crate::types::env::OpenLookupKind::Module) => {
            mark_module_lid_used(ctx, env, arena, lid, &mut report);
        }
        (Longident::Ldot(prefix, _), _) => {
            mark_module_lid_used(ctx, env, arena, prefix, &mut report);
        }
        _ => {}
    }
    mark_open_lid_use_inner(ctx, env, arena, lid, kind);
    // The opened-layer `using` call of the head happens while the head is
    // found (env.ml:1000-1004), before `report_deprecated`.
    for deprecation in deprecations {
        ctx.record_module_deprecation(deprecation);
    }
}

/// Where the lookup of a module longident has arrived.
enum ModuleLidTarget {
    /// A module declaration of the lookup environment. `name` is the path
    /// whose `Path.name` reports it.
    Local {
        name: Path,
        md_type: crate::types::decl::ModuleType,
    },
    /// A module inside a persistent unit: `target` is rooted at the unit's
    /// persistent identifier (see [`persistent_path_components`]).
    Persistent { name: Path, target: Path },
}

type ModuleDeprecationReport<'r> = Option<(
    LocIdx,
    &'r mut Vec<crate::types::context::ModuleDeprecation>,
)>;

/// The `mark_module_used` and `report_deprecated` calls of
/// `Env.lookup_module_descr` and `Env.lookup_module` (env.ml:989-1074) along
/// a module longident: each component is marked with the location of its
/// declaration (`comps.loc`, the `md_loc` the components were built from),
/// and reported when its components are deprecated.
fn mark_module_lid_used(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    arena: &ParseArena,
    lid: &Longident,
    report: &mut ModuleDeprecationReport<'_>,
) -> Option<ModuleLidTarget> {
    use crate::types::context::ModuleDeprecation;
    let (name, path_name, md) = match lid {
        Longident::Lident(idx) => {
            let name = arena.get_string(*idx);
            match env.find_module_with_path(arena.name(*idx)) {
                Ok((path, md)) => (name, path, std::borrow::Cow::Borrowed(md)),
                // `find_pers_struct s` then `ps.ps_comps.deprecated`
                // (env.ml:1043-1048).
                Err(_) => {
                    let unit = Path::pident(crate::ident::Ident::create_persistent(
                        arena.name(*idx),
                    ));
                    return Some(persistent_module_target(report, unit, unit));
                }
            }
        }
        Longident::Ldot(prefix, idx) => {
            let parent = mark_module_lid_used(ctx, env, arena, prefix, report)?;
            let name = arena.get_string(*idx);
            match parent {
                ModuleLidTarget::Local {
                    name: parent_name,
                    md_type,
                } => {
                    let path_name = Path::pdot(parent_name, arena.name(*idx));
                    match submodule_declaration(env, &md_type, name, 0) {
                        Some(md) => (name, path_name, std::borrow::Cow::Owned(md)),
                        None => {
                            let target = local_module_type_persistent_target(env, &md_type, 0)?;
                            return Some(persistent_module_target(
                                report,
                                path_name,
                                Path::pdot(target, arena.name(*idx)),
                            ));
                        }
                    }
                }
                ModuleLidTarget::Persistent {
                    name: parent_name,
                    target,
                } => {
                    return Some(persistent_module_target(
                        report,
                        Path::pdot(parent_name, arena.name(*idx)),
                        Path::pdot(target, arena.name(*idx)),
                    ));
                }
            }
        }
        Longident::Lapply(_, _) => return None,
    };
    if !env.is_implicit_coercion() {
        ctx.usage()
            .mark_module_used(name, ctx.resolve_loc(md.md_loc));
    }
    if let Some((loc, deprecations)) = report.as_mut()
        // `Env.store_module` (env.ml:1649) read this payload when the
        // module entered the environment, raising there on an invalid escape.
        && let Some(deprecated) = deprecated_of_decl_attrs(&md.md_attributes)
            .expect("the module's definition read its deprecated payload")
    {
        deprecations.push(ModuleDeprecation::Resolved {
            loc: *loc,
            name: path_name.name(),
            deprecated,
        });
    }
    Some(ModuleLidTarget::Local {
        name: path_name,
        md_type: match md {
            std::borrow::Cow::Borrowed(md) => md.md_type.clone(),
            std::borrow::Cow::Owned(md) => md.md_type,
        },
    })
}

/// A module inside a persistent unit; its deprecation is resolved once the
/// lookup has loaded the unit.
fn persistent_module_target(
    report: &mut ModuleDeprecationReport<'_>,
    name: Path,
    target: Path,
) -> ModuleLidTarget {
    if let Some((loc, deprecations)) = report.as_mut() {
        deprecations.push(crate::types::context::ModuleDeprecation::Persistent {
            loc: *loc,
            name,
            target,
        });
    }
    ModuleLidTarget::Persistent { name, target }
}

/// The persistent module a local module type is an alias of, through local
/// module type and alias indirections.
fn local_module_type_persistent_target(
    env: &Env,
    mty: &crate::types::decl::ModuleType,
    depth: usize,
) -> Option<Path> {
    use crate::types::decl::ModuleType;
    if depth > 32 {
        return None;
    }
    match mty {
        ModuleType::MtyIdent(path) => {
            let mty = env.lookup_modtype(path).ok()?.mtd_type.clone()?;
            local_module_type_persistent_target(env, &mty, depth + 1)
        }
        ModuleType::MtyAlias(_, path) => match persistent_path_components(path) {
            Some(_) => Some(**path),
            None => {
                let mty = env.lookup_module(path).ok()?.md_type.clone();
                local_module_type_persistent_target(env, &mty, depth + 1)
            }
        },
        _ => None,
    }
}

/// The declaration of submodule `name` in the components of a local module
/// type (`components_of_module_maker`, env.ml:1516-1578).
fn submodule_declaration(
    env: &Env,
    mty: &crate::types::decl::ModuleType,
    name: &str,
    depth: usize,
) -> Option<crate::types::decl::ModuleDeclaration> {
    use crate::types::decl::{ModuleType, SignatureItem};
    if depth > 32 {
        return None;
    }
    match mty {
        ModuleType::MtySignature(items) => items.iter().rev().find_map(|item| match item {
            SignatureItem::SigModule(id, md, _) if id.name() == name => Some(md.clone()),
            _ => None,
        }),
        ModuleType::MtyIdent(path) => {
            let decl = env.lookup_modtype(path).ok()?;
            let mty = decl.mtd_type.clone()?;
            submodule_declaration(env, &mty, name, depth + 1)
        }
        ModuleType::MtyAlias(_, path) => {
            let md = env.lookup_module(path).ok()?;
            let mty = md.md_type.clone();
            submodule_declaration(env, &mty, name, depth + 1)
        }
        _ => None,
    }
}

fn mark_open_lid_use_inner(
    ctx: &crate::types::context::TypeContext,
    env: &Env,
    arena: &ParseArena,
    lid: &Longident,
    kind: crate::types::env::OpenLookupKind,
) {
    match lid {
        Longident::Lident(idx) => mark_open_name_use(ctx, env, kind, arena.name(*idx)),
        Longident::Ldot(prefix, _) => {
            if let Longident::Lident(head) = prefix.as_ref()
                && arena.get_string(*head) == "*predef*"
            {
                return;
            }
            mark_open_lid_use_inner(
                ctx,
                env,
                arena,
                prefix,
                crate::types::env::OpenLookupKind::Component,
            );
        }
        Longident::Lapply(_, _) => {}
    }
}

/// How [`with_resolved_module_components_for_lid_inner`] looks up the
/// components of a longident.
#[derive(Clone, Copy)]
struct LidComponentLookup {
    /// Which OCaml lookup the components are read through.
    api: ComponentLookupApi,
    /// Whether to build the path the lookup returns for the callback.
    with_path: bool,
}

/// `Env.lookup_module_descr` (compiler/ml/env.ml:966-978): the components
/// a longident names. With `with_path`, `f` also gets the path the lookup
/// builds: for the root, the path `find_name` returns from the environment
/// (`Pident id`, or `Pdot (root, s, pos)` through an open, env.ml:284-301),
/// or else `Pident (Ident.create_persistent s)`; then `Pdot (p, s, pos)` per
/// step, named by the longident's strings. The components keep their own
/// access paths.
fn with_resolved_module_components_for_lid_inner<'a, R>(
    lid: &Longident,
    arena: &ParseArena,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
    mode: LidComponentLookup,
    f: &mut dyn FnMut(
        Option<&Path>,
        crate::types::env_lazy::Components<'_>,
    ) -> Option<R>,
) -> Option<R> {
    let LidComponentLookup {
        api,
        with_path: lookup,
    } = mode;
    match lid {
        Longident::Lident(mod_idx) => {
            let mod_name = arena.name(*mod_idx);
            let (module_path, lookup_path) = if let Ok((module_path, _)) =
                env.find_module_with_path(mod_name)
            {
                let lookup_path = lookup.then_some(module_path);
                if let PathView::Pident(mod_id) = module_path.view() {
                    let pident_path = Path::pident(*mod_id);
                    if let Some(result) = env
                        .with_local_module_components(&pident_path, |stored| {
                            stored.with_components(pers_env, ctx, api, |components| {
                                f(lookup_path.as_ref(), components)
                            })
                        })
                        .flatten()
                        .flatten()
                    {
                        return Some(result);
                    }
                }
                (module_path, lookup_path)
            } else {
                (
                    Path::pident(Ident::create_persistent(mod_name)),
                    lookup.then(|| Path::pident(ctx.create_ast_persistent_ident(arena, *mod_idx))),
                )
            };
            with_resolved_module_components_for_path_with_cache_mode(
                &module_path,
                env,
                pers_env,
                ctx,
                api,
                |components| f(lookup_path.as_ref(), components),
            )
            .flatten()
        }
        Longident::Ldot(prefix, child_idx) => {
            let child_name = arena.get_string(*child_idx).to_string();
            // OCaml compiler/ml/env.ml:1000-1014 `lookup_module_descr_aux`
            // resolves a dotted prefix by recursively getting the parent
            // descriptor, then forcing that descriptor's `comp_components`.
            // Constructor lookup reaches this through
            // compiler/ml/typetexp.ml:127-131 and env.ml:1091-1120, so a
            // cached child access path is not enough: the child component
            // thunk must be forced in the same order as OCaml.
            let (parent_path, parent_components) = with_resolved_module_components_for_lid_inner(
                prefix,
                arena,
                env,
                pers_env,
                ctx,
                mode,
                &mut |path, components| Some((path.cloned(), components.to_held())),
            )?;
            with_resolved_child_module_components(
                parent_components.components(),
                child_name.as_str(),
                env,
                pers_env,
                ctx,
                api,
                |pos, components| {
                    let path = parent_path
                        .map(|parent| ctx.create_ast_dotted(arena, parent, *child_idx, pos));
                    f(path.as_ref(), components)
                },
            )
            .flatten()
        }
        Longident::Lapply(_, _) => None,
    }
}

/// [`with_resolved_module_components_for_lid`] that also gives `f` the path
/// `Env.lookup_module_descr` returns for `lid`.
pub(crate) fn with_module_descr_for_lid<R>(
    lid: &Longident,
    arena: &ParseArena,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    f: impl FnOnce(&Path, crate::types::env_lazy::Components<'_>) -> R,
) -> Option<R> {
    let mut f = Some(f);
    let mut wrapper = |path: Option<&Path>,
                       components: crate::types::env_lazy::Components<'_>| {
        Some((f.take().expect("module descriptor callback reused"))(
            path.expect("lookup path requested"),
            components,
        ))
    };
    with_resolved_module_components_for_lid_inner(
        lid,
        arena,
        env,
        pers_env,
        ctx,
        LidComponentLookup {
            api: ComponentLookupApi::FindModuleDescr,
            with_path: true,
        },
        &mut wrapper,
    )
}

pub(crate) fn with_resolved_module_components_for_lid<R>(
    lid: &Longident,
    arena: &ParseArena,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    f: impl FnOnce(crate::types::env_lazy::Components<'_>) -> R,
) -> Option<R> {
    let mut f = Some(f);
    let mut wrapper =
        |_: Option<&Path>, components: crate::types::env_lazy::Components<'_>| {
            Some((f.take().expect(
                "qualified module components by lid callback reused",
            ))(components))
        };
    with_resolved_module_components_for_lid_inner(
        lid,
        arena,
        env,
        pers_env,
        ctx,
        LidComponentLookup {
            api: ComponentLookupApi::FindModuleDescr,
            with_path: false,
        },
        &mut wrapper,
    )
}

pub(crate) fn open_module_lid_components_into_env(
    lid: &Longident,
    arena: &ParseArena,
    lookup_env: &Env,
    target_env: &mut Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    slot: Option<u32>,
) -> Option<Path> {
    // OCaml compiler/ml/typemod.ml:88-90 and typecore.ml open modules through
    // `Env.open_signature`, which in compiler/ml/env.ml:1874-1877 forces the
    // selected module descriptor's component table and then env.ml:1841-1860
    // installs both `comp_modules` and `comp_components`. Keep Rust opens on the
    // same component-view path rather than rebuilding from a detached signature.
    if let Longident::Lident(mod_idx) = lid {
        let mod_name = arena.get_string(*mod_idx);
        if let Ok((selected_path, _)) = lookup_env.find_module_with_path(mod_name)
            && let PathView::Pdot(parent, child_name, _) = selected_path.view()
        {
            // OCaml compiler/ml/typetexp.ml:144-151 calls
            // compiler/ml/env.ml:1036-1055 `lookup_module` before
            // `Env.open_signature`. For an unqualified module selected from an
            // opened layer, env.ml:1040-1043 forces the `comp_modules`
            // declaration thunk with `EnvLazy.force subst_modtype_maker`; if
            // that module type is a signature, compiler/ml/subst.ml:351-364
            // freshens its bound identifiers before env.ml:1874-1877 opens the
            // separate `comp_components` thunk. Preserve that force order here;
            // dotted opens stay on the descriptor path below, matching
            // env.ml:1064-1073.
            let _ = with_resolved_module_components_for_path_with_cache_mode(
                parent,
                lookup_env,
                pers_env,
                ctx,
                ComponentLookupApi::LookupModule,
                |components| components.lookup_qualified_module(child_name.as_str(), ctx),
            );
        }
    }
    // The open's root is the path `Env.lookup_module` builds for `lid`.
    let mut wrapper =
        |path: Option<&Path>, components: crate::types::env_lazy::Components<'_>| {
            let path = *path.expect("lookup path requested");
            crate::cmi::persistent_env::open_module_components_into_env(
                components, path, target_env, ctx, slot,
            );
            Some(path)
        };
    with_resolved_module_components_for_lid_inner(
        lid,
        arena,
        lookup_env,
        pers_env,
        ctx,
        LidComponentLookup {
            api: ComponentLookupApi::OpenSignature,
            with_path: true,
        },
        &mut wrapper,
    )
}

fn build_module_components_from_parent_path(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<crate::types::env_lazy::QualifiedModuleComponents> {
    let PathView::Pdot(parent, module_name, _) = module_path.view() else {
        return None;
    };

    // OCaml compiler/ml/env.ml:1516-1518 always calls scrape_alias while
    // building module components; env.ml:1440-1442 resolves Mty_alias through
    // find_module, independent of typedtree output mode.
    if ctx.persistent_env_is_in_process()
        && let Some(Some((runtime_pos, alias_target, parent_access_path))) =
            with_resolved_module_components_for_path_with_cache_mode(
                parent,
                env,
                pers_env,
                ctx,
                cache_mode,
                |components| {
                    components.lookup_module(module_name.as_str()).and_then(
                        |(runtime_pos, _, md)| match md
                            .md_type
                            .ident_or_alias_path()
                            .map(|p| p.view())
                        {
                            Some(PathView::Pident(alias_id)) if alias_id.is_persistent() => Some((
                                runtime_pos,
                                alias_id.name().to_string(),
                                *components.access_path(),
                            )),
                            _ => None,
                        },
                    )
                },
            )
    {
        let pers = pers_env.as_mut()?;
        if let Some(ps) = pers.find_pers_struct(&alias_target, ctx) {
            // env.ml:1440-1442 `scrape_alias` reaches `find_module`, whose
            // persistent branch (env.ml:872-875) forces `ps_sig`, freshening
            // the unit's bound identifiers. The view below shares the
            // unrenamed signature, so take the rename's stamps here.
            ctx.trigger_module_sig_rename(&alias_target);
            let source_prefix = Path::pident(Ident::create_persistent(&alias_target));
            let access_path =
                Path::pdot_pos(parent_access_path, module_name.as_str(), runtime_pos as i32);
            return Some(
                crate::types::env_lazy::QualifiedModuleComponents::new_with_child_components_arc_and_value_source_prefix(
                    access_path,
                    ps.ps_sig.clone(),
                    HashMap::new(),
                    Some(source_prefix),
                    ctx,
                ),
            );
        }
    }

    if let Some(Some((_, stored))) = with_resolved_module_components_for_path_with_cache_mode(
        parent,
        env,
        pers_env,
        ctx,
        cache_mode,
        |components| components.lookup_child_components(module_name.as_str(), ctx),
    ) {
        // Reached for a key no world view answers (one scoped to an
        // environment, or a view the pool had no room for): the tables are
        // built for this compilation.
        if let Some(components) =
            stored.with_local_components(pers_env, ctx, cache_mode, |child| child.clone())
        {
            return Some(components);
        }
    }

    // OCaml compiler/ml/env.ml:1568 stores `comp_modules` as a lazy
    // `Subst.modtype` thunk, while env.ml:1573-1578 stores
    // `comp_components` as a separate child-component thunk. Building a
    // child's component table from the raw module entry keeps navigation like
    // `Belt.Array` from forcing the parent module-declaration thunk and
    // freshening sibling module binders before OCaml does.
    if let Some(Some((access_path, md, parent_access_path, parent_sig))) =
        with_resolved_module_components_for_path_with_cache_mode(
            parent,
            env,
            pers_env,
            ctx,
            cache_mode,
            |components| {
                components
                    .lookup_module(module_name.as_str())
                    .map(|(runtime_pos, _, md)| {
                        let access_path = qualified_submodule_access_path(
                            components.access_path(),
                            module_name.as_str(),
                            runtime_pos,
                            md,
                        );
                        (
                            access_path,
                            md.clone(),
                            *components.access_path(),
                            components.signature_arc(),
                        )
                    })
            },
        )
    {
        let stored = crate::types::env_lazy::StoredModuleComponents::new_with_parent_context(
            env.clone(),
            access_path,
            md,
            Some((parent_access_path, parent_sig)),
        );
        if let Some(components) =
            stored.with_local_components(pers_env, ctx, cache_mode, |child| child.clone())
        {
            return Some(components);
        }
    }

    with_resolved_module_components_for_path_with_cache_mode(
        parent,
        env,
        pers_env,
        ctx,
        cache_mode,
        |components| {
            let (runtime_pos, _, md) =
                components.lookup_qualified_module(module_name.as_str(), ctx)?;
            let access_path = qualified_submodule_access_path(
                components.access_path(),
                module_name.as_str(),
                runtime_pos,
                &md,
            );
            match md.md_type {
                crate::types::decl::ModuleType::MtySignature(sig) => {
                    Some(crate::types::env_lazy::QualifiedModuleComponents::new(
                        access_path,
                        std::sync::Arc::unwrap_or_clone(sig),
                        ctx,
                    ))
                }
                _ => None,
            }
        },
    )
    .flatten()
}

fn build_functor_application_components(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<crate::types::env_lazy::QualifiedModuleComponents> {
    let PathView::Papply(functor_path, arg_path) = module_path.view() else {
        return None;
    };

    let applied_mty = match functor_path.view() {
        PathView::Pident(_) => {
            let stored = env.local_module_components_shared(functor_path)?;
            stored.instantiate_functor_result_for_application(arg_path, ctx)?
        }
        PathView::Pdot(parent, module_name, _) => {
            // OCaml compiler/ml/env.ml:781-793 resolves the functor path with
            // `find_module_descr`, and env.ml:1744-1756 then runs
            // `components_of_functor_appl`. This must use the child
            // `comp_components` thunk, not the module-declaration thunk from
            // env.ml:1568, because env.ml:1595-1602 freshens only the functor
            // argument/result module types at this point.
            let stored = with_resolved_module_components_for_path_with_cache_mode(
                parent,
                env,
                pers_env,
                ctx,
                cache_mode,
                |components| {
                    components
                        .lookup_child_components(module_name.as_str(), ctx)
                        .map(|(_, stored)| stored)
                },
            )
            .flatten()?;
            stored.instantiate_functor_result_for_application(arg_path, ctx)?
        }
        PathView::Papply(_, _) => return None,
    };

    let (raw_sig, resolved_name) = match &applied_mty {
        crate::types::decl::ModuleType::MtySignature(sig) => ((**sig).clone(), None),
        _ => env.resolve_module_type(&applied_mty, pers_env, ctx, cache_mode)?,
    };
    let sig = qualify_resolved_signature_for_local_components(
        module_path,
        &applied_mty,
        &raw_sig,
        resolved_name.as_deref(),
        pers_env,
        ctx,
    );
    Some(crate::types::env_lazy::QualifiedModuleComponents::new(
        *module_path,
        sig,
        ctx,
    ))
}

fn flattened_alias_component_parent(
    parent: &Path,
    pers_env: Option<&crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> bool {
    // OCaml compiler/ml/env.ml:1440-1446 only scrapes explicit aliases.
    // Skip the eager child lookup above only for component parents whose
    // flattened backing relation was registered from that alias scrape, not
    // from the spelling of the persistent head.
    let head = parent.head();
    if !head.is_persistent() {
        return false;
    }

    let source_path = Path::pident(*head);
    pers_env
        .and_then(|pers| pers.qualified_alias_path_for_flattened_head(head.name()))
        .is_some()
        || ctx.has_component_paths_for_alias_source(&source_path)
}

/// The world's view of unit `ps`, adopted by this compilation under `key`
/// (see `TypeContext::adopt_view`); `None` when the world does not own the
/// unit. One load of the unit's view cell when the view is built already.
pub(crate) fn adopt_unit_view(
    ps: &std::sync::Arc<crate::cmi::persistent_env::PersStruct>,
    key: crate::types::context::QualifiedModuleComponentsCacheKey,
    ctx: &crate::types::context::TypeContext,
) -> Option<std::sync::Arc<crate::types::module_view::ModuleView>> {
    use crate::types::module_view::{ViewKey, verify_view, world_verify_enabled};
    let world = ctx.world();
    let view_key = ViewKey::Unit(ps);
    let view = world.views().get_or_build(world, &view_key)?;
    if world_verify_enabled() {
        verify_view(world, &view_key, &view);
    }
    ctx.adopt_view(key, view.clone());
    Some(view)
}

/// The world's view of `module_path` when it is the path of a unit.
///
/// Which kind of key a path is, is a fact of the path and the world: a
/// persistent identifier names a unit, and a unit's components are its own
/// (`ps_comps`, compiler/ml/env.ml:669-678, 1000-1007), whether or not the
/// asking compilation has met a module alias of the unit. Loads the unit as
/// any lookup of it does; a lookup that carries no persistent environment
/// (type expansion) reads the unit through the compilation's own, as its
/// raw signature was read before.
///
/// Cost: the unit lookup (one probe of the compilation's unit cache when it
/// is loaded) and one load of the unit's view cell.
fn adopt_persistent_root_view(
    module_path: &Path,
    key: &crate::types::context::QualifiedModuleComponentsCacheKey,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<std::sync::Arc<crate::types::module_view::ModuleView>> {
    if !ctx.persistent_env_is_in_process() {
        return None;
    }
    let name = crate::types::module_view::unit_key_name(module_path)?;
    let ps = match pers_env.as_mut() {
        Some(pers) => {
            if !pers.unit_visible(name) {
                return None;
            }
            pers.find_pers_struct(name, ctx)?
        }
        None => {
            let mut pers = ctx.persistent_env_clone()?;
            if !pers.unit_visible(name) {
                return None;
            }
            pers.find_pers_struct(name, ctx)?
        }
    };
    adopt_unit_view(&ps, key.clone(), ctx)
}

/// The world's view of child `ordinal` of `parent`, a child whose path is a
/// view key (`ModuleView::world_child_kind`), adopted by this compilation;
/// `None` when the pool had no room for it, and for an alias of a unit
/// this compilation cannot load or the world does not own.
///
/// Adopting the view of an alias of a unit loads the unit and takes its
/// signature's rename, as building the alias's tables did
/// (env.ml:1440-1442 `scrape_alias` reaches `find_module`, env.ml:872-875).
///
/// Cost, when the view is built and adopted already: one load of the
/// child's cell and one probe of the compilation's component cache.
pub(crate) fn adopt_child_view(
    parent: &std::sync::Arc<crate::types::module_view::ModuleView>,
    ordinal: u32,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<std::sync::Arc<crate::types::module_view::ModuleView>> {
    use crate::types::module_view::{AliasKey, ViewKey, WorldChild, verify_view, world_verify_enabled};
    let key_of = |view: &crate::types::module_view::ModuleView| {
        crate::types::context::QualifiedModuleComponentsCacheKey::new(*view.access_path(), None)
    };
    if let Some(view) = parent.built_child(ordinal)
        && ctx.holds_view(&key_of(view), view)
    {
        return Some(view.clone());
    }
    let world = ctx.world();
    let adopt = |view_key: ViewKey<'_>| {
        let view = world.views().get_or_build(world, &view_key)?;
        if world_verify_enabled() {
            verify_view(world, &view_key, &view);
        }
        Some(view)
    };
    let view = match parent.world_child_kind(ordinal)? {
        WorldChild::Structure => adopt(ViewKey::Child(parent, ordinal))?,
        WorldChild::UnitAlias(name) => {
            let unit = pers_env.as_mut()?.find_pers_struct(name, ctx)?;
            unit.ps_view.get()?;
            ctx.trigger_module_sig_rename(name);
            let view = adopt(ViewKey::Alias(&AliasKey {
                parent,
                ordinal,
                unit: &unit,
            }))?;
            // The cell holds the view of the unit the first compilation
            // loaded under this name; one that loads another builds its own
            // tables.
            if !view.is_alias_of(&unit) {
                return None;
            }
            view
        }
    };
    ctx.adopt_view(key_of(&view), view.clone());
    Some(view)
}

/// The world's view of `module_path` when it is a child path whose parent
/// has a world view and the child's path is a view key. Resolves the parent
/// as any lookup of the child does.
///
/// Cost: the lookup of the parent's components, one probe of the parent's
/// name index, and [`adopt_child_view`].
fn adopt_world_child_view(
    module_path: &Path,
    key: &crate::types::context::QualifiedModuleComponentsCacheKey,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<std::sync::Arc<crate::types::module_view::ModuleView>> {
    if !ctx.persistent_env_is_in_process() || !key.is_worker_shareable() {
        return None;
    }
    let PathView::Pdot(parent, name, _) = module_path.view() else {
        return None;
    };
    let (parent, ordinal) = with_resolved_module_components_for_path_with_cache_mode(
        parent,
        env,
        pers_env,
        ctx,
        cache_mode,
        |components| match components {
            crate::types::env_lazy::Components::World(view) => view
                .world_child(name.as_str())
                .map(|(ordinal, _)| (view.clone(), ordinal)),
            crate::types::env_lazy::Components::Local(_) => None,
        },
    )??;
    adopt_child_view(&parent, ordinal, pers_env, ctx)
}

/// The components of a unit only this compilation holds (the world owns no
/// copy of it): built for this compilation, like any other local path.
fn build_private_unit_components(
    module_path: &Path,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<crate::types::env_lazy::QualifiedModuleComponents> {
    if !ctx.persistent_env_is_in_process() {
        return None;
    }

    let PathView::Pident(id) = module_path.view() else {
        return None;
    };
    if !id.is_persistent() {
        return None;
    }

    let pers = pers_env.as_mut()?;
    let ps = pers.find_pers_struct(id.name(), ctx)?;
    let access_path = Path::pident(Ident::create_persistent(id.name()));
    Some(
        crate::types::env_lazy::QualifiedModuleComponents::new_with_child_components_arc(
            access_path,
            ps.ps_sig.clone(),
            HashMap::new(),
            ctx,
        ),
    )
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ComponentLookupApi {
    /// OCaml `Env.find_module`, `env.ml:865-882`: force the selected
    /// `comp_modules` declaration and build any alias component table normally.
    FindModule,
    /// OCaml `Env.lookup_module`, `env.ml:1036-1074`: source longident lookup.
    LookupModule,
    /// OCaml `Env.find_module_descr`, `env.ml:781-793`: read component
    /// descriptors through `get_components`.
    FindModuleDescr,
    /// OCaml `Env.find_type` / `Env.lookup_type`, `env.ml:800-813` and
    /// `env.ml:1091-1145`: read `comp_types` from component tables.
    FindType,
    /// OCaml `Env.find_modtype` / `Env.lookup_modtype`, `env.ml:800-815` and
    /// `env.ml:1091-1145`: read `comp_modtypes` from component tables.
    FindModtype,
    /// OCaml `Env.open_signature`, `env.ml:1874-1877`: open the selected
    /// descriptor's component table into another environment.
    OpenSignature,
}

pub(crate) fn with_resolved_module_components_for_path_with_cache_mode<R>(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
    f: impl FnOnce(crate::types::env_lazy::Components<'_>) -> R,
) -> Option<R> {
    // OCaml compiler/ml/env.ml:781-788 path-based `Pident` lookup is exact
    // (`IdTbl.find_same`). Source `Longident.Lident` name lookup is handled
    // before paths reach this helper (compiler/ml/env.ml:1000-1007), so
    // persistent type paths from imported signatures stay independent from
    // local/opened same-name modules: `module_path` is used as given.
    let mut f = Some(f);
    let module_key = module_components_cache_key(module_path, env);
    if let Some(result) = env
        .with_local_module_components(module_path, |stored| {
            stored.with_components(pers_env, ctx, cache_mode, |components| {
                (f.take()
                    .expect("qualified module components callback reused"))(components)
            })
        })
        .flatten()
    {
        return Some(result);
    }

    // Outside a store build, this compilation's own cache answers first; the
    // shared-view checks below are only needed on a miss.
    if !ctx.in_store_build()
        && let Some(module_key) = module_key.as_ref()
        && let Some(result) = ctx.with_qualified_module_components(module_key, |components| {
            (f.take()
                .expect("qualified module components callback reused"))(components)
        })
    {
        return Some(result);
    }

    // The view of a unit's own path is the same for every compilation
    // (OCaml builds `ps_comps` from `Env.empty`, compiler/ml/env.ml:669-678):
    // the world holds it, built once per build.
    if let Some(module_key) = module_key.as_ref()
        && let Some(view) = adopt_persistent_root_view(module_path, module_key, pers_env, ctx)
    {
        return Some((f
            .take()
            .expect("qualified module components callback reused"))(
            crate::types::env_lazy::Components::World(&view),
        ));
    }

    // So is the view of a child that a world view declares with a
    // signature (env.ml:1573-1578) or as an alias of a unit
    // (env.ml:1516-1518): it is the parent's, built once.
    if let Some(module_key) = module_key.as_ref()
        && let Some(view) =
            adopt_world_child_view(module_path, module_key, env, pers_env, ctx, cache_mode)
    {
        return Some((f
            .take()
            .expect("qualified module components callback reused"))(
            crate::types::env_lazy::Components::World(&view),
        ));
    }

    // Any other persistent-rooted view is the same for every compilation
    // too; it is built once per worker as a store build and shared.
    let shared_key = module_key
        .as_ref()
        .filter(|key| {
            ctx.persistent_env_is_in_process()
                && key.is_worker_shareable()
                && shared_components_enabled()
                // The worker's shared view was built by a compilation that
                // could see the root unit; one that cannot (a package that
                // does not depend on it) must not reach it through the view.
                && pers_env
                    .as_ref()
                    .is_none_or(|pers| pers.unit_visible(module_path.head().name()))
        })
        .cloned();
    if ctx.in_store_build()
        && shared_key.is_none()
        && let Some(module_key) = module_key.as_ref()
        && let Some(result) = ctx.with_qualified_module_components(module_key, |components| {
            (f.take()
                .expect("qualified module components callback reused"))(components)
        })
    {
        // A store build must not read this compilation's cache when the
        // shared cache below answers for the same key.
        return Some(result);
    }
    if let Some(shared_key) = shared_key.as_ref()
        && let Some((components, piece)) = ctx.thread_store().shared_components(shared_key)
        && (ctx.store_guards_hold(&piece) || {
            if crate::types::context::store_debug_enabled() {
                eprintln!("[store-guard-miss] {}", module_path.name());
            }
            if ctx.compiler_counters_enabled() {
                crate::perf_counters::store_views::record_view_guard_miss();
            }
            false
        })
    {
        if crate::types::context::store_debug_enabled() {
            eprintln!("[store-hit] {}", module_path.name());
        }
        if ctx.compiler_counters_enabled() {
            crate::perf_counters::store_views::record_view_hit();
        }
        ctx.touch_store_piece(&piece);
        let result =
            (f.take()
                .expect("qualified module components callback reused"))(
                crate::types::env_lazy::Components::Local(&components),
            );
        ctx.register_qualified_module_components_shared(shared_key.clone(), components);
        return Some(result);
    }

    let build = |pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>| {
        build_module_components_from_parent_path(module_path, env, pers_env, ctx, cache_mode)
            .or_else(|| {
                build_functor_application_components(module_path, env, pers_env, ctx, cache_mode)
            })
            .or_else(|| build_private_unit_components(module_path, pers_env, ctx))
            .or_else(|| {
                let (access_path, sig) =
                    build_module_signature_for_path(module_path, env, pers_env, ctx, cache_mode)?;
                Some(crate::types::env_lazy::QualifiedModuleComponents::new(
                    access_path,
                    sig,
                    ctx,
                ))
            })
    };
    let (components, piece) = if shared_key.is_some() {
        ctx.build_in_store_guarded(|| build(pers_env))
    } else {
        (build(pers_env), None)
    };
    let components = Rc::new(components?);
    if ctx.compiler_counters_enabled()
        && (matches!(module_path.view(), PathView::Papply(..)) || module_path.has_apply_prefix())
    {
        crate::perf_counters::world::record_papply_view_build();
    }
    if shared_key.is_some() && piece.is_none() {
        components.make_private();
    }
    let result = (f
        .take()
        .expect("qualified module components callback reused"))(
                crate::types::env_lazy::Components::Local(&components),
            );
    if let Some(module_key) = module_key {
        if crate::types::context::store_debug_enabled() && shared_key.is_some() {
            eprintln!(
                "[store-build] {} published={}",
                module_path.name(),
                piece.is_some()
            );
        }
        if shared_key.is_some() && ctx.compiler_counters_enabled() {
            crate::perf_counters::store_views::record_view_build(
                module_path.name(),
                piece.is_some(),
            );
        }
        if let (Some(shared_key), Some(piece)) = (shared_key, piece) {
            ctx.thread_store()
                .publish_shared_components(shared_key, components.clone(), piece);
        }
        ctx.register_qualified_module_components_shared(module_key, components);
    }
    Some(result)
}

/// `RESCRIPT_NO_SHARED_COMPONENTS=1` disables worker-shared component views
/// (for A/B measurements and bisecting).
pub(crate) fn shared_components_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var_os("RESCRIPT_NO_SHARED_COMPONENTS").is_none())
}

pub(crate) fn with_resolved_module_components_for_path<R>(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    f: impl FnOnce(crate::types::env_lazy::Components<'_>) -> R,
) -> Option<R> {
    with_resolved_module_components_for_path_with_cache_mode(
        module_path,
        env,
        pers_env,
        ctx,
        ComponentLookupApi::FindModuleDescr,
        f,
    )
}

fn qualified_submodule_access_path(
    parent_access_path: &Path,
    module_name: &str,
    runtime_pos: usize,
    _md: &crate::types::decl::ModuleDeclaration,
) -> Path {
    if path_non_apply_root_is_persistent_or_global(parent_access_path) {
        // OCaml compiler/ml/env.ml:1454-1481 `prefix_idents` creates
        // component paths as `Pdot(root, name, pos)`, and env.ml:1568-1578
        // stores both module declarations and child components under that
        // prefixed path. The declaration's own `md_path` may name an alias
        // target, but it is not the selected path for a qualified lookup.
        Path::pdot_pos(
            *parent_access_path,
            module_name.to_string(),
            runtime_pos as i32,
        )
    } else {
        Path::pdot_pos(
            *parent_access_path,
            module_name.to_string(),
            runtime_pos as i32,
        )
    }
}

pub(crate) fn lookup_module_in_resolved_path(
    parent_module_path: &Path,
    module_name: &str,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, Path, crate::types::decl::ModuleDeclaration)> {
    with_resolved_module_components_for_path_with_cache_mode(
        parent_module_path,
        env,
        pers_env,
        ctx,
        ComponentLookupApi::FindModule,
        |components| {
            components
                .lookup_qualified_module(module_name, ctx)
                .map(|(runtime_pos, _, md)| {
                    let parent_access_path = *components.access_path();
                    let access_path = qualified_submodule_access_path(
                        &parent_access_path,
                        module_name,
                        runtime_pos,
                        &md,
                    );
                    (parent_access_path, access_path, md)
                })
        },
    )
    .flatten()
}

pub(crate) fn copy_resolved_module_signature_for_path(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, crate::types::decl::Signature)> {
    with_resolved_module_components_for_path_with_cache_mode(
        module_path,
        env,
        pers_env,
        ctx,
        ComponentLookupApi::FindModule,
        |components| {
            (
                *components.access_path(),
                copy_lookup_signature_for_subst(components.signature(), ctx),
            )
        },
    )
}

pub(crate) fn lookup_modtype_in_resolved_path(
    parent_module_path: &Path,
    modtype_name: &str,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, crate::types::decl::ModtypeDeclaration)> {
    with_resolved_module_components_for_path_with_cache_mode(
        parent_module_path,
        env,
        pers_env,
        ctx,
        ComponentLookupApi::FindModtype,
        |components| {
            components
                .lookup_qualified_modtype(modtype_name, ctx)
                .map(|(_, mtd)| (*components.access_path(), mtd))
        },
    )
    .flatten()
}

pub(crate) fn lookup_type_in_resolved_path(
    parent_module_path: &Path,
    type_name: &str,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, Ident, Arc<crate::types::decl::TypeDeclaration>)> {
    lookup_type_in_resolved_path_with_cache_mode(
        parent_module_path,
        type_name,
        env,
        pers_env,
        ctx,
        ComponentLookupApi::FindType,
    )
}

fn lookup_type_in_resolved_path_with_cache_mode(
    parent_module_path: &Path,
    type_name: &str,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<(Path, Ident, Arc<crate::types::decl::TypeDeclaration>)> {
    if let Some(cached) =
        ctx.find_resolved_module_type(env.scope_id(), parent_module_path, type_name)
    {
        return Some(cached);
    }

    if let PathView::Pident(id) = parent_module_path.view()
        && id.is_persistent()
    {
        let find_in_sig = |sig: &crate::types::decl::Signature| {
            sig.iter().find_map(|item| match item {
                crate::types::decl::SignatureItem::SigType(sig_id, sig_decl, _)
                    if sig_id.name() == type_name =>
                {
                    Some((*parent_module_path, *sig_id, sig_decl.clone()))
                }
                _ => None,
            })
        };
        let found = ctx
            .with_raw_module_sig(id.name(), find_in_sig)
            .flatten()
            .or_else(|| {
                pers_env
                    .as_mut()
                    .and_then(|pers| pers.find_pers_struct(id.name(), ctx))
                    .and_then(|ps| find_in_sig(ps.ps_sig.as_ref()))
            })
            .or_else(|| {
                let mut pers = ctx.persistent_env_clone()?;
                pers.find_pers_struct(id.name(), ctx)
                    .and_then(|ps| find_in_sig(ps.ps_sig.as_ref()))
            });
        if let Some(found) = found {
            // OCaml compiler/ml/env.ml:781-788 returns persistent `ps_comps` for
            // direct module-descriptor lookup, then env.ml:800-813 reads
            // `comp_types`. Rust's `find_pers_struct` path mirrors
            // env.ml:658-678 by loading/finalizing the persistent signature, but
            // scanning `SigType` here avoids constructing the broader
            // `QualifiedModuleComponents` view whose env.ml:1581-1585
            // modtype/module thunks would be forced only by later lookups. Do
            // not use the raw CMI reader here: OCaml's `ps_comps` is built from
            // the acknowledged persistent structure, not from an uncomponentized
            // CMI declaration.
            ctx.register_resolved_module_type(
                env.scope_id(),
                parent_module_path,
                type_name,
                found.0,
                found.1,
                found.2.clone(),
            );
            return Some(found);
        }
    }

    // OCaml compiler/ml/typetexp.ml:116-122 resolves source type
    // constructors through Env.lookup_type and then Env.find_type. Both that
    // source path and env.ml:800-813 read the parent module's component table
    // directly; they do not force a dotted alias target before selecting the
    // type entry.
    // OCaml compiler/ml/env.ml:800-813 implements qualified type lookup by
    // first reading the parent with `find_module_descr`; for persistent modules
    // env.ml:1000-1007 returns `ps_comps`, not `Lazy.force ps.ps_sig`. Read the
    // resolved component table for the declaration, but return the selected
    // lookup prefix: env.ml:1091-1099 builds `Pdot(p, s, pos)` from the module
    // path `p`, even when the component table was produced by scraping an alias.
    with_resolved_module_components_for_path_with_cache_mode(
        parent_module_path,
        env,
        pers_env,
        ctx,
        cache_mode,
        |components| {
            components.lookup_type(type_name).map(|(id, decl)| {
                let result = (*parent_module_path, *id, decl.clone());
                ctx.register_resolved_module_type(
                    env.scope_id(),
                    parent_module_path,
                    type_name,
                    result.0,
                    result.1,
                    result.2.clone(),
                );
                result
            })
        },
    )
    .flatten()
}

fn rewrite_alias_pident_child_prefixes(
    sig: &mut [crate::types::decl::SignatureItem],
    target: &Path,
    access_path: &Path,
    ctx: &crate::types::context::TypeContext,
) {
    let child_ids = sig
        .iter()
        .filter_map(|item| match item {
            crate::types::decl::SignatureItem::SigModule(id, _, _) => Some(*id),
            _ => None,
        })
        .collect::<Vec<_>>();
    let access_path = Arc::new(*access_path);
    for child_id in child_ids {
        let old_prefix = Path::pdot(*target, child_id.name());
        let new_prefix =
            ctx.dotted_from_ident(access_path.clone(), child_id, crate::types::path::NOPOS);
        let rewrite_target = std::sync::Arc::new(new_prefix);
        crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
            sig,
            &old_prefix,
            &rewrite_target,
            ctx,
        );
        crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
            sig,
            &old_prefix,
            &rewrite_target,
            ctx,
        );
    }
}

/// Rewrite a `Pdot` module-alias target prefix to the selected access path.
fn rewrite_alias_pdot_target(
    sig: &mut crate::types::decl::Signature,
    target: &Path,
    access_path: &Path,
    pers_env: &Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) {
    let rewrite_target = std::sync::Arc::new(*access_path);
    crate::cmi::persistent_env::rewrite_sig_by_path_prefix(sig, target, &rewrite_target, ctx);
    // OCaml compiler/ml/env.ml:1567-1579 keeps child module
    // declarations/components as separate lazy thunks. For an alias such as
    // `module J = Js.Json`, compiler/ml/mtype.ml:98-102 strengthens `Kind` to
    // the scraped target `Js.Json.Kind`, while compiler/ml/env.ml:1530 and
    // compiler/ml/subst.ml:87-95 expose the selected component path as
    // `J.Kind`. Do not rewrite the child module declaration alias itself here.
    crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix_shallow(
        sig,
        target,
        &rewrite_target,
        ctx,
    );
    // OCaml compiler/ml/env.ml:1517 scrapes the alias target and
    // compiler/ml/env.ml:1530-1538 then prefixes the selected component path.
    // If the scraped target came from a flattened runtime unit such as
    // `Js_json`, rewrite that backing unit as well as the source alias path
    // (`Js.Json`) before child components are forced.
    rewrite_flattened_alias_head_prefixes(sig, target, access_path, pers_env.as_ref(), ctx);
}

fn qualify_resolved_signature_for_access_path_inner(
    access_path: &Path,
    mty: &crate::types::decl::ModuleType,
    resolved_sig: &crate::types::decl::Signature,
    resolved_name: Option<&str>,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    force_generalize_values: bool,
) -> crate::types::decl::Signature {
    let should_rebind_direct_type_family = should_rebind_direct_sig_type_family(mty, access_path);
    let access_path_has_local_root = matches!(path_root_module(access_path).view(), crate::types::path::PathView::Pident(id) if !id.is_persistent() && id.stamp() != 0);
    let access_path_has_persistent_root = matches!(path_root_module(access_path).view(), crate::types::path::PathView::Pident(id) if id.is_persistent());
    if ctx.compiler_counters_enabled() {
        let kind = if let Some(old_name) = resolved_name {
            match access_path.view() {
                PathView::Pident(id) if id.name() == old_name => "resolved_name_exact_pident",
                PathView::Pident(_) => "resolved_name_alias_pident",
                PathView::Pdot(..) => "resolved_name_pdot",
                PathView::Papply(_, _) => "resolved_name_papply",
            }
        } else if matches!(mty, crate::types::decl::ModuleType::MtyAlias(..)) {
            "alias"
        } else if should_rebind_direct_type_family {
            "direct_type_family_rebind"
        } else if access_path_has_persistent_root {
            "persistent_root"
        } else if access_path_has_local_root {
            "local_root"
        } else {
            "other"
        };
        crate::perf_counters::record_signature_qualification(kind, resolved_sig.len());
        crate::perf_counters::record_signature_qualification_name(
            kind,
            access_path.name().as_str(),
            resolved_sig.len(),
        );
    }

    // OCaml compiler/ml/env.ml:1530-1538 always routes component signatures
    // through `prefix_idents` and `Subst.value_description`, even when the
    // current signature contains only values and the substitution is otherwise
    // empty. Do not skip the signature copy based on item shape; the value-type
    // sharing must come from compiler/ml/subst.ml:303-309.
    let mut sig = copy_lookup_signature_for_subst(resolved_sig, ctx);
    let alias_requires_exact_persistent_prefix = matches!(
        (mty, access_path.view()),
        (
            crate::types::decl::ModuleType::MtyAlias(_, target),
            PathView::Pident(id),
        ) if id.is_persistent() && !target.same(access_path)
    );
    let mut alias_module_strengthen_path = None;
    if matches!(mty, crate::types::decl::ModuleType::MtyAlias(..)) {
        let strengthen_path = match mty {
            crate::types::decl::ModuleType::MtyAlias(_, target)
                if !alias_requires_exact_persistent_prefix =>
            {
                // OCaml compiler/ml/env.ml:1435-1444 scrapes an alias by
                // strengthening the resolved module type at the alias target
                // path, and compiler/ml/mtype.ml:32-49 leaves value
                // descriptions unchanged. The later env.ml:1529-1538
                // `prefix_idents` pass only substitutes bound identifiers for
                // the selected component path.
                target
            }
            _ => access_path,
        };
        alias_module_strengthen_path = Some(*strengthen_path);
        sig = strengthen_sig_for_module_access_path(ctx, strengthen_path, &sig);
    }
    // OCaml compiler/ml/subst.ml:69-84 and subst.ml:87-100 rewrite module
    // and type paths structurally; applicative family paths remain under
    // `Pdot(Papply(...), type_name)`. Do not rebind those paths to the selected
    // access path here. compiler/ml/env.ml:1744-1756 must force
    // `components_of_functor_appl` when that manifest is later expanded.
    if should_rebind_direct_type_family {
        rebind_direct_sig_type_family_to_access_path(ctx, access_path, &mut sig);
    }
    if let Some(old_name) = resolved_name {
        let resolved_alias_to_persistent_root = matches!(
            mty.ident_or_alias_path().map(|p| p.view()),
            Some(PathView::Pident(alias_id))
                if alias_id.is_persistent() && alias_id.name() == old_name
        );
        if resolved_alias_to_persistent_root {
            // OCaml compiler/ml/env.ml:1516-1518 scrapes aliases before
            // env.ml:1530-1578 builds component tables. For a persistent-root
            // alias, compiler/ml/mtype.ml:98-102 strengthens child modules into
            // Mty_alias entries at the persistent target, and the current
            // compiler/ml/subst.ml:303-309 value-description substitution only
            // sees this component level. Leave nested module signatures for
            // their own env.ml:1568/1573 lazy component thunks.
            let prefix_target = std::sync::Arc::new(*access_path);
            crate::cmi::persistent_env::rewrite_module_prefix_in_sig_shallow(
                &sig,
                old_name,
                &prefix_target,
                ctx,
            );
            crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig_shallow(
                &mut sig,
                old_name,
                &prefix_target,
                ctx,
            );
        } else {
            let prefix_target = std::sync::Arc::new(*access_path);
            crate::cmi::persistent_env::rewrite_module_prefix_in_sig(
                &sig,
                old_name,
                &prefix_target,
                ctx,
            );
            crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig(
                &mut sig,
                old_name,
                &prefix_target,
                ctx,
            );
        }
    }
    let alias_access_is_persistent_child = matches!(
        (mty, access_path.view()),
        (
            crate::types::decl::ModuleType::MtyAlias(_, _),
            PathView::Pdot(parent, _, _),
        ) if parent.head().is_persistent()
    );
    if let crate::types::decl::ModuleType::MtyAlias(_, target) = mty
        && !target.same(access_path)
        && (!access_path_has_persistent_root || alias_access_is_persistent_child)
    {
        // OCaml compiler/ml/env.ml:1517 scrapes module aliases before
        // compiler/ml/env.ml:1530-1538 prefixes component declarations with the
        // selected access path. Rust persistent signatures are already finalized
        // under their saved unit path, so rewrite that target prefix to the
        // selected alias path before applying the component substitution.
        // This also covers persistent child aliases such as `Web.MediaStream =
        // Web__MediaStream`: env.ml:1008-1013 selects the child component path,
        // then env.ml:1542-1556 exposes value/type descriptions through that
        // selected path rather than the flattened backing unit.
        match target.view() {
            PathView::Pident(alias_id) => {
                // OCaml compiler/ml/env.ml:1517 scrapes the persistent alias
                // target, then env.ml:1530 builds the current component
                // substitution with `prefix_idents`. Apply that substitution
                // only at this signature level; nested child component thunks
                // keep their own env.ml:1568/1573 lazy substitution boundary.
                let prefix_target = std::sync::Arc::new(*access_path);
                crate::cmi::persistent_env::rewrite_module_prefix_in_sig_shallow(
                    &sig,
                    alias_id.name(),
                    &prefix_target,
                    ctx,
                );
                crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig_shallow(
                    &mut sig,
                    alias_id.name(),
                    &prefix_target,
                    ctx,
                );
            }
            PathView::Pdot(..) => {
                rewrite_alias_pdot_target(&mut sig, target, access_path, pers_env, ctx);
            }
            PathView::Papply(_, _) => {}
        }
    }
    if let crate::types::decl::ModuleType::MtyAlias(_, target) = mty
        && alias_requires_exact_persistent_prefix
        && !target.same(access_path)
    {
        match target.view() {
            PathView::Pdot(..) => {
                rewrite_alias_pdot_target(&mut sig, target, access_path, pers_env, ctx);
            }
            PathView::Pident(alias_id) => {
                // OCaml compiler/ml/env.ml:1567-1579 stores child
                // module declarations/components as lazy thunks;
                // compiler/ml/subst.ml:69-95,303-309,350-377
                // rewrites only paths reached through the
                // `prefix_idents` substitution when those thunks
                // are forced. Keep this alias-target root rewrite
                // to the current signature level so nested module
                // value types keep explicit persistent paths until
                // their own component thunk runs.
                let prefix_target = std::sync::Arc::new(*access_path);
                crate::cmi::persistent_env::rewrite_module_prefix_in_sig_shallow(
                    &sig,
                    alias_id.name(),
                    &prefix_target,
                    ctx,
                );
                crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig_shallow(
                    &mut sig,
                    alias_id.name(),
                    &prefix_target,
                    ctx,
                );
                rewrite_alias_pident_child_prefixes(&mut sig, target, access_path, ctx);
            }
            PathView::Papply(_, _) => {}
        }
    }
    if let Some(strengthen_path) = alias_module_strengthen_path.as_ref() {
        strengthen_sig_module_decls_for_module_access_path(&mut sig, strengthen_path, ctx);
    }
    crate::cmi::persistent_env::substitute_type_paths_in_sig(&sig, access_path, ctx);
    crate::cmi::persistent_env::substitute_sig_decl_paths_in_place(&mut sig, access_path, ctx);
    if force_generalize_values {
        crate::types::ctype::force_generalize_signature_values(ctx, &sig);
    }
    sig
}

pub(crate) fn qualify_resolved_signature_for_access_path(
    access_path: &Path,
    mty: &crate::types::decl::ModuleType,
    resolved_sig: &crate::types::decl::Signature,
    resolved_name: Option<&str>,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> crate::types::decl::Signature {
    qualify_resolved_signature_for_access_path_inner(
        access_path,
        mty,
        resolved_sig,
        resolved_name,
        pers_env,
        ctx,
        true,
    )
}

pub(crate) fn qualify_resolved_signature_for_local_components(
    access_path: &Path,
    mty: &crate::types::decl::ModuleType,
    resolved_sig: &crate::types::decl::Signature,
    resolved_name: Option<&str>,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> crate::types::decl::Signature {
    qualify_resolved_signature_for_access_path_inner(
        access_path,
        mty,
        resolved_sig,
        resolved_name,
        pers_env,
        ctx,
        false,
    )
}

pub(crate) fn build_qualified_signature_for_access_path(
    env: &Env,
    access_path: &Path,
    mty: &crate::types::decl::ModuleType,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<crate::types::decl::Signature> {
    let (sig, resolved_name) = env.resolve_module_type(mty, pers_env, ctx, cache_mode)?;
    Some(qualify_resolved_signature_for_access_path(
        access_path,
        mty,
        &sig,
        resolved_name.as_deref(),
        pers_env,
        ctx,
    ))
}

fn lookup_pident_module_for_path<'a>(
    env: &'a Env,
    module_path: &Path,
    id: &Ident,
) -> Option<&'a crate::types::decl::ModuleDeclaration> {
    // OCaml compiler/ml/env.ml:781-788 path lookup uses `IdTbl.find_same`
    // for `Pident` and falls through to the persistent unit when that exact
    // identity is not present. Name lookup belongs to source Longident lookup
    // (`lookup_module_descr_aux`, compiler/ml/env.ml:1000-1007), so a local or
    // opened `Dom` must not shadow the persistent `Dom` carried by a type path.
    if id.is_persistent() {
        env.lookup_module_ident_exact(id).ok()
    } else {
        env.lookup_module(module_path)
            .or_else(|_| env.find_module(id.name_atom()))
            .ok()
    }
}

fn build_module_signature_for_path(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<(Path, crate::types::decl::Signature)> {
    let resolved = match module_path.view() {
        PathView::Pident(id) => {
            if let Some(md) = lookup_pident_module_for_path(env, module_path, id) {
                let access_path = if id.is_persistent() {
                    // OCaml compiler/ml/env.ml:1000-1007 resolves an exact
                    // persistent unit through that unit's `ps_comps` before
                    // any alias recovery. Keep the selected path as the
                    // requested unit (`Belt_Id`) even if an opened declaration
                    // also carries a qualified alias path (`Belt.Id`); the
                    // component substitution at env.ml:1530-1538 then prefixes
                    // values and types with the exact unit.
                    Path::pident(*id)
                } else if env.has_module_ident(id) {
                    Path::pident(*id)
                } else {
                    md.md_path.unwrap_or_else(|| Path::pident(*id))
                };
                let sig = build_qualified_signature_for_access_path(
                    env,
                    &access_path,
                    &md.md_type,
                    pers_env,
                    ctx,
                    cache_mode,
                )?;
                Some((access_path, sig))
            } else if let Some(pers) = pers_env
                .as_mut()
                // env.ml:865-882: only a persistent ident names a unit; a
                // local ident (e.g. the type of an inline record path
                // `variant.Two`) is just not a module.
                .filter(|_| id.is_persistent() || id.stamp() == 0)
            {
                if let Some(ps) = pers.find_pers_struct(id.name(), ctx) {
                    let access_path = Path::pident(Ident::create_persistent(id.name()));
                    let mut sig = copy_lookup_signature_for_subst(&ps.ps_sig, ctx);
                    if let Some(qualified_alias_path) =
                        pers.qualified_alias_path_for_flattened_head(id.name())
                    {
                        // OCaml compiler/ml/env.ml:1000-1007 resolves the
                        // exact persistent unit before alias recovery, then
                        // env.ml:1530-1538 prefixes component value/type
                        // descriptions with that selected path via
                        // compiler/ml/subst.ml:303-309. If the loaded ps_sig
                        // was already observed through the qualified alias
                        // (`Belt.Id`), rewrite the whole prefix back to the
                        // exact unit (`Belt_Id`), not only child-module
                        // prefixes.
                        let rewrite_target = std::sync::Arc::new(access_path);
                        crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                            &sig,
                            &qualified_alias_path,
                            &rewrite_target,
                            ctx,
                        );
                        crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                            &mut sig,
                            &qualified_alias_path,
                            &rewrite_target,
                            ctx,
                        );
                        rewrite_flattened_alias_child_prefixes(
                            &sig,
                            &qualified_alias_path,
                            &access_path,
                            ctx,
                        );
                    }
                    Some((access_path, sig))
                } else {
                    let source_path = Path::pident(*id);
                    let qualified_alias_path = pers
                        .qualified_alias_path_for_flattened_head(id.name())
                        .or_else(|| {
                            ctx.component_paths_for_alias_source(&source_path)
                                .into_iter()
                                .find(|qualified_alias_path| {
                                    !qualified_alias_path.same(module_path)
                                })
                        })
                        .filter(|qualified_alias_path| !qualified_alias_path.same(module_path));
                    if let Some(qualified_alias_path) = qualified_alias_path {
                        // OCaml compiler/ml/env.ml:1000-1007 resolves the
                        // exact persistent path first; env.ml:1529-1538 then
                        // runs `prefix_idents` with that exact path, and
                        // compiler/ml/subst.ml:180-181 rewrites package module
                        // type paths through `modtype_path`. If Rust has only
                        // the already-selected flattened alias component table
                        // available here, reuse its contents but restore the
                        // exact unit prefix (`Belt_Id`, not `Belt.Id`).
                        let access_path = Path::pident(*id);
                        return with_resolved_module_components_for_path(
                            &qualified_alias_path,
                            env,
                            pers_env,
                            ctx,
                            |components| {
                                let mut sig =
                                    copy_lookup_signature_for_subst(components.signature(), ctx);
                                let rewrite_target = std::sync::Arc::new(access_path);
                                crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                                    &sig,
                                    &qualified_alias_path,
                                    &rewrite_target,
                                    ctx,
                                );
                                crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                                    &mut sig,
                                    &qualified_alias_path,
                                    &rewrite_target,
                                    ctx,
                                );
                                rewrite_flattened_alias_child_prefixes(
                                    &sig,
                                    &qualified_alias_path,
                                    &access_path,
                                    ctx,
                                );
                                (access_path, sig)
                            },
                        );
                    }
                    None
                }
            } else {
                let raw_sig = if id.is_persistent() {
                    ctx.with_raw_module_sig(id.name(), |raw_sig| raw_sig.clone())
                        .or_else(|| {
                            ctx.get_or_load_raw_module_sig(id.name())
                                .map(|sig| sig.as_ref().clone())
                        })
                } else {
                    None
                };
                if let Some(raw_sig) = raw_sig {
                    // OCaml compiler/ml/env.ml:669-678 stores persistent
                    // `ps_comps` from the raw `sign` separately from the lazy
                    // `ps_sig = Subst.signature ...`; env.ml:1000-1007 returns
                    // those components for qualified type lookup before
                    // ctype.ml:1367-1372 falls back to env.ml:903-914
                    // `normalize_path`. Recover the component view from the raw
                    // signature cache without forcing the full-signature copy.
                    let access_path = Path::pident(*id);
                    let mut sig = raw_sig;
                    let source_path = Path::pident(*id);
                    if let Some(qualified_alias_path) = ctx
                        .component_paths_for_alias_source(&source_path)
                        .into_iter()
                        .next()
                    {
                        let rewrite_target = std::sync::Arc::new(access_path);
                        crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                            &sig,
                            &qualified_alias_path,
                            &rewrite_target,
                            ctx,
                        );
                        crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                            &mut sig,
                            &qualified_alias_path,
                            &rewrite_target,
                            ctx,
                        );
                        rewrite_flattened_alias_child_prefixes(
                            &sig,
                            &qualified_alias_path,
                            &access_path,
                            ctx,
                        );
                    }
                    return Some((access_path, sig));
                }
                let source_path = Path::pident(*id);
                let qualified_alias_path = ctx
                    .component_paths_for_alias_source(&source_path)
                    .into_iter()
                    .find(|qualified_alias_path| !qualified_alias_path.same(module_path));
                if let Some(qualified_alias_path) = qualified_alias_path {
                    // OCaml compiler/ml/env.ml:1000-1007 resolves the exact
                    // module first; env.ml:1529-1538 then prefixes component
                    // declarations with that exact path, and
                    // compiler/ml/subst.ml:180-181 applies the same prefix to
                    // package module-type paths. The ctype-only path has no
                    // `PersistentEnv`, so recover from Rust's cached alias
                    // components while keeping OCaml's exact persistent prefix.
                    let access_path = Path::pident(*id);
                    return with_resolved_module_components_for_path(
                        &qualified_alias_path,
                        env,
                        pers_env,
                        ctx,
                        |components| {
                            let mut sig =
                                copy_lookup_signature_for_subst(components.signature(), ctx);
                            let rewrite_target = std::sync::Arc::new(access_path);
                            crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                                &sig,
                                &qualified_alias_path,
                                &rewrite_target,
                                ctx,
                            );
                            crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                                &mut sig,
                                &qualified_alias_path,
                                &rewrite_target,
                                ctx,
                            );
                            rewrite_flattened_alias_child_prefixes(
                                &sig,
                                &qualified_alias_path,
                                &access_path,
                                ctx,
                            );
                            (access_path, sig)
                        },
                    );
                }
                None
            }
        }
        PathView::Pdot(parent, submodule_name, _) => {
            let (resolved_parent_path, access_path, md) = lookup_module_in_resolved_path(
                parent,
                submodule_name.as_str(),
                env,
                pers_env,
                ctx,
            )?;
            let (sig, resolved_name) =
                env.resolve_module_type(&md.md_type, pers_env, ctx, cache_mode)?;
            let mut sig = copy_lookup_signature_for_subst(&sig, ctx);
            if matches!(&md.md_type, crate::types::decl::ModuleType::MtyAlias(..)) {
                sig = strengthen_sig_for_module_access_path(ctx, &access_path, &sig);
            }
            let mut should_rebind_direct_type_family =
                should_rebind_direct_sig_type_family(&md.md_type, &access_path);
            if module_type_has_hidden_unpack_ident(&md.md_type) {
                should_rebind_direct_type_family = true;
            }
            if should_rebind_direct_type_family {
                rebind_direct_sig_type_family_to_access_path(ctx, &access_path, &mut sig);
            }
            if let Some(ref old_name) = resolved_name {
                if should_rewrite_nested_alias_self_path(ctx, old_name, &resolved_parent_path) {
                    let prefix_target = std::sync::Arc::new(access_path);
                    crate::cmi::persistent_env::rewrite_module_prefix_in_sig(
                        &sig,
                        old_name,
                        &prefix_target,
                        ctx,
                    );
                    crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig(
                        &mut sig,
                        old_name,
                        &prefix_target,
                        ctx,
                    );
                }
            }
            if let crate::types::decl::ModuleType::MtyAlias(_, ref target) = md.md_type {
                if !target.same(&access_path) {
                    match target.view() {
                        PathView::Pdot(..) => {
                            let rewrite_target = std::sync::Arc::new(access_path);
                            crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                                &sig,
                                target,
                                &rewrite_target,
                                ctx,
                            );
                            crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                                &mut sig,
                                target,
                                &rewrite_target,
                                ctx,
                            );
                            rewrite_flattened_alias_head_prefixes(
                                &mut sig,
                                target,
                                &access_path,
                                pers_env.as_ref(),
                                ctx,
                            );
                        }
                        PathView::Pident(alias_id) => {
                            let prefix_target = std::sync::Arc::new(access_path);
                            crate::cmi::persistent_env::rewrite_module_prefix_in_sig(
                                &sig,
                                alias_id.name(),
                                &prefix_target,
                                ctx,
                            );
                            crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig(
                                &mut sig,
                                alias_id.name(),
                                &prefix_target,
                                ctx,
                            );
                            rewrite_alias_pident_child_prefixes(
                                &mut sig,
                                target,
                                &access_path,
                                ctx,
                            );
                        }
                        PathView::Papply(_, _) => {}
                    }
                }
            }
            crate::cmi::persistent_env::substitute_type_paths_in_sig(&sig, &access_path, ctx);
            crate::cmi::persistent_env::substitute_sig_decl_paths_in_place(
                &mut sig,
                &access_path,
                ctx,
            );
            crate::types::ctype::force_generalize_signature_values(ctx, &sig);
            let flattened_heads = pers_env
                .as_ref()
                .map(|pers| pers.flattened_alias_heads_for_path(&resolved_parent_path))
                .unwrap_or_default();
            if !flattened_heads.is_empty() {
                with_resolved_module_components_for_path(
                    parent,
                    env,
                    pers_env,
                    ctx,
                    |components| {
                        let parent_sig = components.signature();
                        for flat_head in &flattened_heads {
                            let flattened_parent =
                                Path::pident(Ident::create_persistent(flat_head));
                            if !flattened_parent.same(&resolved_parent_path) {
                                rewrite_child_module_prefixes_from_sig(
                                    &sig,
                                    parent_sig,
                                    &resolved_parent_path,
                                    &flattened_parent,
                                    Some(submodule_name.as_str()),
                                    ctx,
                                );
                            }
                        }
                    },
                )?;
            }
            Some((access_path, sig))
        }
        PathView::Papply(_, _) => None,
    };

    if resolved.is_some() {
        return resolved;
    }

    if matches!(module_path.view(), PathView::Papply(_, _)) {
        return None;
    }

    let head = module_path.head();
    if !head.is_persistent() && head.stamp() != 0 {
        return None;
    }

    if ctx.persistent_env_is_in_process() {
        return None;
    }

    let load_paths = ctx.load_paths();
    if load_paths.is_empty() {
        return None;
    }

    let mut visiting = HashSet::new();
    let sig = crate::types::ctype::resolve_module_signature_through_cmi_shared(
        ctx,
        &load_paths,
        module_path,
        &mut visiting,
    )?;
    let sig = std::sync::Arc::unwrap_or_clone(sig);
    crate::types::ctype::force_generalize_signature_values(ctx, &sig);
    Some((*module_path, sig))
}

pub(crate) fn resolve_module_signature_for_path(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, crate::types::decl::Signature)> {
    resolve_module_signature_for_path_shared(module_path, env, pers_env, ctx)
        .map(|(path, sig)| (path, sig.as_ref().clone()))
}

pub(crate) fn resolve_module_signature_for_path_shared(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<(Path, std::sync::Arc<crate::types::decl::Signature>)> {
    with_resolved_module_components_for_path(module_path, env, pers_env, ctx, |components| {
        (*components.access_path(), components.signature_arc())
    })
}

pub(crate) fn alias_target_for_module_path(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<Path> {
    match module_path.view() {
        PathView::Pident(id) => {
            // OCaml compiler/ml/env.ml:865-875 resolves an exact
            // `Path.Pident` module through `IdTbl.find_same`; env.ml:285-290
            // skips opened component tables. Do not let a same-name opened
            // alias answer alias-target scraping for an already-selected path.
            let md = env.find_module_same(id).ok()?;
            match &md.md_type {
                crate::types::decl::ModuleType::MtyAlias(..)
                | crate::types::decl::ModuleType::MtyIdent(_) => {
                    md.md_type.ident_or_alias_path().cloned()
                }
                _ => None,
            }
        }
        PathView::Pdot(parent, module_name, _) => {
            with_resolved_module_components_for_path(parent, env, pers_env, ctx, |components| {
                // OCaml compiler/ml/typecore.ml:776-787 `expand_path` asks
                // compiler/ml/env.ml:800-813 `Env.find_type` before falling
                // back to `Env.normalize_path`. For a dotted type path, that
                // first step descends through env.ml:781-793
                // `find_module_descr` and the component table; it does not
                // force env.ml:1568's `comp_modules` thunk just to inspect a
                // module alias while comparing constructor result paths.
                components.lookup_module_alias_target(module_name.as_str(), true, ctx)
                    .map(|target| *target)
            })?
        }
        PathView::Papply(_, _) => None,
    }
}

pub(crate) fn module_alias_target_for_path(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<Path> {
    match module_path.view() {
        PathView::Pident(id) => {
            // OCaml compiler/ml/env.ml:865-875 resolves an exact
            // `Path.Pident` module through `IdTbl.find_same`; env.ml:285-290
            // skips opened component tables. This keeps persistent runtime roots
            // such as `Dom` from being strengthened through opened aliases before
            // compiler/ml/ctype.ml:1367-1372 normalizes the path.
            let md = env.find_module_same(id).ok()?;
            match &md.md_type {
                crate::types::decl::ModuleType::MtyAlias(_, target) => Some(**target),
                _ => None,
            }
        }
        PathView::Pdot(parent, module_name, _) => {
            with_resolved_module_components_for_path(parent, env, pers_env, ctx, |components| {
                // OCaml compiler/ml/env.ml:781-793 lets
                // `lookup_module_descr` navigate component tables without
                // forcing env.ml:1568's `comp_modules` thunk. This helper is
                // only asking whether the component declaration is an alias so
                // Rust can choose a recovery path; using
                // `lookup_qualified_module` here would force
                // compiler/ml/subst.ml:378-400-style identifier renaming
                // before OCaml's env.ml:865-882 `find_module` path asks for
                // the module declaration itself.
                components.lookup_module_alias_target(module_name.as_str(), false, ctx)
                    .map(|target| *target)
            })?
        }
        PathView::Papply(_, _) => None,
    }
}

fn raw_alias_target_for_module_path(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<Path> {
    match module_path.view() {
        PathView::Pident(_) => alias_target_for_module_path(module_path, env, pers_env, ctx),
        PathView::Pdot(parent, module_name, _) => {
            with_resolved_module_components_for_path(parent, env, pers_env, ctx, |components| {
                // OCaml compiler/ml/env.ml:781-793 lets
                // `find_module_descr` descend through component tables, while
                // env.ml:865-882 only forces `comp_modules` for callers that
                // need the module declaration itself. This raw alias probe is
                // used while mirroring compiler/ml/subst.ml:91-95 prefix
                // rewriting of copied type paths, so inspect the component
                // declaration without running compiler/ml/subst.ml:378-400
                // child-signature identifier freshening.
                components.lookup_module_alias_target(module_name.as_str(), true, ctx)
                    .map(|target| *target)
            })?
        }
        PathView::Papply(_, _) => None,
    }
}

/// Look up a type declaration for a given path.
/// Tries env first, then module components.
pub(crate) fn lookup_type_decl_for_path(
    type_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
) -> Option<Arc<crate::types::decl::TypeDeclaration>> {
    lookup_type_decl_for_path_with_cache_mode(
        type_path,
        env,
        pers_env,
        ctx,
        ComponentLookupApi::FindType,
    )
}

fn lookup_type_decl_for_path_with_cache_mode(
    type_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<Arc<crate::types::decl::TypeDeclaration>> {
    fn lookup_raw_type_decl_from_module_path(
        module_path: &Path,
        type_name: &str,
        env: &Env,
        ctx: &crate::types::context::TypeContext,
        cache_mode: ComponentLookupApi,
    ) -> Option<Arc<crate::types::decl::TypeDeclaration>> {
        // OCaml compiler/ml/env.ml:1095-1105 and 1138-1143 resolve labels
        // through descriptor component tables; env.ml:800-813 does the same
        // for type lookup. Preserve the caller's descriptor/probe mode here
        // instead of falling back to env.ml:865-882 `find_module`, otherwise a
        // self-manifest fallback can force sibling module declarations while it
        // is only checking raw component type presence.
        let mut no_persistent_env = None;
        with_resolved_module_components_for_path_with_cache_mode(
            module_path,
            env,
            &mut no_persistent_env,
            ctx,
            cache_mode,
            |components| {
                components
                    .lookup_type(type_name)
                    .map(|(_, decl)| decl.clone())
            },
        )
        .flatten()
    }

    // Only use env.lookup_type directly for simple identifiers. For qualified
    // paths, env.lookup_type currently resolves by leaf name and can return an
    // unrelated declaration with the same type name.
    if let PathView::Pident(id) = type_path.view() {
        // OCaml compiler/ml/env.ml:800-813 resolves Pident type paths with
        // `IdTbl.find_same`. Keep this exact here too, so a same-name local
        // alias cannot mask the imported identifier whose stamp is being
        // expanded by ctype.ml:1367-1372.
        if let Some(decl) = env.find_type_arc_by_ident(id) {
            return Some(decl.clone());
        }
    }

    // Only use env.lookup_type directly for simple identifiers after the exact
    // lookup. For qualified paths, env.lookup_type currently resolves by leaf
    // name and can return an unrelated declaration with the same type name.
    if let PathView::Pident(id) = type_path.view() {
        if let Some(decl) = env.lookup_type_arc_by_ident(id) {
            return Some(decl.clone());
        }
    }

    // Try path-based lookup for Pdot paths
    if let PathView::Pdot(parent, type_name, _) = type_path.view() {
        let mut deferred_self_manifest_decl: Option<Arc<crate::types::decl::TypeDeclaration>> =
            None;
        // Inline-record constructor paths are type paths whose parent is also a type path:
        // `<type_path>.<Constructor>`. Rebuild the synthetic record declaration from
        // the parent variant declaration so label disambiguation can recover field types.
        // OCaml compiler/ml/env.ml:822-835 only resolves the parent as a type
        // after `Path.constructor_typath` classifies the path as an inline
        // record constructor. Regular module-qualified type paths like
        // `Js.Types.tagged_t` must not recursively look up `Js.Types` as a type
        // before reading the module component table.
        let could_be_inline_record_constructor = type_name
            .chars()
            .next()
            .is_some_and(|first| first.is_ascii_uppercase());
        if could_be_inline_record_constructor
            && let Some(parent_decl) =
                lookup_type_decl_for_path_with_cache_mode(parent, env, pers_env, ctx, cache_mode)
        {
            if let crate::types::TypeKind::TypeVariant(ref constrs, layout) = parent_decl.type_kind
            {
                for (position, cd) in constrs.iter().enumerate() {
                    if cd.cd_id.name() == type_name.as_str() {
                        if let crate::types::ConstructorArguments::CstrRecord(labels) = &cd.cd_args
                        {
                            let inline_params = inline_record_type_params(ctx, labels);
                            return Some(Arc::new(crate::types::TypeDeclaration {
                                type_params: inline_params.clone(),
                                type_arity: inline_params.len() as i32,
                                type_kind: crate::types::TypeKind::TypeRecord(
                                    crate::types::decl::SharedVec::from(labels.clone()),
                                    if parent_decl.type_representation
                                        == crate::types::TypeRepresentation::Unboxed
                                    {
                                        // compiler/ml/datarepr.ml:163-164: unboxed inline records use `Record_unboxed true`.
                                        crate::types::RecordRepresentation::RecordUnboxed(true)
                                    } else {
                                        crate::types::RecordRepresentation::RecordInlined {
                                            name: type_name.to_string(),
                                            representation: crate::types::ConstructorReference {
                                                variant: layout,
                                                position,
                                            },
                                        }
                                    },
                                ),
                                type_private: parent_decl.type_private,
                                type_manifest: None,
                                type_variance: inline_params
                                    .iter()
                                    .map(|_| crate::types::variance::Variance::full())
                                    .collect(),
                                type_newtype_level: None,
                                type_loc: cd.cd_loc,
                                type_attributes: vec![],
                                type_immediate: false,
                                type_representation: crate::types::TypeRepresentation::Boxed,
                                type_shape: crate::types::ValueShape::Unstated,
                                type_inlined_types: vec![],
                                type_path: None,
                            }));
                        }
                    }
                }
            }
        }

        if let Some(Some(decl)) = with_resolved_module_components_for_path_with_cache_mode(
            parent,
            env,
            pers_env,
            ctx,
            cache_mode,
            |components| {
                let (_, decl) = match components.lookup_type(type_name.as_str()) {
                    Some(found) => found,
                    None => return None,
                };
                let decl = decl.clone();
                let self_manifest = decl
                    .type_manifest
                    .and_then(|manifest| {
                        let manifest_desc = ctx.get_desc(ctx.repr(manifest));
                        match &*manifest_desc {
                            TypeDesc::Tconstr { path, .. } => Some(path.same(type_path)),
                            _ => None,
                        }
                    })
                    .unwrap_or(false);

                // Functor-application edge case: substituted signatures can expose
                // `type t = M.t` self-manifests. Fall back to the module's raw
                // signature declaration so manifest aliases (for example `Path.t`)
                // remain visible to variant disambiguation.
                if self_manifest {
                    if let PathView::Pident(parent_id) = parent.view() {
                        if let Some(md) = lookup_pident_module_for_path(env, parent, parent_id) {
                            // Preserve local alias access paths. For bindings like
                            // `module Functions = WasmBindings__Functions`, deferring
                            // here falls through to the alias target's global
                            // declaration and loses the local path family.
                            if !parent_id.is_persistent()
                                && matches!(
                                    md.md_type,
                                    crate::types::decl::ModuleType::MtyAlias(..)
                                        | crate::types::decl::ModuleType::MtyIdent(..)
                                )
                            {
                                return Some(decl);
                            }
                        }
                    }

                    if let Some(raw_decl) = lookup_raw_type_decl_from_module_path(
                        parent,
                        type_name.as_str(),
                        env,
                        ctx,
                        cache_mode,
                    ) {
                        return Some(raw_decl);
                    }

                    if decl
                        .type_path
                        .as_ref()
                        .is_some_and(|stored_path| !stored_path.same(type_path))
                    {
                        return Some(decl);
                    }

                    // Keep the substituted declaration as a last-resort fallback,
                    // but continue with alias/module resolution first so functor and
                    // module-alias paths can expose their concrete manifest.
                    deferred_self_manifest_decl = Some(decl);
                    return None;
                }

                // Cache the resolved decl so subsequent lookups for the same
                // Pdot path reuse the same type nodes (matching OCaml's
                // components_of_module_maker lazy caching).
                Some(decl)
            },
        ) {
            return Some(decl);
        }

        // Resolve the parent module path through local aliases/signatures only
        // after the exact parent path failed. OCaml compiler/ml/env.ml:1000-1007
        // reads `ps_comps` for the requested persistent unit before any alias
        // recovery, so explicit flattened names like `Stdlib_RegExp.t` must not
        // be eagerly rewritten to `Stdlib.RegExp.t`.
        if let PathView::Pident(parent_id) = parent.view()
            && let Some(qualified_parent) = pers_env
                .as_ref()
                .and_then(|pers| pers.qualified_alias_path_for_flattened_head(parent_id.name()))
        {
            let qualified_type_path = Path::pdot(qualified_parent, type_name.as_str());
            if !qualified_type_path.same(type_path)
                && let Some(decl) = lookup_type_decl_for_path_with_cache_mode(
                    &qualified_type_path,
                    env,
                    pers_env,
                    ctx,
                    cache_mode,
                )
            {
                return Some(decl);
            }
        }

        // Try resolving the module alias: Pdot(Pident(Nullable/9), "t")
        // -> look up "Nullable" module in env -> if it's MtyAlias(Stdlib_Nullable)
        // -> resolve "Stdlib_Nullable.t" through its module components
        if let PathView::Pident(parent_id) = parent.view() {
            if let Some(md) = lookup_pident_module_for_path(env, parent, parent_id) {
                use crate::types::decl::ModuleType;
                match &md.md_type {
                    ModuleType::MtyAlias(..) | ModuleType::MtyIdent(_) => {
                        let alias_path = md.md_type.ident_or_alias_path().unwrap();
                        let resolved_path = Path::pdot(*alias_path, type_name.as_str());
                        if let Some(decl) =
                            crate::types::ctype::resolve_type_through_modules(ctx, &resolved_path)
                        {
                            return Some(Arc::new(decl));
                        }
                    }
                    ModuleType::MtySignature(_) => {
                        let module_path = Path::pident(*parent_id);
                        let mut no_persistent_env = None;
                        if let Some(Some(decl)) =
                            with_resolved_module_components_for_path_with_cache_mode(
                                &module_path,
                                env,
                                &mut no_persistent_env,
                                ctx,
                                cache_mode,
                                |components| {
                                    components
                                        .lookup_type(type_name.as_str())
                                        .map(|(_, decl)| decl.clone())
                                },
                            )
                        {
                            return Some(decl);
                        }
                    }
                    _ => {}
                }
            }
        }

        // Prefer the substituted declaration we just resolved from the parent
        // signature over global path caches when we hit a self-manifest type.
        if let Some(decl) = deferred_self_manifest_decl.take() {
            return Some(decl);
        }

        // Try resolving through modules (loading CMI files on demand)
        if let Some(decl) = crate::types::ctype::resolve_type_through_modules(ctx, type_path) {
            return Some(Arc::new(decl));
        }

        if let Some(decl) = deferred_self_manifest_decl {
            return Some(decl);
        }
    }

    None
}

// ============================================================================
// Parmatch bridge (typecore.ml:1741-1776, pattern_printer.ml)
// ============================================================================

/// The type checker side of [`crate::types::parmatch::Oracle`].
struct TypecoreParmatchOracle<'t, 'c> {
    tctx: &'t mut TypeCheckContext<'c>,
    env: &'t Env,
    /// `expected_ty` passed to `partial_pred`.
    expected_ty: TypeExprRef,
    /// `~lev` passed to `partial_pred`.
    level: i32,
    /// `~explode` for `check_partial` (typecore.ml:1763-1767).
    partial_explode: i32,
    none_type: Option<TypeExprRef>,
}

fn parmatch_warning(warning: &crate::types::parmatch::ParmatchWarning) -> Warning {
    use crate::types::parmatch::ParmatchWarning as W;
    match warning {
        W::AllClausesGuarded => Warning::AllClausesGuarded,
        W::PartialMatch(example) => Warning::PartialMatch {
            example: example.clone(),
        },
        W::FragileMatch(typ) => Warning::FragileMatch { typ: typ.clone() },
        W::UnusedMatch(reason) => Warning::UnusedMatch {
            reason: reason.clone(),
        },
        W::UnusedPat(reason) => Warning::UnusedPat {
            reason: reason.clone(),
        },
        W::UnreachableCase => Warning::UnreachableCase,
        W::AmbiguousPattern(vars) => Warning::AmbiguousPattern { vars: vars.clone() },
    }
}

type PersistentEnvSlot = Option<crate::cmi::persistent_env::PersistentEnv>;

/// `get_variant_constructors env ty` (parmatch.ml:490-501).
fn pm_variant_constructors(
    ctx: &TypeContext,
    env: &Env,
    pers: &mut PersistentEnvSlot,
    ty: TypeExprRef,
) -> Vec<crate::types::ConstructorDescription> {
    let mut ty = ctx.repr(ty);
    loop {
        let path = match &*ctx.get_desc(ty) {
            TypeDesc::Tconstr { path, .. } => *path,
            _ => crate::misc::fatal_error("Parmatch.get_variant_constructors"),
        };
        let Some(decl) = lookup_type_decl_for_path(&path, env, pers, ctx) else {
            crate::misc::fatal_error("Parmatch.get_variant_constructors")
        };
        match &decl.type_kind {
            crate::types::TypeKind::TypeVariant(..) => {
                return crate::types::env_lazy::constructors_of_type_path(&path, &decl, ctx);
            }
            _ if decl.type_manifest.is_some() => {
                match crate::types::ctype::expand_head_once(ctx, env, ty) {
                    Some(expanded) => ty = expanded,
                    None => crate::misc::fatal_error("Parmatch.get_variant_constructors"),
                }
            }
            _ => crate::misc::fatal_error("Parmatch.get_variant_constructors"),
        }
    }
}

/// The environment part of `pats_of_type` (parmatch.ml:942-966).
fn pm_type_shape(
    ctx: &TypeContext,
    env: &Env,
    pers: &mut PersistentEnvSlot,
    ty: TypeExprRef,
    always: bool,
) -> crate::types::parmatch::TypeShape {
    use crate::types::parmatch::TypeShape;
    let expanded = ctx.repr(crate::types::ctype::expand_head(ctx, env, ty));
    let path = match &*ctx.get_desc(expanded) {
        TypeDesc::Tconstr { path, .. } => *path,
        TypeDesc::Ttuple(items) => return TypeShape::Tuple(items.len()),
        _ => return TypeShape::Other,
    };
    let Some(decl) = lookup_type_decl_for_path(&path, env, pers, ctx) else {
        return TypeShape::Other;
    };
    match &decl.type_kind {
        crate::types::TypeKind::TypeVariant(cl, _)
            if always || cl.len() == 1 || cl.iter().all(|cd| cd.cd_res.is_some()) =>
        {
            TypeShape::Variant(crate::types::env_lazy::constructors_of_type_path(
                &path, &decl, ctx,
            ))
        }
        // `snd (Env.find_type_descrs path env)` (parmatch.ml:1012-1013).
        crate::types::TypeKind::TypeRecord(..) => TypeShape::Record(
            find_type_label_family(&path, &decl, env, pers, ctx)
                .and_then(|family| ctx.label_family(family))
                .map(|labels| labels.as_ref().clone())
                .unwrap_or_default(),
        ),
        _ => TypeShape::Other,
    }
}

/// Whether typing a wildcard of type `ty` with `~explode` could meet a GADT
/// constructor. `type_pat` (typecore.ml:1166-1186) types
/// `Parmatch.ppat_of_type` in place of the wildcard: the fields of a record
/// or tuple type, the constructors of a variant type that has one
/// constructor or only GADT ones (parmatch.ml:936-960), each again holding
/// wildcards. This walks the types that can reach, without typing anything.
///
/// It over-approximates: every type argument is followed, as it may stand
/// for a parameter of the declaration, and so is a manifest. Declarations
/// found free of GADT constructors are remembered. A walk that gets long
/// answers `true`.
fn wildcard_may_reach_gadt(tctx: &mut TypeCheckContext<'_>, env: &Env, ty: TypeExprRef) -> bool {
    const MAX_TYPES: usize = 2048;
    const MAX_DECLARATIONS: usize = 256;
    let ctx = tctx.type_ctx;
    let root = ctx.repr(ty);
    let root_path = match &*ctx.borrow_desc(root) {
        // `Ctype.none`: the type is not known.
        TypeDesc::Ttuple(items) if items.is_empty() => return true,
        TypeDesc::Tconstr { path, args, .. } if args.is_empty() => Some(*path),
        _ => None,
    };
    let mut todo = vec![root];
    let mut seen_types: HashSet<TypeExprRef> = HashSet::default();
    let mut seen_paths: HashSet<Path> = HashSet::default();
    // The declarations to remember as free of GADT constructors when the
    // walk ends without finding one. None are when the walk met a locally
    // abstract type: that is equal to another type in some match cases only,
    // so what was found holds for this place alone.
    let mut walked: Vec<Path> = Vec::new();
    let mut met_local_type = false;
    let mut found = false;
    while let Some(ty) = todo.pop() {
        let ty = ctx.repr(ty);
        if !seen_types.insert(ty) {
            continue;
        }
        if seen_types.len() > MAX_TYPES || seen_paths.len() > MAX_DECLARATIONS {
            // Too long to be worth it; next time too, for a type without
            // arguments.
            if let Some(path) = root_path {
                tctx.wildcard_reaches_gadt.insert(path, true);
            }
            return true;
        }
        let path = match &*ctx.borrow_desc(ty) {
            TypeDesc::Tconstr { path, .. } => Some(*path),
            _ => None,
        };
        if let Some(path) = path
            && seen_paths.insert(path)
        {
            match tctx.wildcard_reaches_gadt.get(&path) {
                Some(true) => {
                    found = true;
                    break;
                }
                Some(false) => {}
                None => {
                    // No declaration: the wildcard stays (parmatch.ml:957).
                    if let Some(decl) =
                        lookup_type_decl_for_path(&path, env, &mut tctx.persistent_env, ctx)
                    {
                        match &decl.type_kind {
                            crate::types::TypeKind::TypeVariant(cl, _)
                                if cl.iter().any(|cd| cd.cd_res.is_some()) =>
                            {
                                tctx.wildcard_reaches_gadt.insert(path, true);
                                found = true;
                                break;
                            }
                            crate::types::TypeKind::TypeVariant(cl, _) if cl.len() != 1 => {}
                            kind => {
                                crate::types::btype::iter_type_expr_kind(kind, |ty| todo.push(ty))
                            }
                        }
                        todo.extend(decl.type_manifest);
                        met_local_type |= decl.type_newtype_level.is_some();
                        walked.push(path);
                    }
                }
            }
        }
        crate::types::btype::iter_type_expr(ctx, ty, |ty| todo.push(ty));
    }
    if !found && !met_local_type {
        for path in walked {
            tctx.wildcard_reaches_gadt.insert(path, false);
        }
    }
    found
}

fn pm_is_predef_some_lid(arena: &ParseArena, lid: LidentIdx) -> bool {
    match arena.get_longident(lid) {
        Longident::Ldot(prefix, name) => {
            arena.get_string(*name) == "Some"
                && matches!(prefix.as_ref(), Longident::Lident(p) if arena.get_string(*p) == "*predef*")
        }
        _ => false,
    }
}

fn pm_is_block_that_cannot_be_undefined(
    ctx: &TypeContext,
    cstr: &crate::types::ConstructorDescription,
) -> bool {
    use crate::types::variant_runtime::{BlockType, ConstructorCase};
    let crate::types::ConstructorKind::Ordinary(reference) = cstr.cstr_kind else {
        return false;
    };
    match reference.representation(ctx) {
        // Ast_untagged_variants.block_type_can_be_undefined
        // (ast_untagged_variants.ml:89-93).
        ConstructorCase::Block(crate::types::VariantBlock::Untagged { block_type, .. }) => {
            block_type != BlockType::Unknown
        }
        ConstructorCase::Block(crate::types::VariantBlock::Tagged(_)) => false,
        ConstructorCase::Constant(_) => false,
    }
}

fn pm_variant_length(ctx: &TypeContext, cstr: &crate::types::ConstructorDescription) -> usize {
    match cstr.cstr_kind {
        crate::types::ConstructorKind::Ordinary(reference) => {
            ctx.with_variant_layout(reference.variant, |layout| layout.constructors.len())
        }
        crate::types::ConstructorKind::Extension(_) => 0,
    }
}

/// `get_type_path ty tenv` (parmatch.ml:334-338).
/// The `pat_env` of a pattern the checks inspect. Unlike the match env, it
/// holds the GADT equations of constructors matched earlier in the same
/// pattern, and Parmatch reads pattern types in it: `get_type_path p.pat_type
/// p.pat_env` (parmatch.ml:350-354, 906, 1019), `row_of_pat`
/// (parmatch.ml:844-847), `Ctype.expand_head p.pat_env` (parmatch.ml:149).
fn pm_pattern_env(ctx: &TypeContext, env: EnvRef) -> Rc<Env> {
    ctx.get_typed_env(env)
        .expect("Parmatch: pattern env is stored in the type context")
}

fn pm_type_path(ctx: &TypeContext, env: &Env, ty: TypeExprRef) -> Path {
    let ty = ctx.repr(crate::types::ctype::expand_head(ctx, env, ty));
    match &*ctx.get_desc(ty) {
        TypeDesc::Tconstr { path, .. } => *path,
        _ => crate::misc::fatal_error("Parmatch.get_type_path"),
    }
}

/// `row_of_pat` (parmatch.ml:850-853).
fn pm_row_of(ctx: &TypeContext, env: &Env, ty: TypeExprRef) -> crate::types::type_expr::RowDesc {
    let ty = ctx.repr(crate::types::ctype::expand_head(ctx, env, ty));
    match &*ctx.get_desc(ty) {
        TypeDesc::Tvariant(row) => crate::types::btype::row_repr(ctx, &ctx.row_desc(row)),
        _ => crate::misc::fatal_error("Parmatch.row_of_pat"),
    }
}

impl crate::types::parmatch::Oracle for TypecoreParmatchOracle<'_, '_> {
    /// The checks run with the typed arena set aside (see [`PatCase`]), so
    /// `tctx.typed` is scratch space here.
    fn scratch(&self) -> &TypedArena {
        &self.tctx.typed
    }

    fn scratch_mut(&mut self) -> &mut TypedArena {
        &mut self.tctx.typed
    }

    fn ctx(&self) -> &TypeContext {
        self.tctx.type_ctx
    }

    fn expand_head(&mut self, env: EnvRef, ty: TypeExprRef) -> TypeExprRef {
        let ctx = self.tctx.type_ctx;
        let env = pm_pattern_env(ctx, env);
        ctx.repr(crate::types::ctype::expand_head(ctx, &env, ty))
    }

    fn variant_constructors(
        &mut self,
        env: EnvRef,
        ty: TypeExprRef,
    ) -> Vec<crate::types::ConstructorDescription> {
        let env = pm_pattern_env(self.tctx.type_ctx, env);
        pm_variant_constructors(self.tctx.type_ctx, &env, &mut self.tctx.persistent_env, ty)
    }

    fn type_shape(
        &mut self,
        env: EnvRef,
        ty: TypeExprRef,
        always: bool,
    ) -> crate::types::parmatch::TypeShape {
        let env = pm_pattern_env(self.tctx.type_ctx, env);
        pm_type_shape(
            self.tctx.type_ctx,
            &env,
            &mut self.tctx.persistent_env,
            ty,
            always,
        )
    }

    fn create_ident(&mut self, name: &str) -> Ident {
        self.tctx.type_ctx.create_ident(name)
    }

    fn close_variant(&mut self, _env: EnvRef, _pat_env: EnvRef, ty: TypeExprRef) {
        pressure_matrix_close_variant_type(self.tctx, self.env, ty);
    }

    fn warn(&mut self, loc: LocIdx, warning: crate::types::parmatch::ParmatchWarning) {
        self.tctx.report_warning(loc, parmatch_warning(&warning));
    }

    fn is_active(&self, warning: &crate::types::parmatch::ParmatchWarning) -> bool {
        self.tctx
            .warning_config
            .is_active(&parmatch_warning(warning))
    }

    fn is_ghost(&self, loc: LocIdx) -> bool {
        self.tctx.arena.loc_ghost(loc)
    }

    fn print_pattern(&mut self, v: &Pattern) -> String {
        print_counter_example(&self.tctx.typed, self.tctx.arena, v)
    }

    fn pred(
        &mut self,
        kind: crate::types::parmatch::PredKind,
        u: Pattern,
        loc: Option<LocIdx>,
    ) -> Option<Pattern> {
        let (mode, explode) = match kind {
            crate::types::parmatch::PredKind::Partial => {
                (PatternMode::Normal, self.partial_explode)
            }
            crate::types::parmatch::PredKind::Unused => (PatternMode::SplitOr, 5),
        };
        partial_pred(
            self.tctx,
            self.env,
            PatternOptions {
                mode,
                allow_existentials: true,
                level: self.level,
            },
            explode,
            self.expected_ty,
            &u,
            loc,
        )
    }

    fn wildcard_may_reach_gadt(&mut self, ty: Option<TypeExprRef>) -> bool {
        wildcard_may_reach_gadt(self.tctx, self.env, ty.unwrap_or(self.expected_ty))
    }

    fn is_non_extendable_predef_path(&self, path: &Path) -> bool {
        !extendable_fragile_match_path(path)
    }

    fn placeholder_lid(&self) -> LidentIdx {
        self.tctx.arena.push_typecheck_lident("?temp?")
    }

    fn none_type(&mut self) -> TypeExprRef {
        let ctx = self.tctx.type_ctx;
        *self
            .none_type
            .get_or_insert_with(|| ctx.new_type(TypeDesc::Ttuple(Default::default())))
    }

    fn is_pat_from_variant_spread(&self, pat: &Attributes) -> bool {
        pattern_from_variant_spread_attr(self.tctx.arena, pat)
    }

    fn variant_length(&self, cstr: &crate::types::ConstructorDescription) -> usize {
        pm_variant_length(self.tctx.type_ctx, cstr)
    }

    fn type_path(&mut self, env: EnvRef, ty: TypeExprRef) -> Path {
        let pat_env = pm_pattern_env(self.tctx.type_ctx, env);
        pm_type_path(self.tctx.type_ctx, &pat_env, ty)
    }

    fn row_of(&mut self, env: EnvRef, ty: TypeExprRef) -> crate::types::type_expr::RowDesc {
        let env = pm_pattern_env(self.tctx.type_ctx, env);
        pm_row_of(self.tctx.type_ctx, &env, ty)
    }
}

/// A Parmatch oracle for the translation phase, where only the
/// environment queries of `le_pat`/`satisfiable` are needed
/// (translmod.ml:391 `Parmatch.irrefutable`).
struct TranslParmatchOracle<'t> {
    ctx: &'t TypeContext,
    ta: &'t TypedArena,
    arena: &'t ParseArena,
    env: &'t Env,
    persistent_env: &'t mut PersistentEnvSlot,
    none_type: Option<TypeExprRef>,
    /// Counter-examples; `irrefutable` builds none.
    scratch: TypedArena,
}

impl crate::types::parmatch::Oracle for TranslParmatchOracle<'_> {
    fn scratch(&self) -> &TypedArena {
        &self.scratch
    }

    fn scratch_mut(&mut self) -> &mut TypedArena {
        &mut self.scratch
    }

    fn ctx(&self) -> &TypeContext {
        self.ctx
    }

    fn expand_head(&mut self, _env: EnvRef, ty: TypeExprRef) -> TypeExprRef {
        self.ctx
            .repr(crate::types::ctype::expand_head(self.ctx, self.env, ty))
    }

    fn variant_constructors(
        &mut self,
        _env: EnvRef,
        ty: TypeExprRef,
    ) -> Vec<crate::types::ConstructorDescription> {
        pm_variant_constructors(self.ctx, self.env, self.persistent_env, ty)
    }

    fn type_shape(
        &mut self,
        _env: EnvRef,
        ty: TypeExprRef,
        always: bool,
    ) -> crate::types::parmatch::TypeShape {
        pm_type_shape(self.ctx, self.env, self.persistent_env, ty, always)
    }

    fn create_ident(&mut self, name: &str) -> Ident {
        self.ctx.create_ident(name)
    }

    fn close_variant(&mut self, _env: EnvRef, _pat_env: EnvRef, _ty: TypeExprRef) {
        crate::misc::fatal_error("Parmatch.close_variant during translation")
    }

    fn warn(&mut self, _loc: LocIdx, _warning: crate::types::parmatch::ParmatchWarning) {}

    fn is_active(&self, _warning: &crate::types::parmatch::ParmatchWarning) -> bool {
        false
    }

    fn is_ghost(&self, loc: LocIdx) -> bool {
        self.arena.loc_ghost(loc)
    }

    fn print_pattern(&mut self, v: &Pattern) -> String {
        print_counter_example(&self.scratch, self.arena, v)
    }

    fn pred(
        &mut self,
        _kind: crate::types::parmatch::PredKind,
        u: Pattern,
        _loc: Option<LocIdx>,
    ) -> Option<Pattern> {
        Some(u)
    }

    fn wildcard_may_reach_gadt(&mut self, _ty: Option<TypeExprRef>) -> bool {
        true
    }

    fn is_non_extendable_predef_path(&self, path: &Path) -> bool {
        !extendable_fragile_match_path(path)
    }

    fn placeholder_lid(&self) -> LidentIdx {
        self.arena.push_typecheck_lident("?temp?")
    }

    fn none_type(&mut self) -> TypeExprRef {
        let ctx = self.ctx;
        *self
            .none_type
            .get_or_insert_with(|| ctx.new_type(TypeDesc::Ttuple(Default::default())))
    }

    fn is_pat_from_variant_spread(&self, pat: &Attributes) -> bool {
        pattern_from_variant_spread_attr(self.arena, pat)
    }

    fn variant_length(&self, cstr: &crate::types::ConstructorDescription) -> usize {
        pm_variant_length(self.ctx, cstr)
    }

    fn type_path(&mut self, _env: EnvRef, ty: TypeExprRef) -> Path {
        pm_type_path(self.ctx, self.env, ty)
    }

    fn row_of(&mut self, _env: EnvRef, ty: TypeExprRef) -> crate::types::type_expr::RowDesc {
        pm_row_of(self.ctx, self.env, ty)
    }
}

/// `Parmatch.irrefutable pat` (parmatch.ml:2260), as used by translmod.ml:391.
pub(crate) fn parmatch_irrefutable(
    ta: &TypedArena,
    ctx: &TypeContext,
    arena: &ParseArena,
    env: &Env,
    persistent_env: &mut PersistentEnvSlot,
    pat: &Pattern,
) -> bool {
    let lowering = crate::types::dict_pattern::Lowering::new(ctx, ta, &[pat]);
    let mut lowered_arena;
    let (ta, pat) = if lowering.is_identity() {
        (ta, pat)
    } else {
        lowered_arena = ta.clone_pattern_storage();
        let id = lowered_arena.push_pattern(pat.clone());
        let id = lowering.lower(&mut lowered_arena, id);
        (&lowered_arena, lowered_arena.pattern(id))
    };
    let oracle = TranslParmatchOracle {
        ctx,
        ta,
        arena,
        env,
        persistent_env,
        none_type: None,
        scratch: TypedArena::new(),
    };
    let mut pm = crate::types::parmatch::Parmatch::new(oracle, ta);
    pm.irrefutable(pat)
}

/// Patterns that match every value of their type: wildcards, variables,
/// and aliases and tuples of those.
fn pattern_surely_irrefutable(ta: &TypedArena, p: &Pattern) -> bool {
    match &p.pat_desc {
        PatternDesc::Tpat_any | PatternDesc::Tpat_var(..) => true,
        PatternDesc::Tpat_alias(p, _, _) => pattern_surely_irrefutable(ta, ta.pattern(*p)),
        PatternDesc::Tpat_tuple(ps) => ta.patterns(*ps).all(|p| pattern_surely_irrefutable(ta, p)),
        _ => false,
    }
}

fn pattern_contains_or(ta: &TypedArena, p: &Pattern) -> bool {
    match &p.pat_desc {
        PatternDesc::Tpat_any
        | PatternDesc::Tpat_var(..)
        | PatternDesc::Tpat_constant(_)
        | PatternDesc::Tpat_interval(..) => false,
        PatternDesc::Tpat_or(..) => true,
        PatternDesc::Tpat_alias(p, _, _) => pattern_contains_or(ta, ta.pattern(*p)),
        PatternDesc::Tpat_tuple(ps) | PatternDesc::Tpat_array(ps) => {
            ta.patterns(*ps).any(|p| pattern_contains_or(ta, p))
        }
        PatternDesc::Tpat_construct(_, _, ps) => {
            ta.patterns(*ps).any(|p| pattern_contains_or(ta, p))
        }
        PatternDesc::Tpat_variant(_, arg, _) => {
            arg.is_some_and(|arg| pattern_contains_or(ta, ta.pattern(arg)))
        }
        PatternDesc::Tpat_record(fields, _, _) => fields.iter().any(|(_, _, p, _)| pattern_contains_or(ta, ta.pattern(*p))),
        PatternDesc::Tpat_dict(entries) => entries
            .iter()
            .any(|entry| pattern_contains_or(ta, ta.pattern(entry.tdp_pattern))),
    }
}

/// `partial_pred ~lev ?mode ?explode env expected_ty constrs labels p`
/// (typecore.ml:1788-1803) applied to `Conv.conv u` (parmatch.ml:1961-2001).
fn partial_pred(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    options: PatternOptions,
    explode: i32,
    expected_ty: TypeExprRef,
    u: &Pattern,
    loc: Option<LocIdx>,
) -> Option<Pattern> {
    let ctx = tctx.type_ctx;
    let old_constructors = std::mem::take(&mut tctx.generated_pattern_constructors);
    // `type_pat ~constrs ~labels` (typecore.ml:1915): Conv's tables.
    let old_labels = std::mem::take(&mut tctx.generated_pattern_labels);
    let parsed = conv_counter_example(tctx, u, loc);
    // Everything below is backtracked, so the module's unified pairs need not
    // be copied into the snapshots.
    let unified_pairs = tctx.unify_state.take_unified_pairs();
    let diagnostic_len = tctx.diagnostics.len();
    // `let env = ref env` (typecore.ml:1789): GADT equations added while
    // typing the counter-example go to a fresh env, not one left behind by
    // earlier pattern typing.
    let saved_unify_env = tctx
        .unify_state
        .env()
        .cloned();
    tctx.unify_state.set_env(env);
    // Ctype.with_passive_variants (ctype.ml:2061-2072).
    let passive = ctx.set_passive_variants(true);
    let mut or_splits = OrSplits::default();
    let result = loop {
        let type_snapshot = ctx.snapshot_type_state();
        let unify_snapshot = tctx.unify_state.snapshot_backtrack_state();
        let mut state = PatternState::for_counter_example(or_splits);
        let result = type_pattern_with_existentials_at_level(
            tctx,
            env,
            tctx.arena.get_pat(parsed),
            expected_ty,
            options,
            &mut state,
            explode,
        );
        ctx.restore_type_state(type_snapshot);
        tctx.unify_state.restore_backtrack_state(unify_snapshot);
        tctx.diagnostics.truncate(diagnostic_len);
        or_splits = state.or_splits;
        if result.is_ok() || !or_splits.backtrack() {
            break result;
        }
    };
    ctx.set_passive_variants(passive);
    match saved_unify_env {
        Some(saved) => tctx.unify_state.set_env(&saved),
        None => {
            tctx.unify_state.take_env();
        }
    }
    tctx.unify_state.put_back_unified_pairs(unified_pairs);
    tctx.generated_pattern_constructors = old_constructors;
    tctx.generated_pattern_labels = old_labels;
    result.ok()
}

fn untype_constant(constant: &Constant, arena: &ParseArena) -> ParsedConstant {
    // Untypeast.constant (untypeast.ml:19-27).
    match constant {
        Constant::Int(value) => {
            ParsedConstant::Integer(arena.push_typecheck_string(value.to_string()), None)
        }
        Constant::Char(value) => arena.typecheck_char_constant(*value),
        Constant::String(value) => arena.typecheck_string_constant(value),
        Constant::Float(value) => {
            ParsedConstant::Float(arena.push_typecheck_string(value.clone()), None)
        }
        Constant::BigInt(positive, digits) => {
            let value = if *positive {
                digits.clone()
            } else {
                format!("-{digits}")
            };
            ParsedConstant::Integer(arena.push_typecheck_string(value), Some('n'))
        }
    }
}

fn push_parsed_pattern(
    arena: &ParseArena,
    loc: LocIdx,
    desc: crate::parser::ast::PatternDesc,
) -> crate::parse_arena::PatIdx {
    arena.push_typecheck_pattern(ParsedPattern {
        ppat_desc: desc,
        ppat_loc: loc,
        ppat_attributes: Attributes::new(),
    })
}

/// `Conv.conv` (parmatch.ml:1961-2001): the counter-example as a parsetree
/// pattern whose constructors and labels are the fresh `#$name<n>` entries of
/// `generated_pattern_constructors`/`generated_pattern_labels`.
fn conv_counter_example(
    tctx: &mut TypeCheckContext<'_>,
    typed: &Pattern,
    top_loc: Option<LocIdx>,
) -> crate::parse_arena::PatIdx {
    use crate::parser::ast::{PatternDesc as P, PatternRecordField};

    /// The state of one conversion. Borrows the typed arena and the generated
    /// tables separately, so walking the counter-example copies no pattern.
    struct Conv<'a> {
        ctx: &'a TypeContext,
        typed: &'a TypedArena,
        arena: &'a ParseArena,
        constructors: &'a mut Vec<(crate::name::Name, Arc<crate::types::ConstructorDescription>)>,
        labels: &'a mut Vec<(crate::name::Name, Arc<crate::types::LabelDescription>)>,
        counter: u32,
    }

    impl Conv<'_> {
        /// `Conv.fresh` (parmatch.ml:1943-1946): `#$<name><counter>`, as a
        /// name for the generated table and as an identifier in the arena.
        fn fresh(&mut self, name: &str) -> (crate::name::Name, LidentIdx) {
            let current = self.counter;
            self.counter += 1;
            let text = format!("#${name}{current}");
            let id = crate::name::Name::new(&text);
            (id, self.arena.push_typecheck_lident(text))
        }

        fn list(&mut self, items: &[crate::types::tast_arena::TPatIdx]) -> Vec<crate::parse_arena::PatIdx> {
            let typed = self.typed;
            items
                .iter()
                .map(|item| self.lp(typed.pattern(*item), LocIdx::none()))
                .collect()
        }

        fn lp(&mut self, pat: &Pattern, loc: LocIdx) -> crate::parse_arena::PatIdx {
            let arena = self.arena;
            let typed = self.typed;
            let none = LocIdx::none();
            match &pat.pat_desc {
                PatternDesc::Tpat_or(left, right, _) => {
                    let left = self.lp(typed.pattern(*left), none);
                    let right = self.lp(typed.pattern(*right), none);
                    push_parsed_pattern(arena, loc, P::Ppat_or(left, right))
                }
                PatternDesc::Tpat_var(_, name) if name.txt == "*extension*" => {
                    let txt = arena.push_typecheck_string(name.txt.clone());
                    push_parsed_pattern(arena, loc, P::Ppat_var(Located::new(txt, name.loc)))
                }
                PatternDesc::Tpat_any | PatternDesc::Tpat_var(_, _) => {
                    push_parsed_pattern(arena, loc, P::Ppat_any)
                }
                PatternDesc::Tpat_constant(constant) => push_parsed_pattern(
                    arena,
                    loc,
                    P::Ppat_constant(untype_constant(constant, arena)),
                ),
            PatternDesc::Tpat_interval(c1, c2) => push_parsed_pattern(
                arena,
                loc,
                P::Ppat_interval(Box::new((
                    untype_constant(&c1.constant(), arena),
                    untype_constant(&c2.constant(), arena),
                ))),
            ),
                PatternDesc::Tpat_alias(inner, _, _) => self.lp(typed.pattern(*inner), loc),
                PatternDesc::Tpat_tuple(items) => {
                    let items = self.list(typed.pattern_list(*items));
                    push_parsed_pattern(
                        arena,
                        loc,
                        P::Ppat_tuple(arena.push_shared_pat_list(&items)),
                    )
                }
                PatternDesc::Tpat_construct(cstr_lid, cstr, args) => {
                    let (id, lid) = self.fresh(&cstr.cstr_name);
                    self.constructors.push((id, cstr.clone()));
                    let lid = Located::new(lid, cstr_lid.loc);
                    // parmatch.ml Conv: `Location.mknoloc (List.map loop lst)`.
                    let items = self.list(typed.pattern_list(*args));
                    push_parsed_pattern(
                        arena,
                        loc,
                        P::Ppat_construct(lid, arena.shared_pat_ctor_args(&items, none)),
                    )
                }
                PatternDesc::Tpat_variant(label, arg, _) => {
                    let args: Vec<_> = arg
                        .map(|arg| self.lp(typed.pattern(arg), none))
                        .into_iter()
                        .collect();
                    push_parsed_pattern(
                        arena,
                        loc,
                        P::Ppat_variant(Box::new((
                            label.clone().into(),
                            arena.shared_pat_ctor_args(&args, none),
                        ))),
                    )
                }
            // A lowered dict pattern: its labels are the keys, in order of
            // appearance in the match.
            PatternDesc::Tpat_record(fields, _, _) if typed_pattern_is_dict(self.ctx, pat) => {
                let mut fields: Vec<_> = fields.iter().collect();
                fields.sort_by_key(|(_, lbl, _, _)| lbl.lbl_pos);
                let entries = fields
                    .into_iter()
                    .map(
                        |(_, lbl, p, optional)| crate::parser::ast::DictPatternEntry {
                            pdp_key: Located::new(
                                arena.push_typecheck_string(lbl.lbl_name.to_string()),
                                none,
                            ),
                            pdp_pattern: self.lp(typed.pattern(*p), none),
                            pdp_optional: *optional,
                        },
                    )
                    .collect();
                push_parsed_pattern(arena, loc, P::Ppat_dict(Box::new(entries)))
            }
            PatternDesc::Tpat_dict(entries) => {
                let entries = entries
                    .iter()
                    .map(|entry| crate::parser::ast::DictPatternEntry {
                        pdp_key: Located::new(
                            arena.push_typecheck_string(entry.tdp_key.txt.clone()),
                            entry.tdp_key.loc,
                        ),
                        pdp_pattern: self.lp(typed.pattern(entry.tdp_pattern), none),
                        pdp_optional: entry.tdp_optional,
                    })
                    .collect();
                push_parsed_pattern(arena, loc, P::Ppat_dict(Box::new(entries)))
            }
                PatternDesc::Tpat_record(fields, _, _) => {
                    let fields = fields
                        .iter()
                        .map(|(_, lbl, p, optional)| {
                            let (id, lid) = self.fresh(&lbl.lbl_name);
                            self.labels.push((id, lbl.clone()));
                            PatternRecordField {
                                lid: Located::new(lid, none),
                                pat: self.lp(typed.pattern(*p), none),
                                opt: *optional,
                            }
                        })
                        .collect::<Vec<_>>();
                    // TODO: Conv.conv_record_rest (parmatch.ml:1948-1959) keeps the
                    // rest binding with a `Typ.constr` annotation.
                    push_parsed_pattern(
                        arena,
                        loc,
                        P::Ppat_record(Box::new((
                            arena.push_shared_pat_field_list(&fields),
                            crate::parser::ast::ClosedFlag::Open,
                            None,
                        ))),
                    )
                }
                PatternDesc::Tpat_array(items) => {
                    let items = self.list(typed.pattern_list(*items));
                    push_parsed_pattern(
                        arena,
                        loc,
                        P::Ppat_array(arena.push_shared_pat_list(&items)),
                    )
                }
            }
        }
    }

    // `Conv.name_counter` is global and never reset (parmatch.ml:1942).
    let mut conv = Conv {
        ctx: tctx.type_ctx,
        typed: &tctx.typed,
        arena: tctx.arena,
        constructors: &mut tctx.generated_pattern_constructors,
        labels: &mut tctx.generated_pattern_labels,
        counter: tctx.conv_name_counter,
    };
    let result = conv.lp(typed, top_loc.unwrap_or(LocIdx::none()));
    tctx.conv_name_counter = conv.counter;
    result
}

/// `Pattern_printer.print_pattern` (compiler/common/pattern_printer.ml).
fn print_counter_example(ta: &TypedArena, arena: &ParseArena, typed: &Pattern) -> String {
    use crate::parser::ast::{PatternDesc as P, PatternRecordField};

    fn is_generated_optional_constructor(arena: &ParseArena, lid: LidentIdx) -> bool {
        match arena.get_longident(lid) {
            Longident::Lident(name) => arena.get_string(*name).starts_with("#$"),
            _ => false,
        }
    }

    enum FieldState {
        Normal,
        Missing,
        PresentNone,
    }

    fn classify(ta: &TypedArena, arena: &ParseArena, pat: &Pattern) -> FieldState {
        match &pat.pat_desc {
            PatternDesc::Tpat_construct(lid, cstr, args)
                if args.is_empty()
                    && is_generated_optional_constructor(arena, lid.txt)
                    && cstr.cstr_name == "None" =>
            {
                FieldState::Missing
            }
            PatternDesc::Tpat_construct(lid, cstr, args)
                if args.len() == 1
                    && is_generated_optional_constructor(arena, lid.txt)
                    && cstr.cstr_name == "Some" =>
            {
                match classify(ta, arena, ta.pattern(ta.pattern_list(*args)[0])) {
                    FieldState::Missing | FieldState::PresentNone => FieldState::PresentNone,
                    FieldState::Normal => FieldState::Normal,
                }
            }
            _ => FieldState::Normal,
        }
    }

    fn strip_synthetic_some<'p>(
        ta: &'p TypedArena,
        arena: &ParseArena,
        pat: &'p Pattern,
    ) -> &'p Pattern {
        match &pat.pat_desc {
            PatternDesc::Tpat_construct(lid, cstr, args)
                if args.len() == 1
                    && is_generated_optional_constructor(arena, lid.txt)
                    && cstr.cstr_name == "Some" =>
            {
                ta.pattern(ta.pattern_list(*args)[0])
            }
            _ => pat,
        }
    }

    /// The left operand of an or-pattern being printed: a stored pattern,
    /// or an or-pattern regrouped by [`untype_or`].
    enum OrOperand {
        Pat(TPatIdx),
        Or(Box<(OrOperand, TPatIdx)>),
    }

    /// `left | right`, printing `A | (B | C)` as `(A | B) | C`.
    fn untype_or(
        ta: &TypedArena,
        arena: &ParseArena,
        left: OrOperand,
        right: TPatIdx,
    ) -> crate::parse_arena::PatIdx {
        if let PatternDesc::Tpat_or(p2, p3, _) = &ta.pattern(right).pat_desc {
            return untype_or(ta, arena, OrOperand::Or(Box::new((left, *p2))), *p3);
        }
        let left = match left {
            OrOperand::Pat(p) => untype(ta, arena, ta.pattern(p)),
            OrOperand::Or(pair) => {
                let (l, r) = *pair;
                untype_or(ta, arena, l, r)
            }
        };
        let right = untype(ta, arena, ta.pattern(right));
        push_parsed_pattern(arena, LocIdx::none(), P::Ppat_or(left, right))
    }

    fn untype(ta: &TypedArena, arena: &ParseArena, pat: &Pattern) -> crate::parse_arena::PatIdx {
        let none = LocIdx::none();
        match &pat.pat_desc {
            PatternDesc::Tpat_or(p1, inner, _) => untype_or(ta, arena, OrOperand::Pat(*p1), *inner),
            PatternDesc::Tpat_any | PatternDesc::Tpat_var(_, _) => {
                push_parsed_pattern(arena, none, P::Ppat_any)
            }
            PatternDesc::Tpat_constant(constant) => push_parsed_pattern(
                arena,
                none,
                P::Ppat_constant(untype_constant(constant, arena)),
            ),
            PatternDesc::Tpat_interval(c1, c2) => push_parsed_pattern(
                arena,
                none,
                P::Ppat_interval(Box::new((
                    untype_constant(&c1.constant(), arena),
                    untype_constant(&c2.constant(), arena),
                ))),
            ),
            PatternDesc::Tpat_alias(inner, _, _) => untype(ta, arena, ta.pattern(*inner)),
            PatternDesc::Tpat_tuple(items) => {
                let items = ta
                    .patterns(*items)
                    .map(|item| untype(ta, arena, item))
                    .collect::<Vec<_>>();
                push_parsed_pattern(
                    arena,
                    none,
                    P::Ppat_tuple(arena.push_shared_pat_list(&items)),
                )
            }
            PatternDesc::Tpat_construct(cstr_lid, cstr, args) => {
                let lid = Located::new(arena.push_typecheck_lident(&cstr.cstr_name), cstr_lid.loc);
                // pattern_printer.ml untype: `mknoloc (List.map loop lst)`.
                let items: Vec<_> = ta
                    .patterns(*args)
                    .map(|arg| untype(ta, arena, arg))
                    .collect::<Vec<_>>();
                push_parsed_pattern(
                    arena,
                    none,
                    P::Ppat_construct(lid, arena.shared_pat_ctor_args(&items, none)),
                )
            }
            PatternDesc::Tpat_variant(label, arg, _) => {
                let args: Vec<_> = arg
                    .map(|arg| untype(ta, arena, ta.pattern(arg)))
                    .into_iter()
                    .collect();
                push_parsed_pattern(
                    arena,
                    none,
                    P::Ppat_variant(Box::new((
                        label.clone().into(),
                        arena.shared_pat_ctor_args(&args, none),
                    ))),
                )
            }
            PatternDesc::Tpat_record(subpatterns, closed_flag, rest) => {
                let mut saw_optional_rewrite = false;
                let fields = subpatterns
                    .iter()
                    .map(|(_, lbl, p, opt)| {
                        let state = if lbl.lbl_optional {
                            classify(ta, arena, ta.pattern(*p))
                        } else {
                            FieldState::Normal
                        };
                        let (opt, pat) = match state {
                            FieldState::Missing => {
                                saw_optional_rewrite = true;
                                let none_lid =
                                    Located::new(arena.push_typecheck_lident("None"), none);
                                (
                                    true,
                                    push_parsed_pattern(
                                        arena,
                                        none,
                                        P::Ppat_construct(
                                            none_lid,
                                            crate::parse_arena::Located::new(
                                                crate::parse_arena::PatList::EMPTY,
                                                none,
                                            ),
                                        ),
                                    ),
                                )
                            }
                            FieldState::PresentNone => {
                                saw_optional_rewrite = true;
                                (
                                    *opt,
                                    untype(
                                        ta,
                                        arena,
                                        strip_synthetic_some(ta, arena, ta.pattern(*p)),
                                    ),
                                )
                            }
                            FieldState::Normal => (*opt, untype(ta, arena, ta.pattern(*p))),
                        };
                        PatternRecordField {
                            lid: Located::new(arena.push_typecheck_lident(lbl.lbl_name.as_str()), none),
                            pat,
                            opt,
                        }
                    })
                    .collect::<Vec<_>>();
                let closed_flag = if saw_optional_rewrite {
                    crate::parser::ast::ClosedFlag::Closed
                } else {
                    *closed_flag
                };
                let rest = rest.as_ref().map(|rest| crate::parser::ast::RecordPatRest {
                    rest_loc: rest.rest_name.loc,
                    rest_name: Located::new(
                        arena.push_typecheck_string(rest.rest_name.txt.clone()),
                        rest.rest_name.loc,
                    ),
                    rest_type: None,
                });
                push_parsed_pattern(
                    arena,
                    none,
                    P::Ppat_record(Box::new((
                        arena.push_shared_pat_field_list(&fields),
                        closed_flag,
                        rest,
                    ))),
                )
            }
            PatternDesc::Tpat_array(items) => {
                let items = ta
                    .patterns(*items)
                    .map(|item| untype(ta, arena, item))
                    .collect::<Vec<_>>();
                push_parsed_pattern(
                    arena,
                    none,
                    P::Ppat_array(arena.push_shared_pat_list(&items)),
                )
            }
            // An entry's pattern matches the key's value as an option.
            PatternDesc::Tpat_dict(entries) => {
                let entries = entries
                    .iter()
                    .filter_map(|entry| {
                        let (pattern, optional) = match &ta.pattern(entry.tdp_pattern).pat_desc {
                            PatternDesc::Tpat_any => return None,
                            PatternDesc::Tpat_construct(_, cstr, args)
                                if cstr.cstr_name == "Some" && args.len() == 1 =>
                            {
                                (ta.pattern(ta.pattern_list(*args)[0]), false)
                            }
                            _ => (ta.pattern(entry.tdp_pattern), true),
                        };
                        Some(crate::parser::ast::DictPatternEntry {
                            pdp_key: Located::new(
                                arena.push_typecheck_string(entry.tdp_key.txt.clone()),
                                entry.tdp_key.loc,
                            ),
                            pdp_pattern: untype(ta, arena, pattern),
                            pdp_optional: optional,
                        })
                    })
                    .collect();
                push_parsed_pattern(arena, none, P::Ppat_dict(Box::new(entries)))
            }
        }
    }

    let parsed = untype(ta, arena, typed);
    let doc = crate::parser::printer::print_pattern(
        &crate::parser::printer::PrinterState::init(),
        arena.get_pat(parsed),
        &mut crate::parser::comment_table::CommentTable::new(),
        arena,
    );
    doc.to_string(80)
}

/// A match case for the Parmatch checks.
#[derive(Clone)]
struct ParmatchCase {
    lhs: TPatIdx,
    guarded: bool,
    /// `all_rhs_idents` of the guard.
    guard_idents: Option<std::collections::BTreeSet<Ident>>,
}

/// `check_partial ~lev ?partial_match_warning_hint env expected_ty loc cases`
/// (typecore.ml:1761-1770).
#[allow(clippy::too_many_arguments)]
fn parmatch_check_partial(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    level: i32,
    hint: Option<&str>,
    expected_ty: TypeExprRef,
    loc: LocIdx,
    cases: &[PatCase],
) -> crate::types::typedtree::Partial {
    // An unguarded irrefutable case makes `exhaust` answer `Rnone` without
    // consulting the oracle, so the match is total and nothing is reported;
    // only the fragile-match check still needs the full analysis.
    if cases.iter().any(|case| {
        !case.guarded && pattern_surely_irrefutable(&tctx.typed, tctx.typed.pattern(case.lhs))
    }) && !tctx
        .warning_config
        .is_active(&Warning::FragileMatch { typ: String::new() })
    {
        return crate::types::typedtree::Partial::Total;
    }
    // `check_partial_gadt` lowers the dict patterns of the cases.
    let mut ta = std::mem::take(&mut tctx.typed);
    let lowered = lower_case_dict_patterns(tctx.type_ctx, &mut ta, cases);
    let refs = lowered_case_refs(&ta, &lowered);
    let oracle = TypecoreParmatchOracle {
        tctx: &mut *tctx,
        env,
        expected_ty,
        level,
        partial_explode: if cases.len() == 1 { 5 } else { 0 },
        none_type: None,
    };
    let mut pm = crate::types::parmatch::Parmatch::new(oracle, &ta);
    let partial = match pm.check_partial(hint, loc, &refs) {
        crate::types::parmatch::Partiality::Partial => crate::types::typedtree::Partial::Partial,
        crate::types::parmatch::Partiality::Total => crate::types::typedtree::Partial::Total,
    };
    drop(pm);
    tctx.typed = ta;
    partial
}

/// A match case's pattern side, for the exhaustiveness checks.
///
/// The checks retype counter-examples through the type checker while they
/// read the case patterns, so they set the typed arena aside for their
/// duration: the case patterns are read from it, and whatever the
/// counter-example typing stores goes to an empty scratch arena that is
/// dropped afterwards, like the type state it backtracks
/// (typecore.ml:1741-1760).
#[derive(Clone, Copy)]
struct PatCase {
    lhs: TPatIdx,
    guarded: bool,
}

/// `Parmatch.lower_cases`: the patterns of `cases` with their dict patterns
/// lowered to records, see `Dict_pattern`.
fn lower_case_dict_patterns(ctx: &TypeContext, ta: &mut TypedArena, cases: &[PatCase]) -> Vec<PatCase> {
    let pats: Vec<_> = cases.iter().map(|case| ta.pattern(case.lhs)).collect();
    let lowering = crate::types::dict_pattern::Lowering::new(ctx, ta, &pats);
    cases.iter().map(|case| PatCase {
        lhs: lowering.lower(ta, case.lhs),
        guarded: case.guarded,
    }).collect()
}

fn lowered_case_refs<'p>(ta: &'p TypedArena, cases: &[PatCase]) -> Vec<crate::types::parmatch::CaseRef<'p>> {
    cases.iter().map(|case| crate::types::parmatch::CaseRef {
        lhs: ta.pattern(case.lhs),
        guarded: case.guarded,
    }).collect()
}

fn case_refs(cases: &[crate::types::typedtree::Case]) -> Vec<PatCase> {
    cases.iter().map(|case| PatCase {
        lhs: case.c_lhs,
        guarded: case.c_guard.is_some(),
    }).collect()
}

/// `check_unused ~lev env expected_ty cases` (typecore.ml:1772-1776).
fn parmatch_check_unused(
    tctx: &mut TypeCheckContext<'_>,
    ta: &mut TypedArena,
    env: &Env,
    level: i32,
    expected_ty: TypeExprRef,
    cases: &[PatCase],
) {
    // `check_unused` lowers the dict patterns of the cases.
    let lowered = lower_case_dict_patterns(tctx.type_ctx, ta, cases);
    let cases = &lowered_case_refs(ta, &lowered);
    let oracle = TypecoreParmatchOracle {
        tctx,
        env,
        expected_ty,
        level,
        partial_explode: 0,
        none_type: None,
    };
    let mut pm = crate::types::parmatch::Parmatch::new(oracle, ta);
    pm.check_unused(cases);
}

